(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("polybius-2-e", [{"sp": "HDR", "t": "Ἱστορίαι (Γʹ–Δʹ)"}, {"sp": "HDR", "t": "Βιβλίον Γʹ", "st": "3"}, {"sp": "N", "t": "ὅτι μὲν ἀρχὰς ὑποτιθέμεθα τῆς αὑτῶν πραγματείας τόν τε συμμαχικὸν καὶ τὸν Ἀννιβιακόν, πρὸς δὲ τούτοις τὸν περὶ Κοίλης Συρίας πόλεμον, ἐν τῇ πρώτῃ μὲν τῆς ὅλης συντάξεως, τρίτῃ δὲ ταύτης ἀνώτερον βύβλῳ δεδηλώκαμεν· ὁμοίως δὲ καὶ τὰς αἰτίας, δι’ ἃς ἀναδραμόντες τοῖς χρόνοις πρὸ τούτων τῶν καιρῶν συνεταξάμεθα τὰς πρὸ ταύτης βύβλους, ἐν αὐτῇ ’κείνῃ διεσαφήσαμεν. νῦν δὲ πειρασόμεθα τοὺς προειρημένους πολέμους καὶ τὰς αἰτίας, ἐξ ὧν ἐγένοντο καὶ δι’ ἃς ἐπὶ τοσοῦτον ηὐξήθησαν, μετ’ ἀποδείξεως ἐξαγγέλλειν, βραχέα προειπόντες ὑπὲρ τῆς αὑτῶν πραγματείας. ὄντος γὰρ ἑνὸς ἔργου καὶ θεάματος ἑνὸς τοῦ σύμπαντος, ὑπὲρ οὗ γράφειν ἐπικεχειρήκαμεν, τοῦ πῶς καὶ πότε καὶ διὰ τί πάντα τὰ γνωριζόμενα μέρη τῆς οἰκουμένης ὑπὸ τὴν Ῥωμαίων δυναστείαν ἐγένετο, τούτου δ’ ἔχοντος καὶ τὴν ἀρχὴν γνωριζομένην καὶ τὸν χρόνον ὡρισμένον καὶ τὴν συντέλειαν ὁμολογουμένην, χρήσιμον ἡγούμεθ’ εἶναι καὶ τὸ περὶ τῶν μεγίστων ἐν αὐτῷ μερῶν, ὅσα μεταξὺ κεῖται τῆς ἀρχῆς καὶ τοῦ τέλους, κεφαλαιωδῶς ἐπιμνησθῆναι καὶ προεκθέσθαι. μάλιστα γὰρ οὕτως ὑπολαμβάνομεν τοῖς φιλομαθοῦσι παρασκευάσειν ἱκανὴν ἔννοιαν τῆς ὅλης ἐπιβολῆς. πολλὰ μὲν γὰρ προλαμβανούσης τῆς ψυχῆς ἐκ τῶν ὅλων πρὸς τὴν κατὰ μέρος τῶν πραγμάτων γνῶσιν, πολλὰ δ’ ἐκ τῶν κατὰ μέρος πρὸς τὴν τῶν ὅλων ἐπιστήμην, ἀρίστην ἡγούμενοι τὴν ἐξ ἀμφοῖν ἐπίστασιν καὶ θέαν ἀκόλουθον τοῖς εἰρημένοις ποιησόμεθα τὴν προέκθεσιν τῆς αὑτῶν πραγματείας. τὴν μὲν οὖν καθόλου τῆς ὑποθέσεως ἔμφασιν καὶ τὴν περιγραφὴν ἤδη δεδηλώκαμεν. τῶν δὲ κατὰ μέρος ἐν αὐτῇ γεγονότων ἀρχὰς μὲν εἶναι συμβαίνει τοὺς προειρημένους πολέμους, καταστροφὴν δὲ καὶ συντέλειαν τὴν κατάλυσιν τῆς ἐν Μακεδονίᾳ βασιλείας, χρόνον δὲ τὸν μεταξὺ τῆς ἀρχῆς καὶ τοῦ τέλους ἔτη πεντήκοντα τρία, περιέχεσθαι δ’ ἐν τούτῳ τηλικαύτας καὶ τοιαύτας πράξεις, ὅσας οὐδεὶς τῶν προγεγονότων καιρῶν ἐν ἴσῳ περιέλαβε διαστήματι. περὶ ὧν ἀπὸ τῆς ἑκατοστῆς καὶ τετταρακοστῆς ὀλυμπιάδος ἀρξάμενοι τοιάνδε τινὰ ποιησόμεθα τὴν ἔφοδον τῆς ἐξηγήσεως.", "st": "3.1"}, {"sp": "N", "t": "ὑποδείξαντες γὰρ τὰς αἰτίας, δι’ ἃς ὁ προδεδηλωμένος συνέστη Καρχηδονίοις καὶ Ῥωμαίοις πόλεμος, ὁ προσαγορευθεὶς Ἀννιβιακός, ἐροῦμεν ὡς εἰς Ἰταλίαν ἐμβαλόντες Καρχηδόνιοι καὶ καταλύσαντες τὴν Ῥωμαίων δυναστείαν εἰς μέγαν μὲν φόβον ἐκείνους ἤγαγον περὶ σφῶν καὶ τοῦ τῆς πατρίδος ἐδάφους, μεγάλας δ’ ἔσχον αὐτοὶ καὶ παραδόξους ἐλπίδας, ὡς καὶ τῆς Ῥώμης αὐτῆς ἐξ ἐφόδου κρατήσοντες. ἑξῆς δὲ τούτοις πειρασόμεθα διασαφεῖν ὡς κατὰ τοὺς αὐτοὺς καιροὺς Φίλιππος μὲν ὁ Μακεδὼν διαπολεμήσας Αἰτωλοῖς καὶ μετὰ ταῦτα συστησάμενος τὰ κατὰ τοὺς Ἕλληνας ἐπεβάλετο κοινωνεῖν Καρχηδονίοις τῶν αὐτῶν ἐλπίδων, Ἀντίοχος δὲ καὶ Πτολεμαῖος ὁ Φιλοπάτωρ ἠμφισβήτουν, τέλος δ’ ἐπολέμησαν ὑπὲρ Κοίλης Συρίας πρὸς ἀλλήλους, Ῥόδιοι δὲ καὶ Προυσίας ἀναλαβόντες πρὸς Βυζαντίους πόλεμον ἠνάγκασαν αὐτοὺς ἀποστῆναι τοῦ παραγωγιάζειν τοὺς πλέοντας εἰς τὸν Πόντον. στήσαντες δ’ ἐπὶ τούτων τὴν διήγησιν τὸν ὑπὲρ τῆς Ῥωμαίων πολιτείας συστησόμεθα λόγον, ᾧ κατὰ τὸ συνεχὲς ὑποδείξομεν ὅτι μέγιστα συνεβάλετ’ αὐτοῖς ἡ τοῦ πολιτεύματος ἰδιότης πρὸς τὸ μὴ μόνον ἀνακτήσασθαι τὴν Ἰταλιωτῶν καὶ Σικελιωτῶν δυναστείαν, ἔτι δὲ τὴν Ἰβήρων προσλαβεῖν καὶ Κελτῶν ἀρχήν, ἀλλὰ τὸ τελευταῖον καὶ πρὸς τὸ κρατήσαντας τῷ πολέμῳ Καρχηδονίων ἔννοιαν σχεῖν τῆς τῶν ὅλων ἐπιβολῆς. ἅμα δὲ τούτοις κατὰ παρέκβασιν δηλώσομεν τὴν κατάλυσιν τῆς Ἱέρωνος τοῦ Συρακοσίου δυναστείας. οἷς ἐπισυνάψομεν τὰς περὶ τὴν Αἴγυπτον ταραχὰς καὶ τίνα τρόπον Πτολεμαίου τοῦ βασιλέως μεταλλάξαντος τὸν βίον συμφρονήσαντες Ἀντίοχος καὶ Φίλιππος ἐπὶ διαιρέσει τῆς τοῦ καταλελειμμένου παιδὸς ἀρχῆς ἤρξαντο κακοπραγμονεῖν καὶ τὰς χεῖρας ἐπιβάλλειν Φίλιππος μὲν τοῖς κατ’ Αἴγαιον καὶ Καρίαν καὶ Σάμον, Ἀντίοχος δὲ τοῖς κατὰ Κοίλην Συρίαν καὶ Φοινίκην.", "st": "3.2"}, {"sp": "N", "t": "μετὰ δὲ ταῦτα συγκεφαλαιωσάμενοι τὰς ἐν Ἰβηρίᾳ καὶ Λιβύῃ καὶ Σικελίᾳ πράξεις Ῥωμαίων καὶ Καρχηδονίων μεταβιβάσομεν τὴν διήγησιν ὁλοσχερῶς εἰς τοὺς κατὰ τὴν Ἑλλάδα τόπους ἅμα ταῖς τῶν πραγμάτων μεταβολαῖς. ἐξηγησάμενοι δὲ τὰς Ἀττάλου καὶ Ῥοδίων ναυμαχίας πρὸς Φίλιππον, ἔτι δὲ τὸν Ῥωμαίων καὶ Φιλίππου πόλεμον, ὡς ἐπράχθη καὶ διὰ τίνων καὶ τί τὸ τέλος ἔσχεν, τούτῳ συνάπτοντες τὸ συνεχὲς μνησθησόμεθα τῆς Αἰτωλῶν ὀργῆς, καθ’ ἣν Ἀντίοχον ἐπισπασάμενοι τὸν ἀπὸ τῆς Ἀσίας Ἀχαιοῖς καὶ Ῥωμαίοις ἐξέκαυσαν πόλεμον. οὗ δηλώσαντες τὰς αἰτίας καὶ τὴν Ἀντιόχου διάβασιν εἰς τὴν Εὐρώπην διασαφήσομεν πρῶτον μὲν τίνα τρόπον ἐκ τῆς Ἑλλάδος ἔφυγεν, δεύτερον δὲ πῶς ἡττηθεὶς τῆς ἐπὶ τάδε τοῦ Ταύρου πάσης ἐξεχώρησε, τὸ δὲ τρίτον τίνα τρόπον Ῥωμαῖοι καταλύσαντες τὴν Γαλατῶν ὕβριν ἀδήριτον μὲν σφίσι παρεσκεύασαν τὴν τῆς Ἀσίας ἀρχήν, ἀπέλυσαν δὲ τοὺς ἐπὶ τάδε τοῦ Ταύρου κατοικοῦντας βαρβαρικῶν φόβων καὶ τῆς Γαλατῶν παρανομίας. μετὰ δὲ ταῦτα θέντες ὑπὸ τὴν ὄψιν τὰς Αἰτωλῶν καὶ Κεφαλλήνων ἀτυχίας ἐπιβαλοῦμεν τοὺς Εὐμένει συστάντας πρός τε Προυσίαν καὶ Γαλάτας πολέμους, ὁμοίως δὲ καὶ τὸν μετ’ Ἀριαράθου πρὸς Φαρνάκην. οἷς ἑξῆς ἐπιμνησθέντες τῆς παρὰ Πελοποννησίων ὁμονοίας καὶ καταστάσεως, ἔτι δὲ τῆς αὐξήσεως τοῦ Ῥοδίων πολιτεύματος, συγκεφαλαιωσόμεθα τὴν ὅλην διήγησιν ἅμα καὶ τὰς πράξεις, ἐπὶ πᾶσιν ἐξηγησάμενοι τὴν Ἀντιόχου στρατείαν εἰς Αἴγυπτον τοῦ κληθέντος Ἐπιφανοῦς καὶ τὸν Περσικὸν πόλεμον καὶ τὴν κατάλυσιν τῆς ἐν Μακεδονίᾳ βασιλείας. δι’ ὧν ἅμα θεωρηθήσεται πῶς ἕκαστα χειρίσαντες Ῥωμαῖοι πᾶσαν ἐποιήσαντο τὴν οἰκουμένην ὑπήκοον αὑτοῖς.", "st": "3.3"}, {"sp": "N", "t": "εἰ μὲν οὖν ἐξ αὐτῶν τῶν κατορθωμάτων ἢ καὶ τῶν ἐλαττωμάτων ἱκανὴν ἐνεδέχετο ποιήσασθαι τὴν διάληψιν ὑπὲρ τῶν ψεκτῶν ἢ τοὐναντίον ἐπαινετῶν ἀνδρῶν καὶ πολιτευμάτων, ἐνθάδε που λήγειν ἂν ἡμᾶς ἔδει καὶ καταστρέφειν ἅμα τὴν διήγησιν καὶ τὴν πραγματείαν ἐπὶ τὰς τελευταίας ῥηθείσας πράξεις κατὰ τὴν ἐξ ἀρχῆς πρόθεσιν. ὅ τε γὰρ χρόνος ὁ πεντηκοντακαιτριετὴς εἰς ταῦτ’ ἔληγεν, ἥ τ’ αὔξησις καὶ προκοπὴ τῆς Ῥωμαίων δυναστείας ἐτετελείωτο· πρὸς δὲ τούτοις ὁμολογούμενον ἐδόκει τοῦτ’ εἶναι καὶ κατηναγκασμένον ἅπασιν ὅτι λοιπόν ἐστι Ῥωμαίων ἀκούειν καὶ τούτοις πειθαρχεῖν ὑπὲρ τῶν παραγγελλομένων. ἐπεὶ δ’ οὐκ αὐτοτελεῖς εἰσιν οὔτε περὶ τῶν κρατησάντων οὔτε περὶ τῶν ἐλαττωθέντων αἱ ψιλῶς ἐξ αὐτῶν τῶν ἀγωνισμάτων διαλήψεις, διὰ τὸ πολλοῖς μὲν τὰ μέγιστα δοκοῦντ’ εἶναι τῶν κατορθωμάτων, ὅταν μὴ δεόντως αὐτοῖς χρήσωνται, τὰς μεγίστας ἐπενηνοχέναι συμφοράς, οὐκ ὀλίγοις δὲ τὰς ἐκπληκτικωτάτας περιπετείας, ὅταν εὐγενῶς αὐτὰς ἀναδέξωνται, πολλάκις εἰς τὴν τοῦ συμφέροντος περιπεπτωκέναι μερίδα, προσθετέον ἂν εἴη ταῖς προειρημέναις πράξεσι τήν τε τῶν κρατούντων αἵρεσιν, ποία τις ἦν μετὰ ταῦτα καὶ πῶς προεστάτει τῶν ὅλων, τάς τε τῶν ἄλλων ἀποδοχὰς καὶ διαλήψεις, πόσαι καὶ τίνες ὑπῆρχον περὶ τῶν ἡγουμένων, πρὸς δὲ τούτοις τὰς ὁρμὰς καὶ τοὺς ζήλους ἐξηγητέον, τίνες παρ’ ἑκάστοις ἐπεκράτουν καὶ κατίσχυον περί τε τοὺς κατ’ ἰδίαν βίους καὶ τὰς κοινὰς πολιτείας. δῆλον γὰρ ὡς ἐκ τούτων φανερὸν ἔσται τοῖς μὲν νῦν οὖσιν πότερα φευκτὴν ἢ τοὐναντίον αἱρετὴν εἶναι συμβαίνει τὴν Ῥωμαίων δυναστείαν, τοῖς δ’ ἐπιγενομένοις πότερον ἐπαινετὴν καὶ ζηλωτὴν ἢ ψεκτὴν γεγονέναι νομιστέον τὴν ἀρχὴν αὐτῶν. τὸ γὰρ ὠφέλιμον τῆς ἡμετέρας ἱστορίας πρός τε τὸ παρὸν καὶ πρὸς τὸ μέλλον ἐν τούτῳ πλεῖστον κείσεται τῷ μέρει. οὐ γὰρ δὴ τοῦτ’ εἶναι τέλος ὑποληπτέον ἐν πράγμασιν οὔτε τοῖς ἡγουμένοις οὔτε τοῖς ἀποφαινομένοις ὑπὲρ τούτων, τὸ νικῆσαι καὶ ποιήσασθαι πάντας ὑφ’ ἑαυτούς. οὔτε γὰρ πολεμεῖ τοῖς πέλας οὐδεὶς νοῦν ἔχων ἕνεκεν αὐτοῦ τοῦ καταγωνίσασθαι τοὺς ἀντιταττομένους, οὔτε πλεῖ τὰ πελάγη χάριν τοῦ περαιωθῆναι μόνον, καὶ μὴν οὐδὲ τὰς ἐμπειρίας καὶ τέχνας αὐτῆς ἕνεκα τῆς ἐπιστήμης ἀναλαμβάνει· πάντες δὲ πράττουσι πάντα χάριν τῶν ἐπιγινομένων τοῖς ἔργοις ἡδέων ἢ καλῶν ἢ συμφερόντων. διὸ καὶ τῆς πραγματείας ταύτης τοῦτ’ ἔσται τελεσιούργημα, τὸ γνῶναι τὴν κατάστασιν παρ’ ἑκάστοις, ποία τις ἦν μετὰ τὸ καταγωνισθῆναι τὰ ὅλα καὶ πεσεῖν εἰς τὴν τῶν Ῥωμαίων ἐξουσίαν ἕως τῆς μετὰ ταῦτα πάλιν ἐπιγενομένης ταραχῆς καὶ κινήσεως. ὑπὲρ ἧς διὰ τὸ μέγεθος τῶν ἐν αὐτῇ πράξεων καὶ τὸ παράδοξον τῶν συμβαινόντων, τὸ δὲ μέγιστον, διὰ τὸ τῶν πλείστων μὴ μόνον αὐτόπτης, ἀλλ’ ὧν μὲν συνεργὸς ὧν δὲ καὶ χειριστὴς γεγονέναι, προήχθην οἷον ἀρχὴν ποιησάμενος ἄλλην γράφειν.", "st": "3.4"}, {"sp": "N", "t": "ἦν δ’ ἡ προειρημένη κίνησις, ἐν ᾗ Ῥωμαῖοι μὲν πρὸς Κελτίβηρας καὶ Οὐακκαίους ἐξήνεγκαν πόλεμον, Καρχηδόνιοι δὲ τὸν πρὸς Μασαννάσαν βασιλέα τῶν Λιβύων· περὶ δὲ τὴν Ἀσίαν Ἄτταλος μὲν καὶ Προυσίας πρὸς ἀλλήλους ἐπολέμησαν, ὁ δὲ τῶν Καππαδοκῶν βασιλεὺς Ἀριαράθης ἐκπεσὼν ἐκ τῆς ἀρχῆς ὑπ’ Ὀροφέρνους διὰ Δημητρίου τοῦ βασιλέως αὖθις ἀνεκτήσατο δι’ Ἀττάλου τὴν πατρῴαν ἀρχήν. ὁ δὲ Σελεύκου Δημήτριος κύριος γενόμενος ἔτη δώδεκα τῆς ἐν Συρίᾳ βασιλείας ἅμα τοῦ βίου καὶ τῆς ἀρχῆς ἐστερήθη, συστραφέντων ἐπ’ αὐτὸν τῶν ἄλλων βασιλέων. ἀποκατέστησαν δὲ καὶ Ῥωμαῖοι τοὺς Ἕλληνας εἰς τὴν οἰκείαν τοὺς ἐκ τοῦ Περσικοῦ πολέμου καταιτιαθέντας, ἀπολύσαντες τῆς ἐπενεχθείσης αὐτοῖς διαβολῆς. οἱ δ’ αὐτοὶ μετ’ οὐ πολὺ Καρχηδονίοις ἐπέβαλον τὰς χεῖρας, τὸ μὲν πρῶτον μεταναστῆσαι, μετὰ δὲ ταῦτα πάλιν ἄρδην αὐτοὺς ἐξαναστῆσαι προθέμενοι διὰ τὰς ἐν τοῖς ἑξῆς ῥηθησομένας αἰτίας. οἷς κατάλληλα Μακεδόνων μὲν ἀπὸ τῆς Ῥωμαίων φιλίας, Λακεδαιμονίων δὲ τῆς τῶν Ἀχαιῶν συμπολιτείας ἀποστάντων, ἅμα τὴν ἀρχὴν καὶ τὸ τέλος ἔσχε τὸ κοινὸν ἀτύχημα πάσης τῆς Ἑλλάδος. τὰ μὲν οὖν τῆς ἐπιβολῆς ἡμῶν τοιαῦτα· προσδεῖ δ’ ἔτι τῆς τύχης, ἵνα συνδράμῃ τὰ τοῦ βίου πρὸς τὸ τὴν πρόθεσιν ἐπὶ τέλος ἀγαγεῖν. πέπεισμαι μὲν γάρ, κἄν τι συμβῇ περὶ ἡμᾶς ἀνθρώπινον, οὐκ ἀργήσειν τὴν ὑπόθεσιν οὐδ’ ἀπορήσειν ἀνδρῶν ἀξιόχρεων, διὰ δὲ τὸ κάλλος πολλοὺς κατεγγυηθήσεσθαι καὶ σπουδάσειν ἐπὶ τέλος ἀγαγεῖν αὐτήν. ἐπεὶ δὲ τὰς ἐπιφανεστάτας τῶν πράξεων ἐπὶ κεφαλαίου διεληλύθαμεν, βουλόμενοι καὶ καθόλου καὶ κατὰ μέρος εἰς ἔννοιαν ἀγαγεῖν τῆς ὅλης ἱστορίας τοὺς ἐντυγχάνοντας, ὥρα μνημονεύοντας τῆς προθέσεως ἐπαναγαγεῖν ἐπὶ τὴν ἀρχὴν τῆς αὑτῶν ὑποθέσεως.", "st": "3.5"}, {"sp": "N", "t": "ἔνιοι δὲ τῶν συγγεγραφότων τὰς κατ’ Ἀννίβαν πράξεις βουλόμενοι τὰς αἰτίας ἡμῖν ὑποδεικνύναι, δι’ ἃς Ῥωμαίοις καὶ Καρχηδονίοις ὁ προειρημένος ἐνέστη πόλεμος, πρώτην μὲν ἀποφαίνουσι τὴν Ζακάνθης πολιορκίαν ὑπὸ Καρχηδονίων, δευτέραν δὲ τὴν διάβασιν αὐτῶν παρὰ τὰς συνθήκας τοῦ προσαγορευομένου παρὰ τοῖς ἐγχωρίοις Ἴβηρος ποταμοῦ· ἐγὼ δὲ ταύτας ἀρχὰς μὲν εἶναι τοῦ πολέμου φήσαιμ’ ἄν, αἰτίας γε μὴν οὐδαμῶς ἂν συγχωρήσαιμι. πολλοῦ γε δεῖν, εἰ μὴ καὶ τὴν Ἀλεξάνδρου διάβασιν εἰς τὴν Ἀσίαν αἰτίαν εἶναί τις φήσει τοῦ πρὸς τοὺς Πέρσας πολέμου καὶ τὸν Ἀντιόχου κατάπλουν εἰς Δημητριάδα τοῦ πρὸς Ῥωμαίους· ὧν οὔτ’ εἰκὸς οὔτ’ ἀληθές ἐστιν οὐδέτερον. τίς γὰρ ἂν νομίσειε ταύτας αἰτίας ὑπάρχειν, ὧν πολλὰ μὲν Ἀλέξανδρος πρότερον, οὐκ ὀλίγα δὲ Φίλιππος ἔτι ζῶν ἐνήργησε καὶ παρεσκευάσατο πρὸς τὸν κατὰ τῶν Περσῶν πόλεμον, ὁμοίως δὲ πάλιν Αἰτωλοὶ πρὸ τῆς Ἀντιόχου παρουσίας πρὸς τὸν κατὰ Ῥωμαίων; ἀλλ’ ἔστιν ἀνθρώπων τὰ τοιαῦτα μὴ διειληφότων ἀρχὴ τί διαφέρει καὶ πόσον διέστηκεν αἰτίας καὶ προφάσεως, καὶ διότι τὰ μέν ἐστι πρῶτα τῶν ἁπάντων, ἡ δ’ ἀρχὴ τελευταῖον τῶν εἰρημένων. ἐγὼ δὲ παντὸς ἀρχὰς μὲν εἶναί φημι τὰς πρώτας ἐπιβολὰς καὶ πράξεις τῶν ἤδη κεκριμένων, αἰτίας δὲ τὰς προκαθηγουμένας τῶν κρίσεων καὶ διαλήψεων· λέγω δ’ ἐπινοίας καὶ διαθέσεις καὶ τοὺς περὶ ταῦτα συλλογισμοὺς καὶ δι’ ὧν· ἐπὶ τὸ κρῖναί τι καὶ προθέσθαι παραγινόμεθα. δῆλον δ’ οἷον τὸ προειρημένον ἐκ τῶν ἐπιφερομένων. τίνες γὰρ ἀληθῶς ἦσαν αἰτίαι, καὶ πόθεν φῦναι συνέβη τὸν πρὸς τοὺς Πέρσας πόλεμον, εὐμαρὲς καὶ τῷ τυχόντι συνιδεῖν. ἦν δὲ πρώτη μὲν ἡ τῶν μετὰ Ξενοφῶντος Ἑλλήνων ἐκ τῶν ἄνω σατραπειῶν ἐπάνοδος, ἐν ᾗ πᾶσαν τὴν Ἀσίαν διαπορευομένων αὐτῶν πολεμίαν ὑπάρχουσαν οὐδεὶς ἐτόλμα μένειν κατὰ πρόσωπον τῶν βαρβάρων· δευτέρα δ’ ἡ τοῦ Λακεδαιμονίων βασιλέως Ἀγησιλάου διάβασις εἰς τὴν Ἀσίαν, ἐν ᾗ ’κεῖνος οὐδὲν ἀξιόχρεων οὐδ’ ἀντίπαλον εὑρὼν ταῖς σφετέραις ἐπιβολαῖς ἄπρακτος ἠναγκάσθη μεταξὺ διὰ τὰς περὶ τὴν Ἑλλάδα ταραχὰς ἐπανελθεῖν. ἐξ ὧν Φίλιππος κατανοήσας καὶ συλλογισάμενος τὴν Περσῶν ἀνανδρίαν καὶ ῥᾳθυμίαν καὶ τὴν αὑτοῦ καὶ Μακεδόνων εὐεξίαν ἐν τοῖς πολεμικοῖς, ἔτι δὲ καὶ τὸ μέγεθος καὶ τὸ κάλλος τῶν ἐσομένων ἄθλων ἐκ τοῦ πολέμου πρὸ ὀφθαλμῶν θέμενος, ἅμα τῷ περιποιήσασθαι τὴν ἐκ τῶν Ἑλλήνων εὔνοιαν ὁμολογουμένην, εὐθέως προφάσει χρώμενος ὅτι σπεύδει μετελθεῖν τὴν Περσῶν παρανομίαν εἰς τοὺς Ἕλληνας, ὁρμὴν ἔσχε καὶ προέθετο πολεμεῖν καὶ πάντα πρὸς τοῦτο τὸ μέρος ἡτοίμαζε. διόπερ αἰτίας μὲν τὰς πρώτας ῥηθείσας ἡγητέον τοῦ πρὸς τοὺς Πέρσας πολέμου, πρόφασιν δὲ τὴν δευτέραν, ἀρχὴν δὲ τὴν Ἀλεξάνδρου διάβασιν εἰς τὴν Ἀσίαν.", "st": "3.6"}, {"sp": "N", "t": "καὶ μὴν τοῦ κατ’ Ἀντίοχον καὶ Ῥωμαίους δῆλον ὡς αἰτίαν μὲν τὴν Αἰτωλῶν ὀργὴν θετέον. ἐκεῖνοι γὰρ δόξαντες ὑπὸ Ῥωμαίων ὠλιγωρῆσθαι κατὰ πολλὰ περὶ τὴν ἔκβασιν τὴν ἐκ τοῦ Φιλίππου πολέμου, καθάπερ ἐπάνω προεῖπον, οὐ μόνον Ἀντίοχον ἐπεσπάσαντο, πᾶν δὲ καὶ πρᾶξαι καὶ παθεῖν ὑπέστησαν διὰ τὴν ἐπιγενομένην ὀργὴν ἐκ τῶν προειρημένων καιρῶν. πρόφασιν δ’ ἡγητέον τὴν τῶν Ἑλλήνων ἐλευθέρωσιν, ἣν ἐκεῖνοι περιπορευόμενοι μετ’ Ἀντιόχου τὰς πόλεις ἀλόγως καὶ ψευδῶς κατήγγελλον, ἀρχὴν δὲ τοῦ πολέμου τὸν Ἀντιόχου κατάπλουν εἰς Δημητριάδα. ἐγὼ δὲ τὴν ἐπὶ πλεῖον διαστολὴν πεποίημαι περὶ τούτων οὐχ ἕνεκα τῆς τῶν συγγραφέων ἐπιτιμήσεως, χάριν δὲ τῆς τῶν φιλομαθούντων ἐπανορθώσεως. τί γὰρ ὄφελος ἰατροῦ κάμνουσιν ἀγνοοῦντος τὰς αἰτίας τῶν περὶ τὰ σώματα διαθέσεων; τί δ’ ἀνδρὸς πραγματικοῦ μὴ δυναμένου συλλογίζεσθαι πῶς καὶ διὰ τί καὶ πόθεν ἕκαστα τῶν πραγμάτων τὰς ἀφορμὰς εἴληφεν; οὔτε γὰρ ἐκεῖνον εἰκὸς οὐδέποτε δεόντως συστήσασθαι τὰς τῶν σωμάτων θεραπείας, οὔτε τὸν πραγματικὸν οὐδὲν οἷόν τε κατὰ τρόπον χειρίσαι τῶν προσπιπτόντων ἄνευ τῆς τῶν προειρημένων ἐπιγνώσεως. διόπερ οὐδὲν οὕτω φυλακτέον καὶ ζητητέον ὡς τὰς αἰτίας ἑκάστου τῶν συμβαινόντων, ἐπειδὴ φύεται μὲν ἐκ τῶν τυχόντων πολλάκις τὰ μέγιστα τῶν πραγμάτων, ἰᾶσθαι δὲ ῥᾷστόν ἐστιν παντὸς τὰς πρώτας ἐπιβολὰς καὶ διαλήψεις.", "st": "3.7"}, {"sp": "N", "t": "Φάβιος δέ φησιν ὁ Ῥωμαϊκὸς συγγραφεὺς ἅμα τῷ κατὰ Ζακανθαίους ἀδικήματι καὶ τὴν Ἀσδρούβου πλεονεξίαν καὶ φιλαρχίαν αἰτίαν γίνεσθαι τοῦ κατ’ Ἀννίβαν πολέμου. ἐκεῖνον γὰρ μεγάλην ἀνειληφότα τὴν δυναστείαν ἐν τοῖς κατ’ Ἰβηρίαν τόποις, μετὰ ταῦτα παραγενόμενον ἐπὶ Λιβύην ἐπιβαλέσθαι καταλύσαντα τοὺς νόμους εἰς μοναρχίαν περιστῆσαι τὸ πολίτευμα τῶν Καρχηδονίων· τοὺς δὲ πρώτους ἄνδρας ἐπὶ τοῦ πολιτεύματος προϊδομένους αὐτοῦ τὴν ἐπιβολὴν συμφρονῆσαι καὶ διαστῆναι πρὸς αὐτόν· τὸν δ’ Ἀσδρούβαν ὑπιδόμενον, ἀναχωρήσαντ’ ἐκ τῆς Λιβύης τὸ λοιπὸν ἤδη τὰ κατὰ τὴν Ἰβηρίαν χειρίζειν κατὰ τὴν αὑτοῦ προαίρεσιν, οὐ προσέχοντα τῷ συνεδρίῳ τῶν Καρχηδονίων. Ἀννίβαν δὲ κοινωνὸν καὶ ζηλωτὴν ἐκ μειρακίου γεγονότα τῆς ἐκείνου προαιρέσεως καὶ τότε διαδεξάμενον τὰ κατὰ τὴν Ἰβηρίαν τὴν αὐτὴν ἀγωγὴν Ἀσδρούβᾳ ποιεῖσθαι τῶν πραγμάτων. διὸ καὶ νῦν τὸν πόλεμον τοῦτον ἐξενηνοχέναι κατὰ τὴν αὑτοῦ προαίρεσιν Ῥωμαίοις παρὰ τὴν Καρχηδονίων γνώμην. οὐδένα γὰρ εὐδοκεῖν τῶν ἀξιολόγων ἀνδρῶν ἐν Καρχηδόνι τοῖς ὑπ’ Ἀννίβου περὶ τὴν Ζακανθαίων πόλιν πραχθεῖσιν. ταῦτα δ’ εἰπών φησιν μετὰ τὴν τῆς προειρημένης πόλεως ἅλωσιν παραγενέσθαι τοὺς Ῥωμαίους, οἰομένους δεῖν ἢ τὸν Ἀννίβαν ἐκδιδόναι σφίσι τοὺς Καρχηδονίους ἢ τὸν πόλεμον ἀναλαμβάνειν. εἰ δέ τις ἔροιτο τὸν συγγραφέα ποῖος ἦν καιρὸς οἰκειότερος τοῖς Καρχηδονίοις ἢ ποῖον πρᾶγμα τούτου δικαιότερον ἢ συμφορώτερον, ἐπείπερ ἐξ ἀρχῆς δυσηρεστοῦντο, καθάπερ οὗτός φησιν, τοῖς ὑπ’ Ἀννίβου πραττομένοις, τοῦ πεισθέντας τότε τοῖς ὑπὸ Ῥωμαίων παρακαλουμένοις ἐκδοῦναι μὲν τὸν αἴτιον τῶν ἀδικημάτων, ἐπανελέσθαι δ’ εὐλόγως δι’ ἑτέρων τὸν κοινὸν ἐχθρὸν τῆς πόλεως, περιποιήσασθαι δὲ τῇ χώρᾳ τὴν ἀσφάλειαν, ἀποτριψαμένους τὸν ἐπιφερόμενον πόλεμον, δόγματι μόνον τὴν ἐκδίκησιν ποιησαμένους, τί ἂν εἰπεῖν ἔχοι πρὸς αὐτά; δῆλον γὰρ ὡς οὐδέν. οἵ γε τοσοῦτον ἀπέσχον τοῦ πρᾶξαί τι τῶν προειρημένων ὡς ἑπτακαίδεκ’ ἔτη συνεχῶς πολεμήσαντες κατὰ τὴν Ἀννίβου προαίρεσιν οὐ πρότερον κατελύσαντο τὸν πόλεμον, ἕως οὗ πάσας ἐξελέγξαντες τὰς ἐλπίδας τελευταῖον εἰς τὸν περὶ τῆς πατρίδος καὶ τῶν ἐν αὐτῇ σωμάτων παρεγένοντο κίνδυνον.", "st": "3.8"}, {"sp": "N", "t": "τίνος δὴ χάριν ἐμνήσθην Φαβίου καὶ τῶν ὑπ’ ἐκείνου γεγραμμένων; οὐχ ἕνεκα τῆς πιθανότητος τῶν εἰρημένων, ἀγωνιῶν μὴ πιστευθῇ παρά τισιν — ἡ μὲν γὰρ [παρὰ] τούτων ἀλογία καὶ χωρὶς τῆς ἐμῆς ἐξηγήσεως αὐτὴ δι’ αὑτῆς δύναται θεωρεῖσθαι παρὰ τοῖς ἐντυγχάνουσιν — ἀλλὰ τῆς τῶν ἀναλαμβανόντων τὰς ἐκείνου βύβλους ὑπομνήσεως, ἵνα μὴ πρὸς τὴν ἐπιγραφὴν ἀλλὰ πρὸς τὰ πράγματα βλέπωσιν. ἔνιοι γὰρ οὐκ ἐπὶ τὰ λεγόμενα συνεπιστήσαντες ἀλλ’ ἐπ’ αὐτὸν τὸν λέγοντα καὶ λαβόντες ἐν νῷ διότι κατὰ τοὺς καιροὺς ὁ γράφων γέγονε καὶ τοῦ συνεδρίου μετεῖχε τῶν Ῥωμαίων, πᾶν εὐθέως ἡγοῦνται τὸ λεγόμενον ὑπὸ τούτου πιστόν. ἐγὼ δὲ φημὶ μὲν δεῖν οὐκ ἐν μικρῷ προσλαμβάνεσθαι τὴν τοῦ συγγραφέως πίστιν, οὐκ αὐτοτελῆ δὲ κρίνειν, τὸ δὲ πλεῖον ἐξ αὐτῶν τῶν πραγμάτων ποιεῖσθαι τοὺς ἀναγινώσκοντας τὰς δοκιμασίας. οὐ μὴν ἀλλὰ καὶ τοῦ γε Ῥωμαίων καὶ Καρχηδονίων πολέμου — τὴν γὰρ παρέκβασιν ἐντεῦθεν ἐποιησάμεθα — νομιστέον πρῶτον μὲν αἴτιον γεγονέναι τὸν Ἀμίλκου θυμὸν τοῦ Βάρκα μὲν ἐπικαλουμένου, πατρὸς δὲ κατὰ φύσιν Ἀννίβου γεγονότος. ἐκεῖνος γὰρ οὐχ ἡττηθεὶς τῷ περὶ Σικελίας πολέμῳ τῇ ψυχῇ τῷ δοκεῖν αὐτὸς μὲν ἀκέραια διατετηρηκέναι τὰ περὶ τὸν Ἔρυκα στρατόπεδα ταῖς ὁρμαῖς ἐφ’ ὧν αὐτὸς ἦν, διὰ δὲ τὴν ἐν τῇ ναυμαχίᾳ τῶν Καρχηδονίων ἧτταν τοῖς καιροῖς εἴκων πεποιῆσθαι τὰς συνθήκας, ἔμενεν ἐπὶ τῆς ὀργῆς, τηρῶν ἀεὶ πρὸς ἐπίθεσιν. εἰ μὲν οὖν μὴ τὸ περὶ τοὺς ξένους ἐγένετο κίνημα τοῖς Καρχηδονίοις, εὐθέως ἂν ἄλλην ἀρχὴν ἐποιεῖτο καὶ παρασκευὴν πραγμάτων, ὅσον ἐπ’ ἐκείνῳ. προκαταληφθεὶς δὲ ταῖς ἐμφυλίοις ταραχαῖς ἐν τούτοις καὶ περὶ ταύτας διέτριβε τὰς πράξεις.", "st": "3.9"}, {"sp": "N", "t": "Ῥωμαίων δὲ μετὰ τὸ καταλύσασθαι Καρχηδονίους τὴν προειρημένην ταραχὴν ἀπαγγειλάντων αὐτοῖς πόλεμον, τὸ μὲν πρῶτον εἰς πᾶν συγκατέβαινον, ὑπολαμβάνοντες αὑτοὺς νικήσειν τοῖς δικαίοις, καθάπερ ἐν ταῖς πρὸ ταύτης βύβλοις περὶ τούτων δεδηλώκαμεν, ὧν χωρὶς οὐχ οἷόν τ’ ἦν συμπεριενεχθῆναι δεόντως οὔτε τοῖς νῦν λεγομένοις οὔτε τοῖς μετὰ ταῦτα ῥηθησομένοις ὑφ’ ἡμῶν. πλὴν οὐκ ἐντρεπομένων τῶν Ῥωμαίων, εἴξαντες τῇ περιστάσει καὶ βαρυνόμενοι μέν, οὐκ ἔχοντες δὲ ποιεῖν οὐδὲν ἐξεχώρησαν Σαρδόνος, συνεχώρησαν δ’ εἰσοίσειν ἄλλα χίλια καὶ διακόσια τάλαντα πρὸς τοῖς πρότερον ἐφ’ ᾧ μὴ τὸν πόλεμον ἐκείνοις ἀναδέξασθαι τοῖς καιροῖς. διὸ καὶ δευτέραν, μεγίστην δὲ ταύτην θετέον αἰτίαν τοῦ μετὰ ταῦτα συστάντος πολέμου. Ἀμίλκας γὰρ προσλαβὼν τοῖς ἰδίοις θυμοῖς τὴν ἐπὶ τούτοις ὀργὴν τῶν πολιτῶν, ὡς θᾶττον τοὺς ἀποστάντας τῶν μισθοφόρων καταπολεμήσας ἐβεβαίωσε τῇ πατρίδι τὴν ἀσφάλειαν, εὐθέως ἐποιεῖτο τὴν ὁρμὴν ἐπὶ τὰ κατὰ τὴν Ἰβηρίαν πράγματα, σπουδάζων ταύτῃ χρήσασθαι παρασκευῇ πρὸς τὸν κατὰ Ῥωμαίων πόλεμον. ἣν δὴ καὶ τρίτην αἰτίαν νομιστέον, λέγω δὲ τὴν εὔροιαν τῶν κατ’ Ἰβηρίαν πραγμάτων Καρχηδονίοις. ταύταις γὰρ ταῖς χερσὶ πιστεύσαντες εὐθαρσῶς ἐνέβησαν εἰς τὸν προειρημένον πόλεμον. ὅτι δ’ Ἀμίλκας πλεῖστα μὲν συνεβάλετο πρὸς τὴν σύστασιν τοῦ δευτέρου πολέμου, καίπερ τετελευτηκὼς ἔτεσι δέκα πρότερον τῆς καταρχῆς αὐτοῦ, πολλὰ μὲν ἂν εὕροι τις εἰς τοῦτο· σχεδὸν δὲ πρὸς πίστιν ἀρκοῦν ἔσται τὸ λέγεσθαι μέλλον.", "st": "3.10"}, {"sp": "N", "t": "καθ’ οὓς γὰρ καιροὺς καταπολεμηθεὶς Ἀννίβας ὑπὸ Ῥωμαίων τέλος ἐκ τῆς πατρίδος ἐξεχώρησε καὶ παρ’ Ἀντιόχῳ διέτριβε, τότε Ῥωμαῖοι συνθεωροῦντες ἤδη τὴν Αἰτωλῶν ἐπιβολὴν ἐξαπέστειλαν πρεσβευτὰς πρὸς Ἀντίοχον, βουλόμενοι μὴ λανθάνειν σφᾶς τὴν τοῦ βασιλέως προαίρεσιν. οἱ δὲ πρέσβεις ὁρῶντες τὸν Ἀντίοχον προσέχοντα τοῖς Αἰτωλοῖς καὶ πρόθυμον ὄντα πολεμεῖν Ῥωμαίοις, ἐθεράπευον τὸν Ἀννίβαν, σπουδάζοντες εἰς ὑποψίαν ἐμβαλεῖν πρὸς τὸν Ἀντίοχον. ὃ καὶ συνέβη γενέσθαι. προβαίνοντος γὰρ τοῦ χρόνου, καὶ τοῦ βασιλέως ὑπόπτως ἔχοντος ἀεὶ καὶ μᾶλλον πρὸς τὸν Ἀννίβαν, ἐγένετό τις καιρὸς ὡς ἐπὶ λόγον ἀχθῆναι τὴν ὑποικουρουμένην ἀτοπίαν ἐν αὐτοῖς. ἐν ᾧ καὶ πλείους ἀπολογισμοὺς ποιησάμενος Ἀννίβας τέλος ἐπὶ τὸ τοιοῦτο κατήντησε, δυσχρηστούμενος τοῖς λόγοις. ἔφη γάρ, καθ’ ὃν καιρὸν ὁ πατὴρ αὐτοῦ τὴν εἰς Ἰβηρίαν ἔξοδον μέλλοι στρατεύεσθαι μετὰ τῶν δυνάμεων, ἔτη μὲν ἔχειν ἐννέα, θύοντος δ’ αὐτοῦ τῷ Διὶ παρεστάναι παρὰ τὸν βωμόν. ἐπεὶ δὲ καλλιερήσας κατασπείσαι τοῖς θεοῖς καὶ ποιήσαι τὰ νομιζόμενα, τοὺς μὲν ἄλλους τοὺς περὶ τὴν θυσίαν ἀποστῆναι κελεῦσαι μικρόν, αὐτὸν δὲ προσκαλεσάμενον ἐρέσθαι φιλοφρόνως εἰ βούλεται συνεξορμᾶν ἐπὶ τὴν στρατείαν. ἀσμένως δὲ κατανεύσαντος αὐτοῦ καί τι καὶ προσαξιώσαντος παιδικῶς, λαβόμενον τῆς δεξιᾶς προσαγαγεῖν αὐτὸν πρὸς τὸν βωμὸν καὶ κελεύειν ἁψάμενον τῶν ἱερῶν ὀμνύναι μηδέποτε Ῥωμαίοις εὐνοήσειν. ταῦτ’ οὖν εἰδότα σαφῶς ἠξίου τὸν Ἀντίοχον, ἕως μὲν ἄν τι δυσχερὲς βουλεύηται κατὰ Ῥωμαίων, θαρρεῖν καὶ πιστεύειν, αὐτὸν συνεργὸν ἕξειν νομίζοντ’ ἀληθινώτατον. ἐπὰν δὲ διαλύσεις ἢ φιλίαν συντίθηται πρὸς αὐτούς, τότε μὴ προσδεῖσθαι διαβολῆς, ἀλλ’ ἀπιστεῖν καὶ φυλάττεσθαι·", "st": "3.11"}, {"sp": "N", "t": "πᾶν γάρ τι πρᾶξαι κατ’ αὐτῶν ὃ δυνατὸς εἴη. ὁ μὲν οὖν Ἀντίοχος ἀκούσας καὶ δόξας αὐτοπαθῶς ἅμα δ’ ἀληθινῶς εἰρῆσθαι, πάσης τῆς προϋπαρχούσης ὑποψίας ἀπέστη. τῆς μέντοι γε δυσμενείας τῆς Ἀμίλκου καὶ τῆς ὅλης προθέσεως ὁμολογούμενον θετέον εἶναι τοῦτο μαρτύριον, ὡς καὶ δι’ αὐτῶν φανερὸν ἐγένετο τῶν πραγμάτων. τοιούτους γὰρ ἐχθροὺς παρεσκεύασε Ῥωμαίοις Ἀσδρούβαν τε τὸν τῆς θυγατρὸς ἄνδρα καὶ τὸν αὑτοῦ κατὰ φύσιν υἱὸν Ἀννίβαν ὥστε μὴ καταλιπεῖν ὑπερβολὴν δυσμενείας. Ἀσδρούβας μὲν οὖν προαποθανὼν οὐ πᾶσιν ἔκδηλον ἐποίησε τὴν αὑτοῦ πρόθεσιν· Ἀννίβᾳ δὲ παρέδωκαν οἱ καιροὶ καὶ λίαν ἐναποδείξασθαι τὴν πατρῴαν ἔχθραν εἰς Ῥωμαίους. διὸ καὶ τοὺς ἐπὶ πραγμάτων ταττομένους χρὴ τῶν τοιούτων οὐδενὸς μᾶλλον φροντίζειν ὡς τοῦ μὴ λανθάνειν τὰς προαιρέσεις τῶν διαλυομένων τὰς ἔχθρας ἢ συντιθεμένων τὰς φιλίας, πότε τοῖς καιροῖς εἴκοντες καὶ πότε ταῖς ψυχαῖς ἡττώμενοι ποιοῦνται τὰς συνθήκας, ἵνα τοὺς μὲν ἐφέδρους νομίζοντες εἶναι τῶν καιρῶν ἀεὶ φυλάττωνται, τοῖς δὲ πιστεύοντες ὡς ὑπηκόοις ἢ φίλοις ἀληθινοῖς πᾶν τὸ παραπῖπτον ἐξ ἑτοίμου παραγγέλλωσιν. αἰτίας μὲν οὖν τοῦ κατ’ Ἀννίβαν πολέμου τὰς προειρημένας ἡγητέον, ἀρχὰς δὲ τὰς μελλούσας λέγεσθαι.", "st": "3.12"}, {"sp": "N", "t": "Καρχηδόνιοι γὰρ βαρέως μὲν ἔφερον καὶ τὴν ὑπὲρ Σικελίας ἧτταν, συνεπέτεινε δ’ αὐτῶν τὴν ὀργήν, καθάπερ ἐπάνω προεῖπον, τὰ κατὰ Σαρδόνα καὶ τὸ τῶν τελευταῖον συντεθέντων χρημάτων πλῆθος. διόπερ ἅμα τῷ τὰ πλεῖστα κατ’ Ἰβηρίαν ὑφ’ αὑτοὺς ποιήσασθαι πρὸς πᾶν ἑτοίμως διέκειντο τὸ κατὰ Ῥωμαίων ὑποδεικνύμενον. προσπεσούσης οὖν τῆς Ἀσδρούβου τελευτῆς, ᾧ μετὰ τὸν Ἀμίλκου θάνατον ἐνεχείρισαν τὰ κατὰ τὴν Ἰβηρίαν, τὸ μὲν πρῶτον ἐκαραδόκουν τὰς τῶν δυνάμεων ὁρμάς· ἀφικομένης δὲ τῆς ἀγγελίας ἐκ τῶν στρατοπέδων ὅτι συμβαίνει τὰς δυνάμεις ὁμοθυμαδὸν ᾑρῆσθαι στρατηγὸν Ἀννίβαν, παραυτίκα συναθροίσαντες τὸν δῆμον μιᾷ γνώμῃ κυρίαν ἐποίησαν τὴν τῶν στρατοπέδων αἵρεσιν. Ἀννίβας δὲ παραλαβὼν τὴν ἀρχὴν εὐθέως ὥρμησεν ὡς καταστρεψόμενος τὸ τῶν Ὀλκάδων ἔθνος· ἀφικόμενος δὲ πρὸς Ἀλθαίαν τὴν βαρυτάτην αὐτῶν πόλιν κατεστρατοπέδευσεν. μετὰ δὲ ταῦτα χρησάμενος ἐνεργοῖς ἅμα καὶ καταπληκτικαῖς προσβολαῖς ταχέως ἐκράτησε τῆς πόλεως. οὗ συμβάντος οἱ λοιποὶ γενόμενοι καταπλαγεῖς ἐνέδωκαν αὑτοὺς τοῖς Καρχηδονίοις. ἀργυρολογήσας δὲ τὰς πόλεις καὶ κυριεύσας πολλῶν χρημάτων ἧκε παραχειμάσων εἰς Καινὴν πόλιν. μεγαλοψύχως δὲ χρησάμενος τοῖς ὑποταττομένοις καὶ τὰ μὲν δοὺς τῶν ὀψωνίων τοῖς συστρατευομένοις τὰ δ’ ὑπισχνούμενος πολλὴν εὔνοιαν καὶ μεγάλας ἐλπίδας ἐνειργάσατο ταῖς δυνάμεσι.", "st": "3.13"}, {"sp": "N", "t": "τῷ δ’ ἐπιγινομένῳ θέρει πάλιν ὁρμήσας ἐπὶ τοὺς Οὐακκαίους Ἑλμαντικὴν μὲν ἐξ ἐφόδου ποιησάμενος προσβολὰς κατέσχεν, Ἀρβουκάλην δὲ διὰ τὸ μέγεθος τῆς πόλεως καὶ τὸ πλῆθος, ἔτι δὲ τὴν γενναιότητα τῶν οἰκητόρων μετὰ πολλῆς ταλαιπωρίας πολιορκήσας κατὰ κράτος εἷλε. μετὰ δὲ ταῦτα παραδόξως εἰς τοὺς μεγίστους ἦλθε κινδύνους ἐπανάγων, συνδραμόντων ἐπ’ αὐτὸν τῶν Καρπησίων, ὃ σχεδὸν ἰσχυρότατόν ἐστιν ἔθνος τῶν κατ’ ἐκείνους τοὺς τόπους, ὁμοίως δὲ καὶ τῶν ἀστυγειτόνων ἁθροισθέντων ἅμα τούτοις, οὓς ἠρέθισαν μάλιστα μὲν οἱ τῶν Ὀλκάδων φυγάδες, συνεξέκαυσαν δὲ καὶ τῶν ἐκ τῆς Ἑλμαντικῆς οἱ διασωθέντες. πρὸς οὓς εἰ μὲν ἐκ παρατάξεως ἠναγκάσθησαν οἱ Καρχηδόνιοι διακινδυνεύειν, ὁμολογουμένως ἂν ἡττήθησαν. νῦν δὲ πραγματικῶς καὶ νουνεχῶς ἐξ ὑποστροφῆς ἀναχωρήσαντος Ἀννίβου καὶ πρόβλημα ποιησαμένου τὸν Τάγον καλούμενον ποταμὸν καὶ περὶ τὴν τοῦ ποταμοῦ διάβασιν συστησαμένου τὸν κίνδυνον, ἅμα δὲ συγχρησαμένου συναγωνιστῇ τῷ ποταμῷ καὶ τοῖς θηρίοις οἷς εἶχε περὶ τετταράκοντα τὸν ἀριθμόν, συνέβη τὰ ὅλα παραδόξως καὶ κατὰ λόγον αὐτῷ χωρῆσαι. τῶν γὰρ βαρβάρων ἐπιβαλομένων κατὰ πλείους τόπους βιάζεσθαι καὶ περαιοῦσθαι τὸν ποταμόν, τὸ μὲν πλεῖστον αὐτῶν μέρος διεφθάρη περὶ τὰς ἐκβάσεις, παραπορευομένων τῶν θηρίων παρὰ τὸ χεῖλος καὶ τοὺς ἐκβαίνοντας ἀεὶ προκαταλαμβανόντων· πολλοὶ δὲ κατ’ αὐτὸν τὸν ποταμὸν ὑπὸ τῶν ἱππέων ἀπώλοντο διὰ τὸ κρατεῖν μὲν μᾶλλον τοῦ ῥεύματος τοὺς ἵππους, ἐξ ὑπερδεξίου δὲ ποιεῖσθαι τὴν μάχην τοὺς ἱππέας πρὸς τοὺς πεζούς. τέλος δὲ τοὔμπαλιν ἐπιδιαβάντες οἱ περὶ τὸν Ἀννίβαν ἐπὶ τοὺς βαρβάρους ἐτρέψαντο πλείους ἢ δέκα μυριάδας ἀνθρώπων. ὧν ἡττηθέντων οὐδεὶς ἔτι τῶν ἐντὸς Ἴβηρος ποταμοῦ ῥᾳδίως πρὸς αὐτοὺς ἀντοφθαλμεῖν ἐτόλμα πλὴν Ζακανθαίων. ταύτης δὲ τῆς πόλεως ἐπειρᾶτο κατὰ δύναμιν ἀπέχεσθαι, βουλόμενος μηδεμίαν ἀφορμὴν ὁμολογουμένην δοῦναι τοῦ πολέμου Ῥωμαίοις, ἕως τἄλλα πάντα βεβαίως ὑφ’ αὑτὸν ποιήσαιτο κατὰ τὰς Ἀμίλκου τοῦ πατρὸς ὑποθήκας καὶ παραινέσεις.", "st": "3.14"}, {"sp": "N", "t": "οἱ δὲ Ζακανθαῖοι συνεχῶς ἔπεμπον εἰς τὴν Ῥώμην, ἅμα μὲν ἀγωνιῶντες περὶ σφῶν καὶ προορώμενοι τὸ μέλλον, ἅμα δὲ βουλόμενοι μὴ λανθάνειν Ῥωμαίους τὴν γινομένην εὔροιαν Καρχηδονίοις τῶν κατ’ Ἰβηρίαν πραγμάτων. Ῥωμαῖοι δὲ πλεονάκις αὐτῶν παρακηκοότες τότε πρεσβευτὰς ἐξαπέστειλαν τοὺς ἐπισκεψομένους ὑπὲρ τῶν προσπιπτόντων. Ἀννίβας δὲ κατὰ τοὺς αὐτοὺς καιροὺς πεποιημένος ὑφ’ αὑτὸν οὓς προέθετο παρῆν αὖθις μετὰ τῶν δυνάμεων παραχειμάσων εἰς Καινὴν πόλιν, ἥτις ὡσανεὶ πρόσχημα καὶ βασίλειον ἦν Καρχηδονίων ἐν τοῖς κατὰ τὴν Ἰβηρίαν τόποις. καταλαβὼν δὲ τὴν παρὰ τῶν Ῥωμαίων πρεσβείαν καὶ δοὺς αὑτὸν εἰς ἔντευξιν διήκουε περὶ τῶν ἐνεστώτων. Ῥωμαῖοι μὲν οὖν διεμαρτύροντο Ζακανθαίων ἀπέχεσθαι — κεῖσθαι γὰρ αὐτοὺς ἐν τῇ σφετέρᾳ πίστει — καὶ τὸν Ἴβηρα ποταμὸν μὴ διαβαίνειν κατὰ τὰς ἐπ’ Ἀσδρούβου γενομένας ὁμολογίας. ὁ δ’ Ἀννίβας, ἅτε νέος μὲν ὤν, πλήρης δὲ πολεμικῆς ὁρμῆς, ἐπιτυχὴς δ’ ἐν ταῖς ἐπιβολαῖς, πάλαι δὲ παρωρμημένος πρὸς τὴν κατὰ Ῥωμαίων ἔχθραν, πρὸς μὲν ἐκείνους, ὡς κηδόμενος Ζακανθαίων, ἐνεκάλει Ῥωμαίοις διότι μικροῖς ἔμπροσθεν χρόνοις, στασιαζόντων αὐτῶν, λαβόντες τὴν ἐπιτροπὴν [εἰς τὸ διαλῦσαι] ἀδίκως ἐπανέλοιντό τινας τῶν προεστώτων· οὓς οὐ περιόψεσθαι παρεσπονδημένους· πάτριον γὰρ εἶναι Καρχηδονίοις τὸ μηδένα τῶν ἀδικουμένων περιορᾶν· πρὸς δὲ Καρχηδονίους διεπέμπετο, πυνθανόμενος τί δεῖ ποιεῖν, ὅτι Ζακανθαῖοι πιστεύοντες τῇ Ῥωμαίων συμμαχίᾳ τινὰς τῶν ὑφ’ αὑτοὺς ταττομένων ἀδικοῦσι. καθόλου δ’ ἦν πλήρης ἀλογίας καὶ θυμοῦ βιαίου· διὸ καὶ ταῖς μὲν ἀληθιναῖς αἰτίαις οὐκ ἐχρῆτο, κατέφευγε δ’ εἰς προφάσεις ἀλόγους· ἅπερ εἰώθασι ποιεῖν οἱ διὰ τὰς προεγκαθημένας αὐτοῖς ὁρμὰς ὀλιγωροῦντες τοῦ καθήκοντος. πόσῳ γὰρ ἦν ἄμεινον οἴεσθαι δεῖν Ῥωμαίους ἀποδοῦναι σφίσι Σαρδόνα καὶ τοὺς ἐπιταχθέντας ἅμα ταύτῃ φόρους, οὓς τοῖς καιροῖς συνεπιθέμενοι πρότερον ἀδίκως παρ’ αὐτῶν ἔλαβον· εἰ δὲ μή, φάναι πολεμήσειν; νῦν δὲ τὴν μὲν οὖσαν αἰτίαν ἀληθινὴν παρασιωπῶν, τὴν δ’ οὐχ ὑπάρχουσαν περὶ Ζακανθαίων πλάττων, οὐ μόνον ἀλόγως, ἔτι δὲ μᾶλλον ἀδίκως κατάρχειν ἐδόκει τοῦ πολέμου. οἱ δὲ τῶν Ῥωμαίων πρέσβεις, ὅτι μὲν εἴη πολεμητέον σαφῶς εἰδότες, ἀπέπλευσαν εἰς Καρχηδόνα, τὰ παραπλήσια θέλοντες ἐπιμαρτύρασθαι κἀκείνους· οὐ μὴν ἐν Ἰταλίᾳ γε πολεμήσειν ἤλπισαν, ἀλλ’ ἐν Ἰβηρίᾳ, χρήσεσθαι δὲ πρὸς τὸν πόλεμον ὁρμητηρίῳ τῇ Ζακανθαίων πόλει.", "st": "3.15"}, {"sp": "N", "t": "διὸ καὶ πρὸς ταύτην ἁρμοζόμενοι τὴν ὑπόθεσιν ἡ σύγκλητος ἔκρινεν ἀσφαλίσασθαι τὰ κατὰ τὴν Ἰλλυρίδα πράγματα, προορωμένη διότι μέγας ἔσται καὶ πολυχρόνιος καὶ μακρὰν ἀπὸ τῆς οἰκείας ὁ πόλεμος. συνέβαινε γὰρ κατ’ ἐκείνους τοὺς καιροὺς Δημήτριον τὸν Φάριον, ἐπιλελησμένον μὲν τῶν προγεγονότων εἰς αὐτὸν εὐεργετημάτων ὑπὸ Ῥωμαίων, καταπεφρονηκότα δὲ πρότερον μὲν διὰ τὸν ἀπὸ Γαλατῶν τότε δὲ διὰ τὸν ἀπὸ Καρχηδονίων φόβον περιεστῶτα Ῥωμαίους, πάσας δ’ ἔχοντα τὰς ἐλπίδας ἐν τῇ Μακεδόνων οἰκίᾳ διὰ τὸ συμπεπολεμηκέναι καὶ μετεσχηκέναι τῶν πρὸς Κλεομένη κινδύνων Ἀντιγόνῳ, πορθεῖν μὲν καὶ καταστρέφεσθαι τὰς κατὰ τὴν Ἰλλυρίδα πόλεις τὰς ὑπὸ Ῥωμαίους ταττομένας, πεπλευκέναι δ’ ἔξω τοῦ Λίσσου παρὰ τὰς συνθήκας πεντήκοντα λέμβοις καὶ πεπορθηκέναι πολλὰς τῶν Κυκλάδων νήσων. εἰς ἃ βλέποντες Ῥωμαῖοι καὶ θεωροῦντες ἀνθοῦσαν τὴν Μακεδόνων οἰκίαν ἔσπευδον ἀσφαλίσασθαι τὰ πρὸς ἕω τῆς Ἰταλίας πεπεισμένοι καταταχήσειν διορθωσάμενοι μὲν τὴν Ἰλλυριῶν ἄγνοιαν, ἐπιτιμήσαντες δὲ καὶ κολάσαντες τὴν ἀχαριστίαν καὶ προπέτειαν τὴν Δημητρίου. διεψεύσθησαν δὲ τοῖς λογισμοῖς· κατετάχησε γὰρ αὐτοὺς Ἀννίβας, ἐξελὼν τὴν Ζακανθαίων πόλιν. καὶ παρὰ τοῦτο συνέβη τὸν πόλεμον οὐκ ἐν Ἰβηρίᾳ, πρὸς αὐτῇ δὲ τῇ Ῥώμῃ καὶ κατὰ πᾶσαν γενέσθαι τὴν Ἰταλίαν. οὐ μὴν ἀλλὰ τούτοις χρησάμενοι τοῖς διαλογισμοῖς Ῥωμαῖοι μὲν ὑπὸ τὴν ὡραίαν Λεύκιον τὸν Αἰμίλιον ἐξαπέστειλαν μετὰ δυνάμεως ἐπὶ τὰς κατὰ τὴν Ἰλλυρίδα πράξεις κατὰ τὸ πρῶτον ἔτος τῆς ἑκατοστῆς καὶ τετταρακοστῆς ὀλυμπιάδος.", "st": "3.16"}, {"sp": "N", "t": "Ἀννίβας δὲ μετὰ τῆς δυνάμεως ἀναζεύξας ἐκ τῆς Καινῆς πόλεως προῆγε, ποιούμενος τὴν πορείαν ἐπὶ τὴν Ζάκανθαν. ἡ δὲ πόλις αὕτη κεῖται μὲν ἐπὶ τῷ πρὸς θάλατταν καθήκοντι πρόποδι τῆς ὀρεινῆς τῆς συναπτούσης τὰ πέρατα τῆς Ἰβηρίας καὶ Κελτιβηρίας, ἀπέχει δὲ τῆς θαλάττης ὡς ἑπτὰ στάδια. νέμονται δὲ χώραν οἱ κατοικοῦντες αὐτὴν πάμφορον καὶ διαφέρουσαν ἀρετῇ πάσης τῆς Ἰβηρίας. ᾗ τότε παραστρατοπεδεύσας Ἀννίβας ἐνεργὸς ἐγίνετο περὶ τὴν πολιορκίαν, πολλὰ προορώμενος εὔχρηστα πρὸς τὸ μέλλον ἐκ τοῦ κατὰ κράτος ἑλεῖν αὐτήν. πρῶτον μὲν γὰρ ὑπέλαβε παρελέσθαι Ῥωμαίων τὴν ἐλπίδα τοῦ συστήσασθαι τὸν πόλεμον ἐν Ἰβηρίᾳ· δεύτερον δὲ καταπληξάμενος ἅπαντας εὐτακτοτέρους μὲν ἐπέπειστο παρασκευάσειν τοὺς ὑφ’ αὐτὸν ἤδη ταττομένους, εὐλαβεστέρους δὲ τοὺς ἀκμὴν αὐτοκράτορας ὄντας τῶν Ἰβήρων, τὸ δὲ μέγιστον, οὐδὲν ἀπολιπὼν ὄπισθεν πολέμιον ἀσφαλῶς ποιήσεσθαι τὴν εἰς τοὔμπροσθεν πορείαν. χωρίς τε τούτων εὐπορήσειν μὲν χορηγιῶν αὐτὸς ὑπελάμβανεν πρὸς τὰς ἐπιβολάς, προθυμίαν δ’ ἐνεργάσεσθαι ταῖς δυνάμεσιν ἐκ τῆς ἐσομένης ἑκάστοις ὠφελείας, προκαλέσεσθαι δὲ τὴν εὔνοιαν τῶν ἐν οἴκῳ Καρχηδονίων διὰ τῶν ἀποσταλησομένων αὐτοῖς λαφύρων. τοιούτοις δὲ χρώμενος διαλογισμοῖς ἐνεργῶς προσέκειτο τῇ πολιορκίᾳ, τοτὲ μὲν ὑπόδειγμα τῷ πλήθει ποιῶν αὑτὸν καὶ γινόμενος αὐτουργὸς τῆς ἐν τοῖς ἔργοις ταλαιπωρίας, ἔστι δ’ ὅτε παρακαλῶν τὰ πλήθη καὶ παραβόλως διδοὺς αὑτὸν εἰς τοὺς κινδύνους. πᾶσαν δὲ κακοπάθειαν καὶ μέριμναν ὑπομείνας τέλος ἐν ὀκτὼ μησὶ κατὰ κράτος εἷλε τὴν πόλιν. κύριος δὲ γενόμενος χρημάτων πολλῶν καὶ σωμάτων καὶ κατασκευῆς τὰ μὲν χρήματ’ εἰς τὰς ἰδίας ἐπιβολὰς παρέθετο κατὰ τὴν ἐξ ἀρχῆς πρόθεσιν, τὰ δὲ σώματα διένειμε κατὰ τὴν ἀξίαν ἑκάστοις τῶν συστρατευομένων, τὴν δὲ κατασκευὴν παραχρῆμα πᾶσαν ἐξέπεμψε τοῖς Καρχηδονίοις. ταῦτα δὲ πράξας οὐ διεψεύσθη τοῖς λογισμοῖς οὐδ’ ἀπέτυχε τῆς ἐξ ἀρχῆς προθέσεως, ἀλλὰ τούς τε στρατιώτας προθυμοτέρους ἐποίησε πρὸς τὸ κινδυνεύειν, τούς τε Καρχηδονίους ἑτοίμους παρεσκεύασε πρὸς τὸ παραγγελλόμενον, αὐτός τε πολλὰ τῶν χρησίμων μετὰ ταῦτα κατειργάσατο διὰ τῆς τῶν χορηγιῶν παραθέσεως.", "st": "3.17"}, {"sp": "N", "t": "κατὰ δὲ τοὺς αὐτοὺς καιροὺς Δημήτριος ἅμα τῷ συνεῖναι τὴν ἐπιβολὴν τῶν Ῥωμαίων παραυτίκα μὲν εἰς τὴν Διμάλην ἀξιόχρεων φρουρὰν εἰσέπεμψε καὶ τὰς ἁρμοζούσας ταύτης χορηγίας, ἐκ δὲ τῶν λοιπῶν πόλεων τοὺς μὲν ἀντιπολιτευομένους ἐπανείλετο, τοῖς δ’ αὑτοῦ φίλοις ἐνεχείρισε τὰς δυναστείας, αὐτὸς δ’ ἐκ τῶν ὑποτεταγμένων ἐπιλέξας τοὺς ἀνδρωδεστάτους ἑξακισχιλίους συνέστησε τούτους εἰς τὴν Φάρον. ὁ δὲ στρατηγὸς τῶν Ῥωμαίων ἀφικόμενος εἰς τὴν Ἰλλυρίδα μετὰ τῶν δυνάμεων καὶ θεωρῶν τοὺς ὑπεναντίους θαρροῦντας ἐπὶ τῇ τῆς Διμάλης ὀχυρότητι καὶ ταῖς παρασκευαῖς, ἔτι δὲ τῷ δοκεῖν αὐτὴν ἀνάλωτον ὑπάρχειν, ταύτῃ πρῶτον ἐγχειρεῖν ἔκρινε, βουλόμενος καταπλήξασθαι τοὺς πολεμίους. παρακαλέσας δὲ τοὺς κατὰ μέρος ἡγεμόνας καὶ προσαγαγὼν ἔργα κατὰ πλείους τόπους ἤρξατο πολιορκεῖν. λαβὼν δὲ κατὰ κράτος ἐν ἡμέραις ἑπτὰ παραχρῆμα πάντας ἥττησε ταῖς ψυχαῖς τοὺς ὑπεναντίους. διόπερ εὐθέως παρῆσαν ἐκ πασῶν τῶν πόλεων ἐπιτρέποντες καὶ διδόντες αὑτοὺς εἰς τὴν τῶν Ῥωμαίων πίστιν. ὁ δὲ προσδεξάμενος ἑκάστους ἐπὶ ταῖς ἁρμοζούσαις ὁμολογίαις ἐποιεῖτο τὸν πλοῦν εἰς τὴν Φάρον ἐπ’ αὐτὸν τὸν Δημήτριον. πυνθανόμενος δὲ τήν τε πόλιν ὀχυρὰν εἶναι καὶ πλῆθος ἀνθρώπων διαφερόντων εἰς αὐτὴν ἡθροῖσθαι, πρὸς δὲ καὶ ταῖς χορηγίαις ἐξηρτῦσθαι καὶ ταῖς ἄλλαις παρασκευαῖς, ὑφεωρᾶτο μὴ δυσχερῆ καὶ πολυχρόνιον συμβῇ γενέσθαι τὴν πολιορκίαν. διὸ προορώμενος ἕκαστα τούτων ἐχρήσατο παρ’ αὐτὸν τὸν καιρὸν τοιῷδέ τινι γένει στρατηγήματος. ποιησάμενος γὰρ τὸν ἐπίπλουν νυκτὸς ἐπὶ τὴν νῆσον παντὶ τῷ στρατεύματι τὸ μὲν πλεῖον μέρος τῆς δυνάμεως ἀπεβίβασεν εἴς τινας ὑλώδεις καὶ κοίλους τόπους, εἴκοσι δὲ ναυσὶν ἐπιγενομένης ἡμέρας ἔπλει προδήλως ἐπὶ τὸν ἔγγιστα τῆς πόλεως λιμένα. συνορῶντες δὲ τὰς ναῦς οἱ περὶ τὸν Δημήτριον καὶ καταφρονοῦντες τοῦ πλήθους ὥρμησαν ἐκ τῆς πόλεως ἐπὶ τὸν λιμένα, κωλύσοντες τὴν ἀπόβασιν τῶν ὑπεναντίων.", "st": "3.18"}, {"sp": "N", "t": "ἅμα δὲ τῷ συμμῖξαι γινομένης ἰσχυρᾶς τῆς συμπλοκῆς προσεβοήθουν ἀεὶ πλείους τῶν ἐκ τῆς πόλεως· τέλος δὲ πάντες ἐξεχύθησαν εἰς τὸν κίνδυνον. τῶν δὲ Ῥωμαίων οἱ τῆς νυκτὸς ἀποβάντες εἰς τὸν καιρὸν τοῦτον συνῆψαν, διὰ τόπων ἀδήλων ποιούμενοι τὴν πορείαν. καὶ καταλαβόμενοι μεταξὺ τῆς πόλεως καὶ τοῦ λιμένος λόφον ἐρυμνὸν διέκλεισαν ἀπὸ τῆς πόλεως τοὺς ἐκβεβοηθηκότας. οἱ δὲ περὶ τὸν Δημήτριον συννοήσαντες τὸ γεγονὸς τοῦ μὲν διακωλύειν τοὺς ἀποβαίνοντας ἀπέστησαν, συναθροίσαντες δὲ σφᾶς αὐτοὺς καὶ παρακαλέσαντες ὥρμησαν, κρίναντες ἐκ παρατάξεως διακινδυνεύειν πρὸς τοὺς ἐπὶ τὸν λόφον. οἱ δὲ Ῥωμαῖοι θεωροῦντες τὴν ἔφοδον τῶν Ἰλλυριῶν ἐνεργὸν καὶ συντεταγμένην ἀντέπεσαν ταῖς σπείραις καταπληκτικῶς. ἅμα δὲ τοῖς προειρημένοις οἱ πεποιημένοι τὴν ἀπόβασιν ἀπὸ τῶν πλοίων, συνορῶντες τὸ γινόμενον, προσέκειντο κατόπιν· καὶ πανταχόθεν προσπίπτοντες θόρυβον καὶ ταραχὴν οὐ μικρὰν ἐν τοῖς Ἰλλυριοῖς κατεσκεύαζον. ἐξ οὗ τῶν μὲν κατὰ πρόσωπον τῶν δὲ κατὰ νώτου πονούντων, τέλος οἱ περὶ τὸν Δημήτριον ἐτράπησαν· καὶ τινὲς μὲν αὐτῶν ἔφυγον ὡς πρὸς τὴν πόλιν, οἱ δὲ πλείους ἀνοδίᾳ κατὰ τῆς νήσου διεσπάρησαν. ὁ δὲ Δημήτριος ἔχων ἑτοίμους λέμβους πρὸς τὸ συμβαῖνον ἔν τισι τόποις ἐρήμοις ὑφορμοῦντας ἐπὶ τούτους ἐποιήσατο τὴν ἀποχώρησιν. εἰς οὓς ἐμβὰς ἐπιγενομένης τῆς νυκτὸς ἀπέπλευσε καὶ διεκομίσθη παραδόξως πρὸς τὸν βασιλέα Φίλιππον, παρ’ ᾧ τὸ λοιπὸν διέτριβε τοῦ βίου μέρος, ἀνὴρ θράσος μὲν καὶ τόλμαν κεκτημένος, ἀλόγιστον δὲ ταύτην καὶ τελέως ἄκριτον. διὸ καὶ τὴν καταστροφὴν παραπλησίαν αὐτῷ συνέβη γενέσθαι τῇ κατὰ τὸν ὅλον βίον προαιρέσει. καταλαβέσθαι γὰρ ἐγχειρήσας μετὰ τῆς Φιλίππου γνώμης τὴν τῶν Μεσσηνίων πόλιν εἰκῇ καὶ παραβόλως ἐν αὐτῷ τῷ τῆς πράξεως καιρῷ διεφθάρη· περὶ ὧν ἡμεῖς τὰ κατὰ μέρος, ὅταν ἐπὶ τοὺς καιροὺς ἔλθωμεν, διασαφήσομεν. ὁ δὲ στρατηγὸς τῶν Ῥωμαίων Αἰμίλιος τὴν μὲν Φάρον εὐθέως ἐξ ἐφόδου παραλαβὼν κατέσκαψε, τῆς δὲ λοιπῆς Ἰλλυρίδος ἐγκρατὴς γενόμενος καὶ πάντα διατάξας κατὰ τὴν αὑτοῦ προαίρεσιν μετὰ ταῦτα ληγούσης ἤδη τῆς θερείας εἰς τὴν Ῥώμην ἐπανῆλθεν καὶ τὴν εἴσοδον ἐποιήσατο μετὰ θριάμβου καὶ τῆς ἁπάσης εὐδοξίας. ἐδόκει γὰρ οὐ μόνον ἐπιδεξίως, ἔτι δὲ μᾶλλον ἀνδρωδῶς κεχρῆσθαι τοῖς πράγμασιν.", "st": "3.19"}, {"sp": "N", "t": "οἱ δὲ Ῥωμαῖοι, προσπεπτωκυίας αὐτοῖς ἤδη τῆς τῶν Ζακανθαίων ἁλώσεως, οὐ μὰ Δία περὶ τοῦ πολέμου τότε διαβούλιον ἦγον, καθάπερ ἔνιοι τῶν συγγραφέων φασί, προσκατατάττοντες ἔτι καὶ τοὺς εἰς ἑκάτερα ῥηθέντας λόγους, πάντων ἀτοπώτατον πρᾶγμα ποιοῦντες. πῶς γὰρ οἷόν τ’ ἦν Ῥωμαίους τοὺς ἐνιαυτῷ πρότερον ἐπηγγελκότας πόλεμον Καρχηδονίοις, ἐὰν ἐπιβαίνωσι τῆς Ζακανθαίων χώρας, τούτους κατὰ κράτος ἑαλωκυίας αὐτῆς τῆς πόλεως τότε βουλεύεσθαι συνελθόντας πότερα πολεμητέον ἢ τοὐναντίον; πῶς δὲ καὶ τίνα τρόπον ἅμα μὲν τὴν στυγνότητα τοῦ συνεδρίου παρεισάγουσι θαυμάσιον, ἅμα δὲ τοὺς υἱοὺς ἀπὸ δώδεκ’ ἐτῶν ἄγειν φασὶ τοὺς πατέρας εἰς τὸ συνέδριον, οὓς μετέχοντας τῶν διαβουλίων οὐδὲ τῶν ἀναγκαίων οὐδενὶ προΐεσθαι τῶν ἀπορρήτων οὐδέν; ὧν οὔτ’ εἰκὸς οὔτ’ ἀληθές ἐστι τὸ παράπαν οὐδέν, εἰ μὴ νὴ Δία πρὸς τοῖς ἄλλοις ἡ τύχη καὶ τοῦτο προσένειμε Ῥωμαίοις, τὸ φρονεῖν αὐτοὺς εὐθέως ἐκ γενετῆς. πρὸς μὲν οὖν τὰ τοιαῦτα τῶν συγγραμμάτων οἷα γράφει Χαιρέας καὶ Σωσύλος οὐδὲν ἂν δέοι πλέον λέγειν· οὐ γὰρ ἱστορίας, ἀλλὰ κουρεακῆς καὶ πανδήμου λαλιᾶς ἔμοιγε δοκοῦσι τάξιν ἔχειν καὶ δύναμιν. Ῥωμαῖοι δέ, προσπεσόντος σφίσι τοῦ γεγονότος κατὰ τοὺς Ζακανθαίους ἀτυχήματος, παραχρῆμα πρεσβευτὰς ἑλόμενοι κατὰ σπουδὴν ἐξαπέστειλαν εἰς τὴν Καρχηδόνα, δύο προτείνοντες αὐτοῖς, ὧν τὸ μὲν αἰσχύνην ἅμα καὶ βλάβην ἐδόκει φέρειν δεξαμένοις τοῖς Καρχηδονίοις, τὸ δ’ ἕτερον πραγμάτων καὶ κινδύνων ἀρχὴν μεγάλων. ἢ γὰρ τὸν στρατηγὸν Ἀννίβαν καὶ τοὺς μετ’ αὐτοῦ συνέδρους ἐκδότους διδόναι Ῥωμαίοις ἐπέταττον, ἢ προήγγελλον τὸν πόλεμον. παραγενομένων δὲ τῶν Ῥωμαίων καὶ παρελθόντων εἰς τὸ συνέδριον καὶ διασαφούντων ταῦτα, δυσχερῶς ἤκουον οἱ Καρχηδόνιοι τὴν αἵρεσιν τῶν προτεινομένων. ὅμως δὲ προστησάμενοι τὸν ἐπιτηδειότατον ἐξ αὑτῶν ἤρξαντο περὶ σφῶν δικαιολογεῖσθαι.", "st": "3.20"}, {"sp": "N", "t": "τὰς μὲν οὖν πρὸς Ἀσδρούβαν ὁμολογίας παρεσιώπων, ὡς οὔτε γεγενημένας, εἴ τε γεγόνασιν, οὐδὲν οὔσας πρὸς αὑτοὺς διὰ τὸ χωρὶς τῆς σφετέρας πεπρᾶχθαι γνώμης. ἐχρῶντο δ’ ἐξ αὐτῶν Ῥωμαίων εἰς τοῦτο παραδείγματι. τὰς γὰρ ἐπὶ Λυτατίου γενομένας συνθήκας ἐν τῷ πολέμῳ τῷ περὶ Σικελίας, ταύτας ἔφασαν ἤδη συνωμολογημένας ὑπὸ Λυτατίου μετὰ ταῦτα τὸν δῆμον τῶν Ῥωμαίων ἀκύρους ποιῆσαι διὰ τὸ χωρὶς τῆς αὑτοῦ γενέσθαι γνώμης. ἐπίεζον δὲ καὶ προσαπηρείδοντο παρ’ ὅλην τὴν δικαιολογίαν ἐπὶ τὰς τελευταίας συνθήκας τὰς γενομένας ἐν τῷ περὶ Σικελίας πολέμῳ. ἐν αἷς περὶ μὲν Ἰβηρίας οὐκ ἔφασαν ὑπάρχειν ἔγγραφον οὐδέν, περὶ δὲ τοῦ τοῖς ἑκατέρων συμμάχοις τὴν παρ’ ἀμφοῖν ἀσφάλειαν εἶναι ῥητῶς κατατετάχθαι. Ζακανθαίους δὲ παρεδείκνυον οὐκ ὄντας τότε Ῥωμαίων συμμάχους καὶ παρανεγίνωσκον πρὸς τοῦτο πλεονάκις τὰς συνθήκας. Ῥωμαῖοι δὲ τοῦ μὲν δικαιολογεῖσθαι καθάπαξ ἀπεγίνωσκον, φάσκοντες ἀκεραίου μὲν ἔτι διαμενούσης τῆς τῶν Ζακανθαίων πόλεως ἐπιδέχεσθαι τὰ πράγματα δικαιολογίαν καὶ δυνατὸν εἶναι λόγῳ περὶ τῶν ἀμφισβητουμένων διεξάγειν· ταύτης δὲ παρεσπονδημένης ἢ τοὺς αἰτίους ἐκδοτέον εἶναι σφίσι, δι’ οὗ φανερὸν ἔσται πᾶσιν ὡς οὐ μετεσχήκασι τῆς ἀδικίας, ἀλλ’ ἄνευ τῆς αὑτῶν γνώμης πεπρᾶχθαι τοῦτο τοὔργον, ἢ μὴ βουλομένους τοῦτο ποιεῖν, ὁμολογοῦντας δὲ κοινωνεῖν τῆς ἀδικίας καὶ συναναδέχεσθαι τὸν πόλεμον. οἱ μὲν οὖν καθολικώτερόν πως ἐχρήσαντο τοῖς λόγοις. ἡμῖν δ’ ἀναγκαῖον εἶναι δοκεῖ τὸ μὴ παραλιπεῖν ἄσκεπτον τοῦτο τὸ μέρος, ἵνα μήθ’ οἷς καθήκει καὶ διαφέρει τὸ σαφῶς εἰδέναι τὴν ἐν τούτοις ἀκρίβειαν, παραπαίωσι τῆς ἀληθείας ἐν τοῖς ἀναγκαιοτάτοις διαβουλίοις, μήθ’ οἱ φιλομαθοῦντες περὶ τούτων ἀστοχῶσι, συμπλανώμενοι ταῖς ἀγνοίαις καὶ φιλοτιμίαις τῶν συγγραφέων, ἀλλ’ ᾖ τις ὁμολογουμένη θεωρία τῶν ἀπὸ τῆς ἀρχῆς ὑπαρξάντων δικαίων Ῥωμαίοις καὶ Καρχηδονίοις πρὸς ἀλλήλους ἕως εἰς τοὺς καθ’ ἡμᾶς καιρούς.", "st": "3.21"}, {"sp": "N", "t": "γίνονται τοιγαροῦν συνθῆκαι Ῥωμαίοις καὶ Καρχηδονίοις πρῶται κατὰ Λεύκιον Ἰούνιον Βροῦτον καὶ Μάρκον Ὡράτιον, τοὺς πρώτους κατασταθέντας ὑπάτους μετὰ τὴν τῶν βασιλέων κατάλυσιν, ὑφ’ ὧν συνέβη καθιερωθῆναι καὶ τὸ τοῦ Διὸς ἱερὸν τοῦ Καπετωλίου. ταῦτα δ’ ἔστι πρότερα τῆς Ξέρξου διαβάσεως εἰς τὴν Ἑλλάδα τριάκοντ’ ἔτεσι λείπουσι δυεῖν. ἃς καθ’ ὅσον ἦν δυνατὸν ἀκριβέστατα διερμηνεύσαντες ἡμεῖς ὑπογεγράφαμεν. τηλικαύτη γὰρ ἡ διαφορὰ γέγονε τῆς διαλέκτου καὶ παρὰ Ῥωμαίοις τῆς νῦν πρὸς τὴν ἀρχαίαν ὥστε τοὺς συνετωτάτους ἔνια μόλις ἐξ ἐπιστάσεως διευκρινεῖν. εἰσὶ δ’ αἱ συνθῆκαι τοιαίδε τινές· ‘ἐπὶ τοῖσδε φιλίαν εἶναι Ῥωμαίοις καὶ τοῖς Ῥωμαίων συμμάχοις καὶ Καρχηδονίοις καὶ τοῖς Καρχηδονίων συμμάχοις· μὴ πλεῖν Ῥωμαίους μηδὲ τοὺς Ῥωμαίων συμμάχους ἐπέκεινα τοῦ Καλοῦ ἀκρωτηρίου, ἐὰν μὴ ὑπὸ χειμῶνος ἢ πολεμίων ἀναγκασθῶσιν· ἐὰν δέ τις βίᾳ κατενεχθῇ, μὴ ἐξέστω αὐτῷ μηδὲν ἀγοράζειν μηδὲ λαμβάνειν πλὴν ὅσα πρὸς πλοίου ἐπισκευὴν ἢ πρὸς ἱερά, ἐν πέντε δ’ ἡμέραις ἀποτρεχέτω. τοῖς δὲ κατ’ ἐμπορίαν παραγινομένοις μηδὲν ἔστω τέλος πλὴν ἐπὶ κήρυκι ἢ γραμματεῖ. ὅσα δ’ ἂν τούτων παρόντων πραθῇ, δημοσίᾳ πίστει ὀφειλέσθω τῷ ἀποδομένῳ, ὅσα ἂν ἢ ἐν Λιβύῃ ἢ ἐν Σαρδόνι πραθῇ. ἐὰν Ῥωμαίων τις εἰς Σικελίαν παραγίνηται, ἧς Καρχηδόνιοι ἐπάρχουσιν, ἴσα ἔστω τὰ Ῥωμαίων πάντα. Καρχηδόνιοι δὲ μὴ ἀδικείτωσαν δῆμον Ἀρδεατῶν, Ἀντιατῶν, Λαρεντίνων, Κιρκαιιτῶν, Ταρρακινιτῶν, μηδ’ ἄλλον μηδένα Λατίνων, ὅσοι ἂν ὑπήκοοι· ἐὰν δέ τινες μὴ ὦσιν ὑπήκοοι, τῶν πόλεων ἀπεχέσθωσαν· ἂν δὲ λάβωσι, Ῥωμαίοις ἀποδιδότωσαν ἀκέραιον. φρούριον μὴ ἐνοικοδομείτωσαν ἐν τῇ Λατίνῃ. ἐὰν ὡς πολέμιοι εἰς τὴν χώραν εἰσέλθωσιν, ἐν τῇ χώρᾳ μὴ ἐννυκτερευέτωσαν.’", "st": "3.22"}, {"sp": "N", "t": "τὸ μὲν οὖν Καλὸν ἀκρωτήριόν ἐστι τὸ προκείμενον αὐτῆς τῆς Καρχηδόνος ὡς πρὸς τὰς ἄρκτους· οὗ καθάπαξ ἐπέκεινα πλεῖν ὡς πρὸς μεσημβρίαν οὐκ οἴονται δεῖν οἱ Καρχηδόνιοι τοὺς Ῥωμαίους μακραῖς ναυσὶ διὰ τὸ μὴ βούλεσθαι γινώσκειν αὐτούς, ὡς ἐμοὶ δοκεῖ, μήτε τοὺς κατὰ τὴν Βυσσάτιν μήτε τοὺς κατὰ τὴν μικρὰν Σύρτιν τόπους, ἃ δὴ καλοῦσιν Ἐμπόρια, διὰ τὴν ἀρετὴν τῆς χώρας. ἐὰν δέ τις ὑπὸ χειμῶνος ἢ πολεμίων βίᾳ κατενεχθεὶς δέηταί του τῶν ἀναγκαίων πρὸς ἱερὰ καὶ πρὸς ἐπισκευὴν πλοίου, ταῦτα, πάρεξ δὲ μηδὲν οἴονται δεῖν λαμβάνειν, καὶ κατ’ ἀνάγκην ἐν πένθ’ ἡμέραις ἀπαλλάττεσθαι τοὺς καθορμισθέντας. εἰς δὲ Καρχηδόνα καὶ πᾶσαν τὴν ἐπὶ τάδε τοῦ Καλοῦ ἀκρωτηρίου τῆς Λιβύης καὶ Σαρδόνα καὶ Σικελίαν, ἧς ἐπάρχουσι Καρχηδόνιοι, κατ’ ἐμπορίαν πλεῖν Ῥωμαίοις ἔξεστι, καὶ τὸ δίκαιον ὑπισχνοῦνται βεβαιώσειν οἱ Καρχηδόνιοι δημοσίᾳ πίστει. ἐκ δὲ τούτων τῶν συνθηκῶν περὶ μὲν Σαρδόνος καὶ Λιβύης ἐμφαίνουσιν ὡς περὶ ἰδίας ποιούμενοι τὸν λόγον· ὑπὲρ δὲ Σικελίας τἀναντία διαστέλλονται ῥητῶς, ὑπὲρ αὐτῶν τούτων ποιούμενοι τὰς συνθήκας, ὅσα τῆς Σικελίας ὑπὸ τὴν Καρχηδονίων πίπτει δυναστείαν. ὁμοίως δὲ καὶ Ῥωμαῖοι περὶ τῆς Λατίνης αὐτῆς χώρας ποιοῦνται τὰς συνθήκας, τῆς δὲ λοιπῆς Ἰταλίας οὐ μνημονεύουσι διὰ τὸ μὴ πίπτειν ὑπὸ τὴν αὐτῶν ἐξουσίαν.", "st": "3.23"}, {"sp": "N", "t": "μετὰ δὲ ταύτας ἑτέρας ποιοῦνται συνθήκας, ἐν αἷς προσπεριειλήφασι Καρχηδόνιοι Τυρίους καὶ τὸν Ἰτυκαίων δῆμον. πρόσκειται δὲ καὶ τῷ Καλῷ ἀκρωτηρίῳ Μαστία Ταρσήιον· ὧν ἐκτὸς οἴονται δεῖν Ῥωμαίους μήτε λῄζεσθαι μήτε πόλιν κτίζειν. εἰσὶ δὲ τοιαίδε τινές· ‘ἐπὶ τοῖσδε φιλίαν εἶναι Ῥωμαίοις καὶ τοῖς Ῥωμαίων συμμάχοις καὶ Καρχηδονίων καὶ Τυρίων καὶ Ἰτυκαίων δήμῳ καὶ τοῖς τούτων συμμάχοις. τοῦ Καλοῦ ἀκρωτηρίου, Μαστίας Ταρσηίου, μὴ λῄζεσθαι ἐπέκεινα Ῥωμαίους μηδ’ ἐμπορεύεσθαι μηδὲ πόλιν κτίζειν. ἐὰν δὲ Καρχηδόνιοι λάβωσιν ἐν τῇ Λατίνῃ πόλιν τινὰ μὴ οὖσαν ὑπήκοον Ῥωμαίοις, τὰ χρήματα καὶ τοὺς ἄνδρας ἐχέτωσαν, τὴν δὲ πόλιν ἀποδιδότωσαν. ἐὰν δέ τινες Καρχηδονίων λάβωσί τινας, πρὸς οὓς εἰρήνη μέν ἐστιν ἔγγραπτος Ῥωμαίοις, μὴ ὑποτάττονται δέ τι αὐτοῖς, μὴ καταγέτωσαν εἰς τοὺς Ῥωμαίων λιμένας· ἐὰν δὲ καταχθέντος ἐπιλάβηται ὁ Ῥωμαῖος, ἀφιέσθω. ὡσαύτως δὲ μηδ’ οἱ Ῥωμαῖοι ποιείτωσαν. ἂν ἔκ τινος χώρας, ἧς Καρχηδόνιοι ἐπάρχουσιν, ὕδωρ ἢ ἐφόδια λάβῃ ὁ Ῥωμαῖος, μετὰ τούτων τῶν ἐφοδίων μὴ ἀδικείτω μηδένα πρὸς οὓς εἰρήνη καὶ φιλία ἐστὶ Καρχηδονίοις. ὡσαύτως δὲ μηδ’ ὁ Καρχηδόνιος ποιείτω. εἰ δέ, μὴ ἰδίᾳ μεταπορευέσθω· ἐὰν δέ τις τοῦτο ποιήσῃ, δημόσιον γινέσθω τὸ ἀδίκημα. ἐν Σαρδόνι καὶ Λιβύῃ μηδεὶς Ῥωμαίων μήτ’ ἐμπορευέσθω μήτε πόλιν κτιζέτω, εἰ μὴ ἕως τοῦ ἐφόδια λαβεῖν ἢ πλοῖον ἐπισκευάσαι. ἐὰν δὲ χειμὼν κατενέγκῃ, ἐν πένθ’ ἡμέραις ἀποτρεχέτω. ἐν Σικελίᾳ ἧς Καρχηδόνιοι ἐπάρχουσι καὶ ἐν Καρχηδόνι πάντα καὶ ποιείτω καὶ πωλείτω ὅσα καὶ τῷ πολίτῃ ἔξεστιν. ὡσαύτως δὲ καὶ ὁ Καρχηδόνιος ποιείτω ἐν Ῥώμῃ.’ πάλιν ἐν ταύταις ταῖς συνθήκαις τὰ μὲν κατὰ Λιβύην καὶ Σαρδόνα προσεπιτείνουσιν ἐξιδιαζόμενοι καὶ πάσας ἀφαιρούμενοι τὰς ἐπιβάθρας Ῥωμαίων, περὶ δὲ Σικελίας τἀναντία προσδιασαφοῦσι, περὶ τῆς ὑπ’ αὐτοὺς ταττομένης. ὁμοίως δὲ καὶ Ῥωμαῖοι περὶ τῆς Λατίνης· οὐκ οἴονται δεῖν τοὺς Καρχηδονίους ἀδικεῖν Ἀρδεάτας, Ἀντιάτας, Κιρκαιίτας, Ταρρακινίτας. αὗται δ’ εἰσὶν αἱ πόλεις αἱ περιέχουσαι παρὰ θάλατταν τὴν Λατίνην χώραν, ὑπὲρ ἧς ποιοῦνται τὰς συνθήκας.", "st": "3.24"}, {"sp": "N", "t": "ἔτι τοιγαροῦν τελευταίας συνθήκας ποιοῦνται Ῥωμαῖοι κατὰ τὴν Πύρρου διάβασιν πρὸ τοῦ συστήσασθαι τοὺς Καρχηδονίους τὸν περὶ Σικελίας πόλεμον· ἐν αἷς τὰ μὲν ἄλλα τηροῦσι πάντα κατὰ τὰς ὑπαρχούσας ὁμολογίας, πρόσκειται δὲ τούτοις τὰ ὑπογεγραμμένα. ‘ἐὰν συμμαχίαν ποιῶνται πρὸς Πύρρον ἔγγραπτον, ποιείσθωσαν ἀμφότεροι, ἵνα ἐξῇ βοηθεῖν ἀλλήλοις ἐν τῇ τῶν πολεμουμένων χώρᾳ· ὁπότεροι δ’ ἂν χρείαν ἔχωσι τῆς βοηθείας, τὰ πλοῖα παρεχέτωσαν Καρχηδόνιοι καὶ εἰς τὴν ὁδὸν καὶ εἰς τὴν ἄφοδον, τὰ δὲ ὀψώνια τοῖς αὑτῶν ἑκάτεροι. Καρχηδόνιοι δὲ καὶ κατὰ θάλατταν Ῥωμαίοις βοηθείτωσαν, ἂν χρεία ᾖ. τὰ δὲ πληρώματα μηδεὶς ἀναγκαζέτω ἐκβαίνειν ἀκουσίως.’ τὸν δ’ ὅρκον ὀμνύειν ἔδει τοιοῦτον, ἐπὶ μὲν τῶν πρώτων συνθηκῶν Καρχηδονίους μὲν τοὺς θεοὺς τοὺς πατρῴους, Ῥωμαίους δὲ Δία λίθον κατά τι παλαιὸν ἔθος, ἐπὶ δὲ τούτων τὸν Ἄρην καὶ τὸν Ἐνυάλιον. ἔστι δὲ τὸ Δία λίθον τοιοῦτον· λαβὼν εἰς τὴν χεῖρα λίθον ὁ ποιούμενος τὰ ὅρκια περὶ τῶν συνθηκῶν, ἐπειδὰν ὀμόσῃ δημοσίᾳ πίστει, λέγει τάδε· ‘εὐορκοῦντι μέν μοι εἴη τἀγαθά· εἰ δ’ ἄλλως διανοηθείην τι ἢ πράξαιμι, πάντων τῶν ἄλλων σῳζομένων ἐν ταῖς ἰδίαις πατρίσιν, ἐν τοῖς ἰδίοις νόμοις, ἐπὶ τῶν ἰδίων βίων, ἱερῶν, τάφων, ἐγὼ μόνος ἐκπέσοιμι οὕτως ὡς ὅδε λίθος νῦν. ’ καὶ ταῦτ’ εἰπὼν ῥίπτει τὸν λίθον ἐκ τῆς χειρός.", "st": "3.25"}, {"sp": "N", "t": "τούτων δὴ τοιούτων ὑπαρχόντων, καὶ τηρουμένων τῶν συνθηκῶν ἔτι νῦν ἐν χαλκώμασι παρὰ τὸν Δία τὸν Καπετώλιον ἐν τῷ τῶν ἀγορανόμων ταμιείῳ, τίς οὐκ ἂν εἰκότως θαυμάσειεν Φιλίνου τοῦ συγγραφέως, οὐ διότι ταῦτ’ ἠγνόει — τοῦτο μὲν γὰρ οὐ θαυμαστόν, ἐπεὶ καθ’ ἡμᾶς ἔτι καὶ Ῥωμαίων καὶ Καρχηδονίων οἱ πρεσβύτατοι καὶ μάλιστα δοκοῦντες περὶ τὰ κοινὰ σπουδάζειν ἠγνόουν — ἀλλὰ πόθεν ἢ πῶς ἐθάρρησε γράψαι τἀναντία τούτοις, διότι Ῥωμαίοις καὶ Καρχηδονίοις ὑπάρχοιεν συνθῆκαι, καθ’ ἃς ἔδει Ῥωμαίους μὲν ἀπέχεσθαι Σικελίας ἁπάσης, Καρχηδονίους δ’ Ἰταλίας, καὶ διότι ὑπερέβαινον Ῥωμαῖοι τὰς συνθήκας καὶ τοὺς ὅρκους, ἐπεὶ ἐποιήσαντο τὴν πρώτην εἰς Σικελίαν διάβασιν, μήτε γεγονότος μήθ’ ὑπάρχοντος παράπαν ἐγγράφου τοιούτου μηδενός. ταῦτα γὰρ ἐν τῇ δευτέρᾳ λέγει βύβλῳ διαρρήδην. περὶ ὧν ἡμεῖς ἐν τῇ παρασκευῇ τῆς ἰδίας πραγματείας μνησθέντες εἰς τοῦτον ὑπερεθέμεθα τὸν καιρὸν κατὰ μέρος περὶ αὐτῶν ἐξεργάσασθαι διὰ τὸ καὶ πλείους διεψεῦσθαι τῆς ἀληθείας ἐν τούτοις, πιστεύσαντας τῇ Φιλίνου γραφῇ. οὐ μὴν ἀλλ’ εἰ κατὰ τοῦτό τις ἐπιλαμβάνεται Ῥωμαίων περὶ τῆς εἰς Σικελίαν διαβάσεως, ὅτι καθόλου Μαμερτίνους προσέλαβον εἰς τὴν φιλίαν καὶ μετὰ ταῦτα δεομένοις ἐβοήθησαν, οἵτινες οὐ μόνον τὴν Μεσσηνίων πόλιν ἀλλὰ καὶ τὴν Ῥηγίνων παρεσπόνδησαν, εἰκότως ἂν δόξειεν δυσαρεστεῖν. εἰ δὲ παρὰ τοὺς ὅρκους καὶ τὰς συνθήκας ὑπολαμβάνει τις αὐτοὺς πεποιῆσθαι τὴν διάβασιν, ἀγνοεῖ προφανῶς.", "st": "3.26"}, {"sp": "N", "t": "συντελεσθέντος τοίνυν τοῦ περὶ Σικελίας πολέμου ποιοῦνται συνθήκας ἄλλας, ἐν αἷς τὰ συνέχοντα τῶν ἐγγράπτων ἦν ταῦτα· ‘ἐκχωρεῖν Καρχηδονίους καὶ Σικελίας ἁπάσης καὶ τῶν νήσων ἁπασῶν τῶν κειμένων Ἰταλίας μεταξὺ καὶ Σικελίας. τὴν ἀσφάλειαν ὑπάρχειν παρ’ ἑκατέρων τοῖς ἑκατέρων συμμάχοις. μηδετέρους ἐν ταῖς ἀλλήλων ἐπαρχίαις μηδὲν ἐπιτάττειν μηδ’ οἰκοδομεῖν δημοσίᾳ μηδὲ ξενολογεῖν μηδὲ προσλαμβάνειν εἰς φιλίαν τοὺς ἀλλήλων συμμάχους. ἐξενεγκεῖν Καρχηδονίους ἐν ἔτεσιν δέκα δισχίλια καὶ διακόσια τάλαντα, παραυτίκα δὲ δοῦναι χίλια. τοὺς αἰχμαλώτους χωρὶς λύτρων ἀποδοῦναι πάντας Καρχηδονίους τοῖς Ῥωμαίοις.’ μετὰ δὲ ταῦτα πάλιν, λήξαντος τοῦ Λιβυκοῦ πολέμου, Ῥωμαῖοι Καρχηδονίοις πόλεμον ἐξενέγκαντες ἕως δόγματος ἐπισυνθήκας ἐποιήσαντο τοιαύτας· ‘ἐκχωρεῖν Καρχηδονίους Σαρδόνος καὶ προσεξενεγκεῖν ἄλλα χίλια καὶ διακόσια τάλαντα,’ καθάπερ ἐπάνω προείπαμεν. ἐπὶ δὲ τοῖς προειρημένοις τελευταῖαι πρὸς Ἀσδρούβαν ἐν Ἰβηρίᾳ γίνονται διομολογήσεις, ‘ἐφ’ ᾧ μὴ διαβαίνειν Καρχηδονίους ἐπὶ πολέμῳ τὸν Ἴβηρα ποταμόν.’ ταῦθ’ ὑπῆρχε τὰ δίκαια Ῥωμαίοις καὶ Καρχηδονίοις ἀπὸ τῆς ἀρχῆς ἕως εἰς τοὺς κατ’ Ἀννίβαν καιρούς.", "st": "3.27"}, {"sp": "N", "t": "ὥσπερ οὖν τὴν εἰς Σικελίαν διάβασιν Ῥωμαίων οὐ παρὰ τοὺς ὅρκους εὑρίσκομεν γεγενημένην, οὕτως ὑπὲρ τοῦ δευτέρου πολέμου, καθ’ ὃν ἐποιήσαντο τὰς περὶ Σαρδόνος συνθήκας, οὔτε πρόφασιν οὔτ’ αἰτίαν εὕροι τις ἂν εὔλογον, ἀλλ’ ὁμολογουμένως τοὺς Καρχηδονίους ἠναγκασμένους παρὰ πάντα τὰ δίκαια διὰ τὸν καιρὸν ἐκχωρῆσαι μὲν Σαρδόνος, ἐξενεγκεῖν δὲ τὸ προειρημένον πλῆθος τῶν χρημάτων. τὸ μὲν γὰρ ὑπὸ Ῥωμαίων περὶ τούτων λεγόμενον ἔγκλημα, διότι τοὺς παρὰ σφῶν πλοϊζομένους ἠδίκουν κατὰ τὸν Λιβυκὸν πόλεμον, ἐλύθη καθ’ οὓς καιροὺς κομισάμενοι παρὰ Καρχηδονίων ἅπαντας τοὺς κατηγμένους ἀντεδωρήσαντο χωρὶς λύτρων ἐν χάριτι τοὺς παρὰ σφίσιν ὑπάρχοντας αἰχμαλώτους. ὑπὲρ ὧν ἡμεῖς τὰ κατὰ μέρος ἐν τῇ πρὸ ταύτης βύβλῳ δεδηλώκαμεν. τούτων δὴ τοιούτων ὑπαρχόντων, λοιπὸν διευκρινῆσαι καὶ σκέψασθαι περὶ τοῦ κατ’ Ἀννίβαν πολέμου ποτέροις αὐτῶν τὴν αἰτίαν ἀναθετέον.", "st": "3.28"}, {"sp": "N", "t": "τὰ μὲν οὖν ὑπὸ Καρχηδονίων τότε ῥηθέντα δεδηλώκαμεν, τὰ δ’ ὑπὸ Ῥωμαίων λεγόμενα νῦν ἐροῦμεν· οἷς τότε μὲν οὐκ ἐχρήσαντο διὰ τὸν ἐπὶ τῇ Ζακανθαίων ἀπωλείᾳ θυμόν· λέγεται δὲ πολλάκις καὶ ὑπὸ πολλῶν παρ’ αὐτοῖς. πρῶτον μὲν ὅτι τὰς πρὸς Ἀσδρούβαν γενομένας ὁμολογίας οὐκ ἀθετητέον, καθάπερ οἱ Καρχηδόνιοι λέγειν ἐθάρρουν· οὐ γὰρ προσέκειτο, καθάπερ ἐπὶ τοῦ Λυτατίου, ‘κυρίας εἶναι ταύτας, ἐὰν καὶ τῷ δήμῳ δόξῃ τῶν Ῥωμαίων·’ ἀλλ’ αὐτοτελῶς ἐποιήσατο τὰς ὁμολογίας Ἀσδρούβας, ἐν αἷς ἦν, ‘τὸν Ἴβηρα ποταμὸν μὴ διαβαίνειν ἐπὶ πολέμῳ Καρχηδονίους.’ καὶ μὴν ἐν ταῖς περὶ Σικελίαν συνθήκαις ἦν ἔγγραπτον, καθάπερ κἀκεῖνοί φασιν, ‘ὑπάρχειν τοῖς ἀμφοτέρων συμμάχοις τὴν παρ’ ἑκατέρων ἀσφάλειαν,’ οὐκ αὐτοῖς μόνον τοῖς τότε συμμαχοῦσι, καθάπερ ἐποιοῦντο τὴν ἐκδοχὴν οἱ Καρχηδόνιοι· προσέκειτο γὰρ ἂν ἤτοι τὸ μὴ προσλαμβάνειν ἑτέρους συμμάχους παρὰ τοὺς ὑπάρχοντας ἢ τὸ μὴ παραλαμβάνεσθαι τοὺς ὕστερον προσληφθέντας τούτων τῶν συνθηκῶν. ὅτε δὲ τούτων οὐδέτερον ἐγράφη, προφανὲς ἦν ὅτι πᾶσι τοῖς ἑκατέρων συμμάχοις, καὶ τοῖς οὖσι τότε καὶ τοῖς μετὰ ταῦτα προσληφθησομένοις, τὴν παρ’ ἀμφοῖν ἀσφάλειαν ἀεὶ δέον ἦν ὑπάρχειν. ὃ δὴ καὶ πάντως ἂν εἰκὸς εἶναι δόξειεν. οὐ γὰρ δήπου τοιαύτας ἔμελλον ποιήσεσθαι συνθήκας δι’ ὧν ἀφελοῦνται τὴν ἐξουσίαν σφῶν αὐτῶν τοῦ προσλαμβάνειν κατὰ καιρούς, ἄν τινες ἐπιτήδειοι φανῶσιν αὐτοῖς φίλοι καὶ σύμμαχοι, οὐδὲ μὴν προσλαβόντες εἰς τὴν σφετέραν πίστιν περιόψεσθαι τούτους ὑπό τινων ἀδικουμένους· ἀλλ’ ἦν ἀμφοτέρων τὸ συνέχον τῆς ἐννοίας τῆς ἐν ταῖς συνθήκαις τῶν μὲν ὑπαρχόντων ἀμφοτέροις τότε συμμάχων ἀφέξεσθαι καὶ κατὰ μηδένα τρόπον τοὺς ἑτέρους παρὰ τῶν ἑτέρων ἐπιδέξεσθαί τινας τούτων εἰς συμμαχίαν, περὶ δὲ τῶν μετὰ ταῦτα προσληφθησομένων αὐτὸ τοῦτο, μήτε ξενολογεῖν μήτ’ ἐπιτάττειν μηδετέρους μηδὲν ἐν ταῖς ἀλλήλων ἐπαρχίαις καὶ συμμαχίαις, ὑπάρχειν τε τὴν ἀσφάλειαν πᾶσι τὴν παρ’ ἀμφοῖν.", "st": "3.29"}, {"sp": "N", "t": "τούτων δὴ τοιούτων ὑπαρχόντων, ὁμολογούμενον ἦν κἀκεῖνο διότι Ζακανθαῖοι πλείοσιν ἔτεσιν ἤδη πρότερον τῶν κατ’ Ἀννίβαν καιρῶν ἐδεδώκεισαν αὑτοὺς εἰς τὴν τῶν Ῥωμαίων πίστιν. σημεῖον δὲ τοῦτο μέγιστον καὶ παρ’ αὐτοῖς τοῖς Καρχηδονίοις ὁμολογούμενον ὅτι στασιάσαντες Ζακανθαῖοι πρὸς σφᾶς οὐ Καρχηδονίοις ἐπέτρεψαν, καίπερ ἐγγὺς ὄντων αὐτῶν καὶ τὰ κατὰ τὴν Ἰβηρίαν ἤδη πραττόντων, ἀλλὰ Ῥωμαίοις καὶ διὰ τούτων ἐποιήσαντο τὴν κατόρθωσιν τῆς πολιτείας. διόπερ εἰ μέν τις τὴν Ζακάνθης ἀπώλειαν αἰτίαν τίθησι τοῦ πολέμου, συγχωρητέον ἀδίκως ἐξενηνοχέναι τὸν πόλεμον Καρχηδονίους κατά τε τὰς ἐπὶ τοῦ Λυτατίου συνθήκας, καθ’ ἃς ἔδει τοῖς ἑκατέρων συμμάχοις τὴν ὑφ’ ἑκατέρων ὑπάρχειν ἀσφάλειαν, κατά τε τὰς ἐπ’ Ἀσδρούβου, καθ’ ἃς οὐκ ἔδει διαβαίνειν τὸν Ἴβηρα ποταμὸν ἐπὶ πολέμῳ Καρχηδονίους· εἰ δὲ τὴν Σαρδόνος ἀφαίρεσιν καὶ τὰ σὺν ταύτῃ χρήματα, πάντως ὁμολογητέον εὐλόγως πεπολεμηκέναι τὸν κατ’ Ἀννίβαν πόλεμον τοὺς Καρχηδονίους· καιρῷ γὰρ πεισθέντες ἠμύνοντο σὺν καιρῷ τοὺς βλάψαντας.", "st": "3.30"}, {"sp": "N", "t": "ἔνιοι δὲ τῶν ἀκρίτως τὰ τοιαῦτα θεωμένων τάχ’ ἂν φήσαιεν ἡμᾶς οὐκ ἀναγκαίως ἐπὶ πλεῖον ἐξακριβοῦν τοὺς ὑπὲρ τῶν τοιούτων λόγους. ἐγὼ δ’, εἰ μέν τις ὑπείληφεν πρὸς πᾶσαν περίστασιν αὐτάρκης ὑπάρχειν, καλὴν μέν, οὐκ ἀναγκαίαν δ’ ἴσως φήσαιμ’ ἂν εἶναι τὴν τῶν προγεγονότων ἐπιστήμην· εἰ δὲ μηδεὶς ἂν μήτε περὶ τῶν κατ’ ἰδίαν μήτε περὶ τῶν κοινῶν τολμήσαι τοῦτ’ εἰπεῖν ἄνθρωπος ὢν διὰ τό, κἂν κατὰ τὸ παρὸν εὐτυχῇ, τήν γε περὶ τοῦ μέλλοντος ἐλπίδα μηδὲν ἂν ἐκ τῶν νῦν παρόντων εὐλόγως βεβαιώσασθαι μηδένα τῶν νοῦν ἐχόντων, οὐ μόνον καλήν, ἔτι δὲ μᾶλλον ἀναγκαίαν εἶναί φημι διὰ ταῦτα τὴν τῶν παρεληλυθότων ἐπίγνωσιν. πῶς γὰρ ἂν εἴτ’ αὐτὸς ἀδικούμενός τις ἢ τῆς πατρίδος ἀδικουμένης βοηθοὺς εὕροι καὶ συμμάχους, εἴτε κτήσασθαί τι καὶ προκατάρξασθαι σπουδάζων τοὺς συνεργήσοντας αὐτῷ παρορμήσαι πρὸς τὰς ἐπιβολάς; πῶς δ’ ἂν εὐδοκούμενος τοῖς ὑποκειμένοις τοὺς βεβαιώσοντας τὴν αὐτοῦ προαίρεσιν καὶ διαφυλάξοντας τὴν κατάστασιν παροξύναι δικαίως, εἰ μηδὲν εἰδείη τῆς τῶν προγεγονότων περὶ ἑκάστους ὑπομνήσεως; πρὸς μὲν γὰρ τὸ παρὸν ἀεί πως ἁρμοζόμενοι καὶ συνυποκρινόμενοι τοιαῦτα καὶ λέγουσι καὶ πράττουσι πάντες ὥστε δυσθεώρητον εἶναι τὴν ἑκάστου προαίρεσιν καὶ λίαν ἐν πολλοῖς ἐπισκοτεῖσθαι τὴν ἀλήθειαν. τὰ δὲ παρεληλυθότα τῶν ἔργων, ἐξ αὐτῶν τῶν πραγμάτων λαμβάνοντα τὴν δοκιμασίαν, ἀληθινῶς ἐμφαίνει τὰς ἑκάστων αἱρέσεις καὶ διαλήψεις καὶ δηλοῖ παρ’ οἷς μὲν χάριν, εὐεργεσίαν, βοήθειαν ἡμῖν ὑπάρχουσαν, παρ’ οἷς δὲ τἀναντία τούτων. ἐξ ὧν καὶ τὸν ἐλεήσοντα καὶ τὸν συνοργιούμενον, ἔτι δὲ τὸν δικαιώσοντα, πολλάκις καὶ ἐπὶ πολλῶν εὑρεῖν ἔστιν. ἅπερ ἔχει μεγίστας ἐπικουρίας καὶ κοινῇ καὶ κατ’ ἰδίαν πρὸς τὸν ἀνθρώπινον βίον. διόπερ οὐχ οὕτως ἐστὶ φροντιστέον τῆς αὐτῶν τῶν πράξεων ἐξηγήσεως οὔτε τοῖς γράφουσιν οὔτε τοῖς ἀναγινώσκουσιν τὰς ἱστορίας, ὡς τῶν πρότερον καὶ τῶν ἅμα καὶ τῶν ἐπιγινομένων τοῖς ἔργοις. ἱστορίας γὰρ ἐὰν ἀφέλῃ τις τὸ διὰ τί καὶ πῶς καὶ τίνος χάριν ἐπράχθη τὸ πραχθὲν καὶ πότερον εὔλογον ἔσχε τὸ τέλος, τὸ καταλειπόμενον αὐτῆς ἀγώνισμα μὲν μάθημα δ’ οὐ γίνεται, καὶ παραυτίκα μὲν τέρπει, πρὸς δὲ τὸ μέλλον οὐδὲν ὠφελεῖ τὸ παράπαν.", "st": "3.31"}, {"sp": "N", "t": "ἧι καὶ τοὺς ὑπολαμβάνοντας δύσκτητον εἶναι καὶ δυσανάγνωστον τὴν ἡμετέραν πραγματείαν διὰ τὸ πλῆθος καὶ τὸ μέγεθος τῶν βύβλων ἀγνοεῖν νομιστέον. πόσῳ γὰρ ῥᾷόν ἐστι καὶ κτήσασθαι καὶ διαναγνῶναι βύβλους τετταράκοντα καθαπερανεὶ κατὰ μίτον ἐξυφασμένας καὶ παρακολουθῆσαι σαφῶς ταῖς μὲν κατὰ τὴν Ἰταλίαν καὶ Σικελίαν καὶ Λιβύην πράξεσιν ἀπὸ τῶν κατὰ Πύρρον [καὶ Τίμαιον συγγραφέων καὶ καιρῶν ἐξηγήσεως] εἰς τὴν Καρχηδόνος ἅλωσιν, ταῖς δὲ κατὰ τὴν ἄλλην οἰκουμένην ἀπὸ τῆς Κλεομένους τοῦ Σπαρτιάτου φυγῆς κατὰ τὸ συνεχὲς μέχρι τῆς Ἀχαιῶν καὶ Ῥωμαίων περὶ τὸν Ἰσθμὸν παρατάξεως, ἢ τὰς τῶν κατὰ μέρος γραφόντων συντάξεις ἀναγινώσκειν ἢ κτᾶσθαι; χωρὶς γὰρ τοῦ πολλαπλασίους αὐτὰς ὑπάρχειν τῶν ἡμετέρων ὑπομνημάτων, οὐδὲ καταλαβεῖν ἐξ αὐτῶν βεβαίως οὐδὲν οἷόν τε τοὺς ἀναγινώσκοντας, πρῶτον μὲν διὰ τὸ τοὺς πλείστους μὴ ταὐτὰ περὶ τῶν αὐτῶν γράφειν, εἶτα διὰ τὸ τὰς καταλλήλους τῶν πράξεων παραλείπειν, ὧν ἐκ παραθέσεως συνθεωρουμένων καὶ συγκρινομένων ἀλλοιοτέρας ἕκαστα τυγχάνει δοκιμασίας τῆς κατὰ μέρος διαλήψεως, τῶν δὲ κυριωτάτων μηδὲ ψαύειν αὐτοὺς δύνασθαι τὸ παράπαν. ἀκμὴν γάρ φαμεν ἀναγκαιότατα μέρη τῆς ἱστορίας εἶναι τά τ’ ἐπιγινόμενα τοῖς ἔργοις καὶ τὰ παρεπόμενα καὶ μάλιστα τὰ περὶ τὰς αἰτίας. θεωροῦμεν δὲ τὸν μὲν Ἀντιοχικὸν πόλεμον ἐκ τοῦ Φιλιππικοῦ τὰς ἀφορμὰς εἰληφότα, τὸν δὲ Φιλιππικὸν ἐκ τοῦ κατ’ Ἀννίβαν, τὸν δ’ Ἀννιβιακὸν ἐκ τοῦ περὶ Σικελίαν, τὰ δὲ μεταξὺ τούτων πολλὰς καὶ ποικίλας ἐσχηκότα διαθέσεις, πάσας δὲ συννευούσας πρὸς τὴν αὐτὴν ὑπόθεσιν. ταῦτα δὴ πάντα διὰ μὲν τῶν γραφόντων καθόλου δυνατὸν ἐπιγνῶναι καὶ μαθεῖν, διὰ δὲ τῶν τοὺς πολέμους αὐτούς, οἷον τὸν Περσικὸν ἢ τὸν Φιλιππικόν, ἀδύνατον, εἰ μὴ καὶ τὰς παρατάξεις τις ἀναγινώσκων αὐτὰς ἐξ ὧν ἐκεῖνοι γράφουσιν ὑπολαμβάνει σαφῶς ἐπεγνωκέναι καὶ τὴν τοῦ πολέμου τοῦ σύμπαντος οἰκονομίαν καὶ διάθεσιν. ἀλλ’ οὐκ ἔστι τούτων οὐδέν, ἀλλ’ ὅσῳ διαφέρει τὸ μαθεῖν τοῦ μόνον ἀκοῦσαι, τοσούτῳ καὶ τὴν ἡμετέραν ἱστορίαν ὑπολαμβάνω διαφέρειν τῶν ἐπὶ μέρους συντάξεων.", "st": "3.32"}, {"sp": "N", "t": "οἱ δὲ παρὰ τῶν Ῥωμαίων πρέσβεις — τὴν γὰρ παρέκβασιν ἐντεῦθεν ἐποιησάμεθα — διακούσαντες τὰ παρὰ τῶν Καρχηδονίων ἄλλο μὲν οὐδὲν εἶπαν, ὁ δὲ πρεσβύτατος αὐτῶν δείξας τοῖς ἐν τῷ συνεδρίῳ τὸν κόλπον ἐνταῦθα καὶ τὸν πόλεμον αὐτοῖς ἔφη καὶ τὴν εἰρήνην φέρειν· ἐκβαλὼν οὖν, ὁπότερον ἂν κελεύσωσιν, ἀπολείψειν. ὁ δὲ βασιλεὺς τῶν Καρχηδονίων, ὁπότερον αὐτοῖς φαίνεται, τοῦτ’ ἐκβαλεῖν ἐκέλευσε. τοῦ δὲ Ῥωμαίου φήσαντος τὸν πόλεμον ἐκβαλεῖν, ἀνεφώνησαν ἅμα καὶ πλείους τῶν ἐκ τοῦ συνεδρίου, δέχεσθαι φάσκοντες. οἱ μὲν οὖν πρέσβεις καὶ τὸ συνέδριον ἐπὶ τούτοις ἐχωρίσθησαν. Ἀννίβας δὲ παραχειμάζων ἐν Καινῇ πόλει πρῶτον μὲν διαφῆκε τοὺς Ἴβηρας ἐπὶ τὰς ἑαυτῶν πόλεις, βουλόμενος ἑτοίμους καὶ προθύμους παρασκευάζειν πρὸς τὸ μέλλον. δεύτερον δ’ Ἀσδρούβᾳ τἀδελφῷ διέταξε πῶς δεήσει τῇ τε τῶν Ἰβήρων ἀρχῇ καὶ δυναστείᾳ χρῆσθαι ταῖς τε πρὸς Ῥωμαίους παρασκευαῖς, ἐὰν αὐτὸς χωρίζηταί που. τρίτον ὑπὲρ τῆς ἀσφαλείας τῶν ἐν Λιβύῃ προυνοεῖτο πραγμάτων. πάνυ δ’ ἐμπείρως καὶ φρονίμως ἐκλογιζόμενος ἐκ μὲν Λιβύης εἰς Ἰβηρίαν, ἐκ δ’ Ἰβηρίας εἰς Λιβύην διεβίβαζε στρατιώτας, ἐκδεσμεύων τὴν ἑκατέρων πίστιν εἰς ἀλλήλους διὰ τῆς τοιαύτης οἰκονομίας. ἦσαν δ’ οἱ διαβάντες εἰς τὴν Λιβύην Θερσῖται, Μαστιανοί, πρὸς δὲ τούτοις Ὀρῆτες Ἴβηρες, Ὀλκάδες, οἱ δὲ σύμπαντες ἀπὸ τούτων τῶν ἐθνῶν ἱππεῖς μὲν χίλιοι διακόσιοι, πεζοὶ δὲ μύριοι τρισχίλιοι ὀκτακόσιοι πεντήκοντα, πρὸς δὲ τούτοις Βαλιαρεῖς ὀκτακόσιοι ἑβδομήκοντα, οὓς κυρίως μὲν καλοῦσι σφενδονήτας, ἀπὸ δὲ τῆς χρείας ταύτης συνωνύμως καὶ τὸ ἔθνος αὐτῶν προσαγορεύουσι καὶ τὴν νῆσον. τῶν δὲ προειρημένων τοὺς μὲν πλείους εἰς τὰ Μεταγώνια τῆς Λιβύης, τινὰς δ’ εἰς αὐτὴν Καρχηδόνα κατέταξεν. ἀπὸ δὲ τῶν πόλεων τῶν Μεταγωνιτῶν καλουμένων ἀπέστειλεν ἄλλους εἰς Καρχηδόνα πεζοὺς τετρακισχιλίους, ὁμηρείας ἔχοντας καὶ βοηθείας ἅμα τάξιν. ἐπὶ δὲ τῆς Ἰβηρίας ἀπέλιπεν Ἀσδρούβᾳ τἀδελφῷ πεντήρεις μὲν πεντήκοντα, τετρήρεις δὲ δύο καὶ τριήρεις πέντε· τούτων ἐχούσας πληρώματα πεντήρεις μὲν τριάκοντα δύο, τριήρεις δὲ πέντε. καὶ μὴν ἱππεῖς Λιβυφοινίκων μὲν καὶ Λιβύων τετρακοσίους πεντήκοντα, Λεργητῶν δὲ τριακοσίους, Νομάδων δὲ Μασυλίων καὶ Μασαισυλίων καὶ Μακκοίων καὶ Μαυρουσίων τῶν παρὰ τὸν Ὠκεανὸν χιλίους ὀκτακοσίους, πεζοὺς δὲ Λιβύων μυρίους χιλίους ὀκτακοσίους πεντήκοντα, Λιγυστίνους τριακοσίους, Βαλιαρεῖς πεντακοσίους, ἐλέφαντας εἴκοσι καὶ ἕνα. οὐ χρὴ δὲ θαυμάζειν τὴν ἀκρίβειαν τῆς ἀναγραφῆς, εἰ τοιαύτῃ κεχρήμεθα περὶ τῶν ὑπ’ Ἀννίβου κατ’ Ἰβηρίαν πεπραγμένων οἵᾳ μόλις ἂν χρήσαιτό τις αὐτὸς κεχειρικὼς τὰς κατὰ μέρος πράξεις, οὐδὲ προκαταγινώσκειν, εἰ πεποιήκαμεν παραπλήσιον τοῖς ἀξιοπίστως ψευδομένοις τῶν συγγραφέων. ἡμεῖς γὰρ εὑρόντες ἐπὶ Λακινίῳ τὴν γραφὴν ταύτην ἐν χαλκώματι κατατεταγμένην ὑπ’ Ἀννίβου, καθ’ οὓς καιροὺς ἐν τοῖς κατὰ τὴν Ἰταλίαν τόποις ἀνεστρέφετο, πάντως ἐνομίσαμεν αὐτὴν περί γε τῶν τοιούτων ἀξιόπιστον εἶναι· διὸ καὶ κατακολουθεῖν εἱλόμεθα τῇ γραφῇ ταύτῃ.", "st": "3.33"}, {"sp": "N", "t": "Ἀννίβας δὲ πάντα προνοηθεὶς περὶ τῆς ἀσφαλείας τῶν τε κατὰ Λιβύην πραγμάτων καὶ τῶν ἐν Ἰβηρίᾳ λοιπὸν ἐκαραδόκει καὶ προσεδέχετο τοὺς παρὰ τῶν Κελτῶν πρὸς αὐτὸν ἀποστελλομένους· σαφῶς γὰρ ἐξητάκει καὶ τὴν ἀρετὴν τῆς ὑπὸ τὰς Ἄλπεις καὶ περὶ τὸν Πάδον ποταμὸν χώρας καὶ τὸ πλῆθος τῶν κατοικούντων αὐτήν, ἔτι δὲ τὴν πρὸς τοὺς πολέμους τῶν ἀνδρῶν τόλμαν, καὶ τὸ μέγιστον, τὴν ὑπάρχουσαν δυσμένειαν αὐτοῖς ἐκ τοῦ προγεγονότος πολέμου πρὸς Ῥωμαίους, ὑπὲρ οὗ διήλθομεν ἡμεῖς ἐν τῇ πρὸ ταύτης βύβλῳ χάριν τοῦ συμπεριφέρεσθαι τοὺς ἐντυγχάνοντας τοῖς νῦν μέλλουσι λέγεσθαι. διόπερ εἴχετο ταύτης τῆς ἐλπίδος καὶ πᾶν ὑπισχνεῖτο, διαπεμπόμενος ἐπιμελῶς πρὸς τοὺς δυνάστας τῶν Κελτῶν καὶ τοὺς ἐπὶ τάδε καὶ τοὺς ἐν αὐταῖς ταῖς Ἄλπεσιν ἐνοικοῦντας, μόνως ἂν ὑπολαμβάνων ἐν Ἰταλίᾳ συστήσασθαι τὸν πρὸς Ῥωμαίους πόλεμον, εἰ δυνηθείη διαπεράσας τὰς πρὸ τοῦ δυσχωρίας εἰς τοὺς προειρημένους ἀφικέσθαι τόπους καὶ συνεργοῖς καὶ συμμάχοις χρήσασθαι Κελτοῖς εἰς τὴν προκειμένην ἐπιβολήν. ἀφικομένων δὲ τῶν ἀγγέλων καὶ τήν τε τῶν Κελτῶν βούλησιν καὶ προσδοκίαν ἀπαγγειλάντων τήν τε τῶν Ἀλπεινῶν ὀρῶν ὑπερβολὴν ἐπίπονον μὲν καὶ δυσχερῆ λίαν, οὐ μὴν ἀδύνατον εἶναι φασκόντων, συνῆγε τὰς δυνάμεις ἐκ τῆς παραχειμασίας ὑπὸ τὴν ἐαρινὴν ὥραν. προσπεπτωκότων δὲ προσφάτως αὐτῷ καὶ τῶν ἐκ τῆς Καρχηδόνος, ἐπαρθεὶς τῷ θυμῷ καὶ πιστεύων τῇ τῶν πολιτῶν εὐνοίᾳ παρεκάλει τὰς δυνάμεις φανερῶς ἤδη πρὸς τὸν κατὰ Ῥωμαίων πόλεμον, ἐμφανίζων μὲν ὃν τρόπον ἔκδοτον αὐτὸν ἐγχειρήσαιεν αἰτεῖσθαι Ῥωμαῖοι καὶ πάντας τοὺς τοῦ στρατοπέδου προεστῶτας, ὑποδεικνύων δὲ τὴν τῆς χώρας ἀρετήν, εἰς ἣν ἀφίξονται, καὶ τὴν τῶν Κελτῶν εὔνοιαν καὶ συμμαχίαν. εὐθύμως δὲ τῶν ὄχλων αὐτῷ συνεξισταμένων, ἐπαινέσας καὶ παραγγείλας τακτὴν ἡμέραν, ἐν ᾗ ποιήσεται τὴν ἔξοδον, τότε μὲν διέλυσε τὴν ἐκκλησίαν.", "st": "3.34"}, {"sp": "N", "t": "ἐπιτελέσας δὲ τὰ προειρημένα κατὰ τὴν παραχειμασίαν καὶ παρασκευάσας ἱκανὴν ἀσφάλειαν τοῖς τε κατὰ τὴν Λιβύην καὶ τοῖς ἐν Ἰβηρίᾳ πράγμασι, παραγενομένης τῆς ταχθείσης ἡμέρας, προῆγε, πεζῶν μὲν ἔχων εἰς ἐννέα μυριάδας, ἱππεῖς δὲ περὶ μυρίους καὶ δισχιλίους. καὶ διαβὰς τὸν Ἴβηρα ποταμὸν κατεστρέφετο τό τε τῶν Ἰλουργητῶν ἔθνος καὶ Βαργουσίων ἔτι δὲ τοὺς Αἰρηνοσίους καὶ τοὺς Ἀνδοσίνους μέχρι τῆς προσαγορευομένης Πυρήνης. ποιησάμενος δὲ πάντας ὑφ’ ἑαυτὸν καί τινας πόλεις κατὰ κράτος ἑλών, ταχέως μὲν καὶ παρ’ ἐλπίδα, μετὰ πολλῶν δὲ καὶ μεγάλων ἀγώνων ἔτι δὲ πολλῆς καταφθορᾶς ἀνδρῶν, ἡγεμόνα μὲν ἐπὶ πάσης κατέλιπε τῆς ἐπὶ τάδε τοῦ ποταμοῦ χώρας Ἄννωνα, τῶν δὲ Βαργουσίων καὶ δεσπότην· μάλιστα γὰρ τούτοις ἠπίστει διὰ τὴν πρὸς Ῥωμαίους εὔνοιαν. ἀπεμέρισε δὲ καὶ τῆς δυνάμεως ἧς εἶχε τῷ μὲν Ἄννωνι πεζοὺς μυρίους ἱππεῖς δὲ χιλίους καὶ τὰς ἀποσκευὰς ἀπέλιπε τούτῳ τῶν αὐτῷ συνεξορμώντων. εἰς δὲ τὴν οἰκείαν ἀπέλυσε τοὺς ἴσους τοῖς προειρημένοις, βουλόμενος αὐτούς τε τούτους εὔνους ἀπολιπεῖν, τοῖς τε λοιποῖς ὑποδεικνύων ἐλπίδα τῆς εἰς οἶκον ἐπανόδου καὶ τοῖς μεθ’ ἑαυτοῦ μὲν στρατευομένοις, οὐχ ἧττον δὲ καὶ τοῖς ἐν οἴκῳ μένουσι τῶν Ἰβήρων, ἵνα προθύμως ἐξορμῶσι πάντες, ἄν ποτέ τις ἐπικουρίας χρεία γένηται παρ’ αὐτῶν. τὴν δὲ λοιπὴν στρατιὰν ἀναλαβὼν εὔζωνον πεζοὺς μὲν πεντακισμυρίους ἱππεῖς δὲ πρὸς ἐννακισχιλίους ἦγεν διὰ τῶν Πυρηναίων λεγομένων ὀρῶν ἐπὶ τὴν τοῦ Ῥοδανοῦ καλουμένου ποταμοῦ διάβασιν, ἔχων οὐχ οὕτως πολλὴν δύναμιν ὡς χρησίμην καὶ γεγυμνασμένην διαφερόντως ἐκ τῆς συνεχείας τῶν κατὰ τὴν Ἰβηρίαν ἀγώνων.", "st": "3.35"}, {"sp": "N", "t": "ἵνα δὲ μὴ τῶν τόπων ἀγνοουμένων παντάπασιν ἀσαφῆ γίνεσθαι συμβαίνῃ τὴν διήγησιν, ῥητέον ἂν εἴη πόθεν ὁρμήσας Ἀννίβας καὶ τίνας καὶ πόσους διελθὼν τόπους εἰς ποῖα μέρη κατῆρε τῆς Ἰταλίας. ῥητέον δ’ οὐκ αὐτὰς τὰς ὀνομασίας τῶν τόπων καὶ ποταμῶν καὶ πόλεων, ὅπερ ἔνιοι ποιοῦσι τῶν συγγραφέων, ὑπολαμβάνοντες ἐν παντὶ πρὸς γνῶσιν καὶ σαφήνειαν αὐτοτελὲς εἶναι τοῦτο τὸ μέρος. οἶμαι δ’, ἐπὶ μὲν τῶν γνωριζομένων τόπων οὐ μικρὰ μεγάλα δὲ συμβάλλεσθαι πεποίηκε πρὸς ἀνάμνησιν ἡ τῶν ὀνομάτων παράθεσις· ἐπὶ δὲ τῶν ἀγνοουμένων εἰς τέλος ὁμοίαν ἔχει τὴν δύναμιν ἡ τῶν ὀνομάτων ἐξήγησις ταῖς ἀδιανοήτοις καὶ κρουσματικαῖς λέξεσι. τῆς γὰρ διανοίας ἐπ’ οὐδὲν ἀπερειδομένης οὐδὲ δυναμένης ἐφαρμόττειν τὸ λεγόμενον ἐπ’ οὐδὲν γνώριμον, ἀνυπότακτος καὶ κωφὴ γίνεθ’ ἡ διήγησις. διόπερ ὑποδεικτέος ἂν εἴη τρόπος, δι’ οὗ δυνατὸν ἔσται περὶ τῶν ἀγνοουμένων λέγοντας κατὰ ποσὸν εἰς ἀληθινὰς καὶ γνωρίμους ἐννοίας ἄγειν τοὺς ἀκούοντας. πρώτη μὲν οὖν καὶ μεγίστη γνῶσις, ἔτι δὲ κοινὴ πᾶσιν ἀνθρώποις ἐστὶν ἡ τοῦ περιέχοντος ἡμᾶς διαίρεσις καὶ τάξις, καθ’ ἣν πάντες, ὧν καὶ μικρὸν ὄφελος, ἀνατολάς, δύσεις, μεσημβρίαν, ἄρκτον γνωρίζομεν· δευτέρα δέ, καθ’ ἣν ἑκάστῃ διαφορᾷ τῶν προειρημένων τοὺς ἐπὶ τῆς γῆς τόπους ὑποτάττοντες καὶ φέροντες ἀεὶ τῇ διανοίᾳ τὸ λεγόμενον ἐπί τι τῶν προειρημένων εἰς γνωρίμους καὶ συνήθεις ἐπινοίας ἐμπίπτομεν ὑπὲρ τῶν ἀγνώστων καὶ ἀοράτων τόπων.", "st": "3.36"}, {"sp": "N", "t": "τούτων δὲ περὶ τῆς ὅλης γῆς ὑποκειμένων, ἀκόλουθον ἂν εἴη τὸ καὶ περὶ τῆς καθ’ ἡμᾶς οἰκουμένης ἀνὰ τὸν αὐτὸν λόγον διελομένους εἰς ἐπίστασιν ἀγαγεῖν τοὺς ἀκούοντας. ταύτης διῃρημένης εἰς τρία μέρη καὶ τρεῖς ὀνομασίας, τὸ μὲν ἓν μέρος αὐτῆς Ἀσίαν, τὸ δ’ ἕτερον Λιβύην, τὸ δὲ τρίτον Εὐρώπην προσαγορεύουσι. τὰς δὲ διαφορὰς ταύτας ὁρίζουσιν ὅ τε Τάναϊς ποταμὸς καὶ Νεῖλος καὶ τὸ καθ’ Ἡρακλέους στήλας στόμα. Νείλου μὲν οὖν καὶ Τανάιδος μεταξὺ τὴν Ἀσίαν κεῖσθαι συμβέβηκε, πίπτειν δὲ τοῦ περιέχοντος ὑπὸ τὸ μεταξὺ διάστημα θερινῶν ἀνατολῶν καὶ μεσημβρίας. ἡ δὲ Λιβύη κεῖται μὲν μεταξὺ Νείλου καὶ στηλῶν Ἡρακλείων, τοῦ δὲ περιέχοντος πέπτωκεν ὑπό τε τὴν μεσημβρίαν καὶ κατὰ τὸ συνεχὲς ὑπὸ τὰς χειμερινὰς δύσεις ἕως τῆς ἰσημερινῆς καταφορᾶς, ἣ πίπτει καθ’ Ἡρακλείους στήλας. αὗται μὲν οὖν αἱ χῶραι καθολικώτερον θεωρούμεναι τὸν πρὸς τὴν μεσημβρίαν τόπον ἐπέχουσι τῆς καθ’ ἡμᾶς θαλάττης ἀπὸ τῶν ἀνατολῶν ὡς πρὸς τὰς δύσεις. ἡ δ’ Εὐρώπη ταύταις ἀμφοτέραις ὡς πρὸς τὰς ἄρκτους ἀντιπαράκειται, κατὰ τὸ συνεχὲς ἀπὸ τῶν ἀνατολῶν παρήκουσα μὲν ἄχρι πρὸς τὰς δύσεις, κεῖται δ’ αὐτῆς τὸ μὲν ὁλοσχερέστερον καὶ βαθύτερον μέρος ὑπ’ αὐτὰς τὰς ἄρκτους μεταξὺ τοῦ τε Τανάιδος ποταμοῦ καὶ τοῦ Νάρβωνος, ὃς οὐ πολὺν ἀπέχει τόπον ὡς πρὸς δύσεις ἀπὸ Μασσαλίας καὶ τῶν τοῦ Ῥοδανοῦ στομάτων, δι’ ὧν εἰς τὸ Σαρδόνιον πέλαγος ἐξίησιν ὁ προειρημένος ποταμός. ἀπὸ δὲ τοῦ Νάρβωνος καὶ τὰ περὶ τοῦτον Κελτοὶ νέμονται μέχρι τῶν προσαγορευομένων Πυρηναίων ὀρῶν, ἃ διατείνει κατὰ τὸ συνεχὲς ἀπὸ τῆς καθ’ ἡμᾶς θαλάττης ἕως εἰς τὴν ἐκτός. τὸ δὲ λοιπὸν μέρος τῆς Εὐρώπης ἀπὸ τῶν προειρημένων ὀρῶν τὸ συνάπτον πρός τε τὰς δύσεις καὶ πρὸς Ἡρακλείους στήλας περιέχεται μὲν ὑπό τε τῆς καθ’ ἡμᾶς καὶ τῆς ἔξω θαλάττης, καλεῖται δὲ τὸ μὲν παρὰ τὴν καθ’ ἡμᾶς παρῆκον ἕως Ἡρακλείων στηλῶν Ἰβηρία, τὸ δὲ παρὰ τὴν ἔξω καὶ μεγάλην προσαγορευομένην κοινὴν μὲν ὀνομασίαν οὐκ ἔχει διὰ τὸ προσφάτως κατωπτεῦσθαι, κατοικεῖται δὲ πᾶν ὑπὸ βαρβάρων ἐθνῶν καὶ πολυανθρώπων, ὑπὲρ ὧν ἡμεῖς μετὰ ταῦτα τὸν κατὰ μέρος λόγον ἀποδώσομεν.", "st": "3.37"}, {"sp": "N", "t": "καθάπερ δὲ καὶ τῆς Ἀσίας καὶ τῆς Λιβύης, καθὸ συνάπτουσιν ἀλλήλαις περὶ τὴν Αἰθιοπίαν, οὐδεὶς ἔχει λέγειν ἀτρεκῶς ἕως τῶν καθ’ ἡμᾶς καιρῶν πότερον ἤπειρός ἐστι κατὰ τὸ συνεχὲς τὰ πρὸς τὴν μεσημβρίαν ἢ θαλάττῃ περιέχεται, τὸν αὐτὸν τρόπον τὸ μεταξὺ Τανάιδος καὶ Νάρβωνος εἰς τὰς ἄρκτους ἀνῆκον ἄγνωστον ἡμῖν ἕως τοῦ νῦν ἐστιν, ἐὰν μή τι μετὰ ταῦτα πολυπραγμονοῦντες ἱστορήσωμεν. τοὺς δὲ λέγοντάς τι περὶ τούτων ἄλλως ἢ γράφοντας ἀγνοεῖν καὶ μύθους διατιθέναι νομιστέον. ταῦτα μὲν οὖν εἰρήσθω μοι χάριν τοῦ μὴ τελέως ἀνυπότακτον εἶναι τοῖς ἀπείροις τῶν τόπων τὴν διήγησιν, ἀλλὰ κατά γε τὰς ὁλοσχερεῖς διαφορὰς συνεπιβάλλειν καὶ φέρειν ἐπί τι τῇ διανοίᾳ τὸ λεγόμενον, τεκμαιρομένους ἐκ τοῦ περιέχοντος. καθάπερ γὰρ ἐπὶ τῆς ὁράσεως εἰθίσμεθα συνεπιστρέφειν ἀεὶ τὰ πρόσωπα πρὸς τὸ κατὰ τὴν ἔνδειξιν ὑποδεικνύμενον, οὕτως καὶ τῇ διανοίᾳ χρὴ συνδιανεύειν καὶ συρρέπειν ἐπὶ τοὺς τόπους ἀεὶ τοὺς διὰ τοῦ λόγου συνεπιδεικνυμένους.", "st": "3.38"}, {"sp": "N", "t": "ἀφέμενοι δὲ τούτων τρεψόμεθα πρὸς τὸ συνεχὲς τῆς προκειμένης ἡμῖν διηγήσεως. Καρχηδόνιοι γὰρ ἐν τούτοις τοῖς καιροῖς τῆς μὲν Λιβύης ἐκυρίευον πάντων τῶν ἐπὶ τὴν ἔσω θάλατταν νευόντων μερῶν ἀπὸ τῶν Φιλαίνου βωμῶν, οἳ κεῖνται κατὰ τὴν μεγάλην Σύρτιν, ἕως ἐφ’ Ἡρακλέους στήλας. τοῦτο δὲ τὸ μῆκός ἐστι τῆς παραλίας ὑπὲρ τοὺς ἑξακισχιλίους καὶ μυρίους σταδίους. διαβάντες δὲ τὸν καθ’ Ἡρακλείους στήλας πόρον ὁμοίως ἐκεκρατήκεισαν καὶ τῆς Ἰβηρίας ἁπάσης ἕως τῆς ῥαχίας, ὃ πέρας ἐστὶ πρὸς τῇ καθ’ ἡμᾶς θαλάττῃ τῶν Πυρηναίων ὀρῶν, ἃ διορίζει τοὺς Ἴβηρας καὶ Κελτούς. ἀπέχει δὲ τοῦ καθ’ Ἡρακλείους στήλας στόματος οὗτος ὁ τόπος περὶ ὀκτακισχιλίους σταδίους. ἐπὶ μὲν γὰρ Καινὴν πόλιν ἀπὸ στηλῶν εἶναι συμβαίνει τρισχιλίους, ὅθεν ἐποιεῖτο τὴν ὁρμὴν Ἀννίβας τὴν εἰς Ἰταλίαν· [τὴν δὲ Καινὴν πόλιν ἔνιοι Νέαν Καρχηδόνα καλοῦσιν]· ἀπὸ δὲ ταύτης εἰσὶν ἐπὶ μὲν τὸν Ἴβηρα ποταμὸν ἑξακόσιοι στάδιοι πρὸς δισχιλίοις, ἀπὸ δὲ τούτου πάλιν εἰς Ἐμπόριον χίλιοι σὺν ἑξακοσίοις, ἀπὸ δ’ Ἐμπορίου πόλεως εἰς περὶ ἑξακοσίους, καὶ μὴν ἐντεῦθεν ἐπὶ τὴν τοῦ Ῥοδανοῦ διάβασιν περὶ χιλίους ἑξακοσίους· [ταῦτα γὰρ νῦν βεβημάτισται καὶ σεσημείωται κατὰ σταδίους ὀκτὼ διὰ Ῥωμαίων ἐπιμελῶς· ] ἀπὸ δὲ τῆς διαβάσεως τοῦ Ῥοδανοῦ πορευομένοις παρ’ αὐτὸν τὸν ποταμὸν ὡς ἐπὶ τὰς πηγὰς ἕως πρὸς τὴν ἀναβολὴν τῶν Ἄλπεων τὴν εἰς Ἰταλίαν χίλιοι τετρακόσιοι. λοιπαὶ δ’ αἱ τῶν Ἄλπεων ὑπερβολαί, περὶ χιλίους διακοσίους· ἃς ὑπερβαλὼν ἔμελλεν ἥξειν εἰς τὰ περὶ τὸν Πάδον πεδία τῆς Ἰταλίας. ὥστ’ εἶναι τοὺς πάντας ἐκ Καινῆς πόλεως σταδίους περὶ ἐννακισχιλίους, οὓς ἔδει διελθεῖν αὐτόν. τούτων δὴ τῶν τόπων κατὰ μὲν τὸ μῆκος ἤδη σχεδὸν τοὺς ἡμίσεις διεληλύθει, κατὰ δὲ τὴν δυσχέρειαν τὸ πλέον αὐτῷ μέρος ἀπελείπετο τῆς πορείας.", "st": "3.39"}, {"sp": "N", "t": "Ἀννίβας μὲν οὖν ἐνεχείρει ταῖς διεκβολαῖς τῶν Πυρηναίων ὀρῶν, κατάφοβος ὢν τοὺς Κελτοὺς διὰ τὰς ὀχυρότητας τῶν τόπων. Ῥωμαῖοι δὲ κατὰ τοὺς αὐτοὺς καιροὺς διακούσαντες μὲν τῶν ἐξαποσταλέντων εἰς Καρχηδόνα πρεσβευτῶν τὰ δεδογμένα καὶ τοὺς ῥηθέντας λόγους, προσπεσόντος δὲ θᾶττον ἢ προσεδόκων Ἀννίβαν διαβεβηκέναι τὸν Ἴβηρα ποταμὸν μετὰ τῆς δυνάμεως, προεχειρίσαντο πέμπειν μετὰ στρατοπέδων Πόπλιον μὲν Κορνήλιον εἰς Ἰβηρίαν, Τεβέριον δὲ Σεμπρώνιον εἰς Λιβύην. ἐν ὅσῳ δ’ οὗτοι περὶ τὰς καταγραφὰς ἐγίνοντο τῶν στρατοπέδων καὶ τὴν ἄλλην παρασκευήν, ἔσπευσαν ἐπὶ τέλος ἀγαγεῖν τὰ κατὰ τὰς ἀποικίας, οἳ δὴ πρότερον ἦσαν εἰς Γαλατίαν ἀποστέλλειν προκεχειρισμένοι. τὰς μὲν οὖν πόλεις ἐνεργῶς ἐτείχιζον, τοὺς δ’ οἰκήτορας ἐν ἡμέραις τριάκοντα παρήγγειλαν ἐπιτόπους γίνεσθαι, τὸν ἀριθμὸν ὄντας εἰς ἑκατέραν τὴν πόλιν εἰς ἑξακισχιλίους· ὧν τὴν μὲν μίαν ἔκτιζον ἐπὶ τάδε τοῦ Πάδου ποταμοῦ, προσαγορεύσαντες Πλακεντίαν, τὴν δ’ ἄλλην ἐπὶ θάτερα, κατονομάσαντες Κρεμώνην. ἤδη δὲ τούτων συνῳκισμένων, οἱ Βοῖοι καλούμενοι Γαλάται, πάλαι μὲν οἷον λοχῶντες τὴν πρὸς Ῥωμαίους φιλίαν, οὐκ ἔχοντες δὲ τότε καιρόν, μετεωριζόμενοι καὶ πιστεύοντες ἐκ τῶν διαπεμπομένων τῇ παρουσίᾳ τῶν Καρχηδονίων ἀπέστησαν ἀπὸ Ῥωμαίων, ἐγκαταλιπόντες τοὺς ὁμήρους, οὓς ἔδοσαν ἐκβαίνοντες ἐκ τοῦ πολέμου τοῦ προγεγονότος, ὑπὲρ οὗ τὴν ἐξήγησιν ἡμεῖς ἐν τῇ προτέρᾳ βύβλῳ ταύτης ἐποιησάμεθα. παρακαλέσαντες δὲ τοὺς Ἴνσομβρας καὶ συμφρονήσαντες κατὰ τὴν προγεγενημένην ὀργὴν κατέσυραν τὴν κατακεκληρουχημένην χώραν ὑπὸ Ῥωμαίων καὶ τοὺς φεύγοντας συνδιώξαντες εἰς Μοτίνην, ἀποικίαν ὑπάρχουσαν Ῥωμαίων, ἐπολιόρκουν. ἐν οἷς καὶ τρεῖς ἄνδρας τῶν ἐπιφανῶν συνέκλεισαν τοὺς ἐπὶ τὴν διαίρεσιν τῆς χώρας ἀπεσταλμένους· ὧν εἷς μὲν ἦν Γάιος Λυτάτιος ὁ τὴν ὕπατον ἀρχὴν εἰληφώς, οἱ δὲ δύο τὴν ἑξαπέλεκυν. οἰομένων δὲ δεῖν τούτων εἰς λόγους σφίσι συνελθεῖν, ὑπήκουσαν οἱ Βοῖοι. τῶν δ’ ἀνδρῶν ἐξελθόντων, παρασπονδήσαντες συνέλαβον αὐτούς, ἐλπίσαντες διὰ τούτων κομιεῖσθαι τοὺς αὑτῶν ὁμήρους. Λεύκιος δὲ Μάλιος ἑξαπέλεκυς ὑπάρχων καὶ προκαθήμενος ἐπὶ τῶν τόπων μετὰ δυνάμεως, ἀκούσας τὸ γεγονός, ἐβοήθει κατὰ σπουδήν. οἱ δὲ Βοῖοι συνέντες αὐτοῦ τὴν παρουσίαν, ἔν τισι δρυμοῖς ἑτοιμάσαντες ἐνέδρας ἅμα τῷ παρελθεῖν εἰς τοὺς ὑλώδεις τόπους πανταχόθεν ἅμα προσπεσόντες πολλοὺς ἀπέκτειναν τῶν Ῥωμαίων. οἱ δὲ λοιποὶ τὰς μὲν ἀρχὰς ὥρμησαν πρὸς φυγήν· ἐπεὶ δὲ τῶν ψιλῶν ἥψαντο χωρίων, ἐπὶ ποσὸν συνέστησαν οὕτως ὥστε μόλις εὐσχήμονα ποιήσασθαι τὴν ἀποχώρησιν. οἱ δὲ Βοῖοι κατακολουθήσαντες συνέκλεισαν καὶ τούτους εἰς τὴν Τάννητος καλουμένην κώμην. τοῖς δ’ ἐν τῇ Ῥώμῃ προσπεσόντος ὅτι τὸ τέταρτον στρατόπεδον περιειλημμένον ὑπὸ τῶν Βοίων πολιορκεῖται κατὰ κράτος, τὰ μὲν τῷ Ποπλίῳ προκεχειρισμένα στρατόπεδα κατὰ σπουδὴν ἐξαπέστελλον ἐπὶ τὴν τούτων βοήθειαν, ἡγεμόνα συστήσαντες ἑξαπέλεκυν, ἄλλα δὲ συνάγειν καὶ καταγράφειν ἐκ τῶν συμμάχων αὐτῷ παρήγγειλαν.", "st": "3.40"}, {"sp": "N", "t": "τὰ μὲν οὖν κατὰ Κελτοὺς ἀπὸ τῆς ἀρχῆς ἕως εἰς τὴν Ἀννίβου παρουσίαν ἐν τούτοις ἦν καὶ τοιαύτην εἰλήφει διέξοδον, οἵαν ἔν τε τοῖς πρὸ τοῦ καὶ νῦν διεληλύθαμεν. οἱ δὲ στρατηγοὶ τῶν Ῥωμαίων ἑτοιμασάμενοι τὰ πρὸς τὰς ἰδίας ἐπιβολάς, ἐξέπλεον ἐπὶ τὴν ὡραίαν ἐπὶ τὰς προκειμένας πράξεις, Πόπλιος μὲν οὖν εἰς Ἰβηρίαν ἑξήκοντα ναυσί, Τεβέριος δὲ Σεμπρώνιος εἰς Λιβύην ἑκατὸν ἑξήκοντα σκάφεσι πεντηρικοῖς. οἷς οὕτως καταπληκτικῶς ἐπεβάλετο πολεμεῖν καὶ τοιαύτας ἐποιεῖτο παρασκευὰς ἐν τῷ Λιλυβαίῳ, πάντας καὶ πανταχόθεν ἁθροίζων, ὡς εὐθέως ἐκ κατάπλου πολιορκήσων αὐτὴν τὴν Καρχηδόνα. Πόπλιος δὲ κομισθεὶς παρὰ τὴν Λιγυστίνην ἧκε πεμπταῖος ἀπὸ Πισῶν εἰς τοὺς κατὰ Μασσαλίαν τόπους, καὶ καθορμισθεὶς πρὸς τὸ πρῶτον στόμα τοῦ Ῥοδανοῦ, τὸ Μασσαλιωτικὸν προσαγορευόμενον, ἀπεβίβαζε τὰς δυνάμεις, ἀκούων μὲν ὑπερβάλλειν ἤδη τὰ Πυρηναῖα τὸν Ἀννίβαν ὄρη, πεπεισμένος δ’ ἔτι μακρὰν ἀπέχειν αὐτὸν διά τε τὰς δυσχωρίας τῶν τόπων καὶ διὰ τὸ πλῆθος τῶν μεταξὺ κειμένων Κελτῶν. Ἀννίβας δὲ παραδόξως τοὺς μὲν χρήμασι πείσας τῶν Κελτῶν τοὺς δὲ βιασάμενος ἧκε μετὰ τῶν δυνάμεων, δεξιὸν ἔχων τὸ Σαρδόνιον πέλαγος, ἐπὶ τὴν τοῦ Ῥοδανοῦ διάβασιν. ὁ δὲ Πόπλιος, διασαφηθέντος αὐτῷ παρεῖναι τοὺς ὑπεναντίους, τὰ μὲν ἀπιστῶν διὰ τὸ τάχος τῆς παρουσίας, τὰ δὲ βουλόμενος εἰδέναι τὴν ἀκρίβειαν, αὐτὸς μὲν ἀνελάμβανε τὰς δυνάμεις ἐκ τοῦ πλοῦ καὶ διενοεῖτο μετὰ τῶν χιλιάρχων ποίοις χρηστέον τῶν τόπων καὶ συμμικτέον τοῖς ὑπεναντίοις· τριακοσίους δὲ τῶν ἱππέων ἐξαπέστειλε τοὺς ἀνδρωδεστάτους, συστήσας μετ’ αὐτῶν καθηγεμόνας ἅμα καὶ συναγωνιστὰς Κελτούς, οἳ παρὰ τοῖς Μασσαλιώταις ἐτύγχανον μισθοφοροῦντες.", "st": "3.41"}, {"sp": "N", "t": "Ἀννίβας δὲ προσμίξας τοῖς περὶ τὸν ποταμὸν τόποις εὐθέως ἐνεχείρει ποιεῖσθαι τὴν διάβασιν κατὰ τὴν ἁπλῆν ῥύσιν, σχεδὸν ἡμερῶν τεττάρων ὁδὸν ἀπέχων στρατοπέδῳ τῆς θαλάττης. καὶ φιλοποιησάμενος παντὶ τρόπῳ τοὺς παροικοῦντας τὸν ποταμὸν ἐξηγόρασε παρ’ αὐτῶν τά τε μονόξυλα πλοῖα πάντα καὶ τοὺς λέμβους, ὄντας ἱκανοὺς τῷ πλήθει διὰ τὸ ταῖς ἐκ τῆς θαλάττης ἐμπορίαις πολλοὺς χρῆσθαι τῶν παροικούντων τὸν Ῥοδανόν. ἔτι δὲ τὴν ἁρμόζουσαν ξυλείαν ἐξέλαβε πρὸς τὴν κατασκευὴν τῶν μονοξύλων· ἐξ ὧν ἐν δυσὶν ἡμέραις πλῆθος ἀναρίθμητον ἐγένετο πορθμείων, ἑκάστου σπεύδοντος μὴ προσδεῖσθαι τοῦ πέλας, ἐν αὑτῷ δ’ ἔχειν τὰς τῆς διαβάσεως ἐλπίδας. κατὰ δὲ τὸν καιρὸν τοῦτον ἐν τῷ πέραν πλῆθος ἡθροίσθη βαρβάρων χάριν τοῦ κωλύειν τὴν τῶν Καρχηδονίων διάβασιν. εἰς οὓς ἀποβλέπων Ἀννίβας καὶ συλλογιζόμενος ἐκ τῶν παρόντων ὡς οὔτε διαβαίνειν μετὰ βίας δυνατὸν εἴη τοσούτων πολεμίων ἐφεστώτων, οὔτ’ ἐπιμένειν, μὴ πανταχόθεν προσδέξηται τοὺς ὑπεναντίους, ἐπιγενομένης τῆς τρίτης νυκτὸς ἐξαποστέλλει μέρος τι τῆς δυνάμεως, συστήσας καθηγεμόνας ἐγχωρίους, ἐπὶ δὲ πάντων Ἄννωνα τὸν Βοαμίλκου τοῦ βασιλέως. οἳ ποιησάμενοι τὴν πορείαν ἀντίοι τῷ ῥεύματι παρὰ τὸν ποταμὸν ἐπὶ διακόσια στάδια, παραγενόμενοι πρός τινα τόπον, ἐν ᾧ συνέβαινε περί τι χωρίον νησίζον περισχίζεσθαι τὸν ποταμόν, ἐνταῦθα κατέμειναν. ἐκ δὲ τῆς παρακειμένης ὕλης τὰ μὲν συμπηγνύντες τῶν ξύλων τὰ δὲ συνδεσμεύοντες ἐν ὀλίγῳ χρόνῳ πολλὰς ἥρμοσαν σχεδίας, ἀρκούσας τῇ χρείᾳ πρὸς τὸ παρόν· ἐφ’ αἷς διεκομίσθησαν ἀσφαλῶς οὐδενὸς κωλύοντος. καταλαβόμενοι δὲ τόπον ἐχυρὸν ἐκείνην μὲν τὴν ἡμέραν ἔμειναν ἀναπαύοντες σφᾶς ἐκ τῆς προγεγενημένης κακοπαθείας, ἅμα δὲ παρασκευαζόμενοι πρὸς τὴν ἐπιοῦσαν χρείαν κατὰ τὸ συντεταγμένον. καὶ μὴν Ἀννίβας τὸ παραπλήσιον ἐποίει περὶ τὰς μεθ’ ἑαυτοῦ καταλειφθείσας δυνάμεις. μάλιστα δ’ αὐτῷ παρεῖχε δυσχρηστίαν ἡ τῶν ἐλεφάντων διάβασις· οὗτοι δ’ ἦσαν ἑπτὰ καὶ τριάκοντα τὸν ἀριθμόν.", "st": "3.42"}, {"sp": "N", "t": "οὐ μὴν ἀλλ’ ἐπιγενομένης τῆς πέμπτης νυκτὸς οἱ μὲν προδιαβάντες ἐκ τοῦ πέραν ὑπὸ τὴν ἑωθινὴν προῆγον παρ’ αὐτὸν τὸν ποταμὸν ἐπὶ τοὺς ἀντίπερα βαρβάρους, ὁ δ’ Ἀννίβας ἑτοίμους ἔχων τοὺς στρατιώτας ἐπεῖχε τῇ διαβάσει, τοὺς μὲν λέμβους πεπληρωκὼς τῶν πελτοφόρων ἱππέων, τὰ δὲ μονόξυλα τῶν εὐκινητοτάτων πεζῶν. εἶχον δὲ τὴν μὲν ἐξ ὑπερδεξίου καὶ παρὰ τὸ ῥεῦμα τάξιν οἱ λέμβοι, τὴν δ’ ὑπὸ τούτους τὰ λεπτὰ τῶν πορθμείων, ἵνα τὸ πολὺ τῆς τοῦ ῥεύματος βίας ἀποδεχομένων τῶν λέμβων ἀσφαλεστέρα γίνοιτο τοῖς μονοξύλοις ἡ παρακομιδὴ διὰ τοῦ πόρου. κατὰ δὲ τὰς πρύμνας τῶν λέμβων ἐφέλκειν διενοοῦντο τοὺς ἵππους νέοντας, τρεῖς ἅμα καὶ τέτταρας τοῖς ἀγωγεῦσιν ἑνὸς ἀνδρὸς ἐξ ἑκατέρου τοῦ μέρους τῆς πρύμνης οἰακίζοντος, ὥστε πλῆθος ἱκανὸν ἵππων συνδιακομίζεσθαι κατὰ τὴν πρώτην εὐθέως διάβασιν. οἱ δὲ βάρβαροι θεωροῦντες τὴν ἐπιβολὴν τῶν ὑπεναντίων ἀτάκτως ἐκ τοῦ χάρακος ἐξεχέοντο καὶ σποράδην, πεπεισμένοι κωλύειν εὐχερῶς τὴν ἀπόβασιν τῶν Καρχηδονίων. Ἀννίβας δ’ ἅμα τῷ συνιδεῖν ἐν τῷ πέραν ἐγγίζοντας ἤδη τοὺς παρ’ αὑτοῦ στρατιώτας, σημηνάντων ἐκείνων τὴν παρουσίαν τῷ καπνῷ κατὰ τὸ συντεταγμένον, ἐμβαίνειν ἅπασιν ἅμα παρήγγελλε καὶ βιάζεσθαι πρὸς τὸ ῥεῦμα τοῖς ἐπὶ τῶν πορθμείων τεταγμένοις. ταχὺ δὲ τούτου γενομένου, καὶ τῶν ἐν τοῖς πλοίοις ἁμιλλωμένων μὲν πρὸς ἀλλήλους μετὰ κραυγῆς, διαγωνιζομένων δὲ πρὸς τὴν τοῦ ποταμοῦ βίαν, τῶν δὲ στρατοπέδων ἀμφοτέρων ἐξ ἑκατέρου τοῦ μέρους παρὰ τὰ χείλη τοῦ ποταμοῦ παρεστώτων, καὶ τῶν μὲν ἰδίων συναγωνιώντων καὶ παρακολουθούντων μετὰ κραυγῆς, τῶν δὲ κατὰ πρόσωπον βαρβάρων παιανιζόντων καὶ προκαλουμένων τὸν κίνδυνον, ἦν τὸ γινόμενον ἐκπληκτικὸν καὶ παραστατικὸν ἀγωνίας. ἐν ᾧ καιρῷ τῶν βαρβάρων ἀπολελοιπότων τὰς σκηνὰς ἐπιπεσόντες ἄφνω καὶ παραδόξως οἱ πέραν Καρχηδόνιοι, τινὲς μὲν αὐτῶν ἐνεπίμπρασαν τὴν στρατοπεδείαν, οἱ δὲ πλείους ὥρμησαν ἐπὶ τοὺς τὴν διάβασιν τηροῦντας. οἱ δὲ βάρβαροι, παραλόγου τοῦ πράγματος φανέντος αὐτοῖς, οἱ μὲν ἐπὶ τὰς σκηνὰς ἐφέροντο βοηθήσοντες, οἱ δ’ ἠμύνοντο καὶ διεμάχοντο πρὸς τοὺς ἐπιτιθεμένους. Ἀννίβας δέ, κατὰ τὴν πρόθεσιν αὐτῷ συντρεχόντων τῶν πραγμάτων, εὐθέως τοὺς πρώτους ἀποβαίνοντας συνίστα καὶ παρεκάλει καὶ συνεπλέκετο τοῖς βαρβάροις. οἱ δὲ Κελτοὶ καὶ διὰ τὴν ἀταξίαν καὶ διὰ τὸ παράδοξον τοῦ συμβαίνοντος ταχέως τραπέντες ὥρμησαν πρὸς φυγήν.", "st": "3.43"}, {"sp": "N", "t": "ὁ δὲ στρατηγὸς τῶν Καρχηδονίων ἅμα τῆς τε διαβάσεως καὶ τῶν ὑπεναντίων κεκρατηκὼς παραυτίκα μὲν ἐγίνετο πρὸς τῇ παρακομιδῇ τῶν πέραν ἀπολειπομένων ἀνδρῶν, πάσας δ’ ἐν βραχεῖ χρόνῳ διαπεραιώσας τὰς δυνάμεις ἐκείνην μὲν τὴν νύκτα παρ’ αὐτὸν τὸν ποταμὸν κατεστρατοπέδευσεν, τῇ δ’ ἐπαύριον ἀκούων τὸν τῶν Ῥωμαίων στόλον περὶ τὰ στόματα τοῦ ποταμοῦ καθωρμίσθαι, προχειρισάμενος πεντακοσίους τῶν Νομαδικῶν ἱππέων ἐξαπέστειλε κατασκεψομένους ποῦ καὶ πόσοι τυγχάνουσιν ὄντες καὶ τί πράττουσιν οἱ πολέμιοι. κατὰ δὲ τὸν αὐτὸν καιρὸν καὶ πρὸς τὴν τῶν ἐλεφάντων διάβασιν προεχειρίσατο τοὺς ἐπιτηδείους. αὐτὸς δὲ συναγαγὼν τὰς δυνάμεις εἰσήγαγε τοὺς βασιλίσκους τοὺς περὶ Μάγιλον — οὗτοι γὰρ ἧκον πρὸς αὐτὸν ἐκ τῶν περὶ τὸν Πάδον πεδίων — καὶ δι’ ἑρμηνέως τὰ δεδογμένα παρ’ αὐτῶν διεσάφει τοῖς ὄχλοις. ἦν δὲ τῶν λεγομένων ἰσχυρότατα πρὸς θάρσος τῶν πολλῶν πρῶτον μὲν ἡ τῆς παρουσίας ἐνάργεια τῶν ἐπισπωμένων καὶ κοινωνήσειν ἐπαγγελλομένων τοῦ πρὸς Ῥωμαίους πολέμου, δεύτερον δὲ τὸ τῆς ἐπαγγελίας αὐτῶν ἀξιόπιστον, ὅτι καθηγήσονται διὰ τόπων τοιούτων δι’ ὧν οὐδενὸς ἐπιδεόμενοι τῶν ἀναγκαίων συντόμως ἅμα καὶ μετ’ ἀσφαλείας ποιήσονται τὴν εἰς Ἰταλίαν πορείαν, πρὸς δὲ τούτοις ἡ τῆς χώρας γενναιότης, εἰς ἣν ἀφίξονται, καὶ τὸ μέγεθος, ἔτι δὲ τῶν ἀνδρῶν ἡ προθυμία, μεθ’ ὧν μέλλουσι ποιεῖσθαι τοὺς ἀγῶνας πρὸς τὰς τῶν Ῥωμαίων δυνάμεις. οἱ μὲν οὖν Κελτοὶ τοιαῦτα διαλεχθέντες ἀνεχώρησαν. μετὰ δὲ τούτους εἰσελθὼν αὐτὸς πρῶτον μὲν τῶν προγεγενημένων πράξεων ἀνέμνησε τοὺς ὄχλους· ἐν αἷς ἔφη πολλοῖς αὐτοὺς καὶ παραβόλοις ἔργοις καὶ κινδύνοις ἐπικεχειρηκότας ἐν οὐδενὶ διεσφάλθαι, κατακολουθήσαντας τῇ ’κείνου γνώμῃ καὶ συμβουλίᾳ. τούτοις δ’ ἑξῆς εὐθαρσεῖς εἶναι παρεκάλει, θεωροῦντας διότι τὸ μέγιστον ἤνυσται τῶν ἔργων, ἐπειδὴ τῆς τε τοῦ ποταμοῦ διαβάσεως κεκρατήκασι τῆς τε τῶν συμμάχων εὐνοίας καὶ προθυμίας αὐτόπται γεγόνασι. διόπερ ᾤετο δεῖν περὶ μὲν τῶν κατὰ μέρος ῥᾳθυμεῖν, ὡς αὐτῷ μελόντων, πειθαρχοῦντας δὲ τοῖς παραγγέλμασιν ἄνδρας ἀγαθοὺς γίνεσθαι καὶ τῶν προγεγονότων ἔργων ἀξίους. τοῦ δὲ πλήθους ἐπισημαινομένου καὶ μεγάλην ὁρμὴν καὶ προθυμίαν ἐμφαίνοντος, ἐπαινέσας αὐτοὺς καὶ τοῖς θεοῖς ὑπὲρ ἁπάντων εὐξάμενος διαφῆκε, παραγγείλας θεραπεύειν σφᾶς καὶ παρασκευάζεσθαι μετὰ σπουδῆς, ὡς εἰς τὴν αὔριον ἀναζυγῆς ἐσομένης.", "st": "3.44"}, {"sp": "N", "t": "λυθείσης δὲ τῆς ἐκκλησίας ἧκον τῶν Νομάδων οἱ προαποσταλέντες ἐπὶ τὴν κατασκοπήν, τοὺς μὲν πλείστους αὑτῶν ἀπολωλεκότες, οἱ δὲ λοιποὶ προτροπάδην πεφευγότες. συμπεσόντες γὰρ οὐ μακρὰν ἀπὸ τῆς ἰδίας στρατοπεδείας τοῖς τῶν Ῥωμαίων ἱππεῦσι τοῖς ἐπὶ τὴν αὐτὴν χρείαν ἐξαπεσταλμένοις ὑπὸ τοῦ Ποπλίου τοιαύτην ἐποιήσαντο φιλοτιμίαν ἀμφότεροι κατὰ τὴν συμπλοκὴν ὥστε τῶν Ῥωμαίων καὶ Κελτῶν εἰς ἑκατὸν ἱππεῖς καὶ τετταράκοντα διαφθαρῆναι, τῶν δὲ Νομάδων ὑπὲρ τοὺς διακοσίους. γενομένων δὲ τούτων οἱ Ῥωμαῖοι συνεγγίσαντες κατὰ τὸ δίωγμα τῷ τῶν Καρχηδονίων χάρακι καὶ κατοπτεύσαντες αὖθις ἐξ ὑποστροφῆς ἠπείγοντο, διασαφήσοντες τῷ στρατηγῷ τὴν παρουσίαν τῶν πολεμίων· ἀφικόμενοι δ’ εἰς τὴν παρεμβολὴν ἀνήγγειλαν. Πόπλιος δὲ παραυτίκα τὴν ἀποσκευὴν ἀναθέμενος ἐπὶ τὰς ναῦς ἀνέζευξε παντὶ τῷ στρατεύματι καὶ προῆγε παρὰ τὸν ποταμόν, σπεύδων συμμῖξαι τοῖς ὑπεναντίοις. Ἀννίβας δὲ τῇ κατὰ πόδας ἡμέρᾳ τῆς ἐκκλησίας ἅμα τῷ φωτὶ τοὺς μὲν ἱππεῖς προέθετο πάντας ὡς πρὸς θάλατταν, ἐφεδρείας ἔχοντας τάξιν, τὴν δὲ τῶν πεζῶν ἐκίνει δύναμιν ἐκ τοῦ χάρακος εἰς πορείαν. αὐτὸς δὲ τοὺς ἐλέφαντας ἐξεδέχετο καὶ τοὺς ἅμα τούτοις ἀπολελειμμένους ἄνδρας. ἐγένετο δ’ ἡ διακομιδὴ τῶν θηρίων τοιαύτη τις.", "st": "3.45"}, {"sp": "N", "t": "πήξαντες σχεδίας καὶ πλείους ἀραρότως, τούτων δύο πρὸς ἀλλήλας ζεύξαντες βιαίως ἤρεισαν ἀμφοτέρας εἰς τὴν γῆν κατὰ τὴν ἔμβασιν τοῦ ποταμοῦ, πλάτος ἐχούσας τὸ συναμφότερον ὡς πεντήκοντα πόδας. ταύταις δὲ συζευγνύντες ἄλλας ἐκ τῶν ἐκτὸς προσήρμοζον, προτείνοντες τὴν κατασκευὴν τοῦ ζεύγματος εἰς τὸν πόρον. τὴν δ’ ἀπὸ τοῦ ῥεύματος πλευρὰν ἠσφαλίζοντο τοῖς ἐκ τῆς γῆς ἐπιγύοις, εἰς τὰ περὶ τὸ χεῖλος πεφυκότα τῶν δένδρων ἐνάπτοντες, πρὸς τὸ συμμένειν καὶ μὴ παρωθεῖσθαι τὸ ὅλον ἔργον κατὰ τοῦ ποταμοῦ. ποιήσαντες δὲ πρὸς δύο πλέθρα τῷ μήκει τὸ πᾶν ζεῦγμα τῆς προβολῆς, μετὰ ταῦτα δύο πεπηγυίας σχεδίας διαφερόντως [τὰς μεγίστας] προσέβαλον ταῖς ἐσχάταις, πρὸς αὑτὰς μὲν βιαίως δεδεμένας, πρὸς δὲ τὰς ἄλλας οὕτως ὥστ’ εὐδιακόπους αὐτῶν εἶναι τοὺς δεσμούς. ῥύματα δὲ καὶ πλείω ταύταις ἐνῆψαν, οἷς ἔμελλον οἱ λέμβοι ῥυμουλκοῦντες οὐκ ἐάσειν φέρεσθαι κατὰ ποταμοῦ, βίᾳ δὲ πρὸς τὸν ῥοῦν κατέχοντες παρακομιεῖν καὶ περαιώσειν ἐπὶ τούτων τὰ θηρία. μετὰ δὲ ταῦτα χοῦν ἔφερον ἐπὶ πάσας πολύν, ἕως ἐπιβάλλοντες ἐξωμοίωσαν, ὁμαλὴν καὶ σύγχρουν ποιοῦντες τῇ διὰ τῆς χέρσου φερούσῃ πρὸς τὴν διάβασιν ὁδῷ. τῶν δὲ θηρίων εἰθισμένων τοῖς Ἰνδοῖς μέχρι μὲν πρὸς τὸ ὑγρὸν ἀεὶ πειθαρχεῖν, εἰς δὲ τὸ ὕδωρ ἐμβαίνειν οὐδαμῶς ἔτι τολμώντων, ἦγον διὰ τοῦ χώματος δύο προθέμενοι θηλείας, πειθαρχούντων αὐταῖς τῶν θηρίων. ἐπεὶ δ’ ἐπὶ τὰς τελευταίας ἐπέστησαν σχεδίας, διακόψαντες τοὺς δεσμούς, οἷς προσήρτηντο πρὸς τὰς ἄλλας, καὶ τοῖς λέμβοις ἐπισπασάμενοι τὰ ῥύματα ταχέως ἀπέσπασαν ἀπὸ τοῦ χώματος τά τε θηρία καὶ τὰς ὑπ’ αὐτοῖς σχεδίας. οὗ γενομένου διαταραχθέντα τὰ ζῷα κατὰ μὲν τὰς ἀρχὰς ἐστρέφετο καὶ κατὰ πάντα τόπον ὥρμα· περιεχόμενα δὲ πανταχόθεν ὑπὸ τοῦ ῥεύματος ἀπεδειλία καὶ μένειν ἠναγκάζετο κατὰ χώραν. καὶ τοιούτῳ δὴ τρόπῳ προσαρμοζομένων ἀεὶ σχεδιῶν δυεῖν, τὰ πλεῖστα τῶν θηρίων ἐπὶ τούτων διεκομίσθη, τινὰ δὲ κατὰ μέσον τὸν πόρον ἀπέρριψεν εἰς τὸν ποταμὸν αὑτὰ διὰ τὸν φόβον· ὧν τοὺς μὲν Ἰνδοὺς ἀπολέσθαι συνέβη πάντας, τοὺς δ’ ἐλέφαντας διασωθῆναι. διὰ γὰρ τὴν δύναμιν καὶ τὸ μέγεθος τῶν προβοσκίδων ἐξαίροντες ταύτας ὑπὲρ τὸ ὑγρὸν καὶ διαπνέοντες, ἅμα δ’ ἐκφυσῶντες πᾶν τὸ παρεμπῖπτον ἀντέσχον, τὸ πολὺ καθ’ ὕδατος ὀρθοὶ ποιούμενοι τὴν πορείαν.", "st": "3.46"}, {"sp": "N", "t": "περαιωθέντων δὲ τῶν θηρίων, ἀναλαβὼν Ἀννίβας τοὺς ἐλέφαντας καὶ τοὺς ἱππεῖς προῆγε τούτοις ἀπουραγῶν παρὰ τὸν ποταμὸν ἀπὸ θαλάττης ὡς ἐπὶ τὴν ἕω, ποιούμενος τὴν πορείαν ὡς εἰς τὴν μεσόγαιον τῆς Εὐρώπης. ὁ δὲ Ῥοδανὸς ἔχει τὰς μὲν πηγὰς ὑπὲρ τὸν Ἀδριατικὸν μυχὸν πρὸς τὴν ἑσπέραν νευούσας, ἐν τοῖς ἀποκλίνουσι μέρεσι τῶν Ἄλπεων ὡς πρὸς τὰς ἄρκτους, ῥεῖ δὲ πρὸς [τὰς] δύσεις χειμερινάς, ἐκβάλλει δ’ εἰς τὸ Σαρδῷον πέλαγος. φέρεται δ’ ἐπὶ πολὺ δι’ αὐλῶνος, οὗ πρὸς μὲν τὰς ἄρκτους Ἄρδυες Κελτοὶ κατοικοῦσι, τὴν δ’ ἀπὸ μεσημβρίας αὐτοῦ πλευρὰν ὁρίζουσι πᾶσαν αἱ πρὸς ἄρκτον κεκλιμέναι τῶν Ἄλπεων παρώρειαι. τὰ δὲ πεδία τὰ περὶ τὸν Πάδον, ὑπὲρ ὧν ἡμῖν εἴρηται διὰ πλειόνων, ἀπὸ τοῦ κατὰ τὸν Ῥοδανὸν αὐλῶνος διαζευγνύουσιν αἱ τῶν προειρημένων ὀρῶν ἀκρώρειαι, λαμβάνουσαι τὴν ἀρχὴν ἀπὸ Μασσαλίας ἕως ἐπὶ τὸν τοῦ παντὸς Ἀδρίου μυχόν· ἃς τόθ’ ὑπεράρας Ἀννίβας ἀπὸ τῶν κατὰ τὸν Ῥοδανὸν τόπων ἐνέβαλεν εἰς Ἰταλίαν. ἔνιοι δὲ τῶν γεγραφότων περὶ τῆς ὑπερβολῆς ταύτης, βουλόμενοι τοὺς ἀναγινώσκοντας ἐκπλήττειν τῇ περὶ τῶν προειρημένων τόπων παραδοξολογίᾳ, λανθάνουσιν ἐμπίπτοντες εἰς δύο τὰ πάσης ἱστορίας ἀλλοτριώτατα· καὶ γὰρ ψευδολογεῖν καὶ μαχόμενα γράφειν αὑτοῖς ἀναγκάζονται. ἅμα μὲν γὰρ τὸν Ἀννίβαν ἀμίμητόν τινα παρεισάγοντες στρατηγὸν καὶ τόλμῃ καὶ προνοίᾳ τοῦτον ὁμολογουμένως ἀποδεικνύουσιν ἡμῖν ἀλογιστότατον, ἅμα δὲ καταστροφὴν οὐ δυνάμενοι λαμβάνειν οὐδ’ ἔξοδον τοῦ ψεύδους θεοὺς καὶ θεῶν παῖδας εἰς πραγματικὴν ἱστορίαν παρεισάγουσιν. ὑποθέμενοι γὰρ τὰς ἐρυμνότητας καὶ τραχύτητας τῶν Ἀλπεινῶν ὀρῶν τοιαύτας ὥστε μὴ οἷον ἵππους καὶ στρατόπεδα, σὺν δὲ τούτοις ἐλέφαντας, ἀλλὰ μηδὲ πεζοὺς εὐζώνους εὐχερῶς ἂν διελθεῖν, ὁμοίως δὲ καὶ τὴν ἔρημον τοιαύτην τινὰ περὶ τοὺς τόπους ὑπογράψαντες ἡμῖν ὥστ’, εἰ μὴ θεὸς ἤ τις ἥρως ἀπαντήσας τοῖς περὶ τὸν Ἀννίβαν ὑπέδειξε τὰς ὁδούς, ἐξαπορήσαντας ἂν καταφθαρῆναι πάντας, ὁμολογουμένως ἐκ τούτων εἰς ἑκάτερον τῶν προειρημένων ἁμαρτημάτων ἐμπίπτουσι.", "st": "3.47"}, {"sp": "N", "t": "πρῶτον μὲν γὰρ ἂν τίς φανείη στρατηγὸς ἀλογιστότερος Ἀννίβου, τίς καὶ σκαιότερος ἡγεμών, ὃς τοσούτων ἡγούμενος δυνάμεων καὶ τὰς μεγίστας ἐλπίδας ἔχων ἐν τούτοις τοῦ κατορθώσειν τοῖς ὅλοις, οὔτε τὰς ὁδοὺς οὔτε τόπους, ὡς οὗτοί φασιν, οὔτε ποῦ πορεύεται τὸ παράπαν οὔτε πρὸς τίνας ἐγίνωσκε, τὸ δὲ πέρας, οὐδ’ εἰ καθόλου [τοὐναντίον] δυνατοῖς ἐπιβάλλεται πράγμασιν; ἀλλ’ ὅπερ οἱ τοῖς ὅλοις ἐπταικότες καὶ κατὰ πάντα τρόπον ἐξαποροῦντες οὐχ ὑπομένουσιν, ὥστ’ εἰς ἀπρονοήτους καθιέναι τόπους μετὰ δυνάμεως, τοῦτο περιτιθέασιν οἱ συγγραφεῖς Ἀννίβᾳ τῷ τὰς μεγίστας ἐλπίδας ἀκεραίους ἔχοντι περὶ τῶν καθ’ αὑτὸν πραγμάτων. ὁμοίως δὲ καὶ τὰ περὶ τῆς ἐρημίας, ἔτι δ’ ἐρυμνότητος καὶ δυσχωρίας τῶν τόπων ἔκδηλον ποιεῖ τὸ ψεῦδος αὐτῶν. οὐχ ἱστορήσαντες γὰρ ὅτι συμβαίνει τοὺς Κελτοὺς τοὺς παρὰ τὸν Ῥοδανὸν ποταμὸν οἰκοῦντας οὐχ ἅπαξ οὐδὲ δὶς πρὸ τῆς Ἀννίβου παρουσίας, οὐδὲ μὴν πάλαι προσφάτως δέ, μεγάλοις στρατοπέδοις ὑπερβάντας τὰς Ἄλπεις παρατετάχθαι μὲν Ῥωμαίοις, συνηγωνίσθαι δὲ Κελτοῖς τοῖς τὰ περὶ τὸν Πάδον πεδία κατοικοῦσι, καθάπερ ἡμεῖς ἐν τοῖς πρὸ τούτων ἐδηλώσαμεν, πρὸς δὲ τούτοις οὐκ εἰδότες ὅτι πλεῖστον ἀνθρώπων φῦλον κατ’ αὐτὰς οἰκεῖν συμβαίνει τὰς Ἄλπεις, ἀλλ’ ἀγνοοῦντες ἕκαστα τῶν εἰρημένων ἥρω τινά φασιν ἐπιφανέντα συνυποδεῖξαι τὰς ὁδοὺς αὐτοῖς. ἐξ ὧν εἰκότως ἐμπίπτουσιν εἰς τὸ παραπλήσιον τοῖς τραγῳδιογράφοις. καὶ γὰρ ἐκείνοις πᾶσιν αἱ καταστροφαὶ τῶν δραμάτων προσδέονται θεοῦ καὶ μηχανῆς διὰ τὸ τὰς πρώτας ὑποθέσεις ψευδεῖς καὶ παραλόγους λαμβάνειν, τούς τε συγγραφέας ἀνάγκη τὸ παραπλήσιον πάσχειν καὶ ποιεῖν ἥρωάς τε καὶ θεοὺς ἐπιφαινομένους, ἐπειδὰν τὰς ἀρχὰς ἀπιθάνους καὶ ψευδεῖς ὑποστήσωνται. πῶς γὰρ οἷόν τε παραλόγοις ἀρχαῖς εὔλογον ἐπιθεῖναι τέλος; Ἀννίβας γε μὴν οὐχ ὡς οὗτοι γράφουσιν, λίαν δὲ περὶ ταῦτα πραγματικῶς ἐχρῆτο ταῖς ἐπιβολαῖς. καὶ γὰρ τὴν τῆς χώρας ἀρετήν, εἰς ἣν ἐπεβάλετο καθιέναι, καὶ τὴν τῶν ὄχλων ἀλλοτριότητα πρὸς Ῥωμαίους ἐξητάκει σαφῶς, εἴς τε τὰς μεταξὺ δυσχωρίας ὁδηγοῖς καὶ καθηγεμόσιν ἐγχωρίοις ἐχρῆτο τοῖς τῶν αὐτῶν ἐλπίδων μέλλουσι κοινωνεῖν. ἡμεῖς δὲ περὶ τούτων εὐθαρσῶς ἀποφαινόμεθα διὰ τὸ περὶ τῶν πράξεων παρ’ αὐτῶν ἱστορηκέναι τῶν παρατετευχότων τοῖς καιροῖς, τοὺς δὲ τόπους κατωπτευκέναι καὶ τῇ διὰ τῶν Ἄλπεων αὐτοὶ κεχρῆσθαι πορείᾳ γνώσεως ἕνεκα καὶ θέας.", "st": "3.48"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ Πόπλιος μὲν ὁ τῶν Ῥωμαίων στρατηγὸς ἡμέραις ὕστερον τρισὶ τῆς ἀναζυγῆς τῆς τῶν Καρχηδονίων παραγενόμενος ἐπὶ τὴν τοῦ ποταμοῦ διάβασιν καὶ καταλαβὼν ὡρμηκότας τοὺς ὑπεναντίους ἐξενίσθη μὲν ὡς ἐνδέχεται μάλιστα, πεπεισμένος οὐδέποτ’ ἂν αὐτοὺς τολμῆσαι τῇδε ποιήσασθαι τὴν εἰς Ἰταλίαν πορείαν διὰ τὸ πλῆθος καὶ τὴν ἀθεσίαν τῶν κατοικούντων τοὺς τόπους βαρβάρων. θεωρῶν δὲ τετολμηκότας αὖθις ἐπὶ τὰς ναῦς ἠπείγετο καὶ παραγενόμενος ἐνεβίβαζε τὰς δυνάμεις. καὶ τὸν μὲν ἀδελφὸν ἐξέπεμπεν ἐπὶ τὰς ἐν Ἰβηρίᾳ πράξεις, αὐτὸς δὲ πάλιν ὑποστρέψας εἰς Ἰταλίαν ἐποιεῖτο τὸν πλοῦν, σπεύδων καταταχῆσαι τοὺς ὑπεναντίους διὰ Τυρρηνίας πρὸς τὴν τῶν Ἄλπεων ὑπερβολήν. Ἀννίβας δὲ ποιησάμενος ἑξῆς ἐπὶ τέτταρας ἡμέρας τὴν πορείαν ἀπὸ τῆς διαβάσεως ἧκε πρὸς τὴν καλουμένην Νῆσον, χώραν πολύοχλον καὶ σιτοφόρον, ἔχουσαν δὲ τὴν προσηγορίαν ἀπ’ αὐτοῦ τοῦ συμπτώματος. ᾗ μὲν γὰρ ὁ Ῥοδανός, ᾗ δ’ Ἰσάρας προσαγορευόμενος, ῥέοντες παρ’ ἑκατέραν τὴν πλευράν, ἀποκορυφοῦσιν αὐτῆς τὸ σχῆμα κατὰ τὴν πρὸς ἀλλήλους σύμπτωσιν. ἔστι δὲ παραπλησία τῷ μεγέθει καὶ τῷ σχήματι τῷ κατ’ Αἴγυπτον καλουμένῳ Δέλτα, πλὴν ἐκείνου μὲν θάλαττα τὴν μίαν πλευρὰν καὶ τὰς τῶν ποταμῶν ῥύσεις ἐπιζεύγνυσι, ταύτης δ’ ὄρη δυσπρόσοδα καὶ δυσέμβολα καὶ σχεδὸν ὡς εἰπεῖν ἀπρόσιτα. πρὸς ἣν ἀφικόμενος καὶ καταλαβὼν ἐν αὐτῇ δύ’ ἀδελφοὺς ὑπὲρ τῆς βασιλείας στασιάζοντας καὶ μετὰ στρατοπέδων ἀντικαθημένους ἀλλήλοις, ἐπισπωμένου τοῦ πρεσβυτέρου καὶ παρακαλοῦντος εἰς τὸ συμπρᾶξαι καὶ συμπεριποιῆσαι τὴν ἀρχὴν αὐτῷ, ὑπήκουσε, προδήλου σχεδὸν ὑπαρχούσης τῆς πρὸς τὸ παρὸν ἐσομένης αὐτῷ χρείας. διὸ καὶ συνεπιθέμενος καὶ συνεκβαλὼν τὸν ἕτερον πολλῆς ἐπικουρίας ἔτυχε παρὰ τοῦ κρατήσαντος· οὐ γὰρ μόνον σίτῳ καὶ τοῖς ἄλλοις ἐπιτηδείοις ἀφθόνως ἐχορήγησε τὸ στρατόπεδον, ἀλλὰ καὶ τῶν ὅπλων τὰ παλαιὰ καὶ τὰ πεπονηκότα πάντα διαλλάξας ἐκαινοποίησε πᾶσαν τὴν δύναμιν εὐκαίρως, ἔτι δὲ τοὺς πλείστους ἐσθῆτι καὶ πρὸς τούτοις ὑποδέσει κοσμήσας μεγάλην εὐχρηστίαν παρέσχετο πρὸς τὰς τῶν ὀρῶν ὑπερβολάς. τὸ δὲ μέγιστον, εὐλαβῶς διακειμένοις πρὸς τὴν διὰ τῶν Ἀλλοβρίγων καλουμένων Γαλατῶν πορείαν ἀπουραγήσας μετὰ τῆς σφετέρας δυνάμεως ἀσφαλῆ παρεσκεύασε τὴν δίοδον αὐτοῖς, ἕως ἤγγισαν τῇ τῶν Ἄλπεων ὑπερβολῇ.", "st": "3.49"}, {"sp": "N", "t": "Ἀννίβας δ’ ἐν ἡμέραις δέκα πορευθεὶς παρὰ τὸν ποταμὸν εἰς ὀκτακοσίους σταδίους ἤρξατο τῆς πρὸς τὰς Ἄλπεις ἀναβολῆς, καὶ συνέβη μεγίστοις αὐτὸν περιπεσεῖν κινδύνοις. ἕως μὲν γὰρ ἐν τοῖς ἐπιπέδοις ἦσαν, ἀπείχοντο πάντες αὐτῶν οἱ κατὰ μέρος ἡγεμόνες τῶν Ἀλλοβρίγων, τὰ μὲν τοὺς ἱππεῖς δεδιότες, τὰ δὲ τοὺς παραπέμποντας βαρβάρους· ἐπειδὴ δ’ ἐκεῖνοι μὲν εἰς τὴν οἰκείαν ἀπηλλάγησαν, οἱ δὲ περὶ τὸν Ἀννίβαν ἤρξαντο προάγειν εἰς τὰς δυσχωρίας, τότε συναθροίσαντες οἱ τῶν Ἀλλοβρίγων ἡγεμόνες ἱκανόν τι πλῆθος προκατελάβοντο τοὺς εὐκαίρους τόπους, δι’ ὧν ἔδει τοὺς περὶ τὸν Ἀννίβαν κατ’ ἀνάγκην ποιεῖσθαι τὴν ἀναβολήν. εἰ μὲν οὖν ἔκρυψαν τὴν ἐπίνοιαν, ὁλοσχερῶς ἂν διέφθειραν τὸ στράτευμα τῶν Καρχηδονίων· νῦν δὲ καταφανεῖς γενόμενοι μεγάλα μὲν καὶ τοὺς περὶ Ἀννίβαν ἔβλαψαν, οὐκ ἐλάττω δ’ ἑαυτούς. γνοὺς γὰρ ὁ στρατηγὸς τῶν Καρχηδονίων ὅτι προκατέχουσιν οἱ βάρβαροι τοὺς εὐκαίρους τόπους, αὐτὸς μὲν καταστρατοπεδεύσας πρὸς ταῖς ὑπερβολαῖς ἐπέμενε, προέπεμψε δέ τινας τῶν καθηγουμένων αὐτοῖς Γαλατῶν χάριν τοῦ κατασκέψασθαι τὴν τῶν ὑπεναντίων ἐπίνοιαν καὶ τὴν ὅλην ὑπόθεσιν. ὧν πραξάντων τὸ συνταχθέν, ἐπιγνοὺς ὁ στρατηγὸς ὅτι τὰς μὲν ἡμέρας ἐπιμελῶς παρευτακτοῦσι καὶ τηροῦσι τοὺς τόπους οἱ πολέμιοι, τὰς δὲ νύκτας εἴς τινα παρακειμένην πόλιν ἀπαλλάττονται, πρὸς ταύτην τὴν ὑπόθεσιν ἁρμοζόμενος συνεστήσατο πρᾶξιν τοιαύτην. ἀναλαβὼν τὴν δύναμιν προῆγεν ἐμφανῶς καὶ συνεγγίσας ταῖς δυσχωρίαις οὐ μακρὰν τῶν πολεμίων κατεστρατοπέδευσε. τῆς δὲ νυκτὸς ἐπιγενομένης, συντάξας τὰ πυρὰ καίειν, τὸ μὲν πλεῖον μέρος τῆς δυνάμεως αὐτοῦ κατέλιπε, τοὺς δ’ ἐπιτηδειοτάτους εὐζώνους ποιήσας διῆλθε τὰ στενὰ τὴν νύκτα καὶ κατέσχε τοὺς ὑπὸ τῶν πολεμίων προκαταληφθέντας τόπους, ἀποκεχωρηκότων τῶν βαρβάρων κατὰ τὴν συνήθειαν εἰς τὴν πόλιν.", "st": "3.50"}, {"sp": "N", "t": "οὗ συμβάντος καὶ τῆς ἡμέρας ἐπιγενομένης, οἱ βάρβαροι συνθεασάμενοι τὸ γεγονὸς τὰς μὲν ἀρχὰς ἀπέστησαν τῆς ἐπιβολῆς· μετὰ δὲ ταῦτα θεωροῦντες τὸ τῶν ὑποζυγίων πλῆθος καὶ τοὺς ἱππεῖς δυσχερῶς ἐκμηρυομένους καὶ μακρῶς τὰς δυσχωρίας, ἐξεκλήθησαν ὑπὸ τοῦ συμβαίνοντος ἐξάπτεσθαι τῆς πορείας. τούτου δὲ γενομένου, καὶ κατὰ πλείω μέρη προσπεσόντων τῶν βαρβάρων, οὐχ οὕτως ὑπὸ τῶν ἀνδρῶν ὡς ὑπὸ τῶν τόπων πολὺς ἐγίνετο φθόρος τῶν Καρχηδονίων, καὶ μάλιστα τῶν ἵππων καὶ τῶν ὑποζυγίων. οὔσης γὰρ οὐ μόνον στενῆς καὶ τραχείας τῆς προσβολῆς ἀλλὰ καὶ κρημνώδους, ἀπὸ παντὸς κινήματος καὶ πάσης ταραχῆς ἐφέρετο κατὰ τῶν κρημνῶν ὁμόσε τοῖς φορτίοις πολλὰ τῶν ὑποζυγίων. καὶ μάλιστα τὴν τοιαύτην ταραχὴν ἐποίουν οἱ τραυματιζόμενοι τῶν ἵππων· τούτων γὰρ οἱ μὲν ἀντίοι συμπίπτοντες τοῖς ὑποζυγίοις, ὁπότε διαπτοηθεῖεν ἐκ τῆς πληγῆς, οἱ δὲ κατὰ τὴν εἰς τοὔμπροσθεν ὁρμὴν ἐξωθοῦντες πᾶν τὸ παραπῖπτον ἐν ταῖς δυσχωρίαις, μεγάλην ἀπειργάζοντο ταραχήν. εἰς ἃ βλέπων Ἀννίβας καὶ συλλογιζόμενος ὡς οὐδὲ τοῖς διαφυγοῦσι τὸν κίνδυνον ἔστι σωτηρία τοῦ σκευοφόρου διαφθαρέντος, ἀναλαβὼν τοὺς προκατασχόντας τὴν νύκτα τὰς ὑπερβολὰς ὥρμησε παραβοηθήσων τοῖς τῇ πορείᾳ προλαβοῦσιν. οὗ γενομένου πολλοὶ μὲν τῶν πολεμίων ἀπώλλυντο διὰ τὸ ποιεῖσθαι τὴν ἔφοδον ἐξ ὑπερδεξίων τὸν Ἀννίβαν, οὐκ ἐλάττους δὲ καὶ τῶν ἰδίων· ὁ γὰρ κατὰ τὴν πορείαν θόρυβος ἐξ ἀμφοῖν ηὔξετο διὰ τὴν τῶν προειρημένων κραυγὴν καὶ συμπλοκήν. ἐπεὶ δὲ τοὺς μὲν πλείστους τῶν Ἀλλοβρίγων ἀπέκτεινε, τοὺς δὲ λοιποὺς τρεψάμενος ἠνάγκασε φυγεῖν εἰς τὴν οἰκείαν, τότε δὴ τὸ μὲν ἔτι περιλειπόμενον πλῆθος τῶν ὑποζυγίων καὶ τῶν ἵππων μόλις καὶ ταλαιπώρως διήνυε τὰς δυσχωρίας, αὐτὸς δὲ συναθροίσας ὅσους ἠδύνατο πλείστους ἐκ τοῦ κινδύνου προσέβαλε πρὸς τὴν πόλιν, ἐξ ἧς ἐποιήσαντο τὴν ὁρμὴν οἱ πολέμιοι. καταλαβὼν δὲ σχεδὸν ἔρημον διὰ τὸ πάντας ἐκκληθῆναι πρὸς τὰς ὠφελείας ἐγκρατὴς ἐγένετο τῆς πόλεως. ἐκ δὲ τούτου πολλὰ συνέβη τῶν χρησίμων αὐτῷ πρός τε τὸ παρὸν καὶ πρὸς τὸ μέλλον. παραυτίκα μὲν γὰρ ἐκομίσατο πλῆθος ἵππων καὶ ὑποζυγίων καὶ τῶν ἅμα τούτοις ἑαλωκότων ἀνδρῶν, εἰς δὲ τὸ μέλλον ἔσχε μὲν καὶ σίτου καὶ θρεμμάτων ἐπὶ δυεῖν καὶ τρισὶν ἡμέραις εὐπορίαν, τὸ δὲ συνέχον, φόβον ἐνειργάσατο τοῖς ἑξῆς πρὸς τὸ μὴ τολμᾶν αὐτῷ ῥᾳδίως ἐγχειρεῖν μηδένα τῶν παρακειμένων ταῖς ἀναβολαῖς.", "st": "3.51"}, {"sp": "N", "t": "τότε μὲν οὖν αὐτοῦ ποιησάμενος τὴν παρεμβολὴν καὶ μίαν ἐπιμείνας ἡμέραν αὖθις ὥρμα. ταῖς δ’ ἑξῆς μέχρι μέν τινος ἀσφαλῶς διῆγε τὴν στρατιάν· ἤδη δὲ τεταρταῖος ὢν αὖθις εἰς κινδύνους παρεγένετο μεγάλους. οἱ γὰρ περὶ τὴν δίοδον οἰκοῦντες συμφρονήσαντες ἐπὶ δόλῳ συνήντων αὐτῷ, θαλλοὺς ἔχοντες καὶ στεφάνους· τοῦτο γὰρ σχεδὸν πᾶσι τοῖς βαρβάροις ἐστὶ σύνθημα φιλίας, καθάπερ τὸ κηρύκειον τοῖς Ἕλλησιν. εὐλαβῶς δὲ διακείμενος πρὸς τὴν τοιαύτην πίστιν Ἀννίβας ἐξήτασε φιλοτίμως τὴν ἐπίνοιαν αὐτῶν καὶ τὴν ὅλην ἐπιβολήν. τῶν δὲ φασκόντων καλῶς εἰδέναι καὶ τὴν τῆς πόλεως ἅλωσιν καὶ τὴν τῶν ἐγχειρησάντων αὐτὸν ἀδικεῖν ἀπώλειαν, καὶ διασαφούντων ὅτι πάρεισι διὰ ταῦτα, βουλόμενοι μήτε ποιῆσαι μήτε παθεῖν μηδὲν δυσχερές, ὑπισχνουμένων δὲ καὶ δώσειν ἐξ αὑτῶν ὅμηρα, πολὺν μὲν χρόνον ηὐλαβεῖτο καὶ διηπίστει τοῖς λεγομένοις, συλλογιζόμενος δ’ Ἀννίβας ὡς δεξάμενος μὲν τὰ προτεινόμενα, τάχ’ ἂν ἴσως εὐλαβεστέρους καὶ πρᾳοτέρους ποιήσαι τοὺς παραγεγονότας, μὴ προσδεξάμενος δὲ προδήλους ἕξει πολεμίους αὐτούς, συγκατένευσε τοῖς λεγομένοις καὶ συνυπεκρίθη τίθεσθαι φιλίαν πρὸς αὐτούς. τῶν δὲ βαρβάρων τὰ ὅμηρα παραδόντων καὶ θρέμμασι χορηγούντων ἀφθόνως καὶ καθόλου διδόντων σφᾶς αὐτοὺς εἰς τὰς χεῖρας ἀπαρατηρήτως, ἐπὶ ποσὸν ἐπίστευσαν οἱ περὶ τὸν Ἀννίβαν, ὥστε καὶ καθηγεμόσιν αὐτοῖς χρῆσθαι πρὸς τὰς ἑξῆς δυσχωρίας. προπορευομένων δ’ αὐτῶν ἐπὶ δύ’ ἡμέραις, συναθροισθέντες οἱ προειρημένοι καὶ συνακολουθήσαντες ἐπιτίθενται, φάραγγά τινα δύσβατον καὶ κρημνώδη περαιουμένων αὐτῶν.", "st": "3.52"}, {"sp": "N", "t": "ἐν ᾧ καιρῷ πάντας ἄρδην ἀπολέσθαι συνέβη τοὺς περὶ τὸν Ἀννίβαν, εἰ μὴ δεδιότες ἀκμὴν ἐπὶ ποσὸν καὶ προορώμενοι τὸ μέλλον τὰ μὲν σκευοφόρα καὶ τοὺς ἱππεῖς εἶχον ἐν τῇ πρωτοπορείᾳ, τοὺς δ’ ὁπλίτας ἐπὶ τῆς οὐραγίας. τούτων δ’ ἐφεδρευόντων ἔλαττον συνέβη γενέσθαι τὸ πάθος· οὗτοι γὰρ ἔστεξαν τὴν ἐπιφορὰν τῶν βαρβάρων. οὐ μὴν ἀλλὰ καὶ τούτου συγκυρήσαντος πολύ τι πλῆθος καὶ τῶν ἀνδρῶν καὶ τῶν ὑποζυγίων καὶ τῶν ἵππων διεφθάρη. τῶν γὰρ τόπων ὑπερδεξίων ὄντων τοῖς πολεμίοις, ἀντιπαράγοντες οἱ βάρβαροι ταῖς παρωρείαις καὶ τοῖς μὲν τὰς πέτρας ἐπικυλίοντες τοὺς δ’ ἐκ χειρὸς τοῖς λίθοις τύπτοντες εἰς ὁλοσχερῆ διατροπὴν καὶ κίνδυνον ἦγον, οὕτως ὥστ’ ἀναγκασθῆναι τὸν Ἀννίβαν μετὰ τῆς ἡμισείας δυνάμεως νυκτερεῦσαι περί τι λευκόπετρον ὀχυρὸν χωρὶς τῶν ἵππων καὶ τῶν ὑποζυγίων, ἐφεδρεύοντα τούτοις, ἕως ἐν ὅλῃ τῇ νυκτὶ ταῦτα μόλις ἐξεμηρύσατο τῆς χαράδρας. τῇ δ’ ἐπαύριον τῶν πολεμίων χωρισθέντων, συνάψας τοῖς ἱππεῦσι καὶ τοῖς ὑποζυγίοις προῆγε πρὸς τὰς ὑπερβολὰς τὰς ἀνωτάτω τῶν Ἄλπεων, ὁλοσχερεῖ μὲν οὐδενὶ περιπίπτων ἔτι συστήματι τῶν βαρβάρων, κατὰ μέρη δὲ καὶ κατὰ τόπους παρενοχλούμενος ὑπ’ αὐτῶν· ὧν οἱ μὲν ἀπὸ τῆς οὐραγίας, οἱ δ’ ἀπὸ τῆς πρωτοπορείας ἀπέσπων τῶν σκευοφόρων ἔνια, προσπίπτοντες εὐκαίρως. μεγίστην δ’ αὐτῷ παρείχετο χρείαν τὰ θηρία· καθ’ ὃν γὰρ ἂν τόπον ὑπάρχοι τῆς πορείας ταῦτα, πρὸς τοῦτο τὸ μέρος οὐκ ἐτόλμων οἱ πολέμιοι προσιέναι, τὸ παράδοξον ἐκπληττόμενοι τῆς τῶν ζῴων φαντασίας. ἐναταῖος δὲ διανύσας εἰς τὰς ὑπερβολὰς αὐτοῦ κατεστρατοπέδευσε καὶ δύ’ ἡμέρας προσέμεινε, βουλόμενος ἅμα μὲν ἀναπαῦσαι τοὺς διασῳζομένους, ἅμα δὲ προσδέξασθαι τοὺς ἀπολειπομένους. ἐν ᾧ καιρῷ συνέβη πολλοὺς μὲν ἵππους τῶν ἀπεπτοημένων, πολλὰ δ’ ὑποζύγια τῶν ἀπερριφότων τὰ φορτία παραδόξως ἀναδραμεῖν τοῖς στίβοις ἑπόμενα καὶ συνάψαι πρὸς τὴν παρεμβολήν.", "st": "3.53"}, {"sp": "N", "t": "τῆς δὲ χιόνος ἤδη περὶ τοὺς ἄκρους ἁθροιζομένης διὰ τὸ συνάπτειν τὴν τῆς Πλειάδος δύσιν, θεωρῶν τὰ πλήθη δυσθύμως διακείμενα καὶ διὰ τὴν προγεγενημένην ταλαιπωρίαν καὶ διὰ τὴν ἔτι προσδοκωμένην, ἐπειρᾶτο συναθροίσας παρακαλεῖν, μίαν ἔχων ἀφορμὴν εἰς τοῦτο τὴν τῆς Ἰταλίας ἐνάργειαν· οὕτως γὰρ ὑποπεπτώκει τοῖς προειρημένοις ὄρεσιν ὥστε συνθεωρουμένων ἀμφοῖν ἀκροπόλεως φαίνεσθαι διάθεσιν ἔχειν τὰς Ἄλπεις τῆς ὅλης Ἰταλίας. διόπερ ἐνδεικνύμενος αὐτοῖς τὰ περὶ τὸν Πάδον πεδία καὶ καθόλου τῆς εὐνοίας ὑπομιμνήσκων τῆς τῶν κατοικούντων αὐτὰ Γαλατῶν, ἅμα δὲ καὶ τὸν τῆς Ῥώμης αὐτῆς τόπον ὑποδεικνύων ἐπὶ ποσὸν εὐθαρσεῖς ἐποίησε τοὺς ἀνθρώπους. τῇ δ’ ἐπαύριον ἀναζεύξας ἐνήρχετο τῆς καταβάσεως. ἐν ᾗ πολεμίοις μὲν οὐκέτι περιέτυχε πλὴν τῶν λάθρᾳ κακοποιούντων, ὑπὸ δὲ τῶν τόπων καὶ τῆς χιόνος οὐ πολλῷ λείποντας ἀπέβαλε τῶν κατὰ τὴν ἀνάβασιν φθαρέντων. οὔσης γὰρ στενῆς καὶ κατωφεροῦς τῆς καταβάσεως, τῆς δὲ χιόνος ἄδηλον ποιούσης ἑκάστοις τὴν ἐπίβασιν, πᾶν τὸ παραπεσὸν τῆς ὁδοῦ καὶ σφαλὲν ἐφέρετο κατὰ τῶν κρημνῶν. οὐ μὴν ἀλλὰ ταύτην μὲν ὑπέφερον τὴν ταλαιπωρίαν, ἅτε συνήθεις ὄντες ἤδη τοῖς τοιούτοις κακοῖς· ἅμα δὲ τῷ παραγενέσθαι πρὸς τοιοῦτον τόπον, ὃν οὔτε τοῖς θηρίοις οὔτε τοῖς ὑποζυγίοις δυνατὸν ἦν παρελθεῖν διὰ τὴν στενότητα, σχεδὸν ἐπὶ τρί’ ἡμιστάδια τῆς ἀπορρῶγος καὶ πρὸ τοῦ μὲν οὔσης, τότε δὲ καὶ μᾶλλον ἔτι προσφάτως ἀπερρωγυίας, ἐνταῦθα πάλιν ἀθυμῆσαι καὶ διατραπῆναι συνέβη τὸ πλῆθος. τὸ μὲν οὖν πρῶτον ἐπεβάλετο περιελθεῖν τὰς δυσχωρίας ὁ τῶν Καρχηδονίων στρατηγός· ἐπιγενομένης δὲ χιόνος καὶ ταύτην ἀδύνατον ποιούσης τὴν πορείαν, ἀπέστη τῆς ἐπιβολῆς.", "st": "3.54"}, {"sp": "N", "t": "τὸ γὰρ συμβαῖνον ἴδιον ἦν καὶ παρηλλαγμένον. ἐπὶ γὰρ τὴν προϋπάρχουσαν χιόνα καὶ διαμεμενηκυῖαν ἐκ τοῦ πρότερον χειμῶνος ἄρτι τῆς ἐπ’ ἔτους πεπτωκυίας, ταύτην μὲν εὐδιάκοπτον εἶναι συνέβαινε καὶ διὰ τὸ πρόσφατον οὖσαν ἁπαλὴν ὑπάρχειν καὶ διὰ τὸ μηδέπω βάθος ἔχειν. ὁπότε δὲ ταύτην διαπατήσαντες ἐπὶ τὴν ὑποκάτω καὶ συνεστηκυῖαν ἐπιβαῖεν, οὐκέτι διέκοπτον, ἀλλ’ ἐπέπλεον ὀλισθάνοντες ἀμφοτέροις ἅμα τοῖς ποσί, καθάπερ ἐπὶ τῇ γῇ συμβαίνει τοῖς διὰ τῶν ἀκροπήλων πορευομένοις. τὸ δὲ συνεξακολουθοῦν τούτοις ἔτι δυσχερέστερον ὑπῆρχεν. οἱ μὲν γὰρ ἄνδρες οὐ δυνάμενοι τὴν κάτω χιόνα διακόπτειν, ὁπότε πεσόντες βουληθεῖεν ἢ τοῖς γόνασιν ἢ ταῖς χερσὶ προσεξερείσασθαι πρὸς τὴν ἐξανάστασιν, τότε καὶ μᾶλλον ἐπέπλεον ἅμα πᾶσι τοῖς ἐρείσμασιν, ἐπὶ πολὺ καταφερῶν ὄντων τῶν χωρίων· τὰ δ’ ὑποζύγια διέκοπτεν, ὅτε πέσοι, τὴν κάτω χιόνα κατὰ τὴν διανάστασιν, διακόψαντα δ’ ἔμενε μετὰ τῶν φορτίων οἷον καταπεπηγότα διά τε τὸ βάρος καὶ διὰ τὸ πῆγμα τῆς προϋπαρχούσης χιόνος. ὅθεν ἀποστὰς τῆς τοιαύτης ἐλπίδος ἐστρατοπέδευσε περὶ τὴν ῥάχιν, διαμησάμενος τὴν ἐπ’ αὐτῇ χιόνα, καὶ μετὰ ταῦτα παραστήσας τὰ πλήθη τὸν κρημνὸν ἐξῳκοδόμει μετὰ πολλῆς ταλαιπωρίας. τοῖς μὲν οὖν ὑποζυγίοις καὶ τοῖς ἵπποις ἱκανὴν ἐποίησε πάροδον ἐν ἡμέρᾳ μιᾷ. διὸ καὶ ταῦτα μὲν εὐθέως διαγαγὼν καὶ καταστρατοπεδεύσας περὶ τοὺς ἐκφεύγοντας ἤδη τὴν χιόνα τόπους διαφῆκε πρὸς τὰς νομάς, τοὺς δὲ Νομάδας ἀνὰ μέρος προῆγε πρὸς τὴν οἰκοδομίαν καὶ μόλις ἐν ἡμέραις τρισὶ κακοπαθήσας διήγαγε τὰ θηρία. καὶ τάδε συνέβαινε κακῶς ὑπὸ τοῦ λιμοῦ διατεθεῖσθαι· τῶν γὰρ Ἄλπεων τὰ μὲν ἄκρα καὶ τὰ πρὸς τὰς ὑπερβολὰς ἀνήκοντα τελέως ἄδενδρα καὶ ψιλὰ πάντ’ ἔστι διὰ τὸ συνεχῶς ἐπιμένειν τὴν χιόνα καὶ θέρους καὶ χειμῶνος, τὰ δ’ ὑπὸ μέσην τὴν παρώρειαν ἐξ ἀμφοῖν τοῖν μεροῖν ὑλοφόρα καὶ δενδροφόρα καὶ τὸ ὅλον οἰκήσιμ’ ἔστιν.", "st": "3.55"}, {"sp": "N", "t": "Ἀννίβας δὲ συναθροίσας ὁμοῦ πᾶσαν τὴν δύναμιν κατέβαινε καὶ τριταῖος ἀπὸ τῶν προειρημένων κρημνῶν διανύσας ἥψατο τῶν ἐπιπέδων, πολλοὺς μὲν ἀπολωλεκὼς τῶν στρατιωτῶν ὑπό τε τῶν πολεμίων καὶ τῶν ποταμῶν ἐν τῇ καθόλου πορείᾳ, πολλοὺς δ’ ὑπὸ τῶν κρημνῶν καὶ τῶν δυσχωριῶν κατὰ τὰς Ἄλπεις, οὐ μόνον ἄνδρας, ἔτι δὲ πλείους ἵππους καὶ ὑποζύγια. τέλος δὲ τὴν μὲν πᾶσαν πορείαν ἐκ Καινῆς πόλεως ἐν πέντε μησὶ ποιησάμενος τὴν δὲ τῶν Ἄλπεων ὑπερβολὴν ἡμέραις δεκαπέντε κατῆρε τολμηρῶς εἰς τὰ περὶ τὸν Πάδον πεδία καὶ τὸ τῶν Ἰνσόμβρων ἔθνος, ἔχων τὸ διασῳζόμενον μέρος τῆς μὲν τῶν Λιβύων δυνάμεως πεζοὺς μυρίους καὶ δισχιλίους, τῆς δὲ τῶν Ἰβήρων εἰς ὀκτακισχιλίους, ἱππεῖς δὲ τοὺς πάντας οὐ πλείους ἑξακισχιλίων, ὡς αὐτὸς ἐν τῇ στήλῃ τῇ περὶ τοῦ πλήθους ἐχούσῃ τὴν ἐπιγραφὴν ἐπὶ Λακινίῳ διασαφεῖ. κατὰ δὲ τοὺς αὐτοὺς καιρούς, ὡς ἐπάνω προεῖπα, Πόπλιος ἀπολελοιπὼς τὰς δυνάμεις Γναΐῳ τἀδελφῷ καὶ παρακεκληκὼς αὐτὸν ἔχεσθαι τῶν ἐν Ἰβηρίᾳ πραγμάτων καὶ πολεμεῖν ἐρρωμένως Ἀσδρούβᾳ, κατέπλευσε μετ’ ὀλίγων αὐτὸς εἰς Πίσας. ποιησάμενος δὲ τὴν πορείαν διὰ Τυρρηνίας καὶ παραλαβὼν τὰ παρὰ τῶν ἑξαπελέκεων στρατόπεδα τὰ προκαθήμενα καὶ προσπολεμοῦντα τοῖς Βοίοις ἧκε πρὸς τὰ περὶ τὸν Πάδον πεδία καὶ καταστρατοπεδεύσας ἐπεῖχε τοῖς πολεμίοις, σπεύδων συμβαλεῖν εἰς μάχην.", "st": "3.56"}, {"sp": "N", "t": "ἡμεῖς δ’ ἐπειδὴ καὶ τὴν διήγησιν καὶ τοὺς ἡγεμόνας ἀμφοτέρων καὶ τὸν πόλεμον εἰς Ἰταλίαν ἠγάγομεν, πρὸ τοῦ τῶν ἀγώνων ἄρξασθαι βραχέα βουλόμεθα περὶ τῶν ἁρμοζόντων τῇ πραγματείᾳ διελθεῖν. ἴσως γὰρ δή τινες ἐπιζητήσουσι πῶς πεποιημένοι τὸν πλεῖστον λόγον ὑπὲρ τῶν κατὰ Λιβύην καὶ κατ’ Ἰβηρίαν τόπων οὔτε περὶ τοῦ καθ’ Ἡρακλέους στήλας στόματος οὐδὲν ἐπὶ πλεῖον εἰρήκαμεν οὔτε περὶ τῆς ἔξω θαλάττης καὶ τῶν ἐν ταύτῃ συμβαινόντων ἰδιωμάτων, οὐδὲ μὴν περὶ τῶν Βρεττανικῶν νήσων καὶ τῆς τοῦ καττιτέρου κατασκευῆς, ἔτι δὲ τῶν ἀργυρείων καὶ χρυσείων τῶν κατ’ αὐτὴν Ἰβηρίαν, ὑπὲρ ὧν οἱ συγγραφεῖς ἀμφισβητοῦντες πρὸς ἀλλήλους τὸν πλεῖστον διατίθενται λόγον. ἡμεῖς δ’ οὐχὶ νομίζοντες ἀλλότριον εἶναι τοῦτο τὸ μέρος τῆς ἱστορίας, διὰ τοῦτο παρελείπομεν, ἀλλὰ πρῶτον μὲν οὐ βουλόμενοι παρ’ ἕκαστα διασπᾶν τὴν διήγησιν οὐδ’ ἀποπλανᾶν ἀπὸ τῆς πραγματικῆς ὑποθέσεως τοὺς φιληκοοῦντας, δεύτερον δὲ κρίνοντες οὐ διερριμμένην οὐδ’ ἐν παρέργῳ ποιήσασθαι τὴν περὶ αὐτῶν μνήμην, ἀλλὰ κατ’ ἰδίαν καὶ τόπον καὶ καιρὸν ἀπονείμαντες τῷ μέρει τούτῳ, καθ’ ὅσον οἷοί τ’ ἐσμέν, τὴν ἀλήθειαν περὶ αὐτῶν ἐξηγήσασθαι. διόπερ οὐ χρὴ θαυμάζειν οὐδ’ ἐν τοῖς ἑξῆς, ἐὰν ἐπί τινας τόπους ἐρχόμενοι τοιούτους παραλείπωμεν τοῦτο τὸ μέρος διὰ τὰς προειρημένας αἰτίας. εἰ δέ τινες πάντως ἐπιζητοῦσι κατὰ τόπον καὶ κατὰ μέρος τῶν τοιούτων ἀκούειν, ἴσως ἀγνοοῦσι παραπλήσιόν τι πάσχοντες τοῖς λίχνοις τῶν δειπνητῶν. καὶ γὰρ ἐκεῖνοι πάντων ἀπογευόμενοι τῶν παρακειμένων οὔτε κατὰ τὸ παρὸν οὐδενὸς ἀληθινῶς ἀπολαύουσι τῶν βρωμάτων οὔτ’ εἰς τὸ μέλλον ὠφέλιμον ἐξ αὐτῶν τὴν ἀνάδοσιν καὶ τροφὴν κομίζονται, πᾶν δὲ τοὐναντίον· οἵ τε περὶ τὴν ἀνάγνωσιν τὸ παραπλήσιον ποιοῦντες οὔτε τῆς παραυτίκα διαγωγῆς ἀληθινῶς οὔτε τῆς εἰς τὸ μέλλον ὠφελείας στοχάζονται δεόντως.", "st": "3.57"}, {"sp": "N", "t": "διότι μὲν οὖν, εἰ καί τι τῶν τῆς ἱστορίας μερῶν ἄλλο, καὶ τοῦτο προσδεῖ λόγου καὶ διορθώσεως ἀληθινωτέρας, προφανὲς ἐκ πολλῶν μάλιστα δ’ ἐκ τούτων. σχεδὸν γὰρ πάντων, εἰ δὲ μή γε, τῶν πλείστων συγγραφέων πεπειραμένων μὲν ἐξηγεῖσθαι τὰς ἰδιότητας καὶ θέσεις τῶν περὶ τὰς ἐσχατιὰς τόπων τῆς καθ’ ἡμᾶς οἰκουμένης, ἐν πολλοῖς δὲ τῶν πλείστων διημαρτηκότων, παραλείπειν μὲν οὐδαμῶς καθήκει, ῥητέον δέ τι πρὸς αὐτοὺς οὐκ ἐκ παρέργου καὶ διερριμμένως ἀλλ’ ἐξ ἐπιστάσεως, καὶ ῥητέον οὐκ ἐπιτιμῶντας οὐδ’ ἐπιπλήττοντας, ἐπαινοῦντας δὲ μᾶλλον καὶ διορθουμένους τὴν ἄγνοιαν αὐτῶν, γινώσκοντας ὅτι κἀκεῖνοι τῶν νῦν καιρῶν ἐπιλαβόμενοι πολλὰ τῶν αὐτοῖς εἰρημένων εἰς διόρθωσιν ἂν καὶ μετάθεσιν ἤγαγον. ἐν μὲν γὰρ τῷ προγεγονότι χρόνῳ σπανίους ἂν εὕροι τις τῶν Ἑλλήνων τοὺς ἐπιβεβλημένους πολυπραγμονεῖν τὰ κατὰ τὰς ἐσχατιὰς διὰ τὸ τῆς ἐπιβολῆς ἀδύνατον. πολλοὶ μὲν γὰρ ἦσαν οἱ κατὰ θάλατταν τότε κίνδυνοι καὶ δυσεξαρίθμητοι, πολλαπλάσιοι δὲ τούτων οἱ κατὰ γῆν. ἀλλ’ εἰ καί τις ἢ κατ’ ἀνάγκην ἢ κατὰ προαίρεσιν ἐξίκοιτο πρὸς τὰ πέρατα τῆς οἰκουμένης, οὐδ’ οὕτως ἤνυεν τὸ προκείμενον. δυσχερὲς μὲν γὰρ ἐπὶ πλέον τινῶν αὐτόπτην γενέσθαι διὰ τὸ τοὺς μὲν ἐκβεβαρβαρῶσθαι τοὺς δ’ ἐρήμους εἶναι τόπους, ἔτι δὲ χαλεπώτερον τὸ περὶ τῶν ὁραθέντων διὰ λόγου τι γνῶναι καὶ μαθεῖν διὰ τὸ τῆς φωνῆς ἐξηλλαγμένον. ἐὰν δὲ καὶ γνῷ τις, ἔτι τῶν πρὸ τοῦ δυσχερέστερον τὸ τῶν ἑωρακότων τινὰ μετρίῳ χρῆσθαι τρόπῳ καὶ καταφρονήσαντα τῆς παραδοξολογίας καὶ τερατείας ἑαυτοῦ χάριν προτιμῆσαι τὴν ἀλήθειαν καὶ μηδὲν τῶν πάρεξ ὄντων ἡμῖν ἀναγγεῖλαι.", "st": "3.58"}, {"sp": "N", "t": "διόπερ οὐ δυσχεροῦς ἀλλ’ ἀδυνάτου σχεδὸν ὑπαρχούσης κατά γε τοὺς προγεγονότας καιροὺς τῆς ἀληθοῦς ἱστορίας ὑπὲρ τῶν προειρημένων, οὐκ εἴ τι παρέλιπον οἱ συγγραφεῖς ἢ διήμαρτον, ἐπιτιμᾶν αὐτοῖς ἄξιον, ἀλλ’ ἐφ’ ὅσον ἔγνωσάν τι καὶ προεβίβασαν τὴν ἐμπειρίαν τὴν περὶ τούτων ἐν τοιούτοις καιροῖς, ἐπαινεῖν καὶ θαυμάζειν αὐτοὺς δίκαιον. ἐν δὲ τοῖς καθ’ ἡμᾶς τῶν μὲν κατὰ τὴν Ἀσίαν διὰ τὴν Ἀλεξάνδρου δυναστείαν τῶν δὲ λοιπῶν τόπων διὰ τὴν Ῥωμαίων ὑπεροχὴν σχεδὸν ἁπάντων πλωτῶν καὶ πορευτῶν γεγονότων, ἀπολελυμένων δὲ καὶ τῶν πρακτικῶν ἀνδρῶν τῆς περὶ τὰς πολεμικὰς καὶ πολιτικὰς πράξεις φιλοτιμίας, ἐκ δὲ τούτων πολλὰς καὶ μεγάλας ἀφορμὰς εἰληφότων εἰς τὸ πολυπραγμονεῖν καὶ φιλομαθεῖν περὶ τῶν προειρημένων, δέον ἂν εἴη καὶ βέλτιον γινώσκειν καὶ ἀληθινώτερον ὑπὲρ τῶν πρότερον ἀγνοουμένων. ὅπερ ἡμεῖς αὐτοί τε πειρασόμεθα ποιεῖν, λαβόντες ἁρμόζοντα τόπον ἐν τῇ πραγματείᾳ τῷ μέρει τούτῳ, τούς τε φιλοπευστοῦντας ὁλοσχερέστερον βουλησόμεθα συνεπιστῆσαι περὶ τῶν προειρημένων, ἐπειδὴ καὶ τὸ πλεῖον τούτου χάριν ὑπεδεξάμεθα τοὺς κινδύνους [καὶ τὰς κακοπαθείας] τοὺς συμβάντας ἡμῖν ἐν πλάνῃ τῇ κατὰ Λιβύην καὶ κατ’ Ἰβηρίαν, ἔτι δὲ Γαλατίαν καὶ τὴν ἔξωθεν ταύταις ταῖς χώραις συγκυροῦσαν θάλατταν, ἵνα διορθωσάμενοι τὴν τῶν προγεγονότων ἄγνοιαν ἐν τούτοις γνώριμα ποιήσωμεν τοῖς Ἕλλησι καὶ ταῦτα τὰ μέρη τῆς οἰκουμένης. νῦν δ’ ἀναδραμόντες ἐπὶ τὴν παρέκβασιν τῆς διηγήσεως πειρασόμεθα δηλοῦν τοὺς γενομένους ἐκ παρατάξεως ἐν Ἰταλίᾳ Ῥωμαίοις καὶ Καρχηδονίοις ἀγῶνας.", "st": "3.59"}, {"sp": "N", "t": "τὸ μὲν οὖν πλῆθος τῆς δυνάμεως, ὅπερ ἔχων Ἀννίβας ἐνέβαλεν εἰς Ἰταλίαν, ἤδη δεδηλώκαμεν. μετὰ δὲ τὴν εἰσβολὴν καταστρατοπεδεύσας ὑπ’ αὐτὴν τὴν παρώρειαν τῶν Ἄλπεων τὰς μὲν ἀρχὰς ἀνελάμβανε τὰς δυνάμεις. οὐ γὰρ μόνον ὑπὸ τῶν ἀναβάσεων καὶ καταβάσεων, ἔτι δὲ τραχυτήτων τῶν κατὰ τὰς ὑπερβολάς, δεινῶς τεταλαιπωρήκει τὸ σύμπαν αὐτῷ στρατόπεδον, ἀλλὰ καὶ τῇ τῶν ἐπιτηδείων σπάνει καὶ ταῖς τῶν σωμάτων ἀθεραπευσίαις κακῶς ἀπήλλαττε. πολλοὶ δὲ καὶ καθυφεῖνθ’ ἑαυτοὺς ὁλοσχερῶς διὰ τὴν ἔνδειαν καὶ συνέχειαν τῶν πόνων. οὔτε γὰρ διακομίζειν εἰς τοσαύτας μυριάδας διὰ τοιούτων τόπων δαψιλῆ τὰ πρὸς τὴν τροφὴν οἷοί τ’ ἦσαν, ἅ τε καὶ παρεκόμιζον, ἅμα τῇ τῶν ὑποζυγίων καταφθορᾷ καὶ τούτων τὰ πλεῖστα συναπώλλυτο. διόπερ ὁρμήσας ἀπὸ τῆς τοῦ Ῥοδανοῦ διαβάσεως, πεζοὺς μὲν εἰς ὀκτακισχιλίους καὶ τρισμυρίους ἔχων ἱππεῖς δὲ πλείους ὀκτακισχιλίων, σχεδόν που τὴν ἡμίσειαν τῆς δυνάμεως, καθάπερ ἐπάνω προεῖπον, ἐν ταῖς ὑπερβολαῖς διέφθειρεν. οἵ γε μὴν σωθέντες καὶ ταῖς ἐπιφανείαις καὶ τῇ λοιπῇ διαθέσει διὰ τὴν συνέχειαν τῶν προειρημένων πόνων οἷον ἀποτεθηριωμένοι πάντες ἦσαν. πολλὴν οὖν ποιούμενος πρόνοιαν Ἀννίβας τῆς ἐπιμελείας αὐτῶν ἀνεκτᾶτο καὶ τὰς ψυχὰς ἅμα καὶ τὰ σώματα τῶν ἀνδρῶν, ὁμοίως δὲ καὶ τῶν ἵππων. μετὰ δὲ ταῦτα, προσανειληφυίας ἤδη τῆς δυνάμεως, τῶν Ταυρίνων, οἳ τυγχάνουσι πρὸς τῇ παρωρείᾳ κατοικοῦντες, στασιαζόντων μὲν πρὸς τοὺς Ἴνσομβρας ἀπιστούντων δὲ τοῖς Καρχηδονίοις, τὸ μὲν πρῶτον αὐτοὺς εἰς φιλίαν προυκαλεῖτο καὶ συμμαχίαν· οὐχ ὑπακουόντων δὲ περιστρατοπεδεύσας τὴν βαρυτάτην πόλιν ἐν τρισὶν ἡμέραις ἐξεπολιόρκησεν. κατασφάξας δὲ τοὺς ἐναντιωθέντας αὐτῷ τοιοῦτον ἐνειργάσατο φόβον τοῖς σύνεγγυς κατοικοῦσιν τῶν βαρβάρων ὥστε πάντας ἐκ χειρὸς παραγίνεσθαι, διδόντας αὑτοὺς εἰς τὴν πίστιν. τὸ δὲ λοιπὸν πλῆθος τῶν τὰ πεδία κατοικούντων Κελτῶν ἐσπούδαζε μὲν κοινωνεῖν τοῖς Καρχηδονίοις τῶν πραγμάτων κατὰ τὴν ἐξ ἀρχῆς ἐπιβολήν· παρηλλαχότων δὲ τῶν Ῥωμαϊκῶν στρατοπέδων ἤδη τοὺς πλείστους αὐτῶν καὶ διακεκλεικότων, ἡσυχίαν ἦγον· τινὲς δὲ καὶ συστρατεύειν ἠναγκάζοντο τοῖς Ῥωμαίοις. εἰς ἃ βλέπων Ἀννίβας ἔκρινε μὴ μέλλειν ἀλλὰ προάγειν εἰς τοὔμπροσθεν καὶ πράττειν τι πρὸς τὸ θαρρῆσαι τοὺς βουλομένους μετέχειν σφίσι τῶν αὐτῶν ἐλπίδων.", "st": "3.60"}, {"sp": "N", "t": "προθέμενος δὲ ταῦτα καὶ τὸν Πόπλιον ἀκούων ἤδη διαβεβηκέναι τὸν Πάδον μετὰ τῶν δυνάμεων καὶ σύνεγγυς εἶναι, τὸ μὲν πρῶτον ἠπίστει τοῖς προσαγγελλομένοις, ἐνθυμούμενος μὲν ὅτι πρότερον ἡμέραις ὀλίγαις αὐτὸν ἀπέλιπε περὶ τὴν τοῦ Ῥοδανοῦ διάβασιν, καὶ συλλογιζόμενος τόν τε πλοῦν τὸν ἀπὸ Μασσαλίας εἰς Τυρρηνίαν ὡς μακρὸς καὶ δυσπαρακόμιστος εἴη, πρὸς δὲ τούτοις τὴν πορείαν ἱστορῶν τὴν ἀπὸ τοῦ Τυρρηνικοῦ πελάγους διὰ τῆς Ἰταλίας μέχρι πρὸς τὰς Ἄλπεις ὡς πολλὴ καὶ δυσδίοδος ὑπάρχει στρατοπέδοις. πλειόνων δὲ καὶ σαφεστέρως ἀεὶ προσαγγελλόντων, ἐθαύμαζε καὶ κατεπέπληκτο τὴν ὅλην ἐπιβολὴν καὶ τὴν πρᾶξιν τοῦ στρατηγοῦ. τὸ δὲ παραπλήσιον συνέβαινε πάσχειν καὶ τὸν Πόπλιον· τὰς μὲν γὰρ ἀρχὰς οὐδ’ ἐπιβάλλεσθαι τῇ διὰ τῶν Ἄλπεων ἤλπισε πορείᾳ τὸν Ἀννίβαν δυνάμεσιν ἀλλοφύλοις· εἰ δὲ καὶ τολμήσαι, καταφθαρήσεσθαι προδήλως αὐτὸν ὑπελάμβανεν. διόπερ ἐν τοιούτοις ὢν διαλογισμοῖς, ὡς ἐπυνθάνετο καὶ σεσῶσθαι καὶ πολιορκεῖν αὐτὸν ἤδη τινὰς πόλεις ἐν Ἰταλίᾳ, κατεπέπληκτο τὴν τόλμαν καὶ τὸ παράβολον τἀνδρός. τὸ δ’ αὐτὸ συνέβαινεν καὶ τοῖς ἐν τῇ Ῥώμῃ πεπονθέναι περὶ τῶν προσπιπτόντων. ἄρτι γὰρ τῆς τελευταίας φήμης καταληγούσης ὑπὲρ τῶν Καρχηδονίων ὅτι Ζάκανθαν εἰλήφασιν, καὶ πρὸς ταύτην βεβουλευμένων τὴν ἔννοιαν, καὶ τὸν μὲν ἕνα τῶν στρατηγῶν ἐξαπεσταλκότων εἰς τὴν Λιβύην, ὡς αὐτὴν τὴν Καρχηδόνα πολιορκήσοντα, τὸν ἕτερον δ’ εἰς Ἰβηρίαν, ὡς πρὸς Ἀννίβαν ἐκεῖ διαπολεμήσοντα, παρῆν ἀγγελία διότι πάρεστιν Ἀννίβας μετὰ δυνάμεως καὶ πολιορκεῖ τινας ἤδη πόλεις ἐν Ἰταλίᾳ. διότι παραδόξου φανέντος αὐτοῖς τοῦ γινομένου, διαταραχθέντες παραχρῆμα πρὸς τὸν Τεβέριον εἰς τὸ Λιλύβαιον ἐξαπέστελλον, δηλοῦντες μὲν τὴν παρουσίαν τῶν πολεμίων, οἰόμενοι δὲ δεῖν ἀφέμενον τῶν προκειμένων κατὰ σπουδὴν βοηθεῖν τοῖς ἰδίοις πράγμασιν. ὁ δὲ Τεβέριος τοὺς μὲν ἀπὸ τοῦ στόλου παραυτίκα συναθροίσας ἐξέπεμψε, παραγγείλας ποιεῖσθαι τὸν πλοῦν ὡς ἐπ’ οἴκου· τὰς δὲ πεζικὰς δυνάμεις ἐξώρκισε διὰ τῶν χιλιάρχων, τάξας ἡμέραν ἐν ᾗ δεήσει πάντας ἐν Ἀριμίνῳ γενέσθαι κοιταίους. αὕτη δ’ ἔστι πόλις παρὰ τὸν Ἀδρίαν ἐπὶ τῷ πέρατι κειμένη τῶν περὶ τὸν Πάδον πεδίων ὡς ἀπὸ μεσημβρίας. πανταχόθεν δὲ τοῦ κινήματος ἅμα γινομένου, καὶ τῶν συμβαινόντων πᾶσι παρὰ δόξαν προσπιπτόντων, ἦν παρ’ ἑκάστοις ἐπίστασις ὑπὲρ τοῦ μέλλοντος οὐκ εὐκαταφρόνητος.", "st": "3.61"}, {"sp": "N", "t": "κατὰ δὲ τὸν καιρὸν τοῦτον ἤδη συνεγγίζοντες ἀλλήλοις Ἀννίβας καὶ Πόπλιος ἐπεβάλοντο παρακαλεῖν τὰς ἑαυτῶν δυνάμεις, ἑκάτερος προθέμενος τὰ πρέποντα τοῖς παροῦσι καιροῖς. Ἀννίβας μὲν οὖν διὰ τοιοῦδέ τινος ἐνεχείρει τρόπου ποιεῖσθαι τὴν παραίνεσιν. συναγαγὼν γὰρ τὰ πλήθη παρήγαγεν νεανίσκους τῶν αἰχμαλώτων, οὓς εἰλήφει κακοποιοῦντας τὴν πορείαν ἐν ταῖς περὶ τὰς Ἄλπεις δυσχωρίαις. τούτους δὲ κακῶς διετίθετο, παρασκευαζόμενος πρὸς τὸ μέλλον· καὶ γὰρ δεσμοὺς εἶχον βαρεῖς καὶ τῷ λιμῷ συνέσχηντο, καὶ ταῖς πληγαῖς αὐτῶν τὰ σώματα διέφθαρτο. καθίσας οὖν τούτους εἰς τὸ μέσον προέθηκε πανοπλίας Γαλατικάς, οἵαις εἰώθασιν οἱ βασιλεῖς αὐτῶν, ὅταν μονομαχεῖν μέλλωσιν, κατακοσμεῖσθαι· πρὸς δὲ τούτοις ἵππους παρέστησε καὶ σάγους εἰσήνεγκε πολυτελεῖς. κἄπειτα τῶν νεανίσκων ἤρετο τίνες αὐτῶν βούλονται διαγωνίσασθαι πρὸς ἀλλήλους ἐφ’ ᾧ τὸν μὲν νικήσαντα τὰ προκείμενα λαμβάνειν ἆθλα, τὸν δ’ ἡττηθέντα τῶν παρόντων ἀπηλλάχθαι κακῶν, τελευτήσαντα τὸν βίον. πάντων δ’ ἀναβοησάντων ἅμα καὶ δηλούντων ὅτι βούλονται μονομαχεῖν, κληρώσασθαι προσέταξε καὶ δύο τοὺς λαχόντας καθοπλισαμένους ἐκέλευσε μάχεσθαι πρὸς ἀλλήλους. παραυτίκα μὲν οὖν ἀκούσαντες οἱ νεανίσκοι ταῦτα καὶ τὰς χεῖρας ἐξαίροντες εὔχοντο τοῖς θεοῖς, σπεύδων ἕκαστος αὐτὸς γενέσθαι τῶν λαχόντων. ἐπεὶ δ’ ἐδηλώθη τὰ κατὰ τὸν κλῆρον, ἦσαν οἱ μὲν εἰληχότες περιχαρεῖς, οἱ δ’ ἄλλοι τοὐναντίον. γενομένης δὲ τῆς μάχης οὐχ ἧττον ἐμακάριζον οἱ περιλειπόμενοι τῶν αἰχμαλώτων τὸν τεθνεῶτα τοῦ νενικηκότος, ὡς πολλῶν καὶ μεγάλων κακῶν ἐκείνου μὲν ἀπολελυμένου, σφᾶς δ’ αὐτοὺς ἀκμὴν ὑπομένοντας. ἦν δὲ παραπλησία καὶ περὶ τοὺς πολλοὺς τῶν Καρχηδονίων ἡ διάληψις· ἐκ παραθέσεως γὰρ θεωρουμένης τῆς τῶν ἀγομένων καὶ ζώντων ταλαιπωρίας, τούτους μὲν ἠλέουν, τὸν δὲ τεθνεῶτα πάντες ἐμακάριζον.", "st": "3.62"}, {"sp": "N", "t": "Ἀννίβας δὲ διὰ τῶν προειρημένων τὴν προκειμένην διάθεσιν ἐνεργασάμενος ταῖς τῶν δυνάμεων ψυχαῖς, μετὰ ταῦτα προελθὼν αὐτὸς τούτου χάριν ἔφη παρεισάγειν τοὺς αἰχμαλώτους, ἵν’ ἐπὶ τῶν ἀλλοτρίων συμπτωμάτων ἐναργῶς θεασάμενοι τὸ συμβαῖνον βέλτιον ὑπὲρ τῶν σφίσι παρόντων βουλεύωνται πραγμάτων. εἰς παραπλήσιον γὰρ αὐτοὺς ἀγῶνα καὶ καιρὸν τὴν τύχην συγκεκλεικέναι καὶ παραπλήσια τοῖς νῦν ἆθλα προτεθεικέναι. δεῖν γὰρ ἢ νικᾶν ἢ θνήσκειν ἢ τοῖς ἐχθροῖς ὑποχειρίους γενέσθαι ζῶντας. εἶναι δ’ ἐκ μὲν τοῦ νικᾶν ἆθλον οὐχ ἵππους καὶ σάγους, ἀλλὰ τὸ πάντων ἀνθρώπων γενέσθαι μακαριωτάτους, κρατήσαντας τῆς Ῥωμαίων εὐδαιμονίας, ἐκ δὲ τοῦ μαχομένους τι παθεῖν, διαγωνιζομένους ἕως τῆς ἐσχάτης ἀναπνοῆς ὑπὲρ τῆς καλλίστης ἐλπίδος μεταλλάξαι τὸν βίον ἐν χειρῶν νόμῳ, μηδενὸς κακοῦ λαβόντας πεῖραν, τοῖς δ’ ἡττωμένοις καὶ διὰ τὴν πρὸς τὸ ζῆν ἐπιθυμίαν ὑπομένουσι φεύγειν ἢ κατ’ ἄλλον τινὰ τρόπον ἑλομένοις τὸ ζῆν παντὸς κακοῦ καὶ πάσης ἀτυχίας μετασχεῖν. οὐδένα γὰρ οὕτως ἀλόγιστον οὐδὲ νωθρὸν αὐτῶν ὑπάρχειν, ὃς μνημονεύων μὲν τοῦ μήκους τῆς ὁδοῦ τῆς διηνυσμένης ἐκ τῶν πατρίδων, μνημονεύων δὲ τοῦ πλήθους τῶν μεταξὺ πολεμίων, εἰδὼς δὲ τὰ μεγέθη τῶν ποταμῶν ὧν διεπέρασεν, ἐλπίσαι ποτ’ ἂν ὅτι φεύγων εἰς τὴν οἰκείαν ἀφίξεται. διόπερ ᾤετο δεῖν αὐτούς, ἀποκεκομμένης καθόλου τῆς τοιαύτης ἐλπίδος, τὴν αὐτὴν διάληψιν ποιεῖσθαι περὶ τῶν καθ’ αὑτοὺς πραγμάτων ἥνπερ ἀρτίως ἐποιοῦντο περὶ τῶν ἀλλοτρίων συμπτωμάτων. καθάπερ γὰρ ἐπ’ ἐκείνων τὸν μὲν νικήσαντα καὶ τεθνεῶτα πάντες ἐμακάριζον τοὺς δὲ ζῶντας ἠλέουν, οὕτως ᾤετο δεῖν καὶ περὶ τῶν καθ’ αὑτοὺς διαλαμβάνειν καὶ πάντας ἰέναι πρὸς τοὺς ἀγῶνας, μάλιστα μὲν νικήσοντας, ἂν δὲ μὴ τοῦτ’ ᾖ δυνατόν, ἀποθανουμένους. τὴν δὲ τοῦ ζῆν ἡττημένους ἐλπίδα κατὰ μηδένα τρόπον ἠξίου λαμβάνειν ἐν νῷ. τούτῳ γὰρ χρησαμένων αὐτῶν τῷ λογισμῷ καὶ τῇ προθέσει ταύτῃ, καὶ τὸ νικᾶν ἅμα καὶ τὸ σῴζεσθαι προδήλως σφίσι συνεξακολουθήσειν. πάντας γὰρ τοὺς ἢ κατὰ προαίρεσιν ἢ κατ’ ἀνάγκην τοιαύτῃ προθέσει κεχρημένους οὐδέποτε διεψεῦσθαι τοῦ κρατεῖν τῶν ἀντιταξαμένων. ὅταν δὲ δὴ καὶ τοῖς πολεμίοις συμβαίνῃ τὴν ἐναντίαν ἐλπίδα ταύτης ὑπάρχειν, ὃ νῦν ἐστι περὶ Ῥωμαίους, ὥστε φεύγουσι πρόδηλον εἶναι τοῖς πλείστοις τὴν σωτηρίαν, παρακειμένης αὐτοῖς τῆς οἰκείας, δῆλον ὡς ἀνυπόστατος γίνοιτ’ ἂν ἡ τῶν ἀπηλπικότων τόλμα. τῶν δὲ πολλῶν ἀποδεχομένων τό τε παράδειγμα καὶ τοὺς λόγους καὶ λαμβανόντων ὁρμὴν καὶ παράστασιν οἵαν ὁ παρακαλῶν ἐσπούδασε, τότε μὲν ἐπαινέσας αὐτοὺς διαφῆκε, τῇ δ’ ἐπαύριον ἀναζυγὴν ἅμα τῷ φωτὶ παρήγγειλε.", "st": "3.63"}, {"sp": "N", "t": "Πόπλιος δὲ περὶ τὰς αὐτὰς ἡμέρας τὸν Πάδον ποταμὸν ἤδη πεπεραιωμένος, τὸν δὲ Τίκινον κρίνων εἰς τοὔμπροσθεν διαβαίνειν, τοῖς μὲν ἐπιτηδείοις γεφυροποιεῖν παρήγγειλε, τὰς δὲ λοιπὰς δυνάμεις συναγαγὼν παρεκάλει. τὰ μὲν οὖν πολλὰ τῶν λεγομένων ἦν περί τε τοῦ τῆς πατρίδος ἀξιώματος καὶ τῶν προγονικῶν πράξεων, τὰ δὲ τοῦ παρεστῶτος καιροῦ τοιάδε. ἔφη γὰρ δεῖν καὶ μηδεμίαν μὲν εἰληφότας πεῖραν ἐπὶ τοῦ παρόντος τῶν ὑπεναντίων, αὐτὸ δὲ τοῦτο γινώσκοντας ὅτι μέλλουσι πρὸς Καρχηδονίους κινδυνεύειν, ἀναμφισβήτητον ἔχειν τὴν τοῦ νικᾶν ἐλπίδα, καὶ καθόλου δεινὸν ἡγεῖσθαι καὶ παράλογον, εἰ τολμῶσι Καρχηδόνιοι Ῥωμαίοις ἀντοφθαλμεῖν, πολλάκις μὲν ὑπ’ αὐτῶν ἡττημένοι, πολλοὺς δ’ ἐξενηνοχότες φόρους, μόνον δ’ οὐχὶ δουλεύοντες αὐτοῖς ἤδη τοσούτους χρόνους. ὅταν δέ, χωρὶς τῶν προειρημένων, καὶ τῶν νῦν παρόντων ἀνδρῶν ἔχωμεν ἐπὶ ποσὸν πεῖραν ὅτι μόνον οὐ τολμῶσι κατὰ πρόσωπον ἰδεῖν ἡμᾶς, τίνα χρὴ διάληψιν ποιεῖσθαι περὶ τοῦ μέλλοντος τοὺς ὀρθῶς λογιζομένους; καὶ μὴν οὔτε τοὺς ἱππεῖς συμπεσόντας τοῖς παρ’ αὑτῶν ἱππεῦσι περὶ τὸν Ῥοδανὸν ποταμὸν ἀπαλλάξαι καλῶς, ἀλλὰ πολλοὺς ἀποβαλόντας αὑτῶν φυγεῖν αἰσχρῶς μέχρι τῆς ἰδίας παρεμβολῆς, τόν τε στρατηγὸν αὐτῶν καὶ τὴν σύμπασαν δύναμιν ἐπιγνόντας τὴν παρουσίαν τῶν ἡμετέρων στρατιωτῶν φυγῇ παραπλησίαν ποιήσασθαι τὴν ἀποχώρησιν καὶ παρὰ τὴν αὑτῶν προαίρεσιν διὰ τὸν φόβον κεχρῆσθαι τῇ διὰ τῶν Ἄλπεων πορείᾳ. παρεῖναι δὲ καὶ νῦν ἔφη τὸν Ἀννίβαν, κατεφθαρκότα μὲν τὸ πλεῖστον μέρος τῆς δυνάμεως, τὸ δὲ περιλειπόμενον ἀδύνατον καὶ δύσχρηστον ἔχοντα διὰ τὴν κακουχίαν, ὁμοίως δὲ καὶ τῶν ἵππων τοὺς μὲν πλείστους ἀπολωλεκότα, τοὺς δὲ λοιποὺς ἠχρειωκότα διὰ τὸ μῆκος καὶ τὴν δυσχέρειαν τῆς ὁδοῦ. δι’ ὧν ἐπιδεικνύειν ἐπειρᾶτο διότι μόνον ἐπιφανῆναι δεῖ τοῖς πολεμίοις. μάλιστα δ’ ἠξίου θαρρεῖν αὐτοὺς βλέποντας εἰς τὴν αὑτοῦ παρουσίαν· οὐδέποτε γὰρ ἂν ἀπολιπὼν τὸν στόλον καὶ τὰς ἐν Ἰβηρίᾳ πράξεις, ἐφ’ ἃς ἀπεστάλη, δεῦρο μετὰ τοιαύτης ἐλθεῖν σπουδῆς, εἰ μὴ καὶ λίαν ἐκ τῶν κατὰ λόγον ἑώρα τὴν πρᾶξιν ταύτην ἀναγκαίαν μὲν οὖσαν τῇ πατρίδι, πρόδηλον δ’ ἐν αὐτῇ τὴν νίκην ὑπάρχουσαν. πάντων δὲ καὶ διὰ τὴν τοῦ λέγοντος πίστιν καὶ διὰ τὴν τῶν λεγομένων ἀλήθειαν ἐκθύμως ἐχόντων πρὸς τὸ κινδυνεύειν, ἀποδεξάμενος αὐτῶν τὴν ὁρμὴν διαφῆκε, προσπαρακαλέσας ἑτοίμους εἶναι πρὸς τὸ παραγγελλόμενον.", "st": "3.64"}, {"sp": "N", "t": "τῇ δὲ κατὰ πόδας ἡμέρᾳ προῆγον ἀμφότεροι παρὰ τὸν ποταμὸν ἐκ τοῦ πρὸς τὰς Ἄλπεις μέρους, ἔχοντες εὐώνυμον μὲν οἱ Ῥωμαῖοι, δεξιὸν δὲ τὸν ῥοῦν οἱ Καρχηδόνιοι. γνόντες δὲ τῇ δευτέρᾳ διὰ τῶν προνομευόντων ὅτι σύνεγγύς εἰσιν ἀλλήλων, τότε μὲν αὐτοῦ καταστρατοπεδεύσαντες ἔμειναν. τῇ δ’ ἐπαύριον πᾶσαν τὴν ἵππον ἀναλαβόντες ἀμφότεροι, Πόπλιος δὲ καὶ τῶν πεζῶν τοὺς ἀκοντιστάς, προῆγον διὰ τοῦ πεδίου, σπεύδοντες κατοπτεῦσαι τὰς ἀλλήλων δυνάμεις. ἅμα δὲ τῷ πλησιάζειν αὑτοῖς καὶ συνιδεῖν τὸν κονιορτὸν ἐξαιρόμενον εὐθέως συνετάττοντο πρὸς μάχην. ὁ μὲν οὖν Πόπλιος προθέμενος τοὺς ἀκοντιστὰς καὶ τοὺς ἅμα τούτοις Γαλατικοὺς ἱππεῖς, τοὺς δὲ λοιποὺς ἐν μετώπῳ καταστήσας προῄει βάδην. ὁ δ’ Ἀννίβας τὴν μὲν κεχαλινωμένην ἵππον καὶ πᾶν τὸ στάσιμον αὐτῆς κατὰ πρόσωπον τάξας ἀπήντα τοῖς πολεμίοις, τοὺς δὲ Νομαδικοὺς ἱππεῖς ἀφ’ ἑκατέρου τοῦ κέρατος ἡτοιμάκει πρὸς κύκλωσιν. ἀμφοτέρων δὲ καὶ τῶν ἡγεμόνων καὶ τῶν ἱππέων φιλοτίμως διακειμένων πρὸς τὸν κίνδυνον, τοιαύτην συνέβη γενέσθαι τὴν πρώτην σύμπτωσιν ὥστε τοὺς ἀκοντιστὰς μὴ φθάσαι τὸ πρῶτον ἐκβαλόντας βέλος, φεύγειν δ’ ἐγκλίναντας εὐθέως διὰ τῶν διαστημάτων ὑπὸ τὰς παρ’ αὑτῶν ἴλας, καταπλαγέντας τὴν ἐπιφορὰν καὶ περιδεεῖς γενομένους μὴ συμπατηθῶσιν ὑπὸ τῶν ἐπιφερομένων ἱππέων. οἱ μὲν οὖν κατὰ πρόσωπον ἀλλήλοις συμπεσόντες ἐπὶ πολὺν χρόνον ἐποίουν ἰσόρροπον τὸν κίνδυνον· ὁμοῦ γὰρ ἦν ἱππομαχία καὶ πεζομαχία διὰ τὸ πλῆθος τῶν παρακαταβαινόντων ἀνδρῶν ἐν αὐτῇ τῇ μάχῃ. τῶν δὲ Νομάδων κυκλωσάντων καὶ κατόπιν ἐπιπεσόντων, οἱ μὲν πεζακοντισταὶ τὸ πρῶτον διαφυγόντες τὴν σύμπτωσιν τῶν ἱππέων τότε συνεπατήθησαν ὑπὸ τοῦ πλήθους καὶ τῆς ἐπιφορᾶς τῶν Νομάδων· οἱ δὲ κατὰ πρόσωπον ἐξ ἀρχῆς διαμαχόμενοι πρὸς τοὺς Καρχηδονίους, πολλοὺς μὲν αὑτῶν ἀπολωλεκότες, ἔτι δὲ πλείους τῶν Καρχηδονίων διεφθαρκότες, συνεπιθεμένων ἀπ’ οὐρᾶς τῶν Νομάδων, ἐτράπησαν, οἱ μὲν πολλοὶ σποράδες, τινὲς δὲ περὶ τὸν ἡγεμόνα συστραφέντες.", "st": "3.65"}, {"sp": "N", "t": "Πόπλιος μὲν οὖν ἀναζεύξας προσῆγε διὰ τῶν πεδίων ἐπὶ τὴν τοῦ Πάδου γέφυραν, σπεύδων φθάσαι διαβιβάσας τὰ στρατόπεδα. θεωρῶν γὰρ τοὺς μὲν τόπους ἐπιπέδους ὄντας, τοὺς δ’ ὑπεναντίους ἱπποκρατοῦντας, αὑτὸν δὲ βαρυνόμενον ὑπὸ τοῦ τραύματος, εἰς ἀσφαλὲς ἔκρινε δεῖν ἀποκαταστῆσαι τὰς δυνάμεις. Ἀννίβας δὲ μέχρι μέν τινος ὑπέλαβε τοῖς πεζικοῖς στρατοπέδοις αὐτοὺς διακινδυνεύειν· συνιδὼν δὲ κεκινηκότας ἐκ τῆς παρεμβολῆς, ἕως μὲν τοῦ πρώτου ποταμοῦ καὶ τῆς ἐπὶ τούτῳ γεφύρας ἠκολούθει, καταλαβὼν δὲ τὰς μὲν πλείστας τῶν σανίδων ἀνεσπασμένας, τοὺς δὲ φυλάττοντας τὴν γέφυραν ἔτι περὶ τὸν ποταμὸν ὑπολειπομένους, τούτων μὲν ἐγκρατὴς ἐγένετο, σχεδὸν ἑξακοσίων ὄντων τὸν ἀριθμόν· τοὺς δὲ λοιποὺς ἀκούων ἤδη πολὺ προειληφέναι, μεταβαλόμενος αὖθις εἰς τἀναντία παρὰ τὸν ποταμὸν ἐποιεῖτο τὴν πορείαν, σπεύδων ἐπὶ τόπον εὐγεφύρωτον ἀφικέσθαι τοῦ Πάδου. καταλύσας δὲ δευτεραῖος καὶ γεφυρώσας τοῖς ποταμίοις πλοίοις τὴν διάβασιν Ἀσδρούβᾳ μὲν ἐπέταξεν διακομίζειν τὸ πλῆθος, αὐτὸς δὲ διαβὰς εὐθέως ἐχρημάτιζε τοῖς παραγεγονόσι πρεσβευταῖς ἀπὸ τῶν σύνεγγυς τόπων. ἅμα γὰρ τῷ γενέσθαι τὸ προτέρημα πάντες ἔσπευδον οἱ παρακείμενοι Κελτοὶ κατὰ τὴν ἐξ ἀρχῆς πρόθεσιν καὶ φίλοι γίνεσθαι καὶ χορηγεῖν καὶ συστρατεύειν τοῖς Καρχηδονίοις. ἀποδεξάμενος δὲ τοὺς παρόντας φιλανθρώπως καὶ κομισάμενος τὰς δυνάμεις ἐκ τοῦ πέραν προῆγεν παρὰ τὸν ποταμόν, τὴν ἐναντίαν ποιούμενος τῇ πρόσθεν παρόδῳ· κατὰ ῥοῦν γὰρ ἐποιεῖτο τὴν πορείαν, σπεύδων συνάψαι τοῖς ὑπεναντίοις. ὁ δὲ Πόπλιος περαιωθεὶς τὸν Πάδον καὶ στρατοπεδεύσας περὶ πόλιν Πλακεντίαν, ἥτις ἦν ἀποικία Ῥωμαίων, ἅμα μὲν αὑτὸν ἐθεράπευε καὶ τοὺς ἄλλους τραυματίας, ἅμα δὲ τὰς δυνάμεις εἰς ἀσφαλὲς ἀπηρεῖσθαι νομίζων ἦγε τὴν ἡσυχίαν. Ἀννίβας δὲ παραγενόμενος δευτεραῖος ἀπὸ τῆς διαβάσεως ἐγγὺς τῶν πολεμίων τῇ τρίτῃ παρέταξε τὴν δύναμιν ἐν συνόψει τοῖς ὑπεναντίοις. οὐδενὸς δὲ σφίσιν ἀντεξάγοντος, κατεστρατοπέδευσε, λαβὼν περὶ πεντήκοντα στάδια τὸ μεταξὺ διάστημα τῶν στρατοπέδων.", "st": "3.66"}, {"sp": "N", "t": "οἱ δὲ συστρατευόμενοι Κελτοὶ τοῖς Ῥωμαίοις θεωροῦντες ἐπικυδεστέρας τὰς τῶν Καρχηδονίων ἐλπίδας, συνταξάμενοι πρὸς ἀλλήλους καιρὸν ἐπετήρουν πρὸς ἐπίθεσιν, μένοντες ἐν ταῖς ἑαυτῶν ἕκαστοι σκηναῖς. δειπνοποιησαμένων δὲ καὶ κατακοιμισθέντων τῶν ἐν τῷ χάρακι, παρελθεῖν ἐάσαντες τὸ πλεῖον μέρος τῆς νυκτὸς καθωπλισμένοι περὶ τὴν ἑωθινὴν φυλακὴν ἐπιτίθενται τοῖς σύνεγγυς τῶν Ῥωμαίων παραστρατοπεδεύουσι. καὶ πολλοὺς μὲν αὐτῶν ἀπέκτειναν, οὐκ ὀλίγους δὲ κατετραυμάτισαν· τέλος δὲ τὰς κεφαλὰς ἀποτεμόντες τῶν τεθνεώτων ἀπεχώρουν πρὸς τοὺς Καρχηδονίους, ὄντες πεζοὶ μὲν εἰς δισχιλίους, ἱππεῖς δὲ μικρῷ λείποντες διακοσίων. Ἀννίβας δὲ φιλοφρόνως ἀποδεξάμενος αὐτῶν τὴν παρουσίαν, τούτους μὲν εὐθέως παρακαλέσας καὶ δωρεὰς ἑκάστοις τὰς ἁρμοζούσας ἐπαγγειλάμενος ἐξέπεμψεν εἰς τὰς αὑτῶν πόλεις, δηλώσοντας μὲν τὰ πεπραγμένα τοῖς πολίταις, παρακαλέσοντας δὲ πρὸς τὴν αὑτοῦ συμμαχίαν. ᾔδει γὰρ ὅτι πάντες κατ’ ἀνάγκην αὐτῷ κοινωνήσουσι τῶν πραγμάτων, ἐπιγνόντες τὸ γεγονὸς ἐκ τῶν σφετέρων πολιτῶν παρασπόνδημα κατὰ τῶν Ῥωμαίων. ἅμα δὲ τούτοις καὶ τῶν Βοίων παραγεγονότων καὶ τοὺς τρεῖς ἄνδρας ἐγχειριζόντων αὐτῷ τοὺς ἐπὶ τὴν διάδοσιν τῆς χώρας ὑπὸ Ῥωμαίων ἐξαπεσταλμένους, ὧν κατ’ ἀρχὰς ἐκυρίευσαν τοῦ πολέμου παρασπονδήσαντες, καθάπερ ἐπάνω προεῖπον, ἀποδεξάμενος Ἀννίβας τὴν εὔνοιαν αὐτῶν ὑπὲρ μὲν τῆς φιλίας καὶ συμμαχίας ἔθετο πρὸς τοὺς παρόντας πίστεις· τούς γε μὴν ἄνδρας αὐτοῖς ἀπέδωκε, παραγγείλας τηρεῖν, ἵνα παρὰ τούτων κομίσωνται τοὺς αὑτῶν ὁμήρους κατὰ τὴν ἐξ ἀρχῆς πρόθεσιν. Πόπλιος δὲ σχετλιάζων ἐπὶ τῷ γεγονότι παρασπονδήματι καὶ συλλογισάμενος ὅτι πάλαι τῶν Κελτῶν πρὸς αὐτοὺς ἀλλοτρίως διακειμένων, τούτων ἐπιγεγονότων πάντας τοὺς πέριξ Γαλάτας συμβήσεται πρὸς τοὺς Καρχηδονίους ἀπονεύειν, ἔγνω δεῖν εὐλαβηθῆναι τὸ μέλλον. διόπερ ἐπιγενομένης τῆς νυκτὸς ὑπὸ τὴν ἑωθινὴν ἀναζεύξας ἐποιεῖτο τὴν πορείαν ὡς ἐπὶ τὸν Τρεβίαν ποταμὸν καὶ τοὺς τούτῳ συνάπτοντας γεωλόφους, πιστεύων τῇ τε τῶν τόπων ὀχυρότητι καὶ τοῖς παροικοῦσι τῶν συμμάχων.", "st": "3.67"}, {"sp": "N", "t": "Ἀννίβας δὲ τὴν ἀναζυγὴν αὐτῶν ἐπιγνοὺς παραυτίκα μὲν τοὺς Νομαδικοὺς ἱππεῖς ἐξαπέστελλε, μετ’ οὐ πολὺ δὲ τοὺς ἄλλους· τούτοις δ’ ἐκ ποδὸς τὴν δύναμιν ἔχων αὐτὸς εἵπετο κατόπιν. οἱ μὲν οὖν Νομάδες εἰς ἔρημον τὴν στρατοπεδείαν ἐμπεσόντες ταύτην ἐνεπίμπρασαν. ὃ δὴ καὶ σφόδρα συνήνεγκε τοῖς Ῥωμαίοις, ὡς εἴπερ οὗτοι κατὰ πόδας ἀκολουθήσαντες συνῆψαν ταῖς ἀποσκευαῖς, πολλοὺς ἂν αὐτῶν ὑπὸ τῶν ἱππέων ἐν τοῖς ἐπιπέδοις συνέβη διαφθαρῆναι. νῦν δ’ οἱ πλείους ἔφθασαν διαβάντες τὸν Τρεβίαν ποταμόν· τῶν δὲ καταλειφθέντων ἐπὶ τῆς οὐραγίας οἱ μὲν διεφθάρησαν, οἱ δὲ ζῶντες ἑάλωσαν ὑπὸ τῶν Καρχηδονίων. Πόπλιος μὲν οὖν διαβὰς τὸν προειρημένον ποταμὸν ἐστρατοπέδευσε περὶ τοὺς πρώτους λόφους καὶ περιλαβὼν τάφρῳ καὶ χάρακι τὴν παρεμβολὴν ἀνεδέχετο μὲν τὸν Τεβέριον καὶ τὰς μετ’ ἐκείνου δυνάμεις, ἐθεράπευε δ’ αὑτὸν ἐπιμελῶς, σπουδάζων εἰ δύναιτο κοινωνῆσαι τοῦ μέλλοντος κινδύνου. Ἀννίβας δὲ περὶ τετταράκοντα σταδίους ἀποσχὼν τῶν πολεμίων αὐτοῦ κατεστρατοπέδευσε. τὸ δὲ τῶν Κελτῶν πλῆθος τὸ τὰ πεδία κατοικοῦν, συνεξεστηκὸς ταῖς τῶν Καρχηδονίων ἐλπίσι, δαψιλῶς μὲν ἐχορήγει τὸ στρατόπεδον τοῖς ἐπιτηδείοις, ἕτοιμον δ’ ἦν παντὸς κοινωνεῖν ἔργου καὶ κινδύνου τοῖς περὶ τὸν Ἀννίβαν. οἱ δ’ ἐν τῇ Ῥώμῃ, προσπεπτωκότων τῶν κατὰ τὴν ἱππομαχίαν, ἐξενίζοντο μὲν τῷ τὸ συμβεβηκὸς εἶναι παρὰ τὴν προσδοκίαν, οὐ μὴν ἠπόρουν γε σκήψεων πρὸς τὸ μὴ δοκεῖν αὐτοῖς ἧτταν εἶναι τὸ γεγονός, ἀλλ’ οἱ μὲν ᾐτιῶντο τὴν τοῦ στρατηγοῦ προπέτειαν, οἱ δὲ τὴν τῶν Κελτῶν ἐθελοκάκησιν, στοχαζόμενοι διὰ τῆς τελευταίας ἀποστάσεως. καθόλου δὲ τῶν πεζικῶν στρατοπέδων ἀκεραίων ὄντων ἀκεραίους εἶναι διελάμβανον τὰς ὑπὲρ τῶν ὅλων ἐλπίδας. ὅθεν καὶ συνάψαντος τοῦ Τεβερίου καὶ τῶν μετ’ ἐκείνου στρατοπέδων καὶ διαπορευομένων διὰ τῆς Ῥώμης, ἐξ ἐπιφανείας ἐδόξαζον κριθήσεσθαι τὴν μάχην. ἁθροισθέντων δὲ τῶν στρατιωτῶν κατὰ τὸν ὅρκον εἰς Ἀρίμινον, ἀναλαβὼν αὐτοὺς ὁ στρατηγὸς προῆγε, σπεύδων συνάψαι τοῖς περὶ τὸν Πόπλιον. συμμίξας δὲ καὶ καταστρατοπεδεύσας παρ’ αὐτοῖς ταῖς οἰκείαις δυνάμεσι τὸ μὲν πλῆθος ἀνελάμβανε τῶν ἀνδρῶν, ὡς ἂν ἐκ Λιλυβαίου τετταράκοντα συνεχῶς ἡμέρας πεπεζοπορηκότων εἰς Ἀρίμινον, τὰς δὲ παρασκευὰς ἐποιεῖτο πάσας ὡς πρὸς μάχην, αὐτὸς δ’ ἐπιμελῶς συνήδρευε τῷ Ποπλίῳ, τὰ μὲν ἤδη γεγονότα πυνθανόμενος, περὶ δὲ τῶν παρόντων συνδιανοούμενος.", "st": "3.68"}, {"sp": "N", "t": "κατὰ δὲ τοὺς αὐτοὺς καιροὺς Ἀννίβας πραξικοπήσας πόλιν Κλαστίδιον, ἐνδόντος αὐτῷ τοῦ πεπιστευμένου παρὰ Ῥωμαίων, ἀνδρὸς Βρεντεσίνου, κατέσχε. γενόμενος δὲ κύριος τῆς φρουρᾶς καὶ τῆς τοῦ σίτου παραθέσεως τούτῳ μὲν πρὸς τὸ παρὸν ἐχρήσατο, τοὺς δὲ παραληφθέντας ἄνδρας ἀβλαβεῖς μεθ’ ἑαυτοῦ προῆγε, δεῖγμα βουλόμενος ἐκφέρειν τῆς σφετέρας προαιρέσεως πρὸς τὸ μὴ δεδιότας ἀπελπίζειν τὴν παρ’ αὐτοῦ σωτηρίαν τοὺς ὑπὸ τῶν καιρῶν καταλαμβανομένους. τὸν δὲ προδότην ἐτίμησε μεγαλείως, ἐκκαλέσασθαι σπουδάζων τοὺς ἐπὶ πραγμάτων ταττομένους πρὸς τὰς Καρχηδονίων ἐλπίδας. μετὰ δὲ ταῦτα συνθεωρήσας τινὰς τῶν Κελτῶν, οἳ κατῴκουν μεταξὺ τοῦ Πάδου καὶ τοῦ Τρεβία ποταμοῦ, πεποιημένους μὲν καὶ πρὸς αὑτὸν φιλίαν, διαπεμπομένους δὲ καὶ πρὸς Ῥωμαίους καὶ πεπεισμένους τῷ τοιούτῳ τρόπῳ τὴν παρ’ ἀμφοῖν ἀσφάλειαν αὑτοῖς ὑπάρξειν, ἐξαποστέλλει πεζοὺς μὲν δισχιλίους, ἱππεῖς δὲ Κελτοὺς καὶ Νομάδας εἰς χιλίους, προστάξας ἐπιδραμεῖν αὐτῶν τὴν χώραν. τῶν δὲ πραξάντων τὸ προσταχθὲν καὶ πολλὴν περιβαλομένων λείαν, εὐθέως οἱ Κελτοὶ παρῆσαν ἐπὶ τὸν χάρακα τῶν Ῥωμαίων, δεόμενοι σφίσι βοηθεῖν. Τεβέριος δὲ καὶ πάλαι ζητῶν ἀφορμὴν τοῦ πράττειν τότε λαβὼν πρόφασιν ἐξαπέστειλε τῶν μὲν ἱππέων τὸ πλεῖστον μέρος, πεζοὺς δὲ σὺν τούτοις ἀκοντιστὰς εἰς χιλίους. σπουδῇ δὲ τούτων προσμιξάντων πέραν τοῦ Τρεβία καὶ διαμαχομένων τοῖς πολεμίοις ὑπὲρ τῆς λείας, ἐτράπησαν οἱ Κελτοὶ σὺν τοῖς Νομάσι καὶ τὴν ἀποχώρησιν ἐπὶ τὸν ἑαυτῶν ἐποιοῦντο χάρακα. ταχὺ δὲ συννοήσαντες τὸ γινόμενον οἱ προκαθήμενοι τῆς τῶν Καρχηδονίων παρεμβολῆς ἐντεῦθεν ταῖς ἐφεδρείαις ἐβοήθουν τοῖς πιεζομένοις· οὗ γενομένου τραπέντες οἱ Ῥωμαῖοι πάλιν ἐποιοῦντο τὴν ἀπόλυσιν εἰς τὴν ἑαυτῶν παρεμβολήν. Τεβέριος δὲ συνορῶν τὸ γινόμενον πάντας ἐπαφῆκε τοὺς ἵππους καὶ τοὺς ἀκοντιστάς. τούτου δὲ συμπεσόντος αὖθις ἐγκλίναντες οἱ Κελτοὶ πρὸς τὴν ἑαυτῶν ἀσφάλειαν ἀπεχώρουν. ὁ δὲ στρατηγὸς τῶν Καρχηδονίων ἀπαράσκευος ὢν πρὸς τὸ κρίνειν τὰ ὅλα καὶ νομίζων δεῖν μηδέποτε χωρὶς προθέσεως μηδ’ ἐκ πάσης ἀφορμῆς ποιεῖσθαι τοὺς ὁλοσχερεῖς κινδύνους, ὅπερ εἶναι φατέον ἡγεμόνος ἔργον ἀγαθοῦ, τότε μὲν ἐπέσχε τοὺς παρ’ αὑτοῦ συνεγγίσαντας τῷ χάρακι καὶ στῆναι μὲν ἐκ μεταβολῆς ἠνάγκασε, διώκειν δὲ καὶ συμπλέκεσθαι τοῖς πολεμίοις ἐκώλυσε, διὰ τῶν ὑπηρετῶν καὶ σαλπιγκτῶν ἀνακαλούμενος. οἱ δὲ Ῥωμαῖοι βραχὺν ἐπισχόντες χρόνον ἀνέλυσαν, ὀλίγους μὲν αὑτῶν ἀποβαλόντες, πλείους δὲ τῶν Καρχηδονίων διεφθαρκότες.", "st": "3.69"}, {"sp": "N", "t": "ὁ δὲ Τεβέριος μετεωρισθεὶς καὶ περιχαρὴς γενόμενος ἐπὶ τῷ προτερήματι φιλοτίμως εἶχε πρὸς τὸ τὴν ταχίστην κρῖναι τὰ ὅλα. προέκειτο μὲν οὖν αὐτῷ κατὰ τὴν ἰδίαν γνώμην χρῆσθαι τοῖς παροῦσι διὰ τὸ τὸν Πόπλιον ἀρρωστεῖν· ὅμως δὲ βουλόμενος προσλαβέσθαι καὶ τὴν τοῦ συνάρχοντος γνώμην ἐποιεῖτο λόγους περὶ τούτων πρὸς αὐτόν. ὁ δὲ Πόπλιος τὴν ἐναντίαν εἶχε διάληψιν περὶ τῶν ἐνεστώτων· τὰ γὰρ στρατόπεδα χειμασκήσαντα βελτίω τὰ παρ’ αὑτῶν ὑπελάμβανε γενήσεσθαι, τήν τε τῶν Κελτῶν ἀθεσίαν οὐκ ἐμμενεῖν ἐν τῇ πίστει, τῶν Καρχηδονίων ἀπραγούντων καὶ τὴν ἡσυχίαν ἀναγκαζομένων ἄγειν, ἀλλὰ καινοτομήσειν τι πάλιν κατ’ ἐκείνων. πρὸς δὲ τούτοις αὐτὸς ὑγιασθεὶς ἐκ τοῦ τραύματος ἀληθινὴν παρέξεσθαι χρείαν ἤλπιζε τοῖς κοινοῖς πράγμασιν. διὸ καὶ τοιούτοις χρώμενος λογισμοῖς μένειν ἠξίου τὸν Τεβέριον ἐπὶ τῶν ὑποκειμένων. ὁ δὲ προειρημένος ᾔδει μὲν ἕκαστα τούτων ἀληθινῶς λεγόμενα καὶ δεόντως, ὑπὸ δὲ τῆς φιλοδοξίας ἐλαυνόμενος καὶ καταπιστεύων τοῖς πράγμασι παραλόγως ἔσπευδεν κρῖναι δι’ αὑτοῦ τὰ ὅλα καὶ μήτε τὸν Πόπλιον δύνασθαι παρατυχεῖν τῇ μάχῃ μήτε τοὺς ἐπικαθισταμένους στρατηγοὺς φθάσαι παραλαβόντας τὴν ἀρχήν· οὗτος γὰρ ἦν ὁ χρόνος. διόπερ οὐ τὸν τῶν πραγμάτων καιρὸν ἐκλεγόμενος ἀλλὰ τὸν ἴδιον ἔμελλε τοῦ δέοντος σφαλήσεσθαι προφανῶς. ὁ δ’ Ἀννίβας παραπλησίους ἔχων ἐπινοίας Ποπλίῳ περὶ τῶν ἐνεστώτων κατὰ τοὐναντίον ἔσπευδε συμβαλεῖν τοῖς πολεμίοις, θέλων μὲν πρῶτον ἀκεραίοις ἀποχρήσασθαι ταῖς τῶν Κελτῶν ὁρμαῖς, δεύτερον ἀνασκήτοις καὶ νεοσυλλόγοις συμβαλεῖν τοῖς τῶν Ῥωμαίων στρατοπέδοις, τρίτον ἀδυνατοῦντος ἔτι τοῦ Ποπλίου ποιήσασθαι τὸν κίνδυνον, τὸ δὲ μέγιστον, πράττειν τι καὶ μὴ προΐεσθαι διὰ κενῆς τὸν χρόνον. τῷ γὰρ εἰς ἀλλοτρίαν καθέντι χώραν στρατόπεδα καὶ παραδόξοις ἐγχειροῦντι πράγμασιν εἷς τρόπος ἐστὶν οὗτος σωτηρίας, τὸ συνεχῶς καινοποιεῖν ἀεὶ τὰς τῶν συμμάχων ἐλπίδας. Ἀννίβας μὲν οὖν εἰδὼς τὴν ἐσομένην ὁρμὴν τοῦ Τεβερίου πρὸς τούτοις ἦν.", "st": "3.70"}, {"sp": "N", "t": "πάλαι δὲ συνεωρακὼς μεταξὺ τῶν στρατοπέδων τόπον ἐπίπεδον μὲν καὶ ψιλόν, εὐφυῆ δὲ πρὸς ἐνέδραν διά τι ῥεῖθρον ἔχον ὀφρῦν, ἐπὶ δὲ ταύτης ἀκάνθας καὶ βάτους συνεχεῖς ἐπιπεφυκότας, ἐγίνετο πρὸς τῷ στρατηγεῖν τοὺς ὑπεναντίους. ἔμελλεν δ’ εὐχερῶς λήσειν· οἱ γὰρ Ῥωμαῖοι πρὸς μὲν τοὺς ὑλώδεις τόπους ὑπόπτως εἶχον διὰ τὸ τοὺς Κελτοὺς ἀεὶ τιθέναι τὰς ἐνέδρας ἐν τοῖς τοιούτοις χωρίοις, τοῖς δ’ ἐπιπέδοις καὶ ψιλοῖς ἀπεπίστευον, οὐκ εἰδότες ὅτι καὶ πρὸς τὸ λαθεῖν καὶ πρὸς τὸ μηδὲν παθεῖν τοὺς ἐνεδρεύσαντας εὐφυέστεροι τυγχάνουσιν ὄντες τῶν ὑλωδῶν διὰ τὸ δύνασθαι μὲν ἐκ πολλοῦ προορᾶν πάντα τοὺς ἐνεδρεύοντας, εἶναι δ’ ἐπιπροσθήσεις ἱκανὰς ἐν τοῖς πλείστοις τόποις. τὸ γὰρ τυχὸν ῥεῖθρον μετὰ βραχείας ὀφρύος, ποτὲ δὲ κάλαμοι καὶ πτέρεις καί τι γένος ἀκανθῶν, οὐ μόνον πεζοὺς ἀλλὰ καὶ τοὺς ἱππεῖς ἐνίοτε δύναται κρύπτειν, ἐὰν βραχέα τις προνοηθῇ τοῦ τὰ μὲν ἐπίσημα τῶν ὅπλων ὕπτια τιθέναι πρὸς τὴν γῆν, τὰς δὲ περικεφαλαίας ὑποτιθέναι τοῖς ὅπλοις. πλὴν ὅ γε τῶν Καρχηδονίων στρατηγὸς κοινολογηθεὶς Μάγωνι τἀδελφῷ καὶ τοῖς συνέδροις περὶ τοῦ μέλλοντος ἀγῶνος, συγκατατιθεμένων αὐτῷ πάντων ταῖς ἐπιβολαῖς, ἅμα τῷ δειπνοποιήσασθαι τὸ στρατόπεδον ἀνακαλεσάμενος Μάγωνα τὸν ἀδελφόν, ὄντα νέον μὲν ὁρμῆς δὲ πλήρη καὶ παιδομαθῆ περὶ τὰ πολεμικά, συνέστησε τῶν ἱππέων ἄνδρας ἑκατὸν καὶ πεζοὺς τοὺς ἴσους. ἔτι δὲ τῆς ἡμέρας οὔσης ἐξ ὅλου τοῦ στρατοπέδου σημηνάμενος τοὺς εὐρωστοτάτους παρηγγέλκει δειπνοποιησαμένους ἥκειν ἐπὶ τὴν αὑτοῦ σκηνήν. παρακαλέσας δὲ καὶ παραστήσας τούτοις τὴν πρέπουσαν ὁρμὴν τῷ καιρῷ παρήγγελλε δέκα τοὺς ἀνδρωδεστάτους ἕκαστον ἐπιλεξάμενον ἐκ τῶν ἰδίων τάξεων ἥκειν εἴς τινα τόπον τακτὸν ἤδη τῆς στρατοπεδείας. τῶν δὲ πραξάντων τὸ συνταχθέν, τούτους μὲν ὄντας ἱππεῖς χιλίους καὶ πεζοὺς ἄλλους τοσούτους ἐξαπέστειλε νυκτὸς εἰς τὴν ἐνέδραν, συστήσας ὁδηγοὺς καὶ τἀδελφῷ διαταξάμενος περὶ τοῦ καιροῦ τῆς ἐπιθέσεως· αὐτὸς δ’ ἅμα τῷ φωτὶ τοὺς Νομαδικοὺς ἱππεῖς συναγαγών, ὄντας φερεκάκους διαφερόντως, παρεκάλεσε καί τινας δωρεὰς ἐπαγγειλάμενος τοῖς ἀνδραγαθήσασι προσέταξε πελάσαντας τῷ τῶν ἐναντίων χάρακι κατὰ σπουδὴν ἐπιδιαβαίνειν τὸν ποταμὸν καὶ προσακροβολιζομένους κινεῖν τοὺς πολεμίους, βουλόμενος ἀναρίστους καὶ πρὸς τὸ μέλλον ἀπαρασκεύους λαβεῖν τοὺς ὑπεναντίους. τοὺς δὲ λοιποὺς ἡγεμόνας ἁθροίσας ὁμοίως παρεκάλεσε πρὸς τὸν κίνδυνον καὶ πᾶσιν ἀριστοποιεῖσθαι παρήγγειλε καὶ περὶ τὴν τῶν ὅπλων καὶ τῶν ἵππων γίνεσθαι θεραπείαν.", "st": "3.71"}, {"sp": "N", "t": "ὁ δὲ Τεβέριος ἅμα τῷ συνιδεῖν ἐγγίζοντας τοὺς Νομαδικοὺς ἱππεῖς παραυτίκα μὲν αὐτὴν τὴν ἵππον ἐξαπέστελλε, προστάξας ἔχεσθαι καὶ συμπλέκεσθαι τοῖς πολεμίοις. ἑξῆς δὲ τούτοις ἐξέπεμπε τοὺς πεζακοντιστὰς εἰς ἑξακισχιλίους· ἐκίνει δὲ καὶ τὴν λοιπὴν δύναμιν ἐκ τοῦ χάρακος, ὡς ἐξ ἐπιφανείας κριθησομένων τῶν ὅλων, ἐπαιρόμενος τῷ τε πλήθει τῶν ἀνδρῶν καὶ τῷ γεγονότι τῇ προτεραίᾳ περὶ τοὺς ἱππεῖς εὐημερήματι. οὔσης δὲ τῆς ὥρας περὶ χειμερινὰς τροπὰς καὶ τῆς ἡμέρας νιφετώδους καὶ ψυχρᾶς διαφερόντως, τῶν δ’ ἀνδρῶν καὶ τῶν ἵππων σχεδὸν ὡς εἰπεῖν ἁπάντων ἀναρίστων ἐκπεπορευμένων, τὸ μὲν πρῶτον ὁρμῇ καὶ προθυμίᾳ περιῆν τὸ πλῆθος· ἐπιγενομένης δὲ τῆς τοῦ Τρεβία ποταμοῦ διαβάσεως, καὶ προσαναβεβηκότος τῷ ῥεύματι διὰ τὸν ἐν τῇ νυκτὶ γενόμενον ἐν τοῖς ὑπὲρ τὰ στρατόπεδα τόποις ὄμβρον, μόλις ἕως τῶν μασθῶν οἱ πεζοὶ βαπτιζόμενοι διέβαινον· ἐξ ὧν ἐκακοπάθει τὸ στρατόπεδον ὑπό τε τοῦ ψύχους καὶ τῆς ἐνδείας, ὡς ἂν ἤδη καὶ τῆς ἡμέρας προβαινούσης. οἱ δὲ Καρχηδόνιοι κατὰ σκηνὰς βεβρωκότες καὶ πεπωκότες καὶ τοὺς ἵππους ἡτοιμακότες ἠλείφοντο καὶ καθωπλίζοντο περὶ τὰ πυρὰ πάντες. Ἀννίβας δὲ τὸν καιρὸν ἐπιτηρῶν ἅμα τῷ συνιδεῖν διαβεβηκότας τοὺς Ῥωμαίους τὸν ποταμὸν προβαλόμενος ἐφεδρείαν τοὺς λογχοφόρους καὶ Βαλιαρεῖς, ὄντας εἰς ὀκτακισχιλίους, ἐξῆγε τὴν δύναμιν. καὶ προαγαγὼν ὡς ὀκτὼ στάδια πρὸ τῆς στρατοπεδείας τοὺς μὲν πεζοὺς ἐπὶ μίαν εὐθεῖαν παρενέβαλε, περὶ δισμυρίους ὄντας τὸν ἀριθμόν, Ἴβηρας καὶ Κελτοὺς καὶ Λίβυας, τοὺς δ’ ἱππεῖς διελὼν ἐφ’ ἑκάτερον παρέστησε τὸ κέρας, πλείους ὄντας μυρίων σὺν τοῖς παρὰ τῶν Κελτῶν συμμάχοις, τὰ δὲ θηρία μερίσας πρὸ τῶν κεράτων δι’ ἀμφοτέρων προεβάλετο. Τεβέριος δὲ κατὰ τὸν αὐτὸν καιρὸν τοὺς μὲν ἱππεῖς ἀνεκαλεῖτο, θεωρῶν οὐκ ἔχοντας ὅ,τι χρήσονται τοῖς ὑπεναντίοις διὰ τὸ τοὺς Νομάδας ἀποχωρεῖν μὲν εὐχερῶς καὶ σποράδην, ἐπικεῖσθαι δὲ πάλιν ἐκ μεταβολῆς τολμηρῶς καὶ θρασέως· τὸ γὰρ τῆς Νομαδικῆς μάχης ἴδιόν ἐστι τοῦτο· τοὺς δὲ πεζοὺς παρενέβαλε κατὰ τὰς εἰθισμένας παρ’ αὐτοῖς τάξεις, ὄντας τοὺς μὲν Ῥωμαίους εἰς μυρίους ἑξακισχιλίους, τοὺς δὲ συμμάχους εἰς δισμυρίους. τὸ γὰρ τέλειον στρατόπεδον παρ’ αὐτοῖς πρὸς τὰς ὁλοσχερεῖς ἐπιβολὰς ἐκ τοσούτων ἀνδρῶν ἐστιν, ὅταν ὁμοῦ τοὺς ὑπάτους ἑκατέρους οἱ καιροὶ συνάγωσιν. μετὰ δὲ ταῦτα τοὺς ἱππεῖς ἐφ’ ἑκάτερον θεὶς τὸ κέρας, ὄντας εἰς τετρακισχιλίους, ἐπῄει τοῖς ὑπεναντίοις σοβαρῶς, ἐν τάξει καὶ βάδην ποιούμενος τὴν ἔφοδον.", "st": "3.72"}, {"sp": "N", "t": "ἤδη δὲ σύνεγγυς ὄντων ἀλλήλοις, συνεπλέκησαν οἱ προκείμενοι τῶν δυνάμεων εὔζωνοι. τούτου δὲ συμβάντος οἱ μὲν Ῥωμαῖοι κατὰ πολλοὺς τρόπους ἠλαττοῦντο, τοῖς δὲ Καρχηδονίοις ὑπερδέξιον γίνεσθαι συνέβαινε τὴν χρείαν, ἅτε δὴ τῶν μὲν Ῥωμαίων πεζακοντιστῶν κακοπαθούντων ἐξ ὄρθρου καὶ προεμένων τὰ πλεῖστα βέλη κατὰ τὴν πρὸς τοὺς Νομάδας συμπλοκήν, τῶν δὲ καταλειπομένων βελῶν ἠχρειωμένων αὐτοῖς διὰ τὴν συνέχειαν τῆς νοτίδος. παραπλήσια δὲ τούτοις συνέβαινε καὶ περὶ τοὺς ἱππεῖς γίνεσθαι καὶ περὶ τὸ σύμπαν αὐτοῖς στρατόπεδον. περί γε μὴν τοὺς Καρχηδονίους ὑπῆρχε τἀναντία τούτων· ἀκμαῖοι γὰρ παρατεταγμένοι καὶ νεαλεῖς ἀεὶ πρὸς τὸ δέον εὐχρήστως καὶ προθύμως εἶχον. διόπερ ἅμα τῷ δέξασθαι διὰ τῶν διαστημάτων τοὺς προκινδυνεύοντας καὶ συμπεσεῖν τὰ βαρέα τῶν ὅπλων ἀλλήλοις, οἱ μὲν ἱππεῖς οἱ τῶν Καρχηδονίων εὐθέως ἀπ’ ἀμφοῖν τοῖν κεράτοιν ἐπίεζον τοὺς ὑπεναντίους, ὡς ἂν τῷ πλήθει πολὺ διαφέροντες καὶ ταῖς ἀκμαῖς αὐτῶν τε καὶ τῶν ἵππων διὰ τὴν προειρημένην ἀκεραιότητα περὶ τὴν ἔξοδον· τοῖς δὲ Ῥωμαίοις τῶν ἱππέων ὑποχωρησάντων καὶ ψιλωθέντων τῶν τῆς φάλαγγος κεράτων, οἵ τε λογχοφόροι τῶν Καρχηδονίων καὶ τὸ τῶν Νομάδων πλῆθος ὑπεραίροντες τοὺς προτεταγμένους τῶν ἰδίων καὶ πρὸς τὰ κέρατα προσπίπτοντες τοῖς Ῥωμαίοις πολλὰ καὶ κακὰ διειργάζοντο καὶ μάχεσθαι τοῖς κατὰ πρόσωπον οὐκ εἴων. οἱ δ’ ἐν τοῖς βαρέσιν ὅπλοις παρ’ ἀμφοῖν τὰς πρώτας ἔχοντες καὶ μέσας τῆς ὅλης παρεμβολῆς τάξεις ἐπὶ πολὺν χρόνον ἐμάχοντο συστάδην, ἐφάμιλλον ποιούμενοι τὸν κίνδυνον.", "st": "3.73"}, {"sp": "N", "t": "ἐν ᾧ καιρῷ διαναστάντων τῶν ἐκ τῆς ἐνέδρας Νομάδων καὶ προσπεσόντων ἄφνω κατὰ νώτου τοῖς ἀγωνιζομένοις περὶ τὰ μέσα, μεγάλην ταραχὴν καὶ δυσχρηστίαν συνέβαινε γίνεσθαι περὶ τὰς τῶν Ῥωμαίων δυνάμεις. τέλος δ’ ἀμφότερα τὰ κέρατα τῶν περὶ τὸν Τεβέριον πιεζούμενα κατὰ πρόσωπον μὲν ὑπὸ τῶν θηρίων, πέριξ δὲ καὶ κατὰ τὰς ἐκ τῶν πλαγίων ἐπιφανείας ὑπὸ τῶν εὐζώνων, ἐτράπησαν καὶ συνωθοῦντο κατὰ τὸν διωγμὸν πρὸς τὸν ὑποκείμενον ποταμόν. τούτου δὲ συμβάντος οἱ κατὰ μέσον τὸν κίνδυνον ταχθέντες τῶν Ῥωμαίων οἱ μὲν κατόπιν ἐφεστῶτες ὑπὸ τῶν ἐκ τῆς ἐνέδρας προσπεσόντων ἀπώλλυντο καὶ κακῶς ἔπασχον, οἱ δὲ περὶ τὰς πρώτας χώρας ἐπαναγκασθέντες ἐκράτησαν τῶν Κελτῶν καὶ μέρους τινὸς τῶν Λιβύων καὶ πολλοὺς αὐτῶν ἀποκτείναντες διέκοψαν τὴν τῶν Καρχηδονίων τάξιν. θεωροῦντες δὲ τοὺς ἀπὸ τῶν ἰδίων κεράτων ἐκπεπιεσμένους, τὸ μὲν ἐπιβοηθεῖν τούτοις ἢ πάλιν εἰς τὴν ἑαυτῶν ἀπιέναι παρεμβολὴν ἀπέγνωσαν, ὑφορώμενοι μὲν τὸ πλῆθος τῶν ἱππέων, κωλυόμενοι δὲ διὰ τὸν ποταμὸν καὶ τὴν ἐπιφορὰν καὶ συστροφὴν τοῦ κατὰ κεφαλὴν ὄμβρου. τηροῦντες δὲ τὰς τάξεις ἁθρόοι μετ’ ἀσφαλείας ἀπεχώρησαν εἰς Πλακεντίαν, ὄντες οὐκ ἐλάττους μυρίων. τῶν δὲ λοιπῶν οἱ μὲν πλεῖστοι περὶ τὸν ποταμὸν ἐφθάρησαν ὑπό τε τῶν θηρίων καὶ τῶν ἱππέων, οἱ δὲ διαφυγόντες τῶν πεζῶν καὶ τὸ πλεῖστον μέρος τῶν ἱππέων πρὸς τὸ προειρημένον σύστημα ποιούμενοι τὴν ἀποχώρησιν ἀνεκομίσθησαν ἅμα τούτοις εἰς Πλακεντίαν. τὸ δὲ τῶν Καρχηδονίων στρατόπεδον ἕως τοῦ ποταμοῦ καταδιῶξαν τοὺς πολεμίους, ὑπὸ δὲ τοῦ χειμῶνος οὐκέτι δυνάμενον πορρωτέρω προβαίνειν ἐπανῆλθε πάλιν εἰς τὴν παρεμβολήν. καὶ πάντες ἐπὶ μὲν τῇ μάχῃ περιχαρεῖς ἦσαν, ὡς κατωρθωκότες· συνέβαινε γὰρ ὀλίγους μὲν τῶν Ἰβήρων καὶ Λιβύων, τοὺς δὲ πλείους ἀπολωλέναι τῶν Κελτῶν· ὑπὸ δὲ τῶν ὄμβρων καὶ τῆς ἐπιγινομένης χιόνος οὕτως διετίθεντο δεινῶς ὥστε τὰ μὲν θηρία διαφθαρῆναι πλὴν ἑνός, πολλοὺς δὲ καὶ τῶν ἀνδρῶν ἀπόλλυσθαι καὶ τῶν ἵππων διὰ τὸ ψῦχος.", "st": "3.74"}, {"sp": "N", "t": "ὁ δὲ Τεβέριος εἰδὼς μὲν τὰ συμβεβηκότα, βουλόμενος δὲ κατὰ δύναμιν ἐπικρύπτεσθαι τοὺς ἐν τῇ Ῥώμῃ τὸ γεγονὸς ἔπεμψε τοὺς ἀπαγγελοῦντας ὅτι μάχης γενομένης τὴν νίκην αὐτῶν ὁ χειμὼν ἀφείλετο. οἱ δὲ Ῥωμαῖοι παραυτίκα μὲν ἐπίστευον τοῖς προσπίπτουσιν· μετ’ οὐ πολὺ δὲ πυνθανόμενοι τοὺς μὲν Καρχηδονίους καὶ τὴν παρεμβολὴν τὴν αὑτῶν τηρεῖν καὶ τοὺς Κελτοὺς πάντας ἀπονενευκέναι πρὸς τὴν ἐκείνων φιλίαν, τοὺς δὲ παρ’ αὑτῶν ἀπολελοιπότας τὴν παρεμβολὴν ἐκ τῆς μάχης ἀνακεχωρηκέναι καὶ συνηθροῖσθαι πάντας εἰς τὰς πόλεις καὶ χορηγεῖσθαι δὲ τοῖς ἀναγκαίοις ἐκ θαλάττης ἀνὰ τὸν Πάδον ποταμόν, καὶ λίαν σαφῶς ἔγνωσαν τὰ γεγονότα περὶ τὸν κίνδυνον. διὸ καὶ παραδόξου φανέντος αὐτοῖς τοῦ πράγματος, περὶ τὰς λοιπὰς παρασκευὰς διαφερόντως ἐγίνοντο καὶ περὶ φυλακὴν τῶν προκειμένων τόπων, πέμποντες εἰς Σαρδόνα καὶ Σικελίαν στρατόπεδα, πρὸς δὲ τούτοις εἰς Τάραντα προφυλακὰς καὶ τῶν ἄλλων τόπων εἰς τοὺς εὐκαίρους· παρεσκεύασαν δὲ καὶ ναῦς ἑξήκοντα πεντήρεις. Γνάιος δὲ Σερουίλιος καὶ Γάιος Φλαμίνιος, οἵπερ ἔτυχον ὕπατοι τότε καθεσταμένοι, συνῆγον τοὺς συμμάχους καὶ κατέγραφον τὰ παρ’ αὑτοῖς στρατόπεδα. παρῆγον δὲ καὶ τὰς ἀγορὰς τὰς μὲν εἰς Ἀρίμινον τὰς δ’ εἰς Τυρρηνίαν, ὡς ἐπὶ τούτοις ποιησόμενοι τοῖς τόποις τὴν ἔξοδον. ἔπεμψαν δὲ καὶ πρὸς Ἱέρωνα περὶ βοηθείας, ὃς καὶ πεντακοσίους αὐτοῖς ἐξαπέστειλε Κρῆτας καὶ χιλίους πελτοφόρους· πάντα δὲ καὶ πανταχόθεν ἐνεργῶς ἡτοίμαζον. τότε γάρ εἰσι φοβερώτατοι Ῥωμαῖοι καὶ κοινῇ καὶ κατ’ ἰδίαν, ὅταν αὐτοὺς περιστῇ φόβος ἀληθινός.", "st": "3.75"}, {"sp": "N", "t": "κατὰ δὲ τοὺς αὐτοὺς καιροὺς Γνάιος Κορνήλιος ὁ καταλειφθεὶς ὑπὸ τἀδελφοῦ Ποπλίου στρατηγὸς ἐπὶ τῆς ναυτικῆς δυνάμεως, καθάπερ ἐπάνω προεῖπον, ἀναχθεὶς ἀπὸ τῶν τοῦ Ῥοδανοῦ στομάτων παντὶ τῷ στόλῳ προσέσχε τῆς Ἰβηρίας πρὸς τοὺς κατὰ τὸ καλούμενον Ἐμπόριον τόπους. ἀρξάμενος δ’ ἐντεῦθεν ἀποβάσεις ἐποιεῖτο καὶ τοὺς μὲν ἀπειθοῦντας ἐπολιόρκει τῶν τὴν παραλίαν κατοικούντων ἕως Ἴβηρος ποταμοῦ, τοὺς δὲ προσδεχομένους ἐφιλανθρώπει, τὴν ἐνδεχομένην ποιούμενος περὶ αὐτῶν προμήθειαν. ἀσφαλισάμενος δὲ τοὺς προσκεχωρηκότας τῶν παραθαλαττίων προῆγε παντὶ τῷ στρατεύματι, ποιούμενος τὴν πορείαν εἰς τὴν μεσόγαιον· πολὺ γὰρ ἤδη καὶ τὸ συμμαχικὸν ἡθροίκει τῶν Ἰβήρων. ἅμα δὲ προϊὼν ἃς μὲν προσήγετο τὰς δὲ κατεστρέφετο τῶν πόλεων. τῶν δὲ Καρχηδονίων, οὓς ἔχων ἐπὶ τούτων ἀπελείφθη τῶν τόπων Ἄννων, ἀντιστρατοπεδευσάντων αὐτοῖς περὶ πόλιν προσαγορευομένην Κίσσαν, συμβαλὼν ὁ Γνάιος ἐκ παρατάξεως καὶ νικήσας τῇ μάχῃ πολλῶν μὲν χρημάτων ἐγένετ’ ἐγκρατής, ὡς ἂν ἁπάσης τῆς ἀποσκευῆς τῶν εἰς Ἰταλίαν ὁρμησάντων παρὰ τούτοις ἀπολελειμμένης, πάντας δὲ τοὺς ἐντὸς Ἴβηρος ποταμοῦ συμμάχους ἐποιήσατο καὶ φίλους, ζωγρίᾳ δὲ τόν τε τῶν Καρχηδονίων στρατηγὸν Ἄννωνα καὶ τὸν τῶν Ἰβήρων Ἀνδοβάλην ἔλαβε. τοῦτον δὲ συνέβαινε τύραννον μὲν εἶναι τῶν κατὰ τὴν μεσόγαιον τόπων, εὔνουν δὲ διαφερόντως ἀεί ποτε Καρχηδονίοις. ταχὺ δὲ συνεὶς τὸ γεγονὸς Ἀσδρούβας ἧκε παραβοηθῶν διαβὰς τὸν Ἴβηρα ποταμόν. καὶ καταμαθὼν ἀπολελειμμένους τοὺς ἀπὸ τοῦ στόλου τῶν Ῥωμαίων, ῥᾳθύμως καὶ κατατεθαρρηκότως ἀναστρεφομένους διὰ τὸ προτέρημα τῶν πεζικῶν στρατοπέδων, παραλαβὼν ἀπὸ τῆς ἑαυτοῦ δυνάμεως πεζοὺς μὲν εἰς ὀκτακισχιλίους ἱππεῖς δὲ περὶ χιλίους, καὶ καταλαβὼν ἐσκεδασμένους κατὰ τῆς χώρας τοὺς ἀπὸ τῶν πλοίων, πολλοὺς μὲν αὐτῶν ἀπέκτεινεν, τοὺς δὲ λοιποὺς ἠνάγκασε φυγεῖν ἐπὶ τὰς ναῦς. οὗτος μὲν οὖν ἀναχωρήσας καὶ διαβὰς αὖθις τὸν Ἴβηρα ποταμὸν ἐγίνετο περὶ παρασκευὴν καὶ φυλακὴν τῶν ἐντὸς τοῦ ποταμοῦ τόπων, ποιούμενος τὴν παραχειμασίαν ἐν Καινῇ πόλει. ὁ δὲ Γνάιος συνάψας τῷ στόλῳ καὶ τοὺς αἰτίους τῶν συμβεβηκότων κατὰ τοὺς παρ’ αὐτοῖς ἐθισμοὺς κολάσας, τὸ λοιπὸν ἤδη συναγαγὼν ἐπὶ ταὐτὸ τήν τε πεζὴν καὶ τὴν ναυτικὴν στρατιὰν ἐν Ταρράκωνι τὴν παραχειμασίαν ἐποιεῖτο. διαδοὺς δὲ τὴν λείαν ἴσως τοῖς στρατιώταις μεγάλην εὔνοιαν καὶ προθυμίαν ἐνειργάσατο πρὸς τὸ μέλλον.", "st": "3.76"}, {"sp": "N", "t": "καὶ τὰ μὲν κατὰ τὴν Ἰβηρίαν ἐν τούτοις ἦν. ἐνισταμένης δὲ τῆς ἐαρινῆς ὥρας, Γάιος μὲν Φλαμίνιος ἀναλαβὼν τὰς αὑτοῦ δυνάμεις προῆγε διὰ Τυρρηνίας καὶ κατεστρατοπέδευσε πρὸ τῆς τῶν Ἀρρητίνων πόλεως, Γνάιος δὲ Σερουίλιος τοὔμπαλιν ὡς ἐπ’ Ἀριμίνου, ταύτῃ παρατηρήσων τὴν εἰσβολὴν τῶν ὑπεναντίων. Ἀννίβας δὲ παραχειμάζων ἐν τῇ Κελτικῇ τοὺς μὲν Ῥωμαίους τῶν ἐκ τῆς μάχης αἰχμαλώτων ἐν φυλακῇ συνεῖχεν, τὰ μέτρια τῶν ἐπιτηδείων διδούς, τοὺς δὲ συμμάχους αὐτῶν τὸ μὲν πρῶτον ἐν τῇ πάσῃ φιλανθρωπίᾳ διεξῆγεν, μετὰ δὲ ταῦτα συναγαγὼν παρεκάλει, φάσκων οὐκ ἐκείνοις ἥκειν πολεμήσων, ἀλλὰ Ῥωμαίοις ὑπὲρ ἐκείνων. διόπερ ἔφη δεῖν αὐτούς, ἐὰν ὀρθῶς φρονῶσιν, ἀντέχεσθαι τῆς πρὸς αὑτὸν φιλίας. παρεῖναι γὰρ πρῶτον μὲν τὴν ἐλευθερίαν ἀνακτησόμενος Ἰταλιώταις, ὁμοίως δὲ τὰς πόλεις καὶ τὴν χώραν, ἣν ὑπὸ Ῥωμαίων ἀπολωλεκότες ἕκαστοι τυγχάνουσι, συνανασώσων. ταῦτα δ’ εἰπὼν ἀφῆκε πάντας χωρὶς λύτρων εἰς τὴν οἰκείαν, βουλόμενος ἅμα μὲν προκαλεῖσθαι διὰ τοιούτου τρόπου πρὸς αὑτὸν τοὺς κατοικοῦντας τὴν Ἰταλίαν, ἅμα δ’ ἀπαλλοτριοῦν τῆς πρὸς Ῥωμαίους εὐνοίας, ἐρεθίζειν δὲ τοὺς δοκοῦντας πόλεσιν ἢ λιμέσιν ἠλαττῶσθαί τι διὰ τῆς Ῥωμαίων ἀρχῆς.", "st": "3.77"}, {"sp": "N", "t": "ἐχρήσατο δέ τινι καὶ Φοινικικῷ στρατηγήματι τοιούτῳ κατὰ τὴν παραχειμασίαν. ἀγωνιῶν γὰρ τὴν ἀθεσίαν τῶν Κελτῶν καὶ τὰς ἐπιβουλὰς τὰς περὶ τὸ σῶμα διὰ τὸ πρόσφατον τῆς πρὸς αὐτοὺς συστάσεως κατεσκευάσατο περιθετὰς τρίχας, ἁρμοζούσας ταῖς κατὰ τὰς ὁλοσχερεῖς διαφορὰς τῶν ἡλικιῶν ἐπιπρεπείαις, καὶ ταύταις ἐχρῆτο συνεχῶς μετατιθέμενος· ὁμοίως δὲ καὶ τὰς ἐσθῆτας μετελάμβανε τὰς καθηκούσας ἀεὶ ταῖς περιθεταῖς. δι’ ὧν οὐ μόνον τοῖς αἰφνιδίως ἰδοῦσι δύσγνωστος ἦν, ἀλλὰ καὶ τοῖς ἐν συνηθείᾳ γεγονόσιν. θεωρῶν δὲ τοὺς Κελτοὺς δυσχεραίνοντας ἐπὶ τῷ τὸν πόλεμον ἐν τῇ παρ’ αὑτῶν χώρᾳ λαμβάνειν τὴν τριβήν, σπεύδοντας δὲ καὶ μετεώρους ὄντας εἰς τὴν πολεμίαν, προφάσει μὲν διὰ τὴν πρὸς Ῥωμαίους ὀργήν, τὸ δὲ πλεῖον διὰ τὰς ὠφελείας, ἔκρινε τὴν ταχίστην ἀναζευγνύειν καὶ συνεκπληροῦν τὰς τῶν δυνάμεων ὁρμάς. διόπερ ἅμα τῷ τὴν ὥραν μεταβάλλειν πυνθανόμενος τῶν μάλιστα τῆς χώρας δοκούντων ἐμπειρεῖν τὰς μὲν ἄλλας ἐμβολὰς τὰς εἰς τὴν πολεμίαν μακρὰς εὕρισκε καὶ προδήλους τοῖς ὑπεναντίοις, τὴν δὲ διὰ τῶν ἑλῶν εἰς Τυρρηνίαν φέρουσαν δυσχερῆ μὲν σύντομον δὲ καὶ παράδοξον φανησομένην τοῖς περὶ τὸν Φλαμίνιον. ἀεὶ δέ πως οἰκεῖος ὢν τῇ φύσει τούτου τοῦ μέρους ταύτῃ προέθετο ποιεῖσθαι τὴν πορείαν. διαδοθείσης δὲ τῆς φήμης ἐν τῷ στρατοπέδῳ διότι μέλλει διά τινων ἑλῶν ἄγειν αὐτοὺς ὁ στρατηγός, πᾶς τις εὐλαβῶς εἶχε πρὸς τὴν πορείαν, ὑφορώμενος βάραθρα καὶ τοὺς λιμνώδεις τῶν τόπων.", "st": "3.78"}, {"sp": "N", "t": "Ἀννίβας δ’ ἐπιμελῶς ἐξητακὼς τεναγώδεις καὶ στερεοὺς ὑπάρχοντας τοὺς κατὰ τὴν δίοδον τόπους, ἀναζεύξας εἰς μὲν τὴν πρωτοπορείαν ἔθηκε τοὺς Λίβυας καὶ Ἴβηρας καὶ πᾶν τὸ χρησιμώτερον μέρος τῆς σφετέρας δυνάμεως, συγκαταμίξας αὐτοῖς τὴν ἀποσκευήν, ἵνα πρὸς τὸ παρὸν εὐπορῶσι τῶν ἐπιτηδείων· πρὸς γὰρ τὸ μέλλον εἰς τέλος ἀφροντίστως εἶχε περὶ παντὸς τοῦ σκευοφόρου, λογιζόμενος ὡς ἐὰν ἅψηται τῆς πολεμίας, ἡττηθεὶς μὲν οὐ προσδεήσεται τῶν ἀναγκαίων, κρατῶν δὲ τῶν ὑπαίθρων οὐκ ἀπορήσει τῶν ἐπιτηδείων. ἐπὶ δὲ τοῖς προειρημένοις ἐπέβαλε τοὺς Κελτούς, ἐπὶ δὲ πᾶσι τοὺς ἱππεῖς. ἐπιμελητὴν δὲ τῆς οὐραγίας τὸν ἀδελφὸν ἀπέλιπε Μάγωνα τῶν τε λοιπῶν χάριν καὶ μάλιστα τῆς τῶν Κελτῶν μαλακίας καὶ φυγοπονίας, ἵν’ ἐὰν κακοπαθοῦντες τρέπωνται πάλιν εἰς τοὐπίσω, κωλύῃ διὰ τῶν ἱππέων καὶ προσφέρῃ τὰς χεῖρας αὐτοῖς. οἱ μὲν οὖν Ἴβηρες καὶ Λίβυες δι’ ἀκεραίων τῶν ἑλῶν ποιούμενοι τὴν πορείαν μετρίως κακοπαθοῦντες ἤνυον, ἅτε καὶ φερέκακοι πάντες ὄντες καὶ συνήθεις ταῖς τοιαύταις ταλαιπωρίαις. οἱ δὲ Κελτοὶ δυσχερῶς μὲν εἰς τοὔμπροσθεν προύβαινον, τεταραγμένων καὶ διαπεπατημένων εἰς βάθος τῶν ἑλῶν, ἐπιπόνως δὲ καὶ ταλαιπώρως ὑπέμενον τὴν κακοπάθειαν, ἄπειροι πάσης τῆς τοιαύτης ὄντες κακουχίας. ἐκωλύοντο δὲ πάλιν ἀπονεύειν εἰς τοὐπίσω διὰ τοὺς ἐφεστῶτας αὐτοῖς ἱππεῖς. πάντες μὲν οὖν ἐκακοπάθουν καὶ μάλιστα διὰ τὴν ἀγρυπνίαν, ὡς ἂν ἑξῆς ἡμέρας τέτταρας καὶ τρεῖς νύκτας συνεχῶς δι’ ὕδατος ποιούμενοι τὴν πορείαν· διαφερόντως γε μὴν ἐπόνουν καὶ κατεφθείρονθ’ ὑπὲρ τοὺς ἄλλους οἱ Κελτοί. τῶν δ’ ὑποζυγίων αὐτοῦ τὰ πλεῖστα πίπτοντα διὰ τοὺς πηλοὺς ἀπώλλυντο, μίαν παρεχόμενα χρείαν ἐν τῷ πεσεῖν τοῖς ἀνθρώποις· καθεζόμενοι γὰρ ἐπ’ αὐτῶν καὶ τῶν σκευῶν σωρηδὸν ὑπὲρ τὸ ὑγρὸν ὑπερεῖχον καὶ τῷ τοιούτῳ τρόπῳ βραχὺ μέρος τῆς νυκτὸς ἀπεκοιμῶντο. οὐκ ὀλίγοι δὲ καὶ τῶν ἵππων τὰς ὁπλὰς ἀπέβαλον διὰ τὴν συνέχειαν τῆς διὰ τῶν πηλῶν πορείας. Ἀννίβας δὲ μόλις ἐπὶ τοῦ περιλειφθέντος θηρίου διεσώθη μετὰ πολλῆς ταλαιπωρίας, ὑπεραλγὴς ὢν διὰ τὴν βαρύτητα τῆς ἐπενεχθείσης ὀφθαλμίας αὐτῷ, δι’ ἣν καὶ τέλος ἐστερήθη τῆς μιᾶς ὄψεως, οὐκ ἐπιδεχομένου τοῦ καιροῦ καταμονὴν οὐδὲ θεραπείαν διὰ τὸ τῆς περιστάσεως ἀδύνατον.", "st": "3.79"}, {"sp": "N", "t": "διαπεράσας δὲ παραδόξως τοὺς ἑλώδεις τόπους καὶ καταλαβὼν ἐν Τυρρηνίᾳ τὸν Φλαμίνιον στρατοπεδεύοντα πρὸ τῆς τῶν Ἀρρητίνων πόλεως, τότε μὲν αὐτοῦ πρὸς τοῖς ἕλεσι κατεστρατοπέδευσε, βουλόμενος τήν τε δύναμιν ἀναλαβεῖν καὶ πολυπραγμονῆσαι τὰ περὶ τοὺς ὑπεναντίους καὶ τοὺς προκειμένους τῶν τόπων. πυνθανόμενος δὲ τὴν μὲν χώραν τὴν πρόσθεν πολλῆς γέμειν ὠφελείας, τὸν δὲ Φλαμίνιον ὀχλοκόπον μὲν καὶ δημαγωγὸν εἶναι τέλειον, πρὸς ἀληθινῶν δὲ καὶ πολεμικῶν πραγμάτων χειρισμὸν οὐκ εὐφυῆ, πρὸς δὲ τούτοις καταπεπιστευκέναι τοῖς σφετέροις πράγμασιν, συνελογίζετο διότι παραλλάξαντος αὐτοῦ τὴν ἐκείνων στρατοπεδείαν καὶ καθέντος εἰς τοὺς ἔμπροσθεν τόπους τὰ μὲν ἀγωνιῶν τὸν ἐπιτωθασμὸν τῶν ὄχλων οὐ δυνήσεται περιορᾶν δῃουμένην τὴν χώραν, τὰ δὲ κατηλγηκὼς παρέσται προχείρως εἰς πάντα τόπον ἑπόμενος, σπουδάζων δι’ αὑτοῦ ποιήσασθαι τὸ προτέρημα καὶ μὴ προσδέξασθαι τὴν παρουσίαν τοῦ τὴν ἴσην ἀρχὴν ἔχοντος. ἐξ ὧν πολλοὺς αὐτὸν ὑπελάμβανε παραδώσειν καιροὺς πρὸς ἐπίθεσιν. πάντα δ’ ἐμφρόνως ἐλογίζετο ταῦτα καὶ πραγματικῶς·", "st": "3.80"}, {"sp": "N", "t": "οὐ γὰρ εἰκὸς ἄλλως εἰπεῖν, ὡς εἴ τις οἴεται κυριώτερόν τι μέρος εἶναι στρατηγίας τοῦ γνῶναι τὴν προαίρεσιν καὶ φύσιν τοῦ τῶν ἐναντίων ἡγεμόνος, ἀγνοεῖ καὶ τετύφωται. καθάπερ γὰρ ἐπὶ τῶν κατ’ ἄνδρα καὶ ζυγὸν ἀγωνισμάτων δεῖ τὸν μέλλοντα νικᾶν συνθεωρεῖν πῶς δυνατὸν ἐφικέσθαι τοῦ σκοποῦ καὶ τί γυμνὸν ἢ ποῖον ἔξοπλον μέρος φαίνεται τῶν ἀνταγωνιστῶν, οὕτως χρὴ καὶ τοὺς ὑπὲρ τῶν ὅλων προεστῶτας σκοπεῖν οὐχ ὅπου τι τοῦ σώματος γυμνόν, ἀλλὰ ποῦ τῆς ψυχῆς εὐχείρωτόν τι παραφαίνεται τοῦ τῶν ἐναντίων ἡγεμόνος, ἐπειδὴ πολλοὶ μὲν διὰ ῥᾳθυμίαν καὶ τὴν σύμπασαν ἀργίαν οὐ μόνον τὰς κοινὰς πράξεις, ἀλλὰ καὶ τοὺς ἰδίους καταπροΐενται βίους ἄρδην, πολλοὶ δὲ διὰ τὴν πρὸς τὸν οἶνον ἐπιθυμίαν οὐδ’ ὑπνῶσαι δύνανται χωρὶς ἀλλοιώσεως καὶ μέθης, ἔνιοι δὲ διὰ τὰς τῶν ἀφροδισίων ὁρμὰς καὶ τὴν ἐν τούτοις ἔκπληξιν οὐ μόνον πόλεις καὶ βίους ἀναστάτους πεποιήκασιν, ἀλλὰ καὶ τὸ ζῆν αὑτῶν ἀφῄρηνται μετ’ αἰσχύνης. καὶ μὴν δειλία καὶ βλακεία κατ’ ἰδίαν μὲν αὐτοῖς ὄνειδος ἐπιφέρει τοῖς ἔχουσι, περὶ δὲ τὸν τῶν ὅλων ἡγεμόνα γενομένη κοινόν ἐστι καὶ μέγιστον συμπτωμάτων. οὐ γὰρ μόνον ἀπράκτους ποιεῖ τοὺς ὑποταττομένους, πολλάκις δὲ καὶ κινδύνους ἐπιφέρει τοὺς μεγίστους τοῖς πεπιστευκόσι. προπέτειά γε μὴν καὶ θρασύτης καὶ θυμὸς ἄλογος, ἔτι δὲ κενοδοξία καὶ τῦφος εὐχείρωτα μὲν τοῖς ἐχθροῖς, ἐπισφαλέστατα δὲ τοῖς φίλοις. πρὸς γὰρ πᾶσαν ἐπιβουλήν, ἐνέδραν, ἀπάτην ἕτοιμος ὅ γε τοιοῦτος. διόπερ εἴ τις δύναιτο συννοεῖν τὰ περὶ τοὺς πέλας ἁμαρτήματα καὶ τῇδέ που προσιέναι τοῖς ὑπεναντίοις, ᾗ μάλιστα καὶ δι’ ὧν εὐχείρωτος ἔσθ’ ὁ προεστὼς τῶν πολεμίων, τάχιστ’ ἂν τῶν ὅλων κατακρατοίη. καθάπερ γὰρ νεὼς ἐὰν ἀφέλῃ τις τὸν κυβερνήτην, τὸ ὅλον αὐτανδρὶ σκάφος ὑποχείριον γίνεται τοῖς ἐχθροῖς, τὸν αὐτὸν τρόπον ἐὰν τὸν προεστῶτα [πόλεμον] δυνάμεως χειρώσηταί τις κατὰ τὰς ἐπιβολὰς καὶ συλλογισμούς, αὐτανδρὶ γίνεται πολλάκις κρατεῖν τῶν ἀντιταττομένων. ἃ δὴ καὶ τότε προϊδόμενος καὶ συλλογισάμενος Ἀννίβας περὶ τοῦ τῶν ἐναντίων ἡγεμόνος οὐ διεσφάλη τῆς ἐπιβολῆς.", "st": "3.81"}, {"sp": "N", "t": "ὡς γὰρ θᾶττον ποιησάμενος ἀναζυγὴν ἀπὸ τῶν κατὰ τὴν Φαισόλαν τόπων καὶ μικρὸν ὑπεράρας τὴν τῶν Ῥωμαίων στρατοπεδείαν ἐνέβαλεν εἰς τὴν προκειμένην χώραν, εὐθέως μετέωρος ἦν ὁ Φλαμίνιος καὶ θυμοῦ πλήρης, δοξάζων ἑαυτὸν ὑπὸ τῶν ἐναντίων καταφρονεῖσθαι. μετὰ δὲ ταῦτα πορθουμένης τῆς χώρας, καὶ πανταχόθεν τοῦ καπνοῦ σημαίνοντος τὴν καταφθορὰν αὐτῆς, ἐσχετλίαζε, δεινὸν ἡγούμενος τὸ γινόμενον. διὸ καὶ τινῶν οἰομένων δεῖν μὴ προχείρως ἐπακολουθεῖν μηδὲ συμπλέκεσθαι τοῖς πολεμίοις, φυλάττεσθαι δὲ καὶ προσέχειν τὸ πλῆθος τῶν ἱππέων, μάλιστα δὲ καὶ τὸν ἕτερον ὕπατον προσλαβεῖν καὶ πᾶσιν ἐπὶ ταὐτὸ τοῖς στρατοπέδοις ὁμοῦ ποιήσασθαι τὸν κίνδυνον, οὐχ οἷον προσεῖχε τοῖς λεγομένοις, ἀλλ’ οὐδ’ ἀνείχετο τῶν ἀποφαινομένων ταῦτα, παρεκάλει δ’ αὐτοὺς ἐν νῷ λαμβάνειν τί λέγειν εἰκὸς τοὺς ἐν τῇ πατρίδι τῆς μὲν χώρας καταφθειρομένης σχεδὸν ἕως πρὸς αὐτὴν τὴν Ῥώμην, αὐτῶν δὲ κατόπιν τῶν πολεμίων ἐν Τυρρηνίᾳ στρατοπεδευόντων. τέλος δέ, ταῦτ’ εἰπών, ἀναζεύξας προῆγε μετὰ τῆς δυνάμεως, οὐ καιρόν, οὐ τόπον προορώμενος, μόνον δὲ σπεύδων συμπεσεῖν τοῖς πολεμίοις, ὡς προδήλου τῆς νίκης αὐτοῖς ὑπαρχούσης· τηλικοῦτον γὰρ προενεβεβλήκει κατελπισμὸν τοῖς ὄχλοις ὥστε πλείους εἶναι τῶν τὰ ὅπλα φερόντων τοὺς ἐκτὸς παρεπομένους τῆς ὠφελείας χάριν, κομίζοντας ἁλύσεις καὶ πέδας καὶ πᾶσαν τὴν τοιαύτην παρασκευήν. ὅ γε μὴν Ἀννίβας ἅμα μὲν εἰς τοὔμπροσθεν ὡς πρὸς τὴν Ῥώμην προῄει διὰ τῆς Τυρρηνίας, εὐώνυμον μὲν πόλιν ἔχων τὴν προσαγορευομένην Κυρτώνιον καὶ τὰ ταύτης ὄρη, δεξιὰν δὲ τὴν Ταρσιμέννην καλουμένην λίμνην· ἅμα δὲ προάγων ἐπυρπόλει καὶ κατέφθειρε τὴν χώραν, βουλόμενος ἐκκαλέσασθαι τὸν θυμὸν τῶν ὑπεναντίων. ἐπεὶ δὲ τὸν Φλαμίνιον ἤδη συνάπτοντα καθεώρα, τόπους δ’ εὐφυεῖς συνεθεώρησε πρὸς τὴν χρείαν, ἐγίνετο πρὸς τὸ διακινδυνεύειν.", "st": "3.82"}, {"sp": "N", "t": "ὄντος δὲ κατὰ τὴν δίοδον αὐλῶνος ἐπιπέδου, τούτου δὲ παρὰ μὲν τὰς εἰς μῆκος πλευρὰς ἑκατέρας βουνοὺς ἔχοντος ὑψηλοὺς καὶ συνεχεῖς, παρὰ δὲ τὰς εἰς πλάτος κατὰ μὲν τὴν ἀντικρὺ λόφον ἐπικείμενον ἐρυμνὸν καὶ δύσβατον, κατὰ δὲ τὴν ἀπ’ οὐρᾶς λίμνην τελείως στενὴν ἀπολείπουσαν πάροδον ὡς εἰς τὸν αὐλῶνα παρὰ τὴν παρώρειαν, διελθὼν τὸν αὐλῶνα παρὰ τὴν λίμνην τὸν μὲν κατὰ πρόσωπον τῆς πορείας λόφον αὐτὸς κατελάβετο καὶ τοὺς Ἴβηρας καὶ τοὺς Λίβυας ἔχων ἐπ’ αὐτοῦ κατεστρατοπέδευσε, τοὺς δὲ Βαλιαρεῖς καὶ λογχοφόρους κατὰ τὴν πρωτοπορείαν ἐκπεριάγων ὑπὸ τοὺς ἐν δεξιᾷ βουνοὺς τῶν παρὰ τὸν αὐλῶνα κειμένων, ἐπὶ πολὺ παρατείνας, ὑπέστειλε, τοὺς δ’ ἱππεῖς καὶ τοὺς Κελτοὺς ὁμοίως τῶν εὐωνύμων βουνῶν κύκλῳ περιαγαγὼν παρεξέτεινε συνεχεῖς, ὥστε τοὺς ἐσχάτους εἶναι κατ’ αὐτὴν τὴν εἴσοδον τὴν παρά τε τὴν λίμνην καὶ τὰς παρωρείας φέρουσαν εἰς τὸν προειρημένον τόπον. ὁ μὲν οὖν Ἀννίβας ταῦτα προκατασκευασάμενος τῆς νυκτὸς καὶ περιειληφὼς τὸν αὐλῶνα ταῖς ἐνέδραις τὴν ἡσυχίαν εἶχεν. ὁ δὲ Φλαμίνιος εἵπετο κατόπιν, σπεύδων συνάψαι [τῶν πολεμίων]· κατεστρατοπεδευκὼς δὲ τῇ προτεραίᾳ πρὸς αὐτῇ τῇ λίμνῃ τελέως ὀψὲ τῆς ὥρας, μετὰ ταῦτα τῆς ἡμέρας ἐπιγενομένης εὐθέως ἐπὶ τὴν ἑωθινὴν ἦγε τὴν πρωτοπορείαν παρὰ τὴν λίμνην εἰς τὸν ὑποκείμενον αὐλῶνα, βουλόμενος ἐξάπτεσθαι τῶν πολεμίων.", "st": "3.83"}, {"sp": "N", "t": "οὔσης δὲ τῆς ἡμέρας ὀμιχλώδους διαφερόντως, Ἀννίβας ἅμα τῷ τὸ πλεῖστον μέρος τῆς πορείας εἰς τὸν αὐλῶνα προσδέξασθαι καὶ συνάπτειν πρὸς αὐτὸν ἤδη τὴν τῶν ἐναντίων πρωτοπορείαν ἀποδοὺς τὰ συνθήματα καὶ διαπεμψάμενος πρὸς τοὺς ἐν ταῖς ἐνέδραις συνεπεχείρει πανταχόθεν ἅμα τοῖς πολεμίοις. οἱ δὲ περὶ τὸν Φλαμίνιον, παραδόξου γενομένης αὐτοῖς τῆς ἐπιφανείας, ἔτι δὲ δυσσυνόπτου τῆς κατὰ τὸν ἀέρα περιστάσεως ὑπαρχούσης, καὶ τῶν πολεμίων κατὰ πολλοὺς τόπους ἐξ ὑπερδεξίου καταφερομένων καὶ προσπιπτόντων, οὐχ οἷον παραβοηθεῖν ἐδύναντο πρός τι τῶν δεομένων οἱ ταξίαρχοι καὶ χιλίαρχοι τῶν Ῥωμαίων, ἀλλ’ οὐδὲ συννοῆσαι τὸ γινόμενον. ἅμα γὰρ οἱ μὲν κατὰ πρόσωπον, οἱ δ’ ἀπ’ οὐρᾶς, οἱ δ’ ἐκ τῶν πλαγίων αὐτοῖς προσέπιπτον. διὸ καὶ συνέβη τοὺς πλείστους ἐν αὐτῷ τῷ τῆς πορείας σχήματι κατακοπῆναι, μὴ δυναμένους αὑτοῖς βοηθεῖν, ἀλλ’ ὡσανεὶ προδεδομένους ὑπὸ τῆς τοῦ προεστῶτος ἀκρισίας. ἔτι γὰρ διαβουλευόμενοι τί δεῖ πράττειν ἀπώλλυντο παραδόξως. ἐν ᾧ καιρῷ καὶ τὸν Φλαμίνιον αὐτὸν δυσχρηστούμενον καὶ περικακοῦντα τοῖς ὅλοις προσπεσόντες τινὲς τῶν Κελτῶν ἀπέκτειναν. ἔπεσον οὖν τῶν Ῥωμαίων κατὰ τὸν αὐλῶνα σχεδὸν εἰς μυρίους καὶ πεντακισχιλίους, οὔτ’ εἴκειν τοῖς παροῦσιν οὔτε πράττειν οὐδὲν δυνάμενοι, τοῦτο δ’ ἐκ τῶν ἐθισμῶν αὐτὸ περὶ πλείστου ποιούμενοι, τὸ μὴ φεύγειν μηδὲ λείπειν τὰς τάξεις. οἱ δὲ κατὰ πορείαν μεταξὺ τῆς λίμνης καὶ τῆς παρωρείας ἐν τοῖς στενοῖς συγκλεισθέντες αἰσχρῶς, ἔτι δὲ μᾶλλον ταλαιπώρως διεφθείροντο. συνωθούμενοι [μὲν] γὰρ εἰς τὴν λίμνην οἱ μὲν διὰ τὴν παράστασιν τῆς διανοίας ὁρμῶντες ἐπὶ τὸ νήχεσθαι σὺν τοῖς ὅπλοις ἀπεπνίγοντο, τὸ δὲ πολὺ πλῆθος μέχρι μὲν τοῦ δυνατοῦ προβαῖνον εἰς τὴν λίμνην ἔμενε τὰς κεφαλὰς αὐτὰς ὑπὲρ τὸ ὑγρὸν ὑπερίσχον· ἐπιγενομένων δὲ τῶν ἱππέων, καὶ προδήλου γενομένης ἀπωλείας ἐξαίροντες τὰς χεῖρας καὶ δεόμενοι ζωγρεῖν καὶ πᾶσαν προϊέμενοι φωνὴν τὸ τελευταῖον οἱ μὲν ὑπὸ τῶν πολεμίων, τινὲς δὲ παρακαλέσαντες αὑτοὺς διεφθάρησαν. ἑξακισχίλιοι δ’ ἴσως τῶν κατὰ τὸν αὐλῶνα τοὺς κατὰ πρόσωπον νικήσαντες παραβοηθεῖν μὲν τοῖς ἰδίοις καὶ περιίστασθαι τοὺς ὑπεναντίους ἠδυνάτουν διὰ τὸ μηδὲν συνορᾶν τῶν γινομένων, καίπερ μεγάλην δυνάμενοι πρὸς τὰ ὅλα παρέχεσθαι χρείαν· ἀεὶ δὲ τοῦ πρόσθεν ὀρεγόμενοι προῆγον, πεπεισμένοι συμπεσεῖσθαί τισιν, ἕως ἔλαθον ἐκπεσόντες πρὸς τοὺς ὑπερδεξίους τόπους. γενόμενοι δ’ ἐπὶ τῶν ἄκρων, καὶ τῆς ὀμίχλης ἤδη πεπτωκυίας συνέντες τὸ γεγονὸς ἀτύχημα καὶ ποιεῖν οὐδὲν ὄντες ἔτι δυνατοὶ διὰ τὸ τοῖς ὅλοις ἐπικρατεῖν καὶ πάντα προκατέχειν ἤδη τοὺς πολεμίους, συστραφέντες ἀπεχώρησαν εἴς τινα κώμην Τυρρηνίδα. μετὰ δὲ τὴν μάχην ἀποσταλέντος ὑπὸ τοῦ στρατηγοῦ μετὰ τῶν Ἰβήρων καὶ λογχοφόρων Μαάρβα καὶ περιστρατοπεδεύσαντος τὴν κώμην, ποικίλης αὐτοῖς ἀπορίας περιεστώσης, ἀποθέμενοι τὰ ὅπλα παρέδοσαν αὑτοὺς ὑποσπόνδους, ὡς τευξόμενοι τῆς σωτηρίας. τὰ μὲν οὖν περὶ τὸν ὅλον κίνδυνον τὸν γενόμενον ἐν Τυρρηνίᾳ Ῥωμαίοις καὶ Καρχηδονίοις τοῦτον ἐπετελέσθη τὸν τρόπον.", "st": "3.84"}, {"sp": "N", "t": "Ἀννίβας δέ, πρὸς αὐτὸν ἐπαναχθέντων τῶν ὑποσπόνδων, ὁμοίως δὲ καὶ τῶν ἄλλων αἰχμαλώτων, συναγαγὼν πάντας, ὄντας πλείους τῶν μυρίων καὶ πεντακισχιλίων, πρῶτον μὲν διεσάφησεν ὅτι Μαάρβας οὐκ εἴη κύριος ἄνευ τῆς αὑτοῦ γνώμης διδοὺς τὴν ἀσφάλειαν τοῖς ὑποσπόνδοις, μετὰ δὲ ταῦτα κατηγορίαν ἐποιήσατο Ῥωμαίων. λήξας δὲ τούτων, ὅσοι μὲν ἦσαν Ῥωμαῖοι τῶν ἑαλωκότων, διέδωκεν εἰς φυλακὴν ἐπὶ τὰ τάγματα, τοὺς δὲ συμμάχους ἀπέλυσε χωρὶς λύτρων ἅπαντας εἰς τὴν οἰκείαν, ἐπιφθεγξάμενος τὸν αὐτὸν ὃν καὶ πρόσθεν λόγον ὅτι πάρεστι πολεμήσων οὐκ Ἰταλιώταις, ἀλλὰ Ῥωμαίοις ὑπὲρ τῆς Ἰταλιωτῶν ἐλευθερίας. τὴν δ’ ἑαυτοῦ δύναμιν ἀνελάμβανε καὶ τῶν νεκρῶν τῶν ἐκ τῆς σφετέρας δυνάμεως τοὺς ἐπιφανεστάτους ἔθαψεν, ὄντας εἰς τριάκοντα τὸν ἀριθμόν· οἱ μὲν γὰρ πάντες εἰς χιλίους καὶ πεντακοσίους ἔπεσον, ὧν ἦσαν οἱ πλείους Κελτοί. ταῦτα δὲ πράξας διενοεῖτο μετὰ τἀδελφοῦ καὶ τῶν φίλων ποῦ καὶ πῶς δεῖ ποιεῖσθαι τὴν ὁρμήν, εὐθαρσὴς ὢν ἤδη περὶ τῶν ὅλων. εἰς δὲ τὴν Ῥώμην προσπεσόντος ἤδη τοῦ γεγονότος ἀτυχήματος, στέλλεσθαι μὲν ἢ ταπεινοῦν τὸ συμβεβηκὸς οἱ προεστῶτες τοῦ πολιτεύματος ἠδυνάτουν διὰ τὸ μέγεθος τῆς συμφορᾶς, λέγειν δὲ τοῖς πολλοῖς ἠναγκάζοντο τὰ γεγονότα, συναθροίσαντες τὸν δῆμον εἰς ἐκκλησίαν. διόπερ ἅμα τῷ τὸν στρατηγὸν εἰπεῖν τοῖς ὄχλοις ἀπὸ τῶν ἐμβόλων ὅτι ‘Λειπόμεθα μάχῃ μεγάλῃ’, τηλικαύτην συνέβη γενέσθαι διατροπὴν ὥστε τοῖς παραγενομένοις ἐφ’ ἑκατέρων τῶν καιρῶν πολλῷ μεῖζον τότε φανῆναι τὸ γεγονὸς ἢ παρ’ αὐτὸν τὸν τῆς μάχης καιρόν. καὶ τοῦτ’ εἰκότως συνέβη. πολλῶν γὰρ χρόνων ἄπειροι καὶ τοῦ ῥήματος καὶ τοῦ πράγματος ὑπάρχοντες τῆς ὁμολογουμένης ἥττης οὐ μετρίως οὐδὲ κατὰ σχῆμα τὴν περιπέτειαν ἔφερον. οὐ μὴν ἥ γε σύγκλητος, ἀλλ’ ἐπὶ τοῦ καθήκοντος ἔμενε λογισμοῦ καὶ διενοεῖτο περὶ τοῦ μέλλοντος πῶς καὶ τί πρακτέον ἑκάστοις εἴη.", "st": "3.85"}, {"sp": "N", "t": "κατὰ δὲ τοὺς τῆς μάχης καιροὺς Γνάιος Σερουίλιος ὁ προκαθήμενος ὕπατος ἐπὶ τῶν κατ’ Ἀρίμινον τόπων — οὗτοι δ’ εἰσὶν ἐπὶ τῆς παρὰ τὸν Ἀδρίαν πλευρᾶς, οὗ συνάπτει τὰ Γαλατικὰ πεδία πρὸς τὴν ἄλλην Ἰταλίαν, οὐ μακρὰν τῆς εἰς θάλατταν ἐκβολῆς τῶν τοῦ Πάδου στομάτων — ἀκούσας εἰσβεβληκότα τὸν Ἀννίβαν εἰς Τυρρηνίαν ἀντιστρατοπεδεύειν τῷ Φλαμινίῳ, πᾶσι μὲν ἐπεβάλετο τοῖς στρατοπέδοις αὐτὸς συνάπτειν, ἀδυνατῶν δὲ διὰ τὸ τῆς στρατιᾶς βάρος Γάιον Κεντήνιον κατὰ σπουδὴν δοὺς τετρακισχιλίους ἱππεῖς προεξαπέστειλε, βουλόμενος, εἰ δέοινθ’ οἱ καιροί, πρὸ τῆς αὑτοῦ παρουσίας τούτους καταταχεῖν. Ἀννίβας δέ, μετὰ τὴν μάχην προσαγγελθείσης αὐτῷ τῆς τῶν ὑπεναντίων βοηθείας, ἐξαποστέλλει Μαάρβαν ἔχοντα τοὺς λογχοφόρους καί τι μέρος τῶν ἱππέων. οἳ καὶ συμπεσόντες τοῖς περὶ τὸν Γάιον ἐν αὐτῇ μὲν τῇ πρώτῃ συμπλοκῇ σχεδὸν τοὺς ἡμίσεις αὐτῶν διέφθειραν, τοὺς δὲ λοιποὺς εἴς τινα λόφον συνδιώξαντες τῇ κατὰ πόδας ἡμέρᾳ πάντας ἔλαβον ὑποχειρίους. ἐν δὲ τῇ Ῥώμῃ, τριταίας οὔσης τῆς κατὰ τὴν μάχην προσαγγελίας, καὶ μάλιστα τότε τοῦ πάθους κατὰ τὴν πόλιν ὡσανεὶ φλεγμαίνοντος, ἐπιγενομένης καὶ ταύτης τῆς περιπετείας οὐ μόνον τὸ πλῆθος, ἀλλὰ καὶ τὴν σύγκλητον αὐτὴν συνέβη διατραπῆναι. διὸ καὶ παρέντες τὴν κατ’ ἐνιαυτὸν ἀγωγὴν τῶν πραγμάτων καὶ τὴν αἵρεσιν τῶν ἀρχόντων μειζόνως ἐπεβάλοντο βουλεύεσθαι περὶ τῶν ἐνεστώτων, νομίζοντες αὐτοκράτορος δεῖσθαι στρατηγοῦ τὰ πράγματα καὶ τοὺς περιεστῶτας καιρούς. Ἀννίβας δὲ κατατεθαρρηκὼς τοῖς ὅλοις ἤδη τὸ μὲν συνεγγίζειν τῇ Ῥώμῃ κατὰ τὸ παρὸν ἀπεδοκίμασεν, τὴν δὲ χώραν ἐπιπορευόμενος ἀδεῶς ἐπόρθει, ποιούμενος τὴν πορείαν ὡς ἐπὶ τὸν Ἀδρίαν. διανύσας τε τήν τε τῶν Ὄμβρων καλουμένην χώραν καὶ τὴν τῶν Πικέντων ἧκεν δεκαταῖος πρὸς τοὺς κατὰ τὸν Ἀδρίαν τόπους, πολλῆς μὲν λείας γεγονὼς ἐγκρατής, ὥστε μήτ’ ἄγειν μήτε φέρειν δύνασθαι τὸ στρατόπεδον τὰς ὠφελείας, πολὺ δὲ πλῆθος ἀνθρώπων ἀπεκταγκὼς κατὰ τὴν δίοδον· καθάπερ γὰρ ἐν ταῖς τῶν πόλεων καταλήψεσι, καὶ τότε παράγγελμά τι δεδομένον ἦν φονεύειν τοὺς ὑποπίπτοντας τῶν ἐν ταῖς ἡλικίαις. ταῦτα δ’ ἐποίει διὰ τὸ προϋπάρχον αὐτῷ μῖσος ἔμφυτον πρὸς Ῥωμαίους.", "st": "3.86"}, {"sp": "N", "t": "ἐν ᾧ καιρῷ καταστρατοπεδεύσας παρὰ τὸν Ἀδρίαν ἐν χώρᾳ πρὸς πάντα τὰ γεννήματα διαφερούσῃ μεγάλην ἐποιεῖτο σπουδὴν ὑπὲρ τῆς ἀναλήψεως καὶ θεραπείας τῶν ἀνδρῶν, οὐχ ἧττον δὲ καὶ τῶν ἵππων. ὡς ἂν γὰρ ὑπαίθρου τῆς παραχειμασίας γεγενημένης ἐν τοῖς κατὰ Γαλατίαν τόποις, ὑπό τε τοῦ ψύχους καὶ τῆς ἀνηλειψίας, ἔτι δὲ τῆς μετὰ ταῦτα διὰ τῶν ἑλῶν πορείας καὶ ταλαιπωρίας ἐπεγεγόνει σχεδὸν ἅπασι τοῖς ἵπποις, ὁμοίως δὲ καὶ τοῖς ἀνδράσιν ὁ λεγόμενος λιμόψωρος καὶ τοιαύτη καχεξία. διὸ γενόμενος ἐγκρατὴς χώρας εὐδαίμονος ἐσωματοποίησε μὲν τοὺς ἵππους, ἀνεκτήσατο δὲ τά τε σώματα καὶ τὰς ψυχὰς τῶν στρατιωτῶν· μετακαθώπλισε δὲ τοὺς Λίβυας εἰς τὸν Ῥωμαϊκὸν τρόπον ἐκλεκτοῖς ὅπλοις, ὡς ἂν γεγονὼς κύριος τοσούτων σκύλων. ἐξαπέστειλε δὲ κατὰ θάλατταν ἐν τῷ καιρῷ τούτῳ καὶ τοὺς διασαφήσοντας εἰς τὴν Καρχηδόνα περὶ τῶν γεγονότων· τότε γὰρ πρῶτον ἥψατο θαλάττης, ἀφ’ οὗ τὴν εἰσβολὴν ἐποιήσατο τὴν εἰς Ἰταλίαν. ἐφ’ οἷς ἀκούσαντες μεγαλείως ἐχάρησαν οἱ Καρχηδόνιοι καὶ πολλὴν ἐποιοῦντο σπουδὴν καὶ πρόνοιαν ὑπὲρ τοῦ κατὰ πάντα τρόπον ἐπικουρεῖν καὶ τοῖς ἐν Ἰταλίᾳ καὶ τοῖς ἐν Ἰβηρίᾳ πράγμασι. Ῥωμαῖοι δὲ δικτάτορα μὲν κατέστησαν Κόιντον Φάβιον, ἄνδρα καὶ φρονήσει διαφέροντα καὶ πεφυκότα καλῶς. ἔτι γοῦν ἐπεκαλοῦντο καὶ καθ’ ἡμᾶς οἱ ταύτης τῆς οἰκίας Μάξιμοι, τοῦτο δ’ ἔστι μέγιστοι, διὰ τὰς ἐκείνου τἀνδρὸς ἐπιτυχίας καὶ πράξεις. ὁ δὲ δικτάτωρ ταύτην ἔχει τὴν διαφορὰν τῶν ὑπάτων· τῶν μὲν γὰρ ὑπάτων ἑκατέρῳ δώδεκα πελέκεις ἀκολουθοῦσι, τούτῳ δ’ εἴκοσι καὶ τέτταρες, κἀκεῖνοι μὲν ἐν πολλοῖς προσδέονται τῆς συγκλήτου πρὸς τὸ συντελεῖν τὰς ἐπιβολάς, οὗτος δ’ ἔστιν αὐτοκράτωρ στρατηγός, οὗ κατασταθέντος παραχρῆμα διαλύεσθαι συμβαίνει πάσας τὰς ἀρχὰς ἐν τῇ Ῥώμῃ πλὴν τῶν δημάρχων. οὐ μὴν ἀλλὰ περὶ μὲν τούτων ἐν ἄλλοις ἀκριβεστέραν ποιησόμεθα τὴν διαστολήν. ἅμα δὲ τῷ δικτάτορι κατέστησαν ἱππάρχην Μάρκον Μινύκιον. οὗτος δὲ τέτακται μὲν ὑπὸ τὸν αὐτοκράτορα, γίνεται δ’ οἱονεὶ διάδοχος τῆς ἀρχῆς ἐν τοῖς ἐκείνου περισπασμοῖς.", "st": "3.87"}, {"sp": "N", "t": "Ἀννίβας δὲ κατὰ βραχὺ μεταθεὶς τὴν παρεμβολὴν ἐνδιέτριβε τῇ παρὰ τὸν Ἀδρίαν χώρᾳ καὶ τοὺς μὲν ἵππους ἐκλούων τοῖς παλαιοῖς οἴνοις διὰ τὸ πλῆθος ἐξεθεράπευσε τὴν καχεξίαν αὐτῶν καὶ τὴν ψώραν, παραπλησίως δὲ καὶ τῶν ἀνδρῶν τοὺς μὲν τραυματίας ἐξυγίασε, τοὺς δὲ λοιποὺς εὐέκτας παρεσκεύασε καὶ προθύμους εἰς τὰς ἐπιφερομένας χρείας. διελθὼν δὲ καὶ καταφθείρας τήν τε Πραιτεττιανὴν καὶ τὴν Ἀδριανὴν ἔτι δὲ τὴν Μαρρουκίνην καὶ Φρεντανὴν χώραν ὥρμησε ποιούμενος τὴν πορείαν εἰς τὴν Ἰαπυγίαν. ἧς διῃρημένης εἰς τρεῖς ὀνομασίας, καὶ τῶν μὲν προσαγορευομένων Δαυνίων, τῶν δὲ Πευκετίων, τῶν δὲ Μεσσαπίων, εἰς πρώτην ἐνέβαλε τὴν Δαυνίαν. ἀρξάμενος δὲ ταύτης ἀπὸ Λουκαρίας, οὔσης ἀποικίας Ῥωμαίων, ἐπόρθει τὴν χώραν. μετὰ δὲ ταῦτα καταστρατοπεδεύσας περὶ τὸ καλούμενον Οἰβώνιον ἐπέτρεχε τὴν Ἀργυριππανὴν καὶ πᾶσαν ἀδεῶς ἐλεηλάτει τὴν Δαυνίαν. ἐν ᾧ καιρῷ καὶ Φάβιος μετὰ τὴν κατάστασιν θύσας τοῖς θεοῖς ἐξώρμησε μετὰ τοῦ συνάρχοντος καὶ τῶν ἐκ τοῦ καιροῦ καταγραφέντων τεττάρων στρατοπέδων. συμμίξας δὲ ταῖς ἀπ’ Ἀριμίνου βοηθούσαις δυνάμεσι περὶ τὴν Ναρνίαν, Γνάιον μὲν τὸν ὑπάρχοντα στρατηγὸν ἀπολύσας τῆς κατὰ γῆν στρατείας ἐξαπέστειλε μετὰ παραπομπῆς εἰς τὴν Ῥώμην, ἐντειλάμενος, ἐάν τι κατὰ θάλατταν κινῶνται Καρχηδόνιοι, βοηθεῖν ἀεὶ τοῖς ὑποπίπτουσι καιροῖς, αὐτὸς δὲ μετὰ τοῦ συνάρχοντος παραλαβὼν τὰς δυνάμεις ἀντεστρατοπέδευσε τοῖς Καρχηδονίοις περὶ τὰς Αἴκας καλουμένας, ἀπέχων τῶν πολεμίων περὶ πεντήκοντα σταδίους.", "st": "3.88"}, {"sp": "N", "t": "Ἀννίβας δὲ συνεὶς τὴν παρουσίαν τοῦ Φαβίου καὶ βουλόμενος ἐξ ἐφόδου καταπλήξασθαι τοὺς ὑπεναντίους, ἐξαγαγὼν τὴν δύναμιν καὶ συνεγγίσας τῷ τῶν Ῥωμαίων χάρακι παρετάξατο. χρόνον δέ τινα μείνας, οὐδενὸς ἐπεξιόντος αὖθις ἀνεχώρησεν εἰς τὴν ἑαυτοῦ παρεμβολήν. ὁ γὰρ Φάβιος διεγνωκὼς μήτε παραβάλλεσθαι μήτε διακινδυνεύειν, στοχάζεσθαι δὲ πρῶτον καὶ μάλιστα τῆς ἀσφαλείας τῶν ὑποταττομένων, ἔμενε βεβαίως ἐπὶ τῆς διαλήψεως ταύτης. τὰς μὲν οὖν ἀρχὰς κατεφρονεῖτο καὶ παρεῖχε λόγον ὡς ἀποδεδειλιακὼς καὶ καταπεπληγμένος τὸν κίνδυνον, τῷ δὲ χρόνῳ πάντας ἠνάγκασε παρομολογῆσαι καὶ συγχωρεῖν ὡς οὔτε νουνεχέστερον οὔτε φρονιμώτερον οὐδένα δυνατὸν ἦν χρῆσθαι τοῖς τότε περιεστῶσι καιροῖς. ταχὺ δὲ καὶ τὰ πράγματα προσεμαρτύρησε τοῖς λογισμοῖς αὐτοῦ. καὶ τοῦτ’ εἰκότως ἐγένετο. τὰς μὲν γὰρ τῶν ὑπεναντίων δυνάμεις συνέβαινε γεγυμνάσθαι μὲν ἐκ τῆς πρώτης ἡλικίας συνεχῶς ἐν τοῖς πολεμικοῖς, ἡγεμόνι δὲ χρῆσθαι συντεθραμμένῳ σφίσι καὶ παιδομαθεῖ περὶ τὰς ἐν τοῖς ὑπαίθροις χρείας, νενικηκέναι δὲ πολλὰς μὲν ἐν Ἰβηρίᾳ μάχας, δὶς δὲ Ῥωμαίους ἑξῆς καὶ τοὺς συμμάχους αὐτῶν, τὸ δὲ μέγιστον, ἀπεγνωκότας πάντα μίαν ἔχειν ἐλπίδα τῆς σωτηρίας τὴν ἐν τῷ νικᾶν· περὶ δὲ τὴν τῶν Ῥωμαίων στρατιὰν τἀναντία τούτοις ὑπῆρχε. διόπερ εἰς μὲν τὸν ὑπὲρ τῶν ὅλων κίνδυνον οὐχ οἷός τ’ ἦν συγκαταβαίνειν, προδήλου τῆς ἐλαττώσεως ὑπαρχούσης· εἰς δὲ τὰ σφέτερα προτερήματα τοῖς λογισμοῖς ἀναχωρήσας ἐν τούτοις διέτριβε καὶ διὰ τούτων ἐχείριζε τὸν πόλεμον. ἦν δὲ τὰ προτερήματα Ῥωμαίων ἀκατάτριπτα χορήγια καὶ χειρῶν πλῆθος.", "st": "3.89"}, {"sp": "N", "t": "διόπερ κατὰ τοὺς ἑξῆς χρόνους ἀντιπαρῆγεν τοῖς πολεμίοις ἀεὶ καὶ τοὺς εὐκαίρους προκατελάμβανε τόπους κατὰ τὴν ἐμπειρίαν. ἔχων δὲ κατὰ νώτου τὰς χορηγίας ἀφθόνους οὐδέποτε τοὺς στρατιώτας ἠφίει προνομεύειν οὐδὲ χωρίζεσθαι καθάπαξ ἐκ τοῦ χάρακος, ἅθρους δ’ ἀεὶ καὶ συνεστραμμένους τηρῶν ἐφήδρευε τοῖς τόποις καὶ καιροῖς. καὶ πολλοὺς τῶν πολεμίων ἀποσπωμένους ἀπὸ τῆς ἰδίας παρεμβολῆς ἐπὶ τὰς προνομὰς διὰ τὸ καταφρονεῖν ὑποχειρίους ἐλάμβανε καὶ κατέφθειρε τῷ τοιούτῳ τρόπῳ. ταῦτα δ’ ἐποίει, βουλόμενος ἅμα μὲν ἀφ’ ὡρισμένου πλήθους ἐλαττοῦν ἀεὶ τοὺς ὑπεναντίους, ἅμα δὲ τὰς τῶν ἰδίων δυνάμεων ψυχὰς προηττημένας τοῖς ὅλοις διὰ τῶν κατὰ μέρος προτερημάτων κατὰ βραχὺ σωματοποιεῖν καὶ προσαναλαμβάνειν. εἰς ὁλοσχερῆ δὲ κρίσιν ἐξ ὁμολόγου συγκαταβαίνειν οὐδαμῶς οἷός τ’ ἦν. οὐ μὴν Μάρκῳ γε τῷ συνάρχοντι τούτων οὐδὲν ἤρεσκεν. σύμψηφον δὲ τοῖς ὄχλοις ποιῶν αὑτὸν τὸν μὲν Φάβιον κατελάλει πρὸς πάντας, ὡς ἀγεννῶς χρώμενον τοῖς πράγμασιν καὶ νωθρῶς, αὐτὸς δὲ πρόθυμος ἦν παραβάλλεσθαι καὶ διακινδυνεύειν. οἱ δὲ Καρχηδόνιοι καταφθείραντες τοὺς προειρημένους τόπους ὑπερέβαλον τὸν Ἀπεννῖνον καὶ κατάραντες εἰς τὴν Σαυνῖτιν χώραν, οὖσαν εὐδαίμονα καὶ πολλῶν χρόνων ἀπολέμητον, ἐν τοιαύτῃ περιουσίᾳ τῶν ἐπιτηδείων ἦσαν ὥστε μήτε χρωμένους μήτε καταφθείροντας ἀνύειν δύνασθαι τὰς λείας. κατέδραμον δὲ καὶ τὴν Οὐενοαντανήν, Ῥωμαίων ἀποικίαν ὑπάρχουσαν· εἷλον δὲ καὶ πόλιν Οὐενουσίαν, ἀτείχιστον οὖσαν καὶ πολλῆς καὶ παντοδαπῆς ἀποσκευῆς γέμουσαν. οἱ δὲ Ῥωμαῖοι κατόπιν μὲν εἵποντο συνεχῶς, μιᾶς καὶ δυεῖν ἡμερῶν ὁδὸν ἀπέχοντες, ἐγγίζειν γε μὴν καὶ συμπλέκεσθαι τοῖς πολεμίοις οὐχ οἷοί τ’ ἦσαν. διόπερ Ἀννίβας ὁρῶν τὸν Φάβιον φυγομαχοῦντα μὲν προδήλως τοῖς δ’ ὅλοις οὐκ ἐκχωροῦντα τῶν ὑπαίθρων, ὥρμησε τολμηρῶς εἰς τὰ περὶ Καπύην πεδία, καὶ τούτων εἰς τὸν προσαγορευόμενον Φάλερνον τόπον, πεπεισμένος δυεῖν θάτερον, ἢ μάχεσθαι τοὺς πολεμίους ἀναγκάσειν ἢ πᾶσι δῆλον ποιήσειν ὅτι κρατεῖ τῶν ὅλων καὶ παραχωροῦσι Ῥωμαῖοι τῶν ὑπαίθρων αὐτοῖς. οὗ γενομένου καταπλαγείσας ἤλπιζε τὰς πόλεις ὁρμήσειν πρὸς τὴν ἀπὸ Ῥωμαίων ἀπόστασιν. ἕως γὰρ τότε δυσὶ μάχαις ἤδη λελειμμένων αὐτῶν οὐδεμία πόλις ἀπέστη τῶν κατὰ τὴν Ἰταλίαν πρὸς Καρχηδονίους, ἀλλὰ διετήρουν τὴν πίστιν, καίπερ ἔνιαι πάσχουσαι κακῶς. ἐξ ὧν καὶ παρασημήναιτ’ ἄν τις τὴν κατάπληξιν καὶ καταξίωσιν παρὰ τοῖς συμμάχοις τοῦ Ῥωμαίων πολιτεύματος.", "st": "3.90"}, {"sp": "N", "t": "οὐ μὴν ἀλλ’ ὅ γ’ Ἀννίβας εἰκότως ἐπὶ τούτους κατήντα τοὺς λογισμούς. τὰ γὰρ πεδία τὰ κατὰ Καπύην ἐπιφανέστατα μέν ἐστι τῶν κατὰ τὴν Ἰταλίαν καὶ διὰ τὴν ἀρετὴν καὶ διὰ τὸ κάλλος καὶ διὰ τὸ πρὸς αὐτῇ κεῖσθαι τῇ θαλάττῃ καὶ τούτοις χρῆσθαι τοῖς ἐμπορίοις, εἰς ἃ σχεδὸν ἐκ πάσης τῆς οἰκουμένης κατατρέχουσιν οἱ πλέοντες εἰς Ἰταλίαν. περιέχουσι δὲ καὶ τὰς ἐπιφανεστάτας καὶ καλλίστας πόλεις τῆς Ἰταλίας ἐν αὑτοῖς. τὴν μὲν γὰρ παραλίαν αὐτῶν Σενοεσανοὶ καὶ Κυμαῖοι καὶ Δικαιαρχῖται νέμονται, πρὸς δὲ τούτοις Νεαπολῖται, τελευταῖον δὲ τὸ τῶν Νουκερίνων ἔθνος. τῆς δὲ μεσογαίου τὰ μὲν πρὸς τὰς ἄρκτους Καληνοὶ καὶ Τιανῖται κατοικοῦσι, τὰ δὲ πρὸς ἕω καὶ μεσημβρίαν Δαύνιοι καὶ Νωλανοί. κατὰ μέσα δὲ τὰ πεδία κεῖσθαι συμβαίνει τὴν πασῶν ποτε μακαριωτάτην γεγονυῖαν πόλιν Καπύην. ἐπιεικέστατος δὲ καὶ παρὰ τοῖς μυθογράφοις ὁ περὶ τούτων τῶν πεδίων λέγεται λόγος· προσαγορεύεται δὲ καὶ ταῦτα Φλεγραῖα, καθάπερ καὶ ἕτερα τῶν ἐπιφανῶν πεδίων· θεούς γε μὴν μάλιστα περὶ τούτων εἰκὸς ἠρικέναι διὰ τὸ κάλλος καὶ τὴν ἀρετὴν αὐτῶν. ἅμα δὲ τοῖς προειρημένοις ὀχυρὰ δοκεῖ καὶ δυσέμβολα τελέως εἶναι τὰ πεδία· τὰ μὲν γὰρ θαλάττῃ τὸ δὲ πλεῖον ὄρεσι μεγάλοις πάντῃ καὶ συνεχέσι περιέχεται, δι’ ὧν εἰσβολαὶ τρεῖς ὑπάρχουσι μόνον ἐκ τῆς μεσογαίου στεναὶ καὶ δύσβατοι, μία μὲν ἀπὸ τῆς Σαυνίτιδος, δευτέρα δ’ ἀπὸ τῆς Λατίνης, ἡ δὲ κατάλοιπος ἀπὸ τῶν κατὰ τοὺς Ἱρπίνους τόπων. διόπερ ἔμελλον εἰς ταῦτα καταστρατοπεδεύσαντες ὥσπερ εἰς θέατρον οἱ Καρχηδόνιοι καταπλήξεσθαι μὲν τῷ παραλόγῳ πάντας, ἐκθεατριεῖν δὲ τοὺς πολεμίους φυγομαχοῦντας, αὐτοὶ δ’ ἐξ ὁμολόγου φανήσεσθαι τῶν ὑπαίθρων κρατοῦντες.", "st": "3.91"}, {"sp": "N", "t": "Ἀννίβας μὲν οὖν τοιούτοις χρησάμενος λογισμοῖς καὶ διελθὼν ἐκ τῆς Σαυνίτιδος τὰ στενὰ κατὰ τὸν Ἐριβιανὸν καλούμενον λόφον κατεστρατοπέδευσε παρὰ τὸν Ἄθυρνον ποταμόν, ὃς σχεδὸν δίχα διαιρεῖ τὰ προειρημένα πεδία. καὶ τὴν μὲν παρεμβολὴν ἐκ τοῦ πρὸς Ῥώμην μέρους εἶχε, ταῖς δὲ προνομαῖς πᾶν ἐπιτρέχων ἐπόρθει τὸ πεδίον ἀδεῶς. Φάβιος δὲ κατεπέπληκτο μὲν τὴν ἐπιβολὴν καὶ τόλμαν τῶν ὑπεναντίων, τοσούτῳ δὲ μᾶλλον ἐπὶ τῶν κεκριμένων ἔμενεν. ὁ δὲ συνάρχων αὐτοῦ Μάρκος καὶ πάντες οἱ κατὰ τὸ στρατόπεδον χιλίαρχοι καὶ ταξίαρχοι νομίζοντες ἐν καλῷ τοὺς πολεμίους ἀπειληφέναι, σπεύδειν ᾤοντο δεῖν καὶ συνάπτειν εἰς τὰ πεδία καὶ μὴ περιορᾶν τὴν ἐπιφανεστάτην χώραν δῃουμένην. Φάβιος δὲ μέχρι μὲν τοῦ συνάψαι τοῖς τόποις ἔσπευδε καὶ συνυπεκρίνετο τοῖς προθύμως καὶ φιλοκινδύνως διακειμένοις, ἐγγίσας δὲ τῷ Φαλέρνῳ ταῖς μὲν παρωρείαις ἐπιφαινόμενος ἀντιπαρῆγε τοῖς πολεμίοις, ὥστε μὴ δοκεῖν τοῖς αὑτῶν συμμάχοις ἐκχωρεῖν τῶν ὑπαίθρων, εἰς δὲ τὸ πεδίον οὐ καθίει τὴν δύναμιν, εὐλαβούμενος τοὺς ὁλοσχερεῖς κινδύνους διά τε τὰς προειρημένας αἰτίας καὶ διὰ τὸ προφανῶς ἱπποκρατεῖν παρὰ πολὺ τοὺς ὑπεναντίους. Ἀννίβας δ’ ἐπειδὴ καταπειράσας τῶν πολεμίων καὶ καταφθείρας πᾶν τὸ πεδίον ἥθροισε λείας ἄπλετον πλῆθος, ἐγίνετο πρὸς ἀναζυγήν, βουλόμενος μὴ καταφθεῖραι τὴν λείαν, ἀλλ’ εἰς τοιοῦτον ἀπερείσασθαι τόπον, ἐν ᾧ δυνήσεται ποιήσασθαι καὶ τὴν παραχειμασίαν, ἵνα μὴ μόνον κατὰ τὸ παρὸν εὐωχίαν ἀλλὰ συνεχῶς δαψίλειαν ἔχῃ τῶν ἐπιτηδείων τὸ στρατόπεδον. Φάβιος δὲ καὶ κατανοῶν αὐτοῦ τὴν ἐπιβολήν, ὅτι προχειρίζεται ποιεῖσθαι τὴν ἐπάνοδον ᾗπερ ἐποιήσατο καὶ τὴν εἴσοδον, καὶ θεωρῶν τοὺς τόπους στενοὺς ὄντας καὶ καθ’ ὑπερβολὴν εὐφυεῖς πρὸς ἐπίθεσιν, ἐπ’ αὐτῆς μὲν τῆς διεκβολῆς περὶ τετρακισχιλίους ἐπέστησε, παρακαλέσας χρήσασθαι τῇ προθυμίᾳ σὺν καιρῷ μετὰ τῆς τῶν τόπων εὐφυΐας, αὐτὸς δὲ τὸ πολὺ μέρος ἔχων τῆς δυνάμεως ἐπί τινα λόφον ὑπερδέξιον πρὸ τῶν στενῶν κατεστρατοπέδευσε.", "st": "3.92"}, {"sp": "N", "t": "παραγενομένων δὲ τῶν Καρχηδονίων καὶ ποιησαμένων τὴν παρεμβολὴν ἐν τοῖς ἐπιπέδοις ὑπ’ αὐτὴν τὴν παρώρειαν, τὴν μὲν λείαν αὐτῶν ἤλπισεν ἀδηρίτως περισυρεῖν, ὡς δὲ τὸ πολὺ καὶ τοῖς ὅλοις πέρας ἐπιθήσειν διὰ τὴν τῶν τόπων εὐκαιρίαν. καὶ δὴ περὶ ταῦτα καὶ πρὸς τούτοις ἐγίνετο τοῖς διαβουλίοις, διανοούμενος πῇ καὶ πῶς χρήσεται τοῖς τόποις καὶ τίνες καὶ πόθεν πρῶτον ἐγχειρήσουσι τοῖς ὑπεναντίοις. Ἀννίβας δέ, ταῦτα πρὸς τὴν ἐπιοῦσαν ἡμέραν παρασκευαζομένων τῶν πολεμίων, συλλογιζόμενος ἐκ τῶν εἰκότων οὐκ ἔδωκε χρόνον οὐδ’ ἀναστροφὴν ταῖς ἐπιβολαῖς αὐτῶν, ἀνακαλεσάμενος δὲ τὸν ἐπὶ τῶν λειτουργιῶν τεταγμένον Ἀσδρούβαν παρήγγειλε λαμπάδας δεσμεύειν ἐκ τῆς ξηρᾶς καὶ παντοδαπῆς ὕλης κατὰ τάχος ὡς πλείστας καὶ τῶν ἐργατῶν βοῶν ἐκλέξαντ’ ἐκ πάσης τῆς λείας τοὺς εὐρωστοτάτους εἰς δισχιλίους ἁθροῖσαι πρὸ τῆς παρεμβολῆς. γενομένου δὲ τούτου συναγαγὼν ὑπέδειξε τοῖς λειτουργοῖς ὑπερβολήν τινα μεταξὺ κειμένην τῆς αὑτοῦ στρατοπεδείας καὶ τῶν στενῶν, δι’ ὧν ἔμελλε ποιεῖσθαι τὴν πορείαν, πρὸς ἣν ἐκέλευε προσελαύνειν τοὺς βοῦς ἐνεργῶς καὶ μετὰ βίας, ὅταν δοθῇ τὸ παράγγελμα, μέχρι συνάψωσι τοῖς ἄκροις. μετὰ δὲ τοῦτο δειπνοποιησαμένοις ἀναπαύεσθαι καθ’ ὥραν παρήγγειλε πᾶσιν. ἅμα δὲ τῷ κλῖναι τὸ τρίτον μέρος τῆς νυκτὸς εὐθέως ἐξῆγε τοὺς λειτουργοὺς καὶ προσδεῖν ἐκέλευσε πρὸς τὰ κέρατα τοῖς βουσὶ τὰς λαμπάδας. ταχὺ δὲ τούτου γενομένου διὰ τὸ πλῆθος, ἀνάψαι παρήγγειλε πάσας καὶ τοὺς μὲν βοῦς ἐλαύνειν καὶ προσβάλλειν πρὸς τὰς ἀκρωρείας ἐπέταξε, τοὺς δὲ λογχοφόρους κατόπιν ἐπιστήσας τούτοις ἕως μέν τινος συνεργεῖν παρεκελεύετο τοῖς ἐλαύνουσιν, ὅταν δὲ τὴν πρώτην ἅπαξ ὁρμὴν λάβῃ τὰ ζῷα, παρατρέχοντας παρὰ τὰ πλάγια καὶ συγκρούοντας ἅμα τῶν ὑπερδεξίων ἀντέχεσθαι τόπων καὶ προκαταλαμβάνειν τὰς ἀκρωρείας, ἵνα παραβοηθῶσι καὶ συμπλέκωνται τοῖς πολεμίοις, ἐάν που συναντῶσι πρὸς τὰς ὑπερβολάς. κατὰ δὲ τὸν καιρὸν τοῦτον αὐτὸς ἀναλαβὼν πρῶτα μὲν τὰ βαρέα τῶν ὅπλων, ἐπὶ δὲ τούτοις τοὺς ἱππεῖς, ἑξῆς δὲ τὴν λείαν, ἐπὶ δὲ πᾶσι τοὺς Ἴβηρας καὶ Κελτοὺς ἧκε πρὸς τὰ στενὰ καὶ τὰς διεκβολάς.", "st": "3.93"}, {"sp": "N", "t": "τῶν δὲ Ῥωμαίων οἱ μὲν ἐπὶ τοῖς στενοῖς φυλάττοντες ἅμα τῷ συνιδεῖν τὰ φῶτα προσβάλλοντα πρὸς τὰς ὑπερβολάς, νομίσαντες ταύτῃ ποιεῖσθαι τὴν ὁρμὴν τὸν Ἀννίβαν, ἀπολιπόντες τὰς δυσχωρίας παρεβοήθουν τοῖς ἄκροις. ἐγγίζοντες δὲ τοῖς βουσὶν ἠποροῦντο διὰ τὰ φῶτα, μεῖζόν τι τοῦ συμβαίνοντος καὶ δεινότερον ἀναπλάττοντες καὶ προσδοκῶντες. ἐπιγενομένων δὲ τῶν λογχοφόρων, οὗτοι μὲν βραχέα πρὸς ἀλλήλους ἀκροβολισάμενοι, τῶν βοῶν αὐτοῖς ἐμπιπτόντων ἔμειναν διαστάντες ἐπὶ τῶν ἄκρων ἀμφότεροι καὶ προσανεῖχον καραδοκοῦντες τὴν ἐπιφάνειαν τῆς ἡμέρας διὰ τὸ μὴ δύνασθαι γνῶναι τὸ γινόμενον. Φάβιος δὲ τὰ μὲν ἀπορούμενος ἐπὶ τῷ συμβαίνοντι καὶ κατὰ τὸν ποιητὴν ὀισσάμενος δόλον εἶναι, τὰ δὲ κατὰ τὴν ἐξ ἀρχῆς ὑπόθεσιν οὐδαμῶς κρίνων ἐκκυβεύειν οὐδὲ παραβάλλεσθαι τοῖς ὅλοις, ἦγε τὴν ἡσυχίαν ἐπὶ τῷ χάρακι καὶ προσεδέχετο τὴν ἡμέραν. κατὰ δὲ τὸν καιρὸν τοῦτον Ἀννίβας, προχωρούντων αὐτῷ τῶν πραγμάτων κατὰ τὴν ἐπιβολήν, τήν τε δύναμιν διεκόμισε διὰ τῶν στενῶν μετ’ ἀσφαλείας καὶ τὴν λείαν, λελοιπότων τοὺς τόπους τῶν παραφυλαττόντων τὰς δυσχωρίας. ἅμα δὲ τῷ φωτὶ συνιδὼν τοὺς ἐν τοῖς ἄκροις ἀντικαθημένους τοῖς λογχοφόροις ἐπαπέστειλέ τινας τῶν Ἰβήρων, οἳ καὶ συμμίξαντες κατέβαλον μὲν τῶν Ῥωμαίων εἰς χιλίους, ῥᾳδίως δὲ τοὺς παρὰ σφῶν εὐζώνους ἐκδεξάμενοι κατεβίβασαν. Ἀννίβας μὲν οὖν τοιαύτην ἐκ τοῦ Φαλέρνου ποιησάμενος τὴν ἔξοδον, λοιπὸν ἤδη στρατοπεδεύων ἀσφαλῶς κατεσκέπτετο καὶ προυνοεῖτο περὶ τῆς χειμασίας ποῦ καὶ πῶς ποιήσεται, μέγαν φόβον καὶ πολλὴν ἀπορίαν παρεστακὼς ταῖς πόλεσι καὶ τοῖς κατὰ τὴν Ἰταλίαν ἀνθρώποις. Φάβιος δὲ κακῶς μὲν ἤκουε παρὰ τοῖς πολλοῖς, ὡς ἀνάνδρως ἐκ τοιούτων τόπων προέμενος τοὺς ὑπεναντίους, οὐ μὴν ἀφίστατό γε τῆς προθέσεως. καὶ ἀναγκασθεὶς δὲ μετ’ ὀλίγας ἡμέρας ἐπί τινας ἀπελθεῖν θυσίας εἰς τὴν Ῥώμην παρέδωκεν τῷ συνάρχοντι τὰ στρατόπεδα καὶ πολλὰ χωριζόμενος ἐνετείλατο μὴ τοσαύτην ποιεῖσθαι σπουδὴν ὑπὲρ τοῦ βλάψαι τοὺς πολεμίους ἡλίκην ὑπὲρ τοῦ μηδὲν αὐτοὺς παθεῖν δεινόν. ὧν οὐδὲ μικρὸν ἐν νῷ τιθέμενος Μάρκος ἔτι λέγοντος αὐτοῦ ταῦτα πρὸς τῷ παραβάλλεσθαι καὶ τῷ διακινδυνεύειν ὅλος καὶ πᾶς ἦν.", "st": "3.94"}, {"sp": "N", "t": "τὰ μὲν οὖν κατὰ τὴν Ἰταλίαν τοιαύτην εἶχε τὴν διάθεσιν. κατὰ δὲ τοὺς αὐτοὺς καιροὺς ταῖς προειρημέναις πράξεσιν Ἀσδρούβας ὁ τεταγμένος ἐπὶ τῆς Ἰβηρίας στρατηγὸς κατηρτικὼς ἐν τῇ παραχειμασίᾳ τὰς ὑπὸ τἀδελφοῦ καταλειφθείσας τριάκοντα ναῦς καὶ δέκα προσπεπληρωκὼς ἄλλας, ἀρχομένης τῆς θερείας ἀνήχθη τετταράκοντα ναυσὶ καταφράκτοις ἐκ Καινῆς πόλεως, προχειρισάμενος Ἀμίλκαν τοῦ στόλου ναύαρχον. ἅμα δὲ καὶ τὴν πεζὴν ἐκ τῆς παραχειμασίας ἡθροικὼς δύναμιν ἀνέζευξε· καὶ ταῖς μὲν ναυσὶ παρὰ τὴν χέρσον ἐποιεῖτο τὸν πλοῦν, τοῖς δὲ πεζοῖς τὴν πορείαν παρὰ τὸν αἰγιαλόν, σπεύδων ἀμφοτέραις ἅμα ταῖς δυνάμεσι καταζεῦξαι πρὸς τὸν Ἴβηρα ποταμόν. Γνάιος δὲ τὰς ἐπιβολὰς συλλογιζόμενος τῶν Καρχηδονίων τὸ μὲν πρῶτον ἐπεβάλετο κατὰ γῆν καὶ κατὰ θάλατταν ἐκ τῆς παραχειμασίας ποιεῖσθαι τὴν ἀπάντησιν. ἀκούων δὲ τὸ πλῆθος τῶν δυνάμεων καὶ τὸ μέγεθος τῆς παρασκευῆς τὸ μὲν κατὰ γῆν ἀπαντᾶν ἀπεδοκίμασε, συμπληρώσας δὲ πέντε καὶ τριάκοντα ναῦς καὶ λαβὼν ἐκ τοῦ πεζικοῦ στρατεύματος τοὺς ἐπιτηδειοτάτους ἄνδρας πρὸς τὴν ἐπιβατικὴν χρείαν ἀνήχθη καὶ κατῆρε δευτεραῖος ἐκ Ταρράκωνος εἰς τοὺς περὶ τὸν Ἴβηρα ποταμὸν τόπους. καθορμισθεὶς δὲ τῶν πολεμίων ἐν ἀποστήματι περὶ τοὺς ὀγδοήκοντα σταδίους προαπέστειλε κατασκεψομένας δύο ναῦς ταχυπλοούσας Μασσαλιητικάς· καὶ γὰρ προκαθηγοῦντο καὶ προεκινδύνευον οὗτοι καὶ πᾶσαν ἀποτόμως σφίσι παρείχοντο τὴν χρείαν. εὐγενῶς γάρ, εἰ καί τινες ἕτεροι, κεκοινωνήκασι Ῥωμαίοις πραγμάτων καὶ Μασσαλιῶται, πολλάκις μὲν καὶ μετὰ ταῦτα, μάλιστα δὲ κατὰ τὸν Ἀννιβιακὸν πόλεμον. διασαφούντων δὲ τῶν ἐπὶ τὴν κατασκοπὴν ἐκπεμφθέντων ὅτι περὶ τὸ στόμα τοῦ ποταμοῦ συμβαίνει τὸν τῶν ὑπεναντίων ὁρμεῖν στόλον, ἀνήγετο κατὰ σπουδήν, βουλόμενος ἄφνω προσπεσεῖν τοῖς πολεμίοις.", "st": "3.95"}, {"sp": "N", "t": "οἱ δὲ περὶ τὸν Ἀσδρούβαν, σημηνάντων αὐτοῖς τῶν σκοπῶν ἐκ πολλοῦ τὸν ἐπίπλουν τῶν ὑπεναντίων, ἅμα τὰς πεζικὰς ἐξέταττον δυνάμεις παρὰ τὸν αἰγιαλὸν καὶ τοῖς πληρώμασι παρήγγελλον ἐμβαίνειν εἰς τὰς ναῦς. ἤδη δὲ καὶ τῶν Ῥωμαίων σύνεγγυς ὄντων, σημήναντες πολεμικὸν ἀνήγοντο, κρίναντες ναυμαχεῖν. συμβαλόντες δὲ τοῖς πολεμίοις βραχὺν μέν τινα χρόνον ἀντεποιήσαντο τῆς νίκης, μετ’ οὐ πολὺ δὲ πρὸς τὸ κλίνειν ὥρμησαν. ἡ γὰρ ἐφεδρεία τῶν πεζῶν ἡ περὶ τὸν αἰγιαλὸν οὐχ οὕτως αὐτοὺς ὤνησε, θάρσος παριστάνουσα πρὸς τὸν κίνδυνον, ὡς ἔβλαψε τὴν ἐλπίδα τῆς σωτηρίας ἑτοίμην παρασκευάζουσα. πλὴν δύο μὲν αὐτάνδρους νῆας ἀποβαλόντες, τεττάρων δὲ τοὺς ταρσοὺς καὶ τοὺς ἐπιβάτας ἔφευγον ἐκκλίναντες εἰς γῆν. ἐπικειμένων δὲ τῶν Ῥωμαίων αὐτοῖς ἐκθύμως, τὰς μὲν ναῦς ἐξέβαλον εἰς τὸν αἰγιαλόν, αὐτοὶ δ’ ἀποπηδήσαντες ἐκ τῶν πλοίων ἐσῴζοντο πρὸς τοὺς παρατεταγμένους. οἱ δὲ Ῥωμαῖοι τολμηρῶς συνεγγίσαντες τῇ γῇ καὶ τὰ δυνάμενα κινεῖσθαι τῶν πλοίων ἀναδησάμενοι μετὰ χαρᾶς ὑπερβαλλούσης ἀπέπλεον, νενικηκότες μὲν ἐξ ἐφόδου τοὺς ὑπεναντίους, κρατοῦντες δὲ τῆς θαλάττης, εἴκοσι δὲ καὶ πέντε ναῦς ἔχοντες τῶν πολεμίων. τὰ μὲν οὖν κατὰ τὴν Ἰβηρίαν ἀπὸ τούτων ἐπικυδεστέρας εἰλήφει τοῖς Ῥωμαίοις τὰς ἐλπίδας διὰ τὸ προειρημένον κατόρθωμα. οἱ δὲ Καρχηδόνιοι, προσπεσόντος αὐτοῖς τοῦ γεγονότος ἐλαττώματος, παραχρῆμα πληρώσαντες ἑβδομήκοντα νῆας ἐξαπέστειλαν, κρίναντες ἀναγκαῖον εἶναι πρὸς πάσας τὰς ἐπιβολὰς ἀντέχεσθαι τῆς θαλάττης. αἳ τὸ μὲν πρῶτον εἰς Σαρδόν’, ἐκεῖθεν δὲ πρὸς τοὺς περὶ Πίσας τόπους τῆς Ἰταλίας προσέβαλον, πεπεισμένων τῶν ἐπιπλεόντων συμμίξειν ἐνθάδε τοῖς περὶ τὸν Ἀννίβαν. ταχὺ δὲ τῶν Ῥωμαίων ἀναχθέντων ἐπ’ αὐτοὺς ἐξ αὐτῆς τῆς Ῥώμης ἑκατὸν εἴκοσι σκάφεσι πεντηρικοῖς, πυθόμενοι τὸν ἀνάπλουν οὗτοι μὲν αὖθις ἀπέπλευσαν εἰς τὴν Σαρδόνα, μετὰ δὲ ταῦτα πάλιν εἰς Καρχηδόνα. Γνάιος δὲ Σερουίλιος ἔχων τὸν προειρημένον στόλον ἕως μέν τινος ἐπηκολούθει τοῖς Καρχηδονίοις, συνάψειν πεπεισμένος, πολὺ δὲ καθυστερῶν ἀπέγνω. καὶ τὸ μὲν πρῶτον τῆς Σικελίας Λιλυβαίῳ προσέσχε· μετὰ δὲ ταῦτα καταπλεύσας τῆς Λιβύης ὡς ἐπὶ τὴν τῶν Κερκινητῶν νῆσον καὶ λαβὼν παρ’ αὐτῶν χρήματα τοῦ μὴ πορθῆσαι τὴν χώραν ἀπηλλάγη. κατὰ δὲ τὸν ἀνάπλουν γενόμενος κύριος νήσου Κοσσύρου καὶ φρουρὰν εἰς τὸ πολισμάτιον εἰσαγαγὼν αὖθις εἰς τὸ Λιλύβαιον κατῆρε. καὶ τὸ λοιπὸν οὗτος μὲν αὐτοῦ συνορμίσας τὸν στόλον μετ’ οὐ πολὺν χρόνον αὐτὸς ἀνεκομίσθη πρὸς τὰς πεζικὰς δυνάμεις·", "st": "3.96"}, {"sp": "N", "t": "οἱ δ’ ἐκ τῆς συγκλήτου πυθόμενοι τὸ γεγονὸς προτέρημα διὰ τοῦ Γναΐου περὶ τὴν ναυμαχίαν καὶ νομίσαντες χρήσιμον εἶναι, μᾶλλον δ’ ἀναγκαῖον τὸ μὴ προΐεσθαι τὰ κατὰ τὴν Ἰβηρίαν, ἀλλ’ ἐνίστασθαι τοῖς Καρχηδονίοις καὶ τὸν πόλεμον αὔξειν, προχειρισάμενοι ναῦς εἴκοσι καὶ στρατηγὸν ἐπιστήσαντες Πόπλιον Σκιπίωνα κατὰ τὴν ἐξ ἀρχῆς πρόθεσιν, ἐξαπέστελλον μετὰ σπουδῆς πρὸς τὸν ἀδελφὸν Γνάιον, κοινῇ πράξοντα μετ’ ἐκείνου τὰ κατὰ τὴν Ἰβηρίαν. πάνυ γὰρ ἠγωνίων μὴ κρατήσαντες Καρχηδόνιοι τῶν τόπων ἐκείνων καὶ περιποιησάμενοι χορηγίας ἀφθόνους καὶ χεῖρας ἀντιποιήσωνται μὲν τῆς θαλάττης ὁλοσχερέστερον, συνεπιθῶνται δὲ τοῖς κατὰ τὴν Ἰταλίαν, στρατόπεδα πέμποντες καὶ χρήματα τοῖς περὶ τὸν Ἀννίβαν. διόπερ ἐν μεγάλῳ τιθέμενοι καὶ τοῦτον τὸν πόλεμον ἐξαπέστειλαν τάς τε ναῦς καὶ τὸν Πόπλιον. ὃς καὶ παραγενόμενος εἰς Ἰβηρίαν καὶ συμμίξας τἀδελφῷ μεγάλην παρεῖχε χρείαν τοῖς κοινοῖς πράγμασιν. οὐδέποτε γὰρ πρότερον θαρρήσαντες διαβῆναι τὸν Ἴβηρα ποταμόν, ἀλλ’ ἀσμενίζοντες τῇ τῶν ἐπὶ τάδε φιλίᾳ καὶ συμμαχίᾳ τότε διέβησαν καὶ τότε πρῶτον ἐθάρρησαν ἀντιποιεῖσθαι τῶν πέραν πραγμάτων, μεγάλα καὶ ταὐτομάτου συνεργήσαντος σφίσι πρὸς τοὺς περιεστῶτας καιρούς. ἐπειδὴ γὰρ καταπληξάμενοι τοὺς περὶ τὴν διάβασιν οἰκοῦντας τῶν Ἰβήρων ἧκον πρὸς τὴν τῶν Ζακανθαίων πόλιν, ἀποσχόντες σταδίους ὡς τετταράκοντα περὶ τὸ τῆς Ἀφροδίτης ἱερὸν κατεστρατοπέδευσαν, λαβόντες τόπον εὐφυῶς κείμενον πρός τε τὴν ἀπὸ τῶν πολεμίων ἀσφάλειαν καὶ πρὸς τὴν ἐκ θαλάττης χορηγίαν· ὁμοῦ γὰρ αὐτοῖς συνέβαινε καὶ τὸν στόλον ποιεῖσθαι τὸν παράπλουν. ἔνθα δὴ γίνεταί τις πραγμάτων περιπέτεια τοιάδε.", "st": "3.97"}, {"sp": "N", "t": "καθ’ οὓς καιροὺς Ἀννίβας ἐποιεῖτο τὴν πορείαν εἰς Ἰταλίαν, ὅσαις πόλεσιν ἠπίστησε τῶν κατὰ τὴν Ἰβηρίαν, ἔλαβε παρὰ τούτων ὅμηρα τοὺς υἱεῖς τῶν ἐπιφανεστάτων ἀνδρῶν· οὓς πάντας εἰς τὴν Ζακανθαίων ἀπέθετο πόλιν διά τε τὴν ὀχυρότητα καὶ διὰ τὴν τῶν ἀπολειπομένων ἐπ’ αὐτῆς ἀνδρῶν πίστιν. ἦν δέ τις ἀνὴρ Ἴβηρ, Ἀβίλυξ ὄνομα, κατὰ μὲν τὴν δόξαν καὶ τὴν τοῦ βίου περίστασιν οὐδενὸς δεύτερος Ἰβήρων, κατὰ δὲ τὴν πρὸς Καρχηδονίους εὔνοιαν καὶ πίστιν πολύ τι διαφέρειν δοκῶν τῶν ἄλλων. οὗτος θεωρῶν τὰ πράγματα καὶ νομίσας ἐπικυδεστέρας εἶναι τὰς τῶν Ῥωμαίων ἐλπίδας, συνελογίσατο παρ’ ἑαυτῷ περὶ τῆς τῶν ὁμήρων προδοσίας συλλογισμὸν Ἰβηρικὸν καὶ βαρβαρικόν. πεισθεὶς γὰρ διότι δύναται μέγας γενέσθαι παρὰ Ῥωμαίοις προσενεγκάμενος ἐν καιρῷ πίστιν ἅμα καὶ χρείαν, ἐγίνετο πρὸς τῷ παρασπονδήσας τοὺς Καρχηδονίους ἐγχειρίσαι τοὺς ὁμήρους τοῖς Ῥωμαίοις. θεωρῶν δὲ τὸν Βώστορα τὸν τῶν Καρχηδονίων στρατηγόν, ὃς ἀπεστάλη μὲν ὑπ’ Ἀσδρούβου κωλύσων τοὺς Ῥωμαίους διαβαίνειν τὸν ποταμόν, οὐ θαρρήσας δὲ τοῦτο ποιεῖν ἀνακεχωρηκὼς ἐστρατοπέδευε τῆς Ζακάνθης ἐν τοῖς πρὸς θάλατταν μέρεσιν, τοῦτον μὲν ἄκακον ὄντα τὸν ἄνδρα καὶ πρᾷον τῇ φύσει, πιστῶς δὲ τὰ πρὸς αὐτὸν διακείμενον, ποιεῖται λόγους ὑπὲρ τῶν ὁμήρων πρὸς τὸν Βώστορα φάσκων, ἐπειδὴ διαβεβήκασι Ῥωμαῖοι τὸν ποταμόν, οὐκέτι δύνασθαι Καρχηδονίους φόβῳ συνέχειν τὰ κατὰ τὴν Ἰβηρίαν, προσδεῖσθαι δὲ τοὺς καιροὺς τῆς τῶν ὑποταττομένων εὐνοίας· νῦν οὖν ἠγγικότων Ῥωμαίων καὶ προσκαθεζομένων τῇ Ζακάνθῃ, καὶ κινδυνευούσης τῆς πόλεως, ἐὰν ἐξαγαγὼν τοὺς ὁμήρους ἀποκαταστήσῃ τοῖς γονεῦσι καὶ ταῖς πόλεσιν, ἐκλύσειν μὲν αὐτὸν τῶν Ῥωμαίων τὴν φιλοτιμίαν· τοῦτο γὰρ αὐτὸ καὶ μάλιστα σπουδάζειν ἐκείνους πρᾶξαι, κυριεύοντας τῶν ὁμήρων· ἐκκαλέσεσθαι δὲ τὴν τῶν Ἰβήρων πάντων πρὸς Καρχηδονίους εὔνοιαν, προϊδόμενον τὸ μέλλον καὶ προνοηθέντα τῆς τῶν ὁμήρων ἀσφαλείας. τὴν δὲ χάριν αὐξήσειν ἔφη πολλαπλασίαν, αὐτὸς γενόμενος χειριστὴς τοῦ πράγματος. ἀποκαθιστάνων γὰρ εἰς τὰς πόλεις τοὺς παῖδας οὐ μόνον τὴν παρ’ αὐτῶν εὔνοιαν ἐπισπάσεσθαι τῶν γεννησάντων ἀλλὰ καὶ παρὰ τῶν πολλῶν, ὑπὸ τὴν ὄψιν τιθεὶς διὰ τοῦ συμβαίνοντος τὴν Καρχηδονίων πρὸς τοὺς συμμάχους αἵρεσιν καὶ μεγαλοψυχίαν. προσδοκᾶν δ’ αὐτὸν ἐκέλευσε καὶ δώρων πλῆθος ἰδίᾳ παρὰ τῶν τὰ τέκνα κομιζομένων· παραδόξως γὰρ ἑκάστους ἐγκρατεῖς γινομένους τῶν ἀναγκαιοτάτων ἅμιλλαν ποιήσεσθαι τῆς εἰς τὸν κύριον τῶν πραγμάτων εὐεργεσίας. παραπλήσια δὲ τούτοις ἕτερα καὶ πλείω πρὸς τὸν αὐτὸν τρόπον διαλεχθεὶς ἔπεισε τὸν Βώστορα συγκαταθέσθαι τοῖς λεγομένοις.", "st": "3.98"}, {"sp": "N", "t": "καὶ τότε μὲν ἐπανῆλθε, ταξάμενος ἡμέραν, ᾗ παρέσται μετὰ τῶν ἐπιτηδείων πρὸς τὴν ἀνακομιδὴν τῶν παίδων. παραγενηθεὶς δὲ νυκτὸς ἐπὶ τὸ τῶν Ῥωμαίων στρατόπεδον καὶ συμμίξας τισὶ τῶν συστρατευομένων ἐκείνοις Ἰβήρων διὰ τούτων εἰσῆλθε πρὸς τοὺς στρατηγούς. ἐκλογιζόμενος δὲ διὰ πλειόνων τὴν ἐσομένην ὁρμὴν καὶ μετάπτωσιν πρὸς αὐτοὺς τῶν Ἰβήρων, ἐὰν ἐγκρατεῖς γένωνται τῶν ὁμήρων, ἐπηγγείλατο παραδώσειν αὐτοῖς τοὺς παῖδας. τῶν δὲ περὶ τὸν Πόπλιον ὑπερβολῇ προθύμως δεξαμένων τὴν ἐλπίδα καὶ μεγάλας ὑπισχνουμένων δωρεάς, τότε μὲν εἰς τὴν ἰδίαν ἀπηλλάγη, συνθέμενος ἡμέραν καὶ καιρὸν καὶ τόπον, ἐν ᾧ δεήσει τοὺς ἐκδεξομένους αὐτὸν ὑπομένειν. μετὰ δὲ ταῦτα παραλαβὼν τοὺς ἐπιτηδείους τῶν φίλων ἧκε πρὸς τὸν Βώστορα καί, παραδοθέντων αὐτῷ τῶν παίδων ἐκ τῆς Ζακάνθης, νυκτὸς ποιησάμενος τὴν ἔξοδον, ὡς θέλων λαθεῖν, παραπορευθεὶς τὸν χάρακα τῶν πολεμίων ἧκε πρὸς τὸν τεταγμένον καιρὸν καὶ τόπον καὶ πάντας ἐνεχείρισε τοὺς ὁμήρους τοῖς ἡγεμόσι τῶν Ῥωμαίων. οἱ δὲ περὶ τὸν Πόπλιον ἐτίμησάν τε διαφερόντως τὸν Ἀβίλυγα καὶ πρὸς τὴν ἀποκατάστασιν τῶν ὁμήρων εἰς τὰς πατρίδας ἐχρήσαντο τούτῳ, συμπέμψαντες τοὺς ἐπιτηδείους. ὃς ἐπιπορευόμενος τὰς πόλεις καὶ διὰ τῆς τῶν παίδων ἀποκαταστάσεως τιθεὶς ὑπὸ τὴν ὄψιν τὴν τῶν Ῥωμαίων πρᾳότητα καὶ μεγαλοψυχίαν παρὰ τὴν Καρχηδονίων ἀπιστίαν καὶ βαρύτητα καὶ προσπαρατιθεὶς τὴν αὑτοῦ μετάθεσιν πολλοὺς Ἰβήρων παρώρμησε πρὸς τὴν τῶν Ῥωμαίων φιλίαν. Βώστωρ δὲ παιδικώτερον ἢ κατὰ τὴν ἡλικίαν δόξας ἐγκεχειρικέναι τοὺς ὁμήρους τοῖς πολεμίοις οὐκ εἰς τοὺς τυχόντας ἐπεπτώκει κινδύνους. καὶ τότε μέν, ἤδη τῆς ὥρας κατεπειγούσης, διέλυον εἰς παραχειμασίαν ἀμφότεροι τὰς δυνάμεις, ἱκανοῦ τινος ἐκ τῆς τύχης γεγονότος συνεργήματος τοῖς Ῥωμαίοις τοῦ περὶ τοὺς παῖδας πρὸς τὰς ἐπικειμένας ἐπιβολάς. καὶ τὰ μὲν κατὰ τὴν Ἰβηρίαν ἐν τούτοις ἦν.", "st": "3.99"}, {"sp": "N", "t": "ὁ δὲ στρατηγὸς Ἀννίβας, ὅθεν ἀπελίπομεν, πυνθανόμενος παρὰ τῶν κατασκόπων πλεῖστον ὑπάρχειν σῖτον ἐν τῇ περὶ τὴν Λουκαρίαν καὶ τὸ καλούμενον Γερούνιον χώρᾳ, πρὸς δὲ τὴν συναγωγὴν εὐφυῶς ἔχειν τὸ Γερούνιον, κρίνας ἐκεῖ ποιεῖσθαι τὴν παραχειμασίαν, προῆγε ποιούμενος τὴν πορείαν παρὰ τὸ Λίβυρνον ὄρος ἐπὶ τοὺς προειρημένους τόπους. ἀφικόμενος δὲ πρὸς τὸ Γερούνιον, ὃ τῆς Λουκαρίας ἀπέχει διακόσια στάδια, τὰς μὲν ἀρχὰς διὰ λόγων τοὺς ἐνοικοῦντας εἰς φιλίαν προυκαλεῖτο καὶ πίστεις ἐδίδου τῶν ἐπαγγελιῶν, οὐδενὸς δὲ προσέχοντος, πολιορκεῖν ἐπεβάλετο. ταχὺ δὲ γενόμενος κύριος τοὺς μὲν οἰκήτορας κατέφθειρε, τὰς δὲ πλείστας οἰκίας ἀκεραίους διεφύλαξε καὶ τὰ τείχη, βουλόμενος σιτοβολίοις χρήσασθαι πρὸς τὴν παραχειμασίαν. τὴν δὲ δύναμιν πρὸ τῆς πόλεως παρεμβαλὼν ὠχυρώσατο τάφρῳ καὶ χάρακι τὴν στρατοπεδείαν. γενόμενος δ’ ἀπὸ τούτων τὰ μὲν δύο μέρη τῆς δυνάμεως ἐπὶ τὴν σιτολογίαν ἐξέπεμπε, προστάξας καθ’ ἑκάστην ἡμέραν τακτὸν ἀναφέρειν μέτρον ἕκαστον τοῖς ἰδίοις, ἐπιβολὴν τοῦ τάγματος τοῖς προκεχειρισμένοις ἐπὶ τὴν οἰκονομίαν ταύτην, τῷ δὲ τρίτῳ μέρει τήν τε στρατοπεδείαν ἐτήρει καὶ τοῖς σιτολογοῦσι παρεφήδρευε κατὰ τόπους. οὔσης δὲ τῆς μὲν χώρας τῆς πλείστης εὐεφόδου καὶ πεδιάδος, τῶν δὲ συναγόντων ὡς ἔπος εἰπεῖν ἀναριθμήτων, ἔτι δὲ τῆς ὥρας ἀκμαζούσης πρὸς τὴν συγκομιδήν, ἄπλετον συνέβαινε καθ’ ἑκάστην ἡμέραν ἁθροίζεσθαι τοῦ σίτου τὸ πλῆθος.", "st": "3.100"}, {"sp": "N", "t": "Μάρκος δὲ παρειληφὼς τὰς δυνάμεις παρὰ Φαβίου τὸ μὲν πρῶτον ἀντιπαρῆγε ταῖς ἀκρωρείαις, πεπεισμένος ἀεὶ περὶ τὰς ὑπερβολὰς συμπεσεῖσθαί ποτε τοῖς Καρχηδονίοις. ἀκούσας δὲ τὸ μὲν Γερούνιον τοὺς περὶ τὸν Ἀννίβαν ἤδη κατέχειν, τὴν δὲ χώραν σιτολογεῖν, πρὸ δὲ τῆς πόλεως χάρακα βεβλημένους στρατοπεδεύειν, ἐπιστρέψας ἐκ τῶν ἀκρωρειῶν κατέβαινε κατὰ τὴν ἐπὶ τὰ πεδία κατατείνουσαν ῥάχιν. ἀφικόμενος δ’ ἐπὶ τὴν ἄκραν, ἣ κεῖται μὲν ἐπὶ τῆς Λαρινάτιδος χώρας προσαγορεύεται δὲ Καλήνη, κατεστρατοπέδευσε περὶ ταύτην, πρόχειρος ὢν ἐκ παντὸς τρόπου συμπλέκεσθαι τοῖς πολεμίοις. Ἀννίβας δὲ θεωρῶν ἐγγίζοντας τοὺς πολεμίους τὸ μὲν τρίτον μέρος τῆς δυνάμεως εἴασε σιτολογεῖν, τὰ δὲ δύο μέρη λαβὼν καὶ προελθὼν ἀπὸ τῆς πόλεως ἑκκαίδεκα σταδίους πρὸς τοὺς πολεμίους ἐπί τινος βουνοῦ κατεστρατοπέδευσε, βουλόμενος ἅμα μὲν καταπλήξασθαι τοὺς ὑπεναντίους, ἅμα δὲ τοῖς σιτολογοῦσι τὴν ἀσφάλειαν παρασκευάζειν. μετὰ δὲ ταῦτα, γεωλόφου τινὸς ὑπάρχοντος μεταξὺ τῶν στρατοπέδων, ὃς εὐκαίρως καὶ σύνεγγυς ἐπέκειτο τῇ τῶν πολεμίων παρεμβολῇ, τοῦτον ἔτι νυκτὸς ἐξαποστείλας περὶ δισχιλίους τῶν λογχοφόρων κατελάβετο. οὓς ἐπιγενομένης τῆς ἡμέρας συνιδὼν Μάρκος ἐξῆγε τοὺς εὐζώνους καὶ προσέβαλε τῷ λόφῳ. γενομένου δ’ ἀκροβολισμοῦ νεανικοῦ, τέλος ἐπεκράτησαν οἱ Ῥωμαῖοι καὶ μετὰ ταῦτα τὴν ὅλην στρατοπεδείαν μετεβίβασαν εἰς τοῦτον τὸν τόπον. ὁ δ’ Ἀννίβας ἕως μέν τινος διὰ τὴν ἀντιστρατοπεδείαν συνεῖχεν τὸ πλεῖστον μέρος τῆς δυνάμεως ἐφ’ αὑτόν. πλειόνων δὲ γενομένων ἡμερῶν, ἠναγκάζετο τοὺς μὲν ἐπὶ τὴν νομὴν τῶν θρεμμάτων ἀπομερίζειν τοὺς δ’ ἐπὶ τὴν σιτολογίαν, σπουδάζων κατὰ τὴν ἐν ἀρχῇ πρόθεσιν μήτε τὴν λείαν καταφθεῖραι τόν τε σῖτον ὡς πλεῖστον συναγαγεῖν, ἵνα πάντων ᾖ κατὰ τὴν παραχειμασίαν δαψίλεια τοῖς ἀνδράσιν, μὴ χεῖρον δὲ τοῖς ὑποζυγίοις καὶ τοῖς ἵπποις· εἶχε γὰρ τὰς πλείστας ἐλπίδας τῆς αὑτοῦ δυνάμεως ἐν τῷ τῶν ἱππέων τάγματι.", "st": "3.101"}, {"sp": "N", "t": "καθ’ ὃν δὴ καιρὸν Μάρκος συνθεωρήσας τὸ πολὺ μέρος τῶν ὑπεναντίων ἐπὶ τὰς προειρημένας χρείας κατὰ τῆς χώρας σκεδαννύμενον, λαβὼν τὸν ἀκμαιότατον καιρὸν τῆς ἡμέρας ἐξῆγε τὴν δύναμιν καὶ συνεγγίσας τῇ παρεμβολῇ τῶν Καρχηδονίων τὰ μὲν βαρέα τῶν ὅπλων ἐξέταξε, τοὺς δ’ ἱππεῖς καὶ τοὺς εὐζώνους κατὰ μέρη διελὼν ἐπαφῆκε τοῖς προνομεύουσι, παραγγείλας μηδένα ζωγρεῖν. Ἀννίβας δὲ τούτου συμβάντος εἰς ἀπορίαν ἐνεπεπτώκει μεγάλην· οὔτε γὰρ ἀντεξάγειν τοῖς παρατεταγμένοις ἀξιόχρεως ἦν οὔτε παραβοηθεῖν τοῖς ἐπὶ τῆς χώρας διεσπαρμένοις. τῶν δὲ Ῥωμαίων οἱ μὲν ἐπὶ τοὺς προνομεύοντας ἐξαποσταλέντες πολλοὺς τῶν ἐσκεδασμένων ἀπέκτειναν· οἱ δὲ παρατεταγμένοι τέλος εἰς τοῦτ’ ἦλθον καταφρονήσεως ὥστε καὶ διασπᾶν τὸν χάρακα καὶ μόνον οὐ πολιορκεῖν τοὺς Καρχηδονίους. ὁ δ’ Ἀννίβας ἦν μὲν ἐν κακοῖς, ὅμως δὲ χειμαζόμενος ἔμενε, τοὺς πελάζοντας ἀποτριβόμενος καὶ μόλις διαφυλάττων τὴν παρεμβολήν, ἕως Ἀσδρούβας ἀναλαβὼν τοὺς ἀπὸ τῆς χώρας συμπεφευγότας εἰς τὸν χάρακα τὸν περὶ τὸ Γερούνιον, ὄντας εἰς τετρακισχιλίους, ἧκε παραβοηθῶν. τότε δὲ μικρὸν ἀναθαρρήσας ἐπεξῆλθε καὶ βραχὺ πρὸ τῆς στρατοπεδείας παρεμβαλὼν μόλις ἀπεστρέψατο τὸν ἐνεστῶτα κίνδυνον. Μάρκος δὲ πολλοὺς μὲν ἐν τῇ περὶ τὸν χάρακα συμπλοκῇ τῶν πολεμίων ἀποκτείνας, ἔτι δὲ πλείους ἐπὶ τῆς χώρας διεφθαρκώς, τότε μὲν ἐπανῆλθεν, μεγάλας ἐλπίδας ἔχων ὑπὲρ τοῦ μέλλοντος. τῇ δ’ ἐπαύριον ἐκλιπόντων τὸν χάρακα τῶν Καρχηδονίων, ἐπέβη καὶ κατελάβετο τὴν ἐκείνων παρεμβολήν. ὁ γὰρ Ἀννίβας διαγωνιάσας τοὺς Ῥωμαίους μὴ καταλαβόμενοι νυκτὸς ἔρημον ὄντα τὸν ἐπὶ τῷ Γερουνίῳ χάρακα κύριοι γένωνται τῆς ἀποσκευῆς καὶ τῶν παραθέσεων, ἔκρινεν αὐτὸς ἀναχωρεῖν καὶ πάλιν ἐκεῖ ποιεῖσθαι τὴν στρατοπεδείαν. ἀπὸ δὲ τούτων τῶν καιρῶν οἱ μὲν Καρχηδόνιοι ταῖς προνομαῖς εὐλαβέστερον ἐχρῶντο καὶ φυλακτικώτερον, οἱ δὲ Ῥωμαῖοι τἀναντία θαρραλεώτερον καὶ προπετέστερον.", "st": "3.102"}, {"sp": "N", "t": "οἱ δ’ ἐν τῇ Ῥώμῃ, προσπεσόντος σφίσι τοῦ γεγονότος μειζόνως ἢ κατὰ τὴν ἀλήθειαν, περιχαρεῖς ἦσαν διὰ τὸ πρῶτον μὲν ἐκ τῆς προϋπαρχούσης ὑπὲρ τῶν ὅλων δυσελπιστίας οἱονεὶ μεταβολήν τινα πρὸς τὸ βέλτιον αὐτοῖς προφαίνεσθαι, δεύτερον δὲ καὶ διὰ τὸ δοκεῖν τὸν πρὸ τούτου χρόνον τὴν ἀπραγίαν καὶ κατάπληξιν τῶν στρατοπέδων μὴ παρὰ τὴν τῶν δυνάμεων ἀποδειλίασιν, ἀλλὰ παρὰ τὴν τοῦ προεστῶτος εὐλάβειαν γεγονέναι. διὸ καὶ τὸν μὲν Φάβιον ᾐτιῶντο καὶ κατεμέμφοντο πάντες ὡς ἀτόλμως χρώμενον τοῖς καιροῖς, τὸν δὲ Μάρκον ἐπὶ τοσοῦτον ηὖξον διὰ τὸ συμβεβηκὸς ὥστε τότε γενέσθαι τὸ μηδέποτε γεγονός· αὐτοκράτορα γὰρ κἀκεῖνον κατέστησαν, πεπεισμένοι ταχέως αὐτὸν τέλος ἐπιθήσειν τοῖς πράγμασι· καὶ δὴ δύο δικτάτορες ἐγεγόνεισαν ἐπὶ τὰς αὐτὰς πράξεις, ὃ πρότερον οὐδέποτε συνεβεβήκει παρὰ Ῥωμαίοις. τῷ δὲ Μάρκῳ διασαφηθείσης τῆς τε τοῦ πλήθους εὐνοίας καὶ τῆς παρὰ τοῦ δήμου δεδομένης ἀρχῆς αὐτῷ, διπλασίως παρωρμήθη πρὸς τὸ παραβάλλεσθαι καὶ κατατολμᾶν τῶν πολεμίων. ἧκε δὲ καὶ Φάβιος ἐπὶ τὰς δυνάμεις οὐδὲν ἠλλοιωμένος ὑπὸ τῶν συμβεβηκότων, ἔτι δὲ βεβαιότερον μένων ἐπὶ τῆς ἐξ ἀρχῆς διαλήψεως. θεωρῶν δὲ τὸν Μάρκον ἐκπεφυσημένον καὶ πρὸς πάντ’ ἀντιφιλονικοῦντα καὶ καθόλου πολὺν ὄντα πρὸς τῷ διακινδυνεύειν, αἵρεσιν αὐτῷ προύτεινε τοιαύτην, ἢ κατὰ μέρος ἄρχειν ἢ διελόμενον τὰς δυνάμεις χρῆσθαι τοῖς σφετέροις στρατοπέδοις κατὰ τὴν αὑτοῦ προαίρεσιν. τοῦ δὲ καὶ λίαν ἀσμένως δεξαμένου τὸν μερισμόν, διελόμενοι τὸ πλῆθος χωρὶς ἐστρατοπέδευσαν ἀλλήλων, ἀπέχοντες ὡς δώδεκα σταδίους.", "st": "3.103"}, {"sp": "N", "t": "Ἀννίβας δὲ τὰ μὲν ἀκούων τῶν ἁλισκομένων αἰχμαλώτων, τὰ δὲ θεωρῶν ἐκ τῶν πραττομένων ᾔδει τήν τε τῶν ἡγεμόνων πρὸς ἀλλήλους φιλοτιμίαν καὶ τὴν ὁρμὴν καὶ τὴν φιλοδοξίαν τοῦ Μάρκου. διόπερ οὐ καθ’ αὑτοῦ, πρὸς αὑτοῦ δὲ νομίσας εἶναι τὰ συμβαίνοντα περὶ τοὺς ἐναντίους, ἐγίνετο περὶ τὸν Μάρκον, σπουδάζων τὴν τόλμαν ἀφελέσθαι καὶ προκαταλαβεῖν αὐτοῦ τὴν ὁρμήν. οὔσης δέ τινος ὑπεροχῆς μεταξὺ τῆς αὐτοῦ καὶ τῆς τοῦ Μάρκου στρατοπεδείας δυναμένης ἑκατέρους βλάπτειν, ἐπεβάλετο καταλαβεῖν ταύτην. σαφῶς δὲ γινώσκων ἐκ τοῦ προγεγονότος κατορθώματος ὅτι παρέσται βοηθῶν ἐκ χειρὸς πρὸς ταύτην τὴν ἐπιβολήν, ἐπινοεῖ τι τοιοῦτον. τῶν γὰρ τόπων τῶν περὶ τὸν λόφον ὑπαρχόντων ψιλῶν μέν, πολλὰς δὲ καὶ παντοδαπὰς ἐχόντων περικλάσεις κοιλότητας, ἐξέπεμψε τῆς νυκτὸς εἰς τὰς ἐπιτηδειοτάτας ὑποβολὰς ἀνὰ διακοσίους καὶ τριακοσίους, πεντακοσίους μὲν ἱππεῖς, ψιλοὺς δὲ καὶ πεζοὺς τοὺς πάντας εἰς πεντακισχιλίους. ἵνα δὲ μὴ πρῲ κατοπτευθῶσιν ὑπὸ τῶν εἰς τὰς προνομὰς ἐκπορευομένων, ἅμα τῷ διαυγάζειν κατελάμβανε τοῖς εὐζώνοις τὸν λόφον. ὁ δὲ Μάρκος θεωρῶν τὸ γινόμενον καὶ νομίσας ἑρμαῖον εἶναι παραυτίκα μὲν ἐξαπέστειλε τοὺς ψιλούς, κελεύσας ἀγωνίζεσθαι καὶ διαμάχεσθαι περὶ τοῦ τόπου, μετὰ δὲ ταῦτα τοὺς ἱππεῖς· ἑξῆς δὲ τούτοις κατόπιν αὐτὸς ἦγε συνεχῆ τὰ βαρέα τῶν ὅπλων, καθάπερ καὶ πρότερον, ἑκάστων ποιούμενος παραπλήσιον τὸν χειρισμόν.", "st": "3.104"}, {"sp": "N", "t": "ἄρτι δὲ τῆς ἡμέρας διαφαινούσης, καὶ πάντων ταῖς τε διανοίαις καὶ τοῖς ὄμμασι περιεσπασμένων περὶ τοὺς ἐν τῷ γεωλόφῳ κινδυνεύοντας, ἀνύποπτος ἦν ἡ τῶν ἐνεδρευόντων ὑποβολή. τοῦ δ’ Ἀννίβου συνεχῶς μὲν ἐπαποστέλλοντος τοῖς ἐν τῷ λόφῳ τοὺς βοηθήσοντας, ἑπομένου δὲ κατὰ πόδας αὐτοῦ μετὰ τῶν ἱππέων καὶ τῆς δυνάμεως, ταχέως συνέβη καὶ τοὺς ἱππεῖς συμπεσεῖν ἀλλήλοις. οὗ γενομένου, καὶ πιεζομένων τῶν Ῥωμαίων εὐζώνων ὑπὸ τοῦ πλήθους τῶν ἱππέων, ἅμα μὲν οὗτοι καταφεύγοντες εἰς τὰ βαρέα τῶν ὅπλων θόρυβον ἐποίουν, ἅμα δὲ τοῦ συνθήματος ἀποδοθέντος τοῖς ἐν ταῖς ἐνέδραις, πανταχόθεν ἐπιφαινομένων καὶ προσπιπτόντων τούτων, οὐκέτι περὶ τοὺς εὐζώνους μόνον, ἀλλὰ περὶ πᾶν τὸ στράτευμα μέγας κίνδυνος συνειστήκει τοῖς Ῥωμαίοις. κατὰ δὲ τὸν καιρὸν τοῦτον Φάβιος θεωρῶν τὸ γινόμενον καὶ διαγωνιάσας μὴ σφαλῶσι τοῖς ὅλοις, ἐξῆγε τὰς δυνάμεις καὶ κατὰ σπουδὴν ἐβοήθει τοῖς κινδυνεύουσι. ταχὺ δὲ συνεγγίσαντος αὐτοῦ, πάλιν ἀναθαρρήσαντες οἱ Ῥωμαῖοι, καίπερ λελυκότες ἤδη τὴν ὅλην τάξιν, αὖθις ἁθροιζόμενοι περὶ τὰς σημείας ἀνεχώρουν καὶ κατέφευγον ὑπὸ τὴν τούτων ἀσφάλειαν, πολλοὺς μὲν ἀπολελωκότες τῶν εὐζώνων, ἔτι δὲ πλείους ἐκ τῶν ταγμάτων καὶ τοὺς ἀρίστους ἄνδρας. οἱ δὲ περὶ τὸν Ἀννίβαν καταπλαγέντες τὴν ἀκεραιότητα καὶ σύνταξιν τῶν παραβεβοηθηκότων στρατοπέδων ἀπέστησαν τοῦ διωγμοῦ καὶ τῆς μάχης. τοῖς μὲν οὖν παρ’ αὐτὸν γενομένοις τὸν κίνδυνον ἦν ἐναργὲς ὅτι διὰ μὲν τὴν Μάρκου τόλμαν ἀπόλωλε τὰ ὅλα, διὰ δὲ τὴν εὐλάβειαν τοῦ Φαβίου σέσωσται καὶ πρὸ τοῦ καὶ νῦν· τοῖς δ’ ἐν τῇ Ῥώμῃ τότ’ ἐγένετο φανερὸν ὁμολογουμένως τί διαφέρει στρατιωτικῆς προπετείας καὶ κενοδοξίας στρατηγικὴ πρόνοια καὶ λογισμὸς ἑστὼς καὶ νουνεχής. οὐ μὴν ἀλλ’ οἱ μὲν Ῥωμαῖοι διδαχθέντες ὑπὸ τῶν πραγμάτων καὶ βαλόμενοι χάρακα πάλιν ἕνα πάντες ἐστρατοπέδευσαν ὁμόσε καὶ λοιπὸν ἤδη Φαβίῳ προσεῖχον τὸν νοῦν καὶ τοῖς ὑπὸ τούτου παραγγελλομένοις. οἱ δὲ Καρχηδόνιοι τὸν μὲν μεταξὺ τόπον τοῦ βουνοῦ καὶ τῆς σφετέρας παρεμβολῆς διετάφρευσαν, περὶ δὲ τὴν κορυφὴν τοῦ καταληφθέντος λόφου χάρακα περιβαλόντες καὶ φυλακὴν ἐπιστήσαντες λοιπὸν ἤδη πρὸς τὴν χειμασίαν ἀσφαλῶς ἡτοιμάζοντο.", "st": "3.105"}, {"sp": "N", "t": "τῆς δὲ τῶν ἀρχαιρεσίων ὥρας συνεγγιζούσης, εἵλοντο στρατηγοὺς οἱ Ῥωμαῖοι Λεύκιον Αἰμίλιον καὶ Γάιον Τερέντιον. ὧν κατασταθέντων οἱ μὲν δικτάτορες ἀπέθεντο τὴν ἀρχήν, οἱ δὲ προϋπάρχοντες ὕπατοι, Γνάιος Σερουίλιος καὶ Μάρκος Ῥήγουλος ὁ μετὰ τὴν Φλαμινίου τελευτὴν ἐπικατασταθείς, τότε προχειρισθέντες ὑπὸ τῶν περὶ τὸν Αἰμίλιον ἀντιστράτηγοι καὶ παραλαβόντες τὴν ἐν τοῖς ὑπαίθροις ἐξουσίαν ἐχείριζον κατὰ τὴν ἑαυτῶν γνώμην τὰ κατὰ τὰς δυνάμεις. οἱ δὲ περὶ τὸν Αἰμίλιον βουλευσάμενοι μετὰ τῆς συγκλήτου τὸ μὲν ἐλλεῖπον πλῆθος ἔτι τῶν στρατιωτῶν πρὸς τὴν ὅλην ἐπιβολὴν παραχρῆμα καταγράψαντες ἐξαπέστειλαν, τοῖς δὲ περὶ τὸν Γνάιον διεσάφησαν ὁλοσχερῆ μὲν κίνδυνον κατὰ μηδένα τρόπον συνίστασθαι, τοὺς δὲ κατὰ μέρος ἀκροβολισμοὺς ὡς ἐνεργοτάτους ποιεῖσθαι καὶ συνεχεστάτους χάριν τοῦ γυμνάζειν καὶ παρασκευάζειν εὐθαρσεῖς τοὺς νέους πρὸς τοὺς ὁλοσχερεῖς ἀγῶνας, τῷ καὶ τὰ πρότερον αὐτοῖς συμπτώματα δοκεῖν οὐχ ἥκιστα γεγονέναι διὰ τὸ νεοσυλλόγοις καὶ τελέως ἀνασκήτοις κεχρῆσθαι τοῖς στρατοπέδοις. αὐτοὶ δὲ Λεύκιον μὲν Ποστόμιον, ἑξαπέλεκυν ὄντα στρατηγόν, στρατόπεδον δόντες εἰς Γαλατίαν ἐξαπέστειλαν, βουλόμενοι ποιεῖν ἀντιπερίσπασμα τοῖς Κελτοῖς τοῖς μετ’ Ἀννίβου στρατευομένοις. πρόνοιαν δ’ ἐποιήσαντο καὶ τῆς ἀνακομιδῆς τοῦ παραχειμάζοντος ἐν τῷ Λιλυβαίῳ στόλου, διεπέμψαντο δὲ καὶ τοῖς ἐν Ἰβηρίᾳ στρατηγοῖς πάντα τὰ κατεπείγοντα πρὸς τὴν χρείαν. οὗτοι μὲν οὖν περὶ ταῦτα καὶ περὶ τὰς λοιπὰς ἐγίνοντο παρασκευὰς ἐπιμελῶς. οἱ δὲ περὶ τὸν Γνάιον κομισάμενοι τὰς παρὰ τῶν ὑπάτων ἐντολὰς πάντα τὰ κατὰ μέρος ἐχείριζον κατὰ τὴν ἐκείνων γνώμην· διὸ καὶ τὸ πλείω γράφειν ὑπὲρ αὐτῶν παρήσομεν. ὁλοσχερὲς μὲν γὰρ ἢ μνήμης ἄξιον ἁπλῶς οὐδὲν ἐπράχθη διὰ τὴν ἐντολὴν καὶ διὰ τὴν τοῦ καιροῦ περίστασιν, ἀκροβολισμοὶ δὲ μόνον καὶ συμπλοκαὶ κατὰ μέρος ἐγίνοντο πλείους, ἐν αἷς εὐδοκίμουν οἱ προεστῶτες τῶν Ῥωμαίων· καὶ γὰρ ἀνδρωδῶς καὶ νουνεχῶς ἐδόκουν ἕκαστα χειρίζειν.", "st": "3.106"}, {"sp": "N", "t": "τὸν μὲν οὖν χειμῶνα καὶ τὴν ἐαρινὴν ὥραν διέμειναν ἀντιστρατοπεδεύοντες ἀλλήλοις· ἤδη δὲ παραδιδόντος τοῦ καιροῦ τὴν ἐκ τῶν ἐπετείων καρπῶν χορηγίαν, ἐκίνει τὴν δύναμιν ἐκ τοῦ περὶ τὸ Γερούνιον χάρακος Ἀννίβας. κρίνων δὲ συμφέρειν τὸ κατὰ πάντα τρόπον ἀναγκάσαι μάχεσθαι τοὺς πολεμίους, καταλαμβάνει τὴν τῆς Κάννης προσαγορευομένης πόλεως ἄκραν. εἰς γὰρ ταύτην συνέβαινε τόν τε σῖτον καὶ τὰς λοιπὰς χορηγίας ἁθροίζεσθαι τοῖς Ῥωμαίοις ἐκ τῶν περὶ Κανύσιον τόπων· ἐκ δὲ ταύτης ἀεὶ πρὸς τὴν χρείαν ἐπὶ τὸ στρατόπεδον παρακομίζεσθαι. τὴν μὲν οὖν πόλιν ἔτι πρότερον συνέβαινε κατεσκάφθαι, τῆς παρασκευῆς δὲ καὶ τῆς ἄκρας τότε καταληφθείσης, οὐ μικρὰν συνέπεσε ταραχὴν γενέσθαι περὶ τὰς τῶν Ῥωμαίων δυνάμεις· οὐ γὰρ μόνον διὰ τὰς χορηγίας ἐδυσχρηστοῦντ’ ἐπὶ τῷ κατειλῆφθαι τὸν προειρημένον τόπον, ἀλλὰ καὶ διὰ τὸ κατὰ τὴν πέριξ εὐφυῶς κεῖσθαι χώραν. πέμποντες οὖν εἰς τὴν Ῥώμην συνεχῶς ἐπυνθάνοντο τί δεῖ ποιεῖν, ὡς ἐὰν ἐγγίσωσι τοῖς πολεμίοις, οὐ δυνησόμενοι φυγομαχεῖν, τῆς μὲν χώρας καταφθειρομένης, τῶν δὲ συμμάχων πάντων μετεώρων ὄντων ταῖς διανοίαις, οἱ δ’ ἐβουλεύσαντο μάχεσθαι καὶ συμβάλλειν τοῖς πολεμίοις. τοῖς μὲν οὖν περὶ τὸν Γνάιον ἐπισχεῖν ἔτι διεσάφησαν, αὐτοὶ δὲ τοὺς ὑπάτους ἐξαπέστελλον. συνέβαινε δὲ πάντας εἰς τὸν Αἰμίλιον ἀποβλέπειν καὶ πρὸς τοῦτον ἀπερείδεσθαι τὰς πλείστας ἐλπίδας διά τε τὴν ἐκ τοῦ λοιποῦ βίου καλοκἀγαθίαν καὶ διὰ τὸ μικροῖς πρότερον χρόνοις ἀνδρωδῶς ἅμα καὶ συμφερόντως δοκεῖν κεχειρικέναι τὸν πρὸς Ἰλλυριοὺς πόλεμον. προέθεντο δὲ στρατοπέδοις ὀκτὼ διακινδυνεύειν, ὃ πρότερον οὐδέποτ’ ἐγεγόνει παρὰ Ῥωμαίοις, ἑκάστου τῶν στρατοπέδων ἔχοντος ἄνδρας εἰς πεντακισχιλίους χωρὶς τῶν συμμάχων. Ῥωμαῖοι γάρ, καθά που καὶ πρότερον εἰρήκαμεν, ἀεί ποτε τέτταρα στρατόπεδα προχειρίζονται. τὸ δὲ στρατόπεδον πεζοὺς μὲν λαμβάνει περὶ τετρακισχιλίους, ἱππεῖς δὲ διακοσίους. ἐπὰν δέ τις ὁλοσχερεστέρα προφαίνηται χρεία, τοὺς μὲν πεζοὺς ἐν ἑκάστῳ στρατοπέδῳ ποιοῦσι περὶ πεντακισχιλίους, τοὺς δ’ ἱππεῖς τριακοσίους. τῶν δὲ συμμάχων τὸ μὲν τῶν πεζῶν πλῆθος πάρισον ποιοῦσι τοῖς Ῥωμαϊκοῖς στρατοπέδοις, τὸ δὲ τῶν ἱππέων ὡς ἐπίπαν τριπλάσιον. τούτων δὲ τοὺς ἡμίσεις τῶν συμμάχων καὶ τὰ δύο στρατόπεδα δόντες ἑκατέρῳ τῶν ὑπάτων ἐξαποστέλλουσιν ἐπὶ τὰς πράξεις. καὶ τοὺς μὲν πλείστους ἀγῶνας δι’ ἑνὸς ὑπάτου καὶ δύο στρατοπέδων καὶ τοῦ προειρημένου πλήθους τῶν συμμάχων κρίνουσι, σπανίως δὲ πᾶσι πρὸς ἕνα καιρὸν καὶ πρὸς ἕνα χρῶνται κίνδυνον. τότε γε μὴν οὕτως ἐκπλαγεῖς ἦσαν καὶ κατάφοβοι τὸ μέλλον ὡς οὐ μόνον τέτταρσιν, ἀλλ’ ὀκτὼ στρατοπέδοις Ῥωμαϊκοῖς ὁμοῦ προῄρηντο διακινδυνεύειν.", "st": "3.107"}, {"sp": "N", "t": "διὸ καὶ παρακαλέσαντες τοὺς περὶ τὸν Αἰμίλιον καὶ πρὸ ὀφθαλμῶν θέντες τὸ μέγεθος τῶν εἰς ἑκάτερον τὸ μέρος ἀποβησομένων ἐκ τῆς μάχης ἐξαπέστειλαν, ἐντειλάμενοι σὺν καιρῷ κρίνειν τὰ ὅλα γενναίως καὶ τῆς πατρίδος ἀξίως. οἳ καὶ παραγενόμενοι πρὸς τὰς δυνάμεις καὶ συναθροίσαντες τὰ πλήθη τήν τε τῆς συγκλήτου γνώμην διεσάφησαν τοῖς πολλοῖς καὶ παρεκάλουν τὰ πρέποντα τοῖς παρεστῶσι καιροῖς, ἐξ αὐτοπαθείας τοῦ Λευκίου διατιθεμένου τοὺς λόγους. ἦν δὲ τὰ πλεῖστα τῶν λεγομένων πρὸς τοῦτον τείνοντα τὸν νοῦν, τὸν ὑπὲρ τῶν νεωστὶ γεγονότων συμπτωμάτων· ὧδε γὰρ καὶ τῇδέ που συνέβαινε διατετράφθαι καὶ προσδεῖσθαι παραινέσεως τοὺς πολλούς. διόπερ ἐπειρᾶτο συνιστάνειν ὅτι τῶν μὲν ἐν ταῖς προγεγενημέναις μάχαις ἐλαττωμάτων οὐχ ἓν οὐδὲ δεύτερον, καὶ πλείω δ’ ἂν εὕροι τις αἴτια, δι’ ἃ τοιοῦτον αὐτῶν ἐξέβη τὸ τέλος, ἐπὶ δὲ τῶν νῦν καιρῶν οὐδεμία λείπεται πρόφασις, ἐὰν ἄνδρες ὦσι, τοῦ μὴ νικᾶν τοὺς ἐχθρούς. τότε μὲν γὰρ οὔτε τοὺς ἡγεμόνας ἀμφοτέρους οὐδέποτε συνηγωνίσθαι τοῖς στρατοπέδοις οὔτε ταῖς δυνάμεσι κεχρῆσθαι γεγυμνασμέναις, ἀλλὰ νεοσυλλόγοις καὶ ἀοράτοις παντὸς δεινοῦ· τό τε μέγιστον, ἐπὶ τοσοῦτον ἀγνοεῖσθαι παρ’ αὐτοῖς πρότερον τὰ κατὰ τοὺς ὑπεναντίους ὥστε σχεδὸν μηδ’ ἑωρακότας τοὺς ἀνταγωνιστὰς παρατάττεσθαι καὶ συγκαταβαίνειν εἰς τοὺς ὁλοσχερεῖς κινδύνους. ‘οἱ μὲν γὰρ περὶ τὸν Τρεβίαν ποταμὸν σφαλέντες, ἐκ Σικελίας τῇ προτεραίᾳ παραγενηθέντες, ἅμα τῷ φωτὶ τῇ κατὰ πόδας ἡμέρᾳ παρετάξαντο· τοῖς δὲ κατὰ Τυρρηνίαν ἀγωνισαμένοις οὐχ οἷον πρότερον, ἀλλ’ οὐδ’ ἐν αὐτῇ τῇ μάχῃ συνιδεῖν ἐξεγένετο τοὺς πολεμίους διὰ τὸ περὶ τὸν ἀέρα γενόμενον σύμπτωμα. νῦν γε μὴν πάντα τἀναντία τοῖς προειρημένοις ὑπάρχει.", "st": "3.108"}, {"sp": "N", "t": "πρῶτον γὰρ ἡμεῖς ἀμφότεροι πάρεσμεν, οὐ μόνον αὐτοὶ κοινωνήσοντες ὑμῖν τῶν κινδύνων, ἀλλὰ καὶ τοὺς ἐκ τοῦ πρότερον ἔτους ἄρχοντας ἑτοίμους παρεσκευάκαμεν πρὸς τὸ μένειν καὶ μετέχειν τῶν αὐτῶν ἀγώνων. ὑμεῖς γε μὴν οὐ μόνον ἑωράκατε τοὺς καθοπλισμούς, τὰς τάξεις, τὰ πλήθη τῶν πολεμίων, ἀλλὰ καὶ διαμαχόμενοι μόνον οὐ καθ’ ἑκάστην ἡμέραν δεύτερον ἐνιαυτὸν ἤδη διατελεῖτε. πάντων οὖν τῶν κατὰ μέρος ἐναντίως ἐχόντων ταῖς προγεγενημέναις μάχαις, εἰκὸς καὶ τὸ τέλος ἐναντίον ἐκβήσεσθαι τοῦ νῦν ἀγῶνος. καὶ γὰρ ἄτοπον, μᾶλλον δ’ ὡς εἰπεῖν ἀδύνατον, ἐν μὲν τοῖς κατὰ μέρος ἀκροβολισμοῖς ἴσους πρὸς ἴσους συμπίπτοντας τὸ πλεῖον ἐπικρατεῖν, ὁμοῦ δὲ πάντας παραταξαμένους πλείους ὄντας ἢ διπλασίους τῶν ὑπεναντίων ἐλαττωθῆναι. διόπερ, ὦ ἄνδρες, πάντων ὑμῖν παρεσκευασμένων πρὸς τὸ νικᾶν, ἑνὸς προσδεῖται τὰ πράγματα, τῆς ὑμετέρας βουλήσεως καὶ προθυμίας, ὑπὲρ ἧς οὐδὲ παρακαλεῖσθαι πλείω πρέπειν ὑμῖν ὑπολαμβάνω. τοῖς μέν γε μισθοῦ παρά τισι στρατευομένοις ἢ τοῖς κατὰ συμμαχίαν ὑπὲρ τῶν πέλας μέλλουσι κινδυνεύειν, οἷς κατ’ αὐτὸν τὸν ἀγῶνα καιρός ἐστι δεινότατος, τὰ δ’ ἐκ τῶν ἀποβαινόντων βραχεῖαν ἔχει διαφοράν, ἀναγκαῖος ὁ τῆς παρακλήσεως γίνεται τρόπος· οἷς δέ, καθάπερ ὑμῖν νῦν, οὐχ ὑπὲρ ἑτέρων ἀλλ’ ὑπὲρ σφῶν αὐτῶν καὶ πατρίδος καὶ γυναικῶν καὶ τέκνων ὁ κίνδυνος συνέστηκεν, καὶ πολλαπλασίαν τὰ μετὰ ταῦτα συμβαίνοντα τὴν διαφορὰν ἔχει τῶν ἐνεστώτων ἀεὶ κινδύνων, ὑπομνήσεως μόνον, παρακλήσεως δ’ οὐ προσδεῖ. τίς γὰρ οὐκ ἂν βούλοιτο μάλιστα μὲν νικᾶν ἀγωνιζόμενος, εἰ δὲ μὴ τοῦτ’ εἴη δυνατόν, τεθνάναι πρόσθεν μαχόμενος ἢ ζῶν ἐπιδεῖν τὴν τῶν προειρημένων ὕβριν καὶ καταφθοράν; διόπερ, ὦ ἄνδρες, χωρὶς τῶν ὑπ’ ἐμοῦ λεγομένων, αὐτοὶ λαμβάνοντες πρὸ ὀφθαλμῶν τὴν ἐκ τοῦ λείπεσθαι καὶ τοῦ νικᾶν διαφορὰν καὶ τὰ συνεξακολουθοῦντα τούτοις, οὕτως ἑαυτοὺς παραστήσεσθε πρὸς τὴν μάχην ὡς τῆς πατρίδος οὐ κινδυνευούσης νῦν αὐτοῖς τοῖς στρατοπέδοις, ἀλλὰ τοῖς ὅλοις. τί γὰρ ἔτι προσθεῖσα τοῖς ὑποκειμένοις, ἐὰν ἄλλως πως τὰ παρόντα κριθῇ, περιγενήσεται τῶν ἐχθρῶν, οὐκ ἔχει. πᾶσαν γὰρ τὴν αὑτῆς προθυμίαν καὶ δύναμιν εἰς ὑμᾶς ἀπήρεισται, καὶ πάσας τὰς ἐλπίδας ἔχει τῆς σωτηρίας ἐν ὑμῖν. ὧν ὑμεῖς αὐτὴν μὴ διαψεύσητε νῦν, ἀλλ’ ἀπόδοτε μὲν τῇ πατρίδι τὰς ἁρμοζούσας χάριτας, φανερὸν δὲ πᾶσιν ἀνθρώποις ποιήσατε διότι καὶ τὰ πρότερον ἐλαττώματα γέγονεν οὐ διὰ τὸ Ῥωμαίους χείρους ἄνδρας εἶναι Καρχηδονίων, ἀλλὰ δι’ ἀπειρίαν τῶν τότε μαχομένων καὶ διὰ τὰς ἐκ τῶν καιρῶν περιστάσεις. ’ τότε μὲν οὖν ταῦτα καὶ τοιαῦτα παρακαλέσας ὁ Λεύκιος διαφῆκε τοὺς πολλούς.", "st": "3.109"}, {"sp": "N", "t": "τῇ δ’ ἐπαύριον ἀναζεύξαντες ἦγον τὴν δύναμιν οὗ τοὺς πολεμίους ἤκουον στρατοπεδεύειν. δευτεραῖοι δ’ ἐπιβαλόντες παρενέβαλον, περὶ πεντήκοντα σταδίους ἀποσχόντες τῶν πολεμίων. ὁ μὲν οὖν Λεύκιος συνθεασάμενος ἐπιπέδους καὶ ψιλοὺς ὄντας τοὺς πέριξ τόπους οὐκ ἔφη δεῖν συμβάλλειν ἱπποκρατούντων τῶν πολεμίων, ἀλλ’ ἐπισπᾶσθαι καὶ προάγειν μᾶλλον εἰς τόπους τοιούτους ἐν οἷς τὸ πλέον ἔσται διὰ τῶν πεζικῶν στρατοπέδων ἡ μάχη. τοῦ δὲ Γαΐου διὰ τὴν ἀπειρίαν ὑπὲρ τῆς ἐναντίας ὑπάρχοντος γνώμης, ἦν ἀμφισβήτησις καὶ δυσχρηστία περὶ τοὺς ἡγεμόνας, ὃ πάντων ἐστὶ σφαλερώτατον. τῆς δ’ ἡγεμονίας τῷ Γαΐῳ καθηκούσης εἰς τὴν ἐπιοῦσαν ἡμέραν διὰ τὸ παρὰ μίαν ἐκ τῶν ἐθισμῶν μεταλαμβάνειν τὴν ἀρχὴν τοὺς ὑπάτους, ἀναστρατοπεδεύσας προῆγε, βουλόμενος ἐγγίσαι τοῖς πολεμίοις, πολλὰ διαμαρτυρομένου καὶ κωλύοντος τοῦ Λευκίου. ὁ δ’ Ἀννίβας ἀναλαβὼν τοὺς εὐζώνους καὶ τοὺς ἱππεῖς ἀπήντα καὶ προσπεσὼν ἔτι κατὰ πορείαν οὖσι παραδόξως συνεπλέκετο καὶ πολὺν ἐν αὐτοῖς ἐποιεῖτο θόρυβον. οἱ δὲ Ῥωμαῖοι τὴν μὲν πρώτην ἐπιφορὰν ἐδέξαντο, προθέμενοί τινας τῶν ἐν τοῖς βαρέσι καθοπλισμοῖς· μετὰ δὲ ταῦτα τοὺς ἀκοντιστὰς καὶ τοὺς ἱππεῖς ἐπαφέντες ἐπροτέρουν κατὰ τὴν ὅλην συμπλοκὴν διὰ τὸ τοῖς μὲν Καρχηδονίοις μηδὲν ἐφεδρεύειν ἀξιόλογον, τοῖς δὲ Ῥωμαίοις ἀναμεμιγμένας τοῖς εὐζώνοις ὁμόσε κινδυνεύειν τινὰς σπείρας. τότε μὲν οὖν ἐπιγενομένης νυκτὸς ἐχωρίσθησαν ἀπ’ ἀλλήλων, οὐ κατὰ τὴν ἐλπίδα τοῖς Καρχηδονίοις ἐκβάσης τῆς ἐπιθέσεως· εἰς δὲ τὴν ἐπαύριον ὁ Λεύκιος οὔτε μάχεσθαι κρίνων οὔτε μὴν ἀπάγειν ἀσφαλῶς τὴν στρατιὰν ἔτι δυνάμενος τοῖς μὲν δυσὶ μέρεσι κατεστρατοπέδευσε παρὰ τὸν Αὔφιδον καλούμενον ποταμόν, ὃς μόνος διαρρεῖ τὸν Ἀπεννῖνον — τοῦτο δ’ ἔστιν ὄρος συνεχές, ὃ διείργει πάσας τὰς κατὰ τὴν Ἰταλίαν ῥύσεις, τὰς μὲν εἰς τὸ Τυρρηνικὸν πέλαγος, τὰς δ’ εἰς τὸν Ἀδρίαν· δι’ οὗ ῥέοντα συμβαίνει τὸν Αὔφιδον τὰς μὲν πηγὰς ἔχειν ἐν τοῖς πρὸς τὸ Τυρρηνικὸν κλίμασι τῆς Ἰταλίας, ποιεῖσθαι δὲ τὴν ἐκβολὴν εἰς τὸν Ἀδρίαν — τῷ δὲ τρίτῳ πέραν, ἀπὸ διαβάσεως πρὸς τὰς ἀνατολάς, ἐβάλετο χάρακα, τῆς μὲν ἰδίας παρεμβολῆς περὶ δέκα σταδίους ἀποσχών, τῆς δὲ τῶν ὑπεναντίων μικρῷ πλεῖον, βουλόμενος διὰ τούτων προκαθῆσθαι μὲν τῶν ἐκ τῆς πέραν παρεμβολῆς προνομευόντων, ἐπικεῖσθαι δὲ τοῖς παρὰ τῶν Καρχηδονίων.", "st": "3.110"}, {"sp": "N", "t": "Ἀννίβας δὲ κατὰ τὸν αὐτὸν καιρὸν θεωρῶν ὅτι καλεῖ τὰ πράγματα μάχεσθαι καὶ συμβάλλειν τοῖς πολεμίοις, εὐλαβούμενος δὲ μὴ διατέτραπται τὸ πλῆθος ἐκ τοῦ προγεγονότος ἐλαττώματος, κρίνας προσδεῖσθαι παρακλήσεως τὸν καιρὸν συνῆγε τοὺς πολλούς. ἁθροισθέντων δέ, περιβλέψαι κελεύσας πάντας εἰς τοὺς πέριξ τόπους, ἤρετο τί μεῖζον εὔξασθαι τοῖς θεοῖς κατὰ τοὺς παρόντας ἐδύναντο καιρούς, δοθείσης αὐτοῖς ἐξουσίας, τοῦ παρὰ πολὺ τῶν πολεμίων ἱπποκρατοῦντας ἐν τοιούτοις τόποις διακριθῆναι περὶ τῶν ὅλων. πάντων δὲ τὸ ῥηθὲν ἐπισημηναμένων διὰ τὴν ἐνάργειαν ‘τούτου τοιγαροῦν’ ἔφη ‘πρῶτον μὲν τοῖς θεοῖς ἔχετε χάριν· ἐκεῖνοι γὰρ ἡμῖν συγκατασκευάζοντες τὴν νίκην εἰς τοιούτους τόπους ἤχασι τοὺς ἐχθρούς· δεύτερον δ’ ἡμῖν, ὅτι καὶ μάχεσθαι τοὺς πολεμίους συνηναγκάσαμεν· οὐ γὰρ ἔτι δύνανται τοῦτο διαφυγεῖν· καὶ μάχεσθαι προφανῶς ἐν τοῖς ἡμετέροις προτερήμασι. τὸ δὲ παρακαλεῖν ὑμᾶς νῦν διὰ πλειόνων εὐθαρσεῖς καὶ προθύμους εἶναι πρὸς τὸν κίνδυνον οὐδαμῶς μοι δοκεῖ καθήκειν. ὅτε μὲν γὰρ ἀπείρως διέκεισθε τῆς πρὸς Ῥωμαίους μάχης, ἔδει τοῦτο ποιεῖν, καὶ μεθ’ ὑποδειγμάτων ἐγὼ πρὸς ὑμᾶς πολλοὺς διεθέμην λόγους· ὅτε δὲ κατὰ τὸ συνεχὲς τρισὶ μάχαις τηλικαύταις ἐξ ὁμολογουμένου νενικήκατε Ῥωμαίους, ποῖος ἂν ἔτι λόγος ὑμῖν ἰσχυρότερον παραστήσαι θάρσος αὐτῶν τῶν ἔργων; διὰ μὲν οὖν τῶν πρὸ τοῦ κινδύνων κεκρατήκατε τῆς χώρας καὶ τῶν ἐκ ταύτης ἀγαθῶν κατὰ τὰς ἡμετέρας ἐπαγγελίας, ἀψευστούντων ἡμῶν ἐν πᾶσι τοῖς πρὸς ὑμᾶς εἰρημένοις· ὁ δὲ νῦν ἀγὼν ἐνέστηκεν περὶ τῶν πόλεων καὶ τῶν ἐν αὐταῖς ἀγαθῶν. οὗ κρατήσαντες κύριοι μὲν ἔσεσθε παραχρῆμα πάσης Ἰταλίας, ἀπαλλαγέντες δὲ τῶν νῦν πόνων, γενόμενοι συμπάσης ἐγκρατεῖς τῆς Ῥωμαίων εὐδαιμονίας, ἡγεμόνες ἅμα καὶ δεσπόται πάντων γενήσεσθε διὰ ταύτης τῆς μάχης. διόπερ οὐκέτι λόγων ἀλλ’ ἔργων ἐστὶν ἡ χρεία· θεῶν γὰρ βουλομένων ὅσον οὔπω βεβαιώσειν ὑμῖν πέπεισμαι τὰς ἐπαγγελίας. ’ ταῦτα δὲ καὶ τούτοις παραπλήσια διαλεχθείς, προθύμως αὐτὸν ἐπισημαινομένου τοῦ πλήθους, ἐπαινέσας καὶ δεξάμενος αὐτῶν τὴν ὁρμὴν ἀφῆκε καὶ παραχρῆμα κατεστρατοπέδευσε, ποιούμενος τὸν χάρακα παρὰ τὴν αὐτὴν πλευρὰν τοῦ ποταμοῦ τῇ μείζονι στρατοπεδείᾳ τῶν ὑπεναντίων.", "st": "3.111"}, {"sp": "N", "t": "τῇ δ’ ἐχομένῃ περὶ παρασκευὴν καὶ θεραπείαν παρήγγειλε γίνεσθαι πᾶσι. τῇ δ’ ἑξῆς παρὰ τὸν ποταμὸν ἐξέταττε τὰ στρατόπεδα καὶ δῆλος ἦν μάχεσθαι σπεύδων τοῖς ὑπεναντίοις. ὁ δὲ Λεύκιος δυσαρεστούμενος μὲν τοῖς τόποις, ὁρῶν δ’ ὅτι ταχέως ἀναγκασθήσονται μεταστρατοπεδεύειν οἱ Καρχηδόνιοι διὰ τὸν πορισμὸν τῶν ἐπιτηδείων, εἶχε τὴν ἡσυχίαν, ἀσφαλισάμενος ταῖς ἐφεδρείαις τὰς παρεμβολάς. Ἀννίβας δὲ χρόνον ἱκανὸν μείνας, οὐδενὸς ἀντεξιόντος, τὴν μὲν λοιπὴν δύναμιν αὖθις εἰς χάρακα κατέστησεν, τοὺς δὲ Νομάδας ἐπαφῆκε τοῖς ὑδρευομένοις ἀπὸ τῆς ἐλάττονος παρεμβολῆς. τῶν δὲ Νομάδων ἕως πρὸς αὐτὸν τὸν χάρακα προσπιπτόντων καὶ διακωλυόντων τὴν ὑδρείαν, ὅ τε Γάιος ἔτι μᾶλλον ἐπὶ τούτοις παρωξύνετο, τά τε πλήθη πρὸς τὸν κίνδυνον ὁρμὴν εἶχεν καὶ δυσχερῶς ἔφερε τὰς ὑπερθέσεις. βαρύτατος γὰρ δὴ πᾶσιν ἀνθρώποις ὁ τοῦ μέλλειν γίνεται χρόνος· ὅταν δ’ ἅπαξ κριθῇ, ὅ,τι ἂν ᾖ πάσχειν πάντων τῶν δοκούντων εἶναι δεινῶν ὑπομενετέον. εἰς δὲ τὴν Ῥώμην προσπεπτωκότος ὅτι παραστρατοπεδεύουσιν ἀλλήλοις καὶ συμπλοκαὶ γίνονται τῶν προκινδυνευόντων ἀν’ ἑκάστην ἡμέραν, ὀρθὴ καὶ περίφοβος ἦν ἡ πόλις, δεδιότων μὲν τῶν πολλῶν τὸ μέλλον διὰ τὸ πολλάκις ἤδη προηττῆσθαι, προορωμένων δὲ καὶ προλαμβανόντων τὰ συμβησόμενα ταῖς ἐννοίαις, ἐὰν σφάλλωνται τοῖς ὅλοις. πάντα δ’ ἦν τὰ παρ’ αὐτοῖς λόγια πᾶσι τότε διὰ στόματος, σημείων δὲ καὶ τεράτων πᾶν μὲν ἱερόν, πᾶσα δ’ ἦν οἰκία πλήρης, ἐξ ὧν εὐχαὶ καὶ θυσίαι καὶ θεῶν ἱκετηρίαι καὶ δεήσεις ἐπεῖχον τὴν πόλιν. δεινοὶ γὰρ ἐν ταῖς περιστάσεσι Ῥωμαῖοι καὶ θεοὺς ἐξιλάσασθαι καὶ ἀνθρώπους καὶ μηδὲν ἀπρεπὲς μηδ’ ἀγεννὲς ἐν τοῖς τοιούτοις καιροῖς ἡγεῖσθαι τῶν περὶ ταῦτα συντελουμένων.", "st": "3.112"}, {"sp": "N", "t": "ὁ δὲ Γάιος ἅμα τῷ παραλαβεῖν τῇ κατὰ πόδας ἡμέρᾳ τὴν ἀρχήν, ἄρτι τῆς κατὰ τὸν ἥλιον ἀνατολῆς ἐπιφαινομένης, ἐκίνει τὴν δύναμιν ἐξ ἑκατέρας ἅμα τῆς παρεμβολῆς καὶ τοὺς μὲν ἐκ τοῦ μείζονος χάρακος διαβιβάζων τὸν ποταμὸν εὐθέως παρενέβαλε, τοὺς δ’ ἐκ θατέρου συνάπτων τούτοις ἐπὶ τὴν αὐτὴν εὐθεῖαν ἐξέταττε, λαμβάνων πᾶσι τὴν ἐπιφάνειαν τὴν πρὸς μεσημβρίαν. τοὺς μὲν οὖν τῶν Ῥωμαίων ἱππεῖς παρ’ αὐτὸν τὸν ποταμὸν ἐπὶ τοῦ δεξιοῦ κέρατος κατέστησε, τοὺς δὲ πεζοὺς συνεχεῖς τούτοις ἐπὶ τῆς αὐτῆς εὐθείας ἐξέτεινε, πυκνοτέρας ἢ πρόσθεν τὰς σημείας καθιστάνων, καὶ ποιῶν πολλαπλάσιον τὸ βάθος ἐν ταῖς σπείραις τοῦ μετώπου· τοὺς δὲ τῶν συμμάχων ἱππεῖς εἰς τὸ λαιὸν κέρας παρενέβαλε· πάσης δὲ τῆς δυνάμεως προέστησε τοὺς εὐζώνους ἐν ἀποστάσει. ἦσαν δὲ σὺν τοῖς συμμάχοις πεζῶν μὲν εἰς ὀκτὼ μυριάδας, ἱππεῖς δὲ μικρῷ πλείους τῶν ἑξακισχιλίων. Ἀννίβας δὲ κατὰ τὸν αὐτὸν καιρὸν τοὺς μὲν Βαλιαρεῖς καὶ λογχοφόρους διαβιβάσας τὸν ποταμὸν προεβάλετο τῆς δυνάμεως, τοὺς δὲ λοιποὺς ἐξαγαγὼν ἐκ τοῦ χάρακος καὶ περαιώσας κατὰ διττοὺς τόπους τὸ ῥεῖθρον ἀντετάττετο τοῖς πολεμίοις. ἐτίθει δ’ ἐπ’ αὐτὸν μὲν τὸν ποταμόν, ἐπὶ τῶν εὐωνύμων, τοὺς Ἴβηρας καὶ Κελτοὺς ἱππεῖς ἀντίους τοῖς τῶν Ῥωμαίων ἱππεῦσι, συνεχεῖς δὲ τούτοις πεζοὺς τοὺς ἡμίσεις τῶν ἐν τοῖς βαρέσι καθοπλισμοῖς Λιβύων, ἑξῆς δὲ τοῖς εἰρημένοις Ἴβηρας καὶ Κελτούς. παρὰ δὲ τούτοις τὸ λοιπὸν μέρος ἔθηκε τῶν Λιβύων, ἐπὶ δὲ τοῦ δεξιοῦ κέρως ἐπέταξε τοὺς Νομαδικοὺς ἱππεῖς. ἐπεὶ δὲ πάντ’ ἐπὶ μίαν εὐθεῖαν ἐξέτεινε, μετὰ ταῦτα λαβὼν τὰ μέσα τῶν Ἰβήρων καὶ Κελτῶν τάγματα προῆγε καὶ τἄλλα τούτοις ἐκ τοῦ κατὰ λόγον παρίστανε ζυγοῦντα, μηνοειδὲς ποιῶν τὸ κύρτωμα καὶ λεπτύνων τὸ τούτων αὐτῶν σχῆμα, βουλόμενος ἐφεδρείας μὲν τάξιν ἐν τῇ μάχῃ τοὺς Λίβυας αὐτῶν ἔχειν, προκινδυνεῦσαι δὲ τοῖς Ἴβηρσι καὶ Κελτοῖς.", "st": "3.113"}, {"sp": "N", "t": "ἦν δ’ ὁ καθοπλισμὸς τῶν μὲν Λιβύων Ῥωμαϊκός, οὓς πάντας Ἀννίβας τοῖς ἐκ τῆς προγεγενημένης μάχης σκύλοις ἐκλέξας κατακεκοσμήκει· τῶν δ’ Ἰβήρων καὶ Κελτῶν ὁ μὲν θυρεὸς ἦν παραπλήσιος, τὰ δὲ ξίφη τὴν ἐναντίαν εἶχε διάθεσιν· τῆς μὲν γὰρ οὐκ ἔλαττον τὸ κέντημα τῆς καταφορᾶς ἴσχυε πρὸς τὸ βλάπτειν, ἡ δὲ Γαλατικὴ μάχαιρα μίαν εἶχε χρείαν τὴν ἐκ καταφορᾶς, καὶ ταύτην ἐξ ἀποστάσεως. ἐναλλὰξ δὲ ταῖς σπείραις αὐτῶν παρατεταγμένων, καὶ τῶν μὲν Κελτῶν γυμνῶν, τῶν δ’ Ἰβήρων λινοῖς περιπορφύροις χιτωνίσκοις κεκοσμημένων κατὰ τὰ πάτρια, ξενίζουσαν ἅμα καὶ καταπληκτικὴν συνέβαινε γίνεσθαι τὴν πρόσοψιν. ἦν δὲ τὸ μὲν τῶν ἱππικῶν πλῆθος τὸ σύμπαν τοῖς Καρχηδονίοις εἰς μυρίους, τὸ δὲ τῶν πεζῶν οὐ πολὺ πλείους τετρακισμυρίων σὺν τοῖς Κελτοῖς. εἶχε δὲ τὸ μὲν δεξιὸν τῶν Ῥωμαίων Αἰμίλιος, τὸ δ’ εὐώνυμον Γάιος, τὰ δὲ μέσα Μάρκος καὶ Γνάιος οἱ τῷ πρότερον ἔτει στρατηγοῦντες. τῶν δὲ Καρχηδονίων τὸ μὲν εὐώνυμον Ἀσδρούβας εἶχε, τὸ δὲ δεξιὸν Ἄννων· ἐπὶ δὲ τοῖς μέσοις αὐτὸς ἦν Ἀννίβας, ἔχων μεθ’ ἑαυτοῦ Μάγωνα τὸν ἀδελφόν. βλεπούσης δὲ τῆς μὲν τῶν Ῥωμαίων τάξεως πρὸς μεσημβρίαν, ὡς ἐπάνω προεῖπα, τῆς δὲ τῶν Καρχηδονίων πρὸς τὰς ἄρκτους, ἑκατέροις ἀβλαβῆ συνέβαινε γίνεσθαι τὴν κατὰ τὸν ἥλιον ἀνατολήν.", "st": "3.114"}, {"sp": "N", "t": "γενομένης δὲ τῆς συμπλοκῆς τῆς πρώτης ἐκ τῶν προτεταγμένων, τὰς μὲν ἀρχὰς αὐτῶν τῶν εὐζώνων ἔπισος ἦν ὁ κίνδυνος, ἅμα δὲ τῷ τοὺς Ἴβηρας καὶ Κελτοὺς ἱππεῖς ἀπὸ τῶν εὐωνύμων πελάσαι τοῖς Ῥωμαίοις ἐποίουν οὗτοι μάχην ἀληθινὴν καὶ βαρβαρικήν· οὐ γὰρ ἦν κατὰ νόμους ἐξ ἀναστροφῆς καὶ μεταβολῆς ὁ κίνδυνος, ἀλλ’ εἰσάπαξ συμπεσόντες ἐμάχοντο συμπλεκόμενοι κατ’ ἄνδρα, παρακαταβαίνοντες ἀπὸ τῶν ἵππων. ἐπειδὴ δ’ ἐκράτησαν οἱ παρὰ τῶν Καρχηδονίων καὶ τοὺς μὲν πλείστους ἀπέκτειναν ἐν τῇ συμπλοκῇ, πάντων ἐκθύμως καὶ γενναίως διαγωνιζομένων τῶν Ῥωμαίων, τοὺς δὲ λοιποὺς ἤλαυνον παρὰ τὸν ποταμὸν φονεύοντες καὶ προσφέροντες τὰς χεῖρας ἀπαραιτήτως, τότε δὴ τὰ πεζικὰ στρατόπεδα διαδεξάμενα τοὺς εὐζώνους συνέπεσεν ἀλλήλοις. ἐπὶ βραχὺ μὲν οὖν τῶν Ἰβήρων καὶ τῶν Κελτῶν ἔμενον αἱ τάξεις καὶ διεμάχοντο τοῖς Ῥωμαίοις γενναίως· μετὰ δὲ ταῦτα τῷ βάρει θλιβόμενοι κλίνοντες ὑπεχώρουν εἰς τοὐπίσω, λύσαντες τὸν μηνίσκον. αἱ δὲ τῶν Ῥωμαίων σπεῖραι κατὰ τὴν ἐκθυμίαν ἑπόμεναι τούτοις διέκοψαν ῥᾳδίως τὴν τῶν ὑπεναντίων τάξιν, ἅτε δὴ τῶν μὲν Κελτῶν ἐπὶ λεπτὸν ἐκτεταγμένων, αὐτοὶ δὲ πεπυκνωκότες ἀπὸ τῶν κεράτων ἐπὶ τὰ μέσα καὶ τὸν κινδυνεύοντα τόπον· οὐ γὰρ ἅμα συνέβαινε τὰ κέρατα καὶ τὰ μέσα συμπίπτειν, ἀλλὰ πρῶτα τὰ μέσα διὰ τὸ τοὺς Κελτοὺς ἐν μηνοειδεῖ σχήματι τεταγμένους πολὺ προπεπτωκέναι τῶν κεράτων, ἅτε τοῦ μηνίσκου τὸ κύρτωμα πρὸς τοὺς πολεμίους ἔχοντος. πλὴν ἑπόμενοί γε τούτοις οἱ Ῥωμαῖοι καὶ συντρέχοντες ἐπὶ τὰ μέσα καὶ τὸν εἴκοντα τόπον τῶν πολεμίων οὕτως ἐπὶ πολὺ προέπεσον ὥστ’ ἐξ ἑκατέρου τοῦ μέρους κατὰ τὰς ἐκ τῶν πλαγίων ἐπιφανείας τοὺς Λίβυας αὐτῶν γενέσθαι τοὺς ἐν τοῖς βαρέσι καθοπλισμοῖς· ὧν οἱ μὲν ἀπὸ τοῦ δεξιοῦ κέρατος κλίναντες ἐπ’ ἀσπίδα καὶ τὴν ἐμβολὴν ἐκ δόρατος ποιούμενοι παρίσταντο παρὰ πλευρὰν τοῖς πολεμίοις, οἱ δ’ ἀπὸ τῶν εὐωνύμων ἐπὶ δόρυ ποιούμενοι τὴν κλίσιν ἐξ ἀσπίδος ἐπιπαρενέβαλλον, αὐτοῦ τοῦ πράγματος ὃ δέον ἦν ποιεῖν ὑποδεικνύντος. ἐξ οὗ συνέβη κατὰ τὴν Ἀννίβου πρόνοιαν μέσους ἀποληφθῆναι τοὺς Ῥωμαίους ὑπὸ τῶν Λιβύων κατὰ τὴν ἐπὶ τοὺς Κελτοὺς παράπτωσιν. οὗτοι μὲν οὖν οὐκέτι φαλαγγηδόν, ἀλλὰ κατ’ ἄνδρα καὶ κατὰ σπείρας στρεφόμενοι πρὸς τοὺς ἐκ τῶν πλαγίων προσπεπτωκότας ἐποιοῦντο τὴν μάχην·", "st": "3.115"}, {"sp": "N", "t": "Λεύκιος δὲ καίπερ ὢν ἐξ ἀρχῆς ἐπὶ τοῦ δεξιοῦ κέρατος καὶ μετασχὼν ἐπί τι τοῦ τῶν ἱππέων ἀγῶνος ὅμως ἔτι τότε διεσῴζετο. βουλόμενος δὲ τοῖς κατὰ τὴν παράκλησιν λόγοις ἀκολούθως ἐπ’ αὐτῶν γίνεσθαι τῶν ἔργων καὶ θεωρῶν τὸ συνέχον τῆς κατὰ τὸν ἀγῶνα κρίσεως ἐν τοῖς πεζικοῖς στρατοπέδοις κείμενον, παριππεύων ἐπὶ τὰ μέσα τῆς ὅλης παρατάξεως ἅμα μὲν αὐτὸς συνεπλέκετο καὶ προσέφερε τὰς χεῖρας τοῖς ὑπεναντίοις, ἅμα δὲ παρεκάλει καὶ παρώξυνε τοὺς παρ’ αὑτοῦ στρατιώτας. τὸ δὲ παραπλήσιον Ἀννίβας ἐποίει· καὶ γὰρ οὗτος ἐξ ἀρχῆς ἐπὶ τούτοις τοῖς μέρεσιν ἐπέστη τῆς δυνάμεως. οἱ δὲ Νομάδες ἀπὸ τοῦ δεξιοῦ κέρατος προσπίπτοντες τοῖς ὑπεναντίοις ἱππεῦσι τοῖς ἐπὶ τῶν εὐωνύμων τεταγμένοις μέγα μὲν οὔτ’ ἐποίουν οὐδὲν οὔτ’ ἔπασχον διὰ τὴν ἰδιότητα τῆς μάχης, ἀπράκτους γε μὴν τοὺς πολεμίους παρεσκεύαζον, περισπῶντες καὶ πανταχόθεν προσπίπτοντες. ἐπεὶ δ’ οἱ περὶ τὸν Ἀσδρούβαν ἀποκτείναντες τοὺς περὶ τὸν ποταμὸν ἱππεῖς πλὴν παντελῶς ὀλίγων παρεβοήθησαν ἀπὸ τῶν εὐωνύμων τοῖς Νομάσιν, τότε προϊδόμενοι τὴν ἔφοδον αὐτῶν οἱ σύμμαχοι τῶν Ῥωμαίων ἱππεῖς ἐκκλίναντες ἀπεχώρουν. ἐν ᾧ καιρῷ πραγματικὸν δοκεῖ ποιῆσαι καὶ φρόνιμον ἔργον Ἀσδρούβας· θεωρῶν γὰρ τοὺς Νομάδας τῷ τε πλήθει πολλοὺς ὄντας καὶ πρακτικωτάτους καὶ φοβερωτάτους τοῖς ἅπαξ ἐγκλίνασιν, τοὺς μὲν φεύγοντας παρέδωκε τοῖς Νομάσιν, πρὸς δὲ τὴν τῶν πεζῶν μάχην ἡγεῖτο, σπεύδων παραβοηθῆσαι τοῖς Λίβυσι. προσπεσὼν δὲ τοῖς Ῥωμαϊκοῖς στρατοπέδοις κατὰ νώτου καὶ ποιούμενος ἐκ διαδοχῆς ταῖς ἴλαις ἐμβολὰς ἅμα κατὰ πολλοὺς τόπους ἐπέρρωσε μὲν τοὺς Λίβυας, ἐταπείνωσε δὲ καὶ κατέπληξε ταῖς ψυχαῖς τοὺς Ῥωμαίους. ἐν ᾧ καιρῷ καὶ Λεύκιος Αἰμίλιος περιπεσὼν βιαίοις πληγαῖς ἐν χειρῶν νόμῳ μετήλλαξε τὸν βίον, ἀνὴρ πάντα τὰ δίκαια τῇ πατρίδι κατὰ τὸν λοιπὸν βίον καὶ κατὰ τὸν ἔσχατον καιρόν, εἰ καί τις ἕτερος, ποιήσας. οἱ δὲ Ῥωμαῖοι μέχρι μὲν ἐμάχοντο κατὰ τὰς ἐπιφανείας στρεφόμενοι πρὸς τοὺς κεκυκλωκότας, ἀντεῖχον· ἀεὶ δὲ τῶν πέριξ ἀπολλυμένων, καὶ κατὰ βραχὺ συγκλειόμενοι, τέλος αὐτοῦ πάντες, ἐν οἷς καὶ Μάρκος καὶ Γνάιος, ἔπεσον, οἱ τὸ πρότερον ἔτος ὕπατοι γεγονότες, ἄνδρες ἀγαθοὶ καὶ τῆς Ῥώμης ἄξιοι γενόμενοι κατὰ τὸν κίνδυνον. κατὰ δὲ τὸν τούτων φόνον καὶ τὴν συμπλοκὴν οἱ Νομάδες ἑπόμενοι τοῖς φεύγουσι τῶν ἱππέων τοὺς μὲν πλείστους ἀπέκτειναν, τοὺς δὲ κατεκρήμνισαν ἀπὸ τῶν ἵππων. ὀλίγοι δέ τινες εἰς Οὐενουσίαν διέφυγον, ἐν οἷς ἦν καὶ Γάιος Τερέντιος ὁ τῶν Ῥωμαίων στρατηγός, ἀνὴρ αἰσχρὰν μὲν τὴν ψυχὴν ἀλυσιτελῆ δὲ τὴν ἀρχὴν τὴν αὑτοῦ τῇ πατρίδι πεποιημένος.", "st": "3.116"}, {"sp": "N", "t": "ἡ μὲν οὖν περὶ Κάνναν γενομένη μάχη Ῥωμαίων καὶ Καρχηδονίων ἐπετελέσθη τὸν τρόπον τοῦτον, μάχη γενναιοτάτους ἄνδρας ἔχουσα καὶ τοὺς νικήσαντας καὶ τοὺς ἡττηθέντας. δῆλον δὲ τοῦτ’ ἐγένετ’ ἐξ αὐτῶν τῶν πραγμάτων. τῶν μὲν γὰρ ἑξακισχιλίων ἱππέων ἑβδομήκοντα μὲν εἰς Οὐενουσίαν μετὰ Γαΐου διέφυγον, περὶ τριακοσίους δὲ τῶν συμμάχων σποράδες εἰς τὰς πόλεις ἐσώθησαν· ἐκ δὲ τῶν πεζῶν μαχόμενοι μὲν ἑάλωσαν εἰς μυρίους — οἱ δ’ ἐκτὸς ὄντες τῆς μάχης — ἐξ αὐτοῦ δὲ τοῦ κινδύνου τρισχίλιοι μόνον ἴσως εἰς τὰς παρακειμένας πόλεις διέφυγον. οἱ δὲ λοιποὶ πάντες, ὄντες εἰς ἑπτὰ μυριάδας, ἀπέθανον εὐγενῶς, τὴν μεγίστην χρείαν παρεσχημένου τοῖς Καρχηδονίοις εἰς τὸ νικᾶν καὶ τότε καὶ πρὸ τοῦ τοῦ τῶν ἱππέων ὄχλου. καὶ δῆλον ἐγένετο τοῖς ἐπιγενομένοις ὅτι κρεῖττόν ἐστι πρὸς τοὺς τῶν πολέμων καιροὺς ἡμίσεις ἔχειν πεζούς, ἱπποκρατεῖν δὲ τοῖς ὅλοις, μᾶλλον ἢ πάντα πάρισα τοῖς πολεμίοις ἔχοντα διακινδυνεύειν. τῶν δὲ μετ’ Ἀννίβου Κελτοὶ μὲν ἔπεσον εἰς τετρακισχιλίους, Ἴβηρες δὲ καὶ Λίβυες εἰς χιλίους καὶ πεντακοσίους, ἱππεῖς δὲ περὶ διακοσίους. οἱ δὲ ζωγρηθέντες τῶν Ῥωμαίων ἐκτὸς ἐγένοντο τοῦ κινδύνου, καὶ διὰ τοιαύτην αἰτίαν. Λεύκιος ἀπέλιπε μυρίους πεζοὺς ἐπὶ τῆς ἑαυτοῦ παρεμβολῆς, ἵν’ ἐὰν μὲν Ἀννίβας ὀλιγωρήσας τοῦ χάρακος ἐκτάξῃ πᾶσι, παραπεσόντες οὗτοι κατὰ τὸν τῆς μάχης καιρὸν ἐγκρατεῖς γένωνται τῆς τῶν πολεμίων ἀποσκευῆς, ἐὰν δὲ προϊδόμενος τὸ μέλλον ἀπολίπῃ φυλακὴν ἀξιόχρεων, πρὸς ἐλάττους αὐτοῖς ὁ περὶ τῶν ὅλων γένηται κίνδυνος. ἑάλωσαν δὲ τοιούτῳ τινὶ τρόπῳ. καταλιπόντος Ἀννίβου φυλακὴν ἀρκοῦσαν ἐπὶ τοῦ χάρακος, ἅμα τῷ κατάρξασθαι τὴν μάχην κατὰ τὸ συνταχθὲν ἐπολιόρκουν οἱ Ῥωμαῖοι, προσβάλλοντες τοὺς ἀπολελειμμένους ἐν τῷ τῶν Καρχηδονίων χάρακι. τὸ μὲν οὖν πρῶτον ἀντεῖχον· ἤδη δ’ αὐτῶν πιεζομένων, ἐπειδὴ κατὰ πάντα τὰ μέρη τὴν μάχην Ἀννίβας ἔκρινε, καὶ τότε παραβοηθήσας καὶ τρεψάμενος συνέκλεισε τοὺς Ῥωμαίους εἰς τὴν ἰδίαν παρεμβολὴν καὶ δισχιλίους μὲν αὐτῶν ἀπέκτεινε, τῶν δὲ λοιπῶν ἐγκρατὴς ἐγένετο ζωγρίᾳ πάντων. ὁμοίως δὲ καὶ τοὺς ἐπὶ τὰ κατὰ τὴν χώραν ἐρύματα συμπεφευγότας ἐκπολιορκήσαντες οἱ Νομάδες ἐπανῆγον, ὄντας εἰς δισχιλίους τῶν εἰς φυγὴν τραπέντων ἱππέων.", "st": "3.117"}, {"sp": "N", "t": "Βραβευθείσης δὲ τῆς μάχης τὸν προειρημένον τρόπον, ἀκόλουθον εἰλήφει τὰ ὅλα κρίσιν τοῖς ὑπ’ ἀμφοτέρων προσδοκωμένοις. Καρχηδόνιοι μὲν γὰρ διὰ τῆς πράξεως ταύτης παραχρῆμα τῆς μὲν λοιπῆς παραλίας σχεδὸν πάσης ἦσαν ἐγκρατεῖς· Ταραντῖνοί τε γὰρ εὐθέως ἐνεχείριζον αὑτούς, Ἀργυριππανοὶ δὲ καὶ Καπυανῶν τινες ἐκάλουν τὸν Ἀννίβαν, οἱ δὲ λοιποὶ πάντες ἀπέβλεπον ἤδη τότε πρὸς Καρχηδονίους· μεγάλας δ’ εἶχον ἐλπίδας ἐξ ἐφόδου καὶ τῆς Ῥώμης αὐτῆς ἔσεσθαι κύριοι· Ῥωμαῖοί γε μὴν τὴν Ἰταλιωτῶν δυναστείαν παραχρῆμα διὰ τὴν ἧτταν ἀπεγνώκεισαν, ἐν μεγάλοις δὲ φόβοις καὶ κινδύνοις ἦσαν περί τε σφῶν αὐτῶν καὶ περὶ τοῦ τῆς πατρίδος ἐδάφους, ὅσον οὔπω προσδοκῶντες ἥξειν αὐτὸν τὸν Ἀννίβαν. καὶ γὰρ ὥσπερ ἐπιμετρούσης καὶ συνεπαγωνιζομένης τοῖς γεγονόσι τῆς τύχης, συνέβη μετ’ ὀλίγας ἡμέρας, τοῦ φόβου κατέχοντος τὴν πόλιν, καὶ τὸν εἰς τὴν Γαλατίαν στρατηγὸν ἀποσταλέντ’ εἰς ἐνέδραν ἐμπεσόντα παραδόξως ἄρδην ὑπὸ τῶν Κελτῶν διαφθαρῆναι μετὰ τῆς δυνάμεως. οὐ μὴν ἥ γε σύγκλητος οὐδὲν ἀπέλειπε τῶν ἐνδεχομένων, ἀλλὰ παρεκάλει μὲν τοὺς πολλούς, ἠσφαλίζετο δὲ τὰ κατὰ τὴν πόλιν, ἐβουλεύετο δὲ περὶ τῶν ἐνεστώτων ἀνδρωδῶς. τοῦτο δ’ ἐγένετο φανερὸν ἐκ τῶν μετὰ ταῦτα συμβάντων· ὁμολογουμένως γὰρ Ῥωμαίων ἡττηθέντων τότε καὶ παραχωρησάντων τῆς ἐν τοῖς ὅπλοις ἀρετῆς, τῇ τοῦ πολιτεύματος ἰδιότητι καὶ τῷ βουλεύεσθαι καλῶς οὐ μόνον ἀνεκτήσαντο τὴν τῆς Ἰταλίας δυναστείαν, νικήσαντες μετὰ ταῦτα Καρχηδονίους, ἀλλὰ καὶ τῆς οἰκουμένης ἁπάσης ἐγκρατεῖς ἐγένοντο μετ’ ὀλίγους χρόνους. διόπερ ἡμεῖς ταύτην μὲν τὴν βύβλον ἐπὶ τούτων τῶν ἔργων καταστρέψομεν, ἃ περιέλαβεν Ἰβηρικῶν καὶ τῶν Ἰταλικῶν ἡ τετταρακοστὴ πρὸς ταῖς ἑκατὸν ὀλυμπιάσι δηλώσαντες· ὅταν δὲ τὰς Ἑλληνικὰς πράξεις τὰς κατὰ τὴν αὐτὴν ὀλυμπιάδα γενομένας διεξιόντες ἐπιστῶμεν τοῖς καιροῖς τούτοις, τότ’ ἤδη προθέμενοι ψιλῶς τὸν ὑπὲρ αὐτῆς τῆς Ῥωμαίων πολιτείας ποιησόμεθα λόγον, νομίζοντες οὐ μόνον πρὸς τὴν τῆς ἱστορίας σύνταξιν οἰκείαν εἶναι τὴν περὶ αὐτῆς ἐξήγησιν. ἀλλὰ καὶ πρὸς τὰς τῶν πολιτευμάτων διορθώσεις καὶ κατασκευὰς μεγάλα συμβάλλεσθαι τοῖς φιλομαθοῦσι καὶ πραγματικοῖς τῶν ἀνδρῶν.", "st": "3.118"}, {"sp": "HDR", "t": "Βιβλίον Δʹ", "st": "4"}, {"sp": "N", "t": "ἐν μὲν τῇ πρὸ ταύτης βύβλῳ τὰς αἰτίας ἐδηλώσαμεν τοῦ δευτέρου συστάντος Ῥωμαίοις καὶ Καρχηδονίοις πολέμου καὶ τὰ περὶ τῆς εἰσβολῆς τῆς εἰς Ἰταλίαν Ἀννίβου διήλθομεν, πρὸς δὲ τούτοις ἐξηγησάμεθα τοὺς γενομένους αὐτοῖς ἀγῶνας πρὸς ἀλλήλους μέχρι τῆς μάχης τῆς περὶ τὸν Αὔφιδον ποταμὸν καὶ πόλιν Κάνναν γενομένης. νῦν δὲ τὰς Ἑλληνικὰς διέξιμεν πράξεις τὰς κατὰ τοὺς αὐτοὺς καιροὺς ἐπιτελεσθείσας τοῖς προειρημένοις καὶ ἀπὸ τῆς ἑκατοστῆς καὶ τετταρακοστῆς ὀλυμπιάδος, πρότερον ἀναμνήσαντες διὰ βραχέων τοὺς ἐντυγχάνοντας τῇ πραγματείᾳ τῆς κατασκευῆς, ἣν ἐν τῇ δευτέρᾳ βύβλῳ περὶ τῶν Ἑλληνικῶν ἐποιησάμεθα, καὶ μάλιστα περὶ τοῦ τῶν Ἀχαιῶν ἔθνους, διὰ τὸ καὶ τοῦτο τὸ πολίτευμα παράδοξον ἐπίδοσιν λαβεῖν εἴς τε τοὺς πρὸ ἡμῶν καὶ καθ’ ἡμᾶς καιρούς. ἀρξάμενοι γὰρ ἀπὸ Τισαμενοῦ τῶν Ὀρέστου παίδων ἑνός, καὶ φήσαντες αὐτοὺς ἀπὸ μὲν τούτου βασιλευθῆναι κατὰ γένος ἕως εἰς Ὤγυγον, μετὰ δὲ ταῦτα καλλίστῃ προαιρέσει χρησαμένους δημοκρατικῆς πολιτείας τὸ μὲν πρῶτον ὑπὸ τῶν ἐκ Μακεδονίας βασιλέων διασπασθῆναι κατὰ πόλεις καὶ κώμας, ἑξῆς δὲ τούτοις ἐπεβαλόμεθα λέγειν πῶς αὖθις ἤρξαντο συμφρονεῖν καὶ πότε καὶ τίνες αὐτοῖς πρῶτοι συνέστησαν. τούτοις δ’ ἑπομένως ἐδηλώσαμεν τίνι τρόπῳ καὶ ποίᾳ προαιρέσει προσαγόμενοι τὰς πόλεις ἐπεβάλοντο Πελοποννησίους πάντας ὑπὸ τὴν αὐτὴν ἄγειν ὀνομασίαν καὶ πολιτείαν. καθολικῶς δὲ περὶ τῆς προειρημένης ἐπιβολῆς ἀποφηνάμενοι, μετὰ ταῦτα τῶν κατὰ μέρος ἔργων κατὰ τὸ συνεχὲς ἐπιψαύοντες εἰς τὴν Κλεομένους τοῦ Λακεδαιμονίων βασιλέως ἔκπτωσιν κατηντήσαμεν. συγκεφαλαιωσάμενοι δὲ τὰς ἐκ τῆς προκατασκευῆς πράξεις ἕως τῆς Ἀντιγόνου καὶ Σελεύκου καὶ Πτολεμαίου τελευτῆς, ἐπειδὴ περὶ τοὺς αὐτοὺς καιροὺς πάντες οὗτοι μετήλλαξαν, λοιπὸν ἐπηγγειλάμεθα τῆς αὑτῶν πραγματείας ἀρχὴν ποιήσασθαι τὰς ἑξῆς τοῖς προειρημένοις πράξεις,", "st": "4.1"}, {"sp": "N", "t": "καλλίστην ὑπόστασιν ὑπολαμβάνοντες εἶναι ταύτην διὰ τὸ πρῶτον μὲν τὴν Ἀράτου σύνταξιν ἐπὶ τούτους καταστρέφειν τοὺς καιρούς, οἷς συνάπτοντες τὴν διήγησιν τὸν ἀκόλουθον ὑπὲρ τῶν Ἑλλήνων ἀποδιδόναι προῃρήμεθα λόγον, δεύτερον δὲ διὰ τὸ καὶ τοὺς χρόνους οὕτως συντρέχειν τοὺς ἑξῆς καὶ τοὺς πίπτοντας ὑπὸ τὴν ἡμετέραν ἱστορίαν ὥστε τοὺς μὲν καθ’ ἡμᾶς εἶναι, τοὺς δὲ κατὰ τοὺς πατέρας ἡμῶν· ἐξ οὗ συμβαίνει τοῖς μὲν αὐτοὺς ἡμᾶς παραγεγονέναι, τὰ δὲ παρὰ τῶν ἑωρακότων ἀκηκοέναι. τὸ γὰρ ἀνωτέρω προσλαμβάνειν τοῖς χρόνοις, ὡς ἀκοὴν ἐξ ἀκοῆς γράφειν, οὐκ ἐφαίνεθ’ ἡμῖν ἀσφαλεῖς ἔχειν οὔτε τὰς διαλήψεις οὔτε τὰς ἀποφάσεις. μάλιστα δ’ ἀπὸ τούτων ἠρξάμεθα τῶν καιρῶν διὰ τὸ καὶ τὴν τύχην ὡς ἂν εἰ κεκαινοποιηκέναι πάντα τὰ κατὰ τὴν οἰκουμένην ἐν τοῖς προειρημένοις καιροῖς. Φίλιππος μὲν γὰρ ὁ Δημητρίου κατὰ φύσιν υἱὸς ἔτι παῖς ὢν ἄρτι παρελάμβανε τὴν Μακεδόνων ἀρχήν· Ἀχαιὸς δὲ τῆς ἐπὶ τάδε τοῦ Ταύρου δυναστεύων οὐ μόνον προστασίαν εἶχε βασιλικήν, ἀλλὰ καὶ δύναμιν· ὁ δὲ Μέγας ἐπικληθεὶς Ἀντίοχος μικροῖς ἀνώτερον χρόνοις, τἀδελφοῦ Σελεύκου μετηλλαχότος, ἔτι κομιδῇ νέος ὢν τὴν ἐν Συρίᾳ διεδέδεκτο βασιλείαν. ἅμα δὲ τούτοις Ἀριαράθης παρέλαβε τὴν Καππαδοκῶν ἀρχήν. ὁ δὲ Φιλοπάτωρ Πτολεμαῖος ἐν τοῖς αὐτοῖς καιροῖς τῶν κατ’ Αἴγυπτον ἐγεγόνει κύριος. Λυκοῦργος δὲ Λακεδαιμονίων μετ’ οὐ πολὺ κατεστάθη βασιλεύς. ᾕρηντο δὲ Καρχηδόνιοι προσφάτως ἐπὶ τὰς προειρημένας πράξεις στρατηγὸν αὑτῶν Ἀννίβαν. οὕτως δὲ τοιαύτης περὶ πάσας τὰς δυναστείας καινοποιίας οὔσης, ἔμελλε πραγμάτων ἔσεσθαι καινῶν ἀρχή. τοῦτο γὰρ δὴ πέφυκε καὶ φιλεῖ συμβαίνειν κατὰ φύσιν· ὃ καὶ τότε συνέβη γενέσθαι. Ῥωμαῖοι μὲν γὰρ καὶ Καρχηδόνιοι τὸν προειρημένον ἐνεστήσαντο πόλεμον, Ἀντίοχος δὲ καὶ Πτολεμαῖος ἅμα τούτοις τὸν ὑπὲρ τῆς Κοίλης Συρίας, Ἀχαιοὶ δὲ καὶ Φίλιππος τὸν πρὸς Αἰτωλοὺς καὶ Λακεδαιμονίους· οὗ τὰς αἰτίας συνέβη γενέσθαι τοιαύτας.", "st": "4.2"}, {"sp": "N", "t": "Αἰτωλοὶ πάλαι μὲν δυσχερῶς ἔφερον τὴν εἰρήνην καὶ τὰς ἀπὸ τῶν ἰδίων ὑπαρχόντων δαπάνας, ὡς ἂν εἰθισμένοι μὲν ζῆν ἀπὸ τῶν πέλας, δεόμενοι δὲ πολλῆς χορηγίας διὰ τὴν ἔμφυτον ἀλαζονείαν, ᾗ δουλεύοντες ἀεὶ πλεονεκτικὸν καὶ θηριώδη ζῶσι βίον, οὐδὲν οἰκεῖον, πάντα δ’ ἡγούμενοι πολέμια. οὐ μὴν ἀλλὰ τὸν πρὸ τοῦ χρόνον, ἕως Ἀντίγονος ἔζη, δεδιότες Μακεδόνας ἦγον ἡσυχίαν. ἐπειδὴ δ’ ἐκεῖνος μετήλλαξε τὸν βίον, παῖδα καταλιπὼν Φίλιππον, καταφρονήσαντες ἐζήτουν ἀφορμὰς καὶ προφάσεις τῆς εἰς Πελοπόννησον ἐπιπλοκῆς, ἀγόμενοι κατὰ τὸ παλαιὸν ἔθος ἐπὶ τὰς ἐκ ταύτης ἁρπαγάς, ἅμα δὲ καὶ νομίζοντες ἀξιόχρεως εἶναι σφᾶς πρὸς τὸ πολεμεῖν αὐτοῖς Ἀχαιοῖς. ὄντες δ’ ἐπὶ ταύτης τῆς προθέσεως, βραχέα ταὐτομάτου σφίσι συνεργήσαντος ἔλαβον ἀφορμὰς πρὸς τὴν ἐπιβολὴν τοιαύτας. Δωρίμαχος ὁ Τριχωνεὺς ἦν μὲν υἱὸς Νικοστράτου τοῦ παρασπονδήσαντος τὴν τῶν Παμβοιωτίων πανήγυριν, νέος δ’ ὢν καὶ πλήρης Αἰτωλικῆς ὁρμῆς καὶ πλεονεξίας ἐξαπεστάλη κατὰ κοινὸν εἰς τὴν τῶν Φιγαλέων πόλιν, ἥτις ἐστὶ μὲν ἐν Πελοποννήσῳ, κεῖται δὲ πρὸς τοῖς τῶν Μεσσηνίων ὅροις, ἐτύγχανε δὲ τότε συμπολιτευομένη τοῖς Αἰτωλοῖς, λόγῳ μὲν παραφυλάξων τήν τε χώραν καὶ τὴν πόλιν τῶν Φιγαλέων, ἔργῳ δὲ κατασκόπου τάξιν ἔχων τῶν ἐν Πελοποννήσῳ πραγμάτων. συνδραμόντων δὲ πειρατῶν, καὶ παραγενομένων πρὸς αὐτὸν εἰς τὴν Φιγάλειαν, οὐκ ἔχων τούτοις ἀπὸ τοῦ δικαίου συμπαρασκευάζειν ὠφελείας, διὰ τὸ μένειν ἔτι τότε τὴν κοινὴν εἰρήνην τοῖς Ἕλλησι τὴν ὑπ’ Ἀντιγόνου συντελεσθεῖσαν, τέλος ἀπορούμενος ἐπέτρεψε τοῖς πειραταῖς λῄζεσθαι τὰ τῶν Μεσσηνίων θρέμματα, φίλων ὄντων καὶ συμμάχων. τὸ μὲν οὖν πρῶτον ἠδίκουν τὰ περὶ τὰς ἐσχατιὰς ποίμνια, μετὰ δὲ ταῦτα, προβαινούσης τῆς ἀπονοίας, ἐνεχείρησαν καὶ τὰς ἐπὶ τῶν ἀγρῶν οἰκίας ἐκκόπτειν, ἀνυπονοήτως τὰς νύκτας ἐπιφαινόμενοι. τῶν δὲ Μεσσηνίων ἐπὶ τούτοις ἀγανακτούντων καὶ διαπρεσβευομένων πρὸς τὸν Δωρίμαχον, τὰς μὲν ἀρχὰς παρήκουε, βουλόμενος τὰ μὲν ὠφελεῖν τοὺς ὑπ’ αὐτὸν ταττομένους, τὰ δ’ αὐτὸς ὠφελεῖσθαι, μερίτης γινόμενος τῶν λαμβανομένων. πλεοναζούσης δὲ τῆς παρουσίας τῶν πρεσβειῶν διὰ τὴν συνέχειαν τῶν ἀδικημάτων, αὐτὸς ἥξειν ἐπὶ τὴν Μεσσήνην ἔφη, δικαιολογησόμενος πρὸς τοὺς ἐγκαλοῦντας τοῖς Αἰτωλοῖς. ἐπειδὴ δὲ παρεγένετο, προσπορευομένων αὐτῷ τῶν ἠδικημένων, τοὺς μὲν διέσυρε χλευάζων, τῶν δὲ κατανίστατο, τοὺς δ’ ἐξέπληττε λοιδορῶν.", "st": "4.3"}, {"sp": "N", "t": "ἔτι δ’ αὐτοῦ παρεπιδημοῦντος ἐν τῇ Μεσσήνῃ, συνεγγίσαντες τῇ πόλει νυκτὸς οἱ πειραταὶ καὶ προσβαλόντες κλίμακας ἐξέκοψαν τὸ Χυρῶνος καλούμενον ἐπαύλιον, καὶ τοὺς μὲν ἀμυνομένους ἀπέσφαξαν, τοὺς δὲ λοιποὺς τῶν οἰκετῶν δήσαντες καὶ τὰ κτήνη μετ’ αὐτῶν ἀπήγαγον. οἱ δὲ τῶν Μεσσηνίων ἔφοροι, πάλαι μὲν ἐπί τε τοῖς γινομένοις καὶ τῇ παρεπιδημίᾳ τοῦ Δωριμάχου διαλγοῦντες, τότε δὲ καὶ προσενυβρίζεσθαι δόξαντες, ἀνεκαλοῦντ’ αὐτὸν εἰς τὰς συναρχίας. ἐν ᾧ καιρῷ Σκύρων, ὃς ἦν μὲν ἔφορος τότε τῶν Μεσσηνίων, εὐδοκίμει δὲ καὶ κατὰ τὸν ἄλλον βίον παρὰ τοῖς πολίταις, συνεβούλευε μὴ προίεσθαι τὸν Δωρίμαχον ἐκ τῆς πόλεως, ἐὰν μὴ τὰ μὲν ἀπολωλότα πάντα τοῖς Μεσσηνίοις ἀποκαταστήσῃ, περὶ δὲ τῶν τεθνεώτων δωσιδίκους παράσχῃ τοὺς ἠδικηκότας. πάντων δ’ ἐπισημηναμένων ὡς δίκαια λέγοντος τοῦ Σκύρωνος, διοργισθεὶς ὁ Δωρίμαχος εὐήθεις αὐτοὺς ἔφη τελέως ὑπάρχειν, εἰ Δωρίμαχον οἴονται νῦν προπηλακίζειν, ἀλλ’ οὐ τὸ κοινὸν τῶν Αἰτωλῶν· καὶ καθόλου δεινὸν ἡγεῖτο τὸ γινόμενον, καὶ κοινῆς αὐτοὺς ἐπιστροφῆς ἔφη τεύξεσθαι, καὶ τοῦτο πείσεσθαι δικαίως. ἦν δέ τις κατ’ ἐκείνους τοὺς καιροὺς ἄνθρωπος ἀσυρὴς ἐν τῇ Μεσσήνῃ, τῶν ἐξηρμένων τὸν ἄνδρα κατὰ πάντα τρόπον, ὄνομα Βαβύρτας, ᾧ τις εἰ περιέθηκε τὴν καυσίαν καὶ χλαμύδα τοῦ Δωριμάχου, μὴ οἷόν τ’ εἶναι διαγινώσκειν· ἐπὶ τοσοῦτον ἐξωμοίωτο κατά τε τὴν φωνὴν καὶ τἄλλα μέρη τοῦ σώματος τῷ προειρημένῳ. καὶ τοῦτ’ οὐκ ἐλάνθανε τὸν Δωρίμαχον. ὁμιλοῦντος οὖν [αὐτοῦ] ἀνατατικῶς τότε καὶ μάλ’ ὑπερηφάνως τοῖς Μεσσηνίοις, περιοργισθεὶς ὁ Σκύρων \"νομίζεις γὰρ ἡμῖν\" ἔφη \"σοῦ μέλειν ἢ τῆς σῆς ἀνατάσεως, Βαβύρτα;\" ῥηθέντος δὲ τούτου, παραυτίκα μὲν εἴξας ὁ Δωρίμαχος τῇ περιστάσει συνεχώρησε πάντων ἐπιστροφὴν ποιήσεσθαι τῶν γεγονότων ἀδικημάτων τοῖς Μεσσηνίοις· ἐπανελθὼν δ’ εἰς τὴν Αἰτωλίαν οὕτω πικρῶς ἤνεγκε καὶ βαρέως τὸ ῥηθὲν ὡς οὐδεμίαν ἄλλην ἔχων εὔλογον πρόφασιν δι’ αὐτὸ τοῦτο τοῖς Μεσσηνίοις ἐξέκαυσε τὸν πόλεμον.", "st": "4.4"}, {"sp": "N", "t": "στρατηγὸς μὲν οὖν ὑπῆρχε τῶν Αἰτωλῶν Ἀρίστων· οὗτος δὲ διά τινας σωματικὰς ἀσθενείας ἀδύνατος ὢν πρὸς πολεμικὴν χρείαν, ἅμα δὲ καὶ συγγενὴς ὑπάρχων Δωριμάχου καὶ Σκόπα, τρόπον τινὰ παρακεχωρήκει τούτῳ τῆς ὅλης ἀρχῆς. ὁ δὲ Δωρίμαχος κατὰ κοινὸν μὲν οὐκ ἐτόλμα παρακαλεῖν τοὺς Αἰτωλοὺς εἰς τὸν κατὰ τῶν Μεσσηνίων πόλεμον διὰ τὸ μηδεμίαν ἔχειν ἀξίαν λόγου πρόφασιν, ἀλλ’ ὁμολογουμένως ἐκ παρανομίας καὶ σκώμματος γεγονέναι τὴν ὁρμήν· ἀφέμενος δὲ τῆς ἐπινοίας ταύτης ἰδίᾳ προετρέπετο τὸν Σκόπαν κοινωνῆσαι τῆς ἐπιβολῆς αὐτῷ τῆς κατὰ τῶν Μεσσηνίων, ὑποδεικνύων μὲν τὴν ἀπὸ Μακεδόνων ἀσφάλειαν διὰ τὴν ἡλικίαν τοῦ προεστῶτος — οὐ γὰρ εἶχε πλεῖον ἐτῶν τότε Φίλιππος ἑπτακαίδεκα — παρατιθεὶς δὲ τὴν Λακεδαιμονίων ἀλλοτριότητα πρὸς τοὺς Μεσσηνίους, ἀναμιμνήσκων δὲ τῆς Ἠλείων πρὸς σφᾶς εὐνοίας καὶ συμμαχίας· ἐξ ὧν ἀσφαλῆ τὴν εἰσβολὴν τὴν εἰς τὴν Μεσσηνίαν ἐσομένην αὐτοῖς ἀπέφαινεν. τὸ δὲ συνέχον τῆς Αἰτωλικῆς προτροπῆς, ὑπὸ τὴν ὄψιν ἐτίθει τὰς ἐσομένας ὠφελείας ἐκ τῆς τῶν Μεσσηνίων χώρας, οὔσης ἀπρονοήτου καὶ διαμεμενηκυίας ἀκεραίου μόνης τῶν ἐν Πελοποννήσῳ κατὰ τὸν Κλεομενικὸν πόλεμον. ἐπὶ δὲ πᾶσι τούτοις συνίστανε τὴν ἐξακολουθήσουσαν εὔνοιαν σφίσι παρὰ τοῦ τῶν Αἰτωλῶν πλήθους. Ἀχαιοὺς δ’, ἂν μὲν κωλύσωσι τὴν δίοδον, οὐκ ἐρεῖν ἐγκλήματα τοῖς ἀμυνομένοις· ἐὰν δ’ ἀγάγωσι τὴν ἡσυχίαν, οὐκ ἐμποδιεῖν αὐτοῖς πρὸς τὴν ἐπιβολήν. πρὸς δὲ Μεσσηνίους προφάσεως οὐκ ἀπορήσειν ἔφη· πάλαι γὰρ αὐτοὺς ἀδικεῖν Ἀχαιοῖς καὶ Μακεδόσιν ἐπηγγελμένους κοινωνήσειν τῆς συμμαχίας. ταῦτα δ’ εἰπὼν καὶ παραπλήσια τούτοις ἕτερα πρὸς τὴν αὐτὴν ὑπόθεσιν, τοιαύτην ὁρμὴν παρέστησε τῷ Σκόπᾳ καὶ τοῖς τούτου φίλοις ὥστ’ οὔτε κοινὴν τῶν Αἰτωλῶν προσδεξάμενοι σύνοδον οὔτε τοῖς ἀποκλήτοις συμμεταδόντες, οὐδὲ μὴν ἄλλο τῶν καθηκόντων οὐδὲν πράξαντες, κατὰ δὲ τὰς αὑτῶν ὁρμὰς καὶ κρίσεις διαλαβόντες ἅμα Μεσσηνίοις, Ἠπειρώταις, Ἀχαιοῖς, Ἀκαρνᾶσι, Μακεδόσι πόλεμον ἐξήνεγκαν.", "st": "4.5"}, {"sp": "N", "t": "καὶ κατὰ μὲν θάλατταν παραχρῆμα πειρατὰς ἐξέπεμψαν, οἳ περιτυχόντες πλοίῳ βασιλικῷ τῶν ἐκ Μακεδονίας περὶ Κύθηρα, τοῦτό τ’ εἰς Αἰτωλίαν καταγαγόντες αὔτανδρον, τούς τε ναυκλήρους καὶ τοὺς ἐπιβάτας, σὺν δὲ τούτοις τὴν ναῦν ἀπέδοντο. τῆς δ’ Ἠπείρου τὴν παραλίαν ἐπόρθουν, συγχρώμενοι πρὸς τὴν ἀδικίαν ταῖς τῶν Κεφαλλήνων ναυσίν· ἐπεβάλοντο δὲ καὶ τῆς Ἀκαρνανίας Θύριον καταλαβέσθαι. ἅμα δὲ τούτοις λάθρᾳ διὰ Πελοποννήσου τινὰς πέμψαντες ἐν μέσῃ τῇ τῶν Μεγαλοπολιτῶν χώρᾳ κατέσχον τὸ καλούμενον ὀχύρωμα Κλάριον· ᾧ λαφυροπωλείῳ χρησάμενοι διῆγον ἐν τούτῳ πρὸς τὰς ἁρπαγάς. οὐ μὴν ἀλλὰ τοῦτο μὲν Τιμόξενος ὁ τῶν Ἀχαιῶν στρατηγός, παραλαβὼν Ταυρίωνα τὸν ἐπὶ τῶν ἐν Πελοποννήσῳ βασιλικῶν πραγμάτων ὑπ’ Ἀντιγόνου καταλελειμμένον, ἐξεπολιόρκησε τελέως ἐν ὀλίγαις ἡμέραις. ὁ γὰρ βασιλεὺς Ἀντίγονος Κόρινθον μὲν εἶχε κατὰ τὸ τῶν Ἀχαιῶν συγχώρημα διὰ τοὺς Κλεομενικοὺς καιρούς, Ὀρχομενὸν δὲ κατὰ κράτος ἑλὼν οὐκ ἀποκατέστησε τοῖς Ἀχαιοῖς, ἀλλὰ σφετερισάμενος κατεῖχε, βουλόμενος, ὥς γ’ ἐμοὶ δοκεῖ, μὴ μόνον τῆς εἰσόδου κυριεύειν τῆς εἰς Πελοπόννησον, ἀλλὰ καὶ τὴν μεσόγαιαν αὐτῆς παραφυλάττειν διὰ τῆς ἐν Ὀρχομενῷ φρουρᾶς καὶ παρασκευῆς. οἱ δὲ περὶ τὸν Δωρίμαχον καὶ Σκόπαν παρατηρήσαντες τὸν καιρόν, ἐν ᾧ λοιπὸς ἦν Τιμοξένῳ μὲν ὀλίγος ἔτι χρόνος τῆς ἀρχῆς, Ἄρατος δὲ καθίστατο μὲν εἰς τὸν ἐνιαυτὸν τὸν ἐπιόντα στρατηγὸς ὑπὸ τῶν Ἀχαιῶν, οὔπω δ’ ἔμελλε τὴν ἀρχὴν ἕξειν, συναθροίσαντες πανδημεὶ τοὺς Αἰτωλοὺς ἐπὶ τὸ Ῥίον, καὶ παρασκευασάμενοι πορθμεῖα καὶ τὰς Κεφαλλήνων ἑτοιμάσαντες ναῦς, διεβίβασαν τοὺς ἄνδρας εἰς Πελοπόννησον καὶ προῆγον ἐπὶ τὴν Μεσσηνίαν. ποιούμενοι δὲ τὴν πορείαν διὰ τῆς Πατρέων καὶ Φαραιέων καὶ Τριταιέων χώρας ὑπεκρίνοντο μὲν βούλεσθαι μηδὲν ἀδίκημα ποιεῖν εἰς τοὺς Ἀχαιούς, οὐ δυναμένου δὲ τοῦ πλήθους ἀπέχεσθαι τῆς χώρας διὰ τὴν πρὸς τὰς ὠφελείας ἀκρασίαν, κακοποιοῦντες αὐτὴν καὶ λυμαινόμενοι διῄεσαν, μέχρι παρεγενήθησαν εἰς τὴν Φιγάλειαν. ποιησάμενοι δὲ τὴν ὁρμὴν ἐντεῦθεν αἰφνιδίως καὶ θρασέως, ἐνέβαλον εἰς τὴν τῶν Μεσσηνίων χώραν, οὔτε τῆς ὑπαρχούσης αὐτοῖς ἐκ παλαιῶν χρόνων πρὸς τοὺς Μεσσηνίους φιλίας καὶ συμμαχίας οὐδ’ ἡντινοῦν ποιησάμενοι πρόνοιαν οὔτε τῶν κατὰ κοινὸν ὡρισμένων δικαίων παρ’ ἀνθρώποις. ἅπαντα δ’ ἐν ἐλάττονι θέμενοι τῆς σφετέρας πλεονεξίας ἀδεῶς ἐπόρθουν, οὐ τολμώντων ἐπεξιέναι καθόλου τῶν Μεσσηνίων.", "st": "4.6"}, {"sp": "N", "t": "οἱ δ’ Ἀχαιοί, καθηκούσης αὐτοῖς ἐκ τῶν νόμων συνόδου κατὰ τὸν καιρὸν τοῦτον, ἧκον εἰς Αἴγιον. συνελθόντες δ’ εἰς τὴν ἐκκλησίαν, καὶ τῶν τε Πατρέων καὶ Φαραιέων ἀπολογιζομένων τὰ γεγονότα περὶ τὴν χώραν αὐτῶν ἀδικήματα κατὰ τὴν τῶν Αἰτωλῶν δίοδον, τῶν τε Μεσσηνίων παρόντων κατὰ πρεσβείαν καὶ δεομένων σφίσι βοηθεῖν ἀδικουμένοις καὶ παρασπονδουμένοις, διακούσαντες τῶν λεγομένων, καὶ συναγανακτοῦντες μὲν τοῖς Πατρεῦσι καὶ Φαραιεῦσι, συμπάσχοντες δὲ ταῖς τῶν Μεσσηνίων ἀτυχίαις, μάλιστα δὲ νομίζοντες εἶναι δεινὸν εἰ μήτε συγχωρήσαντος τοῖς Αἰτωλοῖς μηδενὸς τὴν δίοδον μήτε καθάπαξ ἐπιβαλόμενοι παραιτεῖσθαι κατετόλμησαν ἐπιβῆναι στρατοπέδῳ τῆς Ἀχαΐας παρὰ τὰς συνθήκας, ἐπὶ πᾶσι τούτοις παροξυνθέντες ἐψηφίσαντο βοηθεῖν τοῖς Μεσσηνίοις καὶ συνάγειν τὸν στρατηγὸν τοὺς Ἀχαιοὺς ἐν τοῖς ὅπλοις· ὃ δ’ ἂν τοῖς συνελθοῦσι βουλευομένοις δόξῃ, τοῦτ’ εἶναι κύριον. ὁ μὲν οὖν Τιμόξενος ὁ τότ’ ἔθ’ ὑπάρχων στρατηγός, ὅσον οὔπω ληγούσης τῆς ἀρχῆς, ἅμα δὲ τοῖς Ἀχαιοῖς ἀπιστῶν διὰ τὸ ῥᾳθύμως αὐτοὺς ἐσχηκέναι κατὰ τὸ παρὸν περὶ τὴν ἐν τοῖς ὅπλοις γυμνασίαν, ἀνεδύετο τὴν ἔξοδον καὶ καθόλου τὴν συναγωγὴν τῶν ὄχλων. μετὰ γὰρ τὴν Κλεομένους τοῦ Σπαρτιατῶν βασιλέως ἔκπτωσιν, κάμνοντες μὲν τοῖς προγεγονόσι πολέμοις, πιστεύοντες δὲ τῇ παρούσῃ καταστάσει, πάντες ὠλιγώρησαν Πελοποννήσιοι τῆς περὶ τὰ πολεμικὰ παρασκευῆς. ὁ δ’ Ἄρατος, σχετλιάζων καὶ παροξυνόμενος ἐπὶ τῇ τόλμῃ τῶν Αἰτωλῶν, θυμικώτερον ἐχρῆτο τοῖς πράγμασιν, ἅτε καὶ προϋπαρχούσης αὐτοῖς ἀλλοτριότητος ἐκ τῶν ἐπάνω χρόνων. διὸ καὶ συνάγειν ἔσπευδε τοὺς Ἀχαιοὺς ἐν τοῖς ὅπλοις καὶ συμβαλεῖν πρόθυμος ἦν τοῖς Αἰτωλοῖς. τέλος δὲ πένθ’ ἡμέραις πρότερον τοῦ καθήκοντος αὐτῷ χρόνου παραλαβὼν παρὰ τοῦ Τιμοξένου τὴν δημοσίαν σφραγῖδα, πρός τε τὰς πόλεις ἔγραφε καὶ συνῆγε τοὺς ἐν ταῖς ἡλικίαις μετὰ τῶν ὅπλων εἰς τὴν Μεγάλην πόλιν. ὑπὲρ οὗ δοκεῖ μοι πρέπον εἶναι βραχέα προειπεῖν διὰ τὴν ἰδιότητα τῆς φύσεως.", "st": "4.7"}, {"sp": "N", "t": "Ἄρατος γὰρ ἦν τὰ μὲν ἄλλα τέλειος ἀνὴρ εἰς τὸν πραγματικὸν τρόπον· καὶ γὰρ εἰπεῖν καὶ διανοηθῆναι καὶ στέξαι τὸ κριθὲν δυνατός, καὶ μὴν ἐνεγκεῖν τὰς πολιτικὰς διαφορὰς πρᾴως καὶ φίλους ἐνδήσασθαι καὶ συμμάχους προσλαβεῖν οὐδενὸς δεύτερος, ἔτι δὲ πράξεις, ἀπάτας, ἐπιβουλὰς συστήσασθαι κατὰ τῶν πολεμίων, καὶ ταύτας ἐπὶ τέλος ἀγαγεῖν διὰ τῆς αὑτοῦ κακοπαθείας καὶ τόλμης, δεινότατος. ἐναργῆ δὲ τῶν τοιούτων μαρτύρια καὶ πλείω μέν, ἐκφανέστατα δὲ τοῖς ἱστορηκόσι κατὰ μέρος περί τε τῆς Σικυῶνος καὶ Μαντινείας καταλήψεως καὶ περὶ τῆς Αἰτωλῶν ἐκ τῆς Πελληνέων πόλεως ἐκβολῆς, τὸ δὲ μέγιστον, περὶ τῆς κατὰ τὸν Ἀκροκόρινθον πράξεως. ὁ δ’ αὐτὸς οὗτος, ὅτε τῶν ὑπαίθρων ἀντιποιήσασθαι βουληθείη, νωθρὸς μὲν ἐν ταῖς ἐπινοίαις, ἄτολμος δ’ ἐν ταῖς ἐπιβολαῖς, ἐν ὄψει δ’ οὐ μένων τὸ δεινόν. διὸ καὶ τροπαίων ἐπ’ αὐτὸν βλεπόντων ἐπλήρωσε τὴν Πελοπόννησον, καὶ τῇδέ πῃ τοῖς πολεμίοις ἀεί ποτ’ ἦν εὐχείρωτος. οὕτως αἱ τῶν ἀνθρώπων φύσεις οὐ μόνον τοῖς σώμασιν ἔχουσί τι πολυειδές, ἔτι δὲ μᾶλλον ταῖς ψυχαῖς, ὥστε τὸν αὐτὸν ἄνδρα μὴ μόνον ἐν τοῖς διαφέρουσι τῶν ἐνεργημάτων πρὸς ἃ μὲν εὐφυῶς ἔχειν, πρὸς ἃ δ’ ἐναντίως, ἀλλὰ καὶ περί τινα τῶν ὁμοειδῶν πολλάκις τὸν αὐτὸν καὶ συνετώτατον εἶναι καὶ βραδύτατον, ὁμοίως δὲ καὶ τολμηρότατον καὶ δειλότατον. οὐ παράδοξα ταῦτά γε, συνήθη δὲ καὶ γνώριμα τοῖς βουλομένοις συνεφιστάνειν. τινὲς μὲν γὰρ ἐν ταῖς κυνηγίαις εἰσὶ τολμηροὶ πρὸς τὰς τῶν θηρίων συγκαταστάσεις, οἱ δ’ αὐτοὶ πρὸς ὅπλα καὶ πολεμίους ἀγεννεῖς, καὶ τῆς γε πολεμικῆς χρείας τῆς κατ’ ἄνδρα μὲν καὶ κατ’ ἰδίαν εὐχερεῖς καὶ πρακτικοί, κοινῇ δὲ καὶ μετὰ πολεμικῆς ἐπ’ ἴσον συντάξεως ἄπρακτοι. Θετταλῶν γοῦν ἱππεῖς κατ’ ἴλην μὲν καὶ φαλαγγηδὸν ἀνυπόστατοι, χωρὶς δὲ παρατάξεως πρὸς καιρὸν καὶ τόπον κατ’ ἄνδρα κινδυνεῦσαι δύσχρηστοι καὶ βραδεῖς· Αἰτωλοὶ δὲ τούτων τἀναντία. Κρῆτες δὲ καὶ κατὰ γῆν καὶ κατὰ θάλατταν πρὸς μὲν ἐνέδρας καὶ λῃστείας καὶ κλοπὰς πολεμίων καὶ νυκτερινὰς ἐπιθέσεις καὶ πάσας τὰς μετὰ δόλου καὶ κατὰ μέρος χρείας ἀνυπόστατοι, πρὸς δὲ τὴν ἐξ ὁμολόγου καὶ κατὰ πρόσωπον φαλαγγηδὸν ἔφοδον ἀγεννεῖς καὶ πλάγιοι ταῖς ψυχαῖς· Ἀχαιοὶ δὲ καὶ Μακεδόνες τἀναντία τούτων. ταῦτα μὲν εἰρήσθω μοι χάριν τοῦ μὴ διαπιστεῖν τοὺς ἀναγινώσκοντας τοῖς λεγομένοις, ἐάν που περὶ τῶν αὐτῶν ἀνδρῶν ἐναντίας ἀποφάσεις ποιώμεθα περὶ τὰ παραπλήσια τῶν ἐπιτηδευμάτων.", "st": "4.8"}, {"sp": "N", "t": "ἁθροισθέντων δὲ τῶν ἐν ταῖς ἡλικίαις μετὰ τῶν ὅπλων εἰς τὴν Μεγάλην πόλιν κατὰ δόγμα τῶν Ἀχαιῶν — ἀπὸ γὰρ τούτων παρεξέβημεν — καὶ τῶν Μεσσηνίων αὖθις ἐπιπορευθέντων ἐπὶ τὸ πλῆθος καὶ δεομένων μὴ περιιδεῖν σφᾶς οὕτω προφανῶς παρασπονδουμένους, βουλομένων δὲ καὶ τῆς κοινῆς συμμαχίας μετασχεῖν καὶ σπευδόντων ὁμοῦ τοῖς ἄλλοις ἐπιγραφῆναι, περὶ μὲν τῆς συμμαχίας οἱ προεστῶτες τῶν Ἀχαιῶν ἀπέλεγον, οὐ φάσκοντες δυνατὸν εἶναι χωρὶς Φιλίππου καὶ τῶν συμμάχων οὐδένα προσλαβεῖν· ἔτι γὰρ ἔνορκος ἔμενε πᾶσιν ἡ γεγενημένη συμμαχία δι’ Ἀντιγόνου κατὰ τοὺς Κλεομενικοὺς καιροὺς Ἀχαιοῖς, Ἠπειρώταις, Φωκεῦσι, Μακεδόσι, Βοιωτοῖς, Ἀκαρνᾶσι, Θετταλοῖς. ἐξελεύσεσθαι δὲ καὶ βοηθήσειν αὐτοῖς ἔφασαν, ἐὰν ὅμηρα δῶσιν οἱ παραγεγονότες τοὺς ἑαυτῶν υἱεῖς εἰς τὴν τῶν Λακεδαιμονίων πόλιν χάριν τοῦ μὴ διαλυθήσεσθαι πρὸς Αἰτωλοὺς χωρὶς τῆς τῶν Ἀχαιῶν βουλήσεως. ἐστρατοπέδευον δὲ καὶ Λακεδαιμόνιοι, κατὰ τὴν συμμαχίαν ἐξεληλυθότες, ἐπὶ τοῖς τῶν Μεγαλοπολιτῶν ὅροις, ἐφέδρων καὶ θεωρῶν μᾶλλον ἢ συμμάχων ἔχοντες τάξιν. Ἄρατος δὲ τὸν τρόπον τοῦτον τὰ πρὸς Μεσσηνίους διαπράξας, ἔπεμπε πρὸς τοὺς Αἰτωλούς, διασαφῶν τὰ δεδογμένα καὶ παρακελευόμενος ἐπανάγειν ἐκ τῆς τῶν Μεσσηνίων χώρας καὶ τῆς Ἀχαΐας μὴ ψαύειν· εἰ δὲ μή, διότι χρήσεται τοῖς ἐπιβαίνουσιν ὡς πολεμίοις. Σκόπας δὲ καὶ Δωρίμαχος ἀκούσαντες τὰ λεγόμενα καὶ γνόντες ἡθροισμένους τοὺς Ἀχαιούς, ἡγοῦντο συμφέρειν σφίσι τότε τίθεσθαι τοῖς παραγγελλομένοις. παραυτίκα μὲν οὖν ἐξαπέστελλον γραμματοφόρους εἴς τε Κυλλήνην καὶ πρὸς Ἀρίστωνα τὸν τῶν Αἰτωλῶν στρατηγόν, ἀξιοῦντες κατὰ σπουδὴν αὑτοῖς ἀποστέλλειν τὰ πορθμεῖα τῆς Ἠλείας εἰς τὴν Φειάδα καλουμένην νῆσον. αὐτοὶ δὲ μετὰ δύ’ ἡμέρας ἀνέζευξαν γέμοντες τῆς λείας, καὶ προῆγον ὡς ἐπὶ τὴν Ἠλείαν. ἀεὶ γάρ ποτε τῆς τῶν Ἠλείων ἀντείχοντο φιλίας Αἰτωλοὶ χάριν τοῦ διὰ τούτων ἐπιπλοκὰς λαμβάνειν πρὸς τὰς ἁρπαγὰς τὰς ἐκ Πελοποννήσου καὶ λῃστείας.", "st": "4.9"}, {"sp": "N", "t": "ὁ δ’ Ἄρατος ἐπιμείνας δύ’ ἡμέρας, καὶ πιστεύσας εὐήθως ὅτι ποιήσονται τὴν ἐπάνοδον, καθάπερ ὑπεδείκνυσαν, τοὺς μὲν λοιποὺς Ἀχαιοὺς καὶ τοὺς Λακεδαιμονίους διαφῆκε πάντας εἰς τὴν οἰκείαν, τρισχιλίους δ’ ἔχων πεζοὺς καὶ τριακοσίους ἱππεῖς καὶ τοὺς ἅμα τῷ Ταυρίωνι στρατιώτας, προῆγε τὴν ἐπὶ Πάτρας, ἀντιπαράγειν τοῖς Αἰτωλοῖς προαιρούμενος. οἱ δὲ περὶ τὸν Δωρίμαχον, πυνθανόμενοι τοὺς περὶ τὸν Ἄρατον ἀντιπαράγειν αὐτοῖς καὶ συμμένειν, τὰ μὲν διαγωνιάσαντες μὴ κατὰ τὴν εἰς τὰς ναῦς ἔμβασιν ἐπίθωνται σφίσι περισπωμένοις, τὰ δὲ σπουδάζοντες συγχέαι τὸν πόλεμον, τὴν μὲν λείαν ἀπέστειλαν ἐπὶ τὰ πλοῖα, συστήσαντες τοὺς ἱκανοὺς καὶ τοὺς ἐπιτηδείους πρὸς τὴν διακομιδήν, προσεντειλάμενοι τοῖς ἐκπεμπομένοις ταῦτα πρὸς τὸ Ῥίον ἀπαντᾶν, ὡς ἐντεῦθεν ποιησόμενοι τὴν ἔμβασιν, αὐτοὶ δὲ τὸ μὲν πρῶτον ἐφήδρευον τῇ τῆς λείας ἐξαποστολῇ περιέποντες, μετὰ δὲ ταῦτα προῆγον ἐκ μεταβολῆς ὡς ἐπ’ Ὀλυμπίας. ἀκούοντες δὲ τοὺς περὶ τὸν Ταυρίωνα μετὰ τοῦ προειρημένου πλήθους περὶ τὴν Κλειτορίαν εἶναι, καὶ νομίζοντες οὐδ’ ὣς δυνήσεσθαι τὴν ἀπὸ τοῦ Ῥίου διάβασιν ἄνευ κινδύνου ποιήσασθαι καὶ συμπλοκῆς, ἔκριναν συμφέρειν τοῖς σφετέροις πράγμασιν ὡς τάχιστα συμμῖξαι τοῖς περὶ τὸν Ἄρατον, ἀκμὴν ὀλίγοις οὖσι καὶ τοῦ μέλλοντος ἀνυπονοήτοις, ὑπολαβόντες, ἂν μὲν τρέψωνται τούτους, προκατασύραντες τὴν χώραν ἀσφαλῆ ποιήσεσθαι τὴν ἀπὸ τοῦ Ῥίου διάβασιν, ἐν ᾧ μέλλει καὶ βουλεύεται συναθροίζεσθαι πάλιν τὸ τῶν Ἀχαιῶν πλῆθος, ἂν δὲ καταπλαγέντες φυγομαχῶσι καὶ μὴ βούλωνται συμβάλλειν οἱ περὶ τὸν Ἄρατον, ἄνευ κινδύνου ποιήσεσθαι τὴν ἀπόλυσιν, ὁπόταν αὐτοῖς δοκῇ συμφέρειν. οὗτοι μὲν οὖν τοιούτοις χρησάμενοι λογισμοῖς προῆγον, καὶ κατεστρατοπέδευσαν περὶ Μεθύδριον τῆς Μεγαλοπολίτιδος·", "st": "4.10"}, {"sp": "N", "t": "οἱ δὲ τῶν Ἀχαιῶν ἡγεμόνες, συνέντες τὴν παρουσίαν τῶν Αἰτωλῶν, οὕτως κακῶς ἐχρήσαντο τοῖς πράγμασιν ὥσθ’ ὑπερβολὴν ἀνοίας μὴ καταλιπεῖν. ἀναστρέψαντες γὰρ ἐκ τῆς Κλειτορίας κατεστρατοπέδευσαν περὶ Καφύας. τῶν δ’ Αἰτωλῶν ποιουμένων τὴν πορείαν ἀπὸ Μεθυδρίου παρὰ τὴν τῶν Ὀρχομενίων πόλιν, ἐξάγοντες τοὺς Ἀχαιοὺς ἐν τῷ τῶν Καφυέων πεδίῳ παρενέβαλον, πρόβλημα ποιούμενοι τὸν δι’ αὐτοῦ ῥέοντα ποταμόν. οἱ δ’ Αἰτωλοὶ καὶ διὰ τὰς μεταξὺ δυσχωρίας — ἦσαν γὰρ ἔτι πρὸ τοῦ ποταμοῦ τάφροι καὶ πλείους δύσβατοι — καὶ διὰ τὴν ἐπίφασιν τῆς ἑτοιμότητος τῶν Ἀχαιῶν πρὸς τὸν κίνδυνον τοῦ μὲν ἐγχειρεῖν τοῖς ὑπεναντίοις κατὰ τὴν ἐξ ἀρχῆς πρόθεσιν ἀπεδειλίασαν, μετὰ δὲ πολλῆς εὐταξίας ἐποιοῦντο τὴν πορείαν ὡς ἐπὶ τὰς ὑπερβολὰς ἐπὶ τὸν Ὀλύγυρτον, ἀσμενίζοντες, εἰ μή τις αὐτοῖς ἐγχειροίη καὶ βιάζοιτο κινδυνεύειν. οἱ δὲ περὶ τὸν Ἄρατον, τῆς μὲν πρωτοπορείας τῶν Αἰτωλῶν ἤδη προσβαινούσης πρὸς τὰς ὑπερβολάς, τῶν δ’ ἱππέων οὐραγούντων διὰ τοῦ πεδίου καὶ συνεγγιζόντων τῷ προσαγορευομένῳ Πρόποδι τῆς παρωρείας, ἐξαποστέλλουσι τοὺς ἱππεῖς καὶ τοὺς εὐζώνους, Ἐπίστρατον ἐπιστήσαντες τὸν Ἀκαρνᾶνα, καὶ συντάξαντες ἐξάπτεσθαι τῆς οὐραγίας καὶ καταπειράζειν τῶν πολεμίων. καίτοι γ’ εἰ μὲν ἦν κινδυνευτέον, οὐ πρὸς τὴν οὐραγίαν ἐχρῆν συμπλέκεσθαι, διηνυκότων ἤδη τῶν πολεμίων τοὺς ὁμαλοὺς τόπους, πρὸς δὲ τὴν πρωτοπορείαν, εὐθέως ἐμβαλόντων εἰς τὸ πεδίον. οὕτως γὰρ ἂν τὸν ἀγῶνα συνέβη γενέσθαι τὸν ὅλον ἐν τοῖς ἐπιπέδοις καὶ πεδινοῖς τόποις, οὗ τοὺς μὲν Αἰτωλοὺς δυσχρηστοτάτους εἶναι συνέβαινε διά τε τὸν καθοπλισμὸν καὶ τὴν ὅλην σύνταξιν, τοὺς δ’ Ἀχαιοὺς εὐχρηστοτάτους καὶ δυναμικωτάτους διὰ τἀναντία τῶν προειρημένων. νῦν δ’ ἀφέμενοι τῶν οἰκείων τόπων καὶ καιρῶν εἰς τὰ τῶν πολεμίων προτερήματα συγκατέβησαν. τοιγαροῦν ἀκόλουθον τὸ τέλος ἐξέβη τοῦ κινδύνου ταῖς ἐπιβολαῖς.", "st": "4.11"}, {"sp": "N", "t": "ἐξαπτομένων γὰρ τῶν εὐζώνων τηροῦντες οἱ τῶν Αἰτωλῶν ἱππεῖς τὴν τάξιν ἀπεχώρουν εἰς τὴν παρώρειαν, σπεύδοντες συνάψαι τοῖς παρ’ αὑτῶν πεζοῖς. οἱ δὲ περὶ τὸν Ἄρατον, οὔτε κατιδόντες καλῶς τὸ γινόμενον οὔτ’ ἐκλογισάμενοι δεόντως τὸ μετὰ ταῦτα συμβησόμενον, ἅμα τῷ τοὺς ἱππεῖς ἰδεῖν ὑποχωροῦντας ἐλπίσαντες αὐτοὺς φεύγειν, τοὺς μὲν ἀπὸ τῶν κεράτων θωρακίτας ἐξαπέστειλαν, παραγγείλαντες βοηθεῖν καὶ συνάπτειν τοῖς παρ’ αὑτῶν εὐζώνοις, αὐτοὶ δ’ ἐπὶ κέρας κλίναντες τὴν δύναμιν ἦγον μετὰ δρόμου καὶ σπουδῆς. οἱ δὲ τῶν Αἰτωλῶν ἱππεῖς, διανύσαντες τὸ πεδίον, ἅμα τῷ συνάψαι τοῖς πεζοῖς αὐτοὶ μὲν ὑπὸ τὴν παρώρειαν ὑποστείλαντες ἔμενον, τοὺς δὲ πεζοὺς ἥθροιζον πρὸς τὰ πλάγια καὶ παρεκάλουν, ἑτοίμως πρὸς τὴν κραυγὴν ἀνατρεχόντων καὶ παραβοηθούντων ἀεὶ τῶν ἐκ τῆς πορείας. ἐπεὶ δ’ ἀξιομάχους ὑπέλαβον εἶναι σφᾶς αὐτοὺς κατὰ τὸ πλῆθος, συστραφέντες ἐνέβαλον τοῖς προμαχομένοις τῶν Ἀχαϊκῶν ἱππέων καὶ ψιλῶν. ὄντες δὲ πλείους, καὶ ποιούμενοι τὴν ἔφοδον ἐξ ὑπερδεξίου, πολὺν μὲν χρόνον ἐκινδύνευσαν, τέλος δ’ ἐτρέψαντο τοὺς συγκαθεστῶτας. ἐν δὲ τῷ τούτους ἐγκλίναντας φεύγειν οἱ προσβοηθοῦντες θωρακῖται κατὰ πορείαν ἀτάκτως ἐπιπαραγενόμενοι καὶ σποράδην, οἱ μὲν ἀποροῦντες ἐπὶ τοῖς γινομένοις, οἱ δὲ συμπίπτοντες ἀντίοις τοῖς φεύγουσι κατὰ τὴν ἀποχώρησιν, ἀναστρέφειν ἠναγκάζοντο καὶ τὸ παραπλήσιον ποιεῖν. ἐξ οὗ συνέβαινε τοὺς μὲν ἐκ τῆς συγκαταστάσεως ἡττηθέντας μὴ πλείους εἶναι πεντακοσίων, τοὺς δὲ φεύγοντας πλείους δισχιλίων. τοῦ δὲ πράγματος αὐτοῦ διδάσκοντος τοὺς Αἰτωλοὺς ὃ δεῖ ποιεῖν, εἵποντο κατόπιν, ἐπιπολαστικῶς καὶ κατακόρως χρώμενοι τῇ κραυγῇ. ποιουμένων δὲ τῶν Ἀχαϊκῶν τὴν ἀποχώρησιν πρὸς τὰ βαρέα τῶν ὅπλων, ὡς μενόντων ὑπὸ ταῖς ἀσφαλείαις ἐπὶ τῆς ἐξ ἀρχῆς τάξεως, τὸ μὲν πρῶτον εὐσχήμων ἐγένεθ’ ἡ φυγὴ καὶ σωτήριος· συνθεασάμενοι δὲ καὶ τούτους λελοιπότας τὰς τῶν τόπων ἀσφαλείας καὶ μακροὺς ὄντας ἐν πορείᾳ καὶ διαλελυμένους, οἱ μὲν αὐτῶν εὐθέως διαρρέοντες ἀτάκτως ἐποιήσαντο τὴν ἀποχώρησιν ἐπὶ τὰς παρακειμένας πόλεις, οἱ δὲ συμπίπτοντες ἀντίοις τοῖς ἐπιφερομένοις φαλαγγίταις οὐ προσεδέοντο τῶν πολεμίων, αὐτοὶ δὲ σφᾶς αὐτοὺς ἐκπλήττοντες ἠνάγκαζον φεύγειν προτροπάδην. ἐχρῶντο δὲ τῇ φυγῇ κατὰ τὴν ἀποχώρησιν, ὡς προείπομεν, ἐπὶ τὰς πόλεις· ὅ τε γὰρ Ὀρχομενὸς αἵ τε Καφύαι σύνεγγυς οὖσαι πολλοὺς ὤνησαν. μὴ γὰρ τούτου συμβάντος ἅπαντες ἂν ἐκινδύνευσαν διαφθαρῆναι παραλόγως. ὁ μὲν οὖν περὶ Καφύας γενόμενος κίνδυνος τοῦτον ἀπέβη τὸν τρόπον.", "st": "4.12"}, {"sp": "N", "t": "οἱ δὲ Μεγαλοπολῖται, συνέντες τοὺς Αἰτωλοὺς περὶ τὸ Μεθύδριον ἐστρατοπεδευκότας, ἧκον ἀπὸ σάλπιγγος πανδημεὶ βοηθοῦντες τῇ κατὰ πόδας ἡμέρᾳ τῆς μάχης, καὶ μεθ’ ὧν ζώντων ἤλπισαν κινδυνεύσειν πρὸς τοὺς ὑπεναντίους, τούτους ἠναγκάζοντο θάπτειν ὑπὸ τῶν ἐχθρῶν τετελευτηκότας. ὀρύξαντες δὲ τάφρον ἐν τῷ τῶν Καφυέων πεδίῳ, καὶ συναθροίσαντες τοὺς νεκρούς, ἐκήδευσαν μετὰ πάσης φιλοτιμίας τοὺς ἠτυχηκότας. οἱ δ’ Αἰτωλοὶ παραδόξως δι’ αὐτῶν τῶν ἱππέων καὶ τῶν ψιλῶν ποιήσαντες τὸ προτέρημα, λοιπὸν ἤδη μετ’ ἀσφαλείας διὰ μέσης Πελοποννήσου διῄεσαν. ἐν ᾧ καιρῷ καταπειράσαντες μὲν τῆς Πελληνέων πόλεως, κατασύραντες δὲ τὴν Σικυωνίαν χώραν, τέλος κατὰ τὸν Ἰσθμὸν ἐποιήσαντο τὴν ἀπόλυσιν. τὴν μὲν οὖν αἰτίαν καὶ τὴν ἀφορμὴν ὁ συμμαχικὸς πόλεμος ἔσχεν ἐκ τούτων, τὴν δ’ ἀρχὴν ἐκ τοῦ μετὰ ταῦτα γενομένου δόγματος ἁπάντων τῶν συμμάχων· οἳ συνελθόντες εἰς τὴν τῶν Κορινθίων πόλιν ἐπεκύρωσαν τὸ διαβούλιον διαπροστατεύσαντος Φιλίππου τοῦ βασιλέως.", "st": "4.13"}, {"sp": "N", "t": "τὸ δὲ τῶν Ἀχαιῶν πλῆθος μετά τινας ἡμέρας ἁθροισθὲν εἰς τὴν καθήκουσαν σύνοδον, πικρῶς διέκειτο καὶ κοινῇ καὶ κατ’ ἰδίαν πρὸς τὸν Ἄρατον, ὡς τοῦτον ὁμολογουμένως αἴτιον γεγονότα τοῦ προειρημένου συμπτώματος. διὸ καὶ τῶν ἀντιπολιτευομένων κατηγορούντων αὐτοῦ καὶ φερόντων ἀπολογισμοὺς ἐναργεῖς, ἔτι μᾶλλον ἠγανάκτει καὶ παρωξύνετο τὸ πλῆθος. ἐδόκει γὰρ πρῶτον ἁμάρτημα προφανὲς εἶναι τὸ μηδέπω τῆς ἀρχῆς αὐτῷ καθηκούσης προλαβόντα τὸν ἀλλότριον καιρὸν ἀναδέχεσθαι τοιαύτας πράξεις ἐν αἷς συνῄδει πολλάκις αὑτῷ διεσφαλμένῳ· δεύτερον δὲ καὶ μεῖζον τούτου τὸ διαφεῖναι τοὺς Ἀχαιοὺς ἀκμὴν ἐν μέσῳ Πελοποννήσου τῶν Αἰτωλῶν ὑπαρχόντων, ἄλλως τε καὶ προδιειληφότα διότι σπεύδουσιν οἱ περὶ τὸν Σκόπαν καὶ Δωρίμαχον κινεῖν τὰ καθεστῶτα καὶ συνταράξαι τὸν πόλεμον· τρίτον δὲ τὸ συμβαλεῖν τοῖς ὑπεναντίοις οὕτω μετ’ ὀλίγων μηδεμιᾶς κατεπειγούσης ἀνάγκης, δυνάμενον ἀσφαλῶς εἰς τὰς παρακειμένας πόλεις ἀποχωρῆσαι καὶ συναγαγεῖν τοὺς Ἀχαιοὺς καὶ τότε συμβαλεῖν τοῖς πολεμίοις, εἰ τοῦτο πάντως ἡγεῖτο συμφέρειν· τελευταῖον καὶ μέγιστον τὸ προθέμενον καὶ συμβαλεῖν οὕτως εἰκῇ καὶ ἀσκόπως χρήσασθαι τοῖς πράγμασιν ὥστε παρέντα τὰ πεδία καὶ τὴν τῶν ὁπλιτῶν χρείαν δι’ αὐτῶν τῶν εὐζώνων ταῖς παρωρείαις πρὸς Αἰτωλοὺς ποιήσασθαι τὸν κίνδυνον, οἷς οὐδὲν ἦν τούτου προυργιαίτερον οὐδ’ οἰκειότερον. οὐ μὴν ἀλλ’ ἅμα τῷ προελθόντα τὸν Ἄρατον ἀναμνῆσαι μὲν τῶν προπεπολιτευμένων καὶ πεπραγμένων πρότερον αὑτῷ, φέρειν δ’ ἀπολογισμοὺς περὶ τῶν ἐγκαλουμένων ὡς οὐ γέγονεν αἴτιος τῶν συμβεβηκότων, αἰτεῖσθαι δὲ συγγνώμην, εἰ καί τι παρεώρακε κατὰ τὸν γενόμενον κίνδυνον, οἴεσθαι δὲ δεῖν καὶ καθόλου σκοπεῖσθαι τὰ πράγματα μὴ πικρῶς, ἀλλ’ ἀνθρωπίνως, οὕτως ταχέως καὶ μεγαλοψύχως μετεμελήθη τὸ πλῆθος ὥστε καὶ τοῖς συνεπιτιθεμένοις αὐτῷ τῶν ἀντιπολιτευομένων ἐπὶ πολὺ δυσαρεστῆσαι καὶ περὶ τῶν ἑξῆς πάντα βουλεύεσθαι κατὰ τὴν Ἀράτου γνώμην. ταῦτα μὲν οὖν εἰς τὴν προτέραν ἔπεσεν ὀλυμπιάδα, τὰ δ’ ἑξῆς εἰς τὴν τετταρακοστὴν ἐπὶ ταῖς ἑκατόν.", "st": "4.14"}, {"sp": "N", "t": "ἦν δὲ τὰ δόξαντα τοῖς Ἀχαιοῖς ταῦτα· πρεσβεύειν πρὸς Ἠπειρώτας, Βοιωτούς, Φωκέας, Ἀκαρνᾶνας, Φίλιππον, καὶ διασαφεῖν τίνα τρόπον Αἰτωλοὶ παρὰ τὰς συνθήκας μεθ’ ὅπλων ἤδη δὶς εἰσβεβληκότες εἴησαν εἰς τὴν Ἀχαΐαν, καὶ παρακαλεῖν αὐτοὺς βοηθεῖν κατὰ τὰς ὁμολογίας, προσδέξασθαι δὲ καὶ τοὺς Μεσσηνίους εἰς τὴν συμμαχίαν, τὸν δὲ στρατηγὸν ἐπιλέξαι τῶν Ἀχαιῶν πεζοὺς μὲν πεντακισχιλίους, ἱππεῖς δὲ πεντακοσίους, καὶ βοηθεῖν τοῖς Μεσσηνίοις, ἐὰν ἐπιβαίνωσιν Αἰτωλοὶ τῆς χώρας αὐτῶν· συντάξασθαι δὲ καὶ πρὸς Λακεδαιμονίους καὶ πρὸς Μεσσηνίους ὅσους δεήσοι παρ’ ἀμφοῖν ὑπάρχειν ἱππεῖς καὶ πεζοὺς πρὸς τὰς κοινὰς χρείας. δοξάντων δὲ τούτων, οἱ μὲν Ἀχαιοὶ φέροντες γενναίως τὸ γεγονὸς οὔτε τοὺς Μεσσηνίους ἐγκατέλιπον οὔτε τὴν αὑτῶν πρόθεσιν, οἱ δὲ πρὸς τοὺς συμμάχους καθεσταμένοι τὰς πρεσβείας ἐπετέλουν, ὁ δὲ στρατηγὸς τοὺς μὲν ἐκ τῆς Ἀχαΐας ἄνδρας ἐπέλεγε κατὰ τὸ δόγμα, πρὸς δὲ τοὺς Λακεδαιμονίους καὶ Μεσσηνίους συνετάττετο πεζοὺς μὲν παρ’ ἑκατέρων ὑπάρχειν δισχιλίους καὶ πεντακοσίους, ἱππεῖς δὲ πεντήκοντα καὶ διακοσίους, ὥστ’ εἶναι τὸ πᾶν σύστημα πρὸς τὰς ἐπιγινομένας χρείας πεζοὺς μὲν μυρίους, ἱππεῖς δὲ χιλίους. οἱ δ’ Αἰτωλοί, παραγενομένης αὐτοῖς τῆς καθηκούσης ἐκκλησίας, συνελθόντες ἐβουλεύσαντο πρός τε Λακεδαιμονίους καὶ Μεσσηνίους καὶ τοὺς ἄλλους πάντας εἰρήνην ἄγειν, κακοπραγμονοῦντες καὶ βουλόμενοι φθείρειν καὶ λυμαίνεσθαι τοὺς τῶν Ἀχαιῶν συμμάχους· πρὸς αὐτοὺς δὲ τοὺς Ἀχαιούς, ἐὰν μὲν ἀφιστῶνται τῆς τῶν Μεσσηνίων συμμαχίας, ἄγειν ἐψηφίσαντο τὴν εἰρήνην, εἰ δὲ μή, πολεμεῖν, πρᾶγμα πάντων ἀλογώτατον. ὄντες γὰρ αὐτοὶ σύμμαχοι καὶ τῶν Ἀχαιῶν καὶ τῶν Μεσσηνίων, εἰ μὲν οὗτοι πρὸς ἀλλήλους φιλίαν ἄγοιεν καὶ συμμαχίαν, τὸν πόλεμον τοῖς Ἀχαιοῖς ἐπήγγελλον· εἰ δ’ ἔχθραν ἕλοιντο πρὸς τοὺς Μεσσηνίους, τὴν εἰρήνην αὐτοῖς ἐποίουν κατὰ μόνας, ὥστε μηδ’ ὑπὸ λόγον πίπτειν τὴν ἀδικίαν αὐτῶν διὰ τὸ παρηλλαγμένον αὐτῶν τῶν ἐγχειρημάτων.", "st": "4.15"}, {"sp": "N", "t": "οἱ δ’ Ἠπειρῶται καὶ Φίλιππος ὁ βασιλεὺς ἀκούσαντες τῶν πρέσβεων τοὺς μὲν Μεσσηνίους εἰς τὴν συμμαχίαν προσέλαβον, ἐπὶ δὲ τοῖς ὑπὸ τῶν Αἰτωλῶν πεπραγμένοις παραυτίκα μὲν ἠγανάκτησαν, οὐ μὴν ἐπὶ πλεῖον ἐθαύμασαν, διὰ τὸ μηδὲν παράδοξον, τῶν εἰθισμένων δέ τι πεποιηκέναι τοὺς Αἰτωλούς. διόπερ οὐδ’ ὠργίσθησαν ἐπὶ πλεῖον, ἀλλ’ ἐψηφίσαντο τὴν εἰρήνην ἄγειν πρὸς αὐτούς· οὕτως ἡ συνεχὴς ἀδικία συγγνώμης τυγχάνει μᾶλλον τῆς σπανίου καὶ παραδόξου πονηρίας. Αἰτωλοὶ γοῦν τούτῳ τῷ τρόπῳ χρώμενοι, καὶ λῃστεύοντες συνεχῶς τὴν Ἑλλάδα, καὶ πολέμους ἀνεπαγγέλτους φέροντες πολλοῖς, οὐδ’ ἀπολογίας ἔτι κατηξίουν τοὺς ἐγκαλοῦντας, ἀλλὰ καὶ προσεχλεύαζον, εἴ τις αὐτοὺς εἰς δικαιοδοσίας προκαλοῖτο περὶ τῶν γεγονότων ἢ καὶ νὴ Δία τῶν μελλόντων. οἱ δὲ Λακεδαιμόνιοι, προσφάτως μὲν ἠλευθερωμένοι δι’ Ἀντιγόνου καὶ διὰ τῆς τῶν Ἀχαιῶν φιλοτιμίας, ὀφείλοντες δὲ Μακεδόσι καὶ Φιλίππῳ μηδὲν ὑπεναντίον πράττειν, διαπεμψάμενοι λάθρᾳ πρὸς τοὺς Αἰτωλοὺς φιλίαν δι’ ἀπορρήτων ἔθεντο καὶ συμμαχίαν. ἤδη δ’ ἐπιλελεγμένων τῶν Ἀχαϊκῶν νεανίσκων καὶ συντεταγμένων ὑπὲρ τῆς βοηθείας τῶν Λακεδαιμονίων καὶ Μεσσηνίων, Σκερδιλαΐδας ὁμοῦ καὶ Δημήτριος ὁ Φάριος ἔπλευσαν ἐκ τῆς Ἰλλυρίδος ἐν ἐνενήκοντα λέμβοις ἔξω τοῦ Λίσσου παρὰ τὰς πρὸς Ῥωμαίους συνθήκας. οἳ τὸ μὲν πρῶτον τῇ Πύλῳ προσμίξαντες καὶ ποιησάμενοι προσβολὰς ἀπέπεσον· μετὰ δὲ ταῦτα Δημήτριος μὲν ἔχων τοὺς πεντήκοντα τῶν λέμβων ὥρμησεν ἐπὶ νήσων, καὶ περιπλέων τινὰς μὲν ἠργυρολόγει, τινὰς δ’ ἐπόρθει τῶν Κυκλάδων· Σκερδιλαΐδας δὲ ποιούμενος τὸν πλοῦν ὡς ἐπ’ οἴκου προσεῖχε πρὸς Ναύπακτον μετὰ τετταράκοντα λέμβων, πεισθεὶς Ἀμυνᾷ τῷ βασιλεῖ τῶν Ἀθαμάνων, ὃς ἐτύγχανε κηδεστὴς ὑπάρχων αὐτοῦ. ποιησάμενος δὲ συνθήκας πρὸς Αἰτωλοὺς δι’ Ἀγελάου περὶ τοῦ μερισμοῦ τῶν λαφύρων, ὑπέσχετο συνεμβαλεῖν ὁμόσε τοῖς Αἰτωλοῖς εἰς τὴν Ἀχαΐαν. συνθέμενοι δὲ ταῦτα πρὸς τὸν Σκερδιλαΐδαν οἱ περὶ τὸν Ἀγέλαον καὶ Δωρίμαχον καὶ Σκόπαν, πραττομένης αὐτοῖς τῆς τῶν Κυναιθέων πόλεως, συναθροίσαντες πανδημεὶ τοὺς Αἰτωλοὺς ἐνέβαλον εἰς τὴν Ἀχαΐαν μετὰ τῶν Ἰλλυριῶν.", "st": "4.16"}, {"sp": "N", "t": "ἀρίστων δ’ ὁ τῶν Αἰτωλῶν στρατηγός, οὐ προσποιούμενος οὐδὲν τῶν γινομένων, ἦγε τὴν ἡσυχίαν ἐπὶ τῆς οἰκείας, φάσκων οὐ πολεμεῖν τοῖς Ἀχαιοῖς, ἀλλὰ διατηρεῖν τὴν εἰρήνην, εὔηθες καὶ παιδικὸν πρᾶγμα ποιῶν· δῆλον γὰρ ὡς εὐήθη καὶ μάταιον εἰκὸς φαίνεσθαι τὸν τοιοῦτον, ὅταν ὑπολαμβάνῃ τοῖς λόγοις ἐπικρύψασθαι τὰς τῶν πραγμάτων ἐναργείας. οἱ δὲ περὶ τὸν Δωρίμαχον διὰ τῆς Ἀχαιάτιδος ποιησάμενοι τὴν πορείαν, ἧκον ἄφνω πρὸς τὴν Κύναιθαν. συνέβαινε δὲ τοὺς Κυναιθεῖς, ὄντας Ἀρκάδας, ἐκ πολλῶν χρόνων ἐν ἀκαταπαύστοις καὶ μεγάλαις συνεσχῆσθαι στάσεσι, καὶ πολλὰς μὲν κατ’ ἀλλήλων πεποιῆσθαι σφαγὰς καὶ φυγάς, πρὸς δὲ τούτοις ἁρπαγὰς ὑπαρχόντων, ἔτι δὲ γῆς ἀναδασμούς, τέλος δ’ ἐπικρατῆσαι τοὺς τὰ τῶν Ἀχαιῶν αἱρουμένους καὶ κατασχεῖν τὴν πόλιν, φυλακὴν ἔχοντας τῶν τειχῶν καὶ στρατηγὸν τῆς πόλεως ἐξ Ἀχαΐας. τούτων δ’ οὕτως ἐχόντων, ὀλίγοις ἔμπροσθεν χρόνοις τῆς τῶν Αἰτωλῶν παρουσίας διαπεμπομένων τῶν φυγάδων πρὸς τοὺς ἐν τῇ πόλει, καὶ δεομένων διαλυθῆναι πρὸς αὑτοὺς καὶ κατάγειν σφᾶς εἰς τὴν οἰκείαν, πεισθέντες οἱ κατέχοντες τὴν πόλιν ἐπρέσβευον πρὸς τὸ τῶν Ἀχαιῶν ἔθνος, βουλόμενοι μετὰ τῆς ἐκείνων γνώμης ποιεῖσθαι τὰς διαλύσεις. [τῶν Ἀχαιῶν] ἐπιχωρησάντων δ’ ἑτοίμως διὰ τὸ πεπεῖσθαι σφίσιν ἀμφοτέρους εὐνοήσειν, ἅτε τῶν μὲν κατεχόντων τὴν πόλιν ἐν τοῖς Ἀχαιοῖς ἐχόντων πάσας τὰς ἐλπίδας, τῶν δὲ καταπορευομένων μελλόντων τυγχάνειν τῆς σωτηρίας διὰ τὴν τῶν Ἀχαιῶν συγκατάθεσιν, οὕτως ἀποστείλαντες τὴν παραφυλακὴν καὶ τὸν στρατηγὸν ἐκ τῆς πόλεως οἱ Κυναιθεῖς διελύσαντο καὶ κατήγαγον τοὺς φυγάδας, ὄντας σχεδὸν εἰς τριακοσίους, λαβόντες πίστεις τῶν παρ’ ἀνθρώποις νομιζομένων τὰς ἰσχυροτάτας. οἱ δὲ κατανοστήσαντες οὐχ ὡς αἰτίας ἢ προφάσεως ἐπιγενομένης τοῦ δοκεῖν ἄλλης διαφορᾶς ἀρχὴν αὐτοῖς τινα γεγενῆσθαι, τὸ δ’ ἐναντίον παραχρῆμα κατελθόντες εὐθέως ἐπεβούλευον τῇ πατρίδι καὶ τοῖς σώσασι. καί μοι δοκοῦσι, καθ’ ὃν καιρὸν ἐπὶ τῶν σφαγίων τοὺς ὅρκους καὶ τὰς πίστεις ἐδίδοσαν ἀλλήλοις, τότε μάλιστα διανοεῖσθαι περί τε τῆς εἰς τὸ θεῖον καὶ τοὺς πιστεύσαντας ἀσεβείας. ἅμα γὰρ τῷ μετασχεῖν τῆς πολιτείας εὐθέως ἐπεσπῶντο τοὺς Αἰτωλοὺς καὶ τούτοις ἔπραττον τὴν πόλιν, σπεύδοντες τοὺς σώσαντας ἅμα καὶ τὴν θρέψασαν ἄρδην ἀπολέσαι.", "st": "4.17"}, {"sp": "N", "t": "τὴν δὲ πρᾶξιν τοιᾷδέ τινι τόλμῃ καὶ τοιούτῳ τρόπῳ συνεστήσαντο. πολέμαρχοι τῶν κατεληλυθότων τινὲς ἐγεγόνεισαν· ταύτην δὲ συμβαίνει τὴν ἀρχὴν κλείειν τὰς πύλας καὶ τὸν μεταξὺ χρόνον κυριεύειν τῶν κλειδῶν, ποιεῖσθαι δὲ καὶ τὸ καθ’ ἡμέραν τὴν δίαιταν ἐπὶ τῶν πυλώνων. οἱ μὲν οὖν Αἰτωλοὶ διεσκευασμένοι καὶ τὰς κλίμακας ἑτοίμας ἔχοντες ἐπετήρουν τὸν καιρόν· οἱ δὲ πολεμαρχοῦντες τῶν φυγάδων κατασφάξαντες τοὺς συνάρχοντας ἐπὶ τοῦ πυλῶνος ἀνέῳξαν τὴν πύλην. οὗ συμβάντος τινὲς μὲν τῶν Αἰτωλῶν διὰ ταύτης εἰσέπιπτον, τινὲς δὲ τὰς κλίμακας προσερείσαντες ἐβιάσαντο διὰ τούτων καὶ κατελάμβανον τὸ τεῖχος. οἱ δ’ ἐν τῇ πόλει πάντες, ἐκπλαγεῖς ὄντες ἐπὶ τοῖς συντελουμένοις, ἀπόρως καὶ δυσχρήστως εἶχον πρὸς τὸ συμβαῖνον· οὔτε γὰρ πρὸς τοὺς διὰ τῆς πύλης εἰσπίπτοντας οἷοί τ’ ἦσαν βοηθεῖν ἀπερισπάστως διὰ τοὺς πρὸς τὰ τείχη προσβάλλοντας, οὐδὲ μὴν τοῖς τείχεσιν ἐπαμύνειν διὰ τοὺς τῇ πύλῃ βιαζομένους. οἱ δ’ Αἰτωλοὶ διὰ ταύτας τὰς αἰτίας ταχέως ἐγκρατεῖς γενόμενοι τῆς πόλεως, τῶν ἀδίκων ἔργων ἓν τοῦτ’ ἔπραξαν δικαιότατον· πρώτους γὰρ τοὺς εἰσαγαγόντας καὶ προδόντας αὐτοῖς τὴν πόλιν κατασφάξαντες διήρπασαν τοὺς τούτων βίους. ὁμοίως δὲ καὶ τοῖς ἄλλοις ἐχρήσαντο πᾶσι· τὸ δὲ τελευταῖον ἐπισκηνώσαντες ἐπὶ τὰς οἰκίας ἐξετοιχωρύχησαν μὲν τοὺς βίους, ἐστρέβλωσαν δὲ πολλοὺς τῶν Κυναιθέων, οἷς ἠπίστησαν ἔχειν κεκρυμμένα διάφορον ἢ κατασκευάσματ’ ἤπερ ἄλλο τι τῶν πλείονος ἀξίων. τοῦτον δὲ τὸν τρόπον λωβησάμενοι τοὺς Κυναιθεῖς ἀνεστρατοπέδευσαν, ἀπολιπόντες φυλακὴν τῶν τειχῶν, καὶ προῆγον ὡς ἐπὶ Λούσων· καὶ παραγενόμενοι πρὸς τὸ τῆς Ἀρτέμιδος ἱερόν, ὃ κεῖται μὲν μεταξὺ Κλείτορος καὶ Κυναίθης, ἄσυλον δὲ νενόμισται παρὰ τοῖς Ἕλλησιν, ἀνετείνοντο διαρπάσειν τὰ θρέμματα τῆς θεοῦ καὶ τἄλλα τὰ περὶ τὸν ναόν. οἱ δὲ Λουσιᾶται νουνεχῶς δόντες τινὰ τῶν κατασκευασμάτων τῆς θεοῦ, παρῃτήσαντο τὴν τῶν Αἰτωλῶν ἀσέβειαν τοῦ μηδὲν παθεῖν ἀνήκεστον. οἱ δὲ δεξάμενοι παραχρῆμ’ ἀναζεύξαντες προσεστρατοπέδευσαν τῇ τῶν Κλειτορίων πόλει.", "st": "4.18"}, {"sp": "N", "t": "κατὰ δὲ τοὺς καιροὺς τούτους ὁ τῶν Ἀχαιῶν στρατηγὸς Ἄρατος ἐξαπέστειλε μὲν πρὸς Φίλιππον παρακαλῶν βοηθεῖν, συνῆγε δὲ τοὺς ἐπιλέκτους, μετεπέμπετο δὲ παρὰ Λακεδαιμονίων καὶ Μεσσηνίων τοὺς διατεταγμένους κατὰ τὰς ὁμολογίας. οἱ δ’ Αἰτωλοὶ τὸ μὲν πρῶτον παρεκάλουν τοὺς Κλειτορίους ἀποστάντας τῶν Ἀχαιῶν αἱρεῖσθαι τὴν πρὸς αὑτοὺς συμμαχίαν. τῶν δὲ Κλειτορίων ἁπλῶς οὐ προσιεμένων τοὺς λόγους, προσβολὰς ἐποιοῦντο, καὶ προσερείδοντες τὰς κλίμακας τοῖς τείχεσι κατεπείραζον τῆς πόλεως. ἀμυνομένων δὲ γενναίως καὶ τολμηρῶς τῶν ἔνδον, εἴξαντες τοῖς πράγμασιν ἀνεστρατοπέδευσαν, καὶ προαγαγόντες αὖθις ὡς ἐπὶ τὴν Κύναιθαν, ὅμως τὰ θρέμματα τῆς θεοῦ περισύραντες ἀπήγαγον. καὶ τὸ μὲν πρῶτον παρεδίδοσαν τοῖς Ἠλείοις τὴν Κύναιθαν· οὐ βουλομένων δὲ προσδέξασθαι τῶν Ἠλείων, ἐπεβάλοντο μὲν δι’ αὑτῶν κατέχειν τὴν πόλιν, στρατηγὸν ἐπιστήσαντες Εὐριπίδαν, μετὰ δὲ ταῦτα πάλιν δείσαντες ἐκ τῶν προσαγγελλομένων τὴν ἐκ Μακεδονίας βοήθειαν, ἐμπρήσαντες τὴν πόλιν ἀπηλλάγησαν, καὶ προῆγον αὖτις ὡς ἐπὶ τὸ Ῥίον, ταύτῃ κρίνοντες ποιεῖσθαι τὴν διάβασιν. ὁ δὲ Ταυρίων, πυνθανόμενος τὴν τῶν Αἰτωλῶν εἰσβολὴν καὶ τὰ περὶ τὴν Κύναιθαν πεπραγμένα, θεωρῶν δὲ τὸν Δημήτριον τὸν Φάριον ἀπὸ τῶν νήσων εἰς τὰς Κεγχρεὰς καταπεπλευκότα, παρεκάλει τοῦτον βοηθῆσαι τοῖς Ἀχαιοῖς καὶ διισθμίσαντα τοὺς λέμβους ἐπιτίθεσθαι τῇ τῶν Αἰτωλῶν διαβάσει. ὁ δὲ Δημήτριος λυσιτελῆ μέν, οὐκ εὐσχήμονα δὲ πεποιημένος τὴν ἀπὸ τῶν νήσων ἐπάνοδον, διὰ τὸν τῶν Ῥοδίων ἐπ’ αὐτὸν ἀνάπλουν, ἄσμενος ὑπήκουσε τῷ Ταυρίωνι, προσδεξαμένου ’κείνου τὴν εἰς τὴν ὑπέρβασιν τῶν λέμβων δαπάνην. οὗτος μὲν οὖν ὑπερισθμίσας, καὶ δυσὶ καθυστερήσας ἡμέραις τῆς τῶν Αἰτωλῶν διαβάσεως, προκατασύρας τινὰς τόπους τῆς παραλίας τῆς τῶν Αἰτωλῶν κατήχθη πάλιν εἰς τὴν Κόρινθον. Λακεδαιμόνιοι δὲ τὸ μὲν πέμπειν τὰς βοηθείας κατὰ τὴν διάταξιν ἐνεκάκησαν, βραχεῖς δέ τινας παντελῶς ἱππεῖς καὶ πεζούς, στοχαζόμενοι τοῦ δοκεῖν μόνον, ἐξέπεμψαν. Ἄρατος δὲ τοὺς Ἀχαιοὺς ἔχων πολιτικώτερον ἢ στρατηγικώτερον ὑπὲρ τῶν παρόντων ἐβουλεύσατο· μέχρι γὰρ τούτου τὴν ἡσυχίαν ἦγε, προσανέχων καὶ μεμνημένος τῆς προγεγενημένης συμφορᾶς, ἕως οὗ πάντα διαπραξάμενοι κατὰ τὰς αὑτῶν προαιρέσεις οἱ περὶ τὸν Σκόπαν καὶ Δωρίμαχον ἐπανῆλθον εἰς τὴν οἰκείαν, καίπερ διὰ τόπων ποιούμενοι τὰς πορείας εὐεπιθέτων καὶ στενῶν καὶ μόνον σαλπιγκτοῦ δεομένων. Κυναιθεῖς δὲ μεγάλοις ἀτυχήμασιν ὑπ’ Αἰτωλῶν καὶ μεγάλαις συμφοραῖς περιπεσόντες ὅμως πάντων ἀνθρώπων ἔδοξαν ἠτυχηκέναι δικαιότατα.", "st": "4.19"}, {"sp": "N", "t": "ἐπειδὴ δὲ κοινῇ τὸ τῶν Ἀρκάδων ἔθνος ἔχει τινὰ παρὰ πᾶσι τοῖς Ἕλλησιν ἐπ’ ἀρετῇ φήμην, οὐ μόνον διὰ τὴν ἐν τοῖς ἤθεσι καὶ βίοις φιλοξενίαν καὶ φιλανθρωπίαν, μάλιστα δὲ διὰ τὴν εἰς τὸ θεῖον εὐσέβειαν, ἄξιον βραχὺ διαπορῆσαι περὶ τῆς Κυναιθέων ἀγριότητος, πῶς ὄντες ὁμολογουμένως Ἀρκάδες τοσοῦτο κατ’ ἐκείνους τοὺς καιροὺς διήνεγκαν τῶν ἄλλων Ἑλλήνων ὠμότητι καὶ παρανομίᾳ. δοκοῦσι δέ μοι, διότι τὰ καλῶς ὑπὸ τῶν ἀρχαίων ἐπινενοημένα καὶ φυσικῶς συντεθεωρημένα περὶ πάντας τοὺς κατοικοῦντας τὴν Ἀρκαδίαν, ταῦτα δὴ πρῶτοι καὶ μόνοι τῶν Ἀρκάδων ἐγκατέλιπον. μουσικὴν γάρ, τήν γ’ ἀληθῶς μουσικήν, πᾶσι μὲν ἀνθρώποις ὄφελος ἀσκεῖν, Ἀρκάσι δὲ καὶ ἀναγκαῖον. οὐ γὰρ ἡγητέον μουσικήν, ὡς Ἔφορός φησιν ἐν τῷ προοιμίῳ τῆς ὅλης πραγματείας, οὐδαμῶς ἁρμόζοντα λόγον αὑτῷ ῥίψας, ἐπ’ ἀπάτῃ καὶ γοητείᾳ παρεισῆχθαι τοῖς ἀνθρώποις, οὐδὲ τοὺς παλαιοὺς Κρητῶν καὶ Λακεδαιμονίων αὐλὸν καὶ ῥυθμὸν εἰς τὸν πόλεμον ἀντὶ σάλπιγγος εἰκῇ νομιστέον εἰσαγαγεῖν, οὐδὲ τοὺς πρώτους Ἀρκάδων εἰς τὴν ὅλην πολιτείαν τὴν μουσικὴν παραλαβεῖν ἐπὶ τοσοῦτον ὥστε μὴ μόνον παισὶν οὖσιν, ἀλλὰ καὶ νεανίσκοις γενομένοις ἕως τριάκοντ’ ἐτῶν κατ’ ἀνάγκην σύντροφον ποιεῖν αὐτήν, τἄλλα τοῖς βίοις ὄντας αὐστηροτάτους. ταῦτα γὰρ πᾶσίν ἐστι γνώριμα καὶ συνήθη, διότι σχεδὸν παρὰ μόνοις Ἀρκάσι πρῶτον μὲν οἱ παῖδες ἐκ νηπίων ᾄδειν ἐθίζονται κατὰ νόμους τοὺς ὕμνους καὶ παιᾶνας, οἷς ἕκαστοι κατὰ τὰ πάτρια τοὺς ἐπιχωρίους ἥρωας καὶ θεοὺς ὑμνοῦσι· μετὰ δὲ ταῦτα τοὺς Φιλοξένου καὶ Τιμοθέου νόμους μανθάνοντες πολλῇ φιλοτιμίᾳ χορεύουσι κατ’ ἐνιαυτὸν τοῖς Διονυσιακοῖς αὐληταῖς ἐν τοῖς θεάτροις, οἱ μὲν παῖδες τοὺς παιδικοὺς ἀγῶνας, οἱ δὲ νεανίσκοι τοὺς τῶν ἀνδρῶν λεγομένους. ὁμοίως γε μὴν καὶ παρ’ ὅλον τὸν βίον τὰς ἀγωγὰς τὰς ἐν ταῖς συνουσίαις οὐχ οὕτως ποιοῦνται διὰ τῶν ἐπεισάκτων ἀκροαμάτων ὡς δι’ αὑτῶν, ἀνὰ μέρος ᾄδειν ἀλλήλοις προστάττοντες. καὶ τῶν μὲν ἄλλων μαθημάτων ἀρνηθῆναί τι μὴ γινώσκειν οὐδὲν αἰσχρὸν ἡγοῦνται, τήν γε μὴν ᾠδὴν οὔτ’ ἀρνηθῆναι δύνανται διὰ τὸ κατ’ ἀνάγκην πάντας μανθάνειν, οὔθ’ ὁμολογοῦντες ἀποτρίβεσθαι διὰ τὸ τῶν αἰσχρῶν παρ’ αὐτοῖς νομίζεσθαι τοῦτο. καὶ μὴν ἐμβατήρια μετ’ αὐλοῦ καὶ τάξεως ἀσκοῦντες, ἔτι δ’ ὀρχήσεις ἐκπονοῦντες μετὰ κοινῆς ἐπιστροφῆς καὶ δαπάνης κατ’ ἐνιαυτὸν ἐν τοῖς θεάτροις ἐπιδείκνυνται τοῖς αὑτῶν πολίταις οἱ νέοι.", "st": "4.20"}, {"sp": "N", "t": "ταῦτά τέ μοι δοκοῦσιν οἱ πάλαι παρεισαγαγεῖν οὐ τρυφῆς καὶ περιουσίας χάριν, ἀλλὰ θεωροῦντες μὲν τὴν ἑκάστων αὐτουργίαν καὶ συλλήβδην τὸ τῶν βίων ἐπίπονον καὶ σκληρόν, θεωροῦντες δὲ τὴν τῶν ἠθῶν αὐστηρίαν, ἥτις αὐτοῖς παρέπεται διὰ τὴν τοῦ περιέχοντος ψυχρότητα καὶ στυγνότητα τὴν κατὰ τὸ πλεῖστον ἐν τοῖς τόποις ὑπάρχουσαν, ᾧ συνεξομοιοῦσθαι πεφύκαμεν πάντες ἄνθρωποι κατ’ ἀνάγκην· οὐ γὰρ δι’ ἄλλην, διὰ δὲ ταύτην τὴν αἰτίαν κατὰ τὰς ἐθνικὰς καὶ τὰς ὁλοσχερεῖς διαστάσεις πλεῖστον ἀλλήλων διαφέρομεν ἤθεσί τε καὶ μορφαῖς καὶ χρώμασιν, ἔτι δὲ τῶν ἐπιτηδευμάτων τοῖς πλείστοις. βουλόμενοι δὲ μαλάττειν καὶ κιρνᾶν τὸ τῆς φύσεως αὔθαδες καὶ σκληρόν, τά τε προειρημένα πάντα παρεισήγαγον, καὶ πρὸς τούτοις συνόδους κοινὰς καὶ θυσίας πλείστας ὁμοίως ἀνδράσι καὶ γυναιξὶ κατείθισαν, ἔτι δὲ χοροὺς παρθένων ὁμοῦ καὶ παίδων, καὶ συλλήβδην πᾶν ἐμηχανήσαντο, σπεύδοντες τὸ τῆς ψυχῆς ἀτέραμνον διὰ τῆς τῶν ἐθισμῶν κατασκευῆς ἐξημεροῦν καὶ πραΰνειν. ὧν Κυναιθεῖς ὀλιγωρήσαντες εἰς τέλος, καὶ ταῦτα. πλείστης δεόμενοι τῆς τοιαύτης ἐπικουρίας διὰ τὸ σκληρότατον παρὰ πολὺ τῆς Ἀρκαδίας ἔχειν ἀέρα καὶ τόπον, πρὸς αὐτὰς δὲ τὰς ἐν ἀλλήλοις διατριβὰς καὶ φιλοτιμίας ὁρμήσαντες, τέλος ἀπεθηριώθησαν οὕτως ὥστε μηδ’ ἐν ὁποίᾳ γεγονέναι τῶν Ἑλληνίδων πόλεων ἀσεβήματα μείζονα καὶ συνεχέστερα. σημεῖον δὲ τῆς Κυναιθέων ἀτυχίας περὶ τοῦτο τὸ μέρος καὶ τῆς τῶν ἄλλων Ἀρκάδων τοῖς τοιούτοις τῶν ἐπιτηδευμάτων δυσαρεστήσεως· καθ’ οὓς γὰρ καιροὺς τὴν μεγάλην σφαγὴν ποιήσαντες Κυναιθεῖς ἐπρέσβευσαν πρὸς Λακεδαιμονίους, εἰς ἃς πόλεις ποτ’ Ἀρκαδικὰς εἰσῆλθον κατὰ τὴν ὁδόν, οἱ μὲν ἄλλοι παραχρῆμα πάντες αὐτοὺς ἐξεκήρυξαν, Μαντινεῖς δὲ μετὰ τὴν ἀπαλλαγὴν αὐτῶν καὶ καθαρμὸν ἐποιήσαντο καὶ σφάγια περιήνεγκαν τῆς τε πόλεως κύκλῳ καὶ τῆς χώρας πάσης. ταῦτα μὲν οὖν ἡμῖν εἰρήσθω χάριν τοῦ μὴ διὰ μίαν πόλιν τὸ κοινὸν ἦθος διαβάλλεσθαι τῶν Ἀρκάδων, ὁμοίως δὲ καὶ τοῦ μὴ νομίσαντας ἐνίους τῶν κατοικούντων τὴν Ἀρκαδίαν περιουσίας χάριν τὰ κατὰ μουσικὴν ἐπὶ πλεῖον ἀσκεῖσθαι παρ’ αὑτοῖς ὀλιγωρεῖν ἐγχειρῆσαι τούτου τοῦ μέρους, ἔτι δὲ καὶ Κυναιθέων ἕνεκεν, ἵν’ ἄν ποτ’ αὐτοῖς ὁ θεὸς εὖ δῷ, τραπέντες πρὸς παιδείαν ἡμερῶσιν αὑτούς, καὶ μάλιστα ταύτης πρὸς μουσικήν· οὕτως γὰρ μόνως ἂν λήξαιεν τῆς τότε περὶ αὐτοὺς γενομένης ἀγριότητος. ἡμεῖς δ’ ἐπειδὴ τὰ περὶ Κυναιθέων ὑποπίπτοντα δεδηλώκαμεν, αὖτις ἐπὶ τὴν ἐκτροπὴν ἐπάνιμεν.", "st": "4.21"}, {"sp": "N", "t": "Αἰτωλοὶ μὲν οὖν τοιαῦτα διεργασάμενοι κατὰ τὴν Πελοπόννησον ἧκον εἰς τὴν οἰκείαν ἀσφαλῶς. Φίλιππος δὲ μετὰ δυνάμεως βοηθῶν τοῖς Ἀχαιοῖς παρῆν εἰς Κόρινθον· ὑστερήσας δὲ τοῦ καιροῦ διαπέστειλε βιβλιαφόρους πρὸς πάντας τοὺς συμμάχους, παρακαλῶν πέμπειν ἑκάστους παρ’ αὑτῶν κατὰ σπουδὴν εἰς Κόρινθον τοὺς βουλευσομένους ὑπὲρ τῶν κοινῇ συμφερόντων. αὐτὸς δ’ ἀναζεύξας ὡς ἐπὶ Τεγέας προῆγε, πυνθανόμενος τοὺς Λακεδαιμονίους εἰς σφαγὰς καὶ ταραχὰς ἐμπεπτωκέναι πρὸς ἀλλήλους. οἱ γὰρ Λακεδαιμόνιοι συνήθεις ὄντες βασιλεύεσθαι καὶ πάντως τοῖς προεστῶσι πειθαρχεῖν, τότε προσφάτως μὲν ἠλευθερωμένοι δι’ Ἀντιγόνου, βασιλέως δ’ οὐχ ὑπάρχοντος παρ’ αὐτοῖς, ἐστασίαζον πρὸς σφᾶς, πάντες ὑπολαμβάνοντες ἴσον αὑτοῖς μετεῖναι τῆς πολιτείας. τὰς μὲν οὖν ἀρχὰς οἱ μὲν δύο τῶν ἐφόρων ἄδηλον εἶχον τὴν γνώμην, οἱ δὲ τρεῖς ἐκοινώνουν τοῖς Αἰτωλοῖς τῶν πραγμάτων, πεπεισμένοι διὰ τὴν ἡλικίαν τὸν Φίλιππον οὐδέπω δυνήσεσθαι τοῖς κατὰ τὴν Πελοπόννησον πράγμασιν ἐπαρκεῖν. ἐπεὶ δ’ οἱ μὲν Αἰτωλοὶ παρὰ τὴν προσδοκίαν αὐτῶν ἐκ Πελοποννήσου ταχεῖαν ἐποιήσαντο τὴν ἐπάνοδον, ὁ δὲ Φίλιππος ἐκ Μακεδονίας ἔτι θάττω τὴν παρουσίαν, ἀπιστοῦντες οἱ τρεῖς ἑνὶ τῶν δυεῖν Ἀδειμάντῳ διὰ τὸ συνειδέναι μὲν σφίσι πάσας τὰς ἐπιβολάς, μὴ λίαν δὲ τοῖς γινομένοις εὐδοκεῖν, ἠγωνίων μὴ συνεγγίσαντος τοῦ βασιλέως πάντα τὰ πραττόμενα πρὸς τὸν Φίλιππον ἐξηγήσηται. δι’ ἃ δὴ συλλαλήσαντές τισι τῶν νέων ἐκήρυττον εἰς τὸ τῆς Χαλκιοίκου τέμενος μετὰ τῶν ὅπλων ἰέναι τοὺς ἐν ταῖς ἡλικίαις, ὡς τῶν Μακεδόνων ἐπὶ τὴν πόλιν παραγινομένων. ταχὺ δὲ διὰ τὸ παράδοξον ἁθροισθέντων, δυσαρεστῶν Ἀδείμαντος τοῖς γινομένοις ἐπειρᾶτο προπορευθεὶς παρακαλεῖν καὶ διδάσκειν διότι \" πρῴην ἔδει τὰ κηρύγματα ταῦτα καὶ τοὺς ἁθροισμοὺς τοὺς ἐν τοῖς ὅπλοις παραγγέλλειν, καθ’ ὃν καιρὸν τοὺς Αἰτωλοὺς πολεμίους ὄντας ἠκούομεν τοῖς ὅρους τῆς χώρας ἡμῶν συνεγγίζειν, οὐ νῦν, ὅτε Μακεδόνας τοὺς εὐεργέτας καὶ σωτῆρας πυνθανόμεθα πλησιάζειν μετὰ τοῦ βασιλέως\". ἔτι δ’ αὐτοῦ ταῦτ’ ἀνακρουομένου, προσπεσόντες οἱ παρακεκλημένοι τῶν νέων τοῦτόν τε συνεκέντησαν καὶ μετὰ τούτου Σθενέλαον, Ἀλκαμένη, Θυέστην, Βιωνίδαν, ἑτέρους τῶν πολιτῶν καὶ πλείους. οἱ δὲ περὶ Πολυφόνταν καί τινες ἅμα τούτοις ἐμφρόνως προϊδόμενοι τὸ μέλλον, ἀπεχώρησαν πρὸς τὸν Φίλιππον.", "st": "4.22"}, {"sp": "N", "t": "ταῦτα δὲ πράξαντες εὐθέως ἔπεμπον οἱ προεστῶτες ἔφοροι τῶν πραγμάτων τοὺς κατηγορήσοντας πρὸς τὸν Φίλιππον τῶν ἀνῃρημένων καὶ παρακαλέσοντας αὐτὸν ἐπισχεῖν τὴν παρουσίαν, ἕως ἂν ἐκ τοῦ γεγονότος κινήματος εἰς τὴν ἀποκατάστασιν ἔλθῃ τὰ κατὰ τὴν πόλιν· γινώσκειν δὲ διότι πρόκειται διατηρεῖν αὐτοῖς πάντα τὰ δίκαια καὶ φιλάνθρωπα πρὸς Μακεδόνας· οἳ καὶ συμμίξαντες ἤδη περὶ τὸ Παρθένιον ὄρος ὄντι τῷ βασιλεῖ διελέχθησαν ἀκολούθως ταῖς ἐντολαῖς. ὁ δὲ διακούσας παρεκάλεσε τοὺς ἥκοντας κατὰ σπουδὴν ποιήσασθαι τὴν εἰς οἶκον ἐπάνοδον καὶ δηλοῦν τοῖς ἐφόροις ὅτι κατὰ τὸ συνεχὲς πορευθεὶς αὐτὸς μὲν ἐν Τεγέᾳ ποιήσεται τὴν στρατοπεδείαν, ἐκείνους δ’ οἴεται δεῖν τὴν ταχίστην ἐκπέμπειν ἄνδρας ἀξιοχρέους τοὺς κοινολογησομένους πρὸς αὑτὸν ὑπὲρ τῶν ἐνεστώτων. ποιησάντων δὲ τὸ προσταχθὲν τῶν ἀπαντησάντων, διακούσαντες τὰ παρὰ τοῦ βασιλέως οἱ προεστῶτες τῶν Λακεδαιμονίων ἐξέπεμψαν ἄνδρας δέκα πρὸς τὸν Φίλιππον οἳ καὶ πορευθέντες εἰς τὴν Τεγέαν καὶ παρελθόντες εἰς τὸ τοῦ βασιλέως συνέδριον, Ὠμίου προεστῶτος αὐτῶν, κατηγόρησαν μὲν τῶν περὶ τὸν Ἀδείμαντον ὡς αἰτίων γεγονότων τῆς κινήσεως, πάντα δ’ ὑπισχνοῦνται ποιήσειν αὐτοὶ τῷ Φιλίππῳ τὰ κατὰ τὴν συμμαχίαν, καὶ μηδενὸς ἐν μηδενὶ φανήσεσθαι δεύτεροι κατὰ τὴν πρὸς αὐτὸν εὔνοιαν τῶν δοκούντων ἀληθινῶν αὐτῷ φίλων ὑπάρχειν. οἱ μὲν οὖν Λακεδαιμόνιοι ταῦτα καὶ τούτοις παραπλήσια διαλεχθέντες μετέστησαν, οἱ δὲ μετέχοντες τοῦ συνεδρίου διεφέροντο πρὸς ἀλλήλους ταῖς γνώμαις. καὶ τινὲς μέν, εἰδότες τὴν κακοπραγμοσύνην τῶν ἐν τῇ Σπάρτῃ, καὶ πεπεισμένοι τοὺς περὶ τὸν Ἀδείμαντον ἀπολωλέναι διὰ τὴν πρὸς αὑτοὺς εὔνοιαν, τούς τε Λακεδαιμονίους ἐπιβεβλῆσθαι κοινοπραγεῖν τοῖς Αἰτωλοῖς, συνεβούλευον τῷ Φιλίππῳ παράδειγμα ποιῆσαι τοὺς Λακεδαιμονίους, χρησάμενον αὐτοῖς τὸν αὐτὸν τρόπον ὅνπερ Ἀλέξανδρος ἐχρήσατο Θηβαίοις εὐθέως παραλαβὼν τὴν ἀρχήν· ἕτεροι δὲ τῶν πρεσβυτέρων τὴν μὲν τοιαύτην ὀργὴν βαρυτέραν ἀπέφαινον εἶναι τῶν γεγονότων, ἐπιτιμῆσαι δὲ δεῖν τοῖς αἰτίοις, καὶ μεταστησάμενον τούτους ἐγχειρίσαι τὸ πολίτευμα καὶ τὰς ἀρχὰς τοῖς αὑτοῦ φίλοις.", "st": "4.23"}, {"sp": "N", "t": "ὁ δὲ βασιλεὺς ἐπὶ πᾶσιν, εἰ χρὴ τοῦ βασιλέως λέγειν τὰς τότε γνώμας· οὐ γὰρ εἰκὸς ἑπτακαιδεκαέτη παῖδα περὶ τηλικούτων δύνασθαι πραγμάτων διευκρινεῖν. ἀλλ’ ἡμῖν μὲν καθήκει τοῖς γράφουσι τὰς κυρούσας τὰ διαβούλια γνώμας ἀνατιθέναι τοῖς προεστῶσι τῶν ὅλων· τοὺς μέντοι γ’ ἀκούοντας αὐτοὺς χρὴ συνυπονοεῖν διότι τῶν συνόντων καὶ μάλιστα τῶν παρακειμένων εἰκός ἐστιν εἶναι τὰς τοιαύτας ὑποθέσεις καὶ διαλήψεις· ὧν Ἀράτῳ τις ἐπιεικέστατ’ ἂν προσάπτοι τὴν τότε ῥηθεῖσαν ὑπὸ τοῦ βασιλέως γνώμην. ὁ γὰρ Φίλιππος τὰ μὲν κατ’ ἰδίαν τῶν συμμάχων εἰς αὑτοὺς ἀδικήματα καθήκειν ἔφησεν αὑτῷ μέχρι λόγου καὶ γραμμάτων διορθοῦν καὶ συνεπισημαίνεσθαι, τὰ δὲ πρὸς τὴν κοινὴν ἀνήκοντα συμμαχίαν, ταῦτ’ ἔφη μόνα δεῖν κοινῆς ἐπιστροφῆς καὶ διορθώσεως τυγχάνειν ὑπὸ πάντων. Λακεδαιμονίων δὲ μηδὲν εἰς τὴν κοινὴν συμμαχίαν ἐκφανὲς ἡμαρτηκότων, ἐπαγγελλομένων δὲ πάντα καὶ ποιεῖν τὰ δίκαια πρὸς ἡμᾶς, οὐ καλῶς ἔχον εἶναι τὸ βουλεύεσθαί τι περὶ αὐτῶν ἀπαραίτητον· καὶ γὰρ ἄτοπον τὸν μὲν πατέρα πολεμίων ὄντων κρατήσαντα μηδὲν ποιῆσαι δεινόν, αὐτὸν δ’ ἐφ’ οὕτω μικρᾶς αἰτίας ἀνήκεστόν τι βουλεύεσθαι περὶ αὐτῶν. ἐπικυρωθείσης δὲ ταύτης τῆς γνώμης, ὅτι δεῖ παριδεῖν τὸ γεγονός, εὐθέως ὁ βασιλεὺς Πετραῖον τῶν αὑτοῦ φίλων ἅμα τοῖς περὶ τὸν Ὠμίαν ἐξαπέστελλε παρακαλέσοντα τοὺς πολλοὺς ἀντέχεσθαι τῆς πρὸς αὑτὸν καὶ Μακεδόνας εὐνοίας, ἅμα δὲ δώσοντα καὶ ληψόμενον τοὺς ὅρκους περὶ συμμαχίαν. αὐτὸς δὲ μετὰ τῆς δυνάμεως ἀναζεύξας προῆγε πάλιν ὡς ἐπὶ Κορίνθου, καλὸν δεῖγμα τῆς ἑαυτοῦ προαιρέσεως τοῖς συμμάχοις ἐκτιθέμενος ἐν τῇ πρὸς τοὺς Λακεδαιμονίους ἀποφάσει.", "st": "4.24"}, {"sp": "N", "t": "καταλαβὼν δὲ τοὺς ἀπὸ τῶν συμμαχίδων παραγεγονότας εἰς τὴν Κόρινθον, συνήδρευε καὶ διελάμβανε μετὰ τούτων τί δεῖ ποιεῖν καὶ πῶς χρήσασθαι τοῖς Αἰτωλοῖς. ἐγκαλούντων δὲ Βοιωτῶν μὲν ὅτι συλήσαιεν τὸ τῆς Ἀθηνᾶς τῆς Ἰτωνίας ἱερὸν εἰρήνης ὑπαρχούσης, Φωκέων δὲ διότι στρατεύσαντες ἐπ’ Ἄμβρυσον καὶ Δαύλιον ἐπιβάλοιντο καταλαβέσθαι τὰς πόλεις, Ἠπειρωτῶν δὲ καθότι πορθήσαιεν αὐτῶν τὴν χώραν, Ἀκαρνάνων δὲ παραδεικνυόντων τίνα τρόπον συστησάμενοι πρᾶξιν ἐπὶ Θύριον νυκτὸς ἔτι καὶ προσβαλεῖν τολμήσαιεν τῇ πόλει, πρὸς δὲ τούτοις Ἀχαιῶν ἀπολογιζομένων ὡς καταλάβοιντο μὲν τῆς Μεγαλοπολίτιδος Κλάριον, πορθήσαιεν δὲ διεξιόντες τὴν Πατρέων καὶ Φαραιέων χώραν, διαρπάσαιεν δὲ Κύναιθαν, συλήσαιεν δὲ τὸ τῆς ἐν Λούσοις Ἀρτέμιδος ἱερόν, πολιορκήσαιεν δὲ Κλειτορίους, ἐπιβουλεύσαιεν δὲ κατὰ μὲν θάλατταν Πύλῳ, κατὰ δὲ γῆν ἄρτι συνοικιζομένῃ τῇ Μεγαλοπολιτῶν πόλει σπεύδοντες μετὰ τῶν Ἰλλυριῶν ἀνάστατον αὐτὴν ποιῆσαι, διακούσαντες τούτων οἱ τῶν συμμάχων σύνεδροι πάντες ὁμοθυμαδὸν ἐκφέρειν ἐβουλεύσαντο τοῖς Αἰτωλοῖς τὸν πόλεμον. προθέμενοι δὲ τὰς προειρημένας αἰτίας ἐν τῷ δόγματι παρακατεβάλοντο ψήφισμα, προσδιασαφοῦντες ὅτι συνανασώσουσι τοῖς συμμάχοις, εἴ τινα κατέχουσιν αὐτῶν Αἰτωλοὶ χώραν ἢ πόλιν ἀφ’ οὗ Δημήτριος ὁ Φιλίππου κατὰ φύσιν πατὴρ μετήλλαξε· παραπλησίως δὲ καὶ τοὺς ὑπὸ τῶν καιρῶν ἠναγκασμένους ἀκουσίως μετέχειν τῆς Αἰτωλῶν συμπολιτείας, ὅτι πάντας τούτους ἀποκαταστήσουσιν εἰς τὰ πάτρια πολιτεύματα, χώραν ἔχοντας καὶ πόλεις τὰς αὑτῶν, ἀφρουρήτους, ἀφορολογήτους, ἐλευθέρους ὄντας, πολιτείαις καὶ νόμοις χρωμένους τοῖς πατρίοις. συνανακομιεῖσθαι δὲ καὶ τοῖς Ἀμφικτύοσιν ἔγραψαν τοὺς νόμους καὶ τὴν περὶ τὸ ἱερὸν ἐξουσίαν, ἣν Αἰτωλοὶ παρῄρηνται νῦν, βουλόμενοι τῶν κατὰ τὸ ἱερὸν ἐπικρατεῖν αὐτοί.", "st": "4.25"}, {"sp": "N", "t": "τούτου δὲ τοῦ δόγματος κυρωθέντος κατὰ τὸ πρῶτον ἔτος τῆς ἑκατοστῆς καὶ τετταρακοστῆς ὀλυμπιάδος ὁ μὲν συμμαχικὸς προσαγορευόμενος πόλεμος ἀρχὴν εἰλήφει δικαίαν καὶ πρέπουσαν τοῖς γεγονόσιν ἀδικήμασιν. οἱ δὲ σύνεδροι παραχρῆμα πρεσβευτὰς ἐξαπέστελλον πρὸς τοὺς συμμάχους, ἵνα παρ’ ἑκάστοις διὰ τῶν πολλῶν ἐπικυρωθέντος τοῦ δόγματος ἐκφέρωσι πάντες τοῖς Αἰτωλοῖς τὸν ἀπὸ τῆς χώρας πόλεμον. ἔπεμψε δὲ καὶ τοῖς Αἰτωλοῖς ἐπιστολὴν ὁ Φίλιππος, διασαφῶν ἵν’ εἴ τι λέγειν ἔχουσι δίκαιον ὑπὲρ τῶν ἐγκαλουμένων, ἔτι καὶ νῦν συνελθόντες διὰ λόγου ποιῶνται τὴν διεξαγωγήν· εἰ δ’ ὑπειλήφασι, διότι χωρὶς κοινοῦ δόγματος λεηλατοῦσι καὶ πορθοῦσι πάντας, οὐκ ἀμύνεσθαι τοὺς ἀδικουμένους, ἐὰν δ’ ἀμύνωνται, νομισθήσεσθαι τούτους κατάρχειν τοῦ πολέμου, πάντων αὐτοὺς εὐηθεστάτους εἶναι. κομισάμενοι δ’ οἱ τῶν Αἰτωλῶν ἄρχοντες τὴν ἐπιστολὴν ταύτην, τὸ μὲν πρῶτον ἐλπίσαντες οὐχ ἥξειν τὸν Φίλιππον, συνέθεντο ῥητὴν ἡμέραν ἐν ᾗ πρὸς τὸ Ῥίον ἀπαντήσουσι. γνόντες δὲ παραγινόμενον, ἀπέστειλαν γραμματοφόρον διασαφοῦντες ὡς οὐ δύνανται πρὸ τῆς τῶν Αἰτωλῶν συνόδου δι’ αὑτῶν οὐδὲν ὑπὲρ τῶν ὅλων οἰκονομεῖν. οἱ δ’ Ἀχαιοὶ συνελθόντες εἰς τὴν καθήκουσαν σύνοδον τό τε δόγμα πάντες ἐπεκύρωσαν καὶ τὸ λάφυρον ἐπεκήρυξαν κατὰ τῶν Αἰτωλῶν. προσελθόντος δὲ καὶ τοῦ βασιλέως πρὸς τὴν βουλὴν ἐν Αἰγίῳ καὶ διαλεχθέντος διὰ πλειόνων, τὰ ῥηθέντα μετ’ εὐνοίας ἀπεδέξαντο καὶ τὰ προϋπάρχοντα φιλάνθρωπα τοῖς προγόνοις ἀνενεώσαντο πρὸς αὐτὸν τὸν Φίλιππον.", "st": "4.26"}, {"sp": "N", "t": "κατὰ δὲ τοὺς αὐτοὺς καιροὺς Αἰτωλοί, συνάψαντος τοῦ τῶν ἀρχαιρεσίων χρόνου, στρατηγὸν αὑτῶν εἵλοντο Σκόπαν, ὃς ἐγεγόνει πάντων τῶν προειρημένων ἀδικημάτων αἴτιος. ὑπὲρ ὧν οὐκ οἶδα πῶς χρὴ λέγειν. τὸ γὰρ κοινῷ μὲν δόγματι μὴ πολεμεῖν, πανδημεὶ δὲ στρατεύοντας ἄγειν καὶ φέρειν τὰ τῶν πέλας, καὶ κολάζειν μὲν μηδένα τῶν αἰτίων, στρατηγοὺς δ’ αἱρεῖσθαι καὶ τιμᾶν τοὺς προεστῶτας τῶν τοιούτων ἔργων, ἐμοὶ μὲν δοκεῖ τῆς πάσης γέμειν κακοπραγμοσύνης· τί γὰρ ἂν ἄλλο τις τὰς τοιαύτας κακίας ὀνομάσειε; δῆλον δ’ ἔσται τὸ λεγόμενον ἐκ τούτων. Λακεδαιμόνιοι τὴν Καδμείαν Φοιβίδου παρασπονδήσαντος τὸν μὲν αἴτιον ἐζημίωσαν, τὴν δὲ φρουρὰν οὐκ ἐξήγαγον, ὥσπερ λυομένης τῆς ἀδικίας διὰ τῆς τοῦ πράξαντος βλάβης, παρὸν τἀναντία ποιεῖν· τοῦτο γὰρ διέφερε τοῖς Θηβαίοις. πάλιν ἐκήρυττον ἀφιέντες τὰς πόλεις ἐλευθέρας καὶ αὐτονόμους κατὰ τὴν ἐπ’ Ἀνταλκίδου γενομένην εἰρήνην, τοὺς δ’ ἁρμοστὰς οὐκ ἐξῆγον ἐκ τῶν πόλεων. Μαντινεῖς φίλους ὄντας καὶ συμμάχους ἀναστάτους ποιήσαντες οὐκ ἔφασαν ἀδικεῖν, ἐκ μιᾶς πόλεως εἰς πλείους αὐτοὺς διοικίσαντες, ἀνοίᾳ μετὰ κακίας χρησάμενοι προφανῶς διὰ τὸ δοκεῖν, ἐάν τις αὐτὸς ἐπιμύῃ, μηδὲ τοὺς πέλας ὁρᾶν. ἀμφοτέροις τοίνυν ὁ ζῆλος οὗτος τῆς πολιτείας αἴτιος κατέστη τῶν μεγίστων συμπτωμάτων· ὃν οὐδαμῶς οὐδαμῇ ζηλωτέον οὔτε κατ’ ἰδίαν οὔτε κοινῇ τοὺς ὀρθῶς βουλευομένους. ὁ δὲ βασιλεὺς Φίλιππος χρηματίσας τοῖς Ἀχαιοῖς ἀνέζευξε μετὰ τῆς δυνάμεως ἐπὶ Μακεδονίας, σπεύδων ἐπὶ τὴν παρασκευὴν τῶν πρὸς τὴν πόλεμον, οὐ μόνον τοῖς συμμάχοις, ἀλλὰ πᾶσι τοῖς Ἕλλησι διὰ τοῦ προειρημένου ψηφίσματος καλὰς ἐλπίδας ὑποδεικνύων πρᾳότητος καὶ μεγαλοψυχίας βασιλικῆς.", "st": "4.27"}, {"sp": "N", "t": "ταῦτα δ’ ἐπράττετο κατὰ τοὺς αὐτοὺς καιροὺς καθ’ οὓς Ἀννίβας, γεγονὼς ἤδη κύριος τῶν ἐντὸς Ἴβηρος ποταμοῦ πάντων, ἐποιεῖτο τὴν ὁρμὴν ἐπὶ τὴν Ζακανθαίων πόλιν. εἰ μὲν οὖν τὰς πρώτας ἐπιβολὰς τὰς Ἀννίβου ταῖς Ἑλληνικαῖς πράξεσιν ἀπ’ ἀρχῆς εὐθέως ἐπιπεπλέχθαι συνέβαινε, δῆλον ὡς ἐν τῇ προτέρᾳ βύβλῳ περὶ τούτων ἂν ἡμᾶς ἐναλλὰξ ἔδει καὶ κατὰ παράθεσιν τοῖς Ἰβηρικοῖς πεποιῆσθαι τὴν ἐξήγησιν, ἀκολουθοῦντας τοῖς καιροῖς· ἐπεὶ δὲ τά τε κατὰ τὴν Ἰταλίαν καὶ κατὰ τὴν Ἑλλάδα καὶ κατὰ τὴν Ἀσίαν τὰς μὲν ἀρχὰς τῶν πολέμων τούτων ἰδίας εἰλήφει, τὰς δὲ συντελείας κοινάς, καὶ τὴν ἐξήγησιν περὶ αὐτῶν ἐκρίναμεν ποιήσασθαι κατ’ ἰδίαν, ἕως ἂν ἐπὶ τὸν καιρὸν ἔλθωμεν τοῦτον ἐν ᾧ συνεπλάκησαν αἱ προειρημέναι πράξεις ἀλλήλαις καὶ πρὸς ἓν τέλος ἤρξαντο τὴν ἀναφορὰν ἔχειν — οὕτως γὰρ ἥ τε περὶ τὰς ἀρχὰς ἑκάστων ἔσται διήγησις σαφὴς ἥ τε συμπλοκὴ καταφανής, περὶ ἧς ἐν ἀρχαῖς ἐνεδειξάμεθα, παραδείξαντες πότε καὶ πῶς καὶ δι’ ἃς αἰτίας γέγονε — λοιπὸν ἤδη κοινὴν ποιήσασθαι περὶ πάντων τὴν ἱστορίαν. ἐγένετο δ’ ἡ συμπλοκὴ τῶν πράξεων περὶ τὴν τοῦ πολέμου συντέλειαν κατὰ τὸ τρίτον ἔτος τῆς ἑκατοστῆς καὶ τετταρακοστῆς ὀλυμπιάδος. διὸ καὶ τὰ μετὰ ταῦτα κοινῇ τοῖς καιροῖς ἀκολουθοῦντες ἐξηγησόμεθα, τὰ δὲ πρὸ τοῦ κατ’ ἰδίαν, ὡς εἶπα, προσαναμιμνήσκοντες μόνον τῶν κατὰ τοὺς αὐτοὺς καιροὺς ἐν τῇ προτέρᾳ βύβλῳ δεδηλωμένων, ἵνα μὴ μόνον εὐπαρακολούθητος, ἀλλὰ καὶ καταπληκτικὴ γίνηται τοῖς προσέχουσιν ἡ διήγησις.", "st": "4.28"}, {"sp": "N", "t": "Φίλιππος δὲ παραχειμάζων ἐν Μακεδονίᾳ κατέγραφε τὰς δυνάμεις πρὸς τὴν μέλλουσαν χρείαν ἐπιμελῶς, ἅμα δὲ τούτοις ἠσφαλίζετο τὰ πρὸς τοὺς ὑπερκειμένους τῆς Μακεδονίας βαρβάρους. μετὰ δὲ ταῦτα συνελθὼν πρὸς Σκερδιλαΐδαν καὶ τολμηρῶς δοὺς αὑτὸν εἰς τὰς χεῖρας, διελέγετο περὶ φιλίας καὶ συμμαχίας, καὶ τὰ μὲν ὑπισχνούμενος αὐτῷ συγκατασκευάσειν τῶν κατὰ τὴν Ἰλλυρίδα πραγμάτων, τὰ δὲ κατηγορῶν τῶν Αἰτωλῶν, ὄντων εὐκατηγορήτων, ῥᾳδίως ἔπεισε συγχωρεῖν τοῖς παρακαλουμένοις. μήποτε γὰρ οὐδὲν διαφέρει τὰ κατ’ ἰδίαν ἀδικήματα τῶν κοινῶν, ἀλλὰ πλήθει μόνον καὶ μεγέθει τῶν συμβαινόντων. καὶ γὰρ κατ’ ἰδίαν τὸ τῶν ῥᾳδιουργῶν καὶ κλεπτῶν φῦλον τούτῳ μάλιστα τῷ τρόπῳ σφάλλεται, τῷ μὴ ποιεῖν ἀλλήλοις τὰ δίκαια καὶ συλλήβδην διὰ τὰς εἰς αὑτοὺς ἀθεσίας. ὃ καὶ τότε συνέβη γενέσθαι περὶ τοὺς Αἰτωλούς. συνθέμενοι γὰρ τῷ Σκερδιλαΐδᾳ δώσειν μέρος τι τῆς λείας, ἐὰν συνεισβάλῃ μετ’ αὐτῶν εἰς τὴν Ἀχαΐαν, πεισθέντος καὶ ποιήσαντος τοῦτο, διαρπάσαντες τὴν τῶν Κυναιθέων πόλιν, καὶ πολλὰ περιελασάμενοι σώματα καὶ θρέμματα, τὸν Σκερδιλαΐδαν οὐδενὸς μερίτην ἐποίησαν τῶν ἁλόντων. διόπερ ὑποκαθημένης ἐκ τούτων αὐτῷ τῆς ὀργῆς, βραχέα προσαναμνήσαντος τοῦ Φιλίππου, ταχέως ὑπήκουσε καὶ συνέθετο μεθέξειν τῆς κοινῆς συμμαχίας, ἐφ’ ᾧ λαμβάνειν μὲν εἴκοσι τάλαντα κατ’ ἐνιαυτόν, πλεῖν δὲ λέμβοις τριάκοντα καὶ πολεμεῖν τοῖς Αἰτωλοῖς κατὰ θάλατταν.", "st": "4.29"}, {"sp": "N", "t": "ὁ μὲν οὖν Φίλιππος περὶ ταῦτα διέτριβεν. οἱ δ’ ἐξαποσταλέντες πρέσβεις πρὸς τοὺς συμμάχους, ἀφικόμενοι πρῶτον εἰς Ἀκαρνανίαν ἐνετύγχανον τούτοις. οἱ δ’ Ἀκαρνᾶνες τό τε δόγμα γνησίως συνεπεκύρωσαν καὶ τὸν ἀπὸ χώρας πόλεμον ἐξήνεγκαν τοῖς Αἰτωλοῖς· καίπερ τούτοις, εἰ καί τισιν ἑτέροις, δίκαιον ἦν συγγνώμην ἔχειν, ὑπερτιθεμένοις καὶ καταμέλλουσι καὶ καθόλου δεδιόσι τὸν ἀπὸ τῶν ἀστυγειτόνων πόλεμον, καὶ διὰ τὸ παρακεῖσθαι μὲν συντερμονοῦντας τῇ τῶν Αἰτωλῶν χώρᾳ, πολὺ δὲ μᾶλλον διὰ τὸ κατ’ ἰδίαν εὐχειρώτους ὑπάρχειν, τὸ δὲ μέγιστον διὰ τὸ μικροῖς ἔμπροσθεν χρόνοις πεῖραν εἰληφέναι τῶν δεινοτάτων διὰ τὴν πρὸς Αἰτωλοὺς ἀπέχθειαν. ἀλλά μοι δοκοῦσιν οἱ γνήσιοι τῶν ἀνδρῶν καὶ κοινῇ καὶ κατ’ ἰδίαν οὐδέποτε περὶ πλείονος οὐθὲν ποιεῖσθαι τοῦ καθήκοντος· ὅπερ Ἀκαρνᾶνες ἐν τοῖς πλείστοις καιροῖς οὐδενὸς τῶν Ἑλλήνων ἧττον εὑρίσκονται διατετηρηκότες, καίπερ ἀπὸ μικρᾶς ὁρμώμενοι δυνάμεως. οἷς οὐκ ὀκνητέον κατὰ τὰς περιστάσεις κοινωνεῖν πραγμάτων, σπευστέον δὲ μᾶλλον, εἰ καί τισιν ἑτέροις τῶν Ἑλλήνων· καὶ γὰρ ἰδίᾳ καὶ κοινῇ στάσιμον ἔχουσί τι καὶ φιλελεύθερον. Ἠπειρῶται δ’ ἐκ παραθέσεως διακούσαντες τῶν πρέσβεων τὸ μὲν δόγμα παραπλησίως ἐπεκύρωσαν, τὸν δὲ πόλεμον ἐκφέρειν ἐψηφίσαντο τοῖς Αἰτωλοῖς, ἐπειδὰν καὶ Φίλιππος ὁ βασιλεὺς ἐξενέγκῃ. τοῖς δὲ παρὰ τῶν Αἰτωλῶν πρεσβευταῖς ἀπεκρίθησαν ὅτι δέδοκται τοῖς Ἠπειρώταις διατηρεῖν πρὸς αὐτοὺς τὴν εἰρήνην, ἀγεννῶς καὶ ποικίλως χρώμενοι τοῖς πράγμασιν. ἀπεστάλησαν δὲ καὶ πρὸς βασιλέα Πτολεμαῖον πρέσβεις οἱ παρακαλέσοντες αὐτὸν μήτε χρήματα πέμπειν τοῖς Αἰτωλοῖς μήτ’ ἄλλο μηδὲν χορηγεῖν κατὰ Φιλίππου καὶ τῶν συμμάχων.", "st": "4.30"}, {"sp": "N", "t": "Μεσσήνιοι δέ, δι’ οὓς ὁ πόλεμος τὴν ἀρχὴν ἔλαβε, τοῖς παραγενομένοις πρὸς αὐτοὺς ἀπεκρίθησαν ὅτι τῆς Φιγαλείας κειμένης ἐπὶ τοῖς ὅροις αὐτῶν καὶ ταττομένης ὑπ’ Αἰτωλοὺς οὐκ ἂν ἐπιδέξαιντο τὸν πόλεμον, πρὶν ἢ ταύτην ἀπ’ Αἰτωλῶν ἀποσπασθῆναι τὴν πόλιν. περὶ δὲ τῆς ἀποφάσεως ταύτης κατίσχυσαν, οὐδαμῶς εὐδοκούντων τῶν πολλῶν, Αἰτωλῶν δεδιότες τὴν τόλμαν ἐφορεύοντες Οἶνις καὶ Νίκιππος καί τινες ἕτεροι τῶν ὀλιγαρχικῶν, ἀγνοοῦντες καὶ πολὺ παραπαίοντες τοῦ δέοντος κατά γε τὴν ἐμὴν γνώμην. ἐγὼ γὰρ φοβερὸν μὲν εἶναί φημι τὸν πόλεμον, οὐ μὴν οὕτω γε φοβερὸν ὥστε πᾶν ὑπομένειν χάριν τοῦ μὴ προσδέξασθαι πόλεμον. ἐπεὶ τί καὶ θρασύνομεν τὴν ἰσηγορίαν καὶ παρρησίαν καὶ τὸ τῆς ἐλευθερίας ὄνομα πάντες, εἰ μηδὲν ἔσται προυργιαίτερον τῆς εἰρήνης; οὐδὲ γὰρ Θηβαίους ἐπαινοῦμεν κατὰ τὰ Μηδικά, διότι τῶν ὑπὲρ τῆς Ἑλλάδος ἀποστάντες κινδύνων τὰ Περσῶν εἵλοντο διὰ τὸν φόβον, οὐδὲ Πίνδαρον τὸν συναποφηνάμενον αὐτοῖς ἄγειν τὴν ἡσυχίαν διὰ τῶνδε τῶν ποιημάτων, τὸ κοινόν τις ἀστῶν ἐν εὐδίᾳ τιθεὶς ἐρευνασάτω μεγαλάνορος ἡσυχίας τὸ φαιδρὸν φάος. δόξας γὰρ παραυτίκα πιθανῶς εἰρηκέναι, μετ’ οὐ πολὺ πάντων αἰσχίστην εὑρέθη καὶ βλαβερωτάτην πεποιημένος ἀπόφασιν· εἰρήνη γὰρ μετὰ μὲν τοῦ δικαίου καὶ πρέποντος κάλλιστόν ἐστι κτῆμα καὶ λυσιτελέστατον, μετὰ δὲ κακίας ἢ δειλίας ἐπονειδίστου πάντων αἴσχιστον καὶ βλαβερώτατον.", "st": "4.31"}, {"sp": "N", "t": "οἱ δὲ τῶν Μεσσηνίων προεστῶτες ὀλιγαρχικοί, [καὶ] στοχαζόμενοι τοῦ παραυτὰ κατ’ ἰδίαν λυσιτελοῦς, φιλοτιμότερον τοῦ δέοντος ἀεὶ διέκειντο πρὸς τὴν εἰρήνην. διὸ πολλὰς μὲν περιστάσεις καὶ καιροὺς ἔχοντες, ἐνίοτε δὲ φόβους καὶ κινδύνους διωλίσθανον· ἡθροίζετο δὲ κατὰ τὴν πρόθεσιν ταύτην ἀεὶ τὸ κεφάλαιον αὐτοῖς καὶ μεγίσταις ἐποίουν παλαίειν τὴν πατρίδα συμφοραῖς. δοκῶ δ’ ἔγωγε τὴν αἰτίαν εἶναι ταύτην, ὅτι δυσὶ γειτνιῶντες ἔθνεσι τοῖς μεγίστοις τῶν κατὰ Πελοπόννησον, μᾶλλον δὲ σχεδὸν καὶ τῶν Ἑλληνικῶν, λέγω δὲ τῷ τε τῶν Ἀρκάδων καὶ τῷ τῶν Λακώνων, καὶ τοῦ μὲν ἐχθρῶς καὶ ἀκαταλλάκτως ἀεί ποτε πρὸς αὐτοὺς ἔχοντος, ἐξ οὗ καὶ κατέσχον τὴν χώραν, τοῦ δὲ φιλικῶς καὶ κηδεμονικῶς, οὔτε τὴν πρὸς Λακεδαιμονίους ἔχθραν εὐγενῶς ἀνελάμβανον οὔτε τὴν πρὸς Ἀρκάδας φιλίαν. λοιπὸν ὅταν μὲν οὗτοι πρὸς ἀλλήλους ἢ πρὸς ἑτέρους πολεμοῦντες ἐν περισπασμοῖς ἦσαν, ἐγίνετο τὸ δέον αὐτοῖς· ἦγον γὰρ τὴν εἰρήνην ἀεὶ παρευδιαζόμενοι διὰ τὴν τοῦ τόπου παράπτωσιν· ὅταν δ’ εὔσχολοι καὶ ἀπερίσπαστοι Λακεδαιμόνιοι γενηθέντες ἐτράπησαν πρὸς τὸ βλάπτειν αὐτούς, οὔτ’ αὐτοὶ δι’ αὑτῶν ἀντοφθαλμεῖν ἐδύναντο πρὸς τὸ βάρος τὸ Λακεδαιμονίων οὔτε προκατεσκευασμένοι φίλους τοὺς ἀληθινῶς αὐτοῖς πάντα συνυποστησομένους ἢ δουλεύειν ἠναγκάζοντο τούτοις ἀχθοφοροῦντες ἢ φεύγοντας τὴν δουλείαν ἀναστάτους γίνεσθαι, λείποντας τὴν χώραν μετὰ τέκνων καὶ γυναικῶν· ὅπερ ἤδη πλεονάκις αὐτοῖς συνέβη παθεῖν οὐ πάνυ πολλοῖς χρόνοις. εἴη μὲν οὖν οἷον εἰ συμφῦναι τὴν νῦν ὑπάρχουσαν κατάστασιν Πελοποννησίοις, ἵνα μηδενὸς δέῃ τῶν λέγεσθαι μελλόντων· ἐὰν δέ ποτε κίνησιν καὶ μετάστασιν σχῇ ταῦτα, μίαν ὁρῶ Μεσσηνίοις καὶ Μεγαλοπολίταις ἐλπίδα τοῦ δύνασθαι νέμεσθαι τὴν αὑτῶν χώραν τὸν πλείω χρόνον, ἐὰν συμφρονήσαντες κατὰ τὴν Ἐπαμινώνδου γνώμην παντὸς καιροῦ καὶ πράγματος ἕλωνται κοινωνεῖν ἀλλήλοις ἀληθινῶς.", "st": "4.32"}, {"sp": "N", "t": "ὁ δὲ λόγος οὗτος ἔχει μὲν ἴσως καὶ διὰ τῶν πάλαι γεγονότων πίστιν. οἱ γὰρ Μεσσήνιοι πρὸς ἄλλοις πολλοῖς καὶ παρὰ τὸν τοῦ Διὸς τοῦ Λυκαίου βωμὸν ἀνέθεσαν στήλην ἐν τοῖς κατ’ Ἀριστομένην καιροῖς, καθάπερ καὶ Καλλισθένης φησί, γράψαντες τὸ γράμμα τοῦτο· πάντως ὁ χρόνος εὗρε δίκην ἀδίκῳ βασιλῆι, εὗρε δὲ Μεσσήνη σὺν Διὶ τὸν προδότην ῥηιδίως. χαλεπὸν δὲ λαθεῖν θεὸν ἄνδρ’ ἐπίορκον. χαῖρε, Ζεῦ βασιλεῦ, καὶ σάω Ἀρκαδίαν. ἐπεὶ γὰρ τῆς αὑτῶν ἐστερήθησαν, οἷον εἰ περὶ δευτέρας πατρίδος, ὥς γ’ ἐμοὶ δοκεῖ, τοῖς θεοῖς εὐχόμενοι σῴζειν τὴν Ἀρκαδίαν, τοῦτ’ ἀνέθεσαν τὸ γράμμα. καὶ τοῦτ’ εἰκότως ἐποίουν· οὐ γὰρ μόνον αὐτοὺς Ἀρκάδες ὑποδεξάμενοι κατὰ τὴν ἔκπτωσιν τὴν ἐκ τῆς ἰδίας ὑπὸ τὸν Ἀριστομένειον πόλεμον ὁμεστίους ἐποιήσαντο καὶ πολίτας, ἀλλὰ καὶ τὰς θυγατέρας ἐψηφίσαντο τοῖς ἐν ἡλικίᾳ διδόναι τῶν Μεσσηνίων, πρὸς δὲ τούτοις ἀναζητήσαντες τὴν Ἀριστοκράτους τοῦ βασιλέως προδοσίαν ἐν τῇ μάχῃ τῇ καλουμένῃ περὶ Τάφρον αὐτόν τ’ ἀνεῖλον καὶ τὸ γένος αὐτοῦ πᾶν ἠφάνισαν. οὐ μὴν ἀλλὰ καὶ χωρὶς τῶν πάλαι τὰ τελευταῖα γεγονότα μετὰ τὸν Μεγάλης πόλεως καὶ Μεσσήνης συνοικισμὸν ἱκανὴν ἂν παράσχοι πίστιν τοῖς ὑφ’ ἡμῶν εἰρημένοις. καθ’ οὓς γὰρ καιρούς, τῆς περὶ Μαντίνειαν μάχης τῶν Ἑλλήνων ἀμφιδήριτον ἐχούσης τὴν νίκην διὰ τὸν Ἐπαμινώνδου θάνατον, ἐκώλυον Λακεδαιμόνιοι μετέχειν τῶν σπονδῶν Μεσσηνίους, ἀκμὴν σφετεριζόμενοι ταῖς ἐλπίσι τὴν Μεσσηνίαν, ἐπὶ τοσοῦτο διέσπευσαν Μεγαλοπολῖται καὶ πάντες οἱ κοινωνοῦντες Ἀρκάδων τῆς αὐτῶν συμμαχίας ὥστε Μεσσηνίους μὲν ὑπὸ τῶν συμμάχων προσδεχθῆναι καὶ μετασχεῖν τῶν ὅρκων καὶ διαλύσεων, Λακεδαιμονίους δὲ μόνους ἐκσπόνδους γενέσθαι τῶν Ἑλλήνων. ἃ τίς οὐκ ἂν τῶν ἐπιγινομένων ἐν νῷ τιθέμενος νομίσειε καλῶς εἰρῆσθαι τὰ μικρῷ πρότερον ὑφ’ ἡμῶν δεδηλωμένα; ταῦτα μὲν οὖν εἰρήσθω μοι χάριν Ἀρκάδων καὶ Μεσσηνίων, ἵνα μνημονεύοντες τῶν συμβεβηκότων αὐτοῖς περὶ τὰς πατρίδας ἀτυχημάτων ὑπὸ Λακεδαιμονίων ἀληθινῶς ἀντέχωνται τῆς πρὸς αὑτοὺς εὐνοίας καὶ πίστεως, καὶ μήτε φόβον ὑφορώμενοι μήτ’ εἰρήνης ἐπιθυμοῦντες ἐγκαταλείπωσιν ἀλλήλους ἐν ταῖς ὁλοσχερέσι περιστάσεσι.", "st": "4.33"}, {"sp": "N", "t": "Λακεδαιμόνιοι δὲ τῶν εἰθισμένων ἐποίησάν τι — τοῦτο γὰρ συνεχὲς ἦν τοῖς προειρημένοις — τέλος γὰρ τοὺς παρὰ τῶν συμμάχων πρέσβεις ἀναποκρίτους ἀπέστειλαν. οὕτως ἐξηπόρησαν ὑπὸ τῆς ἀλογίας καὶ κακίας τῆς αὑτῶν. καί μοι δοκεῖ τοῦτ’ ἀληθὲς εἶναι διότι πολλάκις τολμᾶν περιττὸν εἰς ἄνοιαν καὶ τὸ μηδὲν καταντᾶν εἴωθεν. οὐ μὴν ἀλλὰ μετὰ ταῦτα, κατασταθέντων ἐφόρων ἄλλων, οἱ κινήσαντες ἐξ ἀρχῆς τὰ πράγματα καὶ γενόμενοι τῆς προειρημένης σφαγῆς αἴτιοι διεπέμποντο πρὸς τοὺς Αἰτωλούς, ἐπισπώμενοι πρεσβευτήν. τῶν δὲ καὶ μάλ’ ἀσμένως ὑπακουσάντων, ἧκε μετ’ ὀλίγον πρεσβεύων εἰς τὴν Λακεδαίμονα Μαχατᾶς. καὶ παραυτίκα προσῄει τοῖς ἐφόροις οἰόμενοι δεῖν τῷ τε Μαχατᾷ δίδοσθαι τὴν ἔφοδον ἐπὶ τοὺς πολλούς, καὶ βασιλέας καθιστάναι κατὰ τὰ πάτρια, καὶ μὴ περιορᾶν τὸν πλείω χρόνον παρὰ τοὺς νόμους καταλελυμένην τὴν τῶν Ἡρακλειδῶν ἀρχήν. οἱ δ’ ἔφοροι, δυσαρεστούμενοι μὲν τοῖς ὅλοις πράγμασιν, οὐ δυνάμενοι δὲ πρὸς τὴν ὁρμὴν ἀντοφθαλμεῖν, ἀλλὰ δεδιότες τὴν τῶν νέων συστροφήν, περὶ μὲν τῶν βασιλέων ἔφασαν μετὰ ταῦτα βουλεύσεσθαι, τῷ δὲ Μαχατᾷ συνεχώρησαν δώσειν τὴν ἐκκλησίαν. συναχθέντος δὲ τοῦ πλήθους παρελθὼν ὁ Μαχατᾶς παρεκάλει διὰ πλειόνων αὐτοὺς αἱρεῖσθαι τὴν πρὸς Αἰτωλοὺς συμμαχίαν, εἰκῇ μὲν καὶ θρασέως κατηγορῶν Μακεδόνων, ἀλόγως δὲ καὶ ψευδῶς ἐγκωμιάζων τοὺς Αἰτωλούς. μεταστάντος δὲ τούτου, πολλῆς ἀμφισβητήσεως ἐτύγχανε τὸ πρᾶγμα· τινὲς μὲν γὰρ συνηγόρουν τοῖς Αἰτωλοῖς καὶ συντίθεσθαι πρὸς αὐτοὺς παρῄνουν τὴν συμμαχίαν, ἔνιοι δὲ τούτοις ἀντέλεγον. οὐ μὴν ἀλλὰ τῶν πρεσβυτέρων τινὲς ἐπιστήσαντες τὸ πλῆθος ἐπί τε τὰς Ἀντιγόνου καὶ Μακεδόνων εὐεργεσίας ἐπί τε τὰς διὰ Χαριξένου καὶ Τιμαίου βλάβας, ὅτε στρατεύσαντες Αἰτωλοὶ πανδημεὶ κατέφθειραν μὲν αὐτῶν τὴν χώραν, ἐξηνδραποδίσαντο δὲ τὰς περιοίκους, ἐπεβούλευσαν δὲ τῇ Σπάρτῃ, μετὰ δόλου καὶ βίας τοὺς φυγάδας ἐπαγαγόντες, ἐπ’ ἄλλης ἐγένοντο γνώμης, καὶ τέλος ἐπείσθησαν τηρεῖν τὴν πρὸς Φίλιππον καὶ Μακεδόνας συμμαχίας. γενομένων δὲ τούτων, ὁ μὲν Μαχατᾶς ἄπρακτος ἐπανῄει πάλιν", "st": "4.34"}, {"sp": "N", "t": "εἰς τὴν οἰκείαν, οἱ δ’ ἐξ ἀρχῆς αἴτιοι γεγονότες τῆς κινήσεως, οὐδαμῶς εἶξαι δυνάμενοι τοῖς παροῦσιν, αὖτις ἐπεβάλοντο πρᾶγμα ποιεῖν πάντων ἀσεβέστατον, φθείραντές τινας τῶν νέων. κατὰ γάρ τινα θυσίαν πάτριον ἔδει τοὺς μὲν ἐν ταῖς ἡλικίαις μετὰ τῶν ὅπλων πομπεύειν ἐπὶ τὸν τῆς Ἀθηνᾶς τῆς Χαλκιοίκου νεών, τοὺς δ’ ἐφόρους συντελεῖν τὰ περὶ τὴν θυσίαν, αὐτοῦ περὶ τὸ τέμενος διατρίβοντας. ἐν τούτῳ τῷ καιρῷ τῶν πομπευόντων ἐν τοῖς ὅπλοις τινὲς νεανίσκων ἄφνω προσπεσόντες θύουσι τοῖς ἐφόροις ἀπέσφαξαν αὐτούς. καίτοι πᾶσι τοῖς καταφυγοῦσι τὴν ἀσφάλειαν παρεσκεύαζε τὸ ἱερόν, κἂν θανάτου τις ᾖ κατακεκριμένος· τότε δὲ διὰ τὴν ὠμότητα τῶν τολμώντων εἰς τοῦτ’ ἦλθε καταφρονήσεως ὥστε περὶ τὸν βωμὸν καὶ τὴν τράπεζαν τῆς θεοῦ κατασφαγῆναι τοὺς ἐφόρους ἅπαντας. ἑξῆς δὲ τούτου τἀκόλουθον τῇ προθέσει ποιοῦντες ἀνεῖλον μὲν τοὺς περὶ Γυρίδαν τῶν γερόντων, ἐφυγάδευσαν δὲ τοὺς ἀντειπόντας τοῖς Αἰτωλοῖς, εἵλοντο δ’ ἐξ αὑτῶν ἐφόρους, συνέθεντο δὲ πρὸς τοὺς Αἰτωλοὺς τὴν συμμαχίαν. ἐποίουν δὲ ταῦτα, καὶ τήν τε πρὸς Ἀχαιοὺς ἀπέχθειαν καὶ τὴν πρὸς Μακεδόνας ἀχαριστίαν καὶ καθόλου τὴν πρὸς πάντας ἀλογίαν ὑπέμενον — οὐχ ἥκιστα δὲ διὰ Κλεομένη καὶ τὴν πρὸς ἐκεῖνον εὔνοιαν — ἐπελπίζοντες ἀεὶ καὶ προσδοκίαν ἔχοντες τῆς ἐκείνου παρουσίας ἅμα καὶ σωτηρίας. οὕτως οἱ δυνάμενοι τῶν ἀνθρώπων ἐπιδεξίως ὁμιλεῖν τοῖς συμπεριφερομένοις οὐ μόνον παρόντες, ἀλλὰ καὶ μακρὰν ἀφεστῶτες ἐγκαταλείπουσί τινα καὶ λίαν ἰσχυρὰ τῆς πρὸς αὑτοὺς εὐνοίας αἰθύγματα. οἵ γε χωρὶς τῶν ἄλλων καὶ τότε, πολιτευόμενοι κατὰ τὰ πάτρια σχεδὸν ἤδη τρεῖς ἐνιαυτοὺς μετὰ τὴν Κλεομένους ἔκπτωσιν, οὐδ’ ἐπενόησαν οὐδέποτε βασιλεῖς καταστῆσαι τῆς Σπάρτης· ἅμα δὲ τῷ τὴν φήμην ἀφικέσθαι περὶ τῆς Κλεομένους τελευτῆς εὐθέως ὥρμησαν ἐπὶ τὸ βασιλεῖς καθιστάναι τά τε πλήθη καὶ τὸ τῶν ἐφόρων ἀρχεῖον. καὶ κατέστησαν οἱ κοινωνοῦντες ἔφοροι τῆς αἱρέσεως τοῖς στασιώταις, οἱ καὶ τὴν πρὸς Αἰτωλοὺς συνθέμενοι συμμαχίαν, ὑπὲρ ὧν τὸν ἄρτι λόγον ἐποιησάμην, τὸν μὲν ἕνα νομίμως καὶ καθηκόντως, Ἀγησίπολιν, ὄντα μὲν παῖδα τὴν ἡλικίαν, υἱὸν δ’ Ἀγησιπόλιδος τοῦ Κλεομβρότου· τὸν δὲ συνέβαινε βεβασιλευκέναι καθ’ οὓς καιροὺς ἐξέπεσε Λεωνίδης ἐκ τῆς ἀρχῆς, διὰ τὸ κατὰ γένος ὑπάρχειν ἔγγιστα τῆς οἰκίας ταύτης. ἐπίτροπον δὲ τοῦ παιδὸς εἵλοντο Κλεομένη, Κλεομβρότου μὲν υἱόν, Ἀγησιπόλιδος δ’ ἀδελφόν. ἀπὸ δὲ τῆς ἑτέρας οἰκίας, ὄντων ἐκ τῆς Ἱππομέδοντος θυγατρὸς Ἀρχιδάμῳ δυεῖν παίδων, ὃς ἦν υἱὸς Εὐδαμίδου, ζῶντος δὲ καὶ Ἱππομέδοντος ἀκμήν, ὃς ἦν υἱὸς Ἀγησιλάου τοῦ Εὐδαμίδου, καὶ ἑτέρων δὲ πλειόνων ἀπὸ τῆς οἰκίας ὑπαρχόντων, ἀπωτέρω μὲν τῶν προειρημένων, προσηκόντων δὲ κατὰ γένος, τούτους μὲν ἅπαντας ὑπερεῖδον, Λυκοῦργον δὲ βασιλέα κατέστησαν, οὗ τῶν προγόνων οὐδεὶς ἐτετεύχει τῆς προσηγορίας· ὃς δοὺς ἑκάστῳ τῶν ἐφόρων τάλαντον Ἡρακλέους ἀπόγονος καὶ βασιλεὺς ἐγεγόνει τῆς Σπάρτης. οὕτως εὔωνα πανταχῇ τὰ καλὰ γέγονε. τοιγαροῦν οὐ παῖδες παίδων, ἀλλ’ αὐτοὶ πρῶτοι τῆς ἀνοίας ἀπέτισαν τοὺς μισθοὺς οἱ καταστήσαντες.", "st": "4.35"}, {"sp": "N", "t": "ὁ δὲ Μαχατᾶς, πυθόμενος τὰ γεγονότα περὶ τοὺς Λακεδαιμονίους, ἧκε πάλιν ὑποστρέψας εἰς τὴν Σπάρτην, καὶ παρεκάλει τοὺς ἐφόρους καὶ τοὺς βασιλέας ἐξανεγκεῖν τοῖς Ἀχαιοῖς τὸν πόλεμον· μόνως γὰρ οὕτως ἔφη λῆξαι τὴν τῶν Λακεδαιμονίων φιλονεικίαν τῶν ἐκ παντὸς τρόπου διακοπτόντων τὴν πρὸς Αἰτωλοὺς συμμαχίαν τήν τε τῶν ἐν Αἰτωλίᾳ τὰ παραπλήσια τούτοις πραττόντων. πεισθέντων δὲ τῶν ἐφόρων καὶ τῶν βασιλέων, ὁ μὲν Μαχατᾶς ἐπανῆλθε, συντετελεσμένος τὴν πρόθεσιν διὰ τὴν ἄγνοιαν τῶν συμπραττόντων, ὁ δὲ Λυκοῦργος ἀναλαβὼν τοὺς στρατιώτας καί τινας τῶν πολιτικῶν ἐνέβαλεν εἰς τὴν Ἀργείαν, ἀφυλάκτως διακειμένων εἰς τέλος τῶν Ἀργείων διὰ τὴν προϋπάρχουσαν κατάστασιν. καὶ Πολίχναν μὲν καὶ Πρασίας καὶ Λεύκας καὶ Κύφαντα προσπεσὼν ἄφνω κατέσχε· Γλυμπέσι δὲ καὶ Ζάρακι προσπεσὼν ἀπέπεσε. τούτου δὲ ταῦτα πράξαντος, ἐπεκήρυξαν τὸ λάφυρον οἱ Λακεδαιμόνιοι κατὰ τῶν Ἀχαιῶν. ἔπεισαν δὲ καὶ τοὺς Ἠλείους οἱ περὶ τὸν Μαχατᾶν, παραπλήσια λέγοντες ἅπερ καὶ πρὸς τοὺς Λακεδαιμονίους, ἐξενεγκεῖν τοῖς Ἀχαιοῖς τὸν πόλεμον. παραδόξως δὲ καὶ κατὰ νοῦν τοῖς Αἰτωλοῖς τῶν πραγμάτων προκεχωρηκότων, οὗτοι μὲν εὐθαρσῶς ἐνέβαινον εἰς τὸν πόλεμον, οἱ δ’ Ἀχαιοὶ τἀναντία· Φίλιππος μὲν γάρ, ἐφ’ ᾧ τὰς ἐλπίδας εἶχον, ἀκμὴν ἐγίνετο περὶ παρασκευήν, Ἠπειρῶται δ’ ἔμελλον πολεμεῖν, Μεσσήνιοι δ’ ἡσυχίαν εἶχον, Αἰτωλοὶ δέ, προσειληφότες τὴν Ἠλείων καὶ Λακεδαιμονίων ἄγνοιαν, πανταχόθεν περιεῖχον αὐτοὺς τῷ πολέμῳ.", "st": "4.36"}, {"sp": "N", "t": "Ἀράτῳ μὲν οὖν συνέβαινε κατὰ τὸν καιρὸν τοῦτον ἤδη λήγειν τὴν ἀρχήν, Ἄρατον δὲ τὸν υἱὸν αὐτοῦ καθεσταμένον ὑπὸ τῶν Ἀχαιῶν παραλαμβάνειν τὴν στρατηγίαν. Αἰτωλῶν δ’ ἐστρατήγει Σκόπας· ὁ δὲ χρόνος αὐτῷ τῆς ἀρχῆς μάλιστα τότε πως διῄρητο· τὰς γὰρ ἀρχαιρεσίας Αἰτωλοὶ μὲν ἐποίουν μετὰ τὴν φθινοπωρινὴν ἰσημερίαν εὐθέως, Ἀχαιοὶ δὲ τότε περὶ τὴν τῆς Πλειάδος ἐπιτολήν. ἤδη δὲ τῆς θερείας ἐνισταμένης, καὶ μετειληφότος Ἀράτου τοῦ νεωτέρου τὴν στρατηγίαν, ἅμα πάντα τὰ πράγματα τὰς ἐπιβολὰς ἐλάμβανε καὶ τὰς ἀρχάς. Ἀννίβας μὲν γὰρ ἐνεχείρει κατὰ τοὺς καιροὺς τούτους Ζάκανθαν πολιορκεῖν, Ῥωμαῖοι δὲ Λεύκιον Αἰμίλιον εἰς τὴν Ἰλλυρίδα μετὰ δυνάμεως ἐξαπέστελλον ἐπὶ Δημήτριον τὸν Φάριον· ὑπὲρ ὧν ἐν τῇ προτέρᾳ βύβλῳ δεδηλώκαμεν. Ἀντίοχος δέ, Πτολεμαΐδα καὶ Τύρον παραδόντος αὐτῷ Θεοδότου, τοῖς κατὰ Κοίλην Συρίαν ἐγχειρεῖν ἐπεβάλλετο· Πτολεμαῖος δὲ περὶ παρασκευὴν ἐγίνετο τοῦ πρὸς Ἀντίοχον πολέμου. Λυκοῦργος δ’ ἀπὸ τῶν ὁμοίων βουλόμενος ἄρχεσθαι Κλεομένει, τὸ τῶν Μεγαλοπολιτῶν Ἀθήναιον ἐπολιόρκει προσεστρατοπεδευκώς. Ἀχαιοὶ δὲ μισθοφόρους ἱππεῖς καὶ πεζοὺς ἥθροιζον εἰς τὸν περιεστῶτα πόλεμον· Φίλιππος δ’ ἐκ Μακεδονίας ἐκίνει μετὰ τῆς δυνάμεως, ἔχων Μακεδόνων φαλαγγίτας μὲν μυρίους, πελταστὰς δὲ πεντακισχιλίους, ἅμα δὲ τούτοις ἱππεῖς ὀκτακοσίους. ταῦτα μὲν οὖν ἅπαντ’ ἦν ἐν τοιαύταις ἐπιβολαῖς καὶ παρασκευαῖς. κατὰ δὲ τοὺς αὐτοὺς καιροὺς ἐξήνεγκαν Ῥόδιοι Βυζαντίοις πόλεμον διά τινας τοιαύτας αἰτίας.", "st": "4.37"}, {"sp": "N", "t": "Βυζάντιοι κατὰ μὲν θάλατταν εὐκαιρότατον οἰκοῦσι τόπον καὶ πρὸς ἀσφάλειαν καὶ πρὸς εὐδαιμονίαν πάντη τῶν ἐν τῇ καθ’ ἡμᾶς οἰκουμένῃ, κατὰ δὲ γῆν πρὸς ἀμφότερα πάντων ἀφυέστατον. κατὰ μὲν γὰρ θάλατταν οὕτως ἐπίκεινται τῷ στόματι τοῦ Πόντου κυρίως ὥστε μήτ’ εἰσπλεῦσαι μήτ’ ἐκπλεῦσαι μηδένα δυνατὸν εἶναι τῶν ἐμπόρων χωρὶς τῆς ἐκείνων βουλήσεως. ἔχοντος δὲ τοῦ Πόντου πολλὰ τῶν πρὸς τὸν βίον εὐχρήστων τοῖς ἄλλοις ἀνθρώποις, πάντων εἰσὶ τούτων κύριοι Βυζάντιοι. πρὸς μὲν γὰρ τὰς ἀναγκαίας τοῦ βίου χρείας τά τε θρέμματα καὶ τὸ τῶν εἰς τὰς δουλείας ἀγομένων σωμάτων πλῆθος οἱ κατὰ τὸν Πόντον ἡμῖν τόποι παρασκευάζουσι δαψιλέστατον καὶ χρησιμώτατον ὁμολογουμένως· πρὸς δὲ περιουσίαν μέλι, κηρόν, τάριχος ἀφθόνως ἡμῖν χορηγοῦσι. δέχονται γε μὴν τῶν ἐν τοῖς παρ’ ἡμῖν τόποις περιττευόντων ἔλαιον καὶ πᾶν οἴνου γένος· σίτῳ δ’ ἀμείβονται, ποτὲ μὲν εὐκαίρως διδόντες, ποτὲ δὲ λαμβάνοντες. πάντων δὴ τούτων ἢ κωλύεσθαι δέον ἦν ὁλοσχερῶς τοὺς Ἕλληνας ἢ τελέως ἀλυσιτελῆ γίνεσθαι σφίσι τὴν ἀλλαγὴν αὐτῶν, Βυζαντίων ἤτοι βουλομένων ἐθελοκακεῖν καὶ συνδυάζειν ποτὲ μὲν Γαλάταις, τοτὲ δὲ πλείονα Θρᾳξὶν ἢ τὸ παράπαν μὴ κατοικούντων τοὺς τόπους· διά τε γὰρ τὴν στενότητα τοῦ πόρου καὶ τὸ παρακείμενον πλῆθος τῶν βαρβάρων ἄπλους ἂν ἡμῖν ἦν ὁμολογουμένως ὁ Πόντος. μέγιστα μὲν οὖν ἴσως αὐτοῖς ἐκείνοις περιγίνεται λυσιτελῆ πρὸς τοὺς βίους διὰ τὰς τῶν τόπων ἰδιότητας· ἅπαν γὰρ τὸ μὲν περιττεῦον παρ’ αὐτοῖς ἐξαγωγῆς, τὸ δὲ λεῖπον εἰσαγωγῆς ἑτοίμου τυγχάνει καὶ λυσιτελοῦς ἄνευ πάσης κακοπαθείας καὶ κινδύνου· πολλά γε μὴν καὶ τοῖς ἄλλοις εὔχρηστα δι’ ἐκείνους, ὡς εἰρήκαμεν, ἀπαντᾷ. διὸ καὶ κοινοί τινες ὡς εὐεργέται πάντων ὑπάρχοντες εἰκότως ἂν οὐ μόνον χάριτος, ἀλλὰ καὶ ἐπικουρίας κοινῆς τυγχάνοιεν ὑπὸ τῶν Ἑλλήνων κατὰ τὰς ὑπὸ τῶν βαρβάρων περιστάσεις. ἐπεὶ δὲ παρὰ τοῖς πλείστοις ἀγνοεῖσθαι συνέβαινε τὴν ἰδιότητα καὶ τὴν εὐφυΐαν τοῦ τόπου, διὰ τὸ μικρὸν ἔξω κεῖσθαι τῶν ἐπισκοπουμένων μερῶν τῆς οἰκουμένης, βουλόμεθα δὲ πάντες εἰδέναι τὰ τοιαῦτα, καὶ μάλιστα μὲν αὐτόπται γίνεσθαι τῶν ἐχόντων παρηλλαγμένον τι καὶ διαφέρον τόπων, εἰ δὲ μὴ τοῦτο δυνατόν, ἐννοίας γε καὶ τύπους ἔχειν ἐν αὑτοῖς ὡς ἔγγιστα τῆς ἀληθείας, ῥητέον ἂν εἴη τί τὸ συμβαῖνόν ἐστι καὶ τί τὸ ποιοῦν τὴν τηλικαύτην καὶ τοιαύτην εὐπορίαν τῆς προειρημένης πόλεως.", "st": "4.38"}, {"sp": "N", "t": "ὁ δὴ καλούμενος Πόντος ἔχει τὴν μὲν περίμετρον ἔγγιστα τῶν δισμυρίων καὶ δισχιλίων σταδίων, στόματα δὲ διττὰ κατὰ διάμετρον ἀλλήλοις κείμενα, τὸ μὲν ἐκ τῆς Προποντίδος, τὸ δ’ ἐκ τῆς Μαιώτιδος λίμνης, ἥτις αὐτὴ καθ’ αὑτὴν ὀκτακισχιλίων ἔχει σταδίων τὴν περιγραφήν. εἰς δὲ τὰ προειρημένα κοιλώματα πολλῶν μὲν καὶ μεγάλων ποταμῶν ἐκ τῆς Ἀσίας ἐκβαλλόντων, ἔτι δὲ μειζόνων καὶ πλειόνων ἐκ τῆς Εὐρώπης, συμβαίνει τὴν μὲν Μαιῶτιν ἀναπληρουμένην ὑπὸ τούτων ῥεῖν εἰς τὸν Πόντον διὰ τοῦ στόματος, τὸν δὲ Πόντον εἰς τὴν Προποντίδα. καλεῖται δὲ τὸ μὲν τῆς Μαιώτιδος στόμα Κιμμερικὸς Βόσπορος, ὃ τὸ μὲν πλάτος ἔχει περὶ τριάκοντα στάδια, τὸ δὲ μῆκος ἑξήκοντα, πᾶν δ’ ἐστὶν ἁλιτενές· τὸ δὲ τοῦ Πόντου παραπλησίως ὀνομάζεται μὲν Βόσπορος Θρᾴκιος, ἔστι δὲ τὸ μὲν μῆκος ἐφ’ ἑκατὸν καὶ εἴκοσι στάδια, τὸ δὲ πλάτος οὐ πάντη ταὐτόν. ἄρχει δὲ τοῦ στόματος ἀπὸ μὲν τῆς Προποντίδος τὸ κατὰ Καλχηδόνα διάστημα καὶ Βυζάντιον, ὃ δεκατεττάρων ἐστὶ σταδίων, ἀπὸ δὲ τοῦ Πόντου τὸ καλούμενον Ἱερόν, ἐφ’ οὗ τόπου φασὶ κατὰ τὴν ἐκ Κόλχων ἀνακομιδὴν Ἰάσονα θῦσαι πρῶτον τοῖς δώδεκα θεοῖς· ὃ κεῖται μὲν ἐπὶ τῆς Ἀσίας, ἀπέχει δὲ τῆς Εὐρώπης ἐπὶ δώδεκα στάδια πρὸς τὸ καταντικρὺ κείμενον Σαραπιεῖον τῆς Θρᾴκης. τοῦ δὲ ῥεῖν ἔξω κατὰ τὸ συνεχὲς τήν τε Μαιῶτιν καὶ τὸν Πόντον εἰσὶν αἰτίαι διτταί, μία μὲν αὐτόθεν καὶ πᾶσι προφανής, καθ’ ἥν, πολλῶν εἰσπιπτόντων ῥευμάτων εἰς περιγραφὴν ἀγγείων ὡρισμένων, πλεῖον ἀεὶ καὶ πλεῖον γίνεται τὸ ὑγρόν, ὃ μηδεμιᾶς μὲν ὑπαρχούσης ἐκρύσεως δέον ἂν ἦν προσαναβαῖνον ἀεὶ μείζω καὶ πλείω τοῦ κοιλώματος περιλαμβάνειν τόπον, ὑπαρχουσῶν δ’ ἐκρύσεων ἀνάγκη τὸ προσγινόμενον καὶ πλεονάζον ὑπερπῖπτον ἀπορρεῖν καὶ φέρεσθαι συνεχῶς διὰ τῶν ὑπαρχόντων στομάτων· δευτέρα δέ, καθ’ ἥν, πολὺν καὶ παντοδαπὸν χοῦν εἰσφερόντων εἰς τὰ προειρημένα κοιλώματα τῶν ποταμῶν κατὰ τὰς τῶν ὄμβρων ἐπιτάσεις, ἐκπιεζόμενον τὸ ὑγρὸν ὑπὸ τῶν συνισταμένων ἐγχωμάτων ἀεὶ προσαναβαίνει καὶ φέρεται κατὰ τὸν αὐτὸν λόγον διὰ τῶν ὑπαρχουσῶν ἐκρύσεων. τῆς δ’ ἐγχώσεως καὶ τῆς ἐπιρρύσεως ἀδιαπαύστου καὶ συνεχοῦς γινομένης ἐκ τῶν ποταμῶν, καὶ τὴν ἀπόρρυσιν ἀδιάπαυστον καὶ συνεχῆ γίνεσθαι διὰ τῶν στομάτων ἀναγκαῖον. αἱ μὲν οὖν ἀληθεῖς αἰτίαι τοῦ ῥεῖν ἔξω τὸν Πόντον αἵδ’ εἰσίν, οὐκ ἐξ ἐμπορικῶν ἔχουσαι διηγημάτων τὴν πίστιν, ἀλλ’ ἐκ τῆς κατὰ φύσιν θεωρίας, ἧς ἀκριβεστέραν εὑρεῖν οὐ ῥᾴδιον·", "st": "4.39"}, {"sp": "N", "t": "ἐπεὶ δ’ ἐπὶ τὸν τόπον ἐπέστημεν, οὐδὲν ἀφετέον ἀργὸν οὐδ’ ἐν αὐτῇ τῇ φάσει κείμενον, ὅπερ οἱ πλεῖστοι ποιεῖν εἰώθασι τῶν συγγραφέων, ἀποδεικτικῇ δὲ μᾶλλον τῇ διηγήσει χρηστέον, ἵνα μηδὲν ἄπορον ἀπολείπωμεν τῶν ζητουμένων τοῖς φιληκόοις. τοῦτο γὰρ ἴδιόν ἐστι τῶν νῦν καιρῶν, ἐν οἷς πάντων πλωτῶν καὶ πορευτῶν γεγονότων οὐκ ἂν ἔτι πρέπον εἴη ποιηταῖς καὶ μυθογράφοις χρῆσθαι μάρτυσι περὶ τῶν ἀγνοουμένων, ὅπερ οἱ πρὸ ἡμῶν πεποιήκασι περὶ τῶν πλείστων, ἀπίστους ἀμφισβητουμένων παρεχόμενοι βεβαιωτὰς κατὰ τὸν Ἡράκλειτον, πειρατέον δὲ δι’ αὐτῆς τῆς ἱστορίας ἱκανὴν παριστάναι πίστιν τοῖς ἀκούουσι. φαμὲν δὴ χώννυσθαι μὲν καὶ πάλαι καὶ νῦν τὸν Πόντον, χρόνῳ γε μὴν ὁλοσχερῶς ἐγχωσθήσεσθαι τήν τε Μαιῶτιν καὶ τοῦτον, μενούσης γε δὴ τῆς αὐτῆς τάξεως περὶ τοὺς τόπους, καὶ τῶν αἰτίων τῆς ἐγχώσεως ἐνεργούντων κατὰ τὸ συνεχές. ὅταν γὰρ ὁ μὲν χρόνος ἄπειρος ᾖ, τὰ δὲ κοιλώματα πάντη πάντως ὡρισμένα, δῆλον ὡς, κἂν τὸ τυχὸν εἰσφέρηται, πληρωθήσονται τῷ χρόνῳ. κατὰ φύσιν γὰρ τὸ πεπερασμένον ἐν ἀπείρῳ χρόνῳ συνεχῶς γινόμενον ἢ φθειρόμενον, κἂν κατ’ ἐλάχιστον γίνηται — τοῦτο γὰρ νοείσθω νῦν — ἀνάγκη τελειωθῆναι κατὰ τὴν πρόθεσιν. ὅταν δὲ μὴ τὸ τυχόν, ἀλλὰ καὶ λίαν πολύς τις εἰσφέρηται χοῦς, φανερὸν ὡς οὐ ποτέ, ταχέως δὲ συμβήσεται γενέσθαι τὸ νῦν δὴ λεγόμενον ὑφ’ ἡμῶν. ὃ δὴ καὶ φαίνεται γινόμενον. τὴν μὲν οὖν Μαιῶτιν ἤδη κεχῶσθαι συμβαίνει· τὸ γάρ τοι πλεῖστον αὐτῆς μέρος ἐν ἑπτὰ καὶ πέντε ὀργυιαῖς ἐστι· διὸ καὶ πλεῖν αὐτὴν οὐκέτι δύνανται ναυσὶ μεγάλαις χωρὶς καθηγεμόνος. οὖσά τ’ ἐξ ἀρχῆς θάλαττα σύρρους τῷ Πόντῳ, καθάπερ οἱ παλαιοὶ συμφωνοῦσι, νῦν ἐστι λίμνη γλυκεῖα, τῆς μὲν θαλάττης ἐκπεπιεσμένης ὑπὸ τῶν ἐγχωμάτων, τῆς δὲ τῶν ποταμῶν εἰσβολῆς ἐπικρατούσης. ἔσται δὲ καὶ περὶ τὸν Πόντον παραπλήσιον, καὶ γίνεται νῦν· ἀλλ’ οὐ λίαν τοῖς πολλοῖς ἐστι καταφανὲς διὰ τὸ μέγεθος τοῦ κοιλώματος. τοῖς μέντοι γε βραχέα συνεπιστήσασι καὶ νῦν ἐστι δῆλον τὸ γινόμενον.", "st": "4.40"}, {"sp": "N", "t": "τοῦ γὰρ Ἴστρου πλείοσι στόμασιν ἀπὸ τῆς Εὐρώπης εἰς τὸν Πόντον εἰσβάλλοντος, συμβαίνει πρὸς τοῦτον σχεδὸν ἐπὶ χίλια στάδια συνεστάναι ταινίαν ἡμέρας δρόμον ἀπέχουσαν τῆς γῆς [ἥτις νῦν συνέστηκεν] ἐκ τῆς τοῖς στόμασιν εἰσφερομένης ἰλύος· ἐφ’ ἣν ἔτι πελάγιοι τρέχοντες οἱ πλέοντες τὸν Πόντον λανθάνουσιν ἐποκέλλοντες νυκτὸς ἐπὶ τοὺς τόπους. καλοῦσι δ’ αὐτοὺς οἱ ναυτικοὶ Στήθη. τοῦ δὲ μὴ παρ’ αὐτὴν συνίστασθαι τὴν γῆν, ἀλλ’ ἐπὶ τὸ πολὺ προωθεῖσθαι τὸν χοῦν, ταύτην νομιστέον εἶναι τὴν αἰτίαν. ἐφ’ ὅσον μὲν γὰρ αἱ ῥύσεις τῶν ποταμῶν διὰ τὴν βίαν τῆς φορᾶς ἐπικρατοῦσι καὶ διωθοῦνται τὴν θάλατταν, ἐπὶ τοσοῦτο καὶ τὴν γῆν καὶ πάντα τὰ φερόμενα τοῖς ῥεύμασιν ἀνάγκη προωθεῖσθαι καὶ μὴ λαμβάνειν μονὴν μηδὲ στάσιν ἁπλῶς· ὅταν δὲ διὰ τὸ βάθος ἤδη καὶ πλῆθος τῆς θαλάττης ἐκλύηται τὰ ῥεύματα, τότ’ εἰκὸς ἤδη κατὰ φύσιν φερόμενον κάτω μονὴν καὶ στάσιν λαμβάνειν τὸν χοῦν. δι’ ἃ δὴ τῶν μὲν λάβρων καὶ μεγάλων ποταμῶν τὰ μὲν χώματα μακρὰν συνίσταται, τὰ δὲ παρὰ τὴν χέρσον ἐστὶν ἀγχιβαθῆ, τῶν δ’ ἐλαττόνων καὶ πρᾴως ῥεόντων παρ’ αὐτὰς τὰς εἰσβολὰς οἱ θῖνες συνίστανται. μάλιστα δ’ ἔκδηλον γίνεται τοῦτο κατὰ τὰς τῶν ὄμβρων ἐπιφοράς· καὶ γὰρ τὰ τυχόντα τότε τῶν ῥείθρων, ἐπειδὰν ἐπικρατήσωσι τοῦ κύματος κατὰ τὴν εἰσβολήν, προωθοῦσι τὸν χοῦν εἰς θάλατταν ἐπὶ τοσοῦτον ὥστε πρὸς λόγον ἑκάστου γίνεσθαι τὴν ἀπόστασιν τῇ βίᾳ τῶν ἐμπιπτόντων ῥευμάτων. τῷ δὲ μεγέθει τῆς προειρημένης ταινίας καὶ καθόλου τῷ πλήθει τῶν εἰσφερομένων λίθων καὶ ξύλων καὶ γῆς ὑπὸ τῶν ποταμῶν οὐδαμῶς ἀπιστητέον — εὔηθες γάρ — θεωροῦντας ὑπὸ τὴν ὄψιν τὸν τυχόντα χειμάρρουν ἐν βραχεῖ χρόνῳ πολλάκις ἐκχαραδροῦντα μὲν καὶ διακόπτοντα τόπους ἠλιβάτους, φέροντα δὲ πᾶν γένος ὕλης καὶ γῆς καὶ λίθων, ἐπιχώσεις δὲ ποιούμενον τηλικαύτας ὥστ’ ἀλλοιοῦν ἐνίοτε καὶ μηδὲ γινώσκειν ἐν βραχεῖ χρόνῳ τοὺς αὐτοὺς τόπους.", "st": "4.41"}, {"sp": "N", "t": "ἐξ ὧν οὐκ εἰκὸς θαυμάζειν πῶς οἱ τηλικοῦτοι καὶ τοιοῦτοι ποταμοὶ συνεχῶς ῥέοντες ἀπεργάζονταί τι τῶν προειρημένων καὶ τέλος ἐκπληροῦσι τὸν Πόντον. οὐ γὰρ εἰκός, ἀλλ’ ἀναγκαῖον γενέσθαι τοῦτό γε προφαίνεται κατὰ τὸν ὀρθὸν λόγον. σημεῖον δὲ τοῦ μέλλοντος· ὅσῳ γάρ ἐστι νῦν ἡ Μαιῶτις γλυκυτέρα τῆς Ποντικῆς θαλάττης, οὕτως θεωρεῖται διαφέρουσα προφανῶς ἡ Ποντικὴ τῆς καθ’ ἡμᾶς. ἐξ ὧν δῆλον ὡς, ὅταν ὁ χρόνος, ἐν ᾧ πεπληρῶσθαι συμβαίνει τὴν Μαιῶτιν, τοῦτον λάβῃ τὸν λόγον πρὸς τὸν χρόνον, ὃν ἔχει τὸ μέγεθος τοῦ κοιλώματος πρὸς τὸ κοίλωμα, τότε συμβήσεται καὶ τὸν Πόντον τεναγώδη καὶ γλυκὺν καὶ λιμνώδη γενέσθαι παραπλησίως τῇ Μαιώτιδι λίμνῃ. καὶ θᾶττον δὲ τοῦτον ὑποληπτέον. ὅσῳ μείζους καὶ πλείους εἰσὶν αἱ ῥύσεις τῶν εἰς τοῦτον ἐκπιπτόντων ποταμῶν. ταῦτα μὲν οὖν ἡμῖν εἰρήσθω πρὸς τοὺς ἀπίστως διακειμένους, εἰ δὴ χώννυσθαι νῦν καὶ χωσθήσεσθαί ποτε συμβήσεται τὸν Πόντον καὶ λίμνη καὶ τέναγος ἔσται τὸ τηλικοῦτον πέλαγος. ἔτι δὲ μᾶλλον εἰρήσθω καὶ τῆς τῶν πλοϊζομένων ψευδολογίας καὶ τερατείας χάριν, ἵνα μὴ παντὶ τῷ λεγομένῳ προσκεχηνέναι παιδικῶς ἀναγκαζώμεθα διὰ τὴν ἀπειρίαν, ἔχοντες δ’ ἴχνη τῆς ἀληθείας ἐπὶ ποσὸν ἐξ αὐτῶν ἐπικρίνειν δυνώμεθα τὸ λεγόμενον ὑπό τινων ἀληθῶς ἢ τοὐναντίον. ἐπὶ δὲ τὸ συνεχὲς τῆς εὐκαιρίας τῶν Βυζαντίων ἐπάνιμεν.", "st": "4.42"}, {"sp": "N", "t": "τοῦ δὴ στόματος τοῦ τὸν Πόντον καὶ τὴν Προποντίδα συνάπτοντος ὄντος ἑκατὸν εἴκοσι σταδίων τὸ μῆκος, καθάπερ ἀρτίως εἶπον, καὶ τοῦ μὲν Ἱεροῦ τὸ πρὸς τὸν Πόντον πέρας ὁρίζοντος, τοῦ δὲ κατὰ Βυζάντιον διαστήματος τὸ πρὸς τὴν Προποντίδα, μεταξὺ τούτων ἐστὶν Ἑρμαῖον, τῆς Εὐρώπης ἐπὶ προοχῆς τινος ἀκρωτηριαζούσης ἐν τῷ στόματι κείμενον, ὃ τῆς μὲν Ἀσίας ἀπέχει περὶ πέντε στάδια, κατὰ τὸν στενώτατον δὲ τόπον ὑπάρχει τοῦ παντὸς στόματος· ᾗ καὶ Δαρεῖον ζεῦξαί φασι τὸν πόρον, καθ’ ὃν χρόνον ἐποιεῖτο τὴν ἐπὶ Σκύθας διάβασιν. κατὰ μὲν δὴ τὸν ἄλλον τόπον ἀπὸ τοῦ Πόντου παραπλήσιός ἐστιν ἡ φορὰ τοῦ ῥεύματος διὰ τὴν ὁμοιότητα τῶν παρ’ ἑκάτερον τὸ μέρος τῷ στόματι παρηκόντων τόπων· ἐπὰν δ’ εἰς τὸ τῆς Εὐρώπης Ἑρμαῖον, ᾗ στενώτατον ἔφαμεν εἶναι, φερόμενος ἐκ τοῦ Πόντου καὶ συγκλειόμενος ὁ ῥοῦς βίᾳ προσπέσῃ, τότε δὴ τραπεὶς ὥσπερ ἀπὸ πληγῆς ἐμπίπτει τοῖς ἀντιπέρας τῆς Ἀσίας τόποις. ἐκεῖθεν δὲ πάλιν, οἷον ἐξ ὑποστροφῆς, τὴν ἀνταπόδοσιν ποιεῖται πρὸς τὰ περὶ τὰς Ἑστίας ἄκρα καλούμενα τῆς Εὐρώπης. ὅθεν αὖθις ὁρμήσας προσπίπτει πρὸς τὴν Βοῦν καλουμένην, ὅς ἐστι τῆς Ἀσίας τόπος, ἐφ’ ὃν ἐπιστῆναί φασι πρῶτον οἱ μῦθοι τὴν Ἰὼ περαιωθεῖσαν. πλὴν ὅ γε ῥοῦς τὸ τελευταῖον ὁρμήσας ἀπὸ τῆς Βοὸς ἐπ’ αὐτὸ φέρεται τὸ Βυζάντιον, περισχισθεὶς δὲ περὶ τὴν πόλιν βραχὺ μὲν εἰς τὸν κόλπον αὑτοῦ διορίζει τὸν καλούμενον Κέρας, τὸ δὲ πλεῖον πάλιν ἀπονεύει. διευτονεῖν μὲν οὖν οὐκέτι δύναται πρὸς τὴν ἀντιπέρας χώραν, ἐφ’ ἧς ἐστι Καλχηδών· πλεονάκις γὰρ τὴν ἀνταπόδοσιν πεποιημένος, καὶ τοῦ πόρου πλάτος ἔχοντος, ἤδη περὶ τοῦτον τὸν τόπον ἐκλυόμενος ὁ ῥοῦς οὐκέτι βραχείας πρὸς ὀξεῖαν γωνίαν ποιεῖται τὰς ἀνακλάσεις ἐπὶ τὴν περαίαν, ἀλλὰ μᾶλλον πρὸς ἀμβλεῖαν· διόπερ ἀπολιπὼν τὴν τῶν Καλχηδονίων πόλιν φέρεται διὰ πόρου.", "st": "4.43"}, {"sp": "N", "t": "καὶ τὸ ποιοῦν τὴν μὲν τῶν Βυζαντίων πόλιν εὐκαιροτάτην, τὴν δὲ τῶν Καλχηδονίων τἀναντία, τοῦτ’ ἔστι τὸ νῦν ὑφ’ ἡμῶν εἰρημένον, καίπερ ἀπὸ τῆς ὄψεως ὁμοίας ἀμφοτέραις δοκούσης εἶναι τῆς θέσεως πρὸς τὴν εὐκαιρίαν. ἀλλ’ ὅμως εἰς τὴν μὲν βουληθέντα καταπλεῦσ’ οὐ ῥᾴδιον, πρὸς ἣν δέ, κἂν μὴ βούλῃ, φέρει κατ’ ἀνάγκην ὁ ῥοῦς, καθάπερ ἀρτίως εἴπομεν. σημεῖον δὲ τούτου· ἐκ Καλχηδόνος γὰρ οἱ βουλόμενοι διαίρειν εἰς Βυζάντιον οὐ δύνανται πλεῖν κατ’ εὐθεῖαν διὰ τὸν μεταξὺ ῥοῦν, ἀλλὰ παράγουσιν ἐπί τε τὴν Βοῦν καὶ τὴν καλουμένην Χρυσόπολιν, ἣν Ἀθηναῖοι τότε κατασχόντες Ἀλκιβιάδου γνώμῃ παραγωγιάζειν ἐπεβάλοντο πρῶτον τοὺς εἰς Πόντον πλέοντας, τὸ δ’ ἔμπροσθεν ἀφιᾶσι κατὰ ῥοῦν, ᾧ φέρονται κατ’ ἀνάγκην πρὸς τὸ Βυζάντιον. ὅμοια δὲ τούτοις καὶ τὰ κατὰ τὸν ἐπὶ θάτερα πλοῦν ἐστι τῆς Βυζαντίων πόλεως· ἄν τε γὰρ ἀφ’ Ἑλλησπόντου τρέχῃ τις τοῖς νότοις ἄν τ’ ἐπὶ τὸν Ἑλλήσποντον ἐκ τοῦ Πόντου τοῖς ἐτησίοις, παρὰ μὲν τὴν Εὐρώπην ἐκ τῆς Βυζαντίων πόλεως ὀρθός, ἅμα δ’ εὐπαρακόμιστός ἐστιν ὁ πλοῦς ἐπὶ τὰ τῆς Προποντίδος στενὰ κατ’ Ἄβυδον καὶ Σηστόν, κἀκεῖθεν ὡσαύτως πάλιν ἐπὶ τὸ Βυζάντιον, ἀπὸ δὲ Καλχηδόνος παρὰ τὴν Ἀσίαν τἀναντία τούτοις διὰ τὸ κολπώδη τὸν παράπλουν ὑπάρχειν καὶ προτείνειν πολὺ τὴν τῶν Κυζικηνῶν χώραν. ἀφ’ Ἑλλησπόντου γὰρ φερόμενον εἰς Καλχηδόνα χρήσασθαι τῷ παρὰ τὴν Εὐρώπην πλῷ, κἄπειτα συνεγγίζοντα τοῖς κατὰ Βυζάντιον τόποις κάμπτειν καὶ προστρέχειν πρὸς τὴν Καλχηδόνα διὰ τὸν ῥοῦν καὶ τὰ προειρημένα δυσχερές. ὁμοίως δὲ πάλιν ἐκπλέοντα προστρέχειν εὐθέως τῇ Θρᾴκῃ τελέως ἀδύνατον διά τε τὸν μεταξὺ ῥοῦν καὶ διὰ τὸ τοὺς ἀνέμους ἑκατέρους ἀντιπίπτειν πρὸς ἀμφοτέρας τὰς ἐπιβολάς, ἐπειδήπερ εἰσάγει μὲν εἰς τὸν Πόντον νότος, ἐξάγει δὲ βορέας, καὶ τούτοις ἀνάγκη χρῆσθαι πρὸς ἑκάτερον τὸν δρόμον τοῖς ἀνέμοις. τὰ μὲν οὖν τὴν κατὰ θάλατταν εὐκαιρίαν ποιοῦντα Βυζαντίοις ταῦτ’ ἔστι, τὰ δὲ τὴν κατὰ γῆν ἀκαιρίαν τὰ μέλλοντα ῥηθήσεσθαι.", "st": "4.44"}, {"sp": "N", "t": "τῆς γὰρ Θρᾴκης κύκλῳ περιεχούσης αὐτῶν τὴν χώραν οὕτως ὥστ’ ἐκ θαλάττης εἰς θάλατταν καθήκειν, ἀίδιον ἔχουσι πόλεμον καὶ δυσχερῆ πρὸς τούτους. οὔτε γὰρ παρασκευασάμενοι καὶ κρατήσαντες αὐτῶν εἰσάπαξ ἀποτρίψασθαι τὸν πόλεμον οἷοί τ’ εἰσὶ διὰ τὸ πλῆθος καὶ τῶν ὄχλων καὶ τῶν δυναστῶν· ἐὰν τοῦ γὰρ ἑνὸς περιγένωνται, τρεῖς ἐπιβαίνουσιν ἐπὶ τὴν τούτων χώραν ἄλλοι βαρύτεροι δυνάσται. καὶ μὴν οὐδ’ εἴξαντες καὶ συγκαταβάντες εἰς φόρους καὶ συνθήκας οὐδὲν ποιοῦσι πλέον· ἂν γὰρ ἑνὶ πρόωνταί τι, πενταπλασίους δι’ αὐτὸ τοῦτο πολεμίους εὑρίσκουσι. διόπερ ἀιδίῳ συνέχονται καὶ δυσχερεῖ πολέμῳ· τί γὰρ ἐπισφαλέστερον ἀστυγείτονος καὶ βαρβάρου πολέμου; τί δεινότερον; οὐ μὴν ἀλλὰ τούτοις τὸ παράπαν κακοῖς παλαίοντες κατὰ γῆν, χωρὶς τῶν ἄλλων τῶν παρεπομένων τῷ πολέμῳ κακῶν, ὑπομένουσί τινα καὶ τιμωρίαν Ταντάλειον κατὰ τὸν ποιητήν· ἔχοντες γὰρ χώραν γενναιοτάτην, ὅταν διαπονήσωσι ταύτην καὶ γένηται τὸ τῶν καρπῶν πλῆθος τῷ κάλλει διαφέρον, κἄπειτα παραγενηθέντες οἱ βάρβαροι τοὺς μὲν καταφθείρωσι, τοὺς δὲ συναθροίσαντες ἀποφέρωσι, τότε δὴ χωρὶς τῶν ἔργων καὶ τῆς δαπάνης καὶ τὴν καταφθορὰν θεώμενοι διὰ τὸ κάλλος τῶν καρπῶν σχετλιάζουσι καὶ βαρέως φέρουσι τὸ συμβαῖνον. ἀλλ’ ὅμως τὸν μὲν ἀπὸ τῶν Θρᾳκῶν πόλεμον κατὰ τὴν συνήθειαν ἀναφέροντες ἔμενον ἐπὶ τῶν ἐξ ἀρχῆς δικαίων πρὸς τοὺς Ἕλληνας· προσεπιγενομένων δὲ Γαλατῶν αὐτοῖς τῶν περὶ Κομοντόριον εἰς πᾶν ἦλθον περιστάσεως.", "st": "4.45"}, {"sp": "N", "t": "οὗτοι δ’ ἐκίνησαν μὲν ἅμα τοῖς περὶ Βρέννον ἐκ τῆς οἰκείας, διαφυγόντες δὲ τὸν περὶ Δελφοὺς κίνδυνον, καὶ παραγενόμενοι πρὸς τὸν Ἑλλήσποντον, εἰς μὲν τὴν Ἀσίαν οὐκ ἐπεραιώθησαν, αὐτοῦ δὲ κατέμειναν διὰ τὸ φιλοχωρῆσαι τοῖς περὶ τὸ Βυζάντιον τόποις. οἳ καὶ κρατήσαντες τῶν Θρᾳκῶν, καὶ κατασκευασάμενοι βασίλειον τὴν Τύλιν, εἰς ὁλοσχερῆ κίνδυνον ἦγον τοὺς Βυζαντίους. κατὰ μὲν οὖν τὰς ἀρχὰς ἐν ταῖς ἐφόδοις αὐτῶν ταῖς κατὰ Κομοντόριον τὸν πρῶτον βασιλεύσαντα δῶρα διετέλουν οἱ Βυζάντιοι διδόντες ἀνὰ τρισχιλίους καὶ πεντακισχιλίους, ποτὲ δὲ καὶ μυρίους χρυσοῦς, ἐφ’ ᾧ μὴ καταφθείρειν τὴν χώραν αὐτῶν. τέλος δ’ ἠναγκάσθησαν ὀγδοήκοντα τάλαντα συγχωρῆσαι φόρον τελεῖν κατ’ ἐνιαυτὸν ἕως εἰς Καύαρον, ἐφ’ οὗ κατελύθη μὲν ἡ βασιλεία, τὸ δὲ γένος αὐτῶν ἐξεφθάρη πᾶν, ὑπὸ Θρᾳκῶν ἐκ μεταβολῆς ἐπικρατηθέν. ἐν οἷς καιροῖς ὑπὸ τῶν φόρων πιεζούμενοι τὸ μὲν πρῶτον ἐπρέσβευον πρὸς τοὺς Ἕλληνας, δεόμενοι σφίσι βοηθεῖν καὶ συγχορηγεῖν εἰς τοὺς περιεστῶτας καιρούς· τῶν δὲ πλείστων παρολιγωρούντων, ἐνεχείρησαν ἀπαναγκασθέντες παραγωγιάζειν τοὺς εἰς τὸν Πόντον πλέοντας.", "st": "4.46"}, {"sp": "N", "t": "μεγάλης δὲ γενομένης τῆς ἀλυσιτελείας καὶ δυσχρηστίας πᾶσιν ἐκ τοῦ τέλος πράττειν τοὺς Βυζαντίους τῶν ἐξαγομένων ἐκ τοῦ Πόντου, δεινὸν ἡγοῦντο, καὶ πάντες ἐνεκάλουν οἱ πλοϊζόμενοι τοῖς Ῥοδίοις διὰ τὸ δοκεῖν τούτους προεστάναι τῶν κατὰ θάλατταν. ἐξ οὗ συνέβη φῦναι τὸν πόλεμον, ὑπὲρ οὗ νῦν ἡμεῖς ἱστορεῖν μέλλομεν. οἱ γὰρ Ῥόδιοι, συνεξεγερθέντες ἅμα μὲν διὰ τὴν σφετέραν βλάβην, ἅμα δὲ καὶ διὰ τὴν τῶν πέλας ἐλάττωσιν, τὸ μὲν πρῶτον παραλαβόντες τοὺς συμμάχους ἐπρέσβευον πρὸς τοὺς Βυζαντίους, ἀξιοῦντες καταλύσειν αὐτοὺς τὸ παραγώγιον· οὐκ ἐντρεπομένων δὲ τοῖς ὅλοις, ἀλλὰ πεπεισμένων δίκαια λέγειν ἐκ τῆς ἀντικαταστάσεως τῆς γενομένης παρ’ αὐτοῖς τῶν περὶ τὸν Ἑκατόδωρον καὶ Ὀλυμπιόδωρον πρὸς τοὺς τῶν Ῥοδίων πρεσβευτάς — οὗτοι γὰρ τότε προέστησαν τοῦ τῶν Βυζαντίων πολιτεύματος — τότε μὲν ἀπηλλάγησαν οἱ Ῥόδιοι περάναντες οὐδέν, ἐπανελθόντες δὲ τὸν πόλεμον ἐψηφίσαντο τοῖς Βυζαντίοις διὰ τὰς προειρημένας αἰτίας. καὶ παραυτίκα πρεσβευτὰς ἐξαπέστελλον πρὸς Προυσίαν, παρακαλοῦντες καὶ τοῦτον εἰς τὸν πόλεμον· ᾔδεσαν γὰρ τὸν Προυσίαν παρατριβόμενον ἔκ τινων πρὸς τοὺς Βυζαντίους.", "st": "4.47"}, {"sp": "N", "t": "τὸ δὲ παραπλήσιον ἐποίουν καὶ Βυζάντιοι· πρός τε γὰρ Ἄτταλον καὶ πρὸς Ἀχαιὸν ἔπεμπον πρέσβεις, δεόμενοι σφίσι βοηθεῖν. ὁ μὲν οὖν Ἄτταλος ἦν πρόθυμος, εἶχε δὲ βραχεῖαν τότε ῥοπήν, ὡς ἂν ὑπ’ Ἀχαιοῦ συνεληλαμένος εἰς τὴν πατρῴαν ἀρχήν· ὁ δ’ Ἀχαιός, κρατῶν μὲν τῆς ἐπὶ τάδε τοῦ Ταύρου, βασιλέα δὲ προσφάτως αὑτὸν ἀναδεδειχώς, ἐπηγγέλλετο βοηθήσειν. ὑπάρχων δ’ ἐπὶ ταύτης τῆς προαιρέσεως, τοῖς μὲν Βυζαντίοις μεγάλην ἐλπίδα παρεσκεύαζε, τοῖς δὲ Ῥοδίοις καὶ Προυσίᾳ τἀναντία κατάπληξιν. Ἀχαιὸς γὰρ ἦν μὲν Ἀντιόχου συγγενὴς τοῦ παρειληφότος τὴν ἐν Συρίᾳ βασιλείαν, ἐγκρατὴς δ’ ἐγένετο τῆς προειρημένης δυναστείας διά τινας τοιαύτας αἰτίας. Σελεύκου μεταλλάξαντος τὸν βίον, ὃς ἦν Ἀντιόχου τοῦ προειρημένου πατήρ, διαδεξαμένου δὲ τὴν βασιλείαν Σελεύκου πρεσβυτάτου τῶν υἱῶν, ἅμα τούτῳ διὰ τὴν οἰκειότητα συνυπερέβαλε τὸν Ταῦρον, δυσὶ μάλιστά πως ἔτεσι πρότερον τῶν νῦν λεγομένων καιρῶν. Σέλευκος γὰρ ὁ νέος ὡς θᾶττον παρέλαβε τὴν βασιλείαν, πυνθανόμενος Ἄτταλον πᾶσαν ἤδη τὴν ἐπὶ τάδε τοῦ Ταύρου δυναστείαν ὑφ’ αὑτὸν πεποιῆσθαι, παρωρμήθη βοηθεῖν τοῖς σφετέροις πράγμασιν. ὑπερβαλὼν δὲ μεγάλῃ δυνάμει τὸν Ταῦρον, καὶ δολοφονηθεὶς ὑπό τ’ Ἀπατουρίου τοῦ Γαλάτου καὶ Νικάνορος, μετήλλαξε τὸν βίον. Ἀχαιὸς δὲ κατὰ τὴν ἀναγκαιότητα τὸν φόνον αὐτοῦ μετῆλθε παραχρῆμα, τοὺς περὶ τὸν Νικάνορα καὶ τὸν Ἀπατούριον ἀποκτείνας, τῶν τε δυνάμεων καὶ τῶν ὅλων πραγμάτων φρονίμως καὶ μεγαλοψύχως προέστη. τῶν γὰρ καιρῶν παρόντων αὐτῷ, καὶ τῆς τῶν ὄχλων ὁρμῆς συνεργούσης εἰς τὸ διάδημα περιθέσθαι, τοῦτο μὲν οὐ προείλετο ποιῆσαι, τηρῶν δὲ τὴν βασιλείαν Ἀντιόχῳ τῷ νεωτέρῳ τῶν υἱῶν, ἐνεργῶς ἐπιπορευόμενος ἀνεκτᾶτο τὴν ἐπὶ τάδε τοῦ Ταύρου πᾶσαν. τῶν δὲ πραγμάτων αὐτῷ παραδόξως εὐροούντων, ἐπεὶ τὸν μὲν Ἄτταλον εἰς αὐτὸ τὸ Πέργαμον συνέκλεισε, τῶν δὲ λοιπῶν πάντων ἦν ἐγκρατής, ἐπαρθεὶς τοῖς εὐτυχήμασι παρὰ πόδας ἐξώκειλε. καὶ διάδημα περιθέμενος καὶ βασιλέα προσαγορεύσας αὑτὸν βαρύτατος ἦν τότε καὶ φοβερώτατος τῶν ἐπὶ τάδε τοῦ Ταύρου βασιλέων καὶ δυναστῶν· ᾧ καὶ μάλιστα τότε Βυζάντιοι πιστεύσαντες ἀνεδέξαντο τὸν πρὸς τοὺς Ῥοδίους καὶ Προυσίαν πόλεμον.", "st": "4.48"}, {"sp": "N", "t": "ὁ δὲ Προυσίας ἐνεκάλει μὲν πρότερον τοῖς Βυζαντίοις ὅτι ψηφισαμένων τινὰς εἰκόνας αὐτοῦ ταύτας οὐκ ἀνετίθεσαν, ἀλλ’ εἰς ἐπισυρμὸν καὶ λήθην ἄγοιεν, δυσηρέστει δ’ αὐτοῖς καὶ ἐπὶ τῷ πᾶσαν προσενέγκασθαι φιλονεικίαν εἰς τὸ διαλῦσαι τὴν Ἀχαιοῦ πρὸς Ἄτταλον ἔχθραν καὶ τὸν πόλεμον, νομίζων κατὰ πολλοὺς τρόπους ἀλυσιτελῆ τοῖς αὑτοῦ πράγμασιν ὑπάρχειν τὴν ἐκείνων φιλίαν. ἠρέθιζε δ’ αὐτὸν καὶ τὸ δοκεῖν Βυζαντίους πρὸς μὲν Ἄτταλον εἰς τοὺς τῆς Ἀθηνᾶς ἀγῶνας τοὺς συνθύσοντας ἐξαπεσταλκέναι, πρὸς αὐτὸν δ’ εἰς τὰ Σωτήρια μηδένα πεπομφέναι. διόπερ ἐκ πάντων τούτων ὑποικουρουμένης παρ’ αὐτῷ τῆς ὀργῆς, ἄσμενος ἐπελάβετο τῆς τῶν Ῥοδίων προφάσεως, καὶ συγκαταθέμενος τοῖς πρεσβευταῖς ἐκείνους μὲν ᾤετο δεῖν κατὰ θάλατταν πολεμεῖν, αὐτὸς δὲ κατὰ γῆν οὐκ ἐλάττω βλάψειν ἔδοξε τοὺς ὑπεναντίους. ὁ μὲν οὖν Ῥοδίων πρὸς Βυζαντίους πόλεμος διὰ ταῦτα καὶ τοιαύτην ἔλαβε τὴν ἀρχήν.", "st": "4.49"}, {"sp": "N", "t": "οἱ δὲ Βυζάντιοι τὸ μὲν πρῶτον ἐρρωμένως ἐπολέμουν, πεπεισμένοι τὸν μὲν Ἀχαιὸν σφίσι βοηθεῖν, αὐτοὶ δὲ τὸν Τιβοίτην ἐκ τῆς Μακεδονίας ἐπαγαγόντες ἀντιπεριστήσειν τῷ Προυσίᾳ φόβους καὶ κινδύνους, ὃς κατὰ τὴν προειρημένην ὁρμὴν πολεμῶν παρείλετο μὲν αὐτῶν τὸ καλούμενον ἐπὶ τοῦ στόματος Ἱερόν, ὃ Βυζάντιοι μικροῖς ἀνώτερον χρόνοις μεγάλων ὠνησάμενοι χρημάτων ἐσφετερίσαντο διὰ τὴν εὐκαιρίαν τοῦ τόπου, βουλόμενοι μηδεμίαν ἀφορμὴν μηδενὶ καταλιπεῖν μήτε κατὰ τῶν εἰς τὸν Πόντον πλεόντων ἐμπόρων μήτε περὶ τοὺς δούλους καὶ τὰς ἐξ αὐτῆς τῆς θαλάττης ἐργασίας, παρείλετο δὲ καὶ τὴν ἐπὶ τῆς Ἀσίας χώραν, ἣν κατεῖχον Βυζάντιοι τῆς Μυσίας πολλοὺς ἤδη χρόνους. οἱ δὲ Ῥόδιοι πληρώσαντες ναῦς ἕξ, ἅμα δὲ ταύταις παρὰ τῶν συμμάχων προσλαβόντες τέτταρας, καὶ ναύαρχον προχειρισάμενοι Ξενόφαντον, ἔπλεον ἐφ’ Ἑλλησπόντου δέκα ναυσί. καὶ ταῖς μὲν λοιπαῖς ὁρμοῦντες περὶ Σηστὸν ἐκώλυον τοὺς πλέοντας εἰς τὸν Πόντον, μιᾷ δ’ ἐκπλεύσας ὁ ναύαρχος κατεπείραζε τῶν Βυζαντίων, εἴ πως ἤδη μεταμελοῖντο καταπεπληγμένοι τὸν πόλεμον. τῶν δ’ οὐ προσεχόντων ἀπέπλευσε καὶ παραλαβὼν τὰς λοιπὰς ναῦς ἀπῆρε πάσαις εἰς τὴν Ῥόδον. οἱ δὲ Βυζάντιοι πρός τε τὸν Ἀχαιὸν ἔπεμπον, ἀξιοῦντες βοηθεῖν, ἐπί τε τὸν Τιβοίτην ἐξαπέστελλον τοὺς ἄξοντας αὐτὸν ἐκ τῆς Μακεδονίας· ἐδόκει γὰρ οὐχ ἧττον ἡ Βιθυνῶν ἀρχὴ Τιβοίτῃ καθήκειν ἢ Προυσίᾳ διὰ τὸ πατρὸς ἀδελφὸν αὐτὸν ὑπάρχειν τῷ Προυσίᾳ οἱ δὲ Ῥόδιοι θεωροῦντες τὴν τῶν Βυζαντίων ὑπόστασιν, πραγματικῶς διενοήθησαν πρὸς τὸ καθικέσθαι τῆς προθέσεως.", "st": "4.50"}, {"sp": "N", "t": "ὁρῶντες γὰρ τὸ συνέχον τοῖς Βυζαντίοις τῆς ὑπομονῆς τοῦ πολέμου κείμενον ἐν ταῖς κατὰ τὸν Ἀχαιὸν ἐλπίσι, θεωροῦντες δὲ τὸν πατέρα τὸν Ἀχαιοῦ κατεχόμενον ἐν Ἀλεξανδρείᾳ, τὸν δ’ Ἀχαιὸν περὶ πλείστου ποιούμενον τὴν τοῦ πατρὸς σωτηρίαν, ἐπεβάλοντο πρεσβεύειν πρὸς τὸν Πτολεμαῖον καὶ παραιτεῖσθαι τὸν Ἀνδρόμαχον, καὶ πρότερον μὲν ἐκ παρέργου τοῦτο πεποιηκότες, τότε δ’ ἀληθινῶς σπεύδοντες ὑπὲρ τοῦ πράγματος, ἵνα προσενεγκάμενοι πρὸς τὸν Ἀχαιὸν τὴν χάριν ταύτην ὑπόχρεων αὐτὸν ποιήσωνται πρὸς πᾶν τὸ παρακαλούμενον. ὁ δὲ Πτολεμαῖος, παραγενομένων τῶν πρέσβεων, ἐβουλεύετο μὲν παρακατέχειν τὸν Ἀνδρόμαχον, ἐλπίζων αὐτῷ χρήσεσθαι πρὸς καιρόν, διὰ τὸ τά τε πρὸς τὸν Ἀντίοχον ἄκριτα μένειν αὐτῷ, καὶ τὸ τὸν Ἀχαιὸν ἀναδεδειχότα προσφάτως αὑτὸν βασιλέα πραγμάτων εἶναι κύριον ἱκανῶν τινων· ἦν γὰρ Ἀνδρόμαχος Ἀχαιοῦ μὲν πατήρ, ἀδελφὸς δὲ Λαοδίκης τῆς Σελεύκου γυναικός. οὐ μὴν ἀλλὰ προσκλίνων τοῖς Ῥοδίοις ὁ Πτολεμαῖος κατὰ τὴν ὅλην αἵρεσιν, καὶ πάντα σπεύδων χαρίζεσθαι, συνεχώρησε καὶ παρέδωκε τὸν Ἀνδρόμαχον αὐτοῖς ἀποκομίζειν ὡς τὸν υἱόν. οἱ δ’ ἐπιτελεσάμενοι τοῦτο, καὶ προσεπιμετρήσαντες τοῖς περὶ τὸν Ἀχαιὸν τιμάς τινας, παρείλαντο τὴν ὁλοσχερεστάτην ἐλπίδα τῶν Βυζαντίων. συνεκύρησε δέ τι καὶ ἕτερον τοῖς Βυζαντίοις ἄτοπον· ὁ γὰρ Τιβοίτης, καταγόμενος ἐκ τῆς Μακεδονίας, ἔσφηλε τὰς ἐπιβολὰς αὐτῶν, μεταλλάξας τὸν βίον. οὗ συμβάντος οἱ μὲν Βυζάντιοι ταῖς ὁρμαῖς ἀνέπεσον, ὁ δὲ Προυσίας ἐπιρρωσθεὶς ταῖς πρὸς τὸν πόλεμον ἐλπίσιν, ἅμα μὲν αὐτὸς ἀπὸ τῶν κατ’ Ἀσίαν μερῶν ἐπολέμει καὶ προσέκειτο τοῖς πράγμασιν ἐνεργῶς, ἅμα δὲ τοὺς Θρᾷκας μισθωσάμενος οὐκ εἴα τὰς πύλας ἐξιέναι τοὺς Βυζαντίους ἀπὸ τῶν κατὰ τὴν Εὐρώπην μερῶν. οἱ δὲ Βυζάντιοι τῶν σφετέρων ἐλπίδων ἐψευσμένοι, τῷ πολέμῳ πονοῦντες πανταχόθεν, ἐξαγωγὴν περιέβλεπον εὐσχήμονα τῶν πραγμάτων.", "st": "4.51"}, {"sp": "N", "t": "Καυάρου δὲ τοῦ τῶν Γαλατῶν βασιλέως παραγενομένου πρὸς τὸ Βυζάντιον, καὶ σπουδάζοντος διαλῦσαι τὸν πόλεμον καὶ διέχοντος τὰς χεῖρας φιλοτίμως, συνεχώρησαν τοῖς παρακαλουμένοις ὅ τε Προυσίας οἵ τε Βυζάντιοι. πυθόμενοι δ’ οἱ Ῥόδιοι τήν τε τοῦ Καυάρου σπουδὴν καὶ τὴν ἐντροπὴν τοῦ Προυσίου, σπουδάζοντες δὲ καὶ τὴν αὑτῶν πρόθεσιν ἐπὶ τέλος ἀγαγεῖν, πρεσβευτὴν μὲν Ἀριδίκην προεχειρίσαντο πρὸς τοὺς Βυζαντίους, Πολεμοκλῆ δὲ τρεῖς ἔχοντα τριήρεις ὁμοῦ συναπέστειλαν, βουλόμενοι τὸ δὴ λεγόμενον καὶ τὸ δόρυ καὶ τὸ κηρύκειον ἅμα πέμπειν πρὸς τοὺς Βυζαντίους. ἐπιφανέντων δὲ τούτων, ἐγένοντο διαλύσεις ἐπὶ Κώθωνος τοῦ Καλλιγείτονος ἱερομνημονοῦντος ἐν τῷ Βυζαντίῳ, πρὸς μὲν Ῥοδίους ἁπλαῖ, Βυζαντίους μὲν μηδένα πράττειν τὸ διαγώγιον τῶν εἰς τὸν Πόντον πλεόντων, Ῥοδίους δὲ καὶ τοὺς συμμάχους τούτου γενομένου τὴν εἰρήνην ἄγειν πρὸς Βυζαντίους· πρὸς δὲ Προυσίαν τοιαίδε τινές, εἶναι Προυσίᾳ καὶ Βυζαντίοις εἰρήνην καὶ φιλίαν εἰς τὸν ἅπαντα χρόνον, μὴ στρατεύειν δὲ μήτε Βυζαντίους ἐπὶ Προυσίαν τρόπῳ μηδενὶ μήτε Προυσίαν ἐπὶ Βυζαντίους· ἀποδοῦναι δὲ Προυσίαν Βυζαντίοις τάς τε χώρας καὶ τὰ φρούρια καὶ τοὺς λαοὺς καὶ τὰ πολεμικὰ σώματα χωρὶς λύτρων, πρὸς δὲ τούτοις τὰ πλοῖα τὰ κατ’ ἀρχὰς ληφθέντα τοῦ πολέμου καὶ τὰ βέλη τὰ καταληφθέντ’ ἐν τοῖς ἐρύμασιν, ὁμοίως δὲ καὶ τὰ ξύλα καὶ τὴν λιθίαν καὶ τὸν κέραμον τὸν ἐκ τοῦ Ἱεροῦ χωρίου — ὁ γὰρ Προυσίας, ἀγωνιῶν τὴν τοῦ Τιβοίτου κάθοδον, πάντα καθεῖλε τὰ δοκοῦντα τῶν φρουρίων εὐκαίρως πρός τι κεῖσθαι — ἐπαναγκάσαι δὲ Προυσίαν καὶ ὅσα τινὲς τῶν Βιθυνῶν εἶχον ἐκ τῆς Μυσίας χώρας τῆς ὑπὸ Βυζαντίους ταττομένης ἀποδοῦναι τοῖς γεωργοῖς. ὁ μὲν οὖν Ῥοδίοις καὶ Προυσίᾳ πρὸς Βυζαντίους συστὰς πόλεμος τοιαύτας ἔλαβε τὰς ἀρχὰς καὶ τὸ τέλος·", "st": "4.52"}, {"sp": "N", "t": "κατὰ δὲ τὸν καιρὸν τοῦτον Κνώσιοι πρεσβεύσαντες πρὸς Ῥοδίους ἔπεισαν τάς τε μετὰ Πολεμοκλέους ναῦς καὶ τρία τῶν ἀφράκτων προσκατασπάσαντας αὑτοῖς ἀποστεῖλαι. γενομένου δὲ τούτου, καὶ τῶν πλοίων ἀφικομένων εἰς τὴν Κρήτην, καὶ σχόντων ὑποψίαν τῶν Ἐλευθερναίων ὅτι τὸν πολίτην αὑτῶν Τίμαρχον οἱ περὶ τὸν Πολεμοκλῆ χαριζόμενοι τοῖς Κνωσίοις ἀνῃρήκασι, τὸ μὲν πρῶτον ῥύσια κατήγγειλαν τοῖς Ῥοδίοις, μετὰ δὲ ταῦτα πόλεμον ἐξήνεγκαν. περιέπεσον δὲ καὶ Λύττιοι βραχὺ πρὸ τούτων τῶν καιρῶν ἀνηκέστῳ συμφορᾷ. καθόλου γὰρ τὰ κατὰ τὴν σύμπασαν Κρήτην ὑπῆρχεν ἐν τοιαύτῃ τινὶ τότε καταστάσει. Κνώσιοι συμφρονήσαντες Γορτυνίοις πᾶσαν ἐποιήσαντο τὴν Κρήτην ὑφ’ αὑτοὺς πλὴν τῆς Λυττίων πόλεως· μόνης δὲ ταύτης ἀπειθούσης, ἐπεβάλοντο πολεμεῖν, σπεύδοντες αὐτὴν εἰς τέλος ἀνάστατον ποιῆσαι καὶ παραδείγματος καὶ φόβου χάριν τῶν ἄλλων Κρηταιέων. τὸ μὲν οὖν πρῶτον ἐπολέμουν πάντες οἱ Κρηταιεῖς τοῖς Λυττίοις· ἐγγενομένης δὲ φιλοτιμίας ἐκ τῶν τυχόντων, ὅπερ ἔθος ἐστὶ Κρησίν, ἐστασίασαν πρὸς τοὺς ἄλλους. καὶ Πολυρρήνιοι μὲν καὶ Κεραῗται καὶ Λαππαῖοι, πρὸς δὲ τούτοις Ὅριοι μετ’ Ἀρκάδων, ὁμοθυμαδὸν ἀποστάντες τῆς τῶν Κνωσίων φιλίας, ἔγνωσαν τοῖς Λυττίοις συμμαχεῖν, τῶν δὲ Γορτυνίων οἱ μὲν πρεσβύτεροι τὰ τῶν Κνωσίων, οἱ δὲ νεώτεροι τὰ τῶν Λυττίων αἱρούμενοι, διεστασίασαν πρὸς ἀλλήλους. οἱ δὲ Κνώσιοι, παραδόξου γεγονότος αὐτοῖς τοῦ περὶ τοὺς συμμάχους κινήματος, ἐπισπῶνται χιλίους ἐξ Αἰτωλίας ἄνδρας κατὰ συμμαχίαν. οὗ γενομένου παραυτίκα τῶν Γορτυνίων οἱ πρεσβύτεροι καταλαμβανόμενοι τὴν ἄκραν εἰσάγονται τούς τε Κνωσίους καὶ τοὺς Αἰτωλούς· καὶ τοὺς μὲν ἐξέβαλον, τοὺς δ’ ἀπέκτειναν τῶν νέων, τὴν δὲ πόλιν ἐνεχείρισαν τοῖς Κνωσίοις.", "st": "4.53"}, {"sp": "N", "t": "κατὰ δὲ τοὺς αὐτοὺς καιροὺς Λυττίων ἐξωδευκότων εἰς τὴν πολεμίαν πανδημεί, συννοήσαντες οἱ Κνώσιοι τὸ γεγονὸς καταλαμβάνονται τὴν Λύττον, ἔρημον οὖσαν τῶν βοηθησόντων· καὶ τὰ μὲν τέκνα καὶ τὰς γυναῖκας εἰς Κνωσὸν ἀπέπεμψαν, τὴν δὲ πόλιν ἐμπρήσαντες καὶ κατασκάψαντες καὶ λωβησάμενοι κατὰ πάντα τρόπον ἐπανῆλθον. οἱ δὲ Λύττιοι παραγενόμενοι πρὸς τὴν πόλιν ἀπὸ τῆς ἐξοδείας, καὶ συνθεασάμενοι τὸ συμβεβηκός, οὕτως περιπαθεῖς ἐγένοντο ταῖς ψυχαῖς ὥστε μηδ’ εἰσελθεῖν μηδένα τολμῆσαι τῶν παρόντων εἰς τὴν πατρίδα· πάντες δὲ περιπορευθέντες αὐτὴν κύκλῳ, καὶ πολλάκις ἀνοιμώξαντες καὶ κατολοφυράμενοι τήν τε τῆς πατρίδος καὶ τὴν αὑτῶν τύχην, αὖθις ἐξ ἀναστροφῆς ἐπανῆλθον εἰς τὴν τῶν Λαππαίων πόλιν. φιλανθρώπως δ’ αὐτοὺς καὶ μετὰ πάσης προθυμίας τῶν Λαππαίων ὑποδεξαμένων, οὗτοι μὲν ἀντὶ πολιτῶν ἀπόλιδες ἐν ἡμέρᾳ μιᾷ καὶ ξένοι γεγονότες ἐπολέμουν πρὸς τοὺς Κνωσίους ἅμα τοῖς συμμάχοις. Λύττος δ’ ἡ Λακεδαιμονίων μὲν ἄποικος οὖσα καὶ συγγενής, ἀρχαιοτάτη δὲ τῶν κατὰ Κρήτην πόλεων, ἄνδρας δ’ ὁμολογουμένως ἀρίστους ἀεὶ τρέφουσα Κρηταιέων, οὕτως ἄρδην καὶ παραλόγως ἀνηρπάσθη.", "st": "4.53"}, {"sp": "N", "t": "Πολυρρήνιοι δὲ καὶ Λαππαῖοι καὶ πάντες οἱ τούτων σύμμαχοι, θεωροῦντες τοὺς Κνωσίους ἀντεχομένους τῆς τῶν Αἰτωλῶν συμμαχίας, τοὺς δ’ Αἰτωλοὺς ὁρῶντες πολεμίους ὄντας τῷ τε βασιλεῖ Φιλίππῳ καὶ τοῖς Ἀχαιοῖς, πέμπουσι πρέσβεις πρός τε τὸν βασιλέα καὶ τοὺς Ἀχαιοὺς περὶ βοηθείας καὶ συμμαχίας. οἱ δ’ Ἀχαιοὶ καὶ Φίλιππος εἴς τε τὴν κοινὴν συμμαχίαν αὐτοὺς προσεδέξαντο καὶ βοήθειαν ἐξαπέστειλαν, Ἰλλυριοὺς μὲν τετρακοσίους, ὧν ἡγεῖτο Πλάτωρ, Ἀχαιοὺς δὲ διακοσίους, Φωκέας ἑκατόν. οἳ καὶ παραγενόμενοι μετ’ οὐ πολὺ πάλιν ἀπέπλευσαν μεγάλην ποιήσαντες ἐπίδοσιν τοῖς Πολυρρηνίοις καὶ τοῖς τούτων συμμάχοις· πάνυ γὰρ ἐν βραχεῖ χρόνῳ τειχήρεις καταστήσαντες τούς τ’ Ἐλευθερναίους καὶ Κυδωνιάτας, ἔτι δὲ τοὺς Ἀπτεραίους, ἠνάγκασαν ἀποστάντας τῆς τῶν Κνωσίων συμμαχίας κοινωνῆσαι σφίσι τῶν αὐτῶν ἐλπίδων. τούτων δὲ γενομένων, ἐξαπέστειλαν Πολυρρήνιοι μὲν καὶ μετὰ τούτων οἱ σύμμαχοι Φιλίππῳ καὶ τοῖς Ἀχαιοῖς πεντακοσίους Κρῆτας, Κνώσιοι δὲ μικρῷ πρότερον ἐξαπεστάλκεισαν χιλίους τοῖς Αἰτωλοῖς. οἳ καὶ συνεπολέμουν ἀμφοτέροις τὸν ἐνεστῶτα πόλεμον. κατελάβοντο δὲ καὶ τὸν λιμένα τῶν Φαιστίων οἱ τῶν Γορτυνίων φυγάδες· ὁμοίως δὲ καὶ τὸν αὐτῶν τῶν Γορτυνίων παραβόλως διακατεῖχον, καὶ προσεπολέμουν ἐκ τούτων ὁρμώμενοι τῶν τόπων τοῖς ἐν τῇ πόλει.", "st": "4.55"}, {"sp": "N", "t": "τὰ μὲν οὖν κατὰ τὴν Κρήτην ἐν τούτοις ἦν· περὶ δὲ τοὺς καιροὺς τούτους καὶ Μιθριδάτης ἐξήνεγκε Σινωπεῦσι πόλεμον, καί τις οἷον ἀρχὴ τότε καὶ πρόφασις ἐγένετο τῆς ἐπὶ τὸ τέλος ἀχθείσης ἀτυχίας Σινωπεῦσιν. εἰς δὲ τὸν πόλεμον τοῦτον πρεσβευσάντων αὐτῶν πρὸς Ῥοδίους καὶ παρακαλούντων βοηθεῖν, ἔδοξε τοῖς Ῥοδίοις προχειρίσασθαι τρεῖς ἄνδρας, καὶ δοῦναι τούτοις δραχμῶν δεκατέτταρας μυριάδας, τοὺς δὲ λαβόντας παρασκευάσαι τὰ πρὸς τὴν χρείαν ἐπιτήδεια τοῖς Σινωπεῦσιν. οἱ δὲ κατασταθέντες ἡτοίμασαν οἴνου κεράμια μύρια, τριχὸς εἰργασμένης τάλαντα τριακόσια, νεύρων εἰργασμένων ἑκατὸν τάλαντα, πανοπλίας χιλίας, χρυσοῦς ἐπισήμους τρισχιλίους, ἔτι δὲ λιθοφόρους τέτταρας καὶ τοὺς ἀφέτας τούτοις. ἃ καὶ λαβόντες οἱ τῶν Σινωπέων πρέσβεις ἐπανῆλθον. ἦσαν γὰρ οἱ Σινωπεῖς ἐν ἀγωνίᾳ μὴ πολιορκεῖν σφᾶς ὁ Μιθριδάτης ἐγχειρήσῃ καὶ κατὰ γῆν καὶ κατὰ θάλατταν· διὸ καὶ τὰς παρασκευὰς πρὸς τοῦτο τὸ μέρος ἐποιοῦντο πάσας. ἡ δὲ Σινώπη κεῖται μὲν ἐν τοῖς δεξιοῖς μέρεσι τοῦ Πόντου παρὰ τὸν εἰς Φᾶσιν πλοῦν, οἰκεῖται δ’ ἐπί τινος χερρονήσου προτεινούσης εἰς τὸ πέλαγος, ἧς τὸν μὲν αὐχένα τὸν συνάπτοντα πρὸς τὴν Ἀσίαν, ὅς ἐστιν οὐ πλεῖον δυεῖν σταδίων, ἡ πόλις ἐπικειμένη διακλείει κυρίως· τὸ δὲ λοιπὸν τῆς χερρονήσου πρόκειται μὲν εἰς τὸ πέλαγος, ἔστι δ’ ἐπίπεδον καὶ πανευέφοδον ἐπὶ τὴν πόλιν, κύκλῳ δ’ ἐκ θαλάττης ἀπότομον καὶ δυσπροσόρμιστον καὶ παντελῶς ὀλίγας ἔχον προσβάσεις. διόπερ ἀγωνιῶντες οἱ Σινωπεῖς μήποτε κατὰ τὴν ἀπὸ τῆς Ἀσίας πλευρὰν ὁ Μιθριδάτης συστησάμενος ἔργα, καὶ κατὰ τὴν ἀπέναντι ταύτης ὁμοίως ποιησάμενος ἀπόβασιν κατὰ θάλατταν εἰς τοὺς ὁμαλοὺς καὶ τοὺς ὑπερκειμένους τῆς πόλεως τόπους, ἐγχειρήσῃ πολιορκεῖν αὐτούς, ἐπεβάλοντο τῆς χερρονήσου κύκλῳ τὸ νησίζον ὀχυροῦν, ἀποσταυροῦντες καὶ περιχαρακοῦντες τὰς ἐκ θαλάττης προσβάσεις, ἅμα δὲ καὶ βέλη καὶ στρατιώτας τιθέντες ἐπὶ τοὺς εὐκαίρους τῶν τόπων· ἔστι γὰρ τὸ πᾶν μέγεθος αὐτῆς οὐ πολύ, τελέως δ’ εὐκατακράτητον καὶ μέτριον.", "st": "4.56"}, {"sp": "N", "t": "καὶ τὰ μὲν περὶ Σινώπης ἐν τούτοις ἦν. ὁ δὲ βασιλεὺς Φίλιππος, ἀναζεύξας ἐκ Μακεδονίας μετὰ τῆς δυνάμεως — ἐν γὰρ ταύταις ταῖς ἐπιβολαῖς ἀπελίπαμεν ἄρτι τὸν συμμαχικὸν πόλεμον — ὥρμησεν ἐπὶ Θετταλίας καὶ τῆς Ἠπείρου, σπεύδων ταύτῃ ποιήσασθαι τὴν εἰσβολὴν τὴν εἰς Αἰτωλίαν. Ἀλέξανδρος δὲ καὶ Δωρίμαχος κατὰ τὸν καιρὸν τοῦτον ἔχοντες πρᾶξιν κατὰ τῆς τῶν Αἰγειρατῶν πόλεως, ἁθροίσαντες τῶν Αἰτωλῶν περὶ χιλίους καὶ διακοσίους εἰς Οἰάνθειαν τῆς Αἰτωλίας, ἣ κεῖται καταντικρὺ τῆς προειρημένης πόλεως, καὶ πορθμεῖα τούτοις ἑτοιμάσαντες, πλοῦν ἐτήρουν πρὸς τὴν ἐπιβολήν. τῶν γὰρ ηὐτομοληκότων τις ἐξ Αἰτωλίας, καὶ πλείω χρόνον διατετριφὼς παρὰ τοῖς Αἰγειράταις, καὶ συντεθεωρηκὼς τοὺς φυλάττοντας τὸν ἀπ’ Αἰγίου πυλῶνα μεθυσκομένους καὶ ῥᾳθύμως διεξάγοντας τὰ κατὰ τὴν φυλακήν, πλεονάκις παραβαλλόμενος καὶ διαβαίνων πρὸς τοὺς περὶ Δωρίμαχον ἐξεκέκλητο πρὸς τὴν πρᾶξιν αὐτούς, ἅτε λίαν οἰκείους ὄντας τῶν τοιούτων ἐγχειρημάτων. ἡ δὲ τῶν Αἰγειρατῶν πόλις ἔκτισται μὲν τῆς Πελοποννήσου κατὰ τὸν Κορινθιακὸν κόλπον μεταξὺ τῆς Αἰγιέων καὶ Σικυωνίων πόλεως, κεῖται δ’ ἐπὶ λόφων ἐρυμνῶν καὶ δυσβάτων, νεύει δὲ τῇ θέσει πρὸς τὸν Παρνασσὸν καὶ ταῦτα τὰ μέρη τῆς ἀντίπερα χώρας, ἀπέχει δὲ τῆς θαλάττης ὡς ἑπτὰ στάδια. παραπεσόντος δὲ πλοῦ τοῖς περὶ τὸν Δωρίμαχον, ἀνήχθησαν καὶ καθορμίζονται νυκτὸς ἔτι πρὸς τὸν παρὰ τὴν πόλιν καταρρέοντα ποταμόν. οἱ μὲν οὖν περὶ τὸν Ἀλέξανδρον καὶ Δωρίμαχον, ἅμα δὲ τούτοις Ἀρχίδαμον τὸν Πανταλέοντος υἱόν, ἔχοντες περὶ αὑτοὺς τὸ πλῆθος τῶν Αἰτωλῶν, προσέβαινον πρὸς τὴν πόλιν κατὰ τὴν ἀπ’ Αἰγίου φέρουσαν ὁδόν. ὁ δ’ αὐτόμολος, ἔχων εἴκοσι τοὺς ἐπιτηδειοτάτους, διανύσας ταῖς ἀνοδίαις τοὺς κρημνοὺς θᾶττον τῶν ἄλλων διὰ τὴν ἐμπειρίαν, καὶ διαδὺς διά τινος ὑδρορροίας, ἔτι κοιμωμένους κατέλαβε τοὺς ἐπὶ τοῦ πυλῶνος. κατασφάξας δ’ αὐτοὺς ἀκμὴν ἐν ταῖς κοίταις ὄντας, καὶ διακόψας τοῖς πελέκεσι τοὺς μοχλούς, ἀνέῳξε τοῖς Αἰτωλοῖς τὰς πύλας. οἱ δὲ παρεισπεσόντες λαμπρῶς ἀπερινοήτως ἐχρήσαντο τοῖς πράγμασιν. ὃ καὶ παραίτιον ἐγένετο τοῖς μὲν Αἰγειράταις τῆς σωτηρίας, τοῖς δ’ Αἰτωλοῖς τῆς ἀπωλείας. ὑπολαμβάνοντες γὰρ τοῦτο τέλος εἶναι τοῦ κατασχεῖν ἀλλοτρίαν πόλιν, τὸ γενέσθαι τῶν πυλώνων ἐντός, τοῦτον τὸν τρόπον ἐχρῶντο τοῖς πράγμασι.", "st": "4.57"}, {"sp": "N", "t": "διὸ καὶ βραχὺν παντελῶς χρόνον ἁθρόοι συμμείναντες περὶ τὴν ἀγοράν, λοιπὸν ἐκπαθεῖς ὄντες πρὸς τὰς ὠφελείας διέρρεον, καὶ παρεισπίπτοντες εἰς τὰς οἰκίας διήρπαζον τοὺς βίους, ἤδη φωτὸς ὄντος. οἱ δ’ Αἰγειρᾶται, τοῦ πράγματος αὐτοῖς ἀνελπίστου καὶ παραδόξου τελέως συμβεβηκότος, οἷς μὲν ἐπέστησαν οἱ πολέμιοι κατὰ τὰς οἰκίας, ἐκπλαγεῖς καὶ περίφοβοι γενόμενοι πάντες ἐτρέποντο πρὸς φυγὴν ἔξω τῆς πόλεως, ὡς ἤδη βεβαίως αὐτῆς κεκρατημένης ὑπὸ τῶν πολεμίων. ὅσοι δὲ τῆς κραυγῆς ἀκούοντες ἐξ ἀκεραίων τῶν οἰκιῶν ἐξεβοήθουν, πάντες εἰς τὴν ἄκραν συνέτρεχον. οὗτοι μὲν οὖν ἀεὶ πλείους ἐγίνοντο καὶ θαρραλεώτεροι, τὸ δὲ τῶν Αἰτωλῶν σύστρεμμα τοὐναντίον ἔλαττον καὶ ταραχωδέστερον διὰ τὰς προειρημένας αἰτίας. οὐ μὴν ἀλλὰ συνορῶντες οἱ περὶ τὸν Δωρίμαχον ἤδη τὸν περιεστῶτα κίνδυνον αὐτούς, συστραφέντες ὥρμησαν ἐπὶ τοὺς κατέχοντας τὴν ἄκραν, ὑπολαμβάνοντες τῇ θρασύτητι καὶ τόλμῃ καταπληξάμενοι τρέψασθαι τοὺς ἡθροισμένους ἐπὶ τὴν βοήθειαν. οἱ δ’ Αἰγειρᾶται παρακαλέσαντες σφᾶς αὐτοὺς ἠμύνοντο καὶ συνεπλέκοντο τοῖς Αἰτωλοῖς γενναίως. οὔσης δὲ τῆς ἄκρας ἀτειχίστου, καὶ τῆς συμπλοκῆς ἐκ χειρὸς καὶ κατ’ ἄνδρα γινομένης, τὸ μὲν πρῶτον ἦν ἀγὼν οἷον εἰκός, ἅτε τῶν μὲν ὑπὲρ πατρίδος καὶ τέκνων, τῶν δ’ ὑπὲρ σωτηρίας ἀγωνιζομένων· τέλος γε μὴν ἐτράπησαν οἱ παρεισπεπτωκότες τῶν Αἰτωλῶν. οἱ δ’ Αἰγειρᾶται, λαβόντες ἀφορμὴν ἐγκλίματος, ἐνεργῶς ἐπέκειντο καὶ καταπληκτικῶς τοῖς πολεμίοις. ἐξ οὗ συνέβη τοὺς πλείστους τῶν Αἰτωλῶν διὰ τὴν πτοίαν αὐτοὺς ὑφ’ αὑτῶν φεύγοντας ἐν ταῖς πύλαις συμπατηθῆναι. ὁ μὲν οὖν Ἀλέξανδρος ἐν χειρῶν νόμῳ κατ’ αὐτὸν ἔπεσε τὸν κίνδυνον, ὁ δ’ Ἀρχίδαμος ἐν τῷ περὶ τὰς πύλας ὠθισμῷ καὶ πνιγμῷ διεφθάρη. τὸ δὲ λοιπὸν πλῆθος τῶν Αἰτωλῶν τὸ μὲν συνεπατήθη, τὸ δὲ κατὰ τῶν κρημνῶν φεῦγον ταῖς ἀνοδίαις ἐξετραχηλίσθη. τὸ δὲ καὶ διασωθὲν αὐτῶν μέρος πρὸς τὰς ναῦς, ἐρριφὸς τὰ ὅπλα παναίσχρως, ἅμα δ’ ἀνελπίστως ἐποιήσατο τὸν ἀπόπλουν. Αἰγειρᾶται μὲν οὖν, διὰ τὴν ὀλιγωρίαν ἀποβαλόντες τὴν πατρίδα, διὰ τὴν εὐψυχίαν καὶ γενναιότητα πάλιν ἔσωσαν παραδόξως.", "st": "4.58"}, {"sp": "N", "t": "κατὰ δὲ τοὺς αὐτοὺς καιροὺς Εὐριπίδας, ὃς ἦν ἀπεσταλμένος ὑπὸ τῶν Αἰτωλῶν στρατηγὸς τοῖς Ἠλείοις, καταδραμὼν τὴν Δυμαίων καὶ Φαραιέων, ἔτι δὲ τὴν τῶν Τριταιέων χώραν, καὶ περιελασάμενος λείας πλῆθος ἱκανόν, ἐποιεῖτο τὴν ἀποχώρησιν ὡς ἐπὶ τὴν Ἠλείαν. ὁ δὲ Μίκκος ὁ Δυμαῖος, ὅσπερ ἐτύγχανε κατ’ ἐκείνους τοὺς καιροὺς ὑποστράτηγος ὢν τῶν Ἀχαιῶν, ἐκβοηθήσας πανδημεὶ τούς τε Δυμαίους καὶ Φαραιεῖς, ἅμα δὲ καὶ Τριταιεῖς ἔχων, προσέκειτο τοῖς πολεμίοις ἀπαλλαττομένοις. ἐνεργότερον δ’ ἐπικείμενος τοῖς φεύγουσιν ἐμπεσὼν εἰς ἐνέδραν ἐσφάλη καὶ πολλοὺς ἀπέβαλε τῶν ἀνδρῶν· τετταράκοντα μὲν γὰρ ἔπεσον, ἑάλωσαν δὲ περὶ διακοσίους τῶν πεζῶν. ὁ μὲν οὖν Εὐριπίδας, ποιήσας τοῦτο τὸ προτέρημα, καὶ μετεωρισθεὶς ἐπὶ τῷ γεγονότι, μετ’ ὀλίγας ἡμέρας αὖτις ἐξελθὼν κατέλαβε παρὰ τὸν Ἄραξον φρούριον τῶν Δυμαίων εὔκαιρον τὸ καλούμενον Τεῖχος· ὅ φασιν οἱ μῦθοι τὸ παλαιὸν Ἡρακλέα πολεμοῦντα τοῖς Ἠλείοις ἐποικοδομῆσαι, βουλόμενον ὁρμητηρίῳ χρῆσθαι τούτῳ κατ’ αὐτῶν.", "st": "4.59"}, {"sp": "N", "t": "οἱ δὲ Δυμαῖοι καὶ Φαραιεῖς καὶ Τριταιεῖς, ἠλαττωμένοι μὲν περὶ τὴν βοήθειαν, δεδιότες δὲ τὸ μέλλον ἐκ τῆς τοῦ φρουρίου καταλήψεως, τὸ μὲν πρῶτον ἔπεμπον ἀγγέλους πρὸς τὸν στρατηγὸν τῶν Ἀχαιῶν, δηλοῦντες τὰ γεγονότα καὶ δεόμενοι σφίσι βοηθεῖν· μετὰ δὲ ταῦτα πρεσβευτὰς ἐξαπέστελλον τοὺς περὶ τῶν αὐτῶν ἀξιώσοντας. ὁ δ’ Ἄρατος οὔτε τὸ ξενικὸν ἐδύνατο συστήσασθαι διὰ τὸ κατὰ τὸν Κλεομενικὸν πόλεμον ἐλλελοιπέναι τινὰ τῶν ὀψωνίων τοὺς Ἀχαιοὺς τοῖς μισθοφόροις, καθόλου τε ταῖς ἐπιβολαῖς καὶ συλλήβδην πᾶσι τοῖς τοῦ πολέμου πράγμασιν ἀτόλμως ἐχρῆτο καὶ νωθρῶς. διόπερ ὅ τε Λυκοῦργος εἷλε τὸ τῶν Μεγαλοπολιτῶν Ἀθήναιον, ὅ τ’ Εὐριπίδας ἑξῆς τοῖς εἰρημένοις Γόρτυναν τῆς Τελφουσίας. οἵ τε Δυμαῖοι καὶ Φαραιεῖς καὶ Τριταιεῖς, δυσελπιστήσαντες ἐπὶ ταῖς τοῦ στρατηγοῦ βοηθείαις, συνεφρόνησαν ἀλλήλοις εἰς τὸ τὰς μὲν κοινὰς εἰσφορὰς τοῖς Ἀχαιοῖς μὴ τελεῖν, ἰδίᾳ δὲ συστήσασθαι μισθοφόρους, πεζοὺς μὲν τριακοσίους, ἱππεῖς δὲ πεντήκοντα, καὶ διὰ τούτων ἀσφαλίζεσθαι τὴν χώραν. τοῦτο δὲ πράξαντες ὑπὲρ μὲν τῶν καθ’ αὑτοὺς πραγμάτων ἐνδεχομένως ἔδοξαν βεβουλεῦσθαι, περὶ δὲ τῶν κοινῶν τἀναντία· πονηρᾶς γὰρ ἐφόδου καὶ προφάσεως τοῖς βουλομένοις διαλύειν τὸ ἔθνος ἐδόκουν ἀρχηγοὶ καὶ καθηγεμόνες γεγονέναι. ταύτης δὲ τῆς πράξεως τὸ μὲν πλεῖστον τῆς αἰτίας ἐπὶ τὸν στρατηγὸν ἄν τις ἀναφέροι δικαίως τὸν ὀλιγωροῦντα καὶ καταμέλλοντα καὶ προϊέμενον ἀεὶ τοὺς δεομένους. πᾶς γὰρ ὁ κινδυνεύων, ἕως μὲν ἄν τινος ἐλπίδος ἀντέχηται παρὰ τῶν οἰκείων καὶ συμμάχων, προσανέχειν φιλεῖ ταύταις· ὅταν δὲ δυσχρηστῶν ἀπογνῷ, τότ’ ἤδη βοηθεῖν ἀναγκάζεθ’ αὑτῷ κατὰ δύναμιν. διὸ καὶ Τριταιεῦσι καὶ Φαραιεῦσι καὶ Δυμαίοις, ὅτι μὲν ἰδίᾳ συνεστήσαντο μισθοφόρους, καταμέλλοντος τοῦ τῶν Ἀχαιῶν ἡγεμόνος, οὐκ ἐγκλητέον· ὅτι δὲ τὰς εἰς τὸ κοινὸν εἰσφορὰς ἀπεῖπαν, μεμψιμοιρητέον. ἐχρῆν γὰρ τὴν μὲν ἰδίαν χρείαν μὴ παραλιπεῖν, εὐκαιροῦντάς γε δὴ καὶ δυναμένους, τὰ δὲ πρὸς τὴν κοινὴν πολιτείαν δίκαια συντηρεῖν, ἄλλως τε δὴ καὶ κομιδῆς ὑπαρχούσης ἀδιαπτώτου κατὰ τοὺς κοινοὺς νόμους, τὸ δὲ μέγιστον, γεγονότας ἀρχηγοὺς τοῦ τῶν Ἀχαιῶν συστήματος.", "st": "4.60"}, {"sp": "N", "t": "τὰ μὲν οὖν κατὰ Πελοπόννησον ἐν τούτοις ἦν. ὁ δὲ βασιλεὺς Φίλιππος διελθὼν τὴν Θετταλίαν παρῆν εἰς Ἤπειρον. ἀναλαβὼν δὲ τοὺς Ἠπειρώτας ἅμα τοῖς Μακεδόσι πανδημεὶ καὶ τοὺς ἐξ Ἀχαΐας αὐτῷ συνηντηκότας σφενδονήτας τριακοσίους, ἔτι δὲ τοὺς παρὰ Πολυρρηνίων ἀπεσταλμένους Κρῆτας πεντακοσίους, προῆγε, καὶ διελθὼν τὴν Ἤπειρον παρῆν εἰς τὴν τῶν Ἀμβρακιωτῶν χώραν. εἰ μὲν οὖν ἐξ ἐφόδου κατὰ τὸ συνεχὲς ἐνέβαλεν εἰς τὴν μεσόγαιαν τὴν Αἰτωλίας, ἄφνω καὶ παραδόξως ἐπιπεσὼν δυνάμει βαρείᾳ τοῖς ὅλοις πράγμασιν ἐπιτεθείκει τέλος· νῦν δὲ πεισθεὶς τοῖς Ἠπειρώταις πρῶτον ἐκπολιορκῆσαι τὸν Ἄμβρακον, ἔδωκε τοῖς Αἰτωλοῖς ἀναστροφὴν εἰς τὸ καὶ στῆναι καὶ προνοηθῆναί τι καὶ παρασκευάσασθαι πρὸς τὸ μέλλον. οἱ γὰρ Ἠπειρῶται, τὸ σφέτερον ἀναγκαιότερον τιθέμενοι τοῦ κοινοῦ τῶν συμμάχων, καὶ μεγάλως σπουδάζοντες ὑφ’ αὑτοὺς ποιήσασθαι τὸν Ἄμβρακον, ἐδέοντο τοῦ Φιλίππου ποιήσασθαι πολιορκίαν περὶ τὸ χωρίον καὶ τοῦτο πρότερον ἐξελεῖν, περὶ πλείστου ποιούμενοι τὸ κομίσασθαι τὴν Ἀμβρακίαν παρὰ τῶν Αἰτωλῶν, τοῦτο δὲ γενέσθαι μόνως ἂν ἐλπίζοντες, εἰ τοῦ προειρημένου τόπου κυριεύσαντες ἐπικαθίσαιεν τῇ πόλει. ὁ γὰρ Ἄμβρακος ἔστι μὲν χωρίον εὖ κατεσκευασμένον καὶ προτειχίσμασι καὶ τείχει, κεῖται δ’ ἐν λίμναις, μίαν ἀπὸ τῆς χώρας στενὴν καὶ χωστὴν ἔχον πρόσοδον, ἐπίκειται δ’ εὐκαίρως τῇ τε χώρᾳ τῶν Ἀμβρακιωτῶν καὶ τῇ πόλει. Φίλιππος μὲν οὖν πεισθεὶς Ἠπειρώταις καὶ καταστρατοπεδεύσας περὶ τὸν Ἄμβρακον, ἐγίνετο περὶ τὴν παρασκευὴν τῶν πρὸς τὴν πολιορκίαν.", "st": "4.61"}, {"sp": "N", "t": "Σκόπας δὲ κατὰ τὸν καιρὸν τοῦτον ἀναλαβὼν τοὺς Αἰτωλοὺς πανδημεί, καὶ ποιησάμενος τὴν πορείαν διὰ Θετταλίας, ἐνέβαλεν εἰς Μακεδονίαν, καὶ τόν τε σῖτον ἐπιπορευόμενος τὸν κατὰ τὴν Πιερίαν ἔφθειρε καὶ λείας περιβαλόμενος πλῆθος ἐπανῆγε, ποιούμενος τὴν πορείαν ὡς ἐπὶ τὸ Δῖον. ἐκλιπόντων δὲ τῶν κατοικούντων τὸν τόπον, εἰσελθὼν τὰ τείχη κατέσκαψε καὶ τὰς οἰκίας καὶ τὸ γυμνάσιον, πρὸς δὲ τούτοις ἐνέπρησε τὰς στοὰς τὰς περὶ τὸ τέμενος καὶ τὰ λοιπὰ διέφθειρε τῶν ἀναθημάτων, ὅσα πρὸς κόσμον ἢ χρείαν ὑπῆρχε τοῖς εἰς τὰς πανηγύρεις συμπορευομένοις· ἀνέτρεψε δὲ καὶ τὰς εἰκόνας τῶν βασιλέων ἁπάσας. οὗτος μὲν οὖν εὐθέως κατὰ τὴν ἔνστασιν τοῦ πολέμου καὶ τὴν πρώτην πρᾶξιν οὐ μόνον τοῖς ἀνθρώποις, ἀλλὰ καὶ τοῖς θεοῖς πόλεμον ἐξενηνοχώς, ἐπανῄει. καὶ παραγενόμενος εἰς Αἰτωλίαν, οὐχ ὡς ἠσεβηκώς, ἀλλ’ ὡς ἀγαθὸς ἀνὴρ εἰς τὰ κοινὰ πράγματα γεγονώς, ἐτιμᾶτο καὶ περιεβλέπετο, πλήρεις ἐλπίδων κενῶν καὶ φρονήματος ἀλόγου πεποιηκὼς τοὺς Αἰτωλούς· ἔσχον γὰρ ἐκ τούτων διάληψιν ὡς τῆς μὲν Αἰτωλίας οὐδ’ ἐγγίζειν τολμήσοντος οὐδενός, αὐτοὶ δὲ πορθήσοντες ἀδεῶς οὐ μόνον τὴν Πελοπόννησον, καθάπερ ἔθος ἦν αὐτοῖς, ἀλλὰ καὶ τὴν Θετταλίαν καὶ τὴν Μακεδονίαν.", "st": "4.62"}, {"sp": "N", "t": "Φίλιππος δὲ τὰ περὶ τὴν Μακεδονίαν ἀκούσας, καὶ παραχρῆμα τῆς Ἠπειρωτῶν ἀγνοίας καὶ φιλονεικίας τἀπίχειρα κεκομισμένος, ἐπολιόρκει τὸν Ἄμβρακον. χρησάμενος δὲ τοῖς τε χώμασιν ἐνεργῶς καὶ τῇ λοιπῇ παρασκευῇ ταχέως κατεπλήξατο τοὺς ἐνόντας, καὶ παρέλαβε τὸ χωρίον ἐν ἡμέραις τετταράκοντα ταῖς πάσαις. ἀφεὶς δὲ τοὺς φυλάττοντας ὑποσπόνδους, ὄντας εἰς πεντακοσίους Αἰτωλῶν, τὴν μὲν τῶν Ἠπειρωτῶν ἐπιθυμίαν ἐπλήρωσε, παραδοὺς τὸν Ἄμβρακον, αὐτὸς δ’ ἀναλαβὼν τὴν δύναμιν προῆγε παρὰ Χαράδραν, σπεύδων διαβῆναι τὸν Ἀμβρακικὸν καλούμενον κόλπον, οὗ στενώτατόν ἐστι, κατὰ τὸ τῶν Ἀκαρνάνων ἱερὸν καλούμενον Ἄκτιον. ὁ γὰρ προειρημένος κόλπος ἐκπίπτει μὲν ἐκ τοῦ Σικελικοῦ πελάγους μεταξὺ τῆς Ἠπείρου καὶ τῆς Ἀκαρνανίας στενῷ παντελῶς στόματι — λείπει γὰρ τῶν πέντε σταδίων — προβαίνων δ’ εἰς τὴν μεσόγαιαν κατὰ μὲν τὸ πλάτος ἐφ’ ἑκατὸν στάδια κεῖται, κατὰ δὲ τὸ μῆκος ἀπὸ τοῦ πελάγους προπίπτει περὶ τριακόσια στάδια· διορίζει δὲ τὴν Ἤπειρον καὶ τὴν Ἀκαρνανίαν, ἔχων τὴν μὲν Ἤπειρον ἀπὸ τῶν ἄρκτων, τὴν δ’ Ἀκαρνανίαν ἀπὸ μεσημβρίας. περαιώσας δὲ κατὰ τὸ προειρημένον στόμα τὴν δύναμιν, καὶ διελθὼν τὴν Ἀκαρνανίαν, ἧκε τῆς Αἰτωλίας πρὸς τὴν καλουμένην πόλιν Φοιτίας, συμπαρειληφὼς Ἀκαρνάνων πεζοὺς δισχιλίους, ἱππεῖς δὲ διακοσίους. περιστρατοπεδεύσας δὲ τὴν προειρημένην πόλιν, καὶ προσβολὰς ἐνεργοὺς καὶ καταπληκτικὰς ἐπὶ δύ’ ἡμέρας ποιησάμενος, παρέλαβε καθ’ ὁμολογίαν, ἀφεὶς ὑποσπόνδους τοὺς ἐνόντας τῶν Αἰτωλῶν. τῆς δ’ ἐπιούσης νυκτός, ὡς ἔτι μενούσης ἀναλώτου τῆς πόλεως, ἧκον βοηθοῦντες πεντακόσιοι τῶν Αἰτωλῶν· ὧν τὴν παρουσίαν προαισθανόμενος ὁ βασιλεύς, καθεὶς ἐπί τινας τόπους εὐκαίρους ἐνέδρας, τοὺς μὲν πλείους αὐτῶν ἀπέκτεινε, τοὺς δὲ λοιποὺς ὑποχειρίους ἔλαβε, πλὴν τελέως ὀλίγων. μετὰ δὲ ταῦτα σιτομετρήσας εἰς τριάκονθ’ ἡμέρας τὴν δύναμιν ἐκ τοῦ περικαταληφθέντος σίτου — πολὺ γὰρ πλῆθος ἐν ταῖς Φοιτίαις εὑρέθη συνηθροισμένον — προῆγε ποιούμενος τὴν πορείαν εἰς τὴν Στρατικήν. ἀποσχὼν δὲ τῆς πόλεως περὶ δέκα στάδια κατεστρατοπέδευσε περὶ τὸν Ἀχελῷον ποταμόν, ὁρμώμενος δ’ ἐντεῦθεν ἀδεῶς ἐπόρθει τὴν χώραν, οὐδενὸς ἐπεξιέναι τολμῶντος τῶν ὑπεναντίων.", "st": "4.63"}, {"sp": "N", "t": "οἱ δ’ Ἀχαιοὶ κατὰ τοὺς καιροὺς τούτους πιεζόμενοι τῷ πολέμῳ, τὸν δὲ βασιλέα πυνθανόμενοι σύνεγγυς εἶναι, πέμπουσι πρέσβεις, ἀξιοῦντες βοηθεῖν. οἳ καὶ συμμίξαντες ἔτι περὶ Στράτον ὄντι τῷ Φιλίππῳ τά τε λοιπὰ διελέγοντο κατὰ τὰς ἐντολάς, καὶ τὰς ὠφελείας ὑποδεικνύντες τῷ στρατοπέδῳ τὰς ἐκ τῆς πολεμίας ἔπειθον αὐτὸν διαβάντα τὸ Ῥίον ἐμβαλεῖν εἰς τὴν Ἠλείαν. ὧν ὁ βασιλεὺς διακούσας τοὺς μὲν πρεσβευτὰς παρακατέσχε, φήσας βουλεύσασθαι περὶ τῶν παρακαλουμένων, αὐτὸς δ’ ἀναζεύξας προῆγε, ποιούμενος τὴν πορείαν ὡς ἐπὶ Μητροπόλεως καὶ Κωνώπης. οἱ δ’ Αἰτωλοὶ τὴν μὲν ἄκραν τῆς Μητροπόλεως κατεῖχον, τὴν δὲ πόλιν ἐξέλιπον. ὁ δὲ Φίλιππος ἐμπρήσας τὴν Μητρόπολιν προῄει κατὰ τὸ συνεχὲς ἐπὶ τὴν Κωνώπην. τῶν δ’ Αἰτωλῶν ἱππέων ἁθροισθέντων καὶ τολμησάντων ἀπαντᾶν πρὸς τὴν τοῦ ποταμοῦ διάβασιν, ἣ κεῖται πρὸ τῆς πόλεως εἴκοσι στάδια διέχουσα, καὶ πεπεισμένων ἢ κωλύειν τελείως ἢ κακοποιήσειν πολλὰ τοὺς Μακεδόνας περὶ τὴν ἔκβασιν, συννοήσας αὐτῶν τὴν ἐπιβολὴν ὁ βασιλεὺς παρήγγειλε τοῖς πελτασταῖς πρώτοις ἐμβαλεῖν εἰς τὸν ποταμὸν καὶ ποιεῖσθαι τὴν ἔκβασιν ἁθρόους κατὰ τάγμα συνησπικότας. τῶν δὲ πειθαρχούντων, ἅμα τῷ τὴν πρώτην διαβῆναι σημαίαν βραχέα ταύτης καταπειράσαντες οἱ τῶν Αἰτωλῶν ἱππεῖς, ἐν τῷ ταύτην τε μεῖναι συνασπίσασαν καὶ τὴν δευτέραν καὶ τρίτην διαβαινούσας συμφράττειν τοῖς ὅπλοις πρὸς τὴν ὑφεστῶσαν, ἀπραγοῦντες καὶ δυσχρήστως ἀπαλλάττοντες ἀπεχώρουν πρὸς τὴν πόλιν. καὶ τὸ λοιπὸν ἤδη τὸ μὲν τῶν Αἰτωλῶν φρόνημα συμπεφευγὸς εἰς τὰς πόλεις ἦγε τὴν ἡσυχίαν. ὁ δὲ Φίλιππος ἐπιδιαβὰς τῷ στρατεύματι, καὶ πορθήσας ἀδεῶς καὶ ταύτην τὴν χώραν προῆγε ποιούμενος τὴν πορείαν εἰς τὴν Ἰθωρίαν· τοῦτο δ’ ἔστι χωρίον, ὃ κεῖται μὲν ἐπὶ τῆς παρόδου κυρίως, ὀχυρότητι δὲ φυσικῇ καὶ χειροποιήτῳ διαφέρει. συνεγγίζοντος δ’ αὐτοῦ, καταπλαγέντες οἱ φυλάττοντες ἐξέλιπον τὸν τόπον· ὁ δὲ βασιλεὺς τοῦ τόπου κυριεύσας εἰς ἔδαφος καθεῖλε. παραπλησίως δὲ καὶ τοὺς λοιποὺς πύργους τοὺς κατὰ τὴν χώραν ἐπέταξε τοῖς προνομεύουσι καταφέρειν.", "st": "4.64"}, {"sp": "N", "t": "διελθὼν δὲ τὰ στενὰ τὸ λοιπὸν ἤδη βάδην καὶ πραεῖαν ἐποιεῖτο τὴν πορείαν, ἀναστροφὴν διδοὺς τῇ δυνάμει πρὸς τὰς ἀπὸ τῆς χώρας ὠφελείας. γέμοντος δὲ τοῦ στρατοπέδου πάντων τῶν ἐπιτηδείων, ἧκε πρὸς τοὺς [Ἀχαιοὺς] Οἰνιάδας. καταστρατοπεδεύσας δὲ πρὸς τὸ Παιάνιον τοῦτο πρῶτον ἐξελεῖν ἔκρινε· ποιησάμενος δὲ προσβολὰς συνεχεῖς εἷλεν αὐτὸ κατὰ κράτος, πόλιν κατὰ μὲν τὸν περίβολον οὐ μεγάλην — ἐλάττων γὰρ ἦν ἑπτὰ σταδίων — κατὰ δὲ τὴν σύμπασαν κατασκευὴν οἰκιῶν καὶ τειχῶν καὶ πύργων οὐδ’ ὁποίας ἥττω. ταύτης δὲ τὸ μὲν τεῖχος κατέσκαψε πᾶν εἰς ἔδαφος, τὰς δ’ οἰκήσεις διαλύων τὰ ξύλα καὶ τὸν κέραμον εἰς σχεδίας καθήρμοζε καὶ συνεχῶς κατῆγεν αὐτὰς τῷ ποταμῷ μετὰ πολλῆς φιλοτιμίας εἰς τοὺς Οἰνιάδας. οἱ δ’ Αἰτωλοὶ τὸ μὲν πρῶτον ἐπεβάλοντο διατηρεῖν τὴν ἄκραν τὴν ἐν τοῖς Οἰνιάδαις, ἀσφαλισάμενοι τείχεσι καὶ τῇ λοιπῇ κατασκευῇ· συνεγγίζοντος δὲ τοῦ Φιλίππου καταπλαγέντες ἐξεχώρησαν. ὁ δὲ βασιλεὺς παραλαβὼν καὶ ταύτην τὴν πόλιν, ἐξ αὐτῆς προελθὼν κατεστρατοπέδευσε τῆς Καλυδωνίας πρός τι χωρίον ὀχυρόν, ὃ καλεῖται μὲν Ἔλαος, ἠσφάλισται δὲ τείχεσι καὶ ταῖς λοιπαῖς παρασκευαῖς διαφερόντως, Ἀττάλου τὴν περὶ αὐτὸ κατασκευὴν ἀναδεξαμένου τοῖς Αἰτωλοῖς. γενόμενοι δὲ καὶ τούτου κύριοι κατὰ κράτος οἱ Μακεδόνες, καὶ πᾶσαν κατασύραντες τὴν Καλυδωνίαν, ἧκον πάλιν εἰς τοὺς Οἰνιάδας. ὁ δὲ Φίλιππος συνθεασάμενος τὴν εὐκαιρίαν τοῦ τόπου, πρός τε τἄλλα καὶ μάλιστα πρὸς τὰς εἰς Πελοπόννησον διαβάσεις, ἐπεβάλετο τειχίζειν τὴν πόλιν. τοὺς γὰρ Οἰνιάδας κεῖσθαι συμβαίνει παρὰ θάλατταν, ἐπὶ τῷ πέρατι τῆς Ἀκαρνανίας τῷ πρὸς Αἰτωλοὺς συνάπτοντι, περὶ τὴν ἀρχὴν τοῦ Κορινθιακοῦ κόλπου. τῆς δὲ Πελοποννήσου τέτακται μὲν ἡ πόλις καταντικρὺ τῆς παραλίας τῆς τῶν Δυμαίων, ἔγγιστα δ’ αὐτῆς ὑπάρχει τοῖς κατὰ τὸν Ἄραξον τόποις· ἀπέχει γὰρ οὐ πλεῖον ἑκατὸν σταδίων. εἰς ἃ βλέψας τήν τε ἄκραν καθ’ αὑτὴν ἠσφαλίσατο, καὶ τῷ λιμένι καὶ τοῖς νεωρίοις ὁμοῦ τεῖχος περιβαλὼν ἐνεχείρει συνάψαι πρὸς τὴν ἄκραν, χρώμενος πρὸς τὴν οἰκονομίαν ταῖς ἐκ τοῦ Παιανίου παρασκευαῖς.", "st": "4.65"}, {"sp": "N", "t": "ἔτι δὲ περὶ ταῦτα γινομένου τοῦ βασιλέως, παρῆν ἐκ Μακεδονίας ἄγγελος διασαφῶν ὅτι συμβαίνει τοὺς Δαρδανεῖς, ὑπονενοηκότας τὴν εἰς Πελοπόννησον αὐτοῦ στρατείαν, ἁθροίζειν δυνάμεις καὶ παρασκευὴν ποιεῖσθαι μεγάλην, κεκρικότας ἐμβαλεῖν εἰς τὴν Μακεδονίαν. ἀκούσας δὲ ταῦτα καὶ νομίσας ἀναγκαῖον εἶναι βοηθεῖν κατὰ τάχος τῇ Μακεδονίᾳ, τοὺς μὲν παρὰ τῶν Ἀχαιῶν πρέσβεις ἀπέστειλε, δοὺς ἀπόκρισιν ὅτι τοῖς προσηγγελμένοις ἐπαρκέσας οὐδὲν προυργιαίτερον ποιήσεται μετὰ ταῦτα τοῦ βοηθεῖν σφίσι κατὰ δύναμιν, αὐτὸς δ’ ἀναζεύξας μετὰ σπουδῆς ἐποιεῖτο τὴν ἐπάνοδον, ᾗπερ καὶ τὴν παρουσίαν ἐπεποίητο. μέλλοντος δ’ αὐτοῦ διαβαίνειν τὸν Ἀμβρακικὸν κόλπον ἐξ Ἀκαρνανίας εἰς Ἤπειρον, παρῆν ἐφ’ ἑνὸς λέμβου Δημήτριος ὁ Φάριος, ἐκπεπτωκὼς ὑπὸ Ῥωμαίων ἐκ τῆς Ἰλλυρίδος· ὑπὲρ ὧν ἐν τοῖς πρὸ τούτων ἡμῖν δεδήλωται. τοῦτον μὲν οὖν Φίλιππος ἀποδεξάμενος φιλανθρώπως ἐκέλευσε πλεῖν ὡς ἐπὶ Κόρινθον κἀκεῖθεν ἥκειν διὰ Θετταλίας εἰς Μακεδονίαν· αὐτὸς δὲ διαβὰς εἰς τὴν Ἤπειρον προῆγε κατὰ τὸ συνεχὲς εἰς τὸ πρόσθεν. παραγενομένου δ’ αὐτοῦ τῆς Μακεδονίας εἰς Πέλλαν, ἀκούσαντες οἱ Δαρδάνιοι παρὰ Θρᾳκῶν τινων αὐτομόλων τὴν παρουσίαν τοῦ Φιλίππου, καταπλαγέντες παραχρῆμα διέλυσαν τὴν στρατείαν, καίπερ ἤδη σύνεγγυς ὄντες τῆς Μακεδονίας. Φίλιππος δὲ πυθόμενος τὴν τῶν Δαρδανέων μετάνοιαν, τοὺς μὲν Μακεδόνας διαφῆκε πάντας ἐπὶ τὴν τῆς ὀπώρας συγκομιδήν, αὐτὸς δὲ πορευθεὶς εἰς Θετταλίαν τὸ λοιπὸν μέρος τοῦ θέρους ἐν Λαρίσῃ διῆγε. κατὰ δὲ τὸν καιρὸν τοῦτον Αἰμίλιος ἐκ τῆς Ἰλλυρίδος εἰσῆγε λαμπρῶς εἰς τὴν Ῥώμην τὸν θρίαμβον, Ἀννίβας δὲ Ζάκανθαν ᾑρηκὼς κατὰ κράτος διέλυσε τὰς δυνάμεις εἰς παραχειμασίαν· Ῥωμαῖοι δέ, προσπεσούσης αὐτοῖς τῆς Ζακανθαίων ἁλώσεως, πρεσβευτὰς ἔπεμπον ἐξαιτήσοντας Ἀννίβαν παρὰ Καρχηδονίων, ἅμα δὲ πρὸς τὸν πόλεμον παρεσκευάζοντο, καταστήσαντες ὑπάτους Πόπλιον Κορνήλιον καὶ Τεβέριον Σεμπρώνιον. ὑπὲρ ὧν ἡμεῖς τὰ μὲν κατὰ μέρος ἐν τῇ προτέρᾳ βύβλῳ δεδηλώκαμεν· νῦν δ’ ἀναμνήσεως χάριν αὐτὰ προηνεγκάμεθα κατὰ τὴν ἐξ ἀρχῆς ἐπαγγελίαν, ἵνα γινώσκηται τὰ κατάλληλα τῶν πραγμάτων. καὶ τὸ μὲν πρῶτον ἔτος ἔληγε τῆς ὑποκειμένης ὀλυμπιάδος.", "st": "4.66"}, {"sp": "N", "t": "παρὰ δὲ τοῖς Αἰτωλοῖς ἤδη τῶν ἀρχαιρεσίων καθηκόντων στρατηγὸς ᾑρέθη Δωρίμαχος· ὃς παραυτίκα τὴν ἀρχὴν παραλαβὼν καὶ τοὺς Αἰτωλοὺς ἁθροίσας μετὰ τῶν ὅπλων, ἐνέβαλεν εἰς τοὺς ἄνω τόπους τῆς Ἠπείρου καὶ τὴν χώραν ἐδῄου, θυμικώτερον χρώμενος τῇ καταφθορᾷ· τὸ γὰρ πλεῖον οὐ τῆς σφετέρας ὠφελείας, ἀλλὰ τῆς τῶν Ἠπειρωτῶν βλάβης χάριν ἕκαστα συνετέλει. παραγενόμενος δὲ πρὸς τὸ περὶ Δωδώνην ἱερὸν τάς τε στοὰς ἐνέπρησε καὶ πολλὰ τῶν ἀναθημάτων διέφθειρε, κατέσκαψε δὲ καὶ τὴν ἱερὰν οἰκίαν, ὥστε μήτ’ εἰρήνης ὅρον μήτε πολέμου πρὸς Αἰτωλοὺς ὑπάρχειν, ἀλλ’ ἐν ἀμφοτέραις ταῖς περιστάσεσι παρὰ τὰ κοινὰ τῶν ἀνθρώπων ἔθη καὶ νόμιμα χρῆσθαι ταῖς ἐπιβολαῖς. οὗτος μὲν οὖν ταῦτα καὶ τοιαῦτα διαπραξάμενος ἐπανῆγεν αὖθις εἰς τὴν οἰκείαν. τοῦ δὲ χειμῶνος ἔτι προβαίνοντος, καὶ πάντων ἀπηλπικότων τὴν παρουσίαν τοῦ Φιλίππου διὰ τὸν καιρόν, ἀναλαβὼν ὁ βασιλεὺς χαλκάσπιδας μὲν τρισχιλίους, πελταστὰς δὲ δισχιλίους καὶ Κρῆτας τριακοσίους, πρὸς δὲ τούτοις ἱππεῖς τοὺς περὶ τὴν αὐλὴν εἰς τετρακοσίους, προῆγεν ἀπὸ Λαρίσης· καὶ διαβιβάσας τούτους ἐκ Θετταλίας εἰς Εὔβοιαν κἀκεῖθεν εἰς Κῦνον ἧκε διὰ τῆς Βοιωτίας καὶ Μεγαρίδος εἰς Κόρινθον περὶ τροπὰς χειμερινάς, ἐνεργὸν καὶ λαθραίαν πεποιημένος τὴν παρουσίαν οὕτως ὥστε μηδένα Πελοποννησίων ὑπονοῆσαι τὸ γεγονός. κλείσας δὲ τὰς πύλας τοῦ Κορίνθου καὶ διαλαβὼν τὰς ὁδοὺς φυλακαῖς, τῇ κατὰ πόδας Ἄρατον μὲν τὸν πρεσβύτερον ὡς αὑτὸν ἐκ τοῦ Σικυῶνος μετεπέμπετο, γράμματά τε πρὸς τὸν στρατηγὸν τῶν Ἀχαιῶν καὶ πρὸς τὰς πόλεις ἐξαπέστελλεν, — ἐν οἷς διεσάφει πότε καὶ ποῦ δεήσει συναντᾶν πάντας ἐν τοῖς ὅπλοις. ταῦτα δ’ οἰκονομήσας ἀνέζευξε, καὶ προελθὼν κατεστρατοπέδευσε τῆς Φλιασίας περὶ τὸ Διοσκούριον.", "st": "4.67"}, {"sp": "N", "t": "κατὰ δὲ τοὺς αὐτοὺς καιροὺς Εὐριπίδας, ἔχων Ἠλείων δύο λόχους μετὰ τῶν πειρατῶν καὶ μισθοφόρων, ὥστ’ εἶναι τοὺς πάντας εἰς δισχιλίους καὶ διακοσίους, ἅμα δὲ τούτοις ἱππεῖς ἑκατόν, ὁρμήσας ἐκ Ψωφῖδος ἐποιεῖτο τὴν πορείαν διὰ τῆς Φενικῆς καὶ Στυμφαλίας, οὐδὲν μὲν εἰδὼς τῶν κατὰ τὸν Φίλιππον, βουλόμενος δὲ κατασῦραι τὴν τῶν Σικυωνίων χώραν. τῆς δὲ νυκτὸς τῆς αὐτῆς, ἐν ᾗ συνέβαινε στρατοπεδεύειν τὸν Φίλιππον περὶ τὸ Διοσκούριον, παρηλλαχὼς τὴν στρατοπεδείαν τοῦ βασιλέως περὶ τὴν ἑωθινὴν ἐμβάλλειν οἷός τ’ ἦν εἰς τὴν Σικυωνίαν. τῶν δὲ παρὰ τοῦ Φιλίππου Κρητῶν τινες ἀπολελοιπότες τὰς τάξεις καὶ διιχνεύοντες περὶ τὰς προνομείας ἐμπίπτουσιν εἰς τοὺς περὶ τὸν Εὐριπίδαν· οὓς ἀνακρίνας καὶ συνεὶς τὴν παρουσίαν τῶν Μακεδόνων ὁ προειρημένος, οὐδενὶ ποιήσας φανερὸν οὐδὲν τῶν προσπεπτωκότων, ἀναλαβὼν τὴν δύναμιν ἐξ ὑποστροφῆς αὖθις ἀνέλυε τὴν αὐτὴν ὁδὸν ἐν ᾗπερ ἧκε, βουλόμενος, ἅμα δὲ καὶ κατελπίζων καταταχήσειν τοὺς Μακεδόνας διεκβαλὼν τὴν Στυμφαλίαν καὶ συνάψας ταῖς ὑπερκειμέναις δυσχωρίαις. ὁ δὲ βασιλεύς, οὐδὲν εἰδὼς τῶν περὶ τοὺς ὑπεναντίους, κατὰ δὲ τὴν αὑτοῦ πρόθεσιν ἀναζεύξας τὴν ἑωθινὴν προῆγε, κρίνων ποιεῖσθαι τὴν πορείαν παρ’ αὐτὸν τὸν Στύμφαλον ὡς ἐπὶ τὰς Καφύας· ἐνθάδε γὰρ ἐγεγράφει τοῖς Ἀχαιοῖς συναθροίζεσθαι μετὰ τῶν ὅπλων.", "st": "4.68"}, {"sp": "N", "t": "τῆς δὲ πρωτοπορείας τῶν Μακεδόνων ἐπιβαλούσης ἐπὶ τὴν ὑπερβολὴν τὴν περὶ τὸ καλούμενον Ἀπέλαυρον, ἣ πρόκειται τῆς τῶν Στυμφαλίων πόλεως περὶ δέκα στάδι’, ἅμα συνεκύρησε καὶ τὴν τῶν Ἠλείων πρωτοπορείαν συμπεσεῖν ἐπὶ τὴν ὑπερβολήν. ὁ μὲν οὖν Εὐριπίδας, συννοήσας τὸ γεγονὸς ἐκ τῶν προσηγγελμένων, παραλαβὼν μεθ’ ἑαυτοῦ τινας τῶν ἱππέων καὶ διαδρὰς τὸν ἐνεστῶτα καιρὸν ἐποιεῖτο τὴν ἀποχώρησιν εἰς τὴν Ψωφῖδα ταῖς ἀνοδίαις· τὸ δὲ λοιπὸν πλῆθος τῶν Ἠλείων, ἐγκαταλελειμμένον ὑπὸ τοῦ προεστῶτος καὶ γεγονὸς ἐκπλαγὲς ἐπὶ τῷ συμβεβηκότι, κατὰ πορείαν ἔμενε, διαπορούμενον τί δεῖ ποιεῖν καὶ πῇ τρέπεσθαι. τὸ μὲν γὰρ πρῶτον αὐτῶν οἱ προεστῶτες ὑπελάμβανον τῶν Ἀχαιῶν αὐτῶν τινας συνεπιβεβοηθηκέναι· καὶ μάλιστ’ ἠπάτων αὐτοὺς οἱ χαλκάσπιδες· Μεγαλοπολίτας γὰρ εἶναι τούτους ἐδόξαζον, διὰ τὸ τοιούτοις ὅπλοις κεχρῆσθαι τοὺς προειρημένους ἐν τῷ περὶ Σελλασίαν [ἐν τῷ] πρὸς Κλεομένη κινδύνῳ, καθοπλίσαντος Ἀντιγόνου τοῦ βασιλέως πρὸς τὴν παροῦσαν χρείαν. διόπερ ἀπεχώρουν τηροῦντες τὰς τάξεις πρός τινας ὑπερδεξίους τόπους, οὐκ ἀπελπίζοντες τὴν σωτηρίαν. ἅμα δὲ τῷ προσάγοντας αὐτοῖς τοὺς Μακεδόνας σύνεγγυς γενέσθαι λαβόντες ἔννοιαν τοῦ κατ’ ἀλήθειαν ὄντος, πάντες ὥρμησαν πρὸς φυγήν, ῥίψαντες τὰ ὅπλα. ζωγρίᾳ μὲν οὖν ἑάλωσαν αὐτῶν περὶ χιλίους καὶ διακοσίους, τὸ δὲ λοιπὸν διεφθάρη πλῆθος, τὸ μὲν ὑπὸ τῶν Μακεδόνων, τὸ δ’ ὑπὸ τῶν κρημνῶν· διέφυγον δ’ οὐ πλείους τῶν ἑκατόν. ὁ δὲ Φίλιππος τά τε σκῦλα καὶ τοὺς αἰχμαλώτους εἰς Κόρινθον ἀποπέμψας εἴχετο τῶν προκειμένων. τοῖς δὲ Πελοποννησίοις πᾶσι παράδοξον ἐφάνη τὸ γεγονός· ἅμα γὰρ ἤκουον τὴν παρουσίαν καὶ τὴν νίκην τοῦ βασιλέως.", "st": "4.69"}, {"sp": "N", "t": "ποιησάμενος δὲ τὴν πορείαν διὰ τῆς Ἀρκαδίας, καὶ πολλὰς ἀναδεξάμενος χιόνας καὶ ταλαιπωρίας ἐν ταῖς περὶ τὸν Ὀλύγυρτον ὑπερβολαῖς, τῇ τρίτῃ τῶν ἡμερῶν κατῆρε νύκτωρ εἰς Καφύας. θεραπεύσας δὲ τὴν δύναμιν ἐπὶ δύ’ ἡμέρας ἐνταῦθα, καὶ προσαναλαβὼν Ἄρατον τὸν νεώτερον καὶ τοὺς ἅμα τούτῳ συνηθροισμένους τῶν Ἀχαιῶν, ὥστ’ εἶναι τὴν ὅλην δύναμιν εἰς τοὺς μυρίους, προῆγε διὰ τῆς Κλειτορίας ὡς ἐπὶ Ψωφῖδος, συναθροίζων ἐκ τῶν πόλεων ὧν διεπορεύετο βέλη καὶ κλίμακας. ἡ δὲ Ψωφὶς ἔστι μὲν ὁμολογούμενον καὶ παλαιὸν Ἀρκάδων κτίσμα τῆς Ἀζανίδος, κεῖται δὲ τῆς μὲν συμπάσης Πελοποννήσου κατὰ τὴν μεσόγαιον, αὐτῆς δὲ τῆς Ἀρκαδίας ἐπὶ τοῖς πρὸς δυσμὰς πέρασι, συνάπτουσα τοῖς περὶ τὰς ἐσχατιὰς κατοικοῦσι τῶν προσεσπερίων Ἀχαιῶν· ἐπίκειται δ’ εὐφυῶς τῇ τῶν Ἠλείων χώρᾳ, μεθ’ ὧν συνέβαινε τότε πολιτεύεσθαι αὐτήν. πρὸς ἣν Φίλιππος τριταῖος ἐκ τῶν Καφυῶν διανύσας, κατεστρατοπέδευε περὶ τοὺς ἀπέναντι τῆς πόλεως ὑπερκειμένους βουνούς, ἀφ’ ὧν ἦν κατοπτεύειν τήν τε πόλιν ὅλην ἀσφαλῶς καὶ τοὺς πέριξ αὐτῆς τόπους. συνθεωρῶν δὲ τὴν ὀχυρότητα τῆς Ψωφῖδος ὁ βασιλεὺς ἠπορεῖτο τί χρὴ ποιεῖν. τὴν γὰρ ἀφ’ ἑσπέρας πλευρὰν αὐτῆς καταφέρεται λάβρος χειμάρρους ποταμός, ὃς κατὰ τὸ πλεῖστον μέρος τοῦ χειμῶνος ἄβατός ἐστι, ποιεῖ δὲ καὶ τὸ παράπαν ἐχυρὰν καὶ δυσπρόσοδον τὴν πόλιν διὰ τὸ μέγεθος τοῦ κοιλώματος, ὃ κατὰ βραχὺ τῷ χρόνῳ κατείργασται φερόμενος ἐξ ὑπερδεξίων τόπων. παρὰ δὲ τὴν ἀπ’ ἠοῦς πλευρὰν ἔχει τὸν Ἐρύμανθον, μέγαν καὶ λάβρον ποταμόν, ὑπὲρ οὗ πολὺς καὶ ὑπὸ πολλῶν τεθρύληται λόγος. τοῦ δὲ χειμάρρου προσπίπτοντος πρὸς τὸν Ἐρύμανθον ὑπὸ τὸ πρὸς μεσημβρίαν μέρος τῆς πόλεως, συμβαίνει τὰς μὲν τρεῖς ἐπιφανείας αὐτῆς ὑπὸ τῶν ποταμῶν περιλαμβανομένας ἀσφαλίζεσθαι τὸν προειρημένον τρόπον· τῇ δὲ λοιπῇ, τῇ πρὸς ἄρκτον, βουνὸς ἐρυμνὸς ἐπίκειται τετειχισμένος, ἄκρας εὐφυοῦς καὶ πραγματικῆς λαμβάνων τάξιν. ἔχει δὲ καὶ τείχη διαφέροντα τῷ μεγέθει καὶ ταῖς κατασκευαῖς. πρὸς δὲ τούτοις βοήθειαν συνέβαινε παρὰ τῶν Ἠλείων εἰσπεπτωκέναι, καὶ τὸν Εὐριπίδαν ἐκ τῆς φυγῆς διασεσωσμένον ὑπάρχειν ἐν αὐτῇ.", "st": "4.70"}, {"sp": "N", "t": "ταῦτ’ οὖν πάντα συνορῶν καὶ συλλογιζόμενος ὁ Φίλιππος τὰ μὲν ἀφίστατο τοῖς λογισμοῖς τοῦ βιάζεσθαι καὶ πολιορκεῖν τὴν πόλιν, τὰ δὲ προθύμως εἶχε, τὴν εὐκαιρίαν ὁρῶν τοῦ τόπου· καθ’ ὅσον γὰρ ἐπέκειτο τοῖς Ἀχαιοῖς τότε καὶ τοῖς Ἀρκάσι καὶ πολεμητήριον ὑπῆρχε τοῖς Ἠλείοις ἀσφαλές, κατὰ τοσοῦτον πάλιν κρατηθὲν ἔμελλε τῶν μὲν Ἀρκάδων προκεῖσθαι, κατὰ δὲ τῶν Ἠλείων ὁρμητήριον ὑπάρξειν τοῖς συμμάχοις εὔκαιρον. διόπερ ἐπὶ τοῦτο τὸ μέρος ὁρμήσας τῇ γνώμῃ παρήγγελλε τοῖς Μακεδόσιν ἅμα τῷ φωτὶ πᾶσιν ἀριστοποιεῖσθαι καὶ διεσκευασμένους ἑτοίμους ὑπάρχειν. μετὰ δὲ ταῦτα διαβὰς τὴν κατὰ τὸν Ἐρύμανθον γέφυραν, οὐδενὸς ἐμποδὼν στάντος διὰ τὸ παράδοξον τῆς ἐπιβολῆς, ἧκε πρὸς αὐτὴν τὴν πόλιν ἐνεργῶς καὶ καταπληκτικῶς. οἱ δὲ περὶ τὸν Εὐριπίδαν καὶ πάντες οἱ κατὰ τὴν πόλιν διηπόρουν ἐπὶ τοῖς συμβαίνουσι τῷ πεπεῖσθαι μήτ’ ἂν ἐξ ἐφόδου τολμῆσαι τοὺς πολεμίους προσβαλεῖν καὶ βιάζεσθαι πρὸς οὕτως ὀχυρὰν πόλιν μήτε χρόνιον ἂν συστήσασθαι πολιορκίαν διὰ τὴν τοῦ καιροῦ περίστασιν. ἅμα δὲ ταῦτα λογιζόμενοι διηπίστουν ἀλλήλοις, δεδιότες μὴ πρᾶξιν ὁ Φίλιππος εἴη διὰ τῶν ἔνδον συνεσταμένος κατὰ τῆς πόλεως. ἐπεὶ δ’ οὐδὲν ἑώρων τοιοῦτον ἐξ αὑτῶν γινόμενον, ὥρμησαν οἱ μὲν πλείους ἐπὶ τὰ τείχη βοηθήσοντες, οἱ δὲ μισθοφόροι τῶν Ἠλείων κατά τινα πύλην ὑπερδέξιον ἐξῆλθον ὡς ἐπιθησόμενοι τοῖς πολεμίοις. ὁ δὲ βασιλεὺς διατάξας κατὰ τρεῖς τόπους τοὺς προσοίσοντας τῷ τείχει τὰς κλίμακας, καὶ τούτοις ὁμοίως μερίσας τοὺς ἄλλους Μακεδόνας, μετὰ ταῦτα διὰ τῶν σαλπιγκτῶν ἀποδοὺς ἑκάστοις τὸ σύνθημα πανταχόθεν ἅμα τὴν προσβολὴν ἐποιεῖτο τοῖς τείχεσι. τὸ μὲν οὖν πρῶτον ἠμύνοντο γενναίως οἱ κατέχοντες τὴν πόλιν, καὶ πολλοὺς ἀπὸ τῶν κλιμάκων ἀπέρριπτον· ἐπεὶ δ’ ἥ τε χορηγία τῶν βελῶν καὶ τῶν ἄλλων τῶν πρὸς τὴν χρείαν ἐπιτηδείων ἐνέλειπεν, ὡς ἂν ἐκ τοῦ καιροῦ τῆς παρασκευῆς γεγενημένης, οἵ τε Μακεδόνες οὐ κατεπλήττοντο τὸ γινόμενον, ἀλλ’ ἐπὶ τὴν τοῦ ῥιφέντος ἀπὸ τῶν κλιμάκων χώραν ὁ κατόπιν ἀμελλήτως ἐπέβαινε, τέλος οἱ μὲν ἐκ τῆς πόλεως τραπέντες ἔφευγον πάντες πρὸς τὴν ἀκρόπολιν, τῶν δὲ παρὰ τοῦ βασιλέως οἱ μὲν Μακεδόνες ἐπέβησαν τοῦ τείχους, οἱ δὲ Κρῆτες πρὸς τοὺς κατὰ τὴν ὑπερδέξιον πύλην ἐπεξελθόντας τῶν μισθοφόρων συμμίξαντες ἠνάγκασαν αὐτοὺς οὐδενὶ κόσμῳ ῥίψαντας τὰ ὅπλα φεύγειν. οἷς ἐπικείμενοι καὶ προσφέροντες τὰς χεῖρας συνεισέπεσον διὰ τῆς πύλης· ἐξ οὗ συνέβη πανταχόθεν ἅμα καταληφθῆναι τὴν πόλιν. οἱ μὲν οὖν Ψωφίδιοι μετὰ τέκνων καὶ γυναικῶν ἀπεχώρησαν εἰς τὴν ἄκραν, ἅμα δὲ τούτοις οἱ περὶ τὸν Εὐριπίδαν, ὁμοίως δὲ καὶ τὸ λοιπὸν πλῆθος τῶν διασῳζομένων·", "st": "4.71"}, {"sp": "N", "t": "οἱ δὲ Μακεδόνες εἰσπεσόντες τὴν μὲν ἐνδομενίαν ἅπασαν ἐκ τῶν οἰκιῶν παραχρῆμα διήρπασαν, μετὰ δὲ ταῦτα ταῖς οἰκίαις ἐπισκηνώσαντες κατεῖχον τὴν πόλιν. οἱ δὲ συμπεφευγότες εἰς τὴν ἀκρόπολιν, οὐδεμιᾶς σφίσι παρασκευῆς ὑπαρχούσης, προορώμενοι τὸ μέλλον ἔγνωσαν ἐγχειρίζειν σφᾶς αὐτοὺς τῷ Φιλίππῳ. πέμψαντες οὖν κήρυκα πρὸς τὸν βασιλέα, καὶ λαβόντες συγχώρημα περὶ πρεσβείας, ἐξαπέστειλαν τοὺς ἄρχοντας καὶ μετὰ τούτων Εὐριπίδαν· οἳ καὶ ποιησάμενοι σπονδὰς ἔλαβον τὴν ἀσφάλειαν τοῖς συμπεφευγόσιν ὁμοῦ ξένοις καὶ πολίταις. οὗτοι μὲν οὖν αὖτις ἐπανῆλθον ὅθεν ὥρμησαν, ἔχοντες παράγγελμα μένειν κατὰ χώραν, ἕως ἂν ἡ δύναμις ἀναζεύξῃ, μή τινες ἀπειθήσαντες τῶν στρατιωτῶν διαρπάσωσιν αὐτούς· ὁ δὲ βασιλεὺς ἐπιγενομένης χιόνος ἠναγκάσθη μένειν ἐπὶ τόπου τινὰς ἡμέρας. ἐν αἷς συναγαγὼν τοὺς παρόντας τῶν Ἀχαιῶν πρῶτον μὲν τὴν ὀχυρότητα καὶ τὴν εὐκαιρίαν ἐπεδείκνυε τῆς πόλεως πρὸς τὸν ἐνεστῶτα πόλεμον, ἀπελογίσατο δὲ καὶ τὴν αἵρεσιν καὶ τὴν εὔνοιαν, ἣν ἔχοι πρὸς τὸ ἔθνος, ἐπὶ δὲ πᾶσιν ἔφη καὶ νῦν παραχωρεῖν καὶ διδόναι τοῖς Ἀχαιοῖς τὴν πόλιν· προκεῖσθαι γὰρ αὐτῷ τὰ δυνατὰ χαρίζεσθαι καὶ μηθὲν ἐλλείπειν προθυμίας. ἐφ’ οἷς εὐχαριστούντων αὐτῷ τῶν τε περὶ τὸν Ἄρατον καὶ τῶν πολλῶν, διαλύσας τὴν ἐκκλησίαν ὁ μὲν Φίλιππος μετὰ τῆς δυνάμεως ἀναζεύξας ἐπὶ Λασιῶνος ἐποιεῖτο τὴν πορείαν, οἱ δὲ Ψωφίδιοι καταβάντες ἐκ τῆς ἄκρας ἐκομίσαντο τὴν πόλιν καὶ τὰς οἰκήσεις ἕκαστοι τὰς αὑτῶν, οἱ δὲ περὶ τὸν Εὐριπίδαν ἀπῆλθον εἰς τὸν Κόρινθον κἀκεῖθεν εἰς Αἰτωλίαν. τῶν δ’ Ἀχαϊκῶν ἀρχόντων οἱ παρόντες ἐπὶ μὲν τὴν ἄκραν ἐπέστησαν μετὰ φυλακῆς ἱκανῆς Πρόσλαον Σικυώνιον, ἐπὶ δὲ τὴν πόλιν Πυθίαν Πελληνέα. καὶ τὰ μὲν περὶ Ψωφῖδα τοῦτον ἐπετελέσθη τὸν τρόπον.", "st": "4.72"}, {"sp": "N", "t": "οἱ δὲ παραφυλάττοντες τὸν Λασιῶνα τῶν Ἠλείων, συνέντες τὴν παρουσίαν τῶν Μακεδόνων, πεπυσμένοι δὲ καὶ τὰ γεγονότα περὶ τὴν Ψωφῖδα, παραχρῆμα τὴν πόλιν ἐξέλιπον. ὁ δὲ βασιλεὺς ὡς θᾶττον ἧκε, ταύτην μὲν ἐξ ἐφόδου παρέλαβε, συναύξων δὲ τὴν πρόθεσιν, ἣν εἶχε πρὸς τὸ ἔθνος, παρέδωκε καὶ τὸν Λασιῶνα τοῖς Ἀχαιοῖς. ὁμοίως δὲ καὶ τὴν Στράτον ἐκλιπόντων τῶν Ἠλείων ἀποκατέστησε τοῖς Τελφουσίοις. ταῦτα δὲ διαπραξάμενος ἧκε πεμπταῖος εἰς Ὀλυμπίαν. θύσας δὲ τῷ θεῷ καὶ τοὺς ἡγεμόνας ἑστιάσας, ἅμα δὲ καὶ τὴν λοιπὴν προσαναπαύσας δύναμιν ἐπὶ τρεῖς ἡμέρας, μετὰ ταῦτα πάλιν ἀνέζευξε. καὶ προελθὼν εἰς τὴν Ἠλείαν τὰς μὲν προνομὰς ἐπαφῆκε κατὰ τῆς χώρας, αὐτὸς δὲ κατεστρατοπέδευσε περὶ τὸ καλούμενον Ἀρτεμίσιον. προσδεξάμενος δ’ ἐνταῦθα τὴν λείαν μετέβη πάλιν ἐπὶ τὸ Διοσκούριον. δῃουμένης δὲ τῆς χώρας, πολὺ μὲν ἦν τὸ τῶν ἁλισκομένων πλῆθος, ἔτι δὲ πλέον τὸ συμφεῦγον εἰς τὰς παρακειμένας κώμας καὶ τοὺς ἐρυμνοὺς τῶν τόπων. συμβαίνει γὰρ τὴν τῶν Ἠλείων χώραν διαφερόντως οἰκεῖσθαι καὶ γέμειν σωμάτων καὶ κατασκευῆς παρὰ τὴν ἄλλην Πελοπόννησον. ἔνιοι γὰρ αὐτῶν οὕτως στέργουσι τὸν ἐπὶ τῶν ἀγρῶν βίον ὥστε τινὰς ἐπὶ δύο καὶ τρεῖς γενεάς, ἔχοντας ἱκανὰς οὐσίας, μὴ παραβεβληκέναι τὸ παράπαν εἰς ἁλίαν. τοῦτο δὲ γίνεται διὰ τὸ μεγάλην ποιεῖσθαι σπουδὴν καὶ πρόνοιαν τοὺς πολιτευομένους τῶν ἐπὶ τῆς χώρας κατοικούντων, ἵνα τό τε δίκαιον αὐτοῖς ἐπὶ τόπου διεξάγηται καὶ τῶν πρὸς βιωτικὰς χρείας μηδὲν ἐλλείπῃ. δοκοῦσι δέ μοι πάντα ταῦτα καὶ διὰ τὸ πλῆθος μὲν τῆς χώρας τὸ παλαιὸν ἐπινοῆσαι καὶ νομοθετῆσαι, τὸ δὲ πλεῖστον διὰ τὸν ὑπάρχοντά ποτε παρ’ αὐτοῖς ἱερὸν βίον, ὅτε λαβόντες παρὰ τῶν Ἑλλήνων συγχώρημα διὰ τὸν ἀγῶνα τῶν Ὀλυμπίων ἱερὰν καὶ ἀπόρθητον ᾤκουν τὴν Ἠλείαν, ἄπειροι παντὸς ὄντες δεινοῦ καὶ πάσης πολεμικῆς περιστάσεως.", "st": "4.73"}, {"sp": "N", "t": "μετὰ δὲ ταῦτα διὰ τὴν Ἀρκάδων ἀμφισβήτησιν περὶ Λασιῶνος καὶ τῆς Πισάτιδος πάσης ἀναγκασθέντες ἐπαμύνειν τῇ χώρᾳ καὶ μεταλαβεῖν τὰς ἀγωγὰς τῶν βίων, οὐκέτι περὶ τοῦ πάλιν ἀνακτήσασθαι παρὰ τῶν Ἑλλήνων τὴν παλαιὰν καὶ πάτριον ἀσυλίαν οὐδὲ τὴν τυχοῦσαν ἐπιμέλειαν ἔσχον, ἀλλ’ ἔμειναν ἐπὶ τῶν αὐτῶν, οὐκ ὀρθῶς κατά γε τὴν ἐμὴν γνώμην περὶ τοῦ μέλλοντος ποιούμενοι πρόνοιαν. εἰ γάρ, ἧς πάντες εὐχόμεθα τοῖς θεοῖς τυχεῖν, καὶ πᾶν ὑπομένομεν ἱμείροντες αὐτῆς μετασχεῖν, καὶ μόνον τοῦτο τῶν νομιζομένων ἀγαθῶν ἀναμφισβήτητόν ἐστι παρ’ ἀνθρώποις, λέγω δὴ τὴν εἰρήνην, ταύτην δυνάμενοί τινες μετὰ τοῦ δικαίου καὶ καθήκοντος παρὰ τῶν Ἑλλήνων εἰς πάντα τὸν χρόνον ἀδήριτον κτᾶσθαι παρολιγωροῦσιν ἢ προυργιαίτερόν τι ποιοῦνται τούτου, πῶς οὐκ ἂν ὁμολογουμένως ἀγνοεῖν δόξαιεν; νὴ Δί’, ἀλλ’ ἴσως εὐεπίθετοι τοῖς πολεμεῖν καὶ παρασπονδεῖν προθεμένοις ἐκ τῆς τοιαύτης ἀγωγῆς γίνονται τῶν βίων. ἀλλ’ ἐκεῖνο μὲν σπάνιον, κἄν ποτε γένηται, δυνάμενον κοινῆς ὑπὸ τῶν Ἑλλήνων τυγχάνειν ἐπικουρίας· πρὸς δὲ τὰς κατὰ μέρος ἀδικίας ὑπογενομένης τοῖς βίοις χορηγίας, ὅπερ εἰκὸς ὑπάρξειν πάντα χρόνον ἐν εἰρήνῃ διάγουσι, δῆλον ὡς οὐκ ἂν ἠπόρησαν ξένων καὶ μισθοφόρων τῶν κατὰ τόπους ἢ καιροὺς παρεφεδρευόντων. νῦν δὲ τὸ σπάνιον καὶ παράδοξον δεδιότες, ἐν συνεχέσι πολέμοις καὶ καταφθοραῖς τήν τε χώραν ἔχουσι καὶ τοὺς βίους. ταῦτα μὲν οὖν ἡμῖν τῆς Ἠλείων ὑπομνήσεως εἰρήσθω χάριν, ἐπειδὴ τὰ τῶν καιρῶν οὐδέποτε πρότερον εὐφυεστέραν διάθεσιν ἔσχηκε τῆς νῦν πρὸς τὸ παρὰ πάντων ὁμολογουμένην κτήσασθαι τὴν ἀσυλίαν· τὴν δὲ χώραν, καθάπερ ἐπάνω προεῖπον, ἔτι τῆς παλαιᾶς συνηθείας οἷον αἰθυγμάτων ἐμμενόντων, οἰκοῦσι διαφερόντως Ἠλεῖοι.", "st": "4.74"}, {"sp": "N", "t": "διὸ καὶ κατὰ τὴν Φιλίππου παρουσίαν ἄπλετον μὲν ἦν τὸ τῶν ἁλισκομένων πλῆθος, ἔτι δὲ πλεῖον τὸ τῶν συμπεφευγότων. πλείστη δ’ ἀποσκευὴ καὶ πλεῖστος ὄχλος ἡθροίσθη σωμάτων καὶ θρεμμάτων εἰς τὸ χωρίον, ὃ καλοῦσι Θαλάμας, διὰ τὸ τήν τε χώραν τὴν πέριξ αὐτοῦ στενὴν εἶναι καὶ δυσέμβολον τό τε χωρίον ἀπραγμάτευτον καὶ δυσπρόσοδον. ἀκούων δ’ ὁ βασιλεὺς τὸ πλῆθος τῶν συμπεφευγότων εἰς τὸν προειρημένον τόπον, καὶ κρίνας μηδὲν ἀβασάνιστον μηδ’ ἀπέραντον ἀπολιπεῖν, τοῖς μὲν μισθοφόροις προκατελάβετο τοὺς ἐπὶ τῆς εἰσβολῆς εὐφυῶς κειμένους τόπους, αὐτὸς δὲ τὴν ἀποσκευὴν καταλιπὼν ἐν τῷ χάρακι καὶ τὸ πλεῖον μέρος τῆς δυνάμεως, ἀναλαβὼν τοὺς πελταστὰς καὶ τοὺς εὐζώνους προῆγε διὰ τῶν στενῶν· οὐδενὸς δὲ κωλύοντος ἧκε πρὸς τὸ χωρίον. καταπλαγέντων δὲ τῶν συμπεφευγότων τὴν ἔφοδον, ἅτε δὴ πρὸς πᾶσαν πολεμικὴν χρείαν ἀπείρως καὶ ἀπαρασκεύως διακειμένων, ἅμα δὲ καὶ συνδεδραμηκότος ὄχλου συρφετώδους, ταχέως παρέδοσαν αὑτούς· ἐν οἷς ἦσαν καὶ μισθοφόροι διακόσιοι μιγάδες, οὓς ἧκεν ἔχων Ἀμφίδαμος ὁ στρατηγὸς τῶν Ἠλείων. ὁ δὲ Φίλιππος, κυριεύσας ἀποσκευῆς τε πολλῆς καὶ σωμάτων πλειόνων ἢ πεντακισχιλίων, πρὸς δὲ τούτοις τῆς τετράποδος λείας ἀναρίθμητον ἐξελασάμενος πλῆθος, τότε μὲν ἐπανῆλθε πρὸς χάρακα, μετὰ δὲ ταῦτα τῆς δυνάμεως ὑπεργεμούσης αὐτῷ παντοδαπῆς ὠφελείας, βαρὺς ὢν καὶ δύσχρηστος, ἀνεχώρει διὰ ταῦτα, καὶ κατέζευξε πάλιν εἰς τὴν Ὀλυμπίαν.", "st": "4.75"}, {"sp": "N", "t": "Ἀπελλῆς δ’, ὃς ἦν μὲν εἷς τῶν ὑπ’ Ἀντιγόνου καταλειφθέντων ἐπιτρόπων τοῦ παιδός, πλεῖστον δ’ ἐτύγχανε τότε δυνάμενος παρὰ τῷ βασιλεῖ, βουληθεὶς τὸ τῶν Ἀχαιῶν ἔθνος ἀγαγεῖν εἰς παραπλησίαν διάθεσιν τῇ Θετταλῶν, ἐπεβάλετο πρᾶγμα ποιεῖν μοχθηρόν. Θετταλοὶ γὰρ ἐδόκουν μὲν κατὰ νόμους πολιτεύειν καὶ πολὺ διαφέρειν Μακεδόνων, διέφερον δ’ οὐδέν, ἀλλὰ πᾶν ὁμοίως ἔπασχον Μακεδόσι καὶ πᾶν ἐποίουν τὸ προσταττόμενον τοῖς βασιλικοῖς. διὸ καὶ πρὸς ταύτην ἁρμοζόμενος τὴν ὑπόθεσιν ὁ προειρημένος ἐπεβάλετο καταπειράζειν τῶν συστρατευομένων. τὸ μὲν οὖν πρῶτον ἐπέτρεψε τοῖς Μακεδόσιν ἐκβαλεῖν ἐκ τῶν σταθμῶν ἀεὶ τοὺς προκατέχοντας τῶν Ἀχαιῶν καταλύσεις, ὁμοίως δὲ καὶ τὴν λείαν ἀφαιρεῖσθαι· μετὰ δὲ ταῦτα τὰς χεῖρας προσέφερε διὰ τῶν ὑπηρετῶν ἐπὶ ταῖς τυχούσαις αἰτίαις, τοὺς δὲ συναγανακτοῦντας ἢ προσβοηθοῦντας τοῖς μαστιγουμένοις παρὼν αὐτὸς εἰς τὴν ἅλυσιν ἀπῆγε, πεπεισμένος διὰ τοῦ τοιούτου τρόπου τὸ κατὰ βραχὺ λήσειν εἰς συνήθειαν ἀγαγὼν τοῦ μηδένα μηδὲν ἡγεῖσθαι δεινόν, ὅ ποτ’ ἂν πάσχῃ τις ὑπὸ τοῦ βασιλέως, καὶ ταῦτα μικροῖς χρόνοις πρότερον μετ’ Ἀντιγόνου συνεστρατευμένος, καὶ τεθεαμένος τοὺς Ἀχαιοὺς ὅτι παντὸς δεινοῦ λαβεῖν πεῖραν ὑπέμειναν, ἐφ’ ᾧ μὴ ποιεῖν Κλεομένει τὸ προσταττόμενον. οὐ μὴν ἀλλὰ συστραφέντων τινῶν Ἀχαϊκῶν νεανίσκων, καὶ προσελθόντων τοῖς περὶ τὸν Ἄρατον καὶ διασαφούντων τὴν Ἀπελλοῦ βούλησιν, ἧκον ἐπὶ τὸν Φίλιππον οἱ περὶ τὸν Ἄρατον, κρίναντες ἐν ἀρχαῖς περὶ τῶν τοιούτων διίστασθαι καὶ μὴ καταμέλλειν. ἐντυχόντων δ’ αὐτῶν τῷ βασιλεῖ περὶ τούτων, διακούσας ὁ Φίλιππος τὰ γεγονότα, τοὺς μὲν νεανίσκους παρεκάλει θαρρεῖν, ὡς οὐδενὸς αὐτοῖς ἔτι συμβησομένου τοιούτου, τῷ δ’ Ἀπελλῇ παρήγγειλε μηδὲν ἐπιτάττειν τοῖς Ἀχαιοῖς χωρὶς τῆς τοῦ στρατηγοῦ γνώμης.", "st": "4.76"}, {"sp": "N", "t": "Φίλιππος μὲν οὖν κατὰ τὴν ὁμιλίαν τὴν πρὸς τοὺς ἐν τοῖς ὑπαίθροις συνδιατρίβοντας καὶ κατὰ τὴν ἐν τοῖς πολεμικοῖς πρᾶξιν καὶ τόλμαν οὐ μόνον παρὰ τοῖς στρατευομένοις, ἀλλὰ καὶ παρὰ τοῖς λοιποῖς πᾶσι Πελοποννησίοις εὐδοκίμει. βασιλέα γὰρ πλείοσιν ἀφορμαῖς ἐκ φύσεως κεχορηγημένον πρὸς πραγμάτων κατάκτησιν οὐκ εὐμαρὲς εὑρεῖν· καὶ γὰρ ἀγχίνοια καὶ μνήμη καὶ χάρις ἐπῆν αὐτῷ διαφέρουσα, πρὸς δὲ τούτοις ἐπίφασις βασιλικὴ καὶ δύναμις, τὸ δὲ μέγιστον, πρᾶξις καὶ τόλμα πολεμική. καὶ τί δή ποτ’ ἦν τὸ ταῦτα πάντα καταγωνισάμενον καὶ ποιῆσαν ἐκ βασιλέως εὐφυοῦς τύραννον ἄγριον οὐκ εὐχερὲς διὰ βραχέων δηλῶσαι. διὸ καὶ περὶ μὲν τούτων σκέπτεσθαι καὶ διαπορεῖν ἄλλος ἁρμόσει καιρὸς μᾶλλον τοῦ νῦν ἐνεστῶτος· ὁ δὲ Φίλιππος ἐκ τῆς Ὀλυμπίας ἀναζεύξας τὴν ἐπὶ Φαραίαν παρῆν εἰς Τέλφουσαν κἀκεῖθεν εἰς Ἡραίαν. καὶ τὴν μὲν λείαν ἐλαφυροπώλει, τὴν δὲ γέφυραν ἐπεσκεύαζε τὴν κατὰ τὸν Ἀλφειόν, βουλόμενος ταύτῃ ποιήσασθαι τὴν εἰς τὴν Τριφυλίαν εἰσβολήν. κατὰ δὲ τοὺς αὐτοὺς καιροὺς Δωρίμαχος ὁ τῶν Αἰτωλῶν στρατηγός, δεομένων τῶν Ἠλείων σφίσι βοηθεῖν πορθουμένοις, ἑξακοσίους Αἰτωλοὺς καὶ στρατηγὸν Φιλλίδαν αὐτοῖς ἐξέπεμψεν. ὃς παραγενόμενος εἰς τὴν Ἠλείαν, καὶ παραλαβὼν τοὺς μισθοφόρους τῶν Ἠλείων, ὄντας εἰς πεντακοσίους, καὶ πολιτικοὺς χιλίους, ἅμα δὲ τούτοις τοὺς Ταραντίνους, ἧκε βοηθῶν εἰς τὴν Τριφυλίαν, ἣ τῆς μὲν προσηγορίας τέτευχε ταύτης ἀπὸ Τριφύλου τῶν Ἀρκάδος παίδων ἑνός, κεῖται δὲ τῆς Πελοποννήσου παρὰ θάλατταν μεταξὺ τῆς Ἠλείων καὶ Μεσσηνίων χώρας, τέτραπται δ’ εἰς τὸ Λιβυκὸν πέλαγος, ἐσχατεύουσα τῆς Ἀρκαδίας ὡς πρὸς χειμερινὰς δύσεις, ἔχει δ’ ἐν αὑτῇ πόλεις ταύτας, Σαμικόν, Λέπρεον, Ὕπαναν, Τυπανέας, Πύργον, Αἴπιον, Βώλακα, Στυλάγγιον, Φρίξαν. ὧν ὀλίγοις χρόνοις πρότερον ἐπικρατήσαντες Ἠλεῖοι προσελάβοντο καὶ τὴν τῶν Ἀλιφειρέων πόλιν, οὖσαν ἐξ ἀρχῆς ὑπ’ Ἀρκαδίαν [καὶ Μεγαλόπολιν], Λυδιάδου τοῦ Μεγαλοπολίτου κατὰ τὴν τυραννίδα πρός τινας ἰδίας πράξεις ἀλλαγὴν δόντος τοῖς Ἠλείοις.", "st": "4.77"}, {"sp": "N", "t": "πλὴν ὅ γε Φιλλίδας τοὺς μὲν Ἠλείους εἰς Λέπρεον, τοὺς δὲ μισθοφόρους εἰς Ἀλίφειραν ἀποστείλας, αὐτὸς δὲ τοὺς Αἰτωλοὺς ἔχων ἐν Τυπανέαις ἐκαραδόκει τὸ συμβησόμενον. ὁ δὲ βασιλεὺς ἀποθέμενος τὴν ἀποσκευὴν καὶ διαβὰς τῇ γεφύρᾳ τὸν Ἀλφειὸν ποταμόν, ὃς ῥεῖ παρ’ αὐτὴν τὴν τῶν Ἡραιέων πόλιν, ἧκε πρὸς τὴν Ἀλίφειραν, ἣ κεῖται μὲν ἐπὶ λόφου κρημνώδους πανταχόθεν, ἔχοντος πλεῖον ἢ δέκα σταδίων πρόσβασιν, ἔχει δ’ ἄκραν ἐν αὐτῇ τῇ κορυφῇ τοῦ σύμπαντος λόφου καὶ χαλκοῦν Ἀθηνᾶς ἀνδριάντα, κάλλει καὶ μεγέθει διαφέροντα. οὗ τὴν μὲν αἰτίαν, ἀπὸ ποίας προθέσεως ἢ χορηγίας ἔλαβε τὴν ἀρχὴν τῆς κατασκευῆς, ἀμφισβητεῖσθαι συμβαίνει καὶ παρὰ τοῖς ἐγχωρίοις — οὔτε γὰρ πόθεν οὔτε τίς ἀνέθηκεν εὑρίσκεται τρανῶς — τὸ μέντοι γε τῆς τέχνης ἀποτέλεσμα συμφωνεῖται παρὰ πᾶσι, διότι τῶν μεγαλομερεστάτων καὶ τεχνικωτάτων ἔργων ἐστίν, Ὑπατοδώρου καὶ Σωστράτου κατεσκευακότων. οὐ μὴν ἀλλ’ ἐπιγενομένης ἡμέρας αἰθρίου καὶ λαμπρᾶς, διατάξας ὑπὸ τὴν ἑωθινὴν ὁ βασιλεὺς κατὰ πλείους τόπους τούς τε τὰς κλίμακας φέροντας καὶ τὰς τῶν μισθοφόρων ἐφεδρείας πρὸ τούτων, ἐπὶ δὲ τοῖς προειρημένοις τοὺς Μακεδόνας διῃρημένους κατόπιν ἑκάστοις ἐπιστήσας, ἅμα τῷ τὸν ἥλιον ἐπιβάλλειν πᾶσι προσέταξε προσβαίνειν πρὸς τὸν λόφον. ποιούντων δὲ τὸ παραγγελθὲν ἐκθύμως καὶ καταπληκτικῶς τῶν Μακεδόνων, συνέβαινε τοὺς Ἀλιφειρεῖς πρὸς τούτους ὁρμᾶν ἀεὶ καὶ συντρέχειν τοὺς τόπους, οἷς μάλιστα τοὺς Μακεδόνας ἑώρων προσπελάζοντας. κατὰ δὲ τὸν καιρὸν τοῦτον αὐτὸς ὁ βασιλεὺς ἔχων τοὺς ἐπιτηδειοτάτους διά τινων κρημνῶν ἔλαθε πρὸς τὸ τῆς ἄκρας προάστειον ἀναβάς. ἀποδοθέντος δὲ τοῦ συνθήματος, πάντες ἅμα προσερείσαντες τὰς κλίμακας κατεπείραζον τῆς πόλεως. πρῶτος μὲν οὖν ὁ βασιλεὺς κατέσχε τὸ προάστειον τῆς ἄκρας, ἔρημον καταλαβών· τούτου δ’ ἐμπιπραμένου, προϊδόμενοι τὸ μέλλον οἱ τοῖς τείχεσιν ἐπαμύνοντες, καὶ περιδεεῖς γενόμενοι μὴ τῆς ἄκρας προκαταληφθείσης στερηθῶσι καὶ τῆς τελευταίας ἐλπίδος, ὥρμησαν ἀπολιπόντες τὰ τείχη φεύγειν πρὸς τὴν ἀκρόπολιν. οἱ δὲ Μακεδόνες, γενομένου τούτου, παραχρῆμα καὶ τῶν τειχῶν καὶ τῆς πόλεως ἐκυρίευσαν. μετὰ δὲ ταῦτα διαπρεσβευσαμένων τῶν ἐκ τῆς ἄκρας πρὸς τὸν Φίλιππον, δοὺς τὴν ἀσφάλειαν παρέλαβε καὶ ταύτην καθ’ ὁμολογίαν.", "st": "4.78"}, {"sp": "N", "t": "συντελεσθέντων δὲ τούτων, καταπλαγεῖς γεγονότες πάντες οἱ κατὰ τὴν Τριφυλίαν ἐβουλεύοντο περὶ σφῶν αὐτῶν καὶ τῶν ἰδίων πατρίδων. ὁ δὲ Φιλλίδας ἐκλιπὼν τὰς Τυπανέας, προσδιαρπάσας τινὰς τῶν οἰκιῶν, ἀπεχώρησεν εἰς τὸ Λέπρεον· ταῦτα γὰρ ἐπίχειρα τότε τοῖς Αἰτωλῶν ἐγίνετο συμμάχοις, τὸ μὴ μόνον ἐν τοῖς ἀναγκαιοτάτοις καιροῖς ἐγκαταλείπεσθαι προφανῶς, ἀλλὰ καὶ διαρπαγέντας ἢ προδοθέντας τούτοις περιπίπτειν ὑπὸ τῶν συμμάχων, ἃ τοῖς κρατηθεῖσιν ὑπὸ τῶν πολεμίων ὀφείλεται πάσχειν. οἱ δὲ Τυπανεᾶται παρέδοσαν τῷ Φιλίππῳ τὴν πόλιν. τούτοις δὲ τὸ παραπλήσιον ἐποίησαν οἱ τὴν Ὕπαναν κατοικοῦντες. ἅμα δὲ τούτοις Φιαλεῖς, ἀκούοντες τὰ περὶ τὴν Τριφυλίαν καὶ δυσαρεστούμενοι τῇ τῶν Αἰτωλῶν συμμαχίᾳ, κατέλαβον μετὰ τῶν ὅπλων τὸν περὶ τὸ πολεμάρχιον τόπον. οἱ δὲ τῶν Αἰτωλῶν πειραταί, διατρίβοντες ἐν ταύτῃ τῇ πόλει διὰ τὰς ἐκ τῆς Μεσσηνίας ὠφελείας, τὸ μὲν πρῶτον οἷοί τ’ ἦσαν ἐγχειρεῖν καὶ κατατολμᾶν τῶν Φιαλέων, ὁρῶντες δὲ τοὺς πολίτας ὁμοθυμαδὸν ἁθροιζομένους πρὸς τὴν βοήθειαν, ἀπέστησαν τῆς ἐπιβολῆς, σπεισάμενοι δὲ καὶ λαβόντες τὰς αὑτῶν ἀποσκευὰς ἀπῆλθον ἐκ τῆς πόλεως. οἱ δὲ Φιαλεῖς διαπρεσβευσάμενοι πρὸς τὸν Φίλιππον ἐνεχείρισαν σφᾶς αὐτοὺς καὶ τὴν πόλιν.", "st": "4.79"}, {"sp": "N", "t": "ἔτι δὴ τούτων πραττομένων οἱ Λεπρεᾶται καταλαβόμενοι τόπον τινὰ τῆς πόλεως ἠξίουν ἐκχωρεῖν τῆς ἄκρας καὶ τῆς πόλεως τοὺς Ἠλείους καὶ τοὺς Αἰτωλούς, ὁμοίως δὲ καὶ τοὺς παρὰ Λακεδαιμονίων· ἧκε γὰρ καὶ παρ’ ἐκείνων αὐτοῖς βοήθεια. τὸ μὲν οὖν πρῶτον οἱ περὶ τὸν Φιλλίδαν οὐ προσεῖχον, ἀλλ’ ἔμενον, ὡς καταπληξόμενοι τοὺς ἐν τῇ πόλει· τοῦ δὲ βασιλέως εἰς μὲν τὴν Φιγάλειαν Ταυρίωνα μετὰ στρατιωτῶν ἐξαποστείλαντος, αὐτοῦ δὲ προάγοντος εἰς τὸ Λέπρεον καὶ συνεγγίζοντος ἤδη τῇ πόλει, συνέντες οἱ περὶ τὸν Φιλλίδαν ἐταπεινώθησαν, οἱ δὲ Λεπρεᾶται προσεπερρώσθησαν ταῖς ὁρμαῖς. καλὸν γὰρ δὴ τοῦτο Λεπρεάταις ἔργον πέπρακται, τὸ χιλίων μὲν ἔνδον ὄντων Ἠλείων, χιλίων δὲ σὺν τοῖς πειραταῖς Αἰτωλῶν, πεντακοσίων δὲ μισθοφόρων, διακοσίων δὲ Λακεδαιμονίων, πρὸς δὲ τούτοις τῆς ἄκρας κατεχομένης, ὅμως ἀντιποιήσασθαι τῆς ἑαυτῶν πατρίδος καὶ μὴ προέσθαι τὰς σφετέρας ἐλπίδας. ὁ δὲ Φιλλίδας, ὁρῶν τοὺς Λεπρεάτας ἀνδρωδῶς ὑφισταμένους καὶ τοὺς Μακεδόνας ἐγγίζοντας, ἐξεχώρησε τῆς πόλεως ἅμα τοῖς Ἠλείοις καὶ τοῖς παρὰ τῶν Λακεδαιμονίων. οἱ μὲν οὖν παρὰ τῶν Σπαρτιατῶν Κρῆτες διὰ τῆς Μεσσηνίας εἰς τὴν οἰκείαν ἐπανῆλθον, οἱ δὲ περὶ τὸν Φιλλίδαν ἐποιοῦντο τὴν ἀπόλυσιν ὡς ἐπὶ τὸ Σαμικόν. τὸ δὲ τῶν Λεπρεατῶν πλῆθος, ἐγκρατὲς γεγονὸς τῆς πατρίδος, ἐξαπέστελλε πρεσβευτάς, ἐγχειρίζον τῷ Φιλίππῳ τὴν πόλιν. ὁ δὲ βασιλεὺς ἀκούσας τὰ γεγονότα, τὴν μὲν λοιπὴν δύναμιν εἰς τὸ Λέπρεον ἀπέστειλε, τοὺς δὲ πελταστὰς καὶ τοὺς εὐζώνους ἀναλαβὼν ἡγεῖτο, συνάψαι σπεύδων τοῖς περὶ τὸν Φιλλίδαν. καταλαβὼν δὲ τῆς μὲν ἀποσκευῆς ἐγκρατὴς ἐγένετο πάσης, οἱ δὲ περὶ τὸν Φιλλίδαν κατετάχησαν εἰς τὸ Σαμικὸν παραπεσόντες. προσστρατοπεδεύσας δὲ τῷ χωρίῳ, καὶ τὴν λοιπὴν ἐπισπασάμενος ἐκ τοῦ Λεπρέου δύναμιν, ἔμφασιν ἐποίει τοῖς ἔνδον ὡς πολιορκήσων τὸ χωρίον. οἱ δ’ Αἰτωλοὶ μετὰ τῶν Ἠλείων οὐδὲν ἔχοντες ἕτοιμον πρὸς πολιορκίαν πλὴν χερῶν, καταπλαγέντες τὴν περίστασιν ἐλάλουν περὶ ἀσφαλείας πρὸς τὸν Φίλιππον. λαβόντες δὲ συγχώρημα μετὰ τῶν ὅπλων ποιήσασθαι τὴν ἀπόλυσιν, οὗτοι μὲν ὥρμησαν εἰς τὴν Ἠλείαν· ὁ δὲ βασιλεὺς τοῦ μὲν Σαμικοῦ παραυτίκα κύριος ἐγένετο, μετὰ δὲ ταῦτα, παραγενομένων πρὸς αὐτὸν καὶ τῶν ἄλλων μεθ’ ἱκετηρίας, παρέλαβε Φρίξαν, Στυλάγγιον, Αἴπιον, Βώλακα, Πύργον, Ἐπιτάλιον. ταῦτα δὲ διαπραξάμενος ἐπανῆλθε πάλιν εἰς τὸ Λέπρεον, πᾶσαν ὑφ’ ἑαυτὸν πεποιημένος τὴν Τριφυλίαν ἐν ἡμέραις ἕξ. παρακαλέσας δὲ τοὺς Λεπρεάτας τὰ πρέποντα τῷ καιρῷ, καὶ φυλακὴν εἰσαγαγὼν εἰς τὴν ἄκραν, ἀνέζευξε μετὰ τῆς δυνάμεως ἐφ’ Ἡραίας, ἀπολιπὼν ἐπιμελητὴν τῆς Τριφυλίας Λάδικον τὸν Ἀκαρνᾶνα. παραγενόμενος δ’ εἰς τὴν προειρημένην πόλιν τὴν μὲν λείαν διένειμε πᾶσαν, τὴν δ’ ἀποσκευὴν ἀναλαβὼν ἐκ τῆς Ἡραίας ἦλθε μέσου χειμῶνος εἰς Μεγάλην πόλιν.", "st": "4.80"}, {"sp": "N", "t": "κατὰ δὲ τοὺς αὐτοὺς καιροὺς Φίλιππος ἔπραττε τὰ κατὰ τὴν Τριφυλίαν, καὶ Χείλων ὁ Λακεδαιμόνιος, ὑπολαμβάνων αὑτῷ καθήκειν κατὰ γένος τὴν βασιλείαν, καὶ βαρέως φέρων τὴν γεγενημένην ὑπεροψίαν περὶ αὐτὸν ἐκ τῶν ἐφόρων ἐν τῇ κατὰ τὸν Λυκοῦργον κρίσει περὶ τῆς βασιλείας, κινεῖν ἐπεβάλετο τὰ καθεστῶτα. νομίσας δ’, εἰ τὴν ὁδὸν τὴν αὐτὴν ἔλθοι Κλεομένει καὶ τοῖς πολλοῖς ὑποδείξαι τὴν ἐλπίδα τῆς κληρουχίας καὶ τῶν ἀναδασμῶν, ταχέως ἐπακολουθήσειν αὐτῷ τὸ πλῆθος, ὥρμησε πρὸς τὴν πρᾶξιν. συμφρονήσας δὲ περὶ τούτων πρὸς τοὺς φίλους, καὶ λαβὼν κοινωνοὺς τῆς τόλμης εἰς διακοσίους τὸ πλῆθος, ἐγίνετο πρὸς τῷ συντελεῖν τὴν ἐπίνοιαν. θεωρῶν δὲ μέγιστον ἐμπόδιον ὑπάρχον αὑτῷ πρὸς τὴν ἐπιβολὴν τὸν Λυκοῦργον καὶ τοὺς ἐφόρους τοὺς περιθέντας ἐκείνῳ τὴν βασιλείαν, ὥρμησε πρῶτον ἐπὶ τούτους. τοὺς μὲν οὖν ἐφόρους δειπνοῦντας καταλαβών, πάντας αὐτοῦ κατέσφαξε, τῆς τύχης τὴν ἁρμόζουσαν αὐτοῖς ἐπιθείσης δίκην· καὶ γὰρ ὑφ’ οὗ καὶ περὶ οὗ ταῦτ’ ἔπαθον, δικαίως αὐτοὺς ἄν τις φήσειε πεπονθέναι. ὁ δὲ Χείλων, τὰ κατὰ τούτους συντελεσάμενος, παρῆν ἐπὶ τὴν οἰκίαν τοῦ Λυκούργου καὶ κατέλαβε μὲν ἔνδον, οὐ μὴν ἐδυνήθη γ’ ἐγκρατὴς αὐτοῦ γενέσθαι. διὰ γάρ τινων κατοικούντων ἐκ γειτόνων ἐκκλαπεὶς καὶ διαδρὰς ἔλαθεν αὐτόν. οὗτος μὲν οὖν ἀνεχώρησε ταῖς ἀνοδίαις εἰς τὴν ἐν τῇ Τριπόλει προσαγορευομένην Πελλήνην. ὁ δὲ Χείλων ἀπεσφαλμένος τοῦ κυριωτάτου πρὸς τὴν ἐπιβολὴν ἀθύμως διέκειτο, πράττειν δ’ ὅμως ἠναγκάζετο τὸ συνεχές. διόπερ εἰς τὴν ἀγορὰν εἰσβαλὼν τοῖς μὲν ἐχθροῖς προσέφερε τὰς χεῖρας, τοὺς δ’ οἰκείους καὶ φίλους παρεκάλει, τοῖς δὲ λοιποῖς ὑπεδείκνυε τὰς ἄρτι ῥηθείσας ἐλπίδας. οὐδενὸς δὲ προσέχοντος αὐτῷ, τἀναντία δὲ συστρεφομένων ἐπ’ αὐτὸν τῶν ἀνθρώπων, συννοήσας τὸ γινόμενον, ἀπεχώρει λαθραίως, καὶ διελθὼν τὴν χώραν ἧκε μόνος εἰς τὴν Ἀχαΐαν ἐκπεπτωκώς. οἱ δὲ Λακεδαιμόνιοι, δείσαντες τὴν τοῦ Φιλίππου παρουσίαν, τἀπὸ τῆς χώρας ἀπεσκευάζοντο καὶ τὸ τῶν Μεγαλοπολιτῶν Ἀθήναιον κατασκάψαντες ἐξέλιπον. Λακεδαιμόνιοι μὲν οὖν, ἀπὸ τῆς Λυκούργου νομοθεσίας καλλίστῃ χρησάμενοι πολιτείᾳ καὶ μεγίστην ἔχοντες δύναμιν ἕως τῆς ἐν Λεύκτροις μάχης, αὖτις ἐπὶ τἀναντία τραπείσης αὐτοῖς τῆς τύχης, καὶ τοὔμπαλιν ἐπὶ τὸ χεῖρον ἀεὶ καὶ μᾶλλον τῆς πολιτείας αὐτῶν προβαινούσης, τέλος πλείστων μὲν πόνων καὶ στάσεων ἐμφυλίων πεῖραν εἶχον, πλείστοις δ’ ἐπάλαισαν ἀναδασμοῖς καὶ φυγαῖς, πικροτάτης δὲ δουλείας πεῖραν ἔλαβον ἕως τῆς Νάβιδος τυραννίδος, οἱ τὸ πρὶν οὐδὲ τοὔνομα δυνηθέντες ἀνασχέσθαι ῥᾳδίως αὐτῆς. τὰ μὲν οὖν πάλαι καὶ τὰ πλείω περὶ Λακεδαιμονίων εἰς ἑκάτερον μέρος ὑπὸ πολλῶν εἴρηται τάδε. ἐναργέστατα δ’ ἐστὶν ἀφ’ οὗ Κλεομένης ὁλοσχερῶς κατέλυσε τὸ πάτριον πολίτευμα. νῦν δ’ ὑφ’ ἡμῶν ῥηθήσεται κατὰ τοὺς ἁρμόζοντας ἀεὶ καιρούς.", "st": "4.81"}, {"sp": "N", "t": "ὁ δὲ Φίλιππος ἀναζεύξας ἐκ τῆς Μεγάλης πόλεως καὶ πορευθεὶς διὰ τῆς Τεγέας παρῆν εἰς Ἄργος, κἀκεῖ τὸ λοιπὸν μέρος τοῦ χειμῶνος διέτριβε, κατά τε τὴν λοιπὴν ἀναστροφὴν καὶ κατὰ τὰς πράξεις τεθαυμασμένος ὑπὲρ τὴν ἡλικίαν ἐν ταῖς προειρημέναις στρατείαις. ὁ δ’ Ἀπελλῆς οὐδ’ ὣς ἔληγε τῆς ἐπιβολῆς, ἀλλ’ οἷός τ’ ἦν ἄγειν ὑπὸ τὸν ζυγὸν τῷ κατὰ βραχὺ τοὺς Ἀχαιούς. ὁρῶν δὲ τῇ τοιαύτῃ προθέσει τοὺς περὶ τὸν Ἄρατον ἐμποδὼν ἱσταμένους, καὶ τὸν Φίλιππον αὐτοῖς προσέχοντα, καὶ μᾶλλον τῷ πρεσβυτέρῳ διά τε τὴν πρὸς Ἀντίγονον σύστασιν καὶ διὰ τὸ πλεῖστον ἐν τοῖς Ἀχαιοῖς ἰσχύειν, καὶ μάλιστα διὰ τὴν ἐπιδεξιότητα καὶ νουνέχειαν τἀνδρός, περὶ τούτους ἐπεβάλετο γίνεσθαι καὶ κακοπραγμονεῖν τοιῷδέ τινι τρόπῳ. ἐξετάζων τοὺς ἀντιπολιτευομένους τοῖς περὶ τὸν Ἄρατον, τίνες εἰσίν, ἑκάστους ἐκ τῶν πόλεων ἐπεσπάσατο, καὶ λαμβάνων εἰς τὰς χεῖρας ἐψυχαγώγει καὶ παρεκάλει πρὸς τὴν ἑαυτοῦ φιλίαν. συνίστανε δὲ καὶ τῷ Φιλίππῳ, προσεπιδεικνύων αὐτῷ παρ’ ἕκαστον ὡς ἐὰν μὲν Ἀράτῳ προσέχῃ, χρήσεται τοῖς Ἀχαιοῖς κατὰ τὴν ἔγγραπτον συμμαχίαν, ἐὰν δ’ αὐτῷ πείθηται καὶ τοιούτους προσλαμβάνῃ φίλους, χρήσεται πᾶσι Πελοποννησίοις κατὰ τὴν αὑτοῦ βούλησιν. περί τε τῶν ἀρχαιρεσίων εὐθὺς ἐσπούδαζε, βουλόμενος τούτων τινὶ περιποιῆσαι τὴν στρατηγίαν, τοὺς δὲ περὶ τὸν Ἄρατον ἐκβαλεῖν ἐκ τῆς ὑποθέσεως. δι’ ἃ δὴ καὶ πείθει Φίλιππον παραγενέσθαι πρὸς τὰς τῶν Ἀχαιῶν ἀρχαιρεσίας εἰς Αἴγιον, ὡς εἰς τὴν Ἠλείαν ἅμα ποιούμενον τὴν πορείαν. πεισθέντος δ’ αὐτῷ τοῦ βασιλέως, παρὼν αὐτὸς ἐπὶ τοῦ καιροῦ, καὶ τοὺς μὲν παρακαλῶν, οἷς δ’ ἀνατεινόμενος, μόλις μὲν ἤνυσε, κατεκράτησε δ’ οὖν ὅμως τοῦ γενέσθαι στρατηγὸν Ἐπήρατον Φαραιέα, τὸν δὲ Τιμόξενον ἐκπεσεῖν, τὸν ὑπὸ τῶν περὶ τὸν Ἄρατον εἰσαγόμενον.", "st": "4.82"}, {"sp": "N", "t": "μετὰ δὲ ταῦτα ἀναζεύξας ὁ βασιλεύς, καὶ ποιησάμενος τὴν πορείαν διὰ Πατρῶν καὶ Δύμης, ἧκε πρὸς τὸ φρούριον, ὃ καλεῖται μὲν Τεῖχος, πρόκειται δὲ τῆς Δυμαίων χώρας· κατέσχον δ’ αὐτὸ μικροῖς ἔμπροσθεν χρόνοις, καθάπερ ἀνώτερον εἶπον, οἱ περὶ τὸν Εὐριπίδαν. σπεύδων δὴ τοῦτο κατὰ πάντα τρόπον ἀνακομίσασθαι τοῖς Δυμαίοις, προσεστρατοπέδευσε μετὰ πάσης δυνάμεως. καταπλαγέντες δ’ οἱ φυλάττοντες τῶν Ἠλείων παρέδοσαν τὸ φρούριον τῷ Φιλίππῳ, χωρίον οὐ μέγα μέν, ἠσφαλισμένον δὲ διαφερόντως· τὴν μὲν γὰρ περίμετρον εἶχεν οὐ πλείω τριῶν ἡμισταδίων, τὸ δ’ ὕψος τοῦ τείχους οὐδαμῇ τριάκοντα πήχεων ἔλαττον. παραδοὺς δὲ τοῦτο τοῖς Δυμαίοις ἐπῄει πορθῶν τὴν τῶν Ἠλείων χώραν· φθείρας δὲ ταύτην, καὶ πολλὴν περιβαλόμενος λείαν, ἐπανῆλθε μετὰ τῆς δυνάμεως εἰς τὴν Δύμην.", "st": "4.83"}, {"sp": "N", "t": "ὁ δ’ Ἀπελλῆς, δοκῶν ἠνυκέναι τι τῆς προθέσεως τῷ δι’ αὐτοῦ καθεστάσθαι τὸν τῶν Ἀχαιῶν στρατηγόν, αὖθις ἐνεχείρει τοῖς περὶ τὸν Ἄρατον, βουλόμενος εἰς τέλος ἀποσπάσαι τὸν Φίλιππον ἀπὸ τῆς πρὸς αὐτοὺς φιλίας. ἐπεβάλετο δὲ τὴν διαβολὴν πλάττειν διὰ τοιαύτης τινὸς ἐπινοίας. Ἀμφίδαμος ὁ τῶν Ἠλείων στρατηγός, ἐν ταῖς Θαλάμαις ἁλοὺς ἅμα τοῖς συμπεφευγόσι, καθάπερ ἀνώτερον ἡμῖν ἐρρήθη περὶ τούτων, ὡς ἧκε μετὰ τῶν ἄλλων αἰχμαλώτων ἀγόμενος εἰς Ὀλυμπίαν, ἔσπευσε διά τινων εἰς λόγους ἐλθεῖν τῷ βασιλεῖ. τυχὼν δὲ τούτου διελέγετο, φάσκων εἶναι δυνατὸς ἐπαγαγέσθαι τοὺς Ἠλείους εἰς τὴν πρὸς αὐτὸν φιλίαν καὶ συμμαχίαν. ὁ δὲ Φίλιππος πεισθεὶς ἐξαπέστειλε τὸν Ἀμφίδαμον χωρὶς λύτρων, κελεύσας ἐπαγγέλλεσθαι τοῖς Ἠλείοις, ἐὰν ἕλωνται τὴν πρὸς αὐτὸν φιλίαν, ὅτι τὰ μὲν αἰχμάλωτα πάντα χωρὶς λύτρων ἀποδώσει, τῇ δὲ χώρᾳ τὴν ἀσφάλειαν αὐτὸς ἀπὸ πάντων τῶν ἐκτὸς παρασκευάσει, πρὸς δὲ τούτοις αὐτοὺς ἐλευθέρους, ἀφρουρήτους, ἀφορολογήτους, χρωμένους τοῖς ἰδίοις πολιτεύμασι, διατηρήσει. οἱ μὲν οὖν Ἠλεῖοι διακούσαντες τούτων οὐδὲν προσέσχον, καίπερ ἐπισπαστικῶν καὶ μεγάλων εἶναι δοκούντων τῶν προτεινομένων· ὁ δ’ Ἀπελλῆς, ἐκ τούτου τοῦ πράγματος πλάσας τὴν διαβολήν, προσήνεγκε τῷ Φιλίππῳ, φάσκων τοὺς περὶ τὸν Ἄρατον οὐκ εἰλικρινῆ τὴν φιλίαν ἄγειν πρὸς Μακεδόνας οὐδ’ ἀληθινῶς εὐνοεῖν αὐτῷ· καὶ γὰρ νῦν τῆς Ἠλείων ἀλλοτριότητος τούτους αἰτίους γεγονέναι. καθ’ ὃν γὰρ καιρὸν Ἀμφίδαμον ἐξ Ὀλυμπίας εἰς Ἦλιν ἀπέστειλε, τούτους ἔφη κατ’ ἰδίαν λαβόντας ἐπιτρῖψαι τὸν ἄνθρωπον καὶ λέγειν ὅτι κατ’ οὐδένα τρόπον συμφέρει τοῖς Πελοποννησίοις τὸ γενέσθαι Φίλιππον Ἠλείων κύριον, καὶ διὰ ταύτην τὴν αἰτίαν πάνθ’ ὑπεριδόντας τὰ προτεινόμενα τοὺς Ἠλείους διατηρεῖν μὲν τὴν πρὸς Αἰτωλοὺς φιλίαν, ὑπομένειν δὲ τὸν πρὸς Μακεδόνας πόλεμον.", "st": "4.84"}, {"sp": "N", "t": "τὸ μὲν οὖν πρῶτον Φίλιππος δεξάμενος τοὺς λόγους καλεῖν ἐκέλευε τοὺς περὶ τὸν Ἄρατον καὶ λέγειν ἐναντίον ἐκείνων ταῦτα τὸν Ἀπελλῆν. τῶν δὲ παραγενομένων, ἔλεγε τὰ προειρημένα τολμηρῶς καὶ καταπληκτικῶς ὁ Ἀπελλῆς, καί τι προσεπεῖπε τοιοῦτον ἔτι σιωπῶντος τοῦ βασιλέως· \" ἐπείπερ οὕτως ἀχαρίστους ὑμᾶς ὁ βασιλεύς, Ἄρατε, καὶ λίαν ἀγνώμονας εὑρίσκει, κρίνει συναγαγὼν τοὺς Ἀχαιοὺς καὶ περὶ τούτων ἀπολογισμοὺς ποιησάμενος ἀπαλλάττεσθαι πάλιν εἰς Μακεδονίαν. \" ὁ δὲ πρεσβύτερος Ἄρατος ὑπολαβὼν καθόλου μὲν ἠξίου τὸν Φίλιππον μηδενὶ τῶν λεγομένων ὀξέως μηδ’ ἀκρίτως μηδέποτε πιστεύειν, ὅταν δὲ κατά τινος τῶν φίλων καὶ συμμάχων προσπέσῃ τις αὐτῷ λόγος, τὸν ἀκριβέστερον ἔλεγχον ποιεῖσθαι πρὶν ἢ δέξασθαι τὴν διαβολήν· καὶ γὰρ βασιλικὸν εἶναι τὸ τοιοῦτο καὶ πρὸς πᾶν συμφέρον. διὸ καὶ νῦν ἠξίου περὶ τῶν ὑπ’ Ἀπελλοῦ λεγομένων καλεῖν τοὺς ἀκηκοότας, ἄγειν εἰς τὸ μέσον τὸν εἰρηκότα πρὸς αὐτόν, μηδὲν παραλιπεῖν τῶν δυνατῶν εἰς τὸ γνῶναι τὴν ἀλήθειαν, πρὶν ἢ πρὸς τοὺς Ἀχαιοὺς ἀνακαλύπτειν τι τούτων.", "st": "4.85"}, {"sp": "N", "t": "τοῦ δὲ βασιλέως εὐαρεστήσαντος τοῖς λεγομένοις, καὶ φήσαντος οὐκ ὀλιγωρήσειν, ἀλλ’ ἐξετάσειν, τότε μὲν διελύθησαν. ἐν δὲ ταῖς ἑξῆς ἡμέραις ὁ μὲν Ἀπελλῆς οὐδεμίαν ἀπόδειξιν προσῆγε τοῖς εἰρημένοις· τοῖς δὲ περὶ τὸν Ἄρατον ἐγένετό τι συγκύρημα τοιοῦτον. οἱ γὰρ Ἠλεῖοι, καθ’ ὃν καιρὸν ὁ Φίλιππος αὐτῶν ἐπόρθει τὴν χώραν, ὑποπτεύσαντες τὸν Ἀμφίδαμον ἐπεβάλοντο συλλαβεῖν καὶ δήσαντες εἰς τὴν Αἰτωλίαν ἐκπέμπειν. ὁ δὲ προαισθόμενος αὐτῶν τὴν ἐπίνοιαν ἀπεχώρησε τὰς μὲν ἀρχὰς εἰς Ὀλυμπίαν, μετὰ δὲ ταῦτα πυνθανόμενος τὸν Φίλιππον ἐν τῇ Δύμῃ περὶ τὴν τῶν λαφύρων οἰκονομίαν διατρίβειν, ἔσπευσε πρὸς τοῦτον διαπεσεῖν. ὅθεν οἱ περὶ τὸν Ἄρατον, ἀκούσαντες τὸν Ἀμφίδαμον ἐκ τῆς Ἤλιδος ἐκπεπτωκότα παρεῖναι, γενόμενοι περιχαρεῖς διὰ τὸ μηδὲν αὑτοῖς συνειδέναι, προσελθόντες ᾤοντο δεῖν τὸν βασιλέα καλεῖν τὸν Ἀμφίδαμον· καὶ γὰρ εἰδέναι περὶ τῶν κατηγορουμένων ἐκεῖνον βέλτιστα πρὸς ὃν ἐρρήθη, καὶ δηλώσειν τὴν ἀλήθειαν, πεφευγότα μὲν ἐξ οἴκου διὰ τὸν Φίλιππον, τὰς δ’ ἐλπίδας ἔχοντα τῆς σωτηρίας κατὰ τὸ παρὸν ἐν ἐκείνῳ. πεισθεὶς δὲ τοῖς λεγομένοις ὁ βασιλεύς, καὶ μεταπεμψάμενος τὸν Ἀμφίδαμον, εὗρε τὴν διαβολὴν οὖσαν ψευδῆ. διὸ καὶ τὸν μὲν Ἄρατον ἀπὸ ταύτης τῆς ἡμέρας ἀεὶ καὶ μᾶλλον ἀπεδέχετο καὶ κατηξίου, πρὸς δὲ τὸν Ἀπελλῆν λοξότερον εἶχε· τῇ γε μὴν ὁλοσχερεῖ προκατεχόμενος ἀποδοχῇ πολλὰ παρορᾶν ἠναγκάζετο τῶν ὑπ’ αὐτοῦ γινομένων.", "st": "4.86"}, {"sp": "N", "t": "ὁ δ’ Ἀπελλῆς οὐδαμῶς ἀφίστατο τῆς προθέσεως, ἀλλ’ ἅμα μὲν τὸν Ταυρίωνα τὸν ἐπὶ τῶν ἐν Πελοποννήσῳ τεταγμένον διέβαλλεν, οὐ ψέγων, ἀλλ’ ἐπαινῶν καὶ φάσκων ἐπιτήδειον αὐτὸν εἶναι μετὰ τοῦ βασιλέως ἐν τοῖς ὑπαίθροις συνδιατρίβειν, βουλόμενος ἕτερον ἐπισταθῆναι δι’ αὑτοῦ τοῖς ἐν Πελοποννήσῳ πράγμασι. καινὸς γὰρ δή τις οὗτος εὕρηται τρόπος διαβολῆς τὸ μὴ ψέγοντας, ἀλλ’ ἐπαινοῦντας λυμαίνεσθαι τοὺς πέλας· εὕρηται δὲ μάλιστα καὶ πρῶτον τοιαύτη κακεντρέχεια καὶ βασκανία καὶ δόλος ἐκ τῶν περὶ τὰς αὐλὰς διατριβόντων καὶ τῆς τούτων πρὸς ἀλλήλους ζηλοτυπίας καὶ πλεονεξίας. ὁμοίως δὲ καὶ τὸν ἐπὶ τῆς θεραπείας τεταγμένον Ἀλέξανδρον, ὅτε λάβοι καιρόν, διέδακνε, βουλόμενος καὶ τὴν περὶ τὸ σῶμα φυλακὴν τοῦ βασιλέως δι’ αὑτοῦ γενέσθαι καὶ καθόλου κινῆσαι τὴν ὑπ’ Ἀντιγόνου καταλειφθεῖσαν διάταξιν. Ἀντίγονος γὰρ καλῶς μὲν ζῶν προέστη τῆς τε βασιλείας καὶ τοῦ παιδὸς αὑτοῦ, καλῶς δὲ τὸν βίον μεταλλάττων προενοήθη πρὸς τὸ μέλλον περὶ πάντων τῶν πραγμάτων. ἀπολιπὼν γὰρ διαθήκην ἔγραφε Μακεδόσιν ὑπὲρ τῶν διῳκημένων· ὁμοίως δὲ καὶ περὶ τοῦ μέλλοντος διέταξε πῶς καὶ διὰ τίνων ἕκαστα δεήσει χειρίζεσθαι, βουλόμενος μηδεμίαν ἀφορμὴν καταλιπεῖν τοῖς περὶ τὴν αὐλὴν πρὸς ἀλλήλους φιλοτιμίας καὶ στάσεως. ἐν οἷς τῶν τότε συστρατευομένων αὐτὸς μὲν Ἀπελλῆς ἐν τοῖς ἐπιτρόποις ἀπελέλειπτο, Λεόντιος δ’ ἐπὶ τῶν πελταστῶν, Μεγαλέας δ’ ἐπὶ τοῦ γραμματείου, Ταυρίων δ’ ἐπὶ τῶν κατὰ Πελοπόννησον, Ἀλέξανδρος δ’ ἐπὶ τῆς θεραπείας. τὸν μὲν οὖν Λεόντιον καὶ Μεγαλέαν ὑφ’ αὑτὸν εἶχεν ὁλοσχερῶς, τὸν δ’ Ἀλέξανδρον καὶ Ταυρίωνα μεταστησάμενος ἀπὸ τῆς χρείας ἔσπευδε καὶ ταῦτα καὶ τἄλλα πάντα δι’ αὑτοῦ καὶ διὰ τῶν ἰδίων φίλων χειρίζειν. ὃ δὴ καὶ ῥᾳδίως ἂν ἐπετέλεσε μὴ παρασκευάσας ἀνταγωνιστὴν Ἄρατον αὑτῷ· νῦν δὲ ταχέως πεῖραν ἔλαβε τῆς σφετέρας ἀφροσύνης καὶ πλεονεξίας. ὃ γὰρ αὐτὸς ἐπεβάλετο πρᾶξαι κατὰ τῶν πέλας, τοῦτ’ ἔπαθε καὶ λίαν ἐν πάνυ βραχεῖ χρόνῳ. πῶς δὲ καὶ τίνι τρόπῳ τοῦτο συνέβη γενέσθαι κατὰ μὲν τὸ παρὸν ὑπερθησόμεθα καὶ καταστρέψομεν τὴν βύβλον ταύτην, ἐν δὲ τοῖς ἑξῆς πειρασόμεθα σαφῶς ὑπὲρ ἑκάστων ἐξαγγέλλειν. Φίλιππος δὲ τὰ προειρημένα διαταξάμενος ἐπανῆλθεν εἰς Ἄργος, κἀνταῦθα τὴν παραχειμασίαν ἐποίει μετὰ τῶν φίλων, τὰς δὲ δυνάμεις ἀπέλυσεν εἰς Μακεδονίαν.", "st": "4.87"}], []);})();
